; Reconstructed from assets/Elite - 128k.tap; no original binary is included at build time.
; TAP SHA256: d9013872555f448308e0b8a69b624600335384cd38911165bde74a9d11de84d6
; Zero-based TAP data block 5; payload SHA256: 55de3c7f56b1d54434c6b1a7b360174a1f56252e839abdce5463526128e1ff07
; Generated by tools/bootstrap_sources.py. Normal builds assemble this file directly.

; Z80 source of the game image $6048..$FFA8 (TAP block 5, entry $7000).
; Generated from control-flow analysis, runtime evidence and the annotation
; database in tools/annotations/; see docs/DISASSEMBLY.md for conventions.
; Each instruction comment starts with its original address and bytes.
; VERIFIED marks proved meanings; INFERRED marks hypotheses still to be checked.
; Remaining DEFB bytes marked UNCLASSIFIED have no proved code or data role yet.
; Every original byte is present. This is not yet a fully documented disassembly.
; Fixed runtime/screen destinations and character format, verified from original instructions.
    INCLUDE "options.asm"
defc FontRuntime = $5D70
defc CockpitAttributesRuntime = $5B00
defc ScreenCockpitBitmap = $5000
defc ScreenCockpitAttributes = $5A00
defc FontFirstCode = $0020
defc FontGlyphHeight = $0008
; Source RAM is reused after the initial font/colour copies.
defc ViewBitmapBuffer = FontBitmap
defc ViewBitmapBufferSecondHalf = CockpitBitmap

; Named constants: structure offsets, fixed workspaces and format values.
defc InstanceSize = $27                         ; bytes per object instance slot
defc InstanceSlotCount = $08                    ; slot 0 station, 1..6 allocatable, 7 missile/title
defc InstanceX = $00                            ; x: 24-bit sign-magnitude, sign = bit 7 of +2
defc InstanceY = $03                            ; y: same format
defc InstanceZ = $06                            ; z: same format; depth in the front view
defc InstanceAxisZ = $09                        ; local z (nose) axis: 3 words, $7FFF = 1.0
defc InstanceAxisY = $0F                        ; local y (roof) axis, same format
defc InstanceAxisX = $15                        ; local x (side) axis; renderer rebuilds Y x Z
defc InstanceSpeed = $1B                        ; speed; starts at half the blueprint maximum
defc InstanceAcceleration = $1C                 ; signed speed change per move (AI command)
defc InstanceExplosionDisc = $1C                ; destroyed: disc x, y, flags, radius (+$1C..+$1F)
defc InstanceRoll = $1D                         ; roll: bits 0..3 steps left, 6 sign, 7 endless
defc InstancePitch = $1E                        ; pitch steps, same format as InstanceRoll
defc InstanceFlags = $20                        ; bits 0..2 payload, 3 fired, 4/5 explosion, 6 AI, 7 pod
defc InstanceBehaviour = $21                    ; blueprint +$12 AND $6F; bit 2 hostile
defc InstanceEnergy = $22                       ; energy; zero marks a free slot
defc InstanceAiState = $25                      ; ship: bit 0 ECM, bits 1..6 courage counter (-14 per hit), 7 fleeing; missile: target
defc InstanceRoleFlags = $26                    ; bit 0 missile, 1 scoopable, 2 station, 3 passive...
defc InstanceBlueprint = $23                    ; pointer to the 23-byte blueprint header
defc InstanceTemplateSize = $1F                 ; bytes +$00..+$1E copied from ShipInstanceTemplate
defc BlueprintHeaderSize = $17                  ; bytes in a blueprint header
defc BlueprintCargo = $00                       ; scooped commodity - 1 (high), canister (low)
defc BlueprintRadius = $01                      ; near limit, target size and collision box
defc BlueprintLaserChance = $02                 ; AI fire chance in 256, halved below 256 kills
defc BlueprintVertexCount = $03                 ; vertex count
defc BlueprintEdgeCount = $04                   ; edge count
defc BlueprintFaceCount = $05                   ; face count (0: no face table)
defc BlueprintMaximumSpeed = $06                ; maximum speed
defc BlueprintEnergy = $07                      ; energy: initial value and regeneration limit
defc BlueprintBounty = $08                      ; bounty word in tenths of a credit
defc BlueprintPayload = $0A                     ; bits 0..2 payload count, bits 4..7 launch type
defc BlueprintDotDistance = $0B                 ; wireframe while the depth high byte is lower
defc BlueprintVertexTable = $0C                 ; vertex table offset from the header
defc BlueprintEdgeTable = $0E                   ; edge table offset from the header
defc BlueprintFaceTable = $10                   ; face table offset from the header (0: none)
defc BlueprintBehaviour = $12                   ; behaviour flags; AND $6F gives instance +$21
defc BlueprintNormalShift = $13                 ; normal scale shift n: normals x 2/2^n
defc BlueprintGunVertex = $14                   ; vertex where AI laser beams start
defc BlueprintCombatScore = $15                 ; award word; half is added to the combat score
defc InterruptStackTop = $FFBF                  ; interrupt handler stack top above the game image; uses $FFAB..$FFBE
defc RomPixelAddressTail = $22B0                ; ROM PIXEL-ADD after its range check: A = row, C = x
defc ScannerBackupBuffer = $5B00                ; 624-byte saved scanner background (also the runtime cockpit attribute buffer when the cockpit is saved)
defc ScannerBackupScreen = $5049                ; screen address of the scanner background area: character rows 2..7, columns 9..21 of the bottom third
defc RomLdBytesAfterSetup = $0562               ; ROM LD-BYTES after its border set-up and SA/LD-RET push
defc RomSaBytesAfterSetup = $04C6               ; ROM SA-BYTES after its SA/LD-RET push
defc RomPixelAddRow = $22B1                     ; ROM PIXEL-ADD entry after the y inversion: A = B = row from the top, C = column -> HL screen address, A = C AND 7
org GameLoadAddress
GameImage:

; KNOWN DATA: VERIFIED DATA: initial mutable game/object state; runtime access tracing records reads and writes here, never instruction fetches.
    INCLUDE "data/initial-runtime-state.asm"


; KNOWN DATA: VERIFIED DATA: structured ship geometry/blueprint records followed by in-image dispatch pointers; read at runtime and never executed.
    INCLUDE "data/ship-blueprints-and-tables.asm"


; VERIFIED: BASIC RANDOMIZE USR 28672 enters here.
Entry:
IF SHIP_ADDER
    JP AdderStartup
ELSE
    JP Startup                                 ; $7000: C3 6B 71
ENDIF

; ============================================================================
; Game state variables
; Word-wrap line buffer, flight controls, cockpit gauge values, sun and planet
; positions and flight-state flags.
; ============================================================================

; VERIFIED: Constant space ($20) in front of WrapLineBuffer.  The backward word search
; at L_BDCB stops here, and JustifyNextWritePointer/JustifyWritePointer count write positions from this byte
; (the write pointer is pre-incremented, so the first character goes to $7004).
; Evidence: BufferJustifiedCharacter..L_BDE2 semantics; tools/check_routines.py text/justified-word-wrap.
WrapSentinelSpace:
    defb $20                                                                              ; $7003  

; VERIFIED: 30-character output line of the justified word-wrap printer (PrintCharacter
; passes characters to BufferJustifiedCharacter while TextRedirectFlag = 1; message control StartJustifiedText enters
; the mode, EndJustifiedText flushes).  PrintJustifiedLine prints these 30 bytes through PutCharacter.
; On overflow the last word moves to WrapCarryBuffer and InsertSpaceInTextBuffer inserts spaces
; at word gaps to fill the line (justification).
; Evidence: tools/check_routines.py text/justified-word-wrap prints a planet description
; as justified 30-column lines; runtime: docked-system-data.
WrapLineBuffer:
    defs 30,0                                                                             ; $7004..$7021

; VERIFIED: 31st character position: receives the character that does not fit; a space
; here simply flushes the line, otherwise the word ending here is carried over.
; L_BDDC also restarts the backward space search from this byte.
WrapOverflowChar:
    defs 1,0                                                                              ; $7022..$7022

; VERIFIED: Carry-over buffer: the word moved off a full line is copied here, then
; StartNextJustifiedLine moves 30 bytes from here to WrapLineBuffer and refills this buffer
; with spaces.
; NOTE: StartJustifiedText fills 31 bytes from here, so it also writes $20 to
; CurrentScreenId ($7041).  Runtime confirms the write (PC $BDA9) and
; tools/check_routines.py text/justified-word-wrap reproduces it; the original code relies
; on later screen selection to overwrite it.
WrapCarryBuffer:
    defs 30,0                                                                             ; $7023..$7040

; VERIFIED: Current screen selector: 0..3 are the four cockpit views; other values select non-flight screens.
CurrentScreenId:
    defb $00                                                                              ; $7041 .

; VERIFIED: Current roll rate, sign-magnitude byte (bit 7 = direction).  Copied each
; frame by ReadFlightControls from L_FF09, which the interrupt code updates.
; Shown by the RL indicator (RollIndicator) and applied by ApplyPlayerMotion, which
; rotates body/object positions by the player's roll and pitch.
PlayerRoll:
    defb $00                                                                              ; $7042 .

; VERIFIED: Current pitch rate, sign-magnitude byte, copied from L_FF0B by
; ReadFlightControls.  Shown by the DC indicator (PitchIndicator); used by
; ApplyPlayerMotion.  Cleared when docking starts (DockIntoStation) and by ClearPitchAndSpeed.
PlayerPitch:
    defb $00                                                                              ; $7043 .

; VERIFIED: Current speed 0..31, copied from the high byte of SpeedControl by ReadFlightControls
; and shown on the SP gauge (SpeedGauge = speed*5+5).  ApplyPlayerMotion moves bodies along z by
; 2*(speed+1) per update.  Set to 7 for the stardust of the remaining launch-tunnel
; frames (SeedLaunchDust), 12 by DockIntoStation and 0 on death.
PlayerSpeed:
    defb $0A                                                                              ; $7044 .

; VERIFIED: Thirteen (last drawn value, current value) byte pairs for the cockpit
; gauges, walked by DrawGauges from ForwardShield in steps of two.  A gauge
; is redrawn only when its current value differs from the last drawn copy
; stored in the byte before it.  This first byte is the drawn copy of
; ForwardShield.  Pairs 0..10 are bars (value/4 pixels, 160 = full 40-pixel
; bar), pairs 11..12 the RL/DC indicators.  Screen addresses: GaugeScreenAddresses.
; Evidence: tools/check_routines.py controls/read-flight-controls, controls/draw-gauges;
; cockpit labels FS AS FU CT LT AL SP 1..4 RL DC.
GaugeDisplayTable:
    defb $00                                                                              ; $7045 .  drawn copy of ForwardShield

; VERIFIED: Fore shield strength, 0..160, drawn as the FS bar.  L_A584 subtracts fore
; damage (FrontDamageThisUpdate), IncrementUpToFull recharges it; PrepareShipForLaunch fills it ($A0) at launch.
ForwardShield:
    defb $00                                                                              ; $7046 .
    defb $00                                                                              ; $7047 .  drawn copy of AftShield

; VERIFIED: Aft shield strength, 0..160, drawn as the AS bar (damage from RearDamageThisUpdate).
AftShield:
    defb $00                                                                              ; $7048 .
    defb $00                                                                              ; $7049 .  drawn copy of FuelGauge

; VERIFIED: FU bar value, written by L_D873 from the commander's fuel (FuelLevel).
FuelGauge:
    defb $A0                                                                              ; $704A .
    defb $00                                                                              ; $704B .  drawn copy of CabinTemperature

; VERIFIED: CT bar value.  UpdateProximityAndCompass sets it from the distance to the sun when close to it;
; UpdateExpandingSun increments it every frame; cleared at launch and after
; hyperspace.
CabinTemperature:
    defb $00                                                                              ; $704C .
    defb $00                                                                              ; $704D .  drawn copy of LaserTemperature

; VERIFIED: LT bar value, raised and checked by the laser-firing code (UpdatePlayerLaser..L_EC39);
; cleared at launch.
LaserTemperature:
    defb $00                                                                              ; $704E .
    defb $00                                                                              ; $704F .  drawn copy of AltitudeGauge

; VERIFIED: AL bar value: $A0 minus the distance-derived value to the planet (L_892F),
; $A0 (full) when far from it.
AltitudeGauge:
    defb $A0                                                                              ; $7050 .
    defb $00                                                                              ; $7051 .  drawn copy of SpeedGauge

; VERIFIED: SP bar value, PlayerSpeed*5+5, computed by ReadFlightControls.
SpeedGauge:
    defb $00                                                                              ; $7052 .
    defb $FF                                                                              ; $7053 .  drawn copy of EnergyBank1

; VERIFIED: Energy bank 1 of 4 (gauge "1"), 0..160.  Damage drains bank 1 first
; (DrainEnergyBanks); recharge (RechargeStep) fills bank 4 first.  When all four are empty
; L_A5AB sets PlayerDeadFlag.
EnergyBank1:
    defb $00                                                                              ; $7054 .
    defb $00                                                                              ; $7055 .  drawn copy of EnergyBank2

; VERIFIED: Energy bank 2 of 4 (gauge "2"); accessed only through the bank loops.
EnergyBank2:
    defb $00                                                                              ; $7056 .
    defb $00                                                                              ; $7057 .  drawn copy of EnergyBank3

; VERIFIED: Energy bank 3 of 4 (gauge "3").  ToggleCloak requires at least $28 here.
EnergyBank3:
    defb $A0                                                                              ; $7058 .
    defb $00                                                                              ; $7059 .  drawn copy of EnergyBank4

; VERIFIED: Energy bank 4 of 4 (gauge "4").  Below $A0 UpdateEnergyAndShields sets FlightCondition $63;
; below $9F CheckFlightWarnings shows "ENERGY LOW" and switches the cloak off.
EnergyBank4:
    defb $A0                                                                              ; $705A .
    defb $00                                                                              ; $705B .  drawn copy of RollIndicator

; VERIFIED: RL indicator position: 21 + roll magnitude for a positive roll, 21 -
; magnitude for a negative one (ReadFlightControls).  Drawn as a two-pixel
; marker at pixels value-2..value-1 of the gauge.
RollIndicator:
    defb $00                                                                              ; $705C .
    defb $00                                                                              ; $705D .  drawn copy of PitchIndicator

; VERIFIED: DC indicator position, computed from PlayerPitch like RollIndicator.
PitchIndicator:
    defb $00                                                                              ; $705E .

; VERIFIED: Two bytes after the gauge table; no static or runtime access was found (no
; instruction or pointer operand $705F/$7060 in the image; no traced read or write).
L_705F:
    defb $00,$00                                                                          ; $705F ..

; VERIFIED: Nonzero after a hyperspace jump that ended between systems: EnterHyperspaceMisjump sets it
; when bit 6 of the option byte ControlOptions is set or AuxRandomSeed's low byte is
; $F9, places the current coordinates midway to the target, clears
; StationPresent, and PlayHyperspaceArrival then launches a Thargoid group
; (DispatchShipEvent 1).  While set, the sun/planet are not drawn or moved,
; no station tunnel starts and ordinary encounters are suppressed.
; Cleared on a normal arrival (ArriveInTargetSystem) and at game start.
WitchspaceFlag:
    defb $00                                                                              ; $7061 .

; VERIFIED: 0 while docked; in flight the colour of the cockpit condition cells
; (L_A4E8 stores it as an attribute): 4 green (launch, SetConditionGreen), 6 yellow
; (SetConditionYellowForShips, L_8A30), 2 red (UpdateConditionIndicator when a shield is empty, L_8A28), $63
; flashing red (UpdateEnergyAndShields when EnergyBank4 is below $A0, L_8A2C); L_A4D6
; alternates attributes 0 and 2 for $63.
; The main loop takes the docked path for 0 and the flight path otherwise.
FlightCondition:
    defb $00                                                                              ; $7062 .

; VERIFIED: Word state of the small generator AdvanceRandomHL used by RespawnDust (particle
; coordinates); saved back at L_A3EA.  Its low byte is also read as a random
; value: $F9 forces witchspace at hyperspace arrival (L_D684) and the
; pirate check at $D80C compares it.  SeedLaunchDust seeds launch particles from it.
AuxRandomSeed:
    defw $4A37                                                                            ; $7063

; VERIFIED: Sun position: x, y, z, each three bytes (fraction, then a 16-bit word whose
; bit 15 is the sign).  Evidence: UpdateProximityAndCompass derives CabinTemperature and the
; fuel-scoop range from it; DrawSunAndPlanet draws it with circle mode 0.
; L_D6E2 places it at hyperspace arrival; ApplyPlayerMotion moves it with the player.
SunPosition:
    defb $00                                                                              ; $7065 .  sun x fraction
SunXWord:
    defb $00                                                                              ; $7066 .  sun x word low
SunXHigh:
    defb $00                                                                              ; $7067 .  sun x word high, bit 7 sign
SunY:
    defb $00                                                                              ; $7068 .  sun y fraction
SunYWord:
    defb $80                                                                              ; $7069 .  sun y word low
SunYHigh:
    defb $01                                                                              ; $706A .  sun y word high, bit 7 sign
SunZ:
    defb $00                                                                              ; $706B .  sun z fraction
SunZWord:
    defb $10                                                                              ; $706C .  sun z word low

; VERIFIED: High byte and sign of the sun z word; LaunchFromStation flips its sign.
SunZHigh:
    defb $09                                                                              ; $706D .  sun z word high, bit 7 sign

; VERIFIED: Planet position, same 9-byte format as SunPosition.  L_892F derives
; AltitudeGauge and StationPresent from it; L_D72B copies it into station
; slot 0 before offsetting the station; drawn with circle mode 1.
PlanetPosition:
    defb $00                                                                              ; $706E .  planet x fraction
PlanetXWord:
    defb $00                                                                              ; $706F .  planet x word low
PlanetXHigh:
    defb $00                                                                              ; $7070 .  planet x word high, bit 7 sign
PlanetY:
    defb $00                                                                              ; $7071 .  planet y fraction
PlanetYWord:
    defb $00                                                                              ; $7072 .  planet y word low
PlanetYHigh:
    defb $00                                                                              ; $7073 .  planet y word high, bit 7 sign
PlanetZ:
    defb $00                                                                              ; $7074 .  planet z fraction

; VERIFIED: Low byte of the planet z word (LaunchFromStation sets z to $0180).
PlanetZWord:
    defb $80                                                                              ; $7075 .  planet z word low
PlanetZHigh:
    defb $14                                                                              ; $7076 .  planet z word high, bit 7 sign

; VERIFIED: Nonzero while the station is present; also selects the cockpit S indicator.
StationPresent:
    defb $00                                                                              ; $7077 .

; VERIFIED: Nonzero ($FF) while station slot 0 is inactive: UpdateStationDormancy sets it
; when the station's energy is zero and clears it (restoring energy $F0) once
; all three station coordinate words are below 256.  Set at hyperspace
; arrival, cleared at launch.  The in-system jump (HandleTorusJumpKey) requires it
; nonzero.  While it is $FF the compass keeps using the station slot, but L_897E
; switches to the coarse 24-bit form (CompassOffsetCoarse).
StationDormantFlag:
    defb $00                                                                              ; $7078 .

; VERIFIED: 1 while the sun closeness value of UpdateProximityAndCompass (negated GetVectorMagnitude result) exceeds
; $2000; above $4000 CollideWithSunOrPlanet is taken instead.  With fuel scoops fitted
; (FuelScoopsFitted) CheckFlightWarnings then shows token $A0 "FUEL SCOOPS ON" and adds fuel.
FuelScoopRangeFlag:
    defb $00                                                                              ; $7079 .

; VERIFIED: Nonzero ends the game: the main loop runs RunGameOverSequence.  Set when all
; energy banks are empty (L_A5AB), by a collision/crash path (CollideWithSunOrPlanet, CrashIntoStation)
; and by UpdateExpandingSun; ReadFlightControls input and UpdateSightsLaserAndEcm laser
; handling stop while it is set.
PlayerDeadFlag:
    defb $00                                                                              ; $707A .

; VERIFIED: 1 when the sun is visible with a projected radius of 40 or more
; (DrawSunAndPlanet).  L_DA29 then patches the four line-plot sites
; (SteepUpPlotOp, ShallowUpPlotOp, SteepDownPlotOp, ShallowDownPlotOp) to XOR C instead of OR C, so lines stay
; visible over the large sun.
LargeSunFlag:
    defb $00                                                                              ; $707B .

; VERIFIED: Nonzero suspends ReadFlightControls in the main loop.  Only four stores exist:
; DockIntoStation sets it and it stays set while docked until LaunchFromStation
; clears it after the launch tunnel; RunGameOverSequence sets it for the death
; sequence and clears it before the restart.  After a game-ending message on docking
; (EndGameWithMessage) it therefore stays set into the next game until its first launch.
ControlsLockedFlag:
    defb $00                                                                              ; $707C .

; VERIFIED: Bit mask of pending sound effects.  UpdateSoundEffect (sound enabled: bit 7 of ControlOptions)
; selects the lowest set bit and jumps through the 8-entry JP table at SoundRequestJumpTable
; to a beeper routine (OUT ($FE)).  Bits are set by game events, e.g. bit 0
; energy bomb (L_9275), bit 2 (L_EB44), bit 4 (L_EC18), bit 6 (L_EB10).
SoundEffectRequests:
    defb $00                                                                              ; $707D .

; VERIFIED: Set when the docking-computer key docks the ship (CheckDockingComputerKey); cleared by PrepareShipForLaunch
; at launch.  While set CheckFlightWarnings shows token $7B "DOCKING COMPUTERS ON".
DockingComputerFlag:
    defb $00                                                                              ; $707E .

; VERIFIED: Copy the high bytes of the interrupt-maintained accumulators RollControl,
; PitchControl and SpeedControl (L_FF09, L_FF0B, L_FF0D) into PlayerRoll, PlayerPitch
; and PlayerSpeed, and compute RollIndicator/PitchIndicator (21 +/- magnitude) and
; SpeedGauge (speed*5+5).  Called by MainLoop unless ControlsLockedFlag is set.
; Clobbers A, B, C, HL.
; Evidence: tools/check_routines.py controls/read-flight-controls, controls/draw-gauges;
; runtime writers of $FF09/$FF0B/$FF0D are $FE7A/$FEE8/$FF1D in the interrupt code.
ReadFlightControls:
    LD HL,RollControl+1                        ; $707F: 21 09 FF  interrupt-maintained roll input
    LD A,(HL)                                  ; $7082: 7E
    LD (PlayerRoll),A                          ; $7083: 32 42 70  sign-magnitude roll rate
    BIT 7,A                                    ; $7086: CB 7F  bit 7: roll direction
    JR NZ,L_708E                               ; $7088: 20 04
    ADD A,$15                                  ; $708A: C6 15  positive: indicator 21 + value
    JR L_7094                                  ; $708C: 18 06
L_708E:
    AND $7F                                    ; $708E: E6 7F  roll magnitude
    LD C,A                                     ; $7090: 4F
    LD A,$15                                   ; $7091: 3E 15  negative: indicator 21 - magnitude
    SUB C                                      ; $7093: 91
L_7094:
    LD (RollIndicator),A                       ; $7094: 32 5C 70  RL marker position
    INC HL                                     ; $7097: 23  HL = high byte of PitchControl
    INC HL                                     ; $7098: 23
    LD A,(HL)                                  ; $7099: 7E
    LD (PlayerPitch),A                         ; $709A: 32 43 70  sign-magnitude pitch rate
    BIT 7,A                                    ; $709D: CB 7F
    JR NZ,L_70A5                               ; $709F: 20 04
    ADD A,$15                                  ; $70A1: C6 15  positive: 21 + value
    JR L_70AB                                  ; $70A3: 18 06
L_70A5:
    AND $7F                                    ; $70A5: E6 7F
    LD C,A                                     ; $70A7: 4F
    LD A,$15                                   ; $70A8: 3E 15  negative: 21 - magnitude
    SUB C                                      ; $70AA: 91
L_70AB:
    LD (PitchIndicator),A                      ; $70AB: 32 5E 70  DC marker position
    INC HL                                     ; $70AE: 23  HL = high byte of SpeedControl
    INC HL                                     ; $70AF: 23
    LD A,(HL)                                  ; $70B0: 7E
    LD (PlayerSpeed),A                         ; $70B1: 32 44 70  speed 0..31
    LD B,A                                     ; $70B4: 47  SpeedGauge = 5*speed + 5
    ADD A,A                                    ; $70B5: 87
    ADD A,A                                    ; $70B6: 87
    ADD A,B                                    ; $70B7: 80
    ADD A,$05                                  ; $70B8: C6 05
    LD (SpeedGauge),A                          ; $70BA: 32 52 70
    RET                                        ; $70BD: C9

; VERIFIED: Per-frame docking check in flight.  Return if HyperspaceKeyLatch (set by the hyperspace
; key handler CheckHyperspaceKeys) is set.  If DockingContactFlag (station slot contact, set at L_EB0C)
; is set, clear it and dock (DockWithStation).  Otherwise read and clear key
; bit 7 of KeyFlagsCombat and dock with the docking computer if the station is
; present, docking computers are fitted (DockingComputerFitted), the ship is in flight,
; JumpTunnelMode is clear (no hyperspace countdown: CheckHyperspaceKeys sets 1 or 2 for normal or
; galactic hyperspace) and the station is not hostile (byte +$21 bit 2).
CheckDocking:
    LD A,(HyperspaceKeyLatch)                  ; $70BE: 3A 39 7C  any hyperspace key press since the last arrival: no docking
    AND A                                      ; $70C1: A7
    RET NZ                                     ; $70C2: C0
    LD A,(DockingContactFlag)                  ; $70C3: 3A 15 DA  station slot contact (L_EB0C)
    AND A                                      ; $70C6: A7
    JR Z,CheckDockingComputerKey               ; $70C7: 28 06  no contact: docking-computer key
    XOR A                                      ; $70C9: AF
    LD (DockingContactFlag),A                  ; $70CA: 32 15 DA  contact consumed
    JR DockWithStation                         ; $70CD: 18 2C

; VERIFIED: Docking-computer key path of CheckDocking: read and clear bit 7 of KeyFlagsCombat
; (key C).  Docking needs StationPresent, DockingComputerFitted, FlightCondition
; nonzero, JumpTunnelMode clear and the station's hostile bit (+$21 bit 2) clear; then
; DockingComputerFlag = 1 and fall into DockWithStation.  Every refusal just returns.
CheckDockingComputerKey:
    LD A,(KeyFlagsCombat)                      ; $70CF: 3A 11 FC  key bit 7: docking computer
    LD B,A                                     ; $70D2: 47
    AND $80                                    ; $70D3: E6 80  Z if not pressed
    RES 7,B                                    ; $70D5: CB B8  key bit consumed
    LD A,B                                     ; $70D7: 78
    LD (KeyFlagsCombat),A                      ; $70D8: 32 11 FC
    RET Z                                      ; $70DB: C8  C not pressed
    LD A,(StationPresent)                      ; $70DC: 3A 77 70  station must be in range
    AND A                                      ; $70DF: A7
    RET Z                                      ; $70E0: C8
    LD A,(DockingComputerFitted)               ; $70E1: 3A 4E A8  docking computers fitted
    AND A                                      ; $70E4: A7
    RET Z                                      ; $70E5: C8
    LD A,(FlightCondition)                     ; $70E6: 3A 62 70  not when docked
    AND A                                      ; $70E9: A7
    RET Z                                      ; $70EA: C8
    LD A,(JumpTunnelMode)                      ; $70EB: 3A 0A A8  not during a jump countdown or tunnel
    AND A                                      ; $70EE: A7
    RET NZ                                     ; $70EF: C0
    LD HL,InitialRuntimeState+InstanceBehaviour ; $70F0: 21 69 60  station behaviour byte
    BIT 2,(HL)                                 ; $70F3: CB 56  station hostile: refuse
    RET NZ                                     ; $70F5: C0
    LD A,$01                                   ; $70F6: 3E 01  remember the automatic docking
    LD (DockingComputerFlag),A                 ; $70F8: 32 7E 70

; VERIFIED: Dock: select the front view, restore the cockpit, make SunPosition
; relative to the station (MakeSunRelativeToStation) and run the docking
; tunnel through StartStationTunnel.
DockWithStation:
    XOR A                                      ; $70FB: AF
    LD (CurrentScreenId),A                     ; $70FC: 32 41 70  front view
    CALL RestoreCockpitIfFullScreen            ; $70FF: CD 1C 74  cockpit back if a page is shown

; VERIFIED: Common docking path: MakeSunRelativeToStation, then StartStationTunnel (which runs
; the docking tunnel because FlightCondition is nonzero).  Reached by falling through
; DockWithStation and by the JP in UpdateEscapePod when its EscapePodTimer countdown
; (24 frames after the escape pod is launched) reaches zero, so the escape pod also
; ends docked at the station.  Evidence: instruction semantics; runtime: executed, and
; the countdown test at $A784 is executed too.
StartDockingSequence:
    CALL MakeSunRelativeToStation              ; $7102: CD 08 71
    JP StartStationTunnel                      ; $7105: C3 F8 7A  in flight: docking tunnel

; VERIFIED: For x, y and z: sun word = sun word - station word (slot 0 at
; InitialRuntimeState), using HalveDifferenceSignMagnitude (halved signed difference) and doubling
; the result again, so bit 0 of each word is lost.  Fraction bytes are kept.
; IX and IY advance by 3 per axis.  Used on every docking (StartDockingSequence): the
; sun position becomes relative to the station, which is the docked ship's position;
; that is the position a tape save stores (SavedSunPosition) and that
; LaunchFromStation later mirrors in z.
; Evidence: tools/check_routines.py maths/sun-relative-to-station (3000 cases).
MakeSunRelativeToStation:
    LD IY,SunPosition                          ; $7108: FD 21 65 70
    LD IX,InitialRuntimeState                  ; $710C: DD 21 48 60  IX = station position (slot 0)
    CALL L_7116                                ; $7110: CD 16 71  x
    CALL L_7116                                ; $7113: CD 16 71  y; z by falling through

; VERIFIED: One axis of MakeSunRelativeToStation: difference, double, keep the sign.
L_7116:
    CALL HalveCoordinateDifference             ; $7116: CD 2C 71
    ADD HL,HL                                  ; $7119: 29  restore the halved difference
    JR NC,L_711E                               ; $711A: 30 02  carry = sign of the halved value
    SET 7,H                                    ; $711C: CB FC  negative: set the sign again
L_711E:
    LD (IY+$02),H                              ; $711E: FD 74 02
    LD (IY+$01),L                              ; $7121: FD 75 01
    LD DE,$0003                                ; $7124: 11 03 00  next coordinate, 3 bytes on
    ADD IY,DE                                  ; $7127: FD 19
    ADD IX,DE                                  ; $7129: DD 19
    RET                                        ; $712B: C9

; VERIFIED: HL = word at IY+1, DE = word at IX+1: the middle and high bytes of two 24-bit
; sign-magnitude coordinates, i.e. coordinate/256 with the sign in bit 15.  Continue in
; HalveDifferenceSignMagnitude, which returns (HL - DE)/2 in sign-magnitude form.  MakeSunRelativeToStation
; uses it for sun minus station (IY = sun, IX = station).
; Evidence: tools/check_routines.py maths/sun-relative-to-station.
HalveCoordinateDifference:
    LD H,(IY+$02)                              ; $712C: FD 66 02
    LD L,(IY+$01)                              ; $712F: FD 6E 01
    LD D,(IX+$02)                              ; $7132: DD 56 02
    LD E,(IX+$01)                              ; $7135: DD 5E 01
    JP HalveDifferenceSignMagnitude            ; $7138: C3 F0 E8

; VERIFIED: Chart keys.  Only on screens 7 (galactic chart, handler 3) and 8 (short-range chart,
; handler 4) and only while JumpTunnelMode is clear (no hyperspace countdown or tunnel): take
; the lowest set bit n of (KeyFlagsFlight AND $0F) OR (KeyFlagsChart AND $70) and run screen handler
; 9 + n through CallScreenHandler, then clear both key bytes.  Handlers: 9 cursor left (bit 0),
; 10 right (1), 11 down (2), 12 up (3), 13 cursor to the current system (bit 4),
; 14 snap to the nearest system (5), 15 find a system by name (6).
; Called by MainLoop when docked and by the non-view flight frame (L_72D2).
; Evidence: HandleScreenKeys maps screen keys to screens 7..12 = handlers 3..8; the JP table
; ScreenFunctionTable; tools/check_routines.py controls/p1-chart-cursor-keys.
HandleChartCursorKeys:
    LD A,(CurrentScreenId)                     ; $713B: 3A 41 70
    CP $07                                     ; $713E: FE 07  charts: screens 7 and 8
    RET C                                      ; $7140: D8  below 7: no chart
    CP $09                                     ; $7141: FE 09
    RET NC                                     ; $7143: D0  9 or more: no chart
    LD A,(JumpTunnelMode)                      ; $7144: 3A 0A A8  jump countdown or tunnel: no cursor
    AND A                                      ; $7147: A7
    RET NZ                                     ; $7148: C0
    LD A,(KeyFlagsFlight)                      ; $7149: 3A 0F FC
    AND $0F                                    ; $714C: E6 0F  bits 0..3: left, right, down, up
    LD C,A                                     ; $714E: 4F
    LD A,(KeyFlagsChart)                       ; $714F: 3A 12 FC
    AND $70                                    ; $7152: E6 70  bits 4..6 of KeyFlagsChart
    OR C                                       ; $7154: B1
    RET Z                                      ; $7155: C8  no chart key
    LD B,$08                                   ; $7156: 06 08  handler = 9 + lowest set bit
L_7158:
    INC B                                      ; $7158: 04
    SRL A                                      ; $7159: CB 3F
    JR NC,L_7158                               ; $715B: 30 FB
    LD A,B                                     ; $715D: 78
    CALL CallScreenHandler                     ; $715E: CD 02 8F  chart handlers 9..15
    XOR A                                      ; $7161: AF  keys consumed
    LD (KeyFlagsChart),A                       ; $7162: 32 12 FC
    LD (KeyFlagsFlight),A                      ; $7165: 32 0F FC
    RET                                        ; $7168: C9

; VERIFIED: Unused routine: EI, RET.  It follows the unconditional RET of HandleChartCursorKeys
; and precedes Startup, so only a call or jump could enter it, and there is none: no
; word $7169 in the image, no relative jump to it, and the seven 48K access traces
; neither execute nor read it.  Called, it enables interrupts and returns with every other register and
; all memory unchanged.  The comparison 48K memory images contain no RET, EI, RET
; sequence, so it is not a leftover of their layout.
; Evidence: tools/check_routines.py dormant/unused-interrupt-routines; execution, read and
; write maps of tools/run_runtime_scenarios.py --accesses.
UnusedEnableInterrupts:
    EI                                         ; $7169: FB
    RET                                        ; $716A: C9

; Direct target of the entry JP at $7000.
; VERIFIED: One-time start-up (default ship variant): copy the font (FontBitmapSize = 728 bytes,
; glyphs $20..$7A) to FontRuntime and the initial cockpit colours to the mutable buffer
; CockpitAttributesRuntime, because their tape areas at $C000/$C700 are reused as view
; buffer and work space.  Then install IM 2, enable interrupts, save SP in
; StartupStackPointer, reset the inputs and draw the first cockpit screen.
IF SHIP_ADDER
Startup:
    INCLUDE "data/text-dispatch-first.asm"
    defs 2,0 ; preserve the original reclaimed-slot padding
defc StartupAfterGraphicsCopy = AdderStartupAfterGraphicsCopy
ELSE
Startup:
    LD HL,FontBitmap                           ; $716B: 21 00 C0  font, 91 glyphs
    LD DE,FontRuntime                          ; $716E: 11 70 5D
    LD BC,FontBitmapSize                       ; $7171: 01 D8 02
    LDIR                                       ; $7174: ED B0
    LD HL,CockpitAttributes                    ; $7176: 21 00 C7  initial colours to the mutable copy
    LD DE,CockpitAttributesRuntime             ; $7179: 11 00 5B
    LD BC,CockpitAttributesSize                ; $717C: 01 00 01
    LDIR                                       ; $717F: ED B0

; VERIFIED: font and cockpit colours have been relocated before their source RAM is reused.
StartupAfterGraphicsCopy:
    CALL EnableInterruptMode2                  ; $7181: CD 4C FF
    EI                                         ; $7184: FB
    LD (StartupStackPointer),SP                ; $7185: ED 73 B2 74  restart stack for EndGameWithMessage
ENDIF

; VERIFIED: Shared startup continuation after font/colour copies and the initial stack save.
; Both original Startup and the one-time relocated AdderStartup reach here.
; Restart/death enters later at RunTitleScreen; do not rerun reclaimed Adder startup storage.
ContinueStartup:
    CALL ResetFlightInputs                     ; $7189: CD FF 7B  controls neutral, speed input 12
    CALL ClearScreenAndDrawCockpit             ; $718C: CD 25 74  first screen: frame and cockpit

; ============================================================================
; Title screen and main game loop
; Title ship display, new-game start, the per-frame main loop and the death
; sequence.
; ============================================================================

; VERIFIED: Title sequence; also the restart point after death or a game-ending message
; (the stack is reset by EndGameWithMessage).  Show title ship ID 9 (Cobra Mk III)
; in slot 7 (DispatchShipEvent event 9 creates ship C+2, C = high nibble), set bit 7 of
; station byte +$1D, paint the top two thirds' attributes white
; on black, then loop showing "LOAD NEW COMMANDER (Y/N)?" with a rotating ship.
; 'Y' opens the tape/access menu (RunAccessMenu); any other key continues to the
; "PRESS SPACE, COMMANDER" loop with a new title ship.
RunTitleScreen:
    LD A,$79                                   ; $718F: 3E 79  event 9, C=7: ID 9 (Cobra Mk III)
    CALL DispatchShipEvent                     ; $7191: CD CA F2
    LD HL,InitialRuntimeState+InstanceRoll     ; $7194: 21 65 60  station byte +$1D
    SET 7,(HL)                                 ; $7197: CB FE  cleared by L_D812; tested by CheckPirateGameOver
    LD HL,$5800                                ; $7199: 21 00 58  attributes of the top two thirds
    CALL FillAttributePageWhite                ; $719C: CD 7D 72  attribute rows 0..7 = $07
    CALL FillAttributePageWhite                ; $719F: CD 7D 72  attribute rows 8..15 = $07

; VERIFIED: Load-prompt loop: one animated frame per pass until a key is pressed
; (LastKeyCode holds $FF while none is).
L_71A2:
    CALL ClearViewBuffer                       ; $71A2: CD 5F 74
    CALL DrawTitleLoadPrompt                   ; $71A5: CD 48 72
    CALL RotateAndDrawTitleShip                ; $71A8: CD DD DF
    CALL BlitViewBitmap                        ; $71AB: CD 98 73
    LD A,(LastKeyCode)                         ; $71AE: 3A 13 FC  $FF: no key
    INC A                                      ; $71B1: 3C  $FF + 1 = 0: still no key
    JR Z,L_71A2                                ; $71B2: 28 EE
    CP $5A                                     ; $71B4: FE 5A  'Y' (code + 1 = $5A)
    JR NZ,L_71C8                               ; $71B6: 20 10  other key: start prompt
    CALL SaveCleanCockpit                      ; $71B8: CD 42 8F  save the cockpit before the menu
    CALL RunAccessMenu                         ; $71BB: CD E4 D2  'Y': tape access menu

; VERIFIED: Return from the access menu (also from the docked main loop when RunAccessMenu
; returns NZ): front view, clear screen, restore cockpit, then the start
; prompt.
L_71BE:
    XOR A                                      ; $71BE: AF
    LD (CurrentScreenId),A                     ; $71BF: 32 41 70  front view
    CALL ClearScreenAndFrame                   ; $71C2: CD 9E BC
    CALL RestoreCockpitIfFullScreen            ; $71C5: CD 1C 74

; VERIFIED: Wait for key release, then pick the next title ship from TitleShipCounter:
; C = (counter AND 7) + 1, plus 10 when below 6 (11..15, 6, 7, 8); event 9
; then shows ship ID C+2: 13..17 (Asp Mk II, Fer-de-Lance, Thargoid, Sidewinder,
; blueprint slot 17), then 8, 9, 10 (Viper, Cobra Mk III, Python).
; Evidence: tools/check_routines.py controls/p1-title-ship-cycle; docs/SHIPS.md IDs.
L_71C8:
    LD A,(LastKeyCode)                         ; $71C8: 3A 13 FC
    INC A                                      ; $71CB: 3C
    JR NZ,L_71C8                               ; $71CC: 20 FA  wait until the key is released
    LD HL,TitleShipCounter                     ; $71CE: 21 86 72
    INC (HL)                                   ; $71D1: 34
    LD A,(HL)                                  ; $71D2: 7E
    AND $07                                    ; $71D3: E6 07
    INC A                                      ; $71D5: 3C
    CP $06                                     ; $71D6: FE 06  1..5 -> 11..15; 6..8 stay
    JR NC,L_71DC                               ; $71D8: 30 02
    ADD A,$0A                                  ; $71DA: C6 0A
L_71DC:
    ADD A,A                                    ; $71DC: 87  C to the high nibble
    ADD A,A                                    ; $71DD: 87
    ADD A,A                                    ; $71DE: 87
    ADD A,A                                    ; $71DF: 87
    ADD A,$09                                  ; $71E0: C6 09  event 9: ship ID C+2
    CALL DispatchShipEvent                     ; $71E2: CD CA F2

; VERIFIED: Start-prompt loop.  Each pass waits one frame (HALT; the interrupt rescans the keys)
; and then picks the control method from a joystick held left: Kempston port $1F bit 1
; (only if bit 5 reads 0, taken as an interface being present) selects 1, key '5'
; (Cursor left, JoystickNumberKeys bit 1) selects 2 and key '6' (Sinclair left, bit 3) selects 3;
; SPACE (LastKeyCode = $20) selects 0 (keyboard).
L_71E5:
    CALL ClearViewBuffer                       ; $71E5: CD 5F 74
    CALL DrawTitleStartPrompt                  ; $71E8: CD 52 72
    CALL RotateAndDrawTitleShip                ; $71EB: CD DD DF
    CALL BlitViewBitmap                        ; $71EE: CD 98 73
    LD BC,$FF1F                                ; $71F1: 01 1F FF  B=$FF, C=Kempston port $1F
    LD HL,JoystickNumberKeys                   ; $71F4: 21 15 FC  keys '5' (bit 1) and '6' (bit 3)
    HALT                                       ; $71F7: 76  next frame: keys rescanned
    IN A,(C)                                   ; $71F8: ED 78
    BIT 5,A                                    ; $71FA: CB 6F  bit 5 set: no Kempston interface
    JR NZ,L_7204                               ; $71FC: 20 06
    AND $02                                    ; $71FE: E6 02  Kempston bit 1: joystick left
    LD A,$01                                   ; $7200: 3E 01  method 1: Kempston
    JR NZ,L_7219                               ; $7202: 20 15
L_7204:
    LD A,$02                                   ; $7204: 3E 02  method 2: Cursor, '5' = left
    BIT 1,(HL)                                 ; $7206: CB 4E
    JR NZ,L_7219                               ; $7208: 20 0F
    INC A                                      ; $720A: 3C  method 3: Sinclair, '6' = left
    BIT 3,(HL)                                 ; $720B: CB 5E
    JR NZ,L_7219                               ; $720D: 20 0A
    LD A,(LastKeyCode)                         ; $720F: 3A 13 FC  SPACE starts with the keyboard
    SUB $20                                    ; $7212: D6 20
    JR NZ,L_71E5                               ; $7214: 20 CF  not SPACE: keep waiting
    LD B,A                                     ; $7216: 47  B = 0: keyboard
    JR StartNewGame                            ; $7217: 18 06

; VERIFIED: Joystick start: remember the method (1..3) in SelectedJoystickType for the freeze-menu
; keyboard/joystick toggle; B = method.
L_7219:
    LD (SelectedJoystickType),A                ; $7219: 32 67 8F
    AND $03                                    ; $721C: E6 03  B = method 1..3
    LD B,A                                     ; $721E: 47

; VERIFIED: Store control method B in bits 0-1 of ControlOptions, restore the commander
; (InitialiseCommander), clear WitchspaceFlag, FlightCondition (docked), ExpandingSunActive,
; FuelScoopRangeFlag, CloakingDeviceActive (cloak) and ExpandingSunRadius, show the status
; screen (ShowCommanderStatus), reset inputs and enter MainLoop.
StartNewGame:
    LD HL,ControlOptions                       ; $721F: 21 14 FC
    LD A,(HL)                                  ; $7222: 7E
    AND $FC                                    ; $7223: E6 FC  bits 0-1: control method
    OR B                                       ; $7225: B0
    LD (HL),A                                  ; $7226: 77
    CALL InitialiseCommander                   ; $7227: CD 76 A9
    XOR A                                      ; $722A: AF
    LD (WitchspaceFlag),A                      ; $722B: 32 61 70
    LD (FlightCondition),A                     ; $722E: 32 62 70  docked
    LD (ExpandingSunActive),A                  ; $7231: 32 7C A8  expanding sun disarmed
    LD (FuelScoopRangeFlag),A                  ; $7234: 32 79 70
    LD (CloakingDeviceActive),A                ; $7237: 32 0C A8  cloak off
    LD (ExpandingSunRadius),A                  ; $723A: 32 BD 74
    CALL SaveCleanCockpit                      ; $723D: CD 42 8F  save the cockpit before the page
    CALL ShowCommanderStatus                   ; $7240: CD B9 D0  docked: status page
    CALL ResetFlightInputs                     ; $7243: CD FF 7B  controls neutral, speed input 12
    JR MainLoop                                ; $7246: 18 3F

; VERIFIED: Print the title banner and message 6 "LOAD NEW COMMANDER (Y/N)?" at
; column 1, row 14 into the view buffer.
DrawTitleLoadPrompt:
    CALL PrintTitleBanner                      ; $7248: CD 67 72
    LD HL,$0E01                                ; $724B: 21 01 0E  row 14, column 1
    LD A,$06                                   ; $724E: 3E 06  message 6: "LOAD NEW COMMANDER (Y/N)?"
    JR L_725A                                  ; $7250: 18 08

; VERIFIED: Print the title banner and message 7 "PRESS SPACE, COMMANDER" at column 4,
; row 14 into the view buffer.
DrawTitleStartPrompt:
    CALL PrintTitleBanner                      ; $7252: CD 67 72
    LD HL,$0E04                                ; $7255: 21 04 0E  row 14, column 4
    LD A,$07                                   ; $7258: 3E 07  message 7: "PRESS SPACE, COMMANDER"

; VERIFIED: HL = row/column, A = message: print the message into the view buffer.
L_725A:
    LD (TextColumn),HL                         ; $725A: 22 0D A8
    LD HL,L_BB81                               ; $725D: 21 81 BB
    SET 7,(HL)                                 ; $7260: CB FE  print into the view buffer ($C000)
    CALL PrintMessage                          ; $7262: CD D7 BA
    JR L_7277                                  ; $7265: 18 10  renderer back to the screen

; VERIFIED: Print token $1D "---- E L I T E ----" at column 5, row 1 into the view
; buffer: setting bit 7 of L_BB81 (high byte of the LD HL,$4000 at LoadCharacterScreenBase)
; redirects the character renderer from screen $4000 to $C000.
PrintTitleBanner:
    LD HL,$0105                                ; $7267: 21 05 01  row 1, column 5
    LD (TextColumn),HL                         ; $726A: 22 0D A8
    LD A,$1D                                   ; $726D: 3E 1D  token $1D: "---- E L I T E ----"
    LD HL,L_BB81                               ; $726F: 21 81 BB
    SET 7,(HL)                                 ; $7272: CB FE  print into the view buffer ($C000)
    CALL PrintToken                            ; $7274: CD 9D BA

; VERIFIED: Restore the character renderer to the screen (clear bit 7 of L_BB81).
L_7277:
    LD HL,L_BB81                               ; $7277: 21 81 BB
    RES 7,(HL)                                 ; $727A: CB BE  printing back to the screen ($4000)
    RET                                        ; $727C: C9

; VERIFIED: Fill 256 bytes from HL with $07 (white ink on black paper): eight attribute rows.
; Output: HL advanced by 256, A = 7, B = 0.  RunTitleScreen calls it twice from $5800
; for attribute rows 0..15 (the view area).
FillAttributePageWhite:
    LD B,$00                                   ; $727D: 06 00  256 bytes
    LD A,$07                                   ; $727F: 3E 07  white ink, black paper
L_7281:
    LD (HL),A                                  ; $7281: 77
    INC HL                                     ; $7282: 23
    DJNZ L_7281                                ; $7283: 10 FC
    RET                                        ; $7285: C9

; VERIFIED: Incremented for each new title ship; see L_71C8.
TitleShipCounter:
    defb $06                                                                              ; $7286 .

; VERIFIED: One game frame.  Unless ControlsLockedFlag is set read the flight controls;
; handle view keys (HandleScreenKeys) and HandleFreezeMode (carry: abandon the game, return to
; the title); hyperspace keys (CheckHyperspaceKeys).  Docked (FlightCondition 0): chart
; keys, SYMBOL SHIFT (bit 5 of KeyFlagsFlight) for the access menu (RunAccessMenu; back to the
; start prompt if a commander was loaded) or the status page.  In flight: docking
; check, jump drive (HandleTorusJumpKey), sun/planet motion
; and station dormancy (outside witchspace), then either a cockpit-view frame
; (L_72FD) or a non-view screen frame (L_72D2), and finally L_732B.
MainLoop:
    LD A,(ControlsLockedFlag)                  ; $7287: 3A 7C 70  set from docking until launch end
    AND A                                      ; $728A: A7
    JR NZ,L_7290                               ; $728B: 20 03
    CALL ReadFlightControls                    ; $728D: CD 7F 70  roll/pitch/speed from the interrupt inputs
L_7290:
    CALL HandleScreenKeys                      ; $7290: CD 95 8E  view keys 1..4 and page keys
    CALL HandleFreezeMode                      ; $7293: CD 68 8F  carry: quit to the title
    JR NC,L_72A2                               ; $7296: 30 0A
    XOR A                                      ; $7298: AF  game abandoned from the freeze menu
    LD (CurrentScreenId),A                     ; $7299: 32 41 70
    CALL RestoreCockpitIfFullScreen            ; $729C: CD 1C 74
    JP RunTitleScreen                          ; $729F: C3 8F 71
L_72A2:
    CALL CheckHyperspaceKeys                   ; $72A2: CD 74 D5  H and G: hyperspace requests
    LD A,(FlightCondition)                     ; $72A5: 3A 62 70
    AND A                                      ; $72A8: A7
    JR NZ,L_72C0                               ; $72A9: 20 15  nonzero: in flight
    CALL HandleChartCursorKeys                 ; $72AB: CD 3B 71  docked: chart keys
    LD A,(KeyFlagsFlight)                      ; $72AE: 3A 0F FC
    BIT 5,A                                    ; $72B1: CB 6F  SYMBOL SHIFT: access menu
    JR Z,MainLoop                              ; $72B3: 28 D2
    CALL RunAccessMenu                         ; $72B5: CD E4 D2  access menu; on Z the docked game continues with whatever record it left
    JP NZ,L_71BE                               ; $72B8: C2 BE 71  commander loaded: start prompt
    CALL ShowCommanderStatus                   ; $72BB: CD B9 D0  otherwise redraw the status page
    JR MainLoop                                ; $72BE: 18 C7

; VERIFIED: In-flight part of MainLoop.
L_72C0:
    LD A,(WitchspaceFlag)                      ; $72C0: 3A 61 70
    AND A                                      ; $72C3: A7
    JR NZ,L_72D2                               ; $72C4: 20 0C  witchspace: no sun, planet or station
    CALL CheckDocking                          ; $72C6: CD BE 70  dock on contact or key C
    CALL HandleTorusJumpKey                    ; $72C9: CD 66 99  J: in-system jump
    CALL MoveSunAndPlanet                      ; $72CC: CD 8F 77  bodies follow the ship's motion
    CALL UpdateStationDormancy                 ; $72CF: CD 9D 77  station slot off/on by distance

; VERIFIED: Non-view screen while flying (CurrentScreenId 4 or more): update ships and
; lasers without drawing; unless CheckDocking docked in this frame (FlightCondition
; 0) also the condition colour (SetConditionYellowForShips) and the energy/shield update UpdateEnergyAndShields, which
; UpdateCockpitSystems runs on cockpit views.  Then keep the expanding sun growing, print the
; message line and wait 8 frames, polling the chart keys.
L_72D2:
    LD A,(CurrentScreenId)                     ; $72D2: 3A 41 70
    CP $04                                     ; $72D5: FE 04  cockpit views are 0..3
    JR C,L_72FD                                ; $72D7: 38 24
    CALL UpdateObjects                         ; $72D9: CD 1D DA  objects move, nothing is shown
    CALL UpdateSightsLaserAndEcm               ; $72DC: CD 3F ED
    LD A,(FlightCondition)                     ; $72DF: 3A 62 70
    AND A                                      ; $72E2: A7
    JR Z,L_72EB                                ; $72E3: 28 06  docked in this frame: skip
    CALL SetConditionYellowForShips            ; $72E5: CD DE 8D  yellow condition with ships near
    CALL UpdateEnergyAndShields                ; $72E8: CD 72 A5  energy, shields and damage
L_72EB:
    CALL UpdateExpandingSun                    ; $72EB: CD FA 74  expanding sun also grows here
    CALL PrintViewTitleAndMessages             ; $72EE: CD 4C D4  message line on the page
    LD B,$08                                   ; $72F1: 06 08  8 frames per pass
L_72F3:
    PUSH BC                                    ; $72F3: C5
    CALL HandleChartCursorKeys                 ; $72F4: CD 3B 71  chart keys
    HALT                                       ; $72F7: 76
    POP BC                                     ; $72F8: C1
    DJNZ L_72F3                                ; $72F9: 10 F8
    JR L_732B                                  ; $72FB: 18 2E

; VERIFIED: Cockpit-view frame: clear the view buffer, draw sun/planet (not in
; witchspace), particles (UpdateDust), view name (PrintViewTitleAndMessages), ships, lasers, the
; hyperspace arrival tunnel, blit, scanner (DrawScannerContacts), gauges, cloak key and
; indicators (UpdateCockpitSystems).
L_72FD:
    CALL RestoreCockpitIfFullScreen            ; $72FD: CD 1C 74  cockpit back after a page
    CALL ClearViewBuffer                       ; $7300: CD 5F 74
    LD A,(WitchspaceFlag)                      ; $7303: 3A 61 70
    AND A                                      ; $7306: A7
    CALL Z,DrawSunAndPlanet                    ; $7307: CC BE 74  no sun or planet in witchspace
    CALL UpdateDust                            ; $730A: CD 74 9E  stardust
    CALL PrintViewTitleAndMessages             ; $730D: CD 4C D4  view name and messages
    CALL UpdateObjects                         ; $7310: CD 1D DA
    CALL UpdateSightsLaserAndEcm               ; $7313: CD 3F ED
    CALL PlayHyperspaceArrival                 ; $7316: CD A3 79  hyperspace arrival tunnel
    CALL DrawFlaggedObjectDiscs                ; $7319: CD 45 85  flagged discs straight on screen
    CALL BlitViewBitmap                        ; $731C: CD 98 73  show the view
    CALL DrawScannerContacts                   ; $731F: CD 29 8C  scanner contacts
    CALL DrawGauges                            ; $7322: CD 59 78  redraw changed gauges
    CALL ToggleCloak                           ; $7325: CD D5 77  cloak key
    CALL UpdateCockpitSystems                  ; $7328: CD 59 A5  indicators, missiles, pod, bomb

; VERIFIED: End of frame: UpdateProximityAndCompass (altitude, cabin temperature, station presence), then
; loop unless PlayerDeadFlag is set.
L_732B:
    CALL UpdateProximityAndCompass             ; $732B: CD E1 88  altitude, temperature, compass
    LD A,(PlayerDeadFlag)                      ; $732E: 3A 7A 70
    AND A                                      ; $7331: A7
    JP Z,MainLoop                              ; $7332: CA 87 72  PlayerDeadFlag clear: next frame

; VERIFIED: Death: stop, lock controls, normal colours (FillViewAttributes with L=7), remove the scanner
; contacts (RestoreScannerBackground), empty every slot and release the wreck (ClearAllShipSlots: a cargo canister
; and two alloy plates), explosion noise (PlayNoiseBurst, PlayLongNoiseSweep), then 30 frames of stardust
; and moving objects with message 9 " GAME OVER" at column 10, row 7 of the view,
; blank the view, free slots 1..7, wait 50 frames, unlock the controls, clear
; PlayerDeadFlag and HyperspaceKeyLatch and restart at RunTitleScreen.
; Not reached in the recorded runtime scenarios.
RunGameOverSequence:
    XOR A                                      ; $7335: AF
    LD (PlayerSpeed),A                         ; $7336: 32 44 70  ship stops
    LD (LargeSunFlag),A                        ; $7339: 32 7B 70  lines OR-plotted again
    INC A                                      ; $733C: 3C
    LD (ControlsLockedFlag),A                  ; $733D: 32 7C 70  controls locked
    LD L,$07                                   ; $7340: 2E 07  normal view colours
    CALL FillViewAttributes                    ; $7342: CD 87 92
    CALL RestoreScannerBackground              ; $7345: CD 1D 8E  remove scanner contacts
    CALL ClearAllShipSlots                     ; $7348: CD A4 EB  canister and two alloy plates
    CALL PlayNoiseBurst                        ; $734B: CD 51 90  explosion noise
    CALL PlayLongNoiseSweep                    ; $734E: CD 30 90
    CALL RestoreCockpitIfFullScreen            ; $7351: CD 1C 74
    LD B,$1E                                   ; $7354: 06 1E  30 frames
L_7356:
    PUSH BC                                    ; $7356: C5
    CALL ClearViewBuffer                       ; $7357: CD 5F 74  one frame of the drifting wreck
    CALL UpdateDust                            ; $735A: CD 74 9E
    CALL UpdateObjects                         ; $735D: CD 1D DA
    CALL UpdateSightsLaserAndEcm               ; $7360: CD 3F ED
    LD HL,L_BB81                               ; $7363: 21 81 BB  print into the view buffer
    PUSH HL                                    ; $7366: E5
    SET 7,(HL)                                 ; $7367: CB FE
    LD HL,$070A                                ; $7369: 21 0A 07  row 7, column 10
    LD (TextColumn),HL                         ; $736C: 22 0D A8
    LD A,$09                                   ; $736F: 3E 09  message 9: " GAME OVER"
    CALL PrintMessage                          ; $7371: CD D7 BA
    POP HL                                     ; $7374: E1
    RES 7,(HL)                                 ; $7375: CB BE  renderer back to the screen
    CALL BlitViewBitmap                        ; $7377: CD 98 73
    POP BC                                     ; $737A: C1
    DJNZ L_7356                                ; $737B: 10 D9
    CALL ClearViewBuffer                       ; $737D: CD 5F 74  blank view
    CALL BlitViewBitmap                        ; $7380: CD 98 73
    CALL ResetShipSlots                        ; $7383: CD 14 7C  free slots 1..7
    LD B,$32                                   ; $7386: 06 32  wait 50 frames
L_7388:
    HALT                                       ; $7388: 76
    DJNZ L_7388                                ; $7389: 10 FD
    XOR A                                      ; $738B: AF
    LD (ControlsLockedFlag),A                  ; $738C: 32 7C 70  controls unlocked
    LD (PlayerDeadFlag),A                      ; $738F: 32 7A 70  alive again
    LD (HyperspaceKeyLatch),A                  ; $7392: 32 39 7C  jump latch cleared
    JP RunTitleScreen                          ; $7395: C3 8F 71

; ============================================================================
; View buffer and cockpit display
; Blit and clear of the 4 KB view buffer at ViewBitmapBuffer, cockpit restore.
; ============================================================================

; VERIFIED: reads the reused $C000/$C800 view buffers, not the initial on-tape font/cockpit data.
; VERIFIED: Copy the 4 KB view buffer (screen layout of $4000..$4FFF, at $C000) to the
; top two screen thirds: even pixel lines of both thirds first, then odd lines.
; The bottom third (cockpit) is never written.
; Evidence: tools/check_routines.py screen/clear-view-buffer, screen/blit-view-bitmap,
; screen/restore-cockpit-test (every byte lands at buffer address - $8000).
BlitViewBitmap:
    LD DE,$4000                                ; $7398: 11 00 40
    LD HL,ViewBitmapBuffer                     ; $739B: 21 00 C0
    CALL BlitAlternateLines                    ; $739E: CD BD 73  top third, lines 0, 2, 4, 6
    LD DE,$4800                                ; $73A1: 11 00 48
    LD HL,ViewBitmapBufferSecondHalf           ; $73A4: 21 00 C8
    CALL BlitAlternateLines                    ; $73A7: CD BD 73  middle third, lines 0, 2, 4, 6
    LD DE,$4100                                ; $73AA: 11 00 41
    LD HL,ViewBitmapBuffer+$100                ; $73AD: 21 00 C1
    CALL BlitAlternateLines                    ; $73B0: CD BD 73  top third, lines 1, 3, 5, 7
    LD DE,$4900                                ; $73B3: 11 00 49
    LD HL,ViewBitmapBufferSecondHalf+$100      ; $73B6: 21 00 C9
    CALL BlitAlternateLines                    ; $73B9: CD BD 73  middle third, lines 1, 3, 5, 7
    RET                                        ; $73BC: C9

; VERIFIED: DE = screen line address, HL = DE + $8000: copy four pixel lines two apart
; (32 bytes each) for each of the 8 character rows of one screen third.
; The LDIs count down in C (reset to $FF per row), so B stays the row counter.
; Output (for the third-aligned entries used): B = 0, DE back at its entry value
; (E wraps after 8 rows), HL = DE + $8000.  Clobbers A, C.
BlitAlternateLines:
    LD B,$08                                   ; $73BD: 06 08  8 character rows
L_73BF:
    PUSH DE                                    ; $73BF: D5
    LD C,$FF                                   ; $73C0: 0E FF  LDI count in C; B stays the row count
    LD A,$04                                   ; $73C2: 3E 04  4 lines per row (every second)
L_73C4:
    PUSH DE                                    ; $73C4: D5
    LDI                                        ; $73C5: ED A0  32 LDIs: one pixel line
    LDI                                        ; $73C7: ED A0
    LDI                                        ; $73C9: ED A0
    LDI                                        ; $73CB: ED A0
    LDI                                        ; $73CD: ED A0
    LDI                                        ; $73CF: ED A0
    LDI                                        ; $73D1: ED A0
    LDI                                        ; $73D3: ED A0
    LDI                                        ; $73D5: ED A0
    LDI                                        ; $73D7: ED A0
    LDI                                        ; $73D9: ED A0
    LDI                                        ; $73DB: ED A0
    LDI                                        ; $73DD: ED A0
    LDI                                        ; $73DF: ED A0
    LDI                                        ; $73E1: ED A0
    LDI                                        ; $73E3: ED A0
    LDI                                        ; $73E5: ED A0
    LDI                                        ; $73E7: ED A0
    LDI                                        ; $73E9: ED A0
    LDI                                        ; $73EB: ED A0
    LDI                                        ; $73ED: ED A0
    LDI                                        ; $73EF: ED A0
    LDI                                        ; $73F1: ED A0
    LDI                                        ; $73F3: ED A0
    LDI                                        ; $73F5: ED A0
    LDI                                        ; $73F7: ED A0
    LDI                                        ; $73F9: ED A0
    LDI                                        ; $73FB: ED A0
    LDI                                        ; $73FD: ED A0
    LDI                                        ; $73FF: ED A0
    LDI                                        ; $7401: ED A0
    LDI                                        ; $7403: ED A0
    POP DE                                     ; $7405: D1
    INC D                                      ; $7406: 14  two pixel lines down
    INC D                                      ; $7407: 14
    LD H,D                                     ; $7408: 62
    SET 7,H                                    ; $7409: CB FC  buffer address = screen address + $8000
    LD L,E                                     ; $740B: 6B
    DEC A                                      ; $740C: 3D
    JP NZ,L_73C4                               ; $740D: C2 C4 73
    POP DE                                     ; $7410: D1
    LD A,E                                     ; $7411: 7B
    ADD A,$20                                  ; $7412: C6 20  next character row: +32
    LD E,A                                     ; $7414: 5F
    LD L,A                                     ; $7415: 6F
    LD H,D                                     ; $7416: 62
    SET 7,H                                    ; $7417: CB FC
    DJNZ L_73BF                                ; $7419: 10 A4
    RET                                        ; $741B: C9

; VERIFIED: Return at once unless screen byte $4000 is $FF.  ClearScreenAndFrame (full-screen page
; clear) draws a top line, so $FF there means a full-screen page is shown;
; cockpit views leave $00 (ClearViewBuffer).  Then clear key state (ClearLatchedKeys)
; and fall into ClearScreenAndDrawCockpit.
RestoreCockpitIfFullScreen:
    LD DE,$4000                                ; $741C: 11 00 40
    LD A,(DE)                                  ; $741F: 1A  ClearScreenAndFrame draws $FF here; views leave $00
    INC A                                      ; $7420: 3C
    RET NZ                                     ; $7421: C0
    CALL ClearLatchedKeys                      ; $7422: CD 09 7C  clear the latched key bytes

; VERIFIED: Clear the screen (ClearScreenAndFrame), black out attribute columns 0 and 31 of all 24
; rows, copy the cockpit bitmap and colours to the bottom third, then
; CockpitRestored.
ClearScreenAndDrawCockpit:
    CALL ClearScreenAndFrame                   ; $7425: CD 9E BC
    LD DE,$001F                                ; $7428: 11 1F 00  column 0 -> column 31
    LD B,$17                                   ; $742B: 06 17  23 row steps
    LD A,$00                                   ; $742D: 3E 00  black on black
    LD HL,$5800                                ; $742F: 21 00 58
    LD (HL),A                                  ; $7432: 77
L_7433:
    ADD HL,DE                                  ; $7433: 19
    LD (HL),A                                  ; $7434: 77
    INC HL                                     ; $7435: 23
    LD (HL),A                                  ; $7436: 77
    DJNZ L_7433                                ; $7437: 10 FA
    ADD HL,DE                                  ; $7439: 19  column 31 of row 23
    LD (HL),A                                  ; $743A: 77

; VERIFIED: restore 256x64 bitmap from CockpitBitmap to the bottom screen third.
RestoreCockpitBitmap:
    LD DE,ScreenCockpitBitmap                  ; $743B: 11 00 50
    LD HL,CockpitBitmap                        ; $743E: 21 00 C8  tape image or saved copy
    LD BC,CockpitBitmapSize                    ; $7441: 01 00 08
    LDIR                                       ; $7444: ED B0

; VERIFIED: restore 32x8 colour cells from the runtime attribute buffer.
RestoreCockpitAttributes:
    LD DE,ScreenCockpitAttributes              ; $7446: 11 00 5A
    LD HL,CockpitAttributesRuntime             ; $7449: 21 00 5B  mutable cockpit colours
    LD BC,CockpitAttributesSize                ; $744C: 01 00 01
    LDIR                                       ; $744F: ED B0

; Bitmap and attribute copies are complete; instrument updates follow.
; VERIFIED: If commander byte NovaMissionActive is set, FillViewAttributes recolours the view red (L=2).
; NovaMissionActive is NovaMissionActive (missions/p5-nova-mission).
; Then SaveScannerBackground (SaveScannerBackground) stores the clean scanner area of the freshly
; drawn cockpit in the backup buffer, which the contact plotter restores each frame.
CockpitRestored:
    LD A,(NovaMissionActive)                   ; $7451: 3A 43 A8  mission flag
    AND A                                      ; $7454: A7
    JR Z,L_745C                                ; $7455: 28 05
    LD L,$02                                   ; $7457: 2E 02
    CALL FillViewAttributes                    ; $7459: CD 87 92
L_745C:
    JP SaveScannerBackground                   ; $745C: C3 F2 8D  save the clean scanner area

; VERIFIED: Clear the 4 KB view buffer with the stack (interrupts off, SP saved in
; ViewClearSavedSP) and draw the view frame: the first and last 32 bytes become
; $00,$FF x30,$00 (top and bottom lines, rows y=0 and y=127) and all other
; rows $00,$80,0...,0,$01,$00 (side pixels at x=8 and x=247).  The frame is thus
; redrawn by every clear.  Interrupts are enabled again on return.
; Clobbers A, BC, DE, HL, IX.  Evidence: tools/check_routines.py screen/clear-view-buffer,
; screen/blit-view-bitmap, screen/restore-cockpit-test.
ClearViewBuffer:
    DI                                         ; $745F: F3
    LD (ViewClearSavedSP),SP                   ; $7460: ED 73 B0 74
    LD SP,ViewBitmapBuffer+$1000               ; $7464: 31 00 D0  stack fills the buffer downwards
    LD HL,$0000                                ; $7467: 21 00 00  row interior: zero words
    LD DE,$00FF                                ; $746A: 11 FF 00  pattern $00FF: right end of a line
    LD IX,$FF00                                ; $746D: DD 21 00 FF  pattern $FF00
    LD BC,$FFFF                                ; $7471: 01 FF FF  pattern $FFFF
    PUSH DE                                    ; $7474: D5  row 127, bytes 30..31
    LD A,$0E                                   ; $7475: 3E 0E  bottom row first: DE, 14 x BC, IX = 32 bytes
L_7477:
    PUSH BC                                    ; $7477: C5  bytes 2..29 = $FF
    DEC A                                      ; $7478: 3D
    JR NZ,L_7477                               ; $7479: 20 FC
    PUSH IX                                    ; $747B: DD E5  bytes 0..1 = $00,$FF
    LD E,$01                                   ; $747D: 1E 01  pattern $00/$01: right side pixel
    LD IX,$8000                                ; $747F: DD 21 00 80  pattern $8000: left side pixel
    LD B,$7E                                   ; $7483: 06 7E  126 middle rows
L_7485:
    PUSH DE                                    ; $7485: D5  one middle row, right end first
    PUSH HL                                    ; $7486: E5
    PUSH HL                                    ; $7487: E5
    PUSH HL                                    ; $7488: E5
    PUSH HL                                    ; $7489: E5
    PUSH HL                                    ; $748A: E5
    PUSH HL                                    ; $748B: E5
    PUSH HL                                    ; $748C: E5
    PUSH HL                                    ; $748D: E5
    PUSH HL                                    ; $748E: E5
    PUSH HL                                    ; $748F: E5
    PUSH HL                                    ; $7490: E5
    PUSH HL                                    ; $7491: E5
    PUSH HL                                    ; $7492: E5
    PUSH HL                                    ; $7493: E5
    PUSH IX                                    ; $7494: DD E5
    DJNZ L_7485                                ; $7496: 10 ED
    LD BC,$FFFF                                ; $7498: 01 FF FF
    LD E,$FF                                   ; $749B: 1E FF
    LD IX,$FF00                                ; $749D: DD 21 00 FF  top row ($C000): frame line
    PUSH DE                                    ; $74A1: D5  row 0, built like row 127
    LD A,$0E                                   ; $74A2: 3E 0E
L_74A4:
    PUSH BC                                    ; $74A4: C5
    DEC A                                      ; $74A5: 3D
    JR NZ,L_74A4                               ; $74A6: 20 FC
    PUSH IX                                    ; $74A8: DD E5
    LD SP,(ViewClearSavedSP)                   ; $74AA: ED 7B B0 74  back to the caller's stack
    EI                                         ; $74AE: FB
    RET                                        ; $74AF: C9

; VERIFIED: Stack pointer saved by ClearViewBuffer.
ViewClearSavedSP:
    defw $0000                                                                            ; $74B0

; VERIFIED: Stack pointer saved at startup (StartupAfterGraphicsCopy, also AdderStartup);
; EndGameWithMessage reloads it before restarting the title.
StartupStackPointer:
    defw $0000                                                                            ; $74B2

; VERIFIED: 9-byte work copy of the body being projected (x, y, z; same format as
; SunPosition), filled by DrawSunAndPlanet for ProjectBodyPosition.
ProjectionX:
    defb $00                                                                              ; $74B4 .  x fraction
ProjectionXWord:
    defb $00                                                                              ; $74B5 .  x word low
ProjectionXHigh:
    defb $00                                                                              ; $74B6 .  x word high, bit 7 sign (cleared in place when x is the depth)
ProjectionY:
    defb $00                                                                              ; $74B7 .  y fraction
ProjectionYWord:
    defb $00                                                                              ; $74B8 .  y word low
ProjectionYHigh:
    defb $00                                                                              ; $74B9 .  y word high, bit 7 sign
ProjectionZ:
    defb $00                                                                              ; $74BA .  z fraction
ProjectionZWord:
    defb $00                                                                              ; $74BB .  z word low
ProjectionZHigh:
    defb $00                                                                              ; $74BC .  z word high, bit 7 sign (cleared in place when z is the depth)

; VERIFIED: Sun radius while the expanding-sun effect runs (UpdateExpandingSun); 0 when
; inactive.  Cleared at game start and at the end of the hyperspace tunnel.
ExpandingSunRadius:
    defb $00                                                                              ; $74BD .

; ============================================================================
; Sun and planet
; Projection and drawing of the two large bodies, the expanding-sun effect,
; station dormancy and the cloak key.
; ============================================================================

; VERIFIED: Clear LargeSunFlag, copy SunPosition to ProjectionX and project it
; (ProjectBodyPosition); run UpdateExpandingSun; if the sun is in view draw it as a
; filled disc (DrawFilledCircle, nothing below radius 9) and set LargeSunFlag for a radius of 40
; or more, so the following UpdateObjects XOR-plots lines over it.  Then copy and project
; PlanetPosition and draw the planet as an outline circle (DrawCircleOutline, radius 9 or more).
; Called by the cockpit-view frame (not in witchspace) and by the last 11 launch frames.
; Evidence: tools/check_routines.py pipeline/project-body-position, circles/circle-renderer.
DrawSunAndPlanet:
    XOR A                                      ; $74BE: AF
    LD (LargeSunFlag),A                        ; $74BF: 32 7B 70  OR-plot lines unless the sun is large
    LD HL,SunPosition                          ; $74C2: 21 65 70  project the sun
    LD DE,ProjectionX                          ; $74C5: 11 B4 74
    LD BC,$0009                                ; $74C8: 01 09 00  9 bytes: x, y, z
    LDIR                                       ; $74CB: ED B0
    CALL ProjectBodyPosition                   ; $74CD: CD 1F 75
    PUSH AF                                    ; $74D0: F5  keep A over UpdateExpandingSun
    CALL UpdateExpandingSun                    ; $74D1: CD FA 74
    POP AF                                     ; $74D4: F1
    AND A                                      ; $74D5: A7
    JR Z,L_74E7                                ; $74D6: 28 0F  sun not in view
    CALL DrawFilledCircle                      ; $74D8: CD F0 7C  sun: filled disc
    LD A,(CircleRadius)                        ; $74DB: 3A 3D 7C
    CP $28                                     ; $74DE: FE 28  radius 40 or more
    JR C,L_74E7                                ; $74E0: 38 05
    LD A,$01                                   ; $74E2: 3E 01
    LD (LargeSunFlag),A                        ; $74E4: 32 7B 70  XOR-plot lines over the sun

; VERIFIED: Planet half of DrawSunAndPlanet.
L_74E7:
    LD HL,PlanetPosition                       ; $74E7: 21 6E 70  project the planet
    LD DE,ProjectionX                          ; $74EA: 11 B4 74
    LD BC,$0009                                ; $74ED: 01 09 00
    LDIR                                       ; $74F0: ED B0
    CALL ProjectBodyPosition                   ; $74F2: CD 1F 75
    AND A                                      ; $74F5: A7
    RET Z                                      ; $74F6: C8  planet not in view
    JP DrawCircleOutline                       ; $74F7: C3 FE 7C  planet: outline circle

; VERIFIED: Only while ExpandingSunActive is set: CabinTemperature += 1 and the sun radius grows by 2
; per call (starting from the radius just projected in CircleRadius); the result is
; stored in CircleRadius and ExpandingSunRadius.  Reaching 256 sets PlayerDeadFlag and
; leaves radius 0.  Called by DrawSunAndPlanet (even when the sun is out of view) and
; by the non-view flight frame, so the growth continues on every screen; L_7ACD
; clears ExpandingSunRadius after a hyperspace jump, restarting from the new sun.
; This is the supernova of the nova mission: ExpandingSunActive (ExpandingSunActive) is armed by
; ArmExpandingSun (missions/p5-nova-mission).
UpdateExpandingSun:
    LD A,(ExpandingSunActive)                  ; $74FA: 3A 7C A8  expanding sun armed?
    AND A                                      ; $74FD: A7
    RET Z                                      ; $74FE: C8
    LD A,(ExpandingSunRadius)                  ; $74FF: 3A BD 74
    AND A                                      ; $7502: A7
    JR NZ,L_7508                               ; $7503: 20 03  already expanding
    LD A,(CircleRadius)                        ; $7505: 3A 3D 7C  start from the projected radius
L_7508:
    LD HL,CabinTemperature                     ; $7508: 21 4C 70
    INC (HL)                                   ; $750B: 34  CabinTemperature += 1
    ADD A,$02                                  ; $750C: C6 02  radius += 2; 256 or more ends the game
    JR Z,L_7512                                ; $750E: 28 02  exactly 256: dead
    JR NC,L_7518                               ; $7510: 30 06  below 256: store
L_7512:
    LD A,$01                                   ; $7512: 3E 01  the sun engulfs the ship
    LD (PlayerDeadFlag),A                      ; $7514: 32 7A 70
    XOR A                                      ; $7517: AF  radius 0
L_7518:
    LD (CircleRadius),A                        ; $7518: 32 3D 7C
    LD (ExpandingSunRadius),A                  ; $751B: 32 BD 74  grown radius for the next call
    RET                                        ; $751E: C9

; VERIFIED: Perspective projection of ProjectionX..ProjectionZ for the current view
; (CurrentScreenId 0 front: depth +z; 1 rear: -z; 2 left: -x; 3 right: +x).
; Returns A=1 when in front of the viewer, with
;   CircleOffsetX = low byte of 256*|horizontal|/depth, CircleOffsetY = same for vertical;
;   CircleFlags bit 0 = right of centre, bit 1 = above centre, bit 2/bit 3 =
;   horizontal/vertical offset below 256 (clear: offset 256..511);
;   CircleRadius = radius $A000/depth word, 255 when the depth word is $00A0 or less.
; Returns A=0 when behind the viewer, when the depth word exceeds $A000 or when an
; offset reaches 512.  The depth coordinate's sign is cleared in place in ProjectionX..
; Offsets below 256 are within 2 of the exact quotient; for the 256..511 range see the
; NOTE at L_7746.
; Evidence: tools/check_routines.py pipeline/project-body-position,
; pipeline/p1-projection-offset-paths.
ProjectBodyPosition:
    EXX                                        ; $751F: D9
    LD BC,$0003                                ; $7520: 01 03 00  B' = flags, C' = 3: call counter
    EXX                                        ; $7523: D9
    LD A,(CurrentScreenId)                     ; $7524: 3A 41 70  view 0: front
    AND A                                      ; $7527: A7
    JP NZ,L_75D3                               ; $7528: C2 D3 75
    LD A,(ProjectionZHigh)                     ; $752B: 3A BC 74
    BIT 7,A                                    ; $752E: CB 7F  z negative: behind
    JP NZ,ProjectionNotVisible                 ; $7530: C2 66 77
    AND $7F                                    ; $7533: E6 7F
    LD (ProjectionZHigh),A                     ; $7535: 32 BC 74  depth made positive in place
    LD HL,(ProjectionZWord)                    ; $7538: 2A BB 74  DE = depth word (z)
    EX DE,HL                                   ; $753B: EB
    LD HL,(ProjectionXWord)                    ; $753C: 2A B5 74  HL = horizontal word (x)
    LD A,(ProjectionZ)                         ; $753F: 3A BA 74  B = depth fraction
    LD B,A                                     ; $7542: 47
    LD A,(ProjectionX)                         ; $7543: 3A B4 74  C = horizontal fraction
    LD C,A                                     ; $7546: 4F
    LD A,H                                     ; $7547: 7C
    BIT 7,A                                    ; $7548: CB 7F
    JR NZ,L_7550                               ; $754A: 20 04  x negative: left of centre
    EXX                                        ; $754C: D9
    SET 0,B                                    ; $754D: CB C0  bit 0: right of centre
    EXX                                        ; $754F: D9

; VERIFIED: Front/rear views: horizontal and vertical offsets, then radius.
L_7550:
    AND $7F                                    ; $7550: E6 7F  magnitude
    LD H,A                                     ; $7552: 67
    CALL ProjectCoordinate                     ; $7553: CD DC 76
    LD A,D                                     ; $7556: 7A
    LD (CircleOffsetX),A                       ; $7557: 32 3B 7C  horizontal offset
    LD HL,(ProjectionZWord)                    ; $755A: 2A BB 74
    EX DE,HL                                   ; $755D: EB
    LD HL,(ProjectionYWord)                    ; $755E: 2A B8 74  HL = vertical word (y)
    LD A,(ProjectionZ)                         ; $7561: 3A BA 74
    LD B,A                                     ; $7564: 47
    LD A,(ProjectionY)                         ; $7565: 3A B7 74
    LD C,A                                     ; $7568: 4F
    LD A,H                                     ; $7569: 7C
    BIT 7,A                                    ; $756A: CB 7F
    JR NZ,L_7572                               ; $756C: 20 04  y negative: below centre
    EXX                                        ; $756E: D9
    SET 1,B                                    ; $756F: CB C8  bit 1: above centre
    EXX                                        ; $7571: D9
L_7572:
    AND $7F                                    ; $7572: E6 7F
    LD H,A                                     ; $7574: 67
    CALL ProjectCoordinate                     ; $7575: CD DC 76
    LD A,D                                     ; $7578: 7A
    LD (CircleOffsetY),A                       ; $7579: 32 3A 7C  vertical offset
    EXX                                        ; $757C: D9
    LD A,B                                     ; $757D: 78
    EXX                                        ; $757E: D9
    LD (CircleFlags),A                         ; $757F: 32 3C 7C  side and range bits
    LD A,(ProjectionZHigh)                     ; $7582: 3A BC 74  depth 65536 or more?
    AND A                                      ; $7585: A7
    JR NZ,L_7597                               ; $7586: 20 0F
    LD HL,$A000                                ; $7588: 21 00 A0  radius = $A000/depth
    LD DE,(ProjectionZ)                        ; $758B: ED 5B BA 74  DE = depth low word and fraction
    SBC HL,DE                                  ; $758F: ED 52
