    BIT 6,(HL)                                 ; $77EB: CB 76
    RET Z                                      ; $77ED: C8
    LD HL,CloakingDeviceActive                 ; $77EE: 21 0C A8
    DEC (HL)                                   ; $77F1: 35  1 -> 0: switch off
    JR Z,L_780A                                ; $77F2: 28 16  off: normal colours
    LD A,(EnergyBank3)                         ; $77F4: 3A 58 70  needs EnergyBank3 >= $28
    CP $28                                     ; $77F7: FE 28
    RET C                                      ; $77F9: D8  too little energy: left nonzero
    LD A,$01                                   ; $77FA: 3E 01
    LD (HL),A                                  ; $77FC: 77  cloak on
    LD HL,InitialRuntimeState+InstanceBehaviour ; $77FD: 21 69 60
    RES 2,(HL)                                 ; $7800: CB 96  station no longer hostile
    XOR A                                      ; $7802: AF
    LD (SharedHostilityAlert),A                ; $7803: 32 14 DA  shared alert cleared
L_7806:
    LD L,$0F                                   ; $7806: 2E 0F  blue paper, white ink
    JR L_780C                                  ; $7808: 18 02
L_780A:
    LD L,$07                                   ; $780A: 2E 07  white ink on black
L_780C:
    JP FillViewAttributes                      ; $780C: C3 87 92

; INFERRED: Unreferenced code: LD A,(NovaMissionActive) / AND A falls into L_7813 (red view colours
; when set).  No static, pointer or runtime reference was found; decoded
; because it ends exactly at the verified instruction L_7813.
L_780F:
    LD A,(NovaMissionActive)                   ; $780F: 3A 43 A8
    AND A                                      ; $7812: A7
L_7813:
    LD L,$02                                   ; $7813: 2E 02  red view colours
    JR NZ,L_780C                               ; $7815: 20 F5
    RET                                        ; $7817: C9

; INFERRED: Unreferenced code: if CloakingDeviceActive is set jump to L_7806 (blue view colours).
; No static, pointer or runtime reference was found; decoded because its JR
; lands on a verified instruction and it ends exactly at ArmExpandingSun.
L_7818:
    LD A,(CloakingDeviceActive)                ; $7818: 3A 0C A8
    AND A                                      ; $781B: A7
    JR NZ,L_7806                               ; $781C: 20 E8
    RET                                        ; $781E: C9

; VERIFIED: Called at launch.  If commander byte NovaMissionActive is set: ExpandingSunActive = 1, which
; enables UpdateExpandingSun, and the view is coloured red (FillViewAttributes, L=2).
ArmExpandingSun:
    LD A,(NovaMissionActive)                   ; $781F: 3A 43 A8
    AND A                                      ; $7822: A7
    RET Z                                      ; $7823: C8  no mission flag: nothing
    LD A,$01                                   ; $7824: 3E 01
    LD (ExpandingSunActive),A                  ; $7826: 32 7C A8  arm UpdateExpandingSun
    JR L_7813                                  ; $7829: 18 E8  red view, return

; VERIFIED: Docking: act on commander byte InvasionMissionState: 1 or 2 -> OfferSpecialMission (Y/N mission offer;
; 'Y' stores 3), 4 -> EndGameWithMessage with message 212 " THARGON" (boarded),
; 5 -> AwardHighestHonour (reward: adds 1 to CombatScoreHigh, sets bit 3 of CommanderFlags, clears InvasionMissionState);
; 0, 3 and 6..255 do nothing.  Called by DockIntoStation before CheckPirateGameOver.
; Evidence: tools/check_routines.py missions/p1-mission-state-on-docking.
; InvasionMissionState is InvasionMissionState (missions/p5-invasion-mission).
CheckMissionStateOnDocking:
    LD A,(InvasionMissionState)                ; $782B: 3A 71 A8
    DEC A                                      ; $782E: 3D  state 1?
    JR Z,L_7832                                ; $782F: 28 01
    DEC A                                      ; $7831: 3D  state 2?
L_7832:
    JP Z,OfferSpecialMission                   ; $7832: CA 19 D2  offer the mission (Y/N)
    SUB $03                                    ; $7835: D6 03  state 5?
    JP Z,AwardHighestHonour                    ; $7837: CA 43 D2  reward
    INC A                                      ; $783A: 3C  state 4?
    LD A,$D4                                   ; $783B: 3E D4  message 212: " THARGON"
    JR Z,EndGameWithMessage                    ; $783D: 28 09  boarded by Thargons
    RET                                        ; $783F: C9  other states: nothing

; VERIFIED: Docking: if bit 7 of station byte +$1D was cleared (L_D812 does this),
; end the game with message 13 " PIRATE".
CheckPirateGameOver:
    LD HL,InitialRuntimeState+InstanceRoll     ; $7840: 21 65 60
    BIT 7,(HL)                                 ; $7843: CB 7E
    RET NZ                                     ; $7845: C0  still set: no boarding
    LD A,$0D                                   ; $7846: 3E 0D  message 13: " PIRATE"

; VERIFIED: A = message: ShowShipBoardedScreen prints it, then "S" and "THEY SHOW NO MERCY...".
; Then front view, restore the cockpit, reload StartupStackPointer and
; restart at RunTitleScreen.
EndGameWithMessage:
    CALL ShowShipBoardedScreen                 ; $7848: CD EC D1
    XOR A                                      ; $784B: AF
    LD (CurrentScreenId),A                     ; $784C: 32 41 70  front view
    CALL RestoreCockpitIfFullScreen            ; $784F: CD 1C 74
    LD SP,(StartupStackPointer)                ; $7852: ED 7B B2 74  discard all callers
    JP RunTitleScreen                          ; $7856: C3 8F 71  title, then a new game

