L_7863:
    LD A,(HL)                                  ; $7863: 7E
    DEC HL                                     ; $7864: 2B
    CP (HL)                                    ; $7865: BE
    JR Z,L_7874                                ; $7866: 28 0C  unchanged: skip
    LD (HL),A                                  ; $7868: 77  remember the drawn value
