    INC HL                                     ; $7877: 23
    INC HL                                     ; $7878: 23
    EXX                                        ; $7879: D9
    DEC C                                      ; $787A: 0D
    EXX                                        ; $787B: D9
    JR NZ,L_7863                               ; $787C: 20 E5
