    LD (GaugeIndicatorMode),A                  ; $7880: 32 A3 78
    EXX                                        ; $7883: D9
    LD C,$02                                   ; $7884: 0E 02  2 indicators
    EXX                                        ; $7886: D9
L_7887:
    LD A,(HL)                                  ; $7887: 7E
    DEC HL                                     ; $7888: 2B
    CP (HL)                                    ; $7889: BE
    JR Z,L_7894                                ; $788A: 28 08
    LD (HL),A                                  ; $788C: 77
    PUSH HL                                    ; $788D: E5
    PUSH DE                                    ; $788E: D5
    CALL DrawIndicatorGauge                    ; $788F: CD C0 78
    POP DE                                     ; $7892: D1
    POP HL                                     ; $7893: E1
L_7894:
    INC DE                                     ; $7894: 13
    INC DE                                     ; $7895: 13
    INC HL                                     ; $7896: 23
    INC HL                                     ; $7897: 23
    INC HL                                     ; $7898: 23
    EXX                                        ; $7899: D9
    DEC C                                      ; $789A: 0D
    EXX                                        ; $789B: D9
    JR NZ,L_7887                               ; $789C: 20 E9
    XOR A                                      ; $789E: AF  bar mode again
    LD (GaugeIndicatorMode),A                  ; $789F: 32 A3 78
    RET                                        ; $78A2: C9

; VERIFIED: 1 while DrawGauges draws the two indicator gauges, 0 for bars.
GaugeIndicatorMode:
    defb $00                                                                              ; $78A3 .

; VERIFIED: Screen address of pixel line 1 of each gauge (bottom third, five lines
; high, 40 pixels wide), in GaugeDisplayTable order.  The 14th entry ($51E3,
; the row of the missile icons) is never read.
GaugeScreenAddresses:
    defw $5123                                                                            ; $78A4  FS bar, row 17 column 3
    defw $5143                                                                            ; $78A6  AS bar, row 18 column 3
    defw $5163                                                                            ; $78A8  FU bar, row 19 column 3
    defw $5183                                                                            ; $78AA  CT bar, row 20 column 3
    defw $51A3                                                                            ; $78AC  LT bar, row 21 column 3
    defw $51C3                                                                            ; $78AE  AL bar, row 22 column 3
    defw $5138                                                                            ; $78B0  SP bar, row 17 column 24
    defw $5198                                                                            ; $78B2  energy bank 1, row 20 column 24
    defw $51B8                                                                            ; $78B4  energy bank 2, row 21 column 24
    defw $51D8                                                                            ; $78B6  energy bank 3, row 22 column 24
    defw $51F8                                                                            ; $78B8  energy bank 4, row 23 column 24
    defw $5158                                                                            ; $78BA  RL indicator, row 18 column 24
    defw $5178                                                                            ; $78BC  DC indicator, row 19 column 24
