; DrawBarGauge stores $FF, DrawIndicatorGauge $03.
defc GaugeEndMask = L_78EC + 1 ; byte inside instruction at $78EC
    LD C,$FF                                   ; $78EC: 0E FF  patched: $FF bars, $03 indicators
    LD B,A                                     ; $78EE: 47
    LD A,D                                     ; $78EF: 7A
    JR Z,L_7902                                ; $78F0: 28 10  multiple of 8: end byte = mask
    LD A,(GaugeIndicatorMode)                  ; $78F2: 3A A3 78
    DEC A                                      ; $78F5: 3D
