    XOR A                                      ; $78F9: AF  bar: n leading pixels
L_78FA:
    SCF                                        ; $78FA: 37
    RRA                                        ; $78FB: 1F
    DJNZ L_78FA                                ; $78FC: 10 FC
L_78FE:
    LD C,A                                     ; $78FE: 4F  C = end byte
    LD A,D                                     ; $78FF: 7A
    ADD A,$08                                  ; $7900: C6 08  round up to whole bytes
L_7902:
    AND $F8                                    ; $7902: E6 F8
    SRL A                                      ; $7904: CB 3F
    SRL A                                      ; $7906: CB 3F
    SRL A                                      ; $7908: CB 3F
    LD B,A                                     ; $790A: 47  B = bytes used (1..5)
    LD A,$05                                   ; $790B: 3E 05
    SUB B                                      ; $790D: 90
    LD D,A                                     ; $790E: 57  D = 5 - bytes used
    JR Z,L_7935                                ; $790F: 28 24  end byte is the fifth
    DEC B                                      ; $7911: 05
    JR Z,L_794C                                ; $7912: 28 38  only the first byte used
    LD E,B                                     ; $7914: 58  E = full bytes before the end byte
L_7915:
    PUSH HL                                    ; $7915: E5
L_7916:
; VERIFIED: Operand of LD A,n: fill byte before the end byte ($FF bars, $00 indicators).
defc GaugeFillByte = L_7916 + 1 ; byte inside instruction at $7916
    LD A,$FF                                   ; $7916: 3E FF  patched: $FF bars, $00 indicators
L_7918:
    LD (HL),A                                  ; $7918: 77
    INC L                                      ; $7919: 2C
    DJNZ L_7918                                ; $791A: 10 FC
    CALL StoreGaugeEndByte                     ; $791C: CD 86 79  end byte
    INC L                                      ; $791F: 2C
    LD B,D                                     ; $7920: 42  bytes after the end byte
    DEC B                                      ; $7921: 05
    JR Z,L_7929                                ; $7922: 28 05
    XOR A                                      ; $7924: AF  are cleared
L_7925:
    LD (HL),A                                  ; $7925: 77
    INC L                                      ; $7926: 2C
    DJNZ L_7925                                ; $7927: 10 FC
L_7929:
    LD (HL),$01                                ; $7929: 36 01  right border pixel
    INC L                                      ; $792B: 2C
    POP HL                                     ; $792C: E1
    EXX                                        ; $792D: D9
    DEC B                                      ; $792E: 05
    EXX                                        ; $792F: D9
    RET Z                                      ; $7930: C8
    INC H                                      ; $7931: 24  next pixel line
    LD B,E                                     ; $7932: 43
    JR L_7915                                  ; $7933: 18 E0
L_7935:
    DEC B                                      ; $7935: 05
    LD E,B                                     ; $7936: 58
L_7937:
    PUSH HL                                    ; $7937: E5
L_7938:
; VERIFIED: Same as GaugeFillByte for a gauge whose end byte is the fifth byte.
defc GaugeFillByteFull = L_7938 + 1 ; byte inside instruction at $7938
    LD A,$FF                                   ; $7938: 3E FF  patched: $FF bars, $00 indicators
L_793A:
    LD (HL),A                                  ; $793A: 77
    INC L                                      ; $793B: 2C
    DJNZ L_793A                                ; $793C: 10 FC
    SET 0,C                                    ; $793E: CB C1  border pixel in the end byte
    CALL StoreGaugeEndByte                     ; $7940: CD 86 79
    POP HL                                     ; $7943: E1
    EXX                                        ; $7944: D9
    DEC B                                      ; $7945: 05
    EXX                                        ; $7946: D9
    RET Z                                      ; $7947: C8
    INC H                                      ; $7948: 24  next pixel line
    LD B,E                                     ; $7949: 43
    JR L_7937                                  ; $794A: 18 EB

; VERIFIED: Length 1..8 (only the first of the five bytes is used): on each of the five pixel
; lines store end byte C in byte 1, clear bytes 2..4 and write $01 (border pixel)
; into byte 5.  StoreGaugeEndByte is not used here.
; Evidence: tools/check_routines.py controls/p1-gauge-all-lengths.
L_794C:
    LD B,$05                                   ; $794C: 06 05
L_794E:
    LD A,C                                     ; $794E: 79  end byte in byte 1
    PUSH HL                                    ; $794F: E5
    LD (HL),A                                  ; $7950: 77
    INC L                                      ; $7951: 2C
    XOR A                                      ; $7952: AF  bytes 2..4 clear
    LD (HL),A                                  ; $7953: 77
    INC L                                      ; $7954: 2C
    LD (HL),A                                  ; $7955: 77
    INC L                                      ; $7956: 2C
    LD (HL),A                                  ; $7957: 77
    INC L                                      ; $7958: 2C
    OR $01                                     ; $7959: F6 01  byte 5: border pixel
    LD (HL),A                                  ; $795B: 77
    POP HL                                     ; $795C: E1
    INC H                                      ; $795D: 24  next pixel line
    DJNZ L_794E                                ; $795E: 10 EE
    RET                                        ; $7960: C9

; VERIFIED: Zero length (empty gauge, HL = its screen address): on all five pixel lines clear
; bytes 1..4 and write $01 into byte 5, keeping the right border pixel.
L_7961:
    LD B,$05                                   ; $7961: 06 05
L_7963:
    XOR A                                      ; $7963: AF  bytes 1..4 clear
    PUSH HL                                    ; $7964: E5
    LD (HL),A                                  ; $7965: 77
    INC L                                      ; $7966: 2C
    LD (HL),A                                  ; $7967: 77
    INC L                                      ; $7968: 2C
    LD (HL),A                                  ; $7969: 77
    INC L                                      ; $796A: 2C
    LD (HL),A                                  ; $796B: 77
    INC L                                      ; $796C: 2C
    OR $01                                     ; $796D: F6 01  byte 5: border pixel
    LD (HL),A                                  ; $796F: 77
    POP HL                                     ; $7970: E1
    INC H                                      ; $7971: 24  next pixel line
    DJNZ L_7963                                ; $7972: 10 EF
    RET                                        ; $7974: C9

; VERIFIED: Indicator with position mod 8 = r (1..7, in B): marker byte $80 for r = 1 (the
; other pixel is bit 0 of the previous byte, see StoreGaugeEndByte), otherwise $C0
; shifted right r-2 times, i.e. pixels r-2 and r-1 of the end byte.  A multiple of 8
; does not come here: it uses GaugeEndMask $03 (pixels 6 and 7).
L_7975:
    LD A,$80                                   ; $7975: 3E 80  r = 1: bit 7 only
    DEC B                                      ; $7977: 05
    JR Z,L_7983                                ; $7978: 28 09
    SCF                                        ; $797A: 37  r = 2: $C0
    RRA                                        ; $797B: 1F
    DEC B                                      ; $797C: 05
    JR Z,L_7983                                ; $797D: 28 04
L_797F:
    SRL A                                      ; $797F: CB 3F  r > 2: shift into place
    DJNZ L_797F                                ; $7981: 10 FC
L_7983:
    JP L_78FE                                  ; $7983: C3 FE 78

; VERIFIED: Store end byte C.  In indicator mode a marker byte of $80/$81 also sets bit 0
; of the previous byte, so the two-pixel marker can straddle two bytes.
StoreGaugeEndByte:
    LD (HL),C                                  ; $7986: 71
    LD A,(GaugeIndicatorMode)                  ; $7987: 3A A3 78
    DEC A                                      ; $798A: 3D
    RET NZ                                     ; $798B: C0  bars: done
    LD A,C                                     ; $798C: 79
    AND $FE                                    ; $798D: E6 FE  marker $80/$81: pixel before it
    CP $80                                     ; $798F: FE 80
    JR Z,L_7994                                ; $7991: 28 01
    RET                                        ; $7993: C9
L_7994:
    DEC L                                      ; $7994: 2D  previous byte, bit 0
    LD (HL),$01                                ; $7995: 36 01
    INC L                                      ; $7997: 2C
    RET                                        ; $7998: C9

; ============================================================================
; Tunnel animations
; Hyperspace arrival rings and the station launch/docking tunnel.
; ============================================================================

; VERIFIED: Print the view name/messages (PrintViewTitleAndMessages), then if a tunnel animation is active
; (JumpTunnelMode) run one step: while TunnelLoopActive is set, the whole first part runs inside
; this call; afterwards each call draws one frame and counts it down.
; The tunnel is a set of concentric outline circles centred in the view (rings of
; radius 256/distance).  Callers: DockIntoStation, LaunchFromStation.
StepTunnelAnimation:
    CALL PrintViewTitleAndMessages             ; $7999: CD 4C D4
    LD A,(JumpTunnelMode)                      ; $799C: 3A 0A A8
    AND A                                      ; $799F: A7
    RET Z                                      ; $79A0: C8  no tunnel running
    JR L_79E3                                  ; $79A1: 18 40

; VERIFIED: Cockpit-view frame after a hyperspace jump (TunnelLoopActive set by FinishHyperspaceArrival): reset
; inputs, clear all ship slots, in witchspace remove the station and launch a
; Thargoid group (DispatchShipEvent 1), then run the 66-frame ring tunnel
; with 16 rings (HyperspaceRingDistances) and finish at FinishHyperspaceTunnel.
; With TunnelFrameLimit = 1 all 66 frames run inside this one call.
PlayHyperspaceArrival:
    LD A,(TunnelLoopActive)                    ; $79A3: 3A 0B A8  set by FinishHyperspaceArrival
    AND A                                      ; $79A6: A7
    RET Z                                      ; $79A7: C8
    CALL ResetFlightInputs                     ; $79A8: CD FF 7B  reset inputs
    CALL ResetShipSlots                        ; $79AB: CD 14 7C  clear all ship slots
    LD A,(WitchspaceFlag)                      ; $79AE: 3A 61 70
    AND A                                      ; $79B1: A7
    JR Z,L_79C0                                ; $79B2: 28 0C
    LD IX,InitialRuntimeState                  ; $79B4: DD 21 48 60
    XOR A                                      ; $79B8: AF
    LD (IX+$22),A                              ; $79B9: DD 77 22  station removed (energy 0)
    INC A                                      ; $79BC: 3C
    CALL DispatchShipEvent                     ; $79BD: CD CA F2  event 1: Thargoid group
L_79C0:
    CALL ClearViewBuffer                       ; $79C0: CD 5F 74  blank view
    CALL BlitViewBitmap                        ; $79C3: CD 98 73
    LD A,$42                                   ; $79C6: 3E 42  66 frames
    LD (TunnelFrameCounter),A                  ; $79C8: 32 DF 7A
    CALL PlayFallingNoiseSweep                 ; $79CB: CD 46 90  hyperspace noise
    LD HL,HyperspaceRingDistances              ; $79CE: 21 E0 7A  TunnelRingTablePointer = hyperspace rings
    LD (TunnelRingTablePointer),HL             ; $79D1: 22 07 7A
    LD A,$10                                   ; $79D4: 3E 10  16 rings
    LD (TunnelRingCount),A                     ; $79D6: 32 DD 7A
    LD A,$01                                   ; $79D9: 3E 01  TunnelFrameLimit = 1
    LD (TunnelFrameLimit),A                    ; $79DB: 32 33 7A
    LD A,FinishHyperspaceTunnel-(TunnelExitOffset+1) ; $79DE: 3E 15  TunnelExitOffset -> FinishHyperspaceTunnel
    LD (TunnelExitOffset),A                    ; $79E0: 32 38 7A

; VERIFIED: Select the ring-loop exit: TunnelLoopActive set -> blit and count frames inside this
; call (L_7A2B); clear -> one frame per call (CountTunnelFrame).  Centre the rings
; (CircleOffsetY/CircleOffsetX = 0, CircleFlags = $0F).
L_79E3:
    LD A,(TunnelLoopActive)                    ; $79E3: 3A 0B A8  first part inside this call?
    AND A                                      ; $79E6: A7
    JR NZ,L_79F0                               ; $79E7: 20 07
    LD A,CountTunnelFrame-(TunnelRingsDoneOffset+1) ; $79E9: 3E 1E  TunnelRingsDoneOffset -> CountTunnelFrame
    LD (TunnelRingsDoneOffset),A               ; $79EB: 32 25 7A
    JR L_79F5                                  ; $79EE: 18 05
L_79F0:
    LD A,L_7A2B-(TunnelRingsDoneOffset+1)      ; $79F0: 3E 05  TunnelRingsDoneOffset -> L_7A2B
    LD (TunnelRingsDoneOffset),A               ; $79F2: 32 25 7A
L_79F5:
    LD A,$0F                                   ; $79F5: 3E 0F  ring centre: both offsets positive, < 256
    LD (CircleFlags),A                         ; $79F7: 32 3C 7C
    LD HL,$0000                                ; $79FA: 21 00 00
    LD (CircleOffsetY),HL                      ; $79FD: 22 3A 7C  both centre offsets 0
    LD A,(TunnelRingCount)                     ; $7A00: 3A DD 7A
    LD (TunnelRingsLeft),A                     ; $7A03: 32 DE 7A  rings to draw this frame

; VERIFIED: Frame start: HL = ring distance table (patched operand).
L_7A06:
; VERIFIED: Operand of LD HL,nn: HyperspaceRingDistances (PlayHyperspaceArrival) or
; StationTunnelRingDistances (StartStationTunnel).
defc TunnelRingTablePointer = L_7A06 + 1 ; byte inside instruction at $7A06
    LD HL,HyperspaceRingDistances              ; $7A06: 21 E0 7A  patched: ring distance table

; VERIFIED: Ring loop: decrement each distance d and draw a ring of radius 256/d
; (DivideFractionABToC) with DrawCircleOutlineAnySize when the radius is 4 or more.
L_7A09:
    LD A,(HL)                                  ; $7A09: 7E
    DEC A                                      ; $7A0A: 3D  ring moves closer
    LD (HL),A                                  ; $7A0B: 77
    INC HL                                     ; $7A0C: 23
    LD B,A                                     ; $7A0D: 47
    LD A,$01                                   ; $7A0E: 3E 01  radius = 256/distance
    CALL DivideFractionABToC                   ; $7A10: CD B9 7A
    LD A,C                                     ; $7A13: 79
    CP $04                                     ; $7A14: FE 04  draw rings of radius 4 or more
    JR C,L_7A20                                ; $7A16: 38 08
    LD (CircleRadius),A                        ; $7A18: 32 3D 7C  ring radius
    PUSH HL                                    ; $7A1B: E5
    CALL DrawCircleOutlineAnySize              ; $7A1C: CD 04 7D  centred outline ring
    POP HL                                     ; $7A1F: E1
L_7A20:
    LD A,(TunnelRingsLeft)                     ; $7A20: 3A DE 7A
    DEC A                                      ; $7A23: 3D
L_7A24:
; VERIFIED: Displacement of JR Z: L_7A2B (5) while TunnelLoopActive is set, CountTunnelFrame ($1E) otherwise.
defc TunnelRingsDoneOffset = L_7A24 + 1 ; byte inside instruction at $7A24
    JR Z,L_7A2B                                ; $7A24: 28 05  patched displacement
    LD (TunnelRingsLeft),A                     ; $7A26: 32 DE 7A
    JR L_7A09                                  ; $7A29: 18 DE

; VERIFIED: In-call frame end: blit, count TunnelFrameCounter down and leave through
; the patched JR C when it falls below TunnelFrameLimit.
L_7A2B:
    CALL BlitViewBitmap                        ; $7A2B: CD 98 73  show the frame
    LD A,(TunnelFrameCounter)                  ; $7A2E: 3A DF 7A
    DEC A                                      ; $7A31: 3D
L_7A32:
; VERIFIED: Operand of CP n: 1 for hyperspace, $30 for the station tunnel.
defc TunnelFrameLimit = L_7A32 + 1 ; byte inside instruction at $7A32
    CP $30                                     ; $7A32: FE 30  patched: TunnelFrameLimit
    LD (TunnelFrameCounter),A                  ; $7A34: 32 DF 7A
L_7A37:
; VERIFIED: Displacement of JR C: FinishHyperspaceTunnel ($15), FinishLaunchTunnelLoop
; ($32, the on-tape value) or FinishDockingTunnelLoop ($38).
defc TunnelExitOffset = L_7A37 + 1 ; byte inside instruction at $7A37
    JR C,FinishLaunchTunnelLoop                ; $7A37: 38 32  patched displacement: TunnelExitOffset
    LD A,(TunnelRingCount)                     ; $7A39: 3A DD 7A
    LD (TunnelRingsLeft),A                     ; $7A3C: 32 DE 7A
    CALL ClearViewBuffer                       ; $7A3F: CD 5F 74  next frame
    JR L_7A06                                  ; $7A42: 18 C2

; VERIFIED: Per-call frame end: decrement TunnelFrameCounter; at zero finish the
; station tunnel (L_7A76).
CountTunnelFrame:
    LD A,(TunnelFrameCounter)                  ; $7A44: 3A DF 7A
    DEC A                                      ; $7A47: 3D
    LD (TunnelFrameCounter),A                  ; $7A48: 32 DF 7A
    JR Z,L_7A76                                ; $7A4B: 28 29
    RET                                        ; $7A4D: C9

; VERIFIED: Clear TunnelLoopActive and JumpTunnelMode, add 66 back to all 16 ring distances (SUB $BE),
; clear and blit the view, then L_7ACD.
FinishHyperspaceTunnel:
    XOR A                                      ; $7A4E: AF
    LD (TunnelLoopActive),A                    ; $7A4F: 32 0B A8  tunnel over
    LD (JumpTunnelMode),A                      ; $7A52: 32 0A A8
    LD A,$10                                   ; $7A55: 3E 10  16 distances
    LD B,A                                     ; $7A57: 47
    LD HL,HyperspaceRingDistances              ; $7A58: 21 E0 7A
L_7A5B:
    LD A,(HL)                                  ; $7A5B: 7E
    SUB $BE                                    ; $7A5C: D6 BE  restore: +66
    LD (HL),A                                  ; $7A5E: 77
    INC HL                                     ; $7A5F: 23
    DJNZ L_7A5B                                ; $7A60: 10 F9
    CALL ClearViewBuffer                       ; $7A62: CD 5F 74  blank view
    CALL BlitViewBitmap                        ; $7A65: CD 98 73
    JP L_7ACD                                  ; $7A68: C3 CD 7A

; VERIFIED: Launch: clear TunnelLoopActive and continue with SeedLaunchDust.
FinishLaunchTunnelLoop:
    XOR A                                      ; $7A6B: AF
    LD (TunnelLoopActive),A                    ; $7A6C: 32 0B A8  one frame per call from now
    JR SeedLaunchDust                          ; $7A6F: 18 17  seed the stardust, return

; VERIFIED: Docking: clear TunnelLoopActive and return.  Reached only through the patched JR C
; (displacement $38 stored by DockIntoStation); executed in the runtime traces
; (write to TunnelLoopActive from $7A72).
FinishDockingTunnelLoop:
    XOR A                                      ; $7A71: AF
    LD (TunnelLoopActive),A                    ; $7A72: 32 0B A8  one frame per call from now
    RET                                        ; $7A75: C9

; VERIFIED: Station tunnel finished: clear JumpTunnelMode and add 64 back to the 8 station ring
; distances (SUB $C0).
L_7A76:
    XOR A                                      ; $7A76: AF
    LD (JumpTunnelMode),A                      ; $7A77: 32 0A A8  station tunnel over
    LD A,$08                                   ; $7A7A: 3E 08  8 distances
    LD B,A                                     ; $7A7C: 47
    LD HL,StationTunnelRingDistances           ; $7A7D: 21 F0 7A
L_7A80:
    LD A,(HL)                                  ; $7A80: 7E
    SUB $C0                                    ; $7A81: D6 C0  restore: +64
    LD (HL),A                                  ; $7A83: 77
    INC HL                                     ; $7A84: 23
    DJNZ L_7A80                                ; $7A85: 10 F9
    RET                                        ; $7A87: C9

; VERIFIED: After the first 17 launch-tunnel frames: PlayerSpeed = 7 for the remaining tunnel
; frames; temporarily patch RespawnDustFront (masks $83, RET at DustRespawnExit) and create all 16
; stardust particles of DustParticleRecords (the records MoveAndPlotDust moves and plots) from
; AuxRandomSeed, each within 3 units of the centre and deep ahead (z >= $80), then
; restore the original bytes.
; Evidence: tools/check_routines.py dust/launch-dust-respawn, dust/stardust-update.
SeedLaunchDust:
    LD A,$83                                   ; $7A88: 3E 83  patch RespawnDustFront operands: masks $83
    LD (L_A348),A                              ; $7A8A: 32 48 A3
    LD (L_A34D),A                              ; $7A8D: 32 4D A3
    LD A,$C9                                   ; $7A90: 3E C9  RET instead of JP NextDustParticle
    LD (DustRespawnExit),A                     ; $7A92: 32 ED A3
    LD A,$07                                   ; $7A95: 3E 07  stardust speed for the rest
    LD (PlayerSpeed),A                         ; $7A97: 32 44 70
    LD HL,(AuxRandomSeed)                      ; $7A9A: 2A 63 70
    LD DE,DustParticleRecords                  ; $7A9D: 11 6C A4  stardust table, 5 bytes per particle
    LD B,$10                                   ; $7AA0: 06 10  16 particles
L_7AA2:
    PUSH BC                                    ; $7AA2: C5
    CALL RespawnDustFront                      ; $7AA3: CD 47 A3  one particle near the centre
    POP BC                                     ; $7AA6: C1
    DJNZ L_7AA2                                ; $7AA7: 10 F9
    LD A,$BF                                   ; $7AA9: 3E BF  restore the original operands
    LD (L_A348),A                              ; $7AAB: 32 48 A3
    LD A,$9F                                   ; $7AAE: 3E 9F
    LD (L_A34D),A                              ; $7AB0: 32 4D A3
    LD A,$C3                                   ; $7AB3: 3E C3  restore JP NextDustParticle
    LD (DustRespawnExit),A                     ; $7AB5: 32 ED A3
    RET                                        ; $7AB8: C9

; VERIFIED: C = A*256/B for A < B.  Evidence: tools/check_routines.py maths/fraction-dividers (all A < B).
DivideFractionABToC:
    LD C,$FE                                   ; $7AB9: 0E FE  sentinel: stop after 8 bits
L_7ABB:
    ADD A,A                                    ; $7ABB: 87
    JR C,L_7AC6                                ; $7ABC: 38 08
    CP B                                       ; $7ABE: B8
    JR NC,L_7AC6                               ; $7ABF: 30 05
    SLA C                                      ; $7AC1: CB 21
    RET NC                                     ; $7AC3: D0
    JR L_7ABB                                  ; $7AC4: 18 F5
L_7AC6:
    SUB B                                      ; $7AC6: 90
    SCF                                        ; $7AC7: 37
    RL C                                       ; $7AC8: CB 11
    RET NC                                     ; $7ACA: D0
    JR L_7ABB                                  ; $7ACB: 18 EE

; VERIFIED: End of the hyperspace tunnel: white view colours unless NovaMissionActive is set (then the
; red view stays), clear ExpandingSunRadius (an armed expansion restarts from the new
; sun's projected radius) and continue in PlayRisingNoiseSweep (sound), which returns to the
; caller of PlayHyperspaceArrival.
L_7ACD:
    LD A,(NovaMissionActive)                   ; $7ACD: 3A 43 A8
    AND A                                      ; $7AD0: A7
    LD L,$07                                   ; $7AD1: 2E 07  white on black
    CALL Z,FillViewAttributes                  ; $7AD3: CC 87 92  mission flag set: colours kept
    XOR A                                      ; $7AD6: AF
    LD (ExpandingSunRadius),A                  ; $7AD7: 32 BD 74  expansion restarts at the new sun
    JP PlayRisingNoiseSweep                    ; $7ADA: C3 3B 90  arrival noise

; VERIFIED: Rings per frame: 16 hyperspace, 8 station tunnel.
TunnelRingCount:
