; VERIFIED: Not in witchspace: set up the 8-ring station tunnel and JumpTunnelMode = TunnelLoopActive = 1,
; then launch (LaunchFromStation) when docked, otherwise dock (DockIntoStation).
; Called from L_8ED1 (docked, launch key) and reached from DockWithStation.
StartStationTunnel:
    LD A,(WitchspaceFlag)                      ; $7AF8: 3A 61 70
    AND A                                      ; $7AFB: A7
    RET NZ                                     ; $7AFC: C0  witchspace: no station
    LD HL,StationTunnelRingDistances           ; $7AFD: 21 F0 7A  TunnelRingTablePointer = station rings
    LD (TunnelRingTablePointer),HL             ; $7B00: 22 07 7A
    LD A,$08                                   ; $7B03: 3E 08  8 rings
    LD (TunnelRingCount),A                     ; $7B05: 32 DD 7A
    LD A,$30                                   ; $7B08: 3E 30  TunnelFrameLimit = $30
    LD (TunnelFrameLimit),A                    ; $7B0A: 32 33 7A
    LD A,$40                                   ; $7B0D: 3E 40  $40 frames in total
    LD (TunnelFrameCounter),A                  ; $7B0F: 32 DF 7A
    LD HL,$0101                                ; $7B12: 21 01 01  JumpTunnelMode = TunnelLoopActive = 1
    LD (JumpTunnelMode),HL                     ; $7B15: 22 0A A8
    LD A,(FlightCondition)                     ; $7B18: 3A 62 70
    AND A                                      ; $7B1B: A7
    JR Z,LaunchFromStation                     ; $7B1C: 28 4A  docked: launch

; VERIFIED: Docking tunnel: speed 12, no roll/pitch, ECM off, controls locked, then the
; 64-frame tunnel (17 frames in the first StepTunnelAnimation call, 47 calls).
; Afterwards FlightCondition = 0 (docked), run the docking checks (CheckMissionStateOnDocking,
; CheckPirateGameOver) and show screen 7 (status) via CallScreenHandler.
DockIntoStation:
    LD A,FinishDockingTunnelLoop-(TunnelExitOffset+1) ; $7B1E: 3E 38  TunnelExitOffset -> FinishDockingTunnelLoop
    LD (TunnelExitOffset),A                    ; $7B20: 32 38 7A
    LD A,$0C                                   ; $7B23: 3E 0C  docking speed
    LD (PlayerSpeed),A                         ; $7B25: 32 44 70
    XOR A                                      ; $7B28: AF
    LD (PlayerPitch),A                         ; $7B29: 32 43 70
    LD (PlayerRoll),A                          ; $7B2C: 32 42 70
    LD (EcmTimer),A                            ; $7B2F: 32 16 DA  ECM countdown stopped
    INC A                                      ; $7B32: 3C
    LD (ControlsLockedFlag),A                  ; $7B33: 32 7C 70  ControlsLockedFlag = 1
    LD HL,EcmFitted                            ; $7B36: 21 47 A8
    RES 7,(HL)                                 ; $7B39: CB BE  player ECM inactive (bit 7)
    CALL ClearViewBuffer                       ; $7B3B: CD 5F 74
    CALL StepTunnelAnimation                   ; $7B3E: CD 99 79  first 17 frames in one call
    LD B,$2F                                   ; $7B41: 06 2F  47 more frames
L_7B43:
    PUSH BC                                    ; $7B43: C5
    CALL ClearViewBuffer                       ; $7B44: CD 5F 74
    CALL StepTunnelAnimation                   ; $7B47: CD 99 79  one frame
    CALL BlitViewBitmap                        ; $7B4A: CD 98 73
    POP BC                                     ; $7B4D: C1
    DJNZ L_7B43                                ; $7B4E: 10 F3
    CALL PlayLongNoiseSweep                    ; $7B50: CD 30 90  docking noise
    XOR A                                      ; $7B53: AF
    LD (FlightCondition),A                     ; $7B54: 32 62 70  docked
    CALL SaveCleanCockpit                      ; $7B57: CD 42 8F  save the cockpit before the page
    CALL ResetFlightInputs                     ; $7B5A: CD FF 7B  controls neutral, speed input 12
    CALL CheckMissionStateOnDocking            ; $7B5D: CD 2B 78  mission state
    CALL CheckPirateGameOver                   ; $7B60: CD 40 78  boarded by pirates?
    LD A,$07                                   ; $7B63: 3E 07  screen 7: status (ShowCommanderStatus)
    JP CallScreenHandler                       ; $7B65: C3 02 8F

; VERIFIED: FlightCondition = 4 (green), front view, station active, cloak off; reset
; shields/energy (PrepareShipForLaunch), ArmExpandingSun; planet ahead at z = $0180, sun z
; mirrored, station slot 0 just behind the ship (z fraction $F0, negative,
; unit orientation, energy $F0); clear other slots; draw gauges; then the
; 64-frame tunnel (17 in the first call, then 36 + 11 calls, the last 11 also
; moving and drawing sun and planet).  Falls into ResetFlightInputs.
LaunchFromStation:
    LD A,$04                                   ; $7B68: 3E 04  FlightCondition: green
    LD (FlightCondition),A                     ; $7B6A: 32 62 70
    CALL PlayLongNoiseSweep                    ; $7B6D: CD 30 90  launch noise
    XOR A                                      ; $7B70: AF
    LD (DockingContactFlag),A                  ; $7B71: 32 15 DA  no pending station contact
    LD (CurrentScreenId),A                     ; $7B74: 32 41 70  front view
    LD (StationDormantFlag),A                  ; $7B77: 32 78 70  station active
    LD (CloakingDeviceActive),A                ; $7B7A: 32 0C A8  cloak off
    LD A,FinishLaunchTunnelLoop-(TunnelExitOffset+1) ; $7B7D: 3E 32  TunnelExitOffset -> FinishLaunchTunnelLoop
    LD (TunnelExitOffset),A                    ; $7B7F: 32 38 7A
    CALL RestoreCockpitIfFullScreen            ; $7B82: CD 1C 74
    CALL PrepareShipForLaunch                  ; $7B85: CD 46 9A  shields, energy, gauge values
    CALL ArmExpandingSun                       ; $7B88: CD 1F 78
    LD HL,PlanetPosition                       ; $7B8B: 21 6E 70
    LD B,$07                                   ; $7B8E: 06 07
    CALL ClearBytes                            ; $7B90: CD 0E 7C  planet x, y and z fraction = 0
    LD (HL),$80                                ; $7B93: 36 80  planet z = $0180
    INC HL                                     ; $7B95: 23
    LD (HL),$01                                ; $7B96: 36 01
    LD A,(SunZHigh)                            ; $7B98: 3A 6D 70
    XOR $80                                    ; $7B9B: EE 80  sun z sign flipped
    LD (SunZHigh),A                            ; $7B9D: 32 6D 70
    LD HL,InitialRuntimeState                  ; $7BA0: 21 48 60
    LD B,$1B                                   ; $7BA3: 06 1B
    CALL ClearBytes                            ; $7BA5: CD 0E 7C  station position and orientation = 0
    LD IX,InitialRuntimeState                  ; $7BA8: DD 21 48 60
    LD A,$F0                                   ; $7BAC: 3E F0  station z fraction $F0
    LD (IX+$06),A                              ; $7BAE: DD 77 06
    LD A,$80                                   ; $7BB1: 3E 80  z sign: behind the ship
    LD (IX+$08),A                              ; $7BB3: DD 77 08
    DEC A                                      ; $7BB6: 3D  $7F: unit orientation
    LD (IX+$0E),A                              ; $7BB7: DD 77 0E
    LD (IX+$12),A                              ; $7BBA: DD 77 12
    LD (IX+$16),A                              ; $7BBD: DD 77 16
    LD A,$F0                                   ; $7BC0: 3E F0  station energy
    LD (IX+$22),A                              ; $7BC2: DD 77 22
    CALL ResetShipSlots                        ; $7BC5: CD 14 7C  free slots 1..7
    CALL DrawGauges                            ; $7BC8: CD 59 78  show the reset gauges
    CALL ClearViewBuffer                       ; $7BCB: CD 5F 74
    CALL StepTunnelAnimation                   ; $7BCE: CD 99 79  first 17 frames, then SeedLaunchDust
    LD B,$24                                   ; $7BD1: 06 24  36 frames
L_7BD3:
    PUSH BC                                    ; $7BD3: C5
    CALL ClearViewBuffer                       ; $7BD4: CD 5F 74
    CALL UpdateDust                            ; $7BD7: CD 74 9E  stardust at speed 7
    CALL StepTunnelAnimation                   ; $7BDA: CD 99 79
    CALL BlitViewBitmap                        ; $7BDD: CD 98 73
    POP BC                                     ; $7BE0: C1
    DJNZ L_7BD3                                ; $7BE1: 10 F0
    LD B,$0B                                   ; $7BE3: 06 0B  11 frames with sun and planet
L_7BE5:
    PUSH BC                                    ; $7BE5: C5
    CALL ClearViewBuffer                       ; $7BE6: CD 5F 74
    CALL MoveSunAndPlanet                      ; $7BE9: CD 8F 77  sun and planet move
    CALL UpdateDust                            ; $7BEC: CD 74 9E
    CALL StepTunnelAnimation                   ; $7BEF: CD 99 79
    CALL DrawSunAndPlanet                      ; $7BF2: CD BE 74  and are drawn
    CALL BlitViewBitmap                        ; $7BF5: CD 98 73
    POP BC                                     ; $7BF8: C1
    DJNZ L_7BE5                                ; $7BF9: 10 EA
    XOR A                                      ; $7BFB: AF
    LD (ControlsLockedFlag),A                  ; $7BFC: 32 7C 70  controls unlocked

; VERIFIED: Clear the interrupt input bytes RollControl..SpeedControl and set L_FF0D (high byte of
; SpeedControl) to 12, so the next ReadFlightControls gives speed 12 with no roll or
; pitch; then clear the key state KeyFlagsScreens..KeyFlagsChart (ClearLatchedKeys).
; Output (from ClearLatchedKeys/ClearBytes): A = 0, B = 0, HL = LastKeyCode.
ResetFlightInputs:
    LD B,$05                                   ; $7BFF: 06 05
    LD HL,RollControl                          ; $7C01: 21 08 FF  roll and pitch words, speed low byte
    CALL ClearBytes                            ; $7C04: CD 0E 7C
    LD (HL),$0C                                ; $7C07: 36 0C  speed high byte (SpeedControl+1) = 12

; ============================================================================
; Workspace clearing and commander template copy
; Small helpers: zero a byte range, free the ship slots, copy the JAMESON
; template into the active commander record.
; ============================================================================

; VERIFIED: Zero the five latched key-state bytes KeyFlagsScreens..KeyFlagsChart (state bytes 0..4
; of KeyActionTable) through ClearBytes; the same effect as ClearKeyFlags.
; Also reached by falling through from ResetFlightInputs, which first zeroes the roll and
; pitch words and the low byte of SpeedControl and sets its high byte to 12.
; Out: A = 0, B = 0, HL = KeyFlagsChart + 1.
; Evidence: instruction semantics; callers RestoreCockpitIfFullScreen+6 and the jump at $8F1E
; after every screen handler call; runtime: executed.
ClearLatchedKeys:
    LD B,$05                                   ; $7C09: 06 05
    LD HL,KeyFlagsScreens                      ; $7C0B: 21 0E FC  5 bytes KeyFlagsScreens..KeyFlagsChart

; VERIFIED: Store zero in B bytes from HL upwards (B=0 clears 256 bytes).
; In: HL = first byte, B = count.
; Out: HL = first byte after the range, A = 0, B = 0.  Flags changed.
; Evidence: instruction semantics; tools/check_routines.py maths/half-chord-root.
ClearBytes:
    XOR A                                      ; $7C0E: AF
L_7C0F:
    LD (HL),A                                  ; $7C0F: 77
    INC HL                                     ; $7C10: 23
    DJNZ L_7C0F                                ; $7C11: 10 FC
    RET                                        ; $7C13: C9

; VERIFIED: Free instance slots 1..7 and clear the station's hostility.
; Clears bit 2 (hostile) of +$21 in slot 0 and SharedHostilityAlert, and writes 0 to
; byte +$22 of slots 1..7 (a zero +$22 marks a free slot, see FindFreeShipSlot).
; Slot 0 (the station) keeps its other bytes.
; Out: A = 0, IX = slot 7, B = 0, DE = 39.
; Callers: the game-over sequence (L_7356+45), hyperspace arrival
; (PlayHyperspaceArrival+8), the launch (LaunchFromStation+93) and the Torus jump key
; handler (HandleTorusJumpKey+41).
; Evidence: instruction semantics; caller code.
ResetShipSlots:
    LD IX,InitialRuntimeState                  ; $7C14: DD 21 48 60  IX = slot 0 (the station)
    RES 2,(IX+$21)                             ; $7C18: DD CB 21 96  slot 0 (station): clear hostile bit
    XOR A                                      ; $7C1C: AF
    LD (SharedHostilityAlert),A                ; $7C1D: 32 14 DA  no shared hostility alert
    LD DE,InstanceSize                         ; $7C20: 11 27 00  39 = instance slot size
    LD B,$07                                   ; $7C23: 06 07  slots 1..7
L_7C25:
    ADD IX,DE                                  ; $7C25: DD 19
    LD (IX+$22),A                              ; $7C27: DD 77 22  +$22 = 0 marks the slot free
    DJNZ L_7C25                                ; $7C2A: 10 F9
    RET                                        ; $7C2C: C9

; VERIFIED: Copy the 102-byte restart snapshot CommanderTemplateBuffer to ActiveCommanderRecord (the
; first 102 bytes of the 104-byte tape record).  The snapshot holds JAMESON at power-on and
; is replaced by the active record after every successful tape load or save
; (CopyCommanderToTemplate), so a new game restarts from the last loaded or saved commander.
; Callers: InitialiseCommander+3 (new game) and ReportTapeLoadingError+5 (a failed load
; restores the record).
; Out: HL and DE advanced past both records, BC = 0.
; Evidence: LDIR operands; caller code; writers of CommanderTemplateBuffer ($D3E2).
CopyCommanderTemplate:
    LD HL,CommanderTemplateBuffer              ; $7C2D: 21 10 A9  restart snapshot (JAMESON until a load/save)
    LD DE,ActiveCommanderRecord                ; $7C30: 11 16 A8  first 102 bytes of the tape record
    LD BC,CommanderTemplateBufferEnd-CommanderTemplateBuffer ; $7C33: 01 66 00  102 commander bytes
    LDIR                                       ; $7C36: ED B0
    RET                                        ; $7C38: C9

; ============================================================================
; Hyperspace key latch and circle renderer workspace
; HyperspaceKeyLatch, then the parameters and work bytes of the circle/disc
; renderer DrawCircle.
; ============================================================================

; VERIFIED: Set to 1 by CheckHyperspaceKeys as soon as it consumes a hyperspace key bit
; (KeyFlagsViews bit 4 H or bit 5 G), before it tests anything else: also when the jump is
; refused (countdown already running, docked, galactic hyperdrive missing, target out of
; range or the current system itself).  While nonzero CheckDocking returns at once, so
; neither station contact (DockingContactFlag) nor the docking computer key docks the ship.
; Cleared only on arrival (FinishHyperspaceArrival) and by the game-over restart at L_7388.
; So a refused hyperspace key press disables docking until the next jump.
; Evidence: tools/check_routines.py missions/p2-hyperspace-key-latch; 48K emulator run
; (docking computer key ignored after H was pressed with the current system selected,
; honoured without the H press).
HyperspaceKeyLatch:
    defb $00                                                                              ; $7C39 .

; VERIFIED: Circle parameter: vertical distance of the centre from the centre row of the area
; (row 64 in the view, row 96 for DrawScreenCircle); CircleFlags bit 1 gives the side.
; Written by the planet/sun projection (L_7572, L_764C), L_79F5, DrawScreenCircle and
; DrawFlaggedObjectDiscs.  Evidence: tools/check_routines.py circles/circle-renderer.
CircleOffsetY:
    defb $00                                                                              ; $7C3A .

; VERIFIED: Circle parameter: horizontal distance of the centre from column 128; CircleFlags bit 0
; gives the side.  Evidence: tools/check_routines.py circles/circle-renderer.
CircleOffsetX:
    defb $00                                                                              ; $7C3B .

; VERIFIED: Circle flags.  Bit 0 set: centre x = 128 + CircleOffsetX, clear: 128 - offset.
; Bit 1 set: centre row = centre - CircleOffsetY (above), clear: below.
; Bits 2 (x) and 3 (y) are bit 8 of the offset, inverted: set = the offset byte is the whole
; distance; clear = the distance is 256 + the byte.  With a clear bit DrawCircle treats the
; centre as beyond that side (bit 2) or top/bottom (bit 3) edge and returns at once when the
; byte is at least the half size ($78 / $40): a radius <= 255 cannot reach the view then.
; ProjectCoordinate sets bits 2/3 when the projection quotient is below 1 (|coord| < z).
; DrawScreenCircle and RecordExplosionPosition store $0C + side bits; L_79F5 stores $0F.
; Evidence: tools/check_routines.py circles/circle-renderer (bits 0/1, all four sides) and
; circles/p2-circle-offset-bit8 (clear bits 2/3: discs and outlines centred 256 + byte away).
CircleFlags:
    defb $0F                                                                              ; $7C3C .

; VERIFIED: Circle radius in pixels.  DrawFilledCircle and DrawCircleOutline draw nothing for a
; radius < 9; DrawCircleOutlineAnySize has no limit.
; Evidence: tools/check_routines.py circles/circle-renderer.
CircleRadius:
    defb $64                                                                              ; $7C3D d

; VERIFIED: Working copy of CircleOffsetY made by DrawCircle (word store with CircleWorkOffsetX).
; The clipping cases replace it with the distance beyond the view edge (offset - $40).
; Read through BC by StartMidpointAtRadius and StartMidpointAtFarEdge.
CircleWorkOffsetY:
    defb $00                                                                              ; $7C3E .

; VERIFIED: Working copy of CircleOffsetX.  The clipping cases store offset - $78 (distance beyond
; the side edge) or restore offset + $78.  Read as B by the span set-ups.
CircleWorkOffsetX:
    defb $00                                                                              ; $7C3F .

; VERIFIED: Screen row of the circle centre computed by DrawCircle (may lie outside the view).
; The case at L_7F5F replaces it with the nearest view edge row (0 or $7F).
CircleCentreY:
    defb $00                                                                              ; $7C40 .

; VERIFIED: Pixel column of the circle centre computed by DrawCircle.
; Evidence: tools/check_routines.py circles/circle-renderer.
CircleCentreX:
    defb $00                                                                              ; $7C41 .

; VERIFIED: ComputeHalfChord result saved by the clipping cases: the half chord where the circle
; meets a view edge, used as a row count and as the midpoint start value.
CircleHalfChord:
    defb $00                                                                              ; $7C42 .

; VERIFIED: Saved SP while SP is repurposed: the span loops fill bytes with PUSH, and the patch
; loops of DrawScreenCircle walk CirclePatchTargets with POP.
; Also used by the outline span code (L_86B0, L_8758, L_8850).
CircleSavedStackPointer:
    defw $0000                                                                            ; $7C43

; VERIFIED: Word D*D - A*A (- carry) stored by ComputeHalfChord and reloaded on every iteration.
HalfChordRadicand:
    defw $0000                                                                            ; $7C45

; VERIFIED: Temporary copy of B, the left end mask built by LocateSpanLeftEnd: LocateSpanRightEnd
; saves it here before the ROM address call and restores it at its end (fill mode) or in
; its outline tail at L_862B.  Evidence: instruction semantics;
; tools/check_routines.py circles/p2-span-end-locators (B preserved, mask stored here).
SavedLeftEndMask:
    defb $00                                                                              ; $7C47 .

; VERIFIED: Row step of the span loops: 1 = downwards (INC H), 0 = upwards (DEC H).  Set by the six
; DrawCircleRows dispatchers; also selects which buffer limit (top or bottom) is checked.
CircleRowDirection:
    defb $00                                                                              ; $7C48 .

; VERIFIED: Renderer style: 1 = outline circle (set by DrawCircleOutlineAnySize), 0 = filled disc
; (set by DrawFilledCircle).  Every dispatcher jumps to the outline code (L_8640, L_866E,
; DrawCircleLeftArc, DrawCirclePairedArcs, DrawCircleRightArc) when nonzero, otherwise
; to the fill code in this range.
; Evidence: tools/check_routines.py circles/circle-renderer.
CircleOutlineFlag:
    defb $00                                                                              ; $7C49 .

; VERIFIED: Number of bytes (32) patched by the two loops of DrawScreenCircle: the entry count of
; CirclePatchTargets and the length of both value tables (see the assertions).
CirclePatchCount:
    defb $20                                                                              ; $7C4A  

; ============================================================================
; Circle and filled-disc renderer
; Midpoint circle drawn row by row into the 256x128 view buffer (SET 7,H turns a
; ROM screen address $40xx..$4Fxx into $C0xx..$CFxx).  CircleOutlineFlag selects
; the outline code (L_8640, L_866E and the arc routines DrawCircleLeftArc, DrawCirclePairedArcs,
; DrawCircleRightArc) or the filled spans here.  The view is drawn between x 8 and 247
; (half width $78) and rows 0..127.
; ============================================================================

; VERIFIED: Draw circle rows downwards whose right end is clipped at the right edge.
; Saves AF, sets the midpoint state HL' = 0, D' = 0, B' = $FF, CircleRowDirection = 1, then
; jumps to DrawCircleLeftArc (outline: left end pixel only) or FillDiscRowsRightClipped.
; In: HL = address of the start row's right end byte, E = low byte of the left end,
; B = left end mask, C = right end mask, C' = -x and E' = y of the midpoint state.
; The span code returns to this dispatcher's caller with AF restored (every exit ends with
; POP AF; RET), so a CALL Z / CALL NZ pair after a flag test runs exactly one dispatcher.
; Main and alternate BC, DE, HL are changed.
DrawCircleRowsDownRightClipped:
    PUSH AF                                    ; $7C4B: F5  restored by every exit of the span code
    EXX                                        ; $7C4C: D9
    LD HL,$0000                                ; $7C4D: 21 00 00  HL' = 0: midpoint error term
    LD D,H                                     ; $7C50: 54  D' = 0: DE' = midpoint y (E')
    LD B,$FF                                   ; $7C51: 06 FF  BC' = $FFxx: negative x counter
    EXX                                        ; $7C53: D9
    LD A,$01                                   ; $7C54: 3E 01  rows downwards
    LD (CircleRowDirection),A                  ; $7C56: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7C59: 3A 49 7C
    AND A                                      ; $7C5C: A7
    JP NZ,DrawCircleLeftArc                    ; $7C5D: C2 9C 86  outline: left end pixel only
    JP FillDiscRowsRightClipped                ; $7C60: C3 31 83  filled: spans clipped at the right edge

; VERIFIED: As DrawCircleRowsDownRightClipped, but CircleRowDirection = 0 (rows upwards).
DrawCircleRowsUpRightClipped:
    PUSH AF                                    ; $7C63: F5
    EXX                                        ; $7C64: D9
    LD HL,$0000                                ; $7C65: 21 00 00
    LD D,H                                     ; $7C68: 54
    LD B,$FF                                   ; $7C69: 06 FF
    EXX                                        ; $7C6B: D9
    XOR A                                      ; $7C6C: AF  rows upwards
    LD (CircleRowDirection),A                  ; $7C6D: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7C70: 3A 49 7C
    AND A                                      ; $7C73: A7
    JP NZ,DrawCircleLeftArc                    ; $7C74: C2 9C 86  outline: left end pixel only
    JP FillDiscRowsRightClipped                ; $7C77: C3 31 83  filled: spans clipped at the right edge

; VERIFIED: Draw circle rows downwards whose left end is clipped at the left edge.
; Same set-up as DrawCircleRowsDownRightClipped, then DrawCircleRightArc (outline: right end pixel
; only) or FillDiscRowsLeftClipped.
DrawCircleRowsDownLeftClipped:
    PUSH AF                                    ; $7C7A: F5
    EXX                                        ; $7C7B: D9
    LD HL,$0000                                ; $7C7C: 21 00 00
    LD D,H                                     ; $7C7F: 54
    LD B,$FF                                   ; $7C80: 06 FF
    EXX                                        ; $7C82: D9
    LD A,$01                                   ; $7C83: 3E 01  rows downwards
    LD (CircleRowDirection),A                  ; $7C85: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7C88: 3A 49 7C
    AND A                                      ; $7C8B: A7
    JP NZ,DrawCircleRightArc                   ; $7C8C: C2 3C 88  outline: right end pixel only
    JP FillDiscRowsLeftClipped                 ; $7C8F: C3 28 82  filled: spans clipped at the left edge

; VERIFIED: As DrawCircleRowsDownLeftClipped, but rows upwards.
DrawCircleRowsUpLeftClipped:
    PUSH AF                                    ; $7C92: F5
    EXX                                        ; $7C93: D9
    LD HL,$0000                                ; $7C94: 21 00 00
    LD D,H                                     ; $7C97: 54
    LD B,$FF                                   ; $7C98: 06 FF
    EXX                                        ; $7C9A: D9
    XOR A                                      ; $7C9B: AF  rows upwards
    LD (CircleRowDirection),A                  ; $7C9C: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7C9F: 3A 49 7C
    AND A                                      ; $7CA2: A7
    JP NZ,DrawCircleRightArc                   ; $7CA3: C2 3C 88  outline: right end pixel only
    JP FillDiscRowsLeftClipped                 ; $7CA6: C3 28 82  filled: spans clipped at the left edge

; VERIFIED: Draw circle rows downwards with both ends inside the view.
; Same set-up as above, then DrawCirclePairedArcs (outline: both end pixels) or FillDiscRows.
DrawCircleRowsDown:
    PUSH AF                                    ; $7CA9: F5
    EXX                                        ; $7CAA: D9
    LD HL,$0000                                ; $7CAB: 21 00 00
    LD D,H                                     ; $7CAE: 54
    LD B,$FF                                   ; $7CAF: 06 FF
    EXX                                        ; $7CB1: D9
    LD A,$01                                   ; $7CB2: 3E 01  rows downwards
    LD (CircleRowDirection),A                  ; $7CB4: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7CB7: 3A 49 7C
    AND A                                      ; $7CBA: A7
    JP NZ,DrawCirclePairedArcs                 ; $7CBB: C2 40 87  outline: both end pixels
    JP FillDiscRows                            ; $7CBE: C3 17 81  filled: both ends masked

; VERIFIED: As DrawCircleRowsDown, but rows upwards.
DrawCircleRowsUp:
    PUSH AF                                    ; $7CC1: F5
    EXX                                        ; $7CC2: D9
    LD HL,$0000                                ; $7CC3: 21 00 00
    LD D,H                                     ; $7CC6: 54
    LD B,$FF                                   ; $7CC7: 06 FF
    EXX                                        ; $7CC9: D9
    XOR A                                      ; $7CCA: AF  rows upwards
    LD (CircleRowDirection),A                  ; $7CCB: 32 48 7C
    LD A,(CircleOutlineFlag)                   ; $7CCE: 3A 49 7C
    AND A                                      ; $7CD1: A7
    JP NZ,DrawCirclePairedArcs                 ; $7CD2: C2 40 87  outline: both end pixels
    JP FillDiscRows                            ; $7CD5: C3 17 81  filled: both ends masked

; VERIFIED: Rows where the circle covers the whole view width, upwards: A = first row, B = count.
; Outline mode: L_8640 only moves HL up B rows; fill mode: FillViewRowsUp fills them.
; Out: HL = address in the row after the block (column 31).  AF, BC, DE preserved.
; When the block reaches the buffer edge, H is left at $BF (up) or $D0 (down); the span
; loops called next then return at once.
FillCircleRowsUp:
    LD C,A                                     ; $7CD8: 4F  keep the start row
    LD A,(CircleOutlineFlag)                   ; $7CD9: 3A 49 7C
    AND A                                      ; $7CDC: A7
    LD A,C                                     ; $7CDD: 79
    JP NZ,L_8640                               ; $7CDE: C2 40 86  outline: only move HL up B rows
    JP FillViewRowsUp                          ; $7CE1: C3 57 80  filled: $FF over x 8..247 of B rows

; VERIFIED: As FillCircleRowsUp, downwards (L_866E outline, FillViewRowsDown fill).
FillCircleRowsDown:
    LD C,A                                     ; $7CE4: 4F  keep the start row
    LD A,(CircleOutlineFlag)                   ; $7CE5: 3A 49 7C
    AND A                                      ; $7CE8: A7
    LD A,C                                     ; $7CE9: 79
    JP NZ,L_866E                               ; $7CEA: C2 6E 86  outline: only move HL down B rows
    JP FillViewRowsDown                        ; $7CED: C3 A2 80  filled: $FF over x 8..247 of B rows

; VERIFIED: Draw a filled disc into the view buffer from CircleOffsetY/X, CircleFlags and
; CircleRadius, clipped to x 8..247 and rows 0..127.  Returns at once if radius < 9.
; Sets CircleOutlineFlag = 0, runs DrawCircle with interrupts disabled (the fill loops use
; SP as a PUSH pointer), then EI.  Pixels are ORed in; the interior bytes are set to $FF.
; Callers: DrawSunAndPlanet+26 (the sun, projected from SunPosition) and
; DrawFlaggedObjectDiscs.
; Evidence: tools/check_routines.py circles/circle-renderer (discs, full-width fill, edge
; clipping).
DrawFilledCircle:
    LD A,(CircleRadius)                        ; $7CF0: 3A 3D 7C
    CP $09                                     ; $7CF3: FE 09  radius < 9: nothing drawn
    RET C                                      ; $7CF5: D8
    DI                                         ; $7CF6: F3  the fill loops use SP as a PUSH pointer
    XOR A                                      ; $7CF7: AF
    LD (CircleOutlineFlag),A                   ; $7CF8: 32 49 7C  CircleOutlineFlag = 0: filled disc
    JP L_7D09                                  ; $7CFB: C3 09 7D

; VERIFIED: Draw an outline circle from the circle parameters; returns at once if radius < 9.
; Falls into DrawCircleOutlineAnySize.  Callers: the jump at L_74E7+16 (the planet,
; projected from PlanetPosition) and DrawScreenCircle.
; Evidence: tools/check_routines.py circles/circle-renderer; runtime: flight views.
DrawCircleOutline:
    LD A,(CircleRadius)                        ; $7CFE: 3A 3D 7C
    CP $09                                     ; $7D01: FE 09
    RET C                                      ; $7D03: D8

; VERIFIED: Draw an outline circle without the radius check: CircleOutlineFlag = 1, DrawCircle, EI.
; Caller: L_7A09+19 (concentric rings centred in the view, CircleFlags = $0F).
DrawCircleOutlineAnySize:
    LD A,$01                                   ; $7D04: 3E 01
    LD (CircleOutlineFlag),A                   ; $7D06: 32 49 7C  CircleOutlineFlag = 1: outline

; VERIFIED: Common tail of the circle entries: CALL DrawCircle, EI, RET.
L_7D09:
    CALL DrawCircle                            ; $7D09: CD 0E 7D
    EI                                         ; $7D0C: FB  interrupts on again
    RET                                        ; $7D0D: C9

; VERIFIED: Circle renderer.  In: CircleOffsetY/X, CircleFlags, CircleRadius, CircleOutlineFlag.
; Computes CircleCentreY = $40 -/+ dy and CircleCentreX = $80 +/- dx (the $40 and $78
; limits are patched by DrawScreenCircle), copies the offsets to CircleWorkOffsetY/X and
; selects a clipping case from dy < $40, dx < $78 and CircleFlags bits 2/3:
; L_7D56 centre inside, L_7D6B beyond a side edge, L_7D7E above/below, L_7DAE diagonal.
; A clear bit 2/3 adds 256 to that offset (see CircleFlags).
; Cases that cannot reach the view return early.  All registers and alternates change.
; Evidence: tools/check_routines.py circles/circle-renderer; runtime: flight views,
; launch/hyperspace rings.
DrawCircle:
    LD BC,(CircleOffsetY)                      ; $7D0E: ED 4B 3A 7C  C = dy, B = dx
    LD (CircleWorkOffsetY),BC                  ; $7D12: ED 43 3E 7C  working copies of the offsets
    LD DE,(CircleFlags)                        ; $7D16: ED 5B 3C 7C  E = CircleFlags, D = CircleRadius
L_7D1A:
defc L_7D1B = L_7D1A + 1 ; byte inside instruction at $7D1A
    LD A,$40                                   ; $7D1A: 3E 40  SMC: centre row $40 (view) / $60 (DrawScreenCircle)
    BIT 1,E                                    ; $7D1C: CB 4B  bit 1: centre above the centre row
    JR NZ,L_7D22                               ; $7D1E: 20 02
    ADD A,C                                    ; $7D20: 81  below: + 2*dy, then - dy
    ADD A,C                                    ; $7D21: 81
L_7D22:
    SUB C                                      ; $7D22: 91
    LD (CircleCentreY),A                       ; $7D23: 32 40 7C  centre row, 8-bit (may lie outside the view)
    LD A,$80                                   ; $7D26: 3E 80  centre column 128
    BIT 0,E                                    ; $7D28: CB 43  bit 0: centre right of column 128
    JR Z,L_7D2E                                ; $7D2A: 28 02
    ADD A,B                                    ; $7D2C: 80  right: + 2*dx, then - dx
    ADD A,B                                    ; $7D2D: 80
L_7D2E:
    SUB B                                      ; $7D2E: 90
    LD (CircleCentreX),A                       ; $7D2F: 32 41 7C  centre column, 8-bit
    LD A,C                                     ; $7D32: 79
L_7D33:
defc L_7D34 = L_7D33 + 1 ; byte inside instruction at $7D33
    CP $40                                     ; $7D33: FE 40  SMC: half height $40 (view) / $60 (screen)
    BIT 3,E                                    ; $7D35: CB 5B  bit 3 set: dy is the whole distance
    EX AF,AF'                                  ; $7D37: 08  keep the y test in AF'
    LD A,B                                     ; $7D38: 78
L_7D39:
defc L_7D3A = L_7D39 + 1 ; byte inside instruction at $7D39
    CP $78                                     ; $7D39: FE 78  SMC: half width $78 (view x 8..247) / $80 (screen)
    BIT 2,E                                    ; $7D3B: CB 53  bit 2 set: dx is the whole distance
    JR Z,L_7D4B                                ; $7D3D: 28 0C  bit 2 clear: x distance 256 + dx
    JR NC,L_7D4C                               ; $7D3F: 30 0B  dx >= half width: beyond a side edge
    EX AF,AF'                                  ; $7D41: 08  column inside: recall the y test
    JR Z,L_7D48                                ; $7D42: 28 04  bit 3 clear: y distance 256 + dy
    JR NC,L_7D7E                               ; $7D44: 30 38  dy >= half height: above/below
    JR L_7D56                                  ; $7D46: 18 0E  centre inside the view

; VERIFIED: Case selection: bit 3 clear and dy >= $40 -> invisible.
L_7D48:
    RET NC                                     ; $7D48: D0  256 + dy: out of reach if dy >= $40
    JR L_7D7E                                  ; $7D49: 18 33  above/below the view, column inside

; VERIFIED: Case selection: bit 2 clear and dx >= $78 -> invisible.
L_7D4B:
    RET NC                                     ; $7D4B: D0  256 + dx: out of reach if dx >= $78
L_7D4C:
    EX AF,AF'                                  ; $7D4C: 08  beyond a side edge: recall the y test
    JR Z,L_7D53                                ; $7D4D: 28 04  bit 3 clear: y distance 256 + dy
    JR NC,L_7DAE                               ; $7D4F: 30 5D  beyond the top/bottom edge too
    JR L_7D6B                                  ; $7D51: 18 18  row inside
L_7D53:
    RET NC                                     ; $7D53: D0  256 + dy: out of reach if dy >= $40
    JR L_7DAE                                  ; $7D54: 18 58  diagonal

; VERIFIED: Case: centre inside the view.  dx + r < $78 -> L_7DE8 (no side edge reached);
; r - dx < $78 -> L_7EB8 (only the nearer side edge); else L_7E1E (both side edges).
L_7D56:
    LD A,B                                     ; $7D56: 78
    ADD A,D                                    ; $7D57: 82  dx + r
    JR C,L_7D5F                                ; $7D58: 38 05  over 255: reaches the nearer edge
L_7D5A:
defc L_7D5B = L_7D5A + 1 ; byte inside instruction at $7D5A
    CP $78                                     ; $7D5A: FE 78  SMC: half width $78 / $80
    JP C,L_7DE8                                ; $7D5C: DA E8 7D  dx + r < half width: no side edge
L_7D5F:
    LD A,D                                     ; $7D5F: 7A
    SUB B                                      ; $7D60: 90  r - dx
    JR C,L_7D65                                ; $7D61: 38 02  r < dx: far edge out of reach (carry)
L_7D63:
defc L_7D64 = L_7D63 + 1 ; byte inside instruction at $7D63
    CP $78                                     ; $7D63: FE 78  SMC: half width $78 / $80
L_7D65:
    JP C,L_7EB8                                ; $7D65: DA B8 7E  r - dx < half width: nearer edge only
    JP L_7E1E                                  ; $7D68: C3 1E 7E  both side edges reached

; VERIFIED: Case: centre beyond a side edge, row inside.  B = dx - $78 (distance beyond the edge);
; returns if r <= B; r - B >= $F0 -> L_7E14 (reaches the opposite edge), else L_7EAE.
L_7D6B:
    LD A,B                                     ; $7D6B: 78
    SUB $78                                    ; $7D6C: D6 78  pixels beyond the side edge
    LD B,A                                     ; $7D6E: 47
    LD (CircleWorkOffsetX),A                   ; $7D6F: 32 3F 7C  CircleWorkOffsetX = that distance
    LD A,D                                     ; $7D72: 7A
    SUB B                                      ; $7D73: 90  r - distance
    RET C                                      ; $7D74: D8  r < distance: out of reach
    RET Z                                      ; $7D75: C8  r = distance: only touches the edge
    SUB $F0                                    ; $7D76: D6 F0  240 = view width
    JP NC,L_7E14                               ; $7D78: D2 14 7E  also reaches the opposite edge
    JP L_7EAE                                  ; $7D7B: C3 AE 7E  nearer edge only

; VERIFIED: Case: centre above/below the view, column inside.  C = dy - $40; returns if r < C.
; Compares r*r - C*C with (120-dx)^2 and (120+dx)^2 to choose L_7F5F (no side edge at
; the edge row), L_7EE2 (one side edge) or L_7E6A (both side edges).
L_7D7E:
    LD A,C                                     ; $7D7E: 79
    SUB $40                                    ; $7D7F: D6 40  rows beyond the top/bottom edge
    LD C,A                                     ; $7D81: 4F
    LD (CircleWorkOffsetY),A                   ; $7D82: 32 3E 7C  CircleWorkOffsetY = that distance
    LD A,D                                     ; $7D85: 7A
    SUB C                                      ; $7D86: 91  r - C
    RET C                                      ; $7D87: D8  r < C: out of reach
    LD A,D                                     ; $7D88: 7A
    CALL SquareA                               ; $7D89: CD DF 7D  DE = r*r
    LD H,D                                     ; $7D8C: 62
    LD L,E                                     ; $7D8D: 6B
    LD A,C                                     ; $7D8E: 79
    CALL SquareA                               ; $7D8F: CD DF 7D  DE = C*C
    SBC HL,DE                                  ; $7D92: ED 52  HL = r*r - C*C: half chord^2 on the edge row
    LD A,$78                                   ; $7D94: 3E 78  $78 - dx: to the nearer side edge
    SUB B                                      ; $7D96: 90
    CALL SquareA                               ; $7D97: CD DF 7D  DE = its square
    SBC HL,DE                                  ; $7D9A: ED 52
    JP C,L_7F5F                                ; $7D9C: DA 5F 7F  chord inside the nearer edge
    ADD HL,DE                                  ; $7D9F: 19  restore r*r - C*C
    LD A,$78                                   ; $7DA0: 3E 78  $78 + dx: to the farther side edge
    ADD A,B                                    ; $7DA2: 80
    CALL SquareA                               ; $7DA3: CD DF 7D  DE = its square
    SBC HL,DE                                  ; $7DA6: ED 52
    JP NC,L_7E6A                               ; $7DA8: D2 6A 7E  chord crosses the farther edge too
    JP L_7EE2                                  ; $7DAB: C3 E2 7E  crosses the nearer edge only

; VERIFIED: Case: centre outside diagonally.  B = dx - $78, C = dy - $40; returns if the nearest
; view corner is outside the circle (r*r - C*C < B*B).  L_7E60 when B < 8 and
; r*r - C*C >= (B+248)^2 (far side edge reached; 248, not 240), else L_7ED8.
L_7DAE:
    LD A,B                                     ; $7DAE: 78
    SUB $78                                    ; $7DAF: D6 78  columns beyond the side edge
    LD B,A                                     ; $7DB1: 47
    LD A,C                                     ; $7DB2: 79
    SUB $40                                    ; $7DB3: D6 40  rows beyond the top/bottom edge
    LD C,A                                     ; $7DB5: 4F
    LD (CircleWorkOffsetY),BC                  ; $7DB6: ED 43 3E 7C  both working offsets
    LD A,D                                     ; $7DBA: 7A
    CALL SquareA                               ; $7DBB: CD DF 7D  DE = r*r
    LD H,D                                     ; $7DBE: 62
    LD L,E                                     ; $7DBF: 6B
    LD A,C                                     ; $7DC0: 79
    CALL SquareA                               ; $7DC1: CD DF 7D  DE = C*C
    SBC HL,DE                                  ; $7DC4: ED 52  HL = r*r - C*C
    RET C                                      ; $7DC6: D8  r < C: out of reach
    LD A,B                                     ; $7DC7: 78
    CALL SquareA                               ; $7DC8: CD DF 7D  DE = B*B
    SBC HL,DE                                  ; $7DCB: ED 52
    RET C                                      ; $7DCD: D8  nearest view corner outside the circle
    ADD HL,DE                                  ; $7DCE: 19  restore r*r - C*C
    LD A,B                                     ; $7DCF: 78
    ADD A,$F8                                  ; $7DD0: C6 F8  B + 248 (carry: B >= 8)
    JR C,L_7DDC                                ; $7DD2: 38 08  B >= 8: far edge out of reach
    CALL SquareA                               ; $7DD4: CD DF 7D  DE = (B + 248)^2 (far edge: B + 240)
    SBC HL,DE                                  ; $7DD7: ED 52
    JP NC,L_7E60                               ; $7DD9: D2 60 7E  far side edge reached
L_7DDC:
    JP L_7ED8                                  ; $7DDC: C3 D8 7E

; VERIFIED: DE = A*A, read from the page-aligned square tables (low byte from
; SquareLookupTables, high byte from the following page).  HL is preserved.
SquareA:
    PUSH HL                                    ; $7DDF: E5
    LD H,SquareLookupTables >> 8               ; $7DE0: 26 BE
    LD L,A                                     ; $7DE2: 6F
    LD E,(HL)                                  ; $7DE3: 5E
    INC H                                      ; $7DE4: 24
    LD D,(HL)                                  ; $7DE5: 56
    POP HL                                     ; $7DE6: E1
    RET                                        ; $7DE7: C9

; VERIFIED: No side edge reached: SetUpCentreRowSpan, DrawCircleRowsUp, SetUpCentreRowSpan again,
; then jump to DrawCircleRowsDown.
L_7DE8:
    CALL SetUpCentreRowSpan                    ; $7DE8: CD F4 7D  centre-row span
    CALL DrawCircleRowsUp                      ; $7DEB: CD C1 7C  upper half
    CALL SetUpCentreRowSpan                    ; $7DEE: CD F4 7D  centre-row span again
    JP DrawCircleRowsDown                      ; $7DF1: C3 A9 7C  lower half

; VERIFIED: Span set-up on the centre row: C' = -radius, E' = 0 (midpoint x and y), left end at
; x = CircleCentreX - radius (LocateSpanLeftEnd), right end at CircleCentreX + radius
; (LocateSpanRightEnd).  The dispatcher called next sets HL', D' and B'.
; Out: B = left end mask, E = left end low byte, HL = right end address, C = right end mask,
; D = radius, C' = -radius, E' = 0.
SetUpCentreRowSpan:
    LD BC,(CircleCentreY)                      ; $7DF4: ED 4B 40 7C  C = CircleCentreY, B = CircleCentreX
    LD DE,(CircleFlags)                        ; $7DF8: ED 5B 3C 7C  D = CircleRadius
    LD A,D                                     ; $7DFC: 7A
    NEG                                        ; $7DFD: ED 44
    EXX                                        ; $7DFF: D9
    LD C,A                                     ; $7E00: 4F  C' = -radius: midpoint x
    LD E,$00                                   ; $7E01: 1E 00  E' = 0: midpoint y
    EXX                                        ; $7E03: D9
    LD A,B                                     ; $7E04: 78
    SUB D                                      ; $7E05: 92  left end x = centre x - radius
    CALL LocateSpanLeftEnd                     ; $7E06: CD F4 7F
    LD A,(CircleCentreY)                       ; $7E09: 3A 40 7C  C = centre row again
    LD C,A                                     ; $7E0C: 4F
    LD A,(CircleCentreX)                       ; $7E0D: 3A 41 7C
    ADD A,D                                    ; $7E10: 82  right end x = centre x + radius
    JP LocateSpanRightEnd                      ; $7E11: C3 0F 80

; VERIFIED: Restore CircleWorkOffsetX (B + $78) and enter L_7E22 with A' = 0: the clipped spans
; never switch to the unclipped loop (the centre lies beyond the side edge).
L_7E14:
    LD A,B                                     ; $7E14: 78
    ADD A,$78                                  ; $7E15: C6 78  dx again
    LD B,A                                     ; $7E17: 47
    LD (CircleWorkOffsetX),A                   ; $7E18: 32 3F 7C  CircleWorkOffsetX = dx
    XOR A                                      ; $7E1B: AF  A' = 0: no switch to the unclipped loop
    JR L_7E22                                  ; $7E1C: 18 04

; VERIFIED: Both side edges reached: A' = $88 + dx + 1 = dx - $77 ($80 base when patched), the
; negative midpoint x at which the spans leave the nearer edge.  The clipped loops
; compare C' with A' and then continue in the FillDiscRows loop (L_8191, L_81D1).
L_7E1E:
defc L_7E1F = L_7E1E + 1 ; byte inside instruction at $7E1E
    LD A,$88                                   ; $7E1E: 3E 88  SMC: $88 = -$78 (view) / $80 = -$80 (screen)
    ADD A,B                                    ; $7E20: 80
    INC A                                      ; $7E21: 3C  switch value $89 + dx (see header)

; VERIFIED: Both side edges reached: CircleHalfChord = ComputeHalfChord(r, $78 + dx), the height
; where the circle meets the far edge.  Those rows are filled up and down from the centre
; row (FillCircleRowsUp/Down); the remaining rows are drawn clipped at the nearer edge
; (StartMidpointAtFarEdge, SetFullWidthSpanEnds, dispatcher by CircleFlags bit 0).
L_7E22:
    EX AF,AF'                                  ; $7E22: 08  keep the switch value in A'
L_7E23:
defc L_7E24 = L_7E23 + 1 ; byte inside instruction at $7E23
    LD A,$78                                   ; $7E23: 3E 78  SMC: half width $78 / $80
    ADD A,B                                    ; $7E25: 80  centre to the far side edge
    CALL ComputeHalfChord                      ; $7E26: CD ED 80  height where the circle crosses it
    LD (CircleHalfChord),A                     ; $7E29: 32 42 7C  full-width rows above and below the centre
    LD B,A                                     ; $7E2C: 47
    LD A,(CircleCentreY)                       ; $7E2D: 3A 40 7C  from the centre row
    CALL FillCircleRowsUp                      ; $7E30: CD D8 7C  full-width rows upwards
    CALL StartMidpointAtFarEdge                ; $7E33: CD 36 80  midpoint state at the far edge
    CALL SetFullWidthSpanEnds                  ; $7E36: CD 45 80  span ends at the view edges
    LD A,(CircleFlags)                         ; $7E39: 3A 3C 7C
    BIT 0,A                                    ; $7E3C: CB 47  bit 0: centre right of column 128
    CALL Z,DrawCircleRowsUpLeftClipped         ; $7E3E: CC 92 7C  centre left: rest clipped at the left edge
    CALL NZ,DrawCircleRowsUpRightClipped       ; $7E41: C4 63 7C  centre right: clipped at the right edge
    LD A,(CircleHalfChord)                     ; $7E44: 3A 42 7C  row count again
    LD B,A                                     ; $7E47: 47
    LD A,(CircleCentreY)                       ; $7E48: 3A 40 7C  from the centre row
    CALL FillCircleRowsDown                    ; $7E4B: CD E4 7C  full-width rows downwards
    CALL StartMidpointAtFarEdge                ; $7E4E: CD 36 80  midpoint state at the far edge
    CALL SetFullWidthSpanEnds                  ; $7E51: CD 45 80  span ends at the view edges
    LD A,(CircleFlags)                         ; $7E54: 3A 3C 7C
    BIT 0,A                                    ; $7E57: CB 47  bit 0: centre right of column 128
    CALL Z,DrawCircleRowsDownLeftClipped       ; $7E59: CC 7A 7C  centre left: rest clipped at the left edge
    CALL NZ,DrawCircleRowsDownRightClipped     ; $7E5C: C4 4B 7C  centre right: clipped at the right edge
    RET                                        ; $7E5F: C9

; VERIFIED: Restore CircleWorkOffsetX and enter L_7E6D with A' = 0 (diagonal case).
L_7E60:
    LD A,B                                     ; $7E60: 78
    ADD A,$78                                  ; $7E61: C6 78  dx again
    LD B,A                                     ; $7E63: 47
    LD (CircleWorkOffsetX),A                   ; $7E64: 32 3F 7C  CircleWorkOffsetX = dx
    XOR A                                      ; $7E67: AF  A' = 0: no switch to the unclipped loop
    JR L_7E6D                                  ; $7E68: 18 03

; VERIFIED: Edge row reaches both side edges: A' = dx - $77 (switch point, see L_7E1E).
L_7E6A:
    LD A,B                                     ; $7E6A: 78
    SUB $77                                    ; $7E6B: D6 77  switch value dx - $77

; VERIFIED: Edge row inside both side edges: CircleHalfChord = ComputeHalfChord(r, $78 + dx); fill
; the rows from the view edge up to that height, then draw the rest clipped at the
; nearer edge (direction from CircleFlags bit 1).
L_7E6D:
    EX AF,AF'                                  ; $7E6D: 08  keep the switch value in A'
    LD DE,(CircleFlags)                        ; $7E6E: ED 5B 3C 7C  E = CircleFlags, D = CircleRadius
    LD A,$78                                   ; $7E72: 3E 78  centre to the far side edge
    ADD A,B                                    ; $7E74: 80
    CALL ComputeHalfChord                      ; $7E75: CD ED 80  height where the circle crosses it
    LD (CircleHalfChord),A                     ; $7E78: 32 42 7C
    SUB C                                      ; $7E7B: 91  minus the rows outside the view
    LD B,A                                     ; $7E7C: 47  B = full-width rows inside the view
    BIT 1,E                                    ; $7E7D: CB 4B  bit 1: centre above the view
    JR Z,L_7E97                                ; $7E7F: 28 16
    XOR A                                      ; $7E81: AF  above: from row 0 downwards
    CALL FillCircleRowsDown                    ; $7E82: CD E4 7C  full-width rows
    CALL StartMidpointAtFarEdge                ; $7E85: CD 36 80  midpoint state at the far edge
    CALL SetFullWidthSpanEnds                  ; $7E88: CD 45 80  span ends at the view edges
    LD A,(CircleFlags)                         ; $7E8B: 3A 3C 7C
    BIT 0,A                                    ; $7E8E: CB 47  bit 0: centre right of column 128
    CALL Z,DrawCircleRowsDownLeftClipped       ; $7E90: CC 7A 7C  centre left: rest clipped at the left edge
    CALL NZ,DrawCircleRowsDownRightClipped     ; $7E93: C4 4B 7C  centre right: clipped at the right edge
    RET                                        ; $7E96: C9

; VERIFIED: As L_7E6D for a centre below the view: start at row $7F and fill upwards.
L_7E97:
    LD A,$7F                                   ; $7E97: 3E 7F  below: from row $7F upwards
    CALL FillCircleRowsUp                      ; $7E99: CD D8 7C  full-width rows
    CALL StartMidpointAtFarEdge                ; $7E9C: CD 36 80  midpoint state at the far edge
    CALL SetFullWidthSpanEnds                  ; $7E9F: CD 45 80  span ends at the view edges
    LD A,(CircleFlags)                         ; $7EA2: 3A 3C 7C
    BIT 0,A                                    ; $7EA5: CB 47  bit 0: centre right of column 128
    CALL Z,DrawCircleRowsUpLeftClipped         ; $7EA7: CC 92 7C  centre left: rest clipped at the left edge
    CALL NZ,DrawCircleRowsUpRightClipped       ; $7EAA: C4 63 7C  centre right: clipped at the right edge
    RET                                        ; $7EAD: C9

; VERIFIED: Restore CircleWorkOffsetX and enter L_7EBB with A' = 0.
L_7EAE:
    LD A,B                                     ; $7EAE: 78
    ADD A,$78                                  ; $7EAF: C6 78  dx again
    LD (CircleWorkOffsetX),A                   ; $7EB1: 32 3F 7C  CircleWorkOffsetX = dx
    LD B,A                                     ; $7EB4: 47
    XOR A                                      ; $7EB5: AF  A' = 0: no switch to the unclipped loop
    JR L_7EBB                                  ; $7EB6: 18 03

; VERIFIED: Only the nearer side edge reached: A' = dx - $77 (switch point, see L_7E1E).
L_7EB8:
    LD A,B                                     ; $7EB8: 78
L_7EB9:
defc L_7EBA = L_7EB9 + 1 ; byte inside instruction at $7EB9
    SUB $77                                    ; $7EB9: D6 77  SMC: half width - 1: $77 / $7F

; VERIFIED: One side edge reached, centre row inside: draw up and down with spans clipped at the
; right edge (CircleFlags bit 0 set, SetUpRightClippedSpan) or the left edge
; (SetUpLeftClippedSpan).
L_7EBB:
