    CALL DrawCircleRowsDownRightClipped        ; $7EC3: CD 4B 7C  lower half
    CALL SetUpRightClippedSpan                 ; $7EC6: CD A5 7F  centre-row span again
    JP DrawCircleRowsUpRightClipped            ; $7EC9: C3 63 7C  upper half
L_7ECC:
    CALL SetUpLeftClippedSpan                  ; $7ECC: CD C1 7F  centre-row span, left end at the edge
    CALL DrawCircleRowsDownLeftClipped         ; $7ECF: CD 7A 7C  lower half
    CALL SetUpLeftClippedSpan                  ; $7ED2: CD C1 7F  centre-row span again
    JP DrawCircleRowsUpLeftClipped             ; $7ED5: C3 92 7C  upper half

; VERIFIED: Restore CircleWorkOffsetX and enter L_7EE5 with A' = 0.
L_7ED8:
    LD A,B                                     ; $7ED8: 78
    ADD A,$78                                  ; $7ED9: C6 78  dx again
    LD (CircleWorkOffsetX),A                   ; $7EDB: 32 3F 7C  CircleWorkOffsetX = dx
    LD B,A                                     ; $7EDE: 47
    XOR A                                      ; $7EDF: AF  A' = 0: no switch to the unclipped loop
    JR L_7EE5                                  ; $7EE0: 18 03

; VERIFIED: Edge row reaches one side edge: A' = dx - $77 (switch point, see L_7E1E).
L_7EE2:
    LD A,B                                     ; $7EE2: 78
    SUB $77                                    ; $7EE3: D6 77  switch value dx - $77

; VERIFIED: Edge row crosses one side edge:
; CircleHalfChord = ComputeHalfChord(r, CircleWorkOffsetY); build the edge-row span (row 0
; or $7F) and draw away from the edge.  Midpoint state: E' = rows beyond the edge,
; C' = -chord.
L_7EE5:
    EX AF,AF'                                  ; $7EE5: 08  keep the switch value in A'
    LD DE,(CircleFlags)                        ; $7EE6: ED 5B 3C 7C  E = CircleFlags, D = CircleRadius
    LD A,C                                     ; $7EEA: 79  rows beyond the top/bottom edge
    CALL ComputeHalfChord                      ; $7EEB: CD ED 80  half chord on the edge row
    LD (CircleHalfChord),A                     ; $7EEE: 32 42 7C
    LD A,C                                     ; $7EF1: 79
    EXX                                        ; $7EF2: D9
    LD E,A                                     ; $7EF3: 5F  E' = rows beyond the edge: midpoint y
    LD A,(CircleHalfChord)                     ; $7EF4: 3A 42 7C
    NEG                                        ; $7EF7: ED 44
    LD C,A                                     ; $7EF9: 4F  C' = -chord: midpoint x
    EXX                                        ; $7EFA: D9
