    CPL                                        ; $7F02: 2F
    ADD A,$81                                  ; $7F03: C6 81  $80 - chord ...
    ADD A,B                                    ; $7F05: 80  ... + dx: left end x on the edge row
    LD C,$00                                   ; $7F06: 0E 00  row 0 (centre above the view)
    BIT 1,E                                    ; $7F08: CB 4B  bit 1: centre above the view
    JR NZ,L_7F0E                               ; $7F0A: 20 02
    LD C,$7F                                   ; $7F0C: 0E 7F  row $7F (centre below the view)
L_7F0E:
    CALL LocateSpanLeftEnd                     ; $7F0E: CD F4 7F
    LD A,(CircleOutlineFlag)                   ; $7F11: 3A 49 7C
    AND A                                      ; $7F14: A7
    JP NZ,L_85F4                               ; $7F15: C2 F4 85  outline: L_85F4
    LD A,E                                     ; $7F18: 7B
    AND $1F                                    ; $7F19: E6 1F
    CP $1F                                     ; $7F1B: FE 1F  left end in column 31 (x >= 248)?
    RET Z                                      ; $7F1D: C8  then nothing is inside the view
    LD A,E                                     ; $7F1E: 7B
    OR $1F                                     ; $7F1F: F6 1F  right end: column 31 (exclusive)
    LD L,A                                     ; $7F21: 6F
    LD C,$00                                   ; $7F22: 0E 00  no right end mask
    LD A,(CircleFlags)                         ; $7F24: 3A 3C 7C
    BIT 1,A                                    ; $7F27: CB 4F  bit 1: centre above the view
    CALL NZ,DrawCircleRowsDownRightClipped     ; $7F29: C4 4B 7C  above: rows downwards from row 0
    CALL Z,DrawCircleRowsUpRightClipped        ; $7F2C: CC 63 7C  below: rows upwards from row $7F
    RET                                        ; $7F2F: C9
L_7F30:
