    ADD A,$80                                  ; $7F33: C6 80  chord + $80 ...
    SUB B                                      ; $7F35: 90  ... - dx: right end x on the edge row
    CP $08                                     ; $7F36: FE 08  x < 8: all in the left border
    RET C                                      ; $7F38: D8
    LD C,$00                                   ; $7F39: 0E 00  row 0 (centre above the view)
    BIT 1,E                                    ; $7F3B: CB 4B  bit 1: centre above the view
    JR NZ,L_7F41                               ; $7F3D: 20 02
    LD C,$7F                                   ; $7F3F: 0E 7F  row $7F (centre below the view)
L_7F41:
    CALL LocateSpanRightEnd                    ; $7F41: CD 0F 80
    LD A,L                                     ; $7F44: 7D
    AND $E0                                    ; $7F45: E6 E0
    OR $01                                     ; $7F47: F6 01  left end: column 1 (x 8)
    LD E,A                                     ; $7F49: 5F
    LD A,(CircleOutlineFlag)                   ; $7F4A: 3A 49 7C
    AND A                                      ; $7F4D: A7
    JP NZ,L_8608                               ; $7F4E: C2 08 86  outline: L_8608
    LD B,$FF                                   ; $7F51: 06 FF  whole left byte
    LD A,(CircleFlags)                         ; $7F53: 3A 3C 7C
    BIT 1,A                                    ; $7F56: CB 4F  bit 1: centre above the view
    CALL NZ,DrawCircleRowsDownLeftClipped      ; $7F58: C4 7A 7C  above: rows downwards from row 0
    CALL Z,DrawCircleRowsUpLeftClipped         ; $7F5B: CC 92 7C  below: rows upwards from row $7F
    RET                                        ; $7F5E: C9

; VERIFIED: In: B = dx, C = rows beyond the top/bottom edge (CircleWorkOffsetY), D = radius.
; Centre above/below, no side edge reached: CircleCentreY := edge row (0 or $7F),
; CircleHalfChord = ComputeHalfChord(r, CircleWorkOffsetY); span from centre x - chord
; to centre x + chord on that row, then DrawCircleRowsDown or DrawCircleRowsUp.
; The midpoint state starts at y = C, x = -chord (E', C').
L_7F5F:
    LD DE,(CircleFlags)                        ; $7F5F: ED 5B 3C 7C  E = CircleFlags, D = CircleRadius
