    LD (CircleHalfChord),A                     ; $7F67: 32 42 7C
    LD A,C                                     ; $7F6A: 79
    EXX                                        ; $7F6B: D9
    LD E,A                                     ; $7F6C: 5F  E' = rows beyond the edge: midpoint y
    LD A,(CircleHalfChord)                     ; $7F6D: 3A 42 7C
    NEG                                        ; $7F70: ED 44
    LD C,A                                     ; $7F72: 4F  C' = -chord: midpoint x
    EXX                                        ; $7F73: D9
    XOR A                                      ; $7F74: AF  row 0 (centre above the view)
    BIT 1,E                                    ; $7F75: CB 4B  bit 1: centre above the view
    JR NZ,L_7F7B                               ; $7F77: 20 02
    LD A,$7F                                   ; $7F79: 3E 7F  row $7F (centre below the view)
L_7F7B:
    LD (CircleCentreY),A                       ; $7F7B: 32 40 7C  the spans start on the edge row
    LD C,A                                     ; $7F7E: 4F
    LD A,(CircleHalfChord)                     ; $7F7F: 3A 42 7C
    LD L,A                                     ; $7F82: 6F
    LD A,(CircleCentreX)                       ; $7F83: 3A 41 7C
