    LD C,A                                     ; $7F8D: 4F
    LD A,(CircleHalfChord)                     ; $7F8E: 3A 42 7C
    LD L,A                                     ; $7F91: 6F
    LD A,(CircleCentreX)                       ; $7F92: 3A 41 7C
    ADD A,L                                    ; $7F95: 85  right end x = centre x + chord
    CALL LocateSpanRightEnd                    ; $7F96: CD 0F 80
    LD A,(CircleFlags)                         ; $7F99: 3A 3C 7C
    BIT 1,A                                    ; $7F9C: CB 4F  bit 1: centre above the view
    CALL NZ,DrawCircleRowsDown                 ; $7F9E: C4 A9 7C  above: rows downwards
    CALL Z,DrawCircleRowsUp                    ; $7FA1: CC C1 7C  below: rows upwards
    RET                                        ; $7FA4: C9

; VERIFIED: Right-clipped set-up: StartMidpointAtRadius, left end at x = $80 + dx - r
; (LocateSpanLeftEnd).  Fill mode: right end L = column 31 (exclusive), C = 0;
; outline mode: L_8616.
; Out: B = left end mask, E = left end low byte, HL = right end address, C = right end mask,
; C' = -radius, E' = 0 (from StartMidpointAtRadius).
SetUpRightClippedSpan:
    CALL StartMidpointAtRadius                 ; $7FA5: CD E3 7F
    LD A,(CircleCentreY)                       ; $7FA8: 3A 40 7C  C = centre row
