    OR $1F                                     ; $7FBB: F6 1F  right end: column 31 (exclusive)
    LD L,A                                     ; $7FBD: 6F
    LD C,$00                                   ; $7FBE: 0E 00  no right end mask
    RET                                        ; $7FC0: C9

; VERIFIED: Left-clipped set-up: StartMidpointAtRadius, right end at x = $80 - dx + r
; (LocateSpanRightEnd), left end E = column 1 (patched 0 for the screen).
; B = $FF (fill) or $80 (outline).
; Out: as SetUpRightClippedSpan (B, E, HL, C; C' = -radius, E' = 0).
SetUpLeftClippedSpan:
    CALL StartMidpointAtRadius                 ; $7FC1: CD E3 7F
    LD A,(CircleCentreY)                       ; $7FC4: 3A 40 7C  C = centre row
    LD C,A                                     ; $7FC7: 4F
    LD A,$80                                   ; $7FC8: 3E 80
    ADD A,D                                    ; $7FCA: 82
    SUB B                                      ; $7FCB: 90  right end x = $80 - dx + r
    CALL LocateSpanRightEnd                    ; $7FCC: CD 0F 80
    LD A,L                                     ; $7FCF: 7D
