L_7FD2:
defc L_7FD3 = L_7FD2 + 1 ; byte inside instruction at $7FD2
    OR $01                                     ; $7FD2: F6 01  SMC: left column 1 (view, x >= 8) / 0 (screen)
    LD E,A                                     ; $7FD4: 5F  left end: the edge byte
    LD B,A                                     ; $7FD5: 47
    LD A,(CircleOutlineFlag)                   ; $7FD6: 3A 49 7C
    AND A                                      ; $7FD9: A7
    LD A,B                                     ; $7FDA: 78
    JR NZ,L_7FE0                               ; $7FDB: 20 03
    LD B,$FF                                   ; $7FDD: 06 FF  filled: whole left byte
