; VERIFIED: In: A = x, C = row.  HL = address of the pixel (ROM PIXEL-ADD tail, then SET 7,H for the
; view buffer, NOP NOP when patched for the screen); B = mask of the pixels right of x in
; that byte (outline mode: L_861F gives the single pixel x); E = L.  Changes A and C.
; Evidence: tools/check_routines.py circles/p2-span-end-locators (all 256 x, both modes).
LocateSpanLeftEnd:
    LD B,C                                     ; $7FF4: 41
    LD C,A                                     ; $7FF5: 4F
    LD A,B                                     ; $7FF6: 78  B = row, C = x, A = row
    CALL RomPixelAddressTail                   ; $7FF7: CD B0 22  A = row, C = x -> HL, A = x AND 7
L_7FFA:
defc L_7FFB = L_7FFA + 1 ; byte inside instruction at $7FFA
    SET 7,H                                    ; $7FFA: CB FC  SMC: SET 7,H (view buffer) / NOP NOP (screen)
    LD B,A                                     ; $7FFC: 47
    LD A,(CircleOutlineFlag)                   ; $7FFD: 3A 49 7C
    AND A                                      ; $8000: A7
    LD A,B                                     ; $8001: 78
    JP NZ,L_861F                               ; $8002: C2 1F 86  outline: single pixel x (L_861F)
    LD B,$FF                                   ; $8005: 06 FF  B = $FF >> (1 + x AND 7): pixels right of x
    INC A                                      ; $8007: 3C
L_8008:
    SRL B                                      ; $8008: CB 38
    DEC A                                      ; $800A: 3D
    JR NZ,L_8008                               ; $800B: 20 FB
    LD E,L                                     ; $800D: 5D  E = low byte of the left end address
    RET                                        ; $800E: C9

; VERIFIED: In: A = x, C = row.  HL = address of the pixel (as LocateSpanLeftEnd); C = mask of the
; pixels left of x (fill) or the single pixel x (outline, L_8629).  B (through
; SavedLeftEndMask), D and E are preserved.  A filled span thus covers the pixels strictly
; between the two x values.
; Evidence: tools/check_routines.py circles/p2-span-end-locators (all 256 x, both modes).
LocateSpanRightEnd:
    PUSH AF                                    ; $800F: F5
    LD A,B                                     ; $8010: 78
    LD (SavedLeftEndMask),A                    ; $8011: 32 47 7C  keep the left end mask
    POP AF                                     ; $8014: F1
    LD B,C                                     ; $8015: 41
    LD C,A                                     ; $8016: 4F
    LD A,B                                     ; $8017: 78  B = row, C = x, A = row
    CALL RomPixelAddressTail                   ; $8018: CD B0 22  A = row, C = x -> HL, A = x AND 7
L_801B:
defc L_801C = L_801B + 1 ; byte inside instruction at $801B
    SET 7,H                                    ; $801B: CB FC  SMC: SET 7,H (view buffer) / NOP NOP (screen)
    SUB $08                                    ; $801D: D6 08
    NEG                                        ; $801F: ED 44  A = 8 - (x AND 7)
    LD C,A                                     ; $8021: 4F
    LD A,(CircleOutlineFlag)                   ; $8022: 3A 49 7C
    AND A                                      ; $8025: A7
    LD A,C                                     ; $8026: 79
    JP NZ,L_8629                               ; $8027: C2 29 86  outline: single pixel x (L_8629)
    LD C,$FF                                   ; $802A: 0E FF  C = $FF << (8 - x AND 7): pixels left of x
L_802C:
    SLA C                                      ; $802C: CB 21
    DEC A                                      ; $802E: 3D
    JR NZ,L_802C                               ; $802F: 20 FB
    LD A,(SavedLeftEndMask)                    ; $8031: 3A 47 7C  left end mask back into B
    LD B,A                                     ; $8034: 47
    RET                                        ; $8035: C9

; VERIFIED: Midpoint start where the circle meets the far side edge: C' = $88 - CircleWorkOffsetX
