    CP H                                       ; $8123: BC
    JR C,L_812F                                ; $8124: 38 09  start row inside: draw
    JR L_812D                                  ; $8126: 18 05  start row above the area
L_8128:
defc L_8129 = L_8128 + 1 ; byte inside instruction at $8128
