L_812D:
    POP AF                                     ; $812D: F1  dispatcher's AF; nothing drawn
    RET                                        ; $812E: C9
L_812F:
    LD (CircleSavedStackPointer),SP            ; $812F: ED 73 43 7C  kept for the PUSH fill and the exits
L_8133:
    LD A,(HL)                                  ; $8133: 7E
    OR C                                       ; $8134: B1  OR the right end mask into its byte
    LD (HL),A                                  ; $8135: 77
    LD D,L                                     ; $8136: 55  D = right end low byte
    LD L,E                                     ; $8137: 6B  HL = left end byte
    LD A,(HL)                                  ; $8138: 7E
    OR B                                       ; $8139: B0  OR the left end mask
    LD (HL),A                                  ; $813A: 77
    LD A,D                                     ; $813B: 7A
    SUB E                                      ; $813C: 93
    DEC A                                      ; $813D: 3D  bytes strictly between the ends
    SRL A                                      ; $813E: CB 3F  words; an odd byte in carry
