    LD SP,FilledSpanPattern                    ; $83FD: 31 F2 85  AF = $FFFF fill pattern
    POP AF                                     ; $8400: F1
    LD SP,HL                                   ; $8401: F9
L_8402:
defc L_8403 = L_8402 + 1 ; byte inside instruction at $8402
    JR L_8402                                  ; $8402: 18 FE  SMC: displacement written above (into the PUSH AF run)

; VERIFIED: PUSH AF run of FillDiscRowsRightClipped (second octant).
L_8404:
    PUSH AF                                    ; $8404: F5
    PUSH AF                                    ; $8405: F5
    PUSH AF                                    ; $8406: F5
    PUSH AF                                    ; $8407: F5
    PUSH AF                                    ; $8408: F5
    PUSH AF                                    ; $8409: F5
    PUSH AF                                    ; $840A: F5
    PUSH AF                                    ; $840B: F5
    PUSH AF                                    ; $840C: F5
    PUSH AF                                    ; $840D: F5
    PUSH AF                                    ; $840E: F5
    PUSH AF                                    ; $840F: F5
    PUSH AF                                    ; $8410: F5
    PUSH AF                                    ; $8411: F5
    PUSH AF                                    ; $8412: F5
    PUSH AF                                    ; $8413: F5
    LD A,(CircleRowDirection)                  ; $8414: 3A 48 7C
    AND A                                      ; $8417: A7
    LD SP,(CircleSavedStackPointer)            ; $8418: ED 7B 43 7C  SP back for the row helpers (flags kept)
    JR NZ,L_8427                               ; $841C: 20 09
    LD A,H                                     ; $841E: 7C
    DEC H                                      ; $841F: 25  row up
    AND $07                                    ; $8420: E6 07
    CALL Z,AdjustRowUpAcrossCell               ; $8422: CC 30 84  cell boundary crossed
    JR L_83CE                                  ; $8425: 18 A7  move x for the next row
L_8427:
    INC H                                      ; $8427: 24  row down
    LD A,H                                     ; $8428: 7C
    AND $07                                    ; $8429: E6 07
    CALL Z,AdjustRowDownAcrossCell             ; $842B: CC 45 84  cell boundary crossed
    JR L_83CE                                  ; $842E: 18 9E  move x for the next row

; VERIFIED: Called after DEC H left a character cell: E -= 32, L -= 32; within the same screen
; third H += 8.  On leaving a third, if H is the top limit ($BF buffer, $3F screen) the
; span loop ends through AbortCircleRows.  Out: HL and E on the row above.
AdjustRowUpAcrossCell:
    LD A,E                                     ; $8430: 7B
    SUB $20                                    ; $8431: D6 20  left end byte: cell row above
    LD E,A                                     ; $8433: 5F
    LD A,L                                     ; $8434: 7D
    SUB $20                                    ; $8435: D6 20  right end byte: cell row above
    LD L,A                                     ; $8437: 6F
    JR NC,L_8440                               ; $8438: 30 06  same third: H + 8
L_843A:
defc L_843B = L_843A + 1 ; byte inside instruction at $843A
    LD A,$BF                                   ; $843A: 3E BF  SMC: top limit $BF (buffer) / $3F (screen)
    CP H                                       ; $843C: BC
    JR Z,AbortCircleRows                       ; $843D: 28 1B  above the area: stop the span loop
    RET                                        ; $843F: C9  previous third: H - 1 is right
L_8440:
    LD A,H                                     ; $8440: 7C
    ADD A,$08                                  ; $8441: C6 08
    LD H,A                                     ; $8443: 67
    RET                                        ; $8444: C9

; VERIFIED: Called after INC H left a character cell: E += 32, L += 32; within the same third
; H -= 8.  On entering the next third, if H is the bottom limit ($D0 buffer, $58 for
; DrawScreenCircle, $50 for DrawFlaggedObjectDiscs) the loop ends via AbortCircleRows.
AdjustRowDownAcrossCell:
    LD A,E                                     ; $8445: 7B
    ADD A,$20                                  ; $8446: C6 20  left end byte: cell row below
    LD E,A                                     ; $8448: 5F
    LD A,L                                     ; $8449: 7D
    ADD A,$20                                  ; $844A: C6 20  right end byte: cell row below
    LD L,A                                     ; $844C: 6F
    JR NC,L_8455                               ; $844D: 30 06  same third: H - 8
L_844F:
defc L_8450 = L_844F + 1 ; byte inside instruction at $844F
    LD A,$D0                                   ; $844F: 3E D0  SMC: bottom limit $D0 (buffer) / $58 or $50 (screen)
    CP H                                       ; $8451: BC
    JR Z,AbortCircleRows                       ; $8452: 28 06  below the area: stop the span loop
    RET                                        ; $8454: C9  next third: H + 1 is right
L_8455:
    LD A,H                                     ; $8455: 7C
    SUB $08                                    ; $8456: D6 08
    LD H,A                                     ; $8458: 67
    RET                                        ; $8459: C9

; VERIFIED: Drop the helper's return address, restore SP from CircleSavedStackPointer, POP AF and
; return to the dispatcher's caller (the span loop stops at the limit).
AbortCircleRows:
    POP AF                                     ; $845A: F1  drop the return into the span loop
    LD SP,(CircleSavedStackPointer)            ; $845B: ED 7B 43 7C  SP saved by the span loop
    POP AF                                     ; $845F: F1  the dispatcher's AF
    RET                                        ; $8460: C9

; ============================================================================
; Direct-screen circle variants (self-modifying code)
; DrawScreenCircle patches 32 operand/opcode bytes for a 256x192 screen circle and
; restores them; DrawFlaggedObjectDiscs/PatchDiscRendererTarget switch the filled
; path to the screen top 128 lines and back.
; ============================================================================

; VERIFIED: Draw an outline circle directly on the 256x192 screen: centre x = (ShapeCentreX),
; row = (ShapeCentreY), radius = (ShapeSize).  Converts them to CircleOffsetX/Y and CircleFlags
; ($0C + side bits, relative to x 128 and row 96), copies ScreenCirclePatchValues to the 32
; bytes listed in CirclePatchTargets (interrupts disabled), calls DrawCircleOutline, then
; copies ViewCirclePatchValues back.  A radius below 9 draws nothing (DrawCircleOutline).
; Out: A = 0, interrupts enabled; other registers changed.
; Callers: the short-range chart L_A9D0+105 (radius = FuelLevel, centred on the current
; system at x $61, row $60), DrawGalacticChart+47 (radius = FuelLevel / 4, centred on
; the current system) and BuyCargoScreen+37 (a fixed circle at x $B6, row $76, radius $3D
; on the message screen it shows while NovaMissionActive is nonzero).
; Evidence: tools/check_routines.py circles/screen-circle-patching (four circles, every patched
; byte restored) and circles/p2-screen-circle-minimum-radius; caller code.
DrawScreenCircle:
    LD B,$0C                                   ; $8461: 06 0C  $0C: both offsets exact (CircleFlags bits 2/3)
    LD A,(ShapeCentreX)                        ; $8463: 3A 13 A8  centre x
    LD C,A                                     ; $8466: 4F
    SUB $80                                    ; $8467: D6 80  x - 128
    JR C,L_846F                                ; $8469: 38 04
    SET 0,B                                    ; $846B: CB C0  right of column 128
    JR L_8472                                  ; $846D: 18 03
L_846F:
    LD A,$80                                   ; $846F: 3E 80
    SUB C                                      ; $8471: 91  128 - x
L_8472:
    LD (CircleOffsetX),A                       ; $8472: 32 3B 7C  CircleOffsetX = |x - 128|
    LD A,(ShapeCentreY)                        ; $8475: 3A 14 A8  centre row
    LD C,A                                     ; $8478: 4F
    SUB $60                                    ; $8479: D6 60  row - 96
    JR NC,L_8482                               ; $847B: 30 05
    SET 1,B                                    ; $847D: CB C8  above row 96
    LD A,$60                                   ; $847F: 3E 60
    SUB C                                      ; $8481: 91  96 - row
L_8482:
    LD (CircleOffsetY),A                       ; $8482: 32 3A 7C  CircleOffsetY = |row - 96|
    LD A,B                                     ; $8485: 78
    LD (CircleFlags),A                         ; $8486: 32 3C 7C  $0C + side bits
    LD A,(ShapeSize)                           ; $8489: 3A 15 A8  radius
    LD (CircleRadius),A                        ; $848C: 32 3D 7C
    DI                                         ; $848F: F3  SP is borrowed by the patch loop
    LD (CircleSavedStackPointer),SP            ; $8490: ED 73 43 7C
    LD A,(CirclePatchCount)                    ; $8494: 3A 4A 7C  32 patch bytes
    LD HL,ScreenCirclePatchValues              ; $8497: 21 C5 84  screen values
    LD SP,CirclePatchTargets                   ; $849A: 31 05 85  SP walks the destination pointers

; VERIFIED: Patch loop: POP DE takes the next destination from CirclePatchTargets, LDI copies one
; value byte; CirclePatchCount iterations.  SP is then restored.
L_849D:
    POP DE                                     ; $849D: D1
    LDI                                        ; $849E: ED A0  patch one byte (destination from POP DE)
    DEC A                                      ; $84A0: 3D
    JR NZ,L_849D                               ; $84A1: 20 FA
    LD SP,(CircleSavedStackPointer)            ; $84A3: ED 7B 43 7C  SP back
    EI                                         ; $84A7: FB  interrupts on while drawing
    CALL DrawCircleOutline                     ; $84A8: CD FE 7C  draw with the screen values in place
    DI                                         ; $84AB: F3  restore with interrupts off
    LD (CircleSavedStackPointer),SP            ; $84AC: ED 73 43 7C
    LD A,(CirclePatchCount)                    ; $84B0: 3A 4A 7C
    LD HL,ViewCirclePatchValues                ; $84B3: 21 E5 84  view-buffer values
    LD SP,CirclePatchTargets                   ; $84B6: 31 05 85  the same 32 destinations

; VERIFIED: Restore loop: as L_849D, copying ViewCirclePatchValues.
L_84B9:
    POP DE                                     ; $84B9: D1
    LDI                                        ; $84BA: ED A0  restore one byte
    DEC A                                      ; $84BC: 3D
    JR NZ,L_84B9                               ; $84BD: 20 FA
    LD SP,(CircleSavedStackPointer)            ; $84BF: ED 7B 43 7C
    EI                                         ; $84C3: FB  A = 0 on return
    RET                                        ; $84C4: C9

; VERIFIED: 32 values for DrawScreenCircle in CirclePatchTargets order: centre row and half height
; $60, half width $80 (and -$80, $7F), columns 0/31, NOP NOP instead of SET 7,H, x limit
; $FF and screen row limits $28/$58/$57/$3F.
ScreenCirclePatchValues:
    defb $60,$60,$80,$80,$80,$80,$80,$7F                                                  ; $84C5 ``......  entries 0..7: centre and half sizes
    defb $1F,$00,$00,$00,$00,$00,$80,$00                                                  ; $84CD ........  entries 8..15: columns, SET 7,H, far edge
    defb $FF,$00,$00,$28,$FF,$00,$00,$58                                                  ; $84D5 ...(...X  entries 16..23: L_8640 and L_866E
    defb $57,$3F,$3F,$57,$57,$3F,$58,$3F                                                  ; $84DD W??WW?X?  entries 24..31: arc start rows, cell limits

; VERIFIED: The 32 view-buffer values, identical to the image bytes at the targets: $40/$78/$88/$77,
; columns 1/30, SET 7,H ($CB,$FC), x limit $F7 and buffer limits $C0/$D0/$CF/$BF.
ViewCirclePatchValues:
    defb $40,$40,$78,$78,$78,$88,$78,$77                                                  ; $84E5 @@xxx.xw  entries 0..7: centre and half sizes
    defb $1E,$01,$CB,$FC,$CB,$FC,$88,$01                                                  ; $84ED ........  entries 8..15: columns, SET 7,H, far edge
    defb $F7,$CB,$FC,$C0,$F7,$CB,$FC,$D0                                                  ; $84F5 ........  entries 16..23: L_8640 and L_866E
    defb $CF,$BF,$BF,$CF,$CF,$BF,$D0,$BF                                                  ; $84FD ........  entries 24..31: arc start rows, cell limits

; VERIFIED: 32 pointers to the patched operand/opcode bytes, shared by both value tables.  Each
; points at the exact byte (checked against ViewCirclePatchValues in
; tools/check_routines.py circles/screen-circle-patching).  Line comments: role of the
; target, view value / screen value.
CirclePatchTargets:
    defw L_7D1B                                                                           ; $8505  DrawCircle centre row: $40 / $60
    defw L_7D34                                                                           ; $8507  DrawCircle half height: $40 / $60
    defw L_7D3A                                                                           ; $8509  DrawCircle half width: $78 / $80
    defw L_7D5B                                                                           ; $850B  L_7D56 dx + r test: $78 / $80
    defw L_7D64                                                                           ; $850D  L_7D56 r - dx test: $78 / $80
    defw L_7E1F                                                                           ; $850F  L_7E1E -(half width): $88 / $80
    defw L_7E24                                                                           ; $8511  L_7E22 half width: $78 / $80
    defw L_7EBA                                                                           ; $8513  L_7EB8 half width - 1: $77 / $7F
    defw L_861A                                                                           ; $8515  L_8616 right column: $1E / $1F
    defw L_7FD3                                                                           ; $8517  SetUpLeftClippedSpan left column: $01 / $00
    defw L_7FFA                                                                           ; $8519  LocateSpanLeftEnd SET 7,H: $CB / NOP
    defw L_7FFB                                                                           ; $851B  LocateSpanLeftEnd SET 7,H: $FC / NOP
    defw L_801B                                                                           ; $851D  LocateSpanRightEnd SET 7,H: $CB / NOP
    defw L_801C                                                                           ; $851F  LocateSpanRightEnd SET 7,H: $FC / NOP
    defw L_803B                                                                           ; $8521  StartMidpointAtFarEdge: $88 / $80
    defw L_8639                                                                           ; $8523  L_8635 left column: $01 / $00
    defw L_8644                                                                           ; $8525  L_8640 start x: $F7 / $FF
    defw L_8648                                                                           ; $8527  L_8640 SET 7,H: $CB / NOP
    defw L_8649                                                                           ; $8529  L_8640 SET 7,H: $FC / NOP
    defw L_8669                                                                           ; $852B  L_8640 top limit: $C0 / $28 (no limit)
    defw L_8672                                                                           ; $852D  L_866E start x: $F7 / $FF
    defw L_8676                                                                           ; $852F  L_866E SET 7,H: $CB / NOP
    defw L_8677                                                                           ; $8531  L_866E SET 7,H: $FC / NOP
    defw L_8697                                                                           ; $8533  L_866E bottom limit: $D0 / $58
    defw L_86AA                                                                           ; $8535  DrawCircleLeftArc last row: $CF / $57
    defw L_86A3                                                                           ; $8537  DrawCircleLeftArc row above: $BF / $3F
    defw L_874B                                                                           ; $8539  DrawCirclePairedArcs row above: $BF / $3F
    defw L_8752                                                                           ; $853B  DrawCirclePairedArcs last row: $CF / $57
    defw L_884A                                                                           ; $853D  DrawCircleRightArc last row: $CF / $57
    defw L_8843                                                                           ; $853F  DrawCircleRightArc row above: $BF / $3F
    defw L_8450                                                                           ; $8541  AdjustRowDownAcrossCell limit: $D0 / $58
    defw L_843B                                                                           ; $8543  AdjustRowUpAcrossCell limit: $BF / $3F

; VERIFIED: Expanding filled discs drawn directly on the screen for destroyed object instances.
; Returns if LastActiveObjectEnergy is zero (no slot active).  Switches the fill path to
; the screen top 128 lines (L_809D = $40; PatchDiscRendererTarget with NOP NOP, $50, $4F,
; $3F).  For every slot 0..7 whose +$20 bits 5:4 are 11: FillViewAttributes with L = $0A
; (ink 2, red); CircleOffsetX/Y, CircleFlags and CircleRadius from +$1C..+$1F; 15
; DrawFilledCircle calls, radius += 2 each; FillViewAttributes with L = $0F (ink 7,
; white); clear +$20 bit 4 (state 10).  Then restores the buffer values by falling into
; PatchDiscRendererTarget ($C0, $CF, $BF, SET 7,H, $D0).
; +$20 bit 4 is set when an object is destroyed (player laser L_EC8E, energy bomb L_DAD4,
; L_EB88).  While such an object lies in the current view, RecordExplosionPosition records its projected x/y
; offsets (+$1C/+$1D), $0C + side bits (+$1E) and projected size (+$1F) and sets bit 5.
; Called every frame from L_72FD+28, before BlitViewBitmap copies the buffer over these lines.
; Evidence: tools/check_routines.py circles/screen-circle-patching (discs on the screen, buffer
; untouched, values restored); writers of +$20 bits 4/5; runtime: called every frame.
DrawFlaggedObjectDiscs:
    LD A,(LastActiveObjectEnergy)              ; $8545: 3A 11 DA  nonzero while an instance slot is in use (L_DAA6)
    AND A                                      ; $8548: A7
    RET Z                                      ; $8549: C8
    LD A,$40                                   ; $854A: 3E 40
    LD (L_809D),A                              ; $854C: 32 9D 80  FillViewRowsUp top limit: $40 (screen)
    LD A,$4F                                   ; $854F: 3E 4F
    LD (L_85D7),A                              ; $8551: 32 D7 85  last row high byte for PatchDiscRendererTarget
    LD A,$3F                                   ; $8554: 3E 3F
    LD (L_85E2),A                              ; $8556: 32 E2 85  row above the top for PatchDiscRendererTarget
    LD HL,$0000                                ; $8559: 21 00 00  NOP NOP replaces SET 7,H
    LD A,$50                                   ; $855C: 3E 50  bottom limit: screen line 128
    CALL PatchDiscRendererTarget               ; $855E: CD C4 85
    LD IX,InitialRuntimeState                  ; $8561: DD 21 48 60  slot 0
    LD B,$08                                   ; $8565: 06 08  8 slots

; VERIFIED: Per-slot loop of DrawFlaggedObjectDiscs (B = 8 slots, IX += 39).
L_8567:
    PUSH BC                                    ; $8567: C5
    LD A,(IX+$20)                              ; $8568: DD 7E 20
    LD C,A                                     ; $856B: 4F
    AND $30                                    ; $856C: E6 30  +$20 bits 4 and 5 both set
    CP $30                                     ; $856E: FE 30
    JR NZ,L_85A8                               ; $8570: 20 36  bits 5:4 not 11: skip the slot
    LD L,$0A                                   ; $8572: 2E 0A  attribute $0A (ink 2, red) for FillViewAttributes
    CALL FillViewAttributes                    ; $8574: CD 87 92
    LD H,(IX+$1C)                              ; $8577: DD 66 1C  +$1C/+$1D -> CircleOffsetX/Y
    LD L,(IX+$1D)                              ; $857A: DD 6E 1D
    LD (CircleOffsetY),HL                      ; $857D: 22 3A 7C
    LD L,(IX+$1E)                              ; $8580: DD 6E 1E  +$1E/+$1F -> CircleFlags/CircleRadius
    LD H,(IX+$1F)                              ; $8583: DD 66 1F
    LD (CircleFlags),HL                        ; $8586: 22 3C 7C
    LD C,$0F                                   ; $8589: 0E 0F  15 discs

; VERIFIED: Draw 15 discs: DrawFilledCircle, CircleRadius += 2.
L_858B:
    PUSH IX                                    ; $858B: DD E5
    PUSH BC                                    ; $858D: C5
    CALL DrawFilledCircle                      ; $858E: CD F0 7C
    POP BC                                     ; $8591: C1
    POP IX                                     ; $8592: DD E1
    LD A,(CircleRadius)                        ; $8594: 3A 3D 7C
    ADD A,$02                                  ; $8597: C6 02  radius + 2
    LD (CircleRadius),A                        ; $8599: 32 3D 7C
    DEC C                                      ; $859C: 0D
    JR NZ,L_858B                               ; $859D: 20 EC
    LD L,$0F                                   ; $859F: 2E 0F  attribute $0F (ink 7, white) for FillViewAttributes
    CALL FillViewAttributes                    ; $85A1: CD 87 92
    RES 4,(IX+$20)                             ; $85A4: DD CB 20 A6  done: bits 5:4 = 10
L_85A8:
    LD DE,InstanceSize                         ; $85A8: 11 27 00  39 = instance slot size
    ADD IX,DE                                  ; $85AB: DD 19
    POP BC                                     ; $85AD: C1
    DJNZ L_8567                                ; $85AE: 10 B7
    LD A,$C0                                   ; $85B0: 3E C0  restore the buffer values
    LD (L_809D),A                              ; $85B2: 32 9D 80
    LD A,$CF                                   ; $85B5: 3E CF
    LD (L_85D7),A                              ; $85B7: 32 D7 85
    LD A,$BF                                   ; $85BA: 3E BF
    LD (L_85E2),A                              ; $85BC: 32 E2 85
    LD HL,$FCCB                                ; $85BF: 21 CB FC  $CB,$FC = SET 7,H opcode bytes
    LD A,$D0                                   ; $85C2: 3E D0  bottom limit: buffer end $D0

; VERIFIED: Patch the filled-disc path.  HL = two opcode bytes for the SET 7,H sites in
; LocateSpanLeftEnd, LocateSpanRightEnd, FillViewRowsUp and FillViewRowsDown ($CB,$FC =
; SET 7,H for the buffer; 0,0 = NOP NOP for the screen); A = bottom limit for
; FillViewRowsDown and AdjustRowDownAcrossCell.  The operands at L_85D7 (last row high
; byte) and L_85E2 (row above the top) are set by the caller and copied into the three
; fill loops (and AdjustRowUpAcrossCell).  The image holds the screen values $4F/$3F
; there; after the first restore they hold $CF/$BF.
PatchDiscRendererTarget:
    LD (L_7FFA),HL                             ; $85C4: 22 FA 7F  SET 7,H site in LocateSpanLeftEnd
    LD (L_801B),HL                             ; $85C7: 22 1B 80  SET 7,H site in LocateSpanRightEnd
    LD (L_8060),HL                             ; $85CA: 22 60 80  SET 7,H site in FillViewRowsUp
    LD (L_80AB),HL                             ; $85CD: 22 AB 80  SET 7,H site in FillViewRowsDown
    LD (L_80E8),A                              ; $85D0: 32 E8 80  bottom limit of FillViewRowsDown
    LD (L_8450),A                              ; $85D3: 32 50 84  bottom limit of AdjustRowDownAcrossCell
L_85D6:
defc L_85D7 = L_85D6 + 1 ; byte inside instruction at $85D6
    LD A,$4F                                   ; $85D6: 3E 4F  SMC parameter: $4F (screen) / $CF (buffer), set by the caller
    LD (L_833F),A                              ; $85D8: 32 3F 83  start check of FillDiscRowsRightClipped
    LD (L_8129),A                              ; $85DB: 32 29 81  start check of FillDiscRows
    LD (L_8236),A                              ; $85DE: 32 36 82  start check of FillDiscRowsLeftClipped
L_85E1:
defc L_85E2 = L_85E1 + 1 ; byte inside instruction at $85E1
    LD A,$3F                                   ; $85E1: 3E 3F  SMC parameter: $3F (screen) / $BF (buffer), set by the caller
    LD (L_8338),A                              ; $85E3: 32 38 83  start check of FillDiscRowsRightClipped
    LD (L_8122),A                              ; $85E6: 32 22 81  start check of FillDiscRows
    LD (L_822F),A                              ; $85E9: 32 2F 82  start check of FillDiscRowsLeftClipped
    LD (L_843B),A                              ; $85EC: 32 3B 84  top limit of AdjustRowUpAcrossCell
    RET                                        ; $85EF: C9

; INFERRED: Two bytes ($01,$3D) with no static or runtime reference and no decoded path into them.
; Plausibly unused filler before FilledSpanPattern.
L_85F0:
    defb $01,$3D                                                                          ; $85F0 .=

; VERIFIED: Word $FFFF loaded into AF (LD SP,FilledSpanPattern; POP AF) by the three fill loops;
; each PUSH AF then writes two set bytes.
FilledSpanPattern:
    defb $FF,$FF                                                                          ; $85F2 ..

; VERIFIED: Outline-mode tail of L_7F0E: right end = column 30 ($1E, not patched), C = 1 (x 247),
; then DrawCircleRowsDownRightClipped or DrawCircleRowsUpRightClipped by CircleFlags bit 1.
L_85F4:
    LD A,E                                     ; $85F4: 7B
    AND $E0                                    ; $85F5: E6 E0  start of the row in E
    OR $1E                                     ; $85F7: F6 1E  right end: column 30 (x 240..247)
    LD L,A                                     ; $85F9: 6F
    LD C,$01                                   ; $85FA: 0E 01  its last pixel (x 247)
    LD A,(CircleFlags)                         ; $85FC: 3A 3C 7C
    BIT 1,A                                    ; $85FF: CB 4F  bit 1: centre above the view
    CALL NZ,DrawCircleRowsDownRightClipped     ; $8601: C4 4B 7C  CircleFlags bit 1 set: rows downwards
    CALL Z,DrawCircleRowsUpRightClipped        ; $8604: CC 63 7C  bit 1 clear: rows upwards (AF comes back intact, so only one call runs)
    RET                                        ; $8607: C9

; ============================================================================
; Outline circle plotting
; Outline branches of the circle renderer at DrawCircle (CircleOutlineFlag = 1): planet outline in
; the view buffer, chart circles directly on the screen (limits patched by DrawScreenCircle).
; ============================================================================

; VERIFIED: Tail of the circle code at L_7F41 (reached by JP) for a circle cut by the left edge
; of the view: E is already column 1 of the start row; B = $80 is the pixel at the left
; edge (x 8), used once the left side of the outline comes into view.  Then draw the
; right-hand arc downwards (DrawCircleRowsDownLeftClipped) when bit 1 of CircleFlags is set, otherwise upwards (DrawCircleRowsUpLeftClipped).
; The arc routines restore AF, so exactly one of the two conditional calls runs.
; Evidence: instruction semantics; runtime: executed in flight scenarios;
; tools/check_routines.py circles/outline-arcs (circles beyond the left edge).
L_8608:
    LD B,$80                                   ; $8608: 06 80  B = $80: pixel at the left view edge (byte E = column 1)
    LD A,(CircleFlags)                         ; $860A: 3A 3C 7C
