; $502A (character row 1, columns 10..20), patch CopyScannerBackground back to the buffer ->
; screen direction (the original image bytes) and copy the saved 624 bytes back.
; Evidence: tools/check_routines.py scanner/scanner-background (no effect for flag values 0,
; 2, $FF; exact restore otherwise).
RestoreScannerBackground:
    LD A,(ScannerContactsDrawn)                ; $8E1D: 3A 14 8C
    DEC A                                      ; $8E20: 3D
    RET NZ                                     ; $8E21: C0  runs only when the flag is exactly 1
    LD (ScannerContactsDrawn),A                ; $8E22: 32 14 8C  A = 0: flag cleared
    XOR A                                      ; $8E25: AF  clear the stick area above the scanner
    LD C,$08                                   ; $8E26: 0E 08  8 pixel rows x 11 bytes
    LD HL,$502A                                ; $8E28: 21 2A 50  character row 1, column 10 of the bottom third
L_8E2B:
    LD B,$0B                                   ; $8E2B: 06 0B
    PUSH HL                                    ; $8E2D: E5
L_8E2E:
    LD (HL),A                                  ; $8E2E: 77
    INC L                                      ; $8E2F: 2C
    DJNZ L_8E2E                                ; $8E30: 10 FC
    POP HL                                     ; $8E32: E1
    INC H                                      ; $8E33: 24
    DEC C                                      ; $8E34: 0D
    JR NZ,L_8E2B                               ; $8E35: 20 F4
    LD BC,ScannerCopyPushLine-ScannerCopyPushRow ; $8E37: 01 05 00
    XOR A                                      ; $8E3A: AF  A = 0: NOP opcode
    LD HL,ScannerCopySwapStart                 ; $8E3B: 21 62 8E
    LD (HL),A                                  ; $8E3E: 77  patch ScannerCopySwapStart = NOP
    LD A,$D5                                   ; $8E3F: 3E D5  PUSH DE
    LD HL,ScannerCopyPushRow                   ; $8E41: 21 65 8E
    LD (HL),A                                  ; $8E44: 77  patch ScannerCopyPushRow
    ADD HL,BC                                  ; $8E45: 09
    LD (HL),A                                  ; $8E46: 77  patch ScannerCopyPushLine
    LD A,$D1                                   ; $8E47: 3E D1  POP DE
    LD HL,ScannerCopyNextLine                  ; $8E49: 21 85 8E
    LD (HL),A                                  ; $8E4C: 77  patch ScannerCopyNextLine
    INC HL                                     ; $8E4D: 23
    LD A,$14                                   ; $8E4E: 3E 14  INC D
    LD (HL),A                                  ; $8E50: 77  patch the INC after the POP
    LD A,$EB                                   ; $8E51: 3E EB  EX DE,HL
    LD HL,ScannerCopyRowSwap                   ; $8E53: 21 90 8E
    LD (HL),A                                  ; $8E56: 77  patch ScannerCopyRowSwap
    XOR A                                      ; $8E57: AF  A = 0: NOP opcode
    LD HL,ScannerCopySwapEnd                   ; $8E58: 21 89 8E
    LD (HL),A                                  ; $8E5B: 77  patch ScannerCopySwapEnd = NOP

; VERIFIED: Copy 6 character rows x 8 pixel rows x 13 bytes between the screen ($5049) and
; ScannerBackupBuffer ($5B00).  Self-modified by
; SaveScannerBackground/RestoreScannerBackground:
;                 save (screen -> buffer)        restore (buffer -> screen, image bytes)
;   $8E62         EX DE,HL                       NOP
;   $8E65/$8E6A   PUSH HL                        PUSH DE
;   $8E85/$8E86   POP HL / INC H                 POP DE / INC D
;   $8E89         EX DE,HL                       NOP
;   $8E90         NOP                            EX DE,HL
; C = $FF keeps the 104 LDI decrements per row group from borrowing into the DJNZ counter B.
; Evidence: tools/check_routines.py scanner/scanner-background; smc.txt (runtime writes from
; $8DFD..$8E5B).
CopyScannerBackground:
    LD DE,ScannerBackupScreen                  ; $8E5C: 11 49 50  screen: character row 2, column 9 of the bottom third
    LD HL,ScannerBackupBuffer                  ; $8E5F: 21 00 5B  saved background (624 bytes)

; VERIFIED: SMC: NOP (restore) or EX DE,HL (save); see CopyScannerBackground.
ScannerCopySwapStart:
    NOP                                        ; $8E62: 00
    LD A,$06                                   ; $8E63: 3E 06  6 character rows

; VERIFIED: SMC: PUSH DE (restore) or PUSH HL (save): keeps the screen row start.
ScannerCopyPushRow:
    PUSH DE                                    ; $8E65: D5
    LD B,$08                                   ; $8E66: 06 08  8 pixel rows
    LD C,$FF                                   ; $8E68: 0E FF  C = $FF: the 13 LDIs never borrow into B

; VERIFIED: SMC: PUSH DE (restore) or PUSH HL (save): keeps the pixel-line start.
ScannerCopyPushLine:
    PUSH DE                                    ; $8E6A: D5
    LDI                                        ; $8E6B: ED A0  13 bytes of one pixel line
    LDI                                        ; $8E6D: ED A0
    LDI                                        ; $8E6F: ED A0
    LDI                                        ; $8E71: ED A0
    LDI                                        ; $8E73: ED A0
    LDI                                        ; $8E75: ED A0
    LDI                                        ; $8E77: ED A0
    LDI                                        ; $8E79: ED A0
    LDI                                        ; $8E7B: ED A0
    LDI                                        ; $8E7D: ED A0
    LDI                                        ; $8E7F: ED A0
    LDI                                        ; $8E81: ED A0
    LDI                                        ; $8E83: ED A0

; VERIFIED: SMC: POP DE / INC D (restore) or POP HL / INC H (save): next pixel line.
ScannerCopyNextLine:
    POP DE                                     ; $8E85: D1
    INC D                                      ; $8E86: 14
    DJNZ ScannerCopyPushLine                   ; $8E87: 10 E1

; VERIFIED: SMC: NOP (restore) or EX DE,HL (save) before the row pointer is popped.
ScannerCopySwapEnd:
    NOP                                        ; $8E89: 00
    POP DE                                     ; $8E8A: D1  row start
    EX DE,HL                                   ; $8E8B: EB
    LD BC,$0020                                ; $8E8C: 01 20 00  next character row
    ADD HL,BC                                  ; $8E8F: 09

; VERIFIED: SMC: EX DE,HL (restore) or NOP (save) after the +$20 row step.
ScannerCopyRowSwap:
    EX DE,HL                                   ; $8E90: EB
    DEC A                                      ; $8E91: 3D
    JR NZ,ScannerCopyPushRow                   ; $8E92: 20 D1
    RET                                        ; $8E94: C9

; ============================================================================
; Screen selection keys and freeze-mode options
; ============================================================================

; VERIFIED: Screen/view keys (called from the main loop at L_7290), ignored while TunnelLoopActive is
; set:
; - KeyFlagsViews bits 0..3 = keys 1..4 (lowest set bit n): docked (FlightCondition = 0) key 1 calls
;   StartStationTunnel (launch), keys 2..4 select screens 4..6 and call handlers 0..2 (buy cargo, sell
;   cargo, equip ship) through CallScreenHandler; in flight keys 1..4 select cockpit views
;   0..3 (SelectScreen only, no handler).
; - otherwise KeyFlagsScreens bits 5..0 = keys I, O, P, K, L, ENTER select screens 7..12 and call
;   handlers 3..8 (galactic chart, short-range chart, system data, market prices, commander
;   status, inventory), docked or in flight.
; Both bytes are cleared afterwards (ClearViewAndScreenKeys).
; Evidence: instruction semantics; key bits from KeyActionTable (input/scan-keyboard);
; tools/check_routines.py input/p3-screen-keys presses every key through ScanKeyboard and
; checks the screen and handler; runtime: docked and flight screen scenarios.
HandleScreenKeys:
    LD A,(TunnelLoopActive)                    ; $8E95: 3A 0B A8  non-zero: screen keys ignored
    AND A                                      ; $8E98: A7
    RET NZ                                     ; $8E99: C0
    LD A,(KeyFlagsViews)                       ; $8E9A: 3A 10 FC  keys 1..4 (bits 0..3)
    AND $0F                                    ; $8E9D: E6 0F
    JR Z,L_8EDB                                ; $8E9F: 28 3A  none: try the screen keys
    LD C,$00                                   ; $8EA1: 0E 00  C = key number - 1
    SRL A                                      ; $8EA3: CB 3F
    JR C,L_8ECB                                ; $8EA5: 38 24  key 1
    INC C                                      ; $8EA7: 0C
    SRL A                                      ; $8EA8: CB 3F
    JR C,L_8EB2                                ; $8EAA: 38 06  key 2
    INC C                                      ; $8EAC: 0C
    SRL A                                      ; $8EAD: CB 3F
    JR C,L_8EB2                                ; $8EAF: 38 01  key 3; otherwise key 4
    INC C                                      ; $8EB1: 0C
L_8EB2:
    LD A,(FlightCondition)                     ; $8EB2: 3A 62 70  0 = docked
    AND A                                      ; $8EB5: A7
    JR NZ,L_8EC6                               ; $8EB6: 20 0E  in flight: cockpit view C
    LD A,$03                                   ; $8EB8: 3E 03  docked: screens 4..6
    ADD A,C                                    ; $8EBA: 81
    LD C,A                                     ; $8EBB: 4F
    CALL SelectScreen                          ; $8EBC: CD 21 8F  screen 4..6; A = C
    SUB $04                                    ; $8EBF: D6 04  handler index 0..2: buy, sell, equip
    CALL CallScreenHandler                     ; $8EC1: CD 02 8F
    JR ClearViewAndScreenKeys                  ; $8EC4: 18 32
L_8EC6:
    CALL SelectScreen                          ; $8EC6: CD 21 8F
    JR ClearViewAndScreenKeys                  ; $8EC9: 18 2D
L_8ECB:
    LD A,(FlightCondition)                     ; $8ECB: 3A 62 70
    AND A                                      ; $8ECE: A7
    JR NZ,L_8ED6                               ; $8ECF: 20 05  in flight: front view
    CALL StartStationTunnel                    ; $8ED1: CD F8 7A  docked key 1: launch
    JR ClearViewAndScreenKeys                  ; $8ED4: 18 22
L_8ED6:
    CALL SelectScreen                          ; $8ED6: CD 21 8F
    JR ClearViewAndScreenKeys                  ; $8ED9: 18 1D
L_8EDB:
    LD A,(KeyFlagsScreens)                     ; $8EDB: 3A 0E FC  screen keys, bits 5..0 -> screens 7..12
    AND $3F                                    ; $8EDE: E6 3F  I, O, P, K, L, ENTER
    ADD A,A                                    ; $8EE0: 87
    RET Z                                      ; $8EE1: C8  none pressed
    ADD A,A                                    ; $8EE2: 87
    LD BC,$0607                                ; $8EE3: 01 07 06  B = 6 keys, C = 7 for I
L_8EE6:
    ADD A,A                                    ; $8EE6: 87  highest key bit first: I 7, O 8, P 9, K 10, L 11, ENTER 12
    JR C,L_8EEC                                ; $8EE7: 38 03
    INC C                                      ; $8EE9: 0C
    DJNZ L_8EE6                                ; $8EEA: 10 FA
L_8EEC:
    CALL SelectScreen                          ; $8EEC: CD 21 8F
    CP $07                                     ; $8EEF: FE 07  A < 7 would mean refused (not possible for 7..12)
    JR C,ClearViewAndScreenKeys                ; $8EF1: 38 05
    SUB $04                                    ; $8EF3: D6 04  handler index 3..8
    CALL CallScreenHandler                     ; $8EF5: CD 02 8F

; VERIFIED: Clear the key bytes KeyFlagsViews and KeyFlagsScreens and return.
; Evidence: instruction semantics; tools/check_routines.py input/p3-screen-keys.
ClearViewAndScreenKeys:
    XOR A                                      ; $8EF8: AF
    LD (KeyFlagsViews),A                       ; $8EF9: 32 10 FC
    LD (KeyFlagsScreens),A                     ; $8EFC: 32 0E FC
    RET                                        ; $8EFF: C9

; VERIFIED: Caller SP saved by CallScreenHandler while the handler runs on the temporary
; stack.
; Evidence: write at $8F02, read at $8F1A.
ScreenHandlerSavedSP:
    defw $0000                                                                            ; $8F00

; VERIFIED: Run screen handler A (0..8) from the JP table ScreenFunctionTable (3 bytes per entry) on a
; temporary stack that ends at CockpitBitmap: saves SP in ScreenHandlerSavedSP, patches the
; CALL operand at ScreenHandlerCall with ScreenFunctionTable + 3*A, calls it, restores SP and jumps to
; ClearLatchedKeys (clears the 5 key bytes from KeyFlagsScreens).
; Handlers: 0 BuyCargoScreen, 1 SellCargoScreen ("SELL"), 2 EquipShipScreen ("EQUIP SHIP"), 3 DrawGalacticChart, 4 DrawShortRangeChart, 5
; DisplaySystemData (system data), 6 ShowMarketPrices (market), 7 ShowCommanderStatus (status), 8 ShowInventory (inventory).
; Other callers: L_7158 (index 9 + the number of the lowest set bit of A) and L_7B43 (7).
; Evidence: instruction semantics; smc.txt ($8F17 written by $8F14); runtime: docked
; screens; tools/check_routines.py input/p3-screen-keys (table entries 0..8).
CallScreenHandler:
    LD (ScreenHandlerSavedSP),SP               ; $8F02: ED 73 00 8F
    LD SP,CockpitBitmap                        ; $8F06: 31 00 C8  temporary stack ends where the saved cockpit bitmap starts
    LD B,A                                     ; $8F09: 47
    ADD A,A                                    ; $8F0A: 87  A*3: JP table entry size
    ADD A,B                                    ; $8F0B: 80
    LD HL,ScreenFunctionTable                  ; $8F0C: 21 DA A7
    ADD A,L                                    ; $8F0F: 85  HL = ScreenFunctionTable + 3*A
    LD L,A                                     ; $8F10: 6F
    JR NC,L_8F14                               ; $8F11: 30 01
    INC H                                      ; $8F13: 24
L_8F14:
    LD (ScreenHandlerCallTarget),HL            ; $8F14: 22 18 8F  patch the CALL operand below

; VERIFIED: SMC: CALL operand replaced by CallScreenHandler with ScreenFunctionTable + 3*index.
ScreenHandlerCall:
; VERIFIED: SMC: CALL operand, set by CallScreenHandler to ScreenFunctionTable + 3*index.
defc ScreenHandlerCallTarget = ScreenHandlerCall + 1 ; byte inside instruction at $8F17
    CALL ScreenHandlerCall                     ; $8F17: CD 17 8F
    LD SP,(ScreenHandlerSavedSP)               ; $8F1A: ED 7B 00 8F  back to the caller's stack
    JP ClearLatchedKeys                        ; $8F1E: C3 09 7C  clear the key bytes and return

; VERIFIED: Make C the current screen (CurrentScreenId).  Pressing the key of the screen
; already shown does nothing for C >= 7 (drops the caller's return address and clears the
; keys).  While JumpTunnelMode is non-zero cockpit views 1..3 are refused (CurrentScreenId = 0, A =
; 0).  When the change is from a cockpit view (0..3) to a full screen (>= 4), the clean
; cockpit is saved (SaveCleanCockpit).  Output: A = C (0 in the refused case).
; Screens 4..6 are redrawn when selected again.
; Evidence: instruction semantics; runtime: screen-change scenarios;
; tools/check_routines.py input/p3-screen-keys.
SelectScreen:
    LD A,(CurrentScreenId)                     ; $8F21: 3A 41 70
    LD B,A                                     ; $8F24: 47  B = old screen
    CP C                                       ; $8F25: B9
    JR NZ,L_8F30                               ; $8F26: 20 08  different screen: change it
    LD A,C                                     ; $8F28: 79
    CP $07                                     ; $8F29: FE 07  static screens are not redrawn
    JR C,L_8F30                                ; $8F2B: 38 03
    POP HL                                     ; $8F2D: E1  drop the caller, clear the keys
    JR ClearViewAndScreenKeys                  ; $8F2E: 18 C8
L_8F30:
    LD A,(JumpTunnelMode)                      ; $8F30: 3A 0A A8  non-zero: cockpit views 1..3 refused
    AND A                                      ; $8F33: A7
    LD A,C                                     ; $8F34: 79
    JR NZ,L_8F5E                               ; $8F35: 20 27
L_8F37:
    LD (CurrentScreenId),A                     ; $8F37: 32 41 70  new current screen
    LD A,B                                     ; $8F3A: 78
    CP $04                                     ; $8F3B: FE 04  old screen a full screen?
    LD A,C                                     ; $8F3D: 79
    RET NC                                     ; $8F3E: D0  old screen is a full screen: no cockpit to save
    CP $04                                     ; $8F3F: FE 04  new screen a cockpit view?
    RET C                                      ; $8F41: D8

; VERIFIED: Restore the scanner background (RestoreScannerBackground), then fall into
; SaveCockpitBitmap and SaveCockpitAttributes.  AF preserved.
; Evidence: instruction semantics; callers L_71A2, StartNewGame, L_7B43, SelectScreen.
SaveCleanCockpit:
    PUSH AF                                    ; $8F42: F5
    CALL RestoreScannerBackground              ; $8F43: CD 1D 8E  remove the contacts before saving
    POP AF                                     ; $8F46: F1

; VERIFIED: save the current cockpit bitmap into the reused CockpitBitmap buffer.
SaveCockpitBitmap:
    LD DE,CockpitBitmap                        ; $8F47: 11 00 C8
    LD HL,ScreenCockpitBitmap                  ; $8F4A: 21 00 50
    LD BC,CockpitBitmapSize                    ; $8F4D: 01 00 08
    LDIR                                       ; $8F50: ED B0

; VERIFIED: save the current cockpit colours into the runtime attribute buffer.
SaveCockpitAttributes:
    LD DE,CockpitAttributesRuntime             ; $8F52: 11 00 5B
    LD HL,ScreenCockpitAttributes              ; $8F55: 21 00 5A
    LD BC,CockpitAttributesSize                ; $8F58: 01 00 01
    LDIR                                       ; $8F5B: ED B0

; Bitmap and attribute backup copies are complete.
CockpitSaved:
    RET                                        ; $8F5D: C9

; VERIFIED: JumpTunnelMode set: allow screens >= 4, otherwise force CurrentScreenId = 0 and return A =
; 0.
; Evidence: instruction semantics; tools/check_routines.py input/p3-screen-keys.
L_8F5E:
    CP $04                                     ; $8F5E: FE 04
    JR NC,L_8F37                               ; $8F60: 30 D5
    XOR A                                      ; $8F62: AF
    LD (CurrentScreenId),A                     ; $8F63: 32 41 70  refused: front view, A = 0
    RET                                        ; $8F66: C9

; VERIFIED: Control type chosen on the title screen ($7219: 1, 2 or 3 when a joystick
; direction was held; not written when SPACE selects the keyboard); its low two bits are the
; joystick value of the options byte ControlOptions bits 0..1.  ToggleControlDevice XORs it into
; ControlOptions to swap between keyboard (0) and that joystick.
; Evidence: write at $7219, reads at $8FFA/$9002.
SelectedJoystickType:
    defb $00                                                                              ; $8F67 .

; VERIFIED: Freeze loop, entered when KeyFlagsViews bit 7 (CAPS SHIFT) is set: wait for no key
; (LastKeyCode = $FF), then for each key code: B, D, F, K, Q, R, S, Y run the option handlers
; below (each returns A = 0, which plays PlayOptionBeep); SPACE returns with carry clear
; (continue), 1 returns with carry set (the caller at $7296 restarts the game).  Both clear
; the key bytes (ClearKeyFlags).  Any other key is ignored.  One HALT per poll.
; Evidence: instruction semantics (key codes $42, $44, $46, $4B, $51, $52, $53, $59, $31,
; $20); caller at $7293; CAPS SHIFT -> KeyFlagsViews bit 7 in KeyActionTable;
; tools/check_routines.py input/p3-freeze-options.
HandleFreezeMode:
    LD A,(KeyFlagsViews)                       ; $8F68: 3A 10 FC  bit 7: CAPS SHIFT freeze key
    AND $80                                    ; $8F6B: E6 80
    RET Z                                      ; $8F6D: C8
    LD HL,ControlOptions                       ; $8F6E: 21 14 FC  HL = options byte for the handlers
L_8F71:
    HALT                                       ; $8F71: 76
    LD A,(LastKeyCode)                         ; $8F72: 3A 13 FC  wait until no key is pressed
    INC A                                      ; $8F75: 3C
    JR NZ,L_8F71                               ; $8F76: 20 F9
L_8F78:
    HALT                                       ; $8F78: 76
    LD A,(LastKeyCode)                         ; $8F79: 3A 13 FC
    CP $FF                                     ; $8F7C: FE FF
    JR Z,L_8F78                                ; $8F7E: 28 F8  wait for a key
    CP $42                                     ; $8F80: FE 42  'B'
    CALL Z,ToggleFreezeOptionB                 ; $8F82: CC C9 8F  reverse roll and pitch keys
    CP $44                                     ; $8F85: FE 44  'D'
    CALL Z,ToggleFreezeOptionD                 ; $8F87: CC CF 8F  control damping
    CP $46                                     ; $8F8A: FE 46  'F'
    CALL Z,ToggleFreezeOptionF                 ; $8F8C: CC D5 8F  forced mis-jump
    CP $4B                                     ; $8F8F: FE 4B  'K'
    CALL Z,ToggleControlDevice                 ; $8F91: CC F6 8F  keyboard <-> joystick
    CP $51                                     ; $8F94: FE 51  'Q'
    CALL Z,SelectSoundOff                      ; $8F96: CC DB 8F  sound off
    CP $52                                     ; $8F99: FE 52  'R'
    CALL Z,ToggleFreezeOptionR                 ; $8F9B: CC E1 8F  recentring
    CP $53                                     ; $8F9E: FE 53  'S'
    CALL Z,SelectSoundOn                       ; $8FA0: CC E7 8F  sound on
    CP $59                                     ; $8FA3: FE 59  'Y'
    CALL Z,ToggleFreezeOptionY                 ; $8FA5: CC F0 8F  reverse the pitch keys
    CP $31                                     ; $8FA8: FE 31  '1': new game
    JR Z,RequestNewGame                        ; $8FAA: 28 18
    CP $20                                     ; $8FAC: FE 20  SPACE: continue
    JR Z,ClearKeyFlags                         ; $8FAE: 28 06
    AND A                                      ; $8FB0: A7  A = 0 after an option handler: beep
    CALL Z,PlayOptionBeep                      ; $8FB1: CC 09 90
    JR L_8F71                                  ; $8FB4: 18 BB

; VERIFIED: Zero the five key bytes KeyFlagsScreens..KeyFlagsChart (A = 0, carry clear).
; Evidence: instruction semantics.
ClearKeyFlags:
    LD HL,KeyFlagsScreens                      ; $8FB6: 21 0E FC  KeyFlagsScreens and the four bytes after it
    XOR A                                      ; $8FB9: AF
    LD (HL),A                                  ; $8FBA: 77
    INC HL                                     ; $8FBB: 23
    LD (HL),A                                  ; $8FBC: 77
    INC HL                                     ; $8FBD: 23
    LD (HL),A                                  ; $8FBE: 77
    INC HL                                     ; $8FBF: 23
    LD (HL),A                                  ; $8FC0: 77
    INC HL                                     ; $8FC1: 23
    LD (HL),A                                  ; $8FC2: 77
    RET                                        ; $8FC3: C9

; VERIFIED: Freeze-mode key 1: ClearKeyFlags, return with carry set (start a new game).
; Evidence: instruction semantics; caller at $7296 jumps to RunTitleScreen on carry.
RequestNewGame:
    CALL ClearKeyFlags                         ; $8FC4: CD B6 8F
    SCF                                        ; $8FC7: 37  carry set: new game
    RET                                        ; $8FC8: C9

; VERIFIED: Freeze-mode key B: toggle bit 4 of ControlOptions.  While it is set the input scan (L_FC69)
; swaps the two roll key bits and the two pitch key bits, reversing both control axes
; (the Kempston path inverts the sense of both swap bits).
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options (N/M and
; X/S swapped through ScanKeyboard).
ToggleFreezeOptionB:
    LD A,(HL)                                  ; $8FC9: 7E
    XOR $10                                    ; $8FCA: EE 10
    LD (HL),A                                  ; $8FCC: 77
    XOR A                                      ; $8FCD: AF  A = 0: the freeze loop beeps
    RET                                        ; $8FCE: C9

; VERIFIED: Freeze-mode key D: toggle bit 3 of ControlOptions.  While it is set UpdateFlightControls lets
; roll and pitch decay towards zero when no direction key is held; clear, they keep their
; value.
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options,
; controls/update-flight-controls.
ToggleFreezeOptionD:
    LD A,(HL)                                  ; $8FCF: 7E
    XOR $08                                    ; $8FD0: EE 08
    LD (HL),A                                  ; $8FD2: 77
    XOR A                                      ; $8FD3: AF
    RET                                        ; $8FD4: C9

; VERIFIED: Freeze-mode key F: toggle bit 6 of ControlOptions.  NormalHyperspaceJump tests it at $D680:
; while it is set every normal jump takes the mis-jump path (EnterHyperspaceMisjump).
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options.
ToggleFreezeOptionF:
    LD A,(HL)                                  ; $8FD5: 7E
    XOR $40                                    ; $8FD6: EE 40
    LD (HL),A                                  ; $8FD8: 77
    XOR A                                      ; $8FD9: AF
    RET                                        ; $8FDA: C9

; VERIFIED: Freeze-mode key Q: clear bit 7 of ControlOptions (sound effects off; every player checks
; this bit).  Pending requests stay in SoundEffectRequests.
; Evidence: all players (PlayLongNoiseSweep, PlayRisingNoiseSweep, PlayFallingNoiseSweep,
; PlayNoiseBurst, UpdateSoundEffect) return at once when bit 7 is clear;
; tools/check_routines.py input/p3-freeze-options.
SelectSoundOff:
    LD A,(HL)                                  ; $8FDB: 7E
    AND $7F                                    ; $8FDC: E6 7F
    LD (HL),A                                  ; $8FDE: 77
    XOR A                                      ; $8FDF: AF
    RET                                        ; $8FE0: C9

; VERIFIED: Freeze-mode key R: toggle bit 2 of ControlOptions.  While it is set UpdateFlightControls
; resets roll or pitch to zero at once when the opposite direction key is pressed;
; clear, the control moves back one step per frame.
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options,
; controls/update-flight-controls.
ToggleFreezeOptionR:
    LD A,(HL)                                  ; $8FE1: 7E
    XOR $04                                    ; $8FE2: EE 04
    LD (HL),A                                  ; $8FE4: 77
    XOR A                                      ; $8FE5: AF
    RET                                        ; $8FE6: C9

; VERIFIED: Freeze-mode key S: set bit 7 of ControlOptions (sound on) and clear the pending sound
; requests SoundEffectRequests.
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options.
SelectSoundOn:
    LD A,(HL)                                  ; $8FE7: 7E
    OR $80                                     ; $8FE8: F6 80
    LD (HL),A                                  ; $8FEA: 77
    XOR A                                      ; $8FEB: AF
    LD (SoundEffectRequests),A                 ; $8FEC: 32 7D 70
    RET                                        ; $8FEF: C9

; VERIFIED: Freeze-mode key Y: toggle bit 5 of ControlOptions.  While it is set the input scan (L_FC7A)
; swaps the two pitch key bits only (vertical control reversed).
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options (X/S
; swapped through ScanKeyboard).
ToggleFreezeOptionY:
    LD A,(HL)                                  ; $8FF0: 7E
    XOR $20                                    ; $8FF1: EE 20
    LD (HL),A                                  ; $8FF3: 77
    XOR A                                      ; $8FF4: AF
    RET                                        ; $8FF5: C9

; VERIFIED: Freeze-mode key K: ControlOptions ^= SelectedJoystickType when ControlOptions bits 0..1 are
; non-zero (joystick -> keyboard) or when SelectedJoystickType is non-zero (keyboard ->
; joystick).  With no joystick chosen nothing changes, but the beep still sounds.
; Evidence: instruction semantics; tools/check_routines.py input/p3-freeze-options.
ToggleControlDevice:
    LD A,(HL)                                  ; $8FF6: 7E
    LD D,A                                     ; $8FF7: 57
    AND $03                                    ; $8FF8: E6 03  joystick selected?
    LD A,(SelectedJoystickType)                ; $8FFA: 3A 67 8F
    JR NZ,L_9002                               ; $8FFD: 20 03  yes: back to the keyboard
    AND A                                      ; $8FFF: A7
    JR Z,L_9007                                ; $9000: 28 05  keyboard and no joystick chosen: no change
L_9002:
    LD A,(SelectedJoystickType)                ; $9002: 3A 67 8F
    XOR D                                      ; $9005: AA  toggle the device bits
    LD (HL),A                                  ; $9006: 77
L_9007:
    XOR A                                      ; $9007: AF
    RET                                        ; $9008: C9

; VERIFIED: Confirmation beep: 6 frames (HALT), each with 4 speaker pulses (OUT $FE = $30 then
; 0) whose length E = 2*E + 5 grows from pulse to pulse.  Clobbers AF, BC, E.
; Evidence: instruction semantics.
PlayOptionBeep:
    LD B,$06                                   ; $9009: 06 06
    LD E,$00                                   ; $900B: 1E 00
L_900D:
    PUSH BC                                    ; $900D: C5
    HALT                                       ; $900E: 76  one frame per group of pulses
    LD C,$04                                   ; $900F: 0E 04
L_9011:
    LD A,E                                     ; $9011: 7B
    ADD A,A                                    ; $9012: 87
    ADD A,$05                                  ; $9013: C6 05  E = 2*E + 5: longer pulses
    LD E,A                                     ; $9015: 5F
    LD B,A                                     ; $9016: 47
    LD A,$30                                   ; $9017: 3E 30  speaker bit on
    OUT ($FE),A                                ; $9019: D3 FE
L_901B:
    DJNZ L_901B                                ; $901B: 10 FE  high time
    LD A,E                                     ; $901D: 7B
    LD B,A                                     ; $901E: 47
    XOR A                                      ; $901F: AF
    OUT ($FE),A                                ; $9020: D3 FE  speaker off
L_9022:
    DJNZ L_9022                                ; $9022: 10 FE  low time
    DEC C                                      ; $9024: 0D
    JR NZ,L_9011                               ; $9025: 20 EA
    POP BC                                     ; $9027: C1
    DJNZ L_900D                                ; $9028: 10 E3
    RET                                        ; $902A: C9

; ============================================================================
; Sound effects
; Beeper effects: an interrupt-driven player for the request bits in SoundEffectRequests and
; synchronous players that run a whole effect with interrupts disabled.
; ============================================================================

; VERIFIED: Current sound player: 0 idle, 1 pulse sweep, 2 ROM pulse burst, 3 or $83 noise
; sweep (bit 7 has no reader).  Players: PlayPulseSweepStep, PlayRomPulseBurst,
; PlayNoiseSweepStep.
; Evidence: dispatch in UpdateSoundEffect; writers in the set-up code; tools/check_routines.py
; sound/interrupt-sound-player, sound/synchronous-sound-players.
SoundState:
    defb $00                                                                              ; $902B .

; VERIFIED: Sound counters, E = low byte, D = high byte.  Noise sweep: E = steps left, D =
; delay per sample.  Pulse sweep: E = pulse width, D = frames left.  ROM pulse burst: D =
; frames left.
; Evidence: loaded/stored as DE by the players; tools/check_routines.py
; sound/interrupt-sound-player, sound/synchronous-sound-players.
SoundCounters:
    defw $0000                                                                            ; $902C

; VERIFIED: Current read address of the noise players (a ROM address: $0127, $031A or $1A1A);
; the sample bytes come from ROM, so the effects are pseudo-random noise.
; Evidence: loaded/stored as HL by PlayNoiseSweepStep/PlayRomPulseBurst; tools/check_routines.py
; sound/interrupt-sound-player, sound/synchronous-sound-players.
SoundDataPointer:
    defw $0000                                                                            ; $902E

; VERIFIED: If sound is on (ControlOptions bit 7): DI, noise sweep with $50 samples per step, delay
; $40 rising by 2 for 32 steps (L_91A4), then the $A0-sample burst (StartNoiseBurst), played
; to the end by WaitSoundFinished.  Callers: launch (LaunchFromStation), docking (L_7B43), destruction
; ($734E).
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players; instruction semantics.
PlayLongNoiseSweep:
    LD A,(ControlOptions)                      ; $9030: 3A 14 FC
    BIT 7,A                                    ; $9033: CB 7F  sound effects on?
    RET Z                                      ; $9035: C8  sound off: no effect
    CALL L_91A4                                ; $9036: CD A4 91  DI and set up the sweep
    JR WaitSoundFinished                       ; $9039: 18 1F  play it to the end

; VERIFIED: If sound is on: DI, noise sweep with $C0 samples per step, delay $C0 falling by 16
; for 12 steps (pitch rises), played to the end.  Entered by JP from L_7ACD at the end of
; the hyperspace tunnel.
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
PlayRisingNoiseSweep:
    LD A,(ControlOptions)                      ; $903B: 3A 14 FC
    BIT 7,A                                    ; $903E: CB 7F
    RET Z                                      ; $9040: C8
    CALL L_91B2                                ; $9041: CD B2 91
    JR WaitSoundFinished                       ; $9044: 18 14

; VERIFIED: If sound is on: DI, noise sweep with $C0 samples per step, delay $40 rising by 16
; for 12 steps (pitch falls), played to the end.  Called from L_79C0 when the hyperspace
; tunnel starts.
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
PlayFallingNoiseSweep:
    LD A,(ControlOptions)                      ; $9046: 3A 14 FC
    BIT 7,A                                    ; $9049: CB 7F
    RET Z                                      ; $904B: C8
    CALL L_91C0                                ; $904C: CD C0 91
    JR WaitSoundFinished                       ; $904F: 18 09

; VERIFIED: If sound is on: StartNoiseBurst ($A0 samples, delay $40, 2 steps, step size left
; from the previous sweep) and play it to the end.  Interrupts are not disabled here. Called
; from the destruction sequence ($734B).
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
PlayNoiseBurst:
    LD A,(ControlOptions)                      ; $9051: 3A 14 FC
    BIT 7,A                                    ; $9054: CB 7F
    RET Z                                      ; $9056: C8
    CALL StartNoiseBurst                       ; $9057: CD D8 90  set up the burst

; VERIFIED: Call PlayNoiseSweepStep until SoundState is 0, then clear all pending requests
; (SoundEffectRequests = 0) and enable interrupts.
; Evidence: instruction semantics.
WaitSoundFinished:
    LD A,(SoundState)                          ; $905A: 3A 2B 90
    AND A                                      ; $905D: A7
    JR Z,L_9065                                ; $905E: 28 05  finished
    CALL PlayNoiseSweepStep                    ; $9060: CD AF 90
    JR WaitSoundFinished                       ; $9063: 18 F5
L_9065:
    LD (SoundEffectRequests),A                 ; $9065: 32 7D 70  cancel all pending requests
    EI                                         ; $9068: FB
    RET                                        ; $9069: C9

; VERIFIED: Eight JP instructions, one per request bit of SoundEffectRequests, entered by JP (HL) from
; UpdateSoundEffect with HL = SoundRequestJumpTable + 3*bit.
; bit 0 -> noise sweep, step -2      bit 4 -> pulse sweep 2 frames, step $FD
; bit 1 -> noise sweep, step -28     bit 5 -> pulse sweep 8 frames, step $D3
; bit 2 -> noise sweep, step +2      bits 6, 7 -> ROM pulse burst (ADD A,$10 variant)
; bit 3 -> ROM pulse burst (SRL A variant)
; Request setters (SET n on SoundEffectRequests): bit 0 UseEnergyBomb ($9275); bit 1 UpdateMissileControl
; when a missile is launched ($A771); bit 2 object removal L_DB0F ($DB24), collision L_EB44
; ($EB47) and ClearAllShipSlots ($EBA7); bit 3 ApplyPlayerLaserHit ($EC5C); bit 4
; UpdatePlayerLaser when the player fires ($EC1B); bit 5 the ECM update while it runs
; ($EDAC); bit 6 player damage: L_EB10 ($EB13) and the AI laser hit at $FADF.  No code
; sets bit 7.
; Evidence: runtime indirect jumps $90A7 -> $906A/$9070/$9076/$9079; tools/check_routines.py
; sound/interrupt-sound-player, sound/synchronous-sound-players reaches all 8; static and
; runtime writers of SoundEffectRequests.
SoundRequestJumpTable:
    JP L_9181                                  ; $906A: C3 81 91  bit 0: energy bomb
L_906D:
    JP L_917D                                  ; $906D: C3 7D 91  bit 1: missile launched
L_9070:
    JP L_919B                                  ; $9070: C3 9B 91  bit 2: object destroyed or collision
L_9073:
    JP L_9167                                  ; $9073: C3 67 91  bit 3: player's laser hit
L_9076:
    JP L_914A                                  ; $9076: C3 4A 91  bit 4: player fires the laser
L_9079:
    JP L_9151                                  ; $9079: C3 51 91  bit 5: ECM running
L_907C:
    JP L_9160                                  ; $907C: C3 60 91  bit 6: player damaged
L_907F:
    JP L_9160                                  ; $907F: C3 60 91  bit 7: no setter in the code

; VERIFIED: Called from the IM 2 interrupt handler (InterruptHandler) every frame.  With sound on: if a
; player is active (SoundState 1, 2 or other), run one step of it; otherwise take the lowest
; set request bit of SoundEffectRequests, store its number in SoundRequestIndex and start it via
; SoundRequestJumpTable.  FinishSoundEffect clears the request bit when the effect ends.
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players (bits 0..7: 8, 8, 8, 1, 2, 8, 1, 1 frames); runtime:
; flight scenarios.
UpdateSoundEffect:
    LD A,(ControlOptions)                      ; $9082: 3A 14 FC
    BIT 7,A                                    ; $9085: CB 7F
    RET Z                                      ; $9087: C8
    LD A,(SoundState)                          ; $9088: 3A 2B 90  player active?
    AND A                                      ; $908B: A7
    JR NZ,L_90A8                               ; $908C: 20 1A
    LD A,(SoundEffectRequests)                 ; $908E: 3A 7D 70  pending requests
    AND A                                      ; $9091: A7
    RET Z                                      ; $9092: C8
    LD B,$FF                                   ; $9093: 06 FF
L_9095:
    INC B                                      ; $9095: 04  B = number of the lowest set bit
    RRA                                        ; $9096: 1F
    JR NC,L_9095                               ; $9097: 30 FC
    LD A,B                                     ; $9099: 78
    LD (SoundRequestIndex),A                   ; $909A: 32 C8 91
    ADD A,A                                    ; $909D: 87  A = 3*B
    ADD A,B                                    ; $909E: 80
    LD HL,SoundRequestJumpTable                ; $909F: 21 6A 90
    ADD A,L                                    ; $90A2: 85
    LD L,A                                     ; $90A3: 6F
    JR NC,L_90A7                               ; $90A4: 30 01
    INC H                                      ; $90A6: 24
L_90A7:
    JP (HL)                                    ; $90A7: E9  JP into SoundRequestJumpTable
L_90A8:
    DEC A                                      ; $90A8: 3D
    JP Z,PlayPulseSweepStep                    ; $90A9: CA 2D 91  state 1
    DEC A                                      ; $90AC: 3D
    JR Z,PlayRomPulseBurst                     ; $90AD: 28 41  state 2; 3 or $83 fall through

; VERIFIED: One step of the ROM noise sweep: C samples (operand NoiseSamplesPerStep), each OUT
; $FE with (HL) AND $18 (speaker and MIC bits of a ROM byte) followed by a delay of D; then
; D += step (operand NoiseDelayStep), E -= 1 and the counters are saved.  At E = 0: if the
; new D has bit 7 set the burst StartNoiseBurst follows, else FinishSoundEffect.
; Evidence: instruction semantics; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
PlayNoiseSweepStep:
    LD HL,(SoundDataPointer)                   ; $90AF: 2A 2E 90
    LD DE,(SoundCounters)                      ; $90B2: ED 5B 2C 90

; VERIFIED: First step of a new noise sweep (JP from StartNoiseSweep).
L_90B6:
; VERIFIED: SMC: operand of LD C,n (samples per step); patched at $9195 and $90DF.
defc NoiseSamplesPerStep = L_90B6 + 1 ; byte inside instruction at $90B6
    LD C,$40                                   ; $90B6: 0E 40
L_90B8:
    LD A,(HL)                                  ; $90B8: 7E
    AND $18                                    ; $90B9: E6 18  speaker (bit 4) and MIC (bit 3) from the ROM byte
    OUT ($FE),A                                ; $90BB: D3 FE
    LD B,D                                     ; $90BD: 42
L_90BE:
    DJNZ L_90BE                                ; $90BE: 10 FE  delay D
    INC HL                                     ; $90C0: 23
    DEC C                                      ; $90C1: 0D
    JR NZ,L_90B8                               ; $90C2: 20 F4
    LD A,D                                     ; $90C4: 7A
L_90C5:
; VERIFIED: SMC: operand of ADD A,n (delay change per step); patched at $9191.
defc NoiseDelayStep = L_90C5 + 1 ; byte inside instruction at $90C5
    ADD A,$00                                  ; $90C5: C6 00
    LD D,A                                     ; $90C7: 57
    DEC E                                      ; $90C8: 1D  one step fewer
    LD (SoundCounters),DE                      ; $90C9: ED 53 2C 90
    LD (SoundDataPointer),HL                   ; $90CD: 22 2E 90
    RET NZ                                     ; $90D0: C0
    LD HL,SoundState                           ; $90D1: 21 2B 90  not used by either continuation
    BIT 7,A                                    ; $90D4: CB 7F  delay wrapped past $7F: add the burst
    JR Z,FinishSoundEffect                     ; $90D6: 28 41

; VERIFIED: SoundState = 3, $A0 samples per step, SoundDataPointer = $0127, D = $40, E = 2.
; The delay step operand keeps its previous value.  Called by PlayNoiseBurst; also reached
; from PlayNoiseSweepStep when a sweep ends with D >= $80.
; Evidence: instruction semantics; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
StartNoiseBurst:
    LD A,$03                                   ; $90D8: 3E 03
    LD (SoundState),A                          ; $90DA: 32 2B 90
    LD A,$A0                                   ; $90DD: 3E A0
    LD (NoiseSamplesPerStep),A                 ; $90DF: 32 B7 90
    LD HL,$0127                                ; $90E2: 21 27 01  ROM address used as noise data
    LD DE,$4002                                ; $90E5: 11 02 40  D = $40 delay, E = 2 steps
    LD (SoundCounters),DE                      ; $90E8: ED 53 2C 90
    LD (SoundDataPointer),HL                   ; $90EC: 22 2E 90
    RET                                        ; $90EF: C9

; VERIFIED: State 2: 100 speaker pulses whose high and low lengths are both f(ROM byte), with
; f = byte/4 (SRL A; SRL A) or (byte+$10)/2 (ADD A,$10; SRL A) selected by the 2-byte patch
; at RomPulseScale; the pointer advances with INC L only.  Then D -= 1 (L_9110); at 0 the
; effect ends.
; Evidence: instruction semantics; set-up at L_9160/L_9167.
PlayRomPulseBurst:
    LD HL,(SoundDataPointer)                   ; $90F0: 2A 2E 90
    LD DE,(SoundCounters)                      ; $90F3: ED 5B 2C 90

; VERIFIED: Entry of the burst loop used by the set-up code at L_9160/L_9167.
L_90F7:
    LD C,$64                                   ; $90F7: 0E 64  100 pulses
L_90F9:
    LD A,(HL)                                  ; $90F9: 7E
    INC L                                      ; $90FA: 2C  INC L only: stays in one 256-byte page

; VERIFIED: SMC: two bytes patched by $916F with CB 3F (SRL A) or C6 10 (ADD A,$10).
RomPulseScale:
    SRL A                                      ; $90FB: CB 3F
    SRL A                                      ; $90FD: CB 3F
    LD E,A                                     ; $90FF: 5F
    LD B,A                                     ; $9100: 47
    LD A,$30                                   ; $9101: 3E 30  speaker bit on
    OUT ($FE),A                                ; $9103: D3 FE
L_9105:
    DJNZ L_9105                                ; $9105: 10 FE  high time
    LD B,E                                     ; $9107: 43
    XOR A                                      ; $9108: AF
    OUT ($FE),A                                ; $9109: D3 FE
L_910B:
    DJNZ L_910B                                ; $910B: 10 FE  low time
    DEC C                                      ; $910D: 0D
    JR NZ,L_90F9                               ; $910E: 20 E9

; VERIFIED: Shared end of a pulse frame: D -= 1, save the counters and pointer, finish when D
; reaches 0.
L_9110:
    DEC D                                      ; $9110: 15  one frame fewer
    LD (SoundCounters),DE                      ; $9111: ED 53 2C 90
    LD (SoundDataPointer),HL                   ; $9115: 22 2E 90
    RET NZ                                     ; $9118: C0

; VERIFIED: SoundState = 0 and toggle request bit SoundRequestIndex of SoundEffectRequests (clears the bit
; that started the effect).  The synchronous players reach this too; WaitSoundFinished then
; clears SoundEffectRequests.  Because the bit is toggled with XOR, a request that was cancelled while
; its effect played (SelectSoundOn) is set again.
; Evidence: instruction semantics; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
FinishSoundEffect:
    XOR A                                      ; $9119: AF
    LD (SoundState),A                          ; $911A: 32 2B 90
    LD A,(SoundRequestIndex)                   ; $911D: 3A C8 91
    INC A                                      ; $9120: 3C
    LD B,A                                     ; $9121: 47
    LD A,$80                                   ; $9122: 3E 80  A = bit SoundRequestIndex
L_9124:
    RLCA                                       ; $9124: 07
    DJNZ L_9124                                ; $9125: 10 FD
    LD HL,SoundEffectRequests                  ; $9127: 21 7D 70
    XOR (HL)                                   ; $912A: AE  clear that request bit
    LD (HL),A                                  ; $912B: 77
    RET                                        ; $912C: C9

; VERIFIED: State 1: E = 2*E + k (k = operand PulseSweepStep), then 15 speaker pulses of E
; high and E low, then the frame end at L_9110.
; Evidence: instruction semantics; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players (requests 4 and 5).
PlayPulseSweepStep:
    LD DE,(SoundCounters)                      ; $912D: ED 5B 2C 90

; VERIFIED: Pulse sweep entry with DE already loaded (from L_914A/L_9151).
L_9131:
    LD A,E                                     ; $9131: 7B
    ADD A,A                                    ; $9132: 87
L_9133:
; VERIFIED: SMC: operand of ADD A,n (pulse width step); patched at $9156 ($FD or $D3).
defc PulseSweepStep = L_9133 + 1 ; byte inside instruction at $9133
    ADD A,$05                                  ; $9133: C6 05  SMC: operand patched by $9156 ($FD or $D3)
    LD E,A                                     ; $9135: 5F
    LD C,$0F                                   ; $9136: 0E 0F  15 pulses
L_9138:
    LD A,$30                                   ; $9138: 3E 30  speaker bit on
    LD B,E                                     ; $913A: 43
    OUT ($FE),A                                ; $913B: D3 FE
L_913D:
    DJNZ L_913D                                ; $913D: 10 FE  high time E
    XOR A                                      ; $913F: AF
    LD B,E                                     ; $9140: 43
    OUT ($FE),A                                ; $9141: D3 FE
L_9143:
    DJNZ L_9143                                ; $9143: 10 FE  low time E
    DEC C                                      ; $9145: 0D
    JR NZ,L_9138                               ; $9146: 20 F0
    JR L_9110                                  ; $9148: 18 C6

; VERIFIED: Request bit 4: pulse sweep with k = $FD for D = 2 frames (E = 0): patch
; PulseSweepStep, SoundState = 1, first frame at L_9131.
; Evidence: runtime executed; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_914A:
    LD A,$FD                                   ; $914A: 3E FD
    LD DE,$0200                                ; $914C: 11 00 02  D = 2 frames, E = 0
    JR L_9156                                  ; $914F: 18 05

; VERIFIED: Request bit 5: pulse sweep with k = $D3 for D = 8 frames.
; Evidence: runtime executed; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_9151:
    LD A,$D3                                   ; $9151: 3E D3
    LD DE,$0800                                ; $9153: 11 00 08  D = 8 frames, E = 0
L_9156:
    LD (PulseSweepStep),A                      ; $9156: 32 34 91  patch the ADD operand at $9134
    LD A,$01                                   ; $9159: 3E 01
    LD (SoundState),A                          ; $915B: 32 2B 90
    JR L_9131                                  ; $915E: 18 D1

; VERIFIED: Request bits 6 and 7: ROM pulse burst with RomPulseScale = ADD A,$10, data at
; $1A1A, 1 frame.
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_9160:
    LD A,$1A                                   ; $9160: 3E 1A
    LD HL,$10C6                                ; $9162: 21 C6 10  C6 10 = ADD A,$10 (opcode bytes, not an address)
    JR L_916C                                  ; $9165: 18 05

; VERIFIED: Request bit 3: ROM pulse burst with RomPulseScale = SRL A, data at $031A, 1 frame
; (SoundState = 2, JP L_90F7).
; Evidence: tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_9167:
    LD A,$03                                   ; $9167: 3E 03
    LD HL,$3FCB                                ; $9169: 21 CB 3F  CB 3F = SRL A (opcode bytes, not an address)
L_916C:
    LD DE,$0100                                ; $916C: 11 00 01  D = 1 frame
    LD (RomPulseScale),HL                      ; $916F: 22 FB 90  patch RomPulseScale
    LD H,A                                     ; $9172: 67  HL = ROM data address A*256 + $1A
    LD L,$1A                                   ; $9173: 2E 1A
    LD A,$02                                   ; $9175: 3E 02
    LD (SoundState),A                          ; $9177: 32 2B 90
    JP L_90F7                                  ; $917A: C3 F7 90

; VERIFIED: Request bit 1: noise sweep with step $E4 (-28) (C = $E4).
L_917D:
    LD C,$E4                                   ; $917D: 0E E4
    JR L_9183                                  ; $917F: 18 02

; VERIFIED: Request bit 0: noise sweep with step $FE (-2): SoundState = 3, B = $40 samples per
; step, D = $40, E = 8 steps, continue at StartNoiseSweep.
; Evidence: runtime executed; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_9181:
    LD C,$FE                                   ; $9181: 0E FE
L_9183:
    LD A,$03                                   ; $9183: 3E 03
    LD (SoundState),A                          ; $9185: 32 2B 90
L_9188:
    LD B,$40                                   ; $9188: 06 40  B = $40 samples per step
    LD DE,$4008                                ; $918A: 11 08 40  D = $40 initial delay, E = 8 steps

; VERIFIED: Start a noise sweep: SoundDataPointer source HL = $0127, delay step operand = C,
; samples per step operand = B, then the first step at L_90B6 with D = initial delay, E =
; steps.
; Evidence: instruction semantics; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
StartNoiseSweep:
    LD HL,$0127                                ; $918D: 21 27 01  ROM address used as noise data
    LD A,C                                     ; $9190: 79
    LD (NoiseDelayStep),A                      ; $9191: 32 C6 90  patch NoiseDelayStep
    LD A,B                                     ; $9194: 78
    LD (NoiseSamplesPerStep),A                 ; $9195: 32 B7 90  patch NoiseSamplesPerStep
    JP L_90B6                                  ; $9198: C3 B6 90

; VERIFIED: Request bit 2: noise sweep with step +2, SoundState = $83 (bit 7 set; no reader
; tests it).
; Evidence: runtime executed; tools/check_routines.py sound/interrupt-sound-player,
; sound/synchronous-sound-players.
L_919B:
    LD A,$83                                   ; $919B: 3E 83
    LD (SoundState),A                          ; $919D: 32 2B 90
