    defb $28,$85,$E2,$1F                                                                  ; $91FE (...  SLAVES: price 40, -5, stock 226, mask $1F
    defb $53,$85,$FB,$0F                                                                  ; $9202 S...  LIQUOR/WINES: price 83, -5, stock 251, mask $0F
    defb $C4,$08,$36,$03                                                                  ; $9206 ..6.  LUXURIES: price 196, +8, stock 54, mask $03
    defb $EB,$1D,$08,$78                                                                  ; $920A ...x  NARCOTICS: price 235, +29, stock 8, mask $78
    defb $9A,$0E,$38,$03                                                                  ; $920E ..8.  COMPUTERS: price 154, +14, stock 56, mask $03
    defb $75,$06,$28,$07                                                                  ; $9212 u.(.  MACHINERY: price 117, +6, stock 40, mask $07
    defb $4E,$01,$11,$1F                                                                  ; $9216 N...  ALLOYS: price 78, +1, stock 17, mask $1F
    defb $7C,$0D,$1D,$07                                                                  ; $921A |...  FIREARMS: price 124, +13, stock 29, mask $07
    defb $B0,$89,$DC,$3F                                                                  ; $921E ...?  FURS: price 176, -9, stock 220, mask $3F
    defb $20,$81,$35,$03                                                                  ; $9222  .5.  MINERALS: price 32, -1, stock 53, mask $03
    defb $61,$A1,$42,$07                                                                  ; $9226 a.B.  GOLD: price 97, -1, stock 66, mask $07 (byte 1 bit 5)
    defb $AB,$A2,$37,$1F                                                                  ; $922A ..7.  PLATINUM: price 171, -2, stock 55, mask $1F (byte 1 bit 5)
