; VERIFIED: Roll the current particle about the view centre when DustRollRate <> 0
; (r = rate 1..15, sign in DustFlags bit 4): X moves by the step
; (|Y| * r) >> 7, then Y by the step (|new X| * r) >> 7.  In signed terms
; x' = x - y*r/128 and y' = y + x'*r/128 (truncated steps), a pair of shears
; that keeps the radius within about 3% (roll test).  |X| grows when the X, Y
; and roll sign bits have odd parity and |Y| grows when they have even parity;
; a shrinking magnitude that crosses zero is negated with its sign flipped
; (NegateDustX/Y), and a growing X or Y that reaches 120 respawns.  A zero step
; leaves that coordinate unchanged.  Continues with ApplyDustPitch.
; Evidence: tools/check_routines.py dust/p4-dust-roll-pitch-side-model (exact
; records for random particles and rates); dust/stardust-update (radius).
ApplyDustRoll:
    LD A,(DustRollRate)                        ; $9FFA: 3A F7 99
    AND A                                      ; $9FFD: A7
    JP Z,ApplyDustPitch                        ; $9FFE: CA 9C A0  no roll: pitch only
    LD C,A                                     ; $A001: 4F
    LD A,(DustY)                               ; $A002: 3A 01 9A  X step from |Y| * roll
    LD B,$04                                   ; $A005: 06 04  B is reloaded by ScaleByRate
    CALL ScaleByRate                           ; $A007: CD 85 A0  L = |Y| * rate / 128
    JR Z,L_A048                                ; $A00A: 28 3C  zero step: X unchanged
    LD L,A                                     ; $A00C: 6F
    LD A,(DustFlags)                           ; $A00D: 3A 07 9A  choose add/subtract from X, Y and roll signs
    BIT 7,A                                    ; $A010: CB 7F
    JR NZ,L_A024                               ; $A012: 20 10
    BIT 6,A                                    ; $A014: CB 77
    JR NZ,L_A01E                               ; $A016: 20 06
    BIT 4,A                                    ; $A018: CB 67
    JR NZ,L_A034                               ; $A01A: 20 18
    JR L_A03E                                  ; $A01C: 18 20
L_A01E:
    BIT 4,A                                    ; $A01E: CB 67
    JR NZ,L_A03E                               ; $A020: 20 1C
    JR L_A034                                  ; $A022: 18 10
L_A024:
    BIT 6,A                                    ; $A024: CB 77
    JR NZ,L_A02E                               ; $A026: 20 06
    BIT 4,A                                    ; $A028: CB 67
    JR NZ,L_A03E                               ; $A02A: 20 12
    JR L_A034                                  ; $A02C: 18 06
L_A02E:
    BIT 4,A                                    ; $A02E: CB 67
    JR NZ,L_A034                               ; $A030: 20 02
    JR L_A03E                                  ; $A032: 18 0A
L_A034:
    LD A,(DustX)                               ; $A034: 3A FF 99  |X| grows (sign parity odd)
    ADD A,L                                    ; $A037: 85
    CP $78                                     ; $A038: FE 78  X >= 120: respawn
    JR NC,L_9FD3                               ; $A03A: 30 97
    JR L_A045                                  ; $A03C: 18 07
L_A03E:
    LD A,(DustX)                               ; $A03E: 3A FF 99  |X| shrinks (sign parity even)
    SUB L                                      ; $A041: 95
    CALL C,NegateDustX                         ; $A042: DC 94 A2  crossed zero: negate, flip X sign
L_A045:
    LD (DustX),A                               ; $A045: 32 FF 99  x = x - y*roll/128 (signed)
L_A048:
    LD A,(DustRollRate)                        ; $A048: 3A F7 99  second shear: Y from the new X
    LD C,A                                     ; $A04B: 4F
    LD A,(DustX)                               ; $A04C: 3A FF 99  Y step from the new |X|
    LD B,$04                                   ; $A04F: 06 04
    CALL ScaleByRate                           ; $A051: CD 85 A0  L = |X| * rate / 128
    JR Z,ApplyDustPitch                        ; $A054: 28 46  zero step: Y unchanged
    LD L,A                                     ; $A056: 6F
    LD A,(DustFlags)                           ; $A057: 3A 07 9A  add/subtract from the sign bits
    BIT 7,A                                    ; $A05A: CB 7F
    JR NZ,L_A06E                               ; $A05C: 20 10
    BIT 6,A                                    ; $A05E: CB 77
    JR NZ,L_A068                               ; $A060: 20 06
    BIT 4,A                                    ; $A062: CB 67
    JR NZ,L_A07C                               ; $A064: 20 16
    JR L_A090                                  ; $A066: 18 28
L_A068:
    BIT 4,A                                    ; $A068: CB 67
    JR NZ,L_A090                               ; $A06A: 20 24
    JR L_A07C                                  ; $A06C: 18 0E
L_A06E:
    BIT 6,A                                    ; $A06E: CB 77
    JR NZ,L_A078                               ; $A070: 20 06
    BIT 4,A                                    ; $A072: CB 67
    JR NZ,L_A090                               ; $A074: 20 1A
    JR L_A07C                                  ; $A076: 18 04
L_A078:
    BIT 4,A                                    ; $A078: CB 67
    JR Z,L_A090                                ; $A07A: 28 14
L_A07C:
    LD A,(DustY)                               ; $A07C: 3A 01 9A  |Y| shrinks (sign parity odd)
    SUB L                                      ; $A07F: 95
    CALL C,NegateDustY                         ; $A080: DC 87 A2  crossed zero: negate, flip Y sign
    JR L_A099                                  ; $A083: 18 14

; VERIFIED: A = (A * (C AND 15)) >> 7, i.e. bits 7..14 of the product; Z set if zero,
; carry clear.  Input: A = magnitude, C = rate.  Output: B = 0.
; Clobbers: C, D, E, HL.  Computes the steps of the roll shears in ApplyDustRoll.
ScaleByRate:
    LD B,$04                                   ; $A085: 06 04  low 4 bits of the rate
    CALL MultiplyByLowBits                     ; $A087: CD A1 A2  HL = A * rate
    LD A,H                                     ; $A08A: 7C  A = HL >> 7
    RL L                                       ; $A08B: CB 15
    RLA                                        ; $A08D: 17
    AND A                                      ; $A08E: A7  Z when zero, carry clear
    RET                                        ; $A08F: C9

; VERIFIED: ApplyDustRoll continued (reached only by jumps from L_A048..L_A078): |Y| grows
; by the roll step in L and respawns at 120 or more; L_A099 stores the new Y and
; falls into ApplyDustPitch.
L_A090:
    LD A,(DustY)                               ; $A090: 3A 01 9A  |Y| grows (sign parity even)
    ADD A,L                                    ; $A093: 85
    CP $78                                     ; $A094: FE 78  Y >= 120: respawn
    JP NC,RespawnDust                          ; $A096: D2 34 A3
L_A099:
    LD (DustY),A                               ; $A099: 32 01 9A  y = y + x*roll/128 (signed)

; VERIFIED: Pitch the current particle when DustPitchRate <> 0 (p = rate, sign in
; DustFlags bit 3; y = signed Y): DustPitchScale s = high byte of
; 2*($4000 - y*p), i.e. 128 - y*p/128 ($80 = 1.0).  Then Z = Z*s/128 (respawn
; when 2*Z*s overflows 16 bits or is zero); X = (X/2)*256/s, respawning when it
; becomes 0 or >= 128; Y = (|y + p|/2)*256/s, the Y sign flipping when y + p
; crosses zero and again when this quotient is 0; Y >= 64 respawns.  So a
; pitch shifts particles vertically by p and scales them by 128/s.  Without
; roll StoreAndPlotDust then also respawns Y >= 63.
; Evidence: tools/check_routines.py dust/p4-dust-roll-pitch-side-model (exact
; records); pitch cases of dust/stardust-update.
ApplyDustPitch:
    LD A,(DustPitchRate)                       ; $A09C: 3A F8 99
    AND A                                      ; $A09F: A7
    JP Z,StoreAndPlotDust                      ; $A0A0: CA 3D A1  no pitch: store the particle
    LD C,A                                     ; $A0A3: 4F  C = pitch rate
    LD A,(DustY)                               ; $A0A4: 3A 01 9A  A = |Y|
    LD E,A                                     ; $A0A7: 5F  overwritten by the product below
    LD B,$04                                   ; $A0A8: 06 04
    CALL MultiplyByLowBits                     ; $A0AA: CD A1 A2  HL = |Y| * rate
    EX DE,HL                                   ; $A0AD: EB
    LD HL,$4000                                ; $A0AE: 21 00 40  $4000 = 1.0 in this fixed-point product (number, not screen)
    LD A,(DustFlags)                           ; $A0B1: 3A 07 9A  Y sign = pitch sign: subtract
    BIT 6,A                                    ; $A0B4: CB 77
    JR NZ,L_A0BE                               ; $A0B6: 20 06
    BIT 3,A                                    ; $A0B8: CB 5F
    JR Z,L_A0C5                                ; $A0BA: 28 09
    JR L_A0C2                                  ; $A0BC: 18 04
L_A0BE:
    BIT 3,A                                    ; $A0BE: CB 5F
    JR NZ,L_A0C5                               ; $A0C0: 20 03
L_A0C2:
    ADD HL,DE                                  ; $A0C2: 19  signs differ: $4000 + |Y|*rate
    JR L_A0C8                                  ; $A0C3: 18 03
L_A0C5:
    AND A                                      ; $A0C5: A7
    SBC HL,DE                                  ; $A0C6: ED 52  signs equal: $4000 - |Y|*rate
L_A0C8:
    ADD HL,HL                                  ; $A0C8: 29  scale = 128 - y*pitch/128 (signed)
    LD A,H                                     ; $A0C9: 7C
    LD (DustPitchScale),A                      ; $A0CA: 32 F9 99  DustPitchScale
    LD A,(DustZ)                               ; $A0CD: 3A 02 9A
    LD E,A                                     ; $A0D0: 5F
    LD B,$08                                   ; $A0D1: 06 08  8-bit multiplier
    LD C,H                                     ; $A0D3: 4C
    CALL MultiplyByLowBits                     ; $A0D4: CD A1 A2  Z * scale
    AND A                                      ; $A0D7: A7
    ADC HL,HL                                  ; $A0D8: ED 6A  HL = 2 * Z * scale
    JR C,L_A119                                ; $A0DA: 38 3D  Z overflow: respawn
    JR Z,L_A119                                ; $A0DC: 28 3B  Z zero: respawn
    LD A,H                                     ; $A0DE: 7C
    LD (DustZ),A                               ; $A0DF: 32 02 9A  Z = Z * scale / 128
    LD A,(DustPitchScale)                      ; $A0E2: 3A F9 99  divisor: the scale
    LD B,A                                     ; $A0E5: 47
    LD A,(DustX)                               ; $A0E6: 3A FF 99
    SRL A                                      ; $A0E9: CB 3F  X/2 * 256 / scale
    CALL DivideToFractionD                     ; $A0EB: CD DB A2
    LD A,D                                     ; $A0EE: 7A
    AND A                                      ; $A0EF: A7
    JR Z,L_A119                                ; $A0F0: 28 27  X became zero: respawn
    BIT 7,A                                    ; $A0F2: CB 7F
    JR NZ,L_A119                               ; $A0F4: 20 23  X >= 128: respawn
    LD (DustX),A                               ; $A0F6: 32 FF 99  X = X * 128 / scale
    LD A,(DustPitchRate)                       ; $A0F9: 3A F8 99  B = pitch rate
    LD B,A                                     ; $A0FC: 47
    LD A,(DustY)                               ; $A0FD: 3A 01 9A
    LD C,A                                     ; $A100: 4F
    LD A,(DustFlags)                           ; $A101: 3A 07 9A  Y sign = pitch sign: add
    BIT 6,A                                    ; $A104: CB 77
    JR NZ,L_A10E                               ; $A106: 20 06
    BIT 3,A                                    ; $A108: CB 5F
    JR NZ,L_A112                               ; $A10A: 20 06
    JR L_A11C                                  ; $A10C: 18 0E
L_A10E:
    BIT 3,A                                    ; $A10E: CB 5F
    JR NZ,L_A11C                               ; $A110: 20 0A
L_A112:
    LD A,C                                     ; $A112: 79  signs differ: |Y| - rate
    SUB B                                      ; $A113: 90
    CALL C,NegateDustY                         ; $A114: DC 87 A2  crossed zero: negate, flip Y sign
    JR L_A11E                                  ; $A117: 18 05
L_A119:
    JP RespawnDust                             ; $A119: C3 34 A3  shared respawn exit
L_A11C:
    LD A,C                                     ; $A11C: 79  signs equal: |Y| + rate
    ADD A,B                                    ; $A11D: 80
L_A11E:
