    LD C,A                                     ; $A120: 4F
    LD A,(DustPitchScale)                      ; $A121: 3A F9 99  divisor: the scale
    LD B,A                                     ; $A124: 47
    LD A,C                                     ; $A125: 79
    CALL DivideToFractionD                     ; $A126: CD DB A2  D = (y + pitch) * 128 / scale
    LD A,D                                     ; $A129: 7A
    AND A                                      ; $A12A: A7
