    XOR $40                                    ; $A130: EE 40  quotient zero: flip the Y sign
    LD (DustFlags),A                           ; $A132: 32 07 9A
L_A135:
    LD A,D                                     ; $A135: 7A
    CP $40                                     ; $A136: FE 40  Y >= 64: respawn
    JR NC,L_A119                               ; $A138: 30 DF
    LD (DustY),A                               ; $A13A: 32 01 9A  new Y magnitude

; VERIFIED: Without roll a particle with Y >= 63 respawns; with roll it is kept (it may
; turn back into the view) but not plotted.  If Y < 63 its pixel (address and
; mask from GetDustPixelAddress) is appended to DustPlotList.  Then the record
; (X|sign, Y|sign, Z, Xfrac, Yfrac) is written back at DustRecordPointer,
; which advances by 5, and NextDustParticle follows.
StoreAndPlotDust:
    LD A,(DustRollRate)                        ; $A13D: 3A F7 99  roll active?
    AND A                                      ; $A140: A7
    LD A,(DustY)                               ; $A141: 3A 01 9A  LD keeps the Z flag of the roll test
    JR NZ,L_A14A                               ; $A144: 20 04  rolling: keep off-view particles
    CP $3F                                     ; $A146: FE 3F  no roll: Y >= 63 respawns
    JR NC,L_A119                               ; $A148: 30 CF
L_A14A:
    CP $3F                                     ; $A14A: FE 3F  Y >= 63: keep the record but do not plot
    JR NC,L_A164                               ; $A14C: 30 16
    CALL GetDustPixelAddress                   ; $A14E: CD EF A2  DE = buffer address, C = mask
    LD HL,(DustPlotPointer)                    ; $A151: 2A 05 9A  next free plot list entry
    LD (HL),E                                  ; $A154: 73  plot list entry: address low, high, mask
    INC HL                                     ; $A155: 23
    LD (HL),D                                  ; $A156: 72
    INC HL                                     ; $A157: 23
    LD (HL),C                                  ; $A158: 71
    INC HL                                     ; $A159: 23
    LD (DustPlotPointer),HL                    ; $A15A: 22 05 9A  advance the plot list
    LD A,(DustPlotCount)                       ; $A15D: 3A 08 9A
    INC A                                      ; $A160: 3C
    LD (DustPlotCount),A                       ; $A161: 32 08 9A  count the entry
L_A164:
    LD HL,(DustRecordPointer)                  ; $A164: 2A FB 99  write the record back
    LD A,(DustFlags)                           ; $A167: 3A 07 9A
    LD B,A                                     ; $A16A: 47  B = sign bits
    LD A,(DustX)                               ; $A16B: 3A FF 99
    BIT 7,B                                    ; $A16E: CB 78
    JR Z,L_A174                                ; $A170: 28 02
    OR $80                                     ; $A172: F6 80  X sign into record byte 0
L_A174:
    LD (HL),A                                  ; $A174: 77
    INC HL                                     ; $A175: 23
    LD A,(DustY)                               ; $A176: 3A 01 9A
    BIT 6,B                                    ; $A179: CB 70
    JR Z,L_A17F                                ; $A17B: 28 02
    OR $80                                     ; $A17D: F6 80  Y sign into record byte 1
L_A17F:
    LD (HL),A                                  ; $A17F: 77
    INC HL                                     ; $A180: 23
    LD A,(DustZ)                               ; $A181: 3A 02 9A  byte 2: Z
    LD (HL),A                                  ; $A184: 77
    INC HL                                     ; $A185: 23
    LD A,(DustXFraction)                       ; $A186: 3A FE 99  byte 3: X fraction
    LD (HL),A                                  ; $A189: 77
    INC HL                                     ; $A18A: 23
    LD A,(DustYFraction)                       ; $A18B: 3A 00 9A  byte 4: Y fraction
    LD (HL),A                                  ; $A18E: 77
    INC HL                                     ; $A18F: 23
    LD (DustRecordPointer),HL                  ; $A190: 22 FB 99  next record

; VERIFIED: Decrement DustRemaining; at zero XOR-plot the list (XorPlotDustList, which
; returns to the caller of MoveAndPlotDust).  Otherwise load the next record
; into DustX/DustY/DustZ/fractions, set DustFlags bits 7/6 from its signs
; (bits 5..3 kept) and continue at MoveDustSideways (side views) or
; MoveDustInDepth.
NextDustParticle:
    LD A,(DustRemaining)                       ; $A193: 3A 04 9A
    DEC A                                      ; $A196: 3D  last particle done?
    JP Z,XorPlotDustList                       ; $A197: CA 72 A2  yes: plot the list and return
    LD (DustRemaining),A                       ; $A19A: 32 04 9A
    LD A,(DustFlags)                           ; $A19D: 3A 07 9A
    AND $3B                                    ; $A1A0: E6 3B  keep direction and rotation sign bits
    LD B,A                                     ; $A1A2: 47
    LD DE,(DustRecordPointer)                  ; $A1A3: ED 5B FB 99  record of the next particle
    LD A,(DE)                                  ; $A1A7: 1A
    CP $80                                     ; $A1A8: FE 80
    JR C,L_A1B0                                ; $A1AA: 38 04
    AND $7F                                    ; $A1AC: E6 7F
    SET 7,B                                    ; $A1AE: CB F8  X sign
L_A1B0:
    LD (DustX),A                               ; $A1B0: 32 FF 99
    INC DE                                     ; $A1B3: 13
    LD A,(DE)                                  ; $A1B4: 1A
    CP $80                                     ; $A1B5: FE 80
    JR C,L_A1BD                                ; $A1B7: 38 04
    AND $7F                                    ; $A1B9: E6 7F
    SET 6,B                                    ; $A1BB: CB F0  Y sign
L_A1BD:
    LD (DustY),A                               ; $A1BD: 32 01 9A
    INC DE                                     ; $A1C0: 13
    LD A,(DE)                                  ; $A1C1: 1A  byte 2: Z
    LD (DustZ),A                               ; $A1C2: 32 02 9A
    INC DE                                     ; $A1C5: 13
    LD A,(DE)                                  ; $A1C6: 1A  byte 3: X fraction
    LD (DustXFraction),A                       ; $A1C7: 32 FE 99
    INC DE                                     ; $A1CA: 13
    LD A,(DE)                                  ; $A1CB: 1A  byte 4: Y fraction
    LD (DustYFraction),A                       ; $A1CC: 32 00 9A
    LD A,B                                     ; $A1CF: 78
    LD (DustFlags),A                           ; $A1D0: 32 07 9A  new X/Y signs, pass bits kept
    LD A,(DustSideViewFlag)                    ; $A1D3: 3A FA 99  side views continue at MoveDustSideways
    DEC A                                      ; $A1D6: 3D
    JP Z,MoveDustSideways                      ; $A1D7: CA 35 A2
    JR L_A1E7                                  ; $A1DA: 18 0B  front and rear views

; VERIFIED: Non-front views (A = CurrentScreenId, nonzero).  Rear (1): flip DustFlags
; bits 5..3 (reverse depth motion and both rotation signs), then
; MoveDustInDepth.  Left (2) / right (3): see L_A1EA.
L_A1DC:
    DEC A                                      ; $A1DC: 3D
    JR NZ,L_A1EA                               ; $A1DD: 20 0B  views 2 and 3: side views
    LD A,(DustFlags)                           ; $A1DF: 3A 07 9A
    XOR $38                                    ; $A1E2: EE 38  rear: reverse depth motion and rotation signs
    LD (DustFlags),A                           ; $A1E4: 32 07 9A
L_A1E7:
    JP MoveDustInDepth                         ; $A1E7: C3 1F 9F

; VERIFIED: Side views: DustSideViewFlag = 1; left flips the roll sign, right flips the
; pitch sign; then bits 4 and 3 of DustFlags are exchanged and DustRollRate /
; DustPitchRate swapped; the right view also flips bit 5 (direction).  The
; exchange fits the geometry: looking sideways, the forward (roll) axis lies
; across the screen and the pitch axis along the line of sight.
L_A1EA:
    LD B,A                                     ; $A1EA: 47
    LD A,$01                                   ; $A1EB: 3E 01  side view: horizontal motion
    LD (DustSideViewFlag),A                    ; $A1ED: 32 FA 99
    DEC B                                      ; $A1F0: 05
    JR NZ,L_A20D                               ; $A1F1: 20 1A  view 3: right
    LD A,(DustFlags)                           ; $A1F3: 3A 07 9A
    XOR $10                                    ; $A1F6: EE 10  left: flip the roll sign
    LD B,A                                     ; $A1F8: 47
    AND $10                                    ; $A1F9: E6 10
    SRL A                                      ; $A1FB: CB 3F  old bit 4 to bit 3
    LD C,A                                     ; $A1FD: 4F
    LD A,B                                     ; $A1FE: 78
    AND $08                                    ; $A1FF: E6 08
    ADD A,A                                    ; $A201: 87  old bit 3 to bit 4
    OR C                                       ; $A202: B1
    LD C,A                                     ; $A203: 4F
    LD A,B                                     ; $A204: 78
    AND $E7                                    ; $A205: E6 E7  exchange bits 4 and 3
    OR C                                       ; $A207: B1
    LD (DustFlags),A                           ; $A208: 32 07 9A
    JR L_A227                                  ; $A20B: 18 1A
L_A20D:
    LD A,(DustFlags)                           ; $A20D: 3A 07 9A
    XOR $08                                    ; $A210: EE 08  right: flip the pitch sign
    LD B,A                                     ; $A212: 47
    AND $10                                    ; $A213: E6 10
    SRL A                                      ; $A215: CB 3F
    LD C,A                                     ; $A217: 4F
    LD A,B                                     ; $A218: 78
    AND $08                                    ; $A219: E6 08
    ADD A,A                                    ; $A21B: 87
    OR C                                       ; $A21C: B1
    LD C,A                                     ; $A21D: 4F
    LD A,B                                     ; $A21E: 78
    AND $E7                                    ; $A21F: E6 E7
    OR C                                       ; $A221: B1
    XOR $20                                    ; $A222: EE 20  right: reverse the sideways direction
    LD (DustFlags),A                           ; $A224: 32 07 9A
L_A227:
    LD A,(DustRollRate)                        ; $A227: 3A F7 99  side views exchange roll and pitch
    LD B,A                                     ; $A22A: 47
    LD A,(DustPitchRate)                       ; $A22B: 3A F8 99
    LD (DustRollRate),A                        ; $A22E: 32 F7 99  swap the roll and pitch rates
    LD A,B                                     ; $A231: 78
    LD (DustPitchRate),A                       ; $A232: 32 F8 99

; VERIFIED: Side-view motion: respawn if DustStep >= Z; otherwise
; step = (DustStep*256/Z)/2 + 1 (nearer particles move faster) and X moves by
; it: |X| grows when DustFlags bit 5 XOR the X sign is 1, otherwise it shrinks
; and crossing zero flips the X sign; a growing X >= 119 respawns.  In signed
; terms x' = x - step with bit 5 clear (left view) and x + step with bit 5 set
; (right view).  Z is not changed in the side views.  Continues with
; ApplyDustRoll.
; Evidence: tools/check_routines.py dust/p4-dust-roll-pitch-side-model.
MoveDustSideways:
    LD A,(DustZ)                               ; $A235: 3A 02 9A
    LD B,A                                     ; $A238: 47
    LD A,(DustStep)                            ; $A239: 3A FD 99
    CP B                                       ; $A23C: B8  carry when dz < Z
L_A23D:
    JP NC,RespawnDust                          ; $A23D: D2 34 A3  also the exit for X >= 119 below (carry clear)
    CALL DivideToFractionD                     ; $A240: CD DB A2  D = dz*256/Z
    SRL D                                      ; $A243: CB 3A  step = D/2 + 1
    INC D                                      ; $A245: 14
    LD A,(DustFlags)                           ; $A246: 3A 07 9A  bit 5 XOR X sign selects the direction
    BIT 5,A                                    ; $A249: CB 6F
    JR NZ,L_A255                               ; $A24B: 20 08
    BIT 7,A                                    ; $A24D: CB 7F
    JR NZ,L_A253                               ; $A24F: 20 02
    JR L_A25B                                  ; $A251: 18 08
L_A253:
    JR L_A264                                  ; $A253: 18 0F
L_A255:
    BIT 7,A                                    ; $A255: CB 7F
    JR NZ,L_A25B                               ; $A257: 20 02
    JR L_A264                                  ; $A259: 18 09
L_A25B:
    LD A,(DustX)                               ; $A25B: 3A FF 99  |X| shrinks
    SUB D                                      ; $A25E: 92
    CALL C,NegateDustX                         ; $A25F: DC 94 A2  crossed zero: negate, flip X sign
    JR L_A26C                                  ; $A262: 18 08
L_A264:
    LD A,(DustX)                               ; $A264: 3A FF 99  |X| grows
    ADD A,D                                    ; $A267: 82
    CP $77                                     ; $A268: FE 77  X >= 119: respawn
    JR NC,L_A23D                               ; $A26A: 30 D1
L_A26C:
    LD (DustX),A                               ; $A26C: 32 FF 99  new X magnitude
    JP ApplyDustRoll                           ; $A26F: C3 FA 9F  then roll, pitch and store

; VERIFIED: XOR every DustPlotList entry (address, mask) into memory, DustPlotCount
; entries.  Output: B = 0, HL after the last entry; with no entries it returns
; at once with A = 0.  Clobbers: AF, B, C, DE, HL.
XorPlotDustList:
    LD HL,DustPlotList                         ; $A272: 21 0A 9A
    LD A,(DustPlotCount)                       ; $A275: 3A 08 9A  entries collected in this pass
    AND A                                      ; $A278: A7
    RET Z                                      ; $A279: C8  nothing to plot
    LD B,A                                     ; $A27A: 47
L_A27B:
    LD E,(HL)                                  ; $A27B: 5E  DE = buffer address
    INC HL                                     ; $A27C: 23
    LD D,(HL)                                  ; $A27D: 56
    INC HL                                     ; $A27E: 23
    LD C,(HL)                                  ; $A27F: 4E  C = pixel mask
    LD A,(DE)                                  ; $A280: 1A
    XOR C                                      ; $A281: A9  toggle the particle pixel
    LD (DE),A                                  ; $A282: 12
    INC HL                                     ; $A283: 23
    DJNZ L_A27B                                ; $A284: 10 F5
    RET                                        ; $A286: C9

; VERIFIED: A = -A and toggle DustFlags bit 6 (Y sign).  Called when a magnitude
; subtraction borrowed: the result is the new magnitude on the other side of
; zero.  Clobbers: B.
NegateDustY:
    NEG                                        ; $A287: ED 44  new magnitude after crossing zero
    LD B,A                                     ; $A289: 47
    LD A,(DustFlags)                           ; $A28A: 3A 07 9A
    XOR $40                                    ; $A28D: EE 40  flip the Y sign
    LD (DustFlags),A                           ; $A28F: 32 07 9A
    LD A,B                                     ; $A292: 78
    RET                                        ; $A293: C9

; VERIFIED: A = -A and toggle DustFlags bit 7 (X sign), like NegateDustY.  Clobbers: B.
NegateDustX:
    NEG                                        ; $A294: ED 44  new magnitude after crossing zero
    LD B,A                                     ; $A296: 47
    LD A,(DustFlags)                           ; $A297: 3A 07 9A
    XOR $80                                    ; $A29A: EE 80  flip the X sign
    LD (DustFlags),A                           ; $A29C: 32 07 9A
    LD A,B                                     ; $A29F: 78
    RET                                        ; $A2A0: C9

; VERIFIED: HL = A * (C mod 2^B): shift-and-add over the low B bits of C.
; Input: A, C, B = bit count (4, 5 or 8 here).  Output: HL.  Clobbers: A, B,
; C (rotated), D = 0 on entry then high bits of the shifted A, E, flags.
; Evidence: tools/check_routines.py maths/dust-arithmetic checks B = 4, 5, 8 for all A, C.
MultiplyByLowBits:
    LD D,$00                                   ; $A2A1: 16 00  D:A = multiplicand
    LD HL,$0000                                ; $A2A3: 21 00 00  product
    AND A                                      ; $A2A6: A7
    JR L_A2AC                                  ; $A2A7: 18 03  first bit without shifting
L_A2A9:
    ADD A,A                                    ; $A2A9: 87  D:A *= 2
    RL D                                       ; $A2AA: CB 12
L_A2AC:
    RR C                                       ; $A2AC: CB 19  next multiplier bit, lowest first
    JR NC,L_A2B2                               ; $A2AE: 30 02
    LD E,A                                     ; $A2B0: 5F
    ADD HL,DE                                  ; $A2B1: 19  HL += D:A
L_A2B2:
    DJNZ L_A2A9                                ; $A2B2: 10 F5  B bits
    RET                                        ; $A2B4: C9

; VERIFIED: C:D = (A:L) * 256 / B (integer part in C, fraction in D) for A:L < $2000
; and a quotient below $4000; larger quotients are not exact.  When the
; division leaves no remainder D is NOT written (it keeps the caller's D; the
; fraction 0 is then only in A).  MoveDustInDepth enters with D = the dividend's
; high byte, so an exact quotient there gets that byte as its fraction.
; Falls into DivideToFractionD for the fraction.  Clobbers: A, L, flags.
; Evidence: random cases in tools/check_routines.py maths/dust-arithmetic.
DivideWordToFixed:
    SLA L                                      ; $A2B5: CB 25  A:L <<= 3: dividend bits 12..5 in A
    RLA                                        ; $A2B7: 17
    SLA L                                      ; $A2B8: CB 25
    RLA                                        ; $A2BA: 17
    SLA L                                      ; $A2BB: CB 25
    RLA                                        ; $A2BD: 17
    LD C,$F8                                   ; $A2BE: 0E F8  quotient sentinel: 6 integer bits
    CP B                                       ; $A2C0: B8  first quotient bit
    JR NC,L_A2D3                               ; $A2C1: 30 10
    SLA C                                      ; $A2C3: CB 21
L_A2C5:
    SLA L                                      ; $A2C5: CB 25  next dividend bit into A
    RLA                                        ; $A2C7: 17
    JR C,L_A2D3                                ; $A2C8: 38 09  overflow: subtract
    CP B                                       ; $A2CA: B8
    JR NC,L_A2D3                               ; $A2CB: 30 06
    SLA C                                      ; $A2CD: CB 21
    JR NC,L_A2D9                               ; $A2CF: 30 08  sentinel out: integer part done
    JR L_A2C5                                  ; $A2D1: 18 F2
L_A2D3:
    SUB B                                      ; $A2D3: 90  quotient bit 1
    SCF                                        ; $A2D4: 37
    RL C                                       ; $A2D5: CB 11
    JR C,L_A2C5                                ; $A2D7: 38 EC
L_A2D9:
    AND A                                      ; $A2D9: A7  no remainder: return without writing D
    RET Z                                      ; $A2DA: C8  exact: C = integer part, A = fraction 0

; VERIFIED: D = A * 256 / B (8 quotient bits, $FE sentinel) for A < B.  Clobbers: A.
; Evidence: all A < B checked (tools/check_routines.py maths/dust-arithmetic).
; DivideFractionABToC is the same algorithm with the result in C.
DivideToFractionD:
    LD D,$FE                                   ; $A2DB: 16 FE  sentinel bit: 8 quotient bits
L_A2DD:
    ADD A,A                                    ; $A2DD: 87  remainder * 2
    JR C,L_A2E8                                ; $A2DE: 38 08  overflow: subtract
    CP B                                       ; $A2E0: B8
    JR NC,L_A2E8                               ; $A2E1: 30 05
    SLA D                                      ; $A2E3: CB 22  quotient bit 0
    RET NC                                     ; $A2E5: D0  sentinel out: 8 bits done
    JR L_A2DD                                  ; $A2E6: 18 F5
L_A2E8:
    SUB B                                      ; $A2E8: 90  quotient bit 1
    SCF                                        ; $A2E9: 37
    RL D                                       ; $A2EA: CB 12
    RET NC                                     ; $A2EC: D0
    JR L_A2DD                                  ; $A2ED: 18 EE

; VERIFIED: View-buffer address and pixel mask of the current particle: column
; $80 +/- DustX, row $3F -/+ DustY (positive Y up).  Output: DE = address
; in the 256x128 view bitmap buffer (Spectrum screen layout, lower half
; selected by the Y sign), C = A = pixel mask.  Clobbers: B (0), H = row,
; L = column.
; Quirk: a negative zero Y maps to row 127 instead of 63.
; Evidence: dust model test compares every plotted pixel.
GetDustPixelAddress:
    LD D,ViewBitmapBuffer >> 8                 ; $A2EF: 16 C0  high byte of the view bitmap buffer
    LD A,(DustFlags)                           ; $A2F1: 3A 07 9A
    LD B,A                                     ; $A2F4: 47  B = sign flags
    LD A,(DustX)                               ; $A2F5: 3A FF 99
    LD L,A                                     ; $A2F8: 6F
    LD A,(DustY)                               ; $A2F9: 3A 01 9A
    LD H,A                                     ; $A2FC: 67
    LD A,$80                                   ; $A2FD: 3E 80  column = $80 +/- X
    BIT 7,B                                    ; $A2FF: CB 78
    JR NZ,L_A306                               ; $A301: 20 03
    ADD A,L                                    ; $A303: 85  X positive: right of the centre
    JR L_A307                                  ; $A304: 18 01
L_A306:
    SUB L                                      ; $A306: 95  X negative: left
L_A307:
    LD L,A                                     ; $A307: 6F
    LD A,$3F                                   ; $A308: 3E 3F  row = $3F -/+ Y
    BIT 6,B                                    ; $A30A: CB 70
    JR NZ,L_A311                               ; $A30C: 20 03
    SUB H                                      ; $A30E: 94  Y positive: above the centre row
    JR L_A314                                  ; $A30F: 18 03
L_A311:
    ADD A,H                                    ; $A311: 84  Y negative: below
    SET 3,D                                    ; $A312: CB DA  Y negative: lower half of the buffer
L_A314:
    LD H,A                                     ; $A314: 67
    AND $07                                    ; $A315: E6 07  pixel line within the character row
    OR D                                       ; $A317: B2
    LD D,A                                     ; $A318: 57
    LD A,H                                     ; $A319: 7C
    AND $38                                    ; $A31A: E6 38  character row bits into E
    ADD A,A                                    ; $A31C: 87
    ADD A,A                                    ; $A31D: 87
    LD E,A                                     ; $A31E: 5F
    LD A,L                                     ; $A31F: 7D
    RRA                                        ; $A320: 1F  column / 8
    RRA                                        ; $A321: 1F
    RRA                                        ; $A322: 1F
    AND $1F                                    ; $A323: E6 1F
    OR E                                       ; $A325: B3
    LD E,A                                     ; $A326: 5F
    LD A,L                                     ; $A327: 7D
    AND $07                                    ; $A328: E6 07  bit position in the byte
    LD C,B                                     ; $A32A: 48
    INC A                                      ; $A32B: 3C
    LD B,A                                     ; $A32C: 47
    LD A,$01                                   ; $A32D: 3E 01  mask = $80 >> (column AND 7)
L_A32F:
    RRCA                                       ; $A32F: 0F
    DJNZ L_A32F                                ; $A330: 10 FD
    LD C,A                                     ; $A332: 4F
    RET                                        ; $A333: C9

; VERIFIED: Re-create the current particle with the dust random generator AdvanceRandomHL (state
; in HL, saved in AuxRandomSeed), writing bytes 0..2 of the record at
; DustRecordPointer (the fraction bytes keep their old values):
;   front, no pitch: X = rnd AND $BF, Y = rnd AND $9F, Z = $80 + rnd AND $7F;
;   front, pitching: X = rnd AND $F8, Y = rnd AND $3F with sign opposite to
;     the pitch sign bit;
;   rear and side views: edge positions (L_A38D).
; Then NextDustParticle; the respawned particle is not plotted this pass.
RespawnDust:
    LD HL,(AuxRandomSeed)                      ; $A334: 2A 63 70  dust random state
    LD DE,(DustRecordPointer)                  ; $A337: ED 5B FB 99  record to overwrite
    LD A,(CurrentScreenId)                     ; $A33B: 3A 41 70  rear and side views at L_A38D
    AND A                                      ; $A33E: A7
    JR NZ,L_A38D                               ; $A33F: 20 4C
    LD A,(DustPitchRate)                       ; $A341: 3A F8 99  pitching front view at L_A36E
    AND A                                      ; $A344: A7
    JR NZ,L_A36E                               ; $A345: 20 27

; VERIFIED: Front-view respawn entry, also CALLed by L_7AA2 for each of the 16 records
; (DE = record, HL = random state) after SeedLaunchDust has patched the two mask
; operands below to $83 and the JP at DustRespawnExit to RET: every particle
; then starts within 3 units of the centre with Z >= $80 (test confirmed).
; Output (patched call): DE advanced by 5, HL = new random state.
RespawnDustFront:
defc L_A348 = RespawnDustFront + 1 ; byte inside instruction at $A347
    LD A,$BF                                   ; $A347: 3E BF  SMC operand: X mask; $83 by $7A8A, $BF again by $7AAB
    LD (L_A359),A                              ; $A349: 32 59 A3  SMC: X mask into the AND at L_A358
L_A34C:
defc L_A34D = L_A34C + 1 ; byte inside instruction at $A34C
    LD A,$9F                                   ; $A34C: 3E 9F  SMC operand: Y mask; $83 by $7A8D, $9F again by $7AB0
    LD (L_A360),A                              ; $A34E: 32 60 A3  SMC: Y mask into the AND at L_A35F
    XOR A                                      ; $A351: AF
    LD (L_A362),A                              ; $A352: 32 62 A3  SMC: Y sign OR value 0 (random sign kept)
L_A355:
    CALL AdvanceRandomHL                       ; $A355: CD 65 A4  A = next random byte (state in HL)
L_A358:
defc L_A359 = L_A358 + 1 ; byte inside instruction at $A358
    AND $BF                                    ; $A358: E6 BF  SMC operand: $BF, $83 (SeedLaunchDust), $F8 pitching ($A375)
    LD (DE),A                                  ; $A35A: 12  byte 0: X
    INC DE                                     ; $A35B: 13
    CALL AdvanceRandomHL                       ; $A35C: CD 65 A4  random Y byte
L_A35F:
defc L_A360 = L_A35F + 1 ; byte inside instruction at $A35F
    AND $9F                                    ; $A35F: E6 9F  SMC operand: $9F, $83 (SeedLaunchDust), $3F pitching ($A370)
L_A361:
defc L_A362 = L_A361 + 1 ; byte inside instruction at $A361
    OR $80                                     ; $A361: F6 80  SMC operand: 0 ($A352/$A387) or $80 ($A381): Y sign
    LD (DE),A                                  ; $A363: 12  byte 1: Y
    INC DE                                     ; $A364: 13
    CALL AdvanceRandomHL                       ; $A365: CD 65 A4  random Z byte
    AND $7F                                    ; $A368: E6 7F  Z = $80..$FF
    ADD A,$80                                  ; $A36A: C6 80
    JR StoreRespawnedDust                      ; $A36C: 18 74  store Z, skip the fractions
L_A36E:
    LD A,$3F                                   ; $A36E: 3E 3F
    LD (L_A360),A                              ; $A370: 32 60 A3  SMC: Y mask $3F into the AND at L_A35F
    LD A,$F8                                   ; $A373: 3E F8
    LD (L_A359),A                              ; $A375: 32 59 A3  SMC: X mask $F8 into the AND at L_A358
    LD A,(DustFlags)                           ; $A378: 3A 07 9A
    AND $08                                    ; $A37B: E6 08  pitch sign selects the half for new particles
    JR NZ,L_A386                               ; $A37D: 20 07
    LD A,$80                                   ; $A37F: 3E 80
    LD (L_A362),A                              ; $A381: 32 62 A3  SMC: Y forced negative (OR $80 at L_A361)
    JR L_A38A                                  ; $A384: 18 04
L_A386:
    XOR A                                      ; $A386: AF
    LD (L_A362),A                              ; $A387: 32 62 A3  SMC: Y positive (OR 0 at L_A361)
L_A38A:
    JP L_A355                                  ; $A38A: C3 55 A3  generate with the pitching masks

; VERIFIED: Respawn for the rear view (id 1) and the side views (RespawnDustSideView).  Rear: alternating with
; AlternatingBits, either X at the left/right edge (|X| = $77, random sign) or
; Y at the top/bottom edge (from the patched AND/OR at L_A3FA/L_A3FC), with
; Z = rnd OR (L_A3E1 operand: $80 when pitching).
L_A38D:
    LD C,A                                     ; $A38D: 4F
    DEC C                                      ; $A38E: 0D  C = view id - 1: zero for the rear view
    JP NZ,RespawnDustSideView                  ; $A38F: C2 02 A4  views 2/3: side-view respawn
    LD A,(DustPitchRate)                       ; $A392: 3A F8 99  rear view: pitching?
    AND A                                      ; $A395: A7
    JR Z,L_A3B6                                ; $A396: 28 1E
    LD A,$80                                   ; $A398: 3E 80
    LD (L_A3E1),A                              ; $A39A: 32 E1 A3  SMC: Z OR value $80 at L_A3E0
    LD A,(DustFlags)                           ; $A39D: 3A 07 9A  pitch sign selects the edge
    AND $08                                    ; $A3A0: E6 08
    JR Z,L_A3AF                                ; $A3A2: 28 0B
    XOR A                                      ; $A3A4: AF
    LD (L_A3FB),A                              ; $A3A5: 32 FB A3  SMC: Y AND mask 0 at L_A3FA
    LD A,$3F                                   ; $A3A8: 3E 3F
    LD (L_A3FD),A                              ; $A3AA: 32 FD A3  SMC: Y OR value $3F at L_A3FC (top edge)
    JR L_A3C4                                  ; $A3AD: 18 15
L_A3AF:
    LD A,$BF                                   ; $A3AF: 3E BF
    LD (L_A3FD),A                              ; $A3B1: 32 FD A3  SMC: Y OR value $BF at L_A3FC (bottom edge)
    JR L_A3C4                                  ; $A3B4: 18 0E
L_A3B6:
    LD A,$80                                   ; $A3B6: 3E 80
    LD (L_A3FB),A                              ; $A3B8: 32 FB A3  SMC: Y AND mask $80 at L_A3FA (random sign)
    LD A,$3F                                   ; $A3BB: 3E 3F
    LD (L_A3FD),A                              ; $A3BD: 32 FD A3  SMC: Y OR value $3F at L_A3FC (edge)
    XOR A                                      ; $A3C0: AF
    LD (L_A3E1),A                              ; $A3C1: 32 E1 A3  SMC: Z OR value 0 at L_A3E0
L_A3C4:
    LD A,(AlternatingBits)                     ; $A3C4: 3A 09 9A  alternate the two edge patterns
    RLCA                                       ; $A3C7: 07  $55 <-> $AA; carry = old bit 7
    LD (AlternatingBits),A                     ; $A3C8: 32 09 9A
    JR C,L_A3F0                                ; $A3CB: 38 23  top/bottom edge pattern
    CALL AdvanceRandomHL                       ; $A3CD: CD 65 A4  random X sign
    OR $7F                                     ; $A3D0: F6 7F  |X| = $77: left/right edge, random sign
    AND $F7                                    ; $A3D2: E6 F7
    LD (DE),A                                  ; $A3D4: 12
    INC DE                                     ; $A3D5: 13
    CALL AdvanceRandomHL                       ; $A3D6: CD 65 A4
    AND $BF                                    ; $A3D9: E6 BF  random Y: sign random, |Y| <= 63
    LD (DE),A                                  ; $A3DB: 12
    INC DE                                     ; $A3DC: 13
L_A3DD:
    CALL AdvanceRandomHL                       ; $A3DD: CD 65 A4  random Z
L_A3E0:
defc L_A3E1 = L_A3E0 + 1 ; byte inside instruction at $A3E0
    OR $80                                     ; $A3E0: F6 80  SMC operand: $80 ($A39A) or 0 ($A3C1)

; VERIFIED: Store the new Z byte, step DE past the two fraction bytes, save
; DustRecordPointer and the random state AuxRandomSeed, then exit (DustRespawnExit).
; Also entered from the side-view respawn at $A426.
StoreRespawnedDust:
    LD (DE),A                                  ; $A3E2: 12
    INC DE                                     ; $A3E3: 13  skip the two fraction bytes
    INC DE                                     ; $A3E4: 13
    INC DE                                     ; $A3E5: 13
    LD (DustRecordPointer),DE                  ; $A3E6: ED 53 FB 99  next record for NextDustParticle
    LD (AuxRandomSeed),HL                      ; $A3EA: 22 63 70  save the dust random state

; VERIFIED: SELF-MODIFIED OPCODE: normally JP NextDustParticle ($C3).  SeedLaunchDust writes $C9
; (RET) here at $7A92 before calling RespawnDustFront 16 times and restores
; $C3 at $7AB5.
DustRespawnExit:
    JP NextDustParticle                        ; $A3ED: C3 93 A1
L_A3F0:
    CALL AdvanceRandomHL                       ; $A3F0: CD 65 A4
    AND $F7                                    ; $A3F3: E6 F7  random X
    LD (DE),A                                  ; $A3F5: 12
    INC DE                                     ; $A3F6: 13
    CALL AdvanceRandomHL                       ; $A3F7: CD 65 A4  Y from the patched AND/OR below
L_A3FA:
defc L_A3FB = L_A3FA + 1 ; byte inside instruction at $A3FA
    AND $80                                    ; $A3FA: E6 80  SMC operand: $80 ($A3B8) or 0 ($A3A5)
L_A3FC:
defc L_A3FD = L_A3FC + 1 ; byte inside instruction at $A3FC
    OR $3F                                     ; $A3FC: F6 3F  SMC operand: $3F ($A3AA/$A3BD) or $BF ($A3B1): Y edge
    LD (DE),A                                  ; $A3FE: 12
    INC DE                                     ; $A3FF: 13
    JR L_A3DD                                  ; $A400: 18 DB

; VERIFIED: Respawn the current particle in a side view.  Reached from L_A38D with C =
; CurrentScreenId - 1 (1 left, 2 right), DE = record (DustRecordPointer), HL = random state.
; Without a vertical rate (DustPitchRate; the side views swap the rates in): X = +120 in
; the left view, -120 in the right view (at the edge), Y = random 0..63 with a random
; sign, Z = random 0..127.  With a rate Z gets bit 7 ($80..$FF), and AlternatingBits
; alternates that pattern with a random X (magnitude bit 3 clear, at most 119) on the top
; edge (Y = +63) when DustFlags bit 3 (pitch sign) is set, else the bottom edge (Y = -63).
; Record bytes 3..4 (fractions) are kept; StoreRespawnedDust writes Z, advances
; DustRecordPointer by 5 and saves the random state.
; Evidence: instruction semantics; tools/check_routines.py dust/p5-side-view-respawn.
RespawnDustSideView:
    LD A,(DustPitchRate)                       ; $A402: 3A F8 99  vertical rate of this view (side views swap the rates in)
    AND A                                      ; $A405: A7
    JR NZ,L_A428                               ; $A406: 20 20
    XOR A                                      ; $A408: AF
    LD (L_A425),A                              ; $A409: 32 25 A4  Z OR operand 0: Z = 0..127
L_A40C:
    DEC C                                      ; $A40C: 0D  C = 1: left view, C = 2: right view
    JR NZ,L_A414                               ; $A40D: 20 05
    LD A,$78                                   ; $A40F: 3E 78  left view: X = +120, at the edge
    LD (DE),A                                  ; $A411: 12
    JR L_A417                                  ; $A412: 18 03
L_A414:
    LD A,$F8                                   ; $A414: 3E F8  right view: X = -120 (sign bit 7 set)
    LD (DE),A                                  ; $A416: 12
L_A417:
    INC DE                                     ; $A417: 13
    CALL AdvanceRandomHL                       ; $A418: CD 65 A4  Y: magnitude 0..63 with a random sign
    AND $BF                                    ; $A41B: E6 BF
L_A41D:
    LD (DE),A                                  ; $A41D: 12  store Y (record byte 1)
    INC DE                                     ; $A41E: 13
    CALL AdvanceRandomHL                       ; $A41F: CD 65 A4  Z = random 0..127 OR the patched operand
    AND $7F                                    ; $A422: E6 7F
L_A424:
defc L_A425 = L_A424 + 1 ; byte inside instruction at $A424
    OR $80                                     ; $A424: F6 80  SMC operand: $00 without, $80 with a vertical rate (Z bit 7)
    JR StoreRespawnedDust                      ; $A426: 18 BA  store Z, save the pointer and the random state
L_A428:
    LD A,$80                                   ; $A428: 3E 80
    LD (L_A425),A                              ; $A42A: 32 25 A4  Z OR operand $80: Z = 128..255
    LD A,(AlternatingBits)                     ; $A42D: 3A 09 9A  alternate the two patterns: bit 7 into carry
    RLCA                                       ; $A430: 07
    LD (AlternatingBits),A                     ; $A431: 32 09 9A
    JR NC,L_A40C                               ; $A434: 30 D6  no carry: X at the side edge as above
    CALL AdvanceRandomHL                       ; $A436: CD 65 A4  carry: random X, magnitude bit 3 clear (at most 119)
    AND $F7                                    ; $A439: E6 F7
    LD (DE),A                                  ; $A43B: 12
    INC DE                                     ; $A43C: 13
    LD A,(DustFlags)                           ; $A43D: 3A 07 9A  pitch sign (DustFlags bit 3) chooses the edge
    AND $08                                    ; $A440: E6 08
    JR Z,L_A448                                ; $A442: 28 04
    LD A,$3F                                   ; $A444: 3E 3F  Y = +63: top edge
    JR L_A41D                                  ; $A446: 18 D5
L_A448:
    LD A,$BF                                   ; $A448: 3E BF  Y = -63: bottom edge
    JR L_A41D                                  ; $A44A: 18 D1

; VERIFIED: Exchange record bytes 0 and 1 (X and Y, magnitude plus sign bit 7) of the first
; DustRemaining particle records at DustParticleRecords; later records are untouched.
; Called by MoveAndPlotDust when CurrentScreenId differs from DustLastScreenId.
; Clobbers: A, B, C, D, E, H, L.
; Evidence: instruction semantics; tools/check_routines.py dust/p5-side-view-respawn.
SwapDustParticleXY:
    LD A,(DustRemaining)                       ; $A44C: 3A 04 9A  B = particles in this pass (16, or 4 in witchspace)
    LD B,A                                     ; $A44F: 47
    LD HL,DustParticleRecords                  ; $A450: 21 6C A4  first particle record
L_A453:
    LD D,H                                     ; $A453: 54
    LD E,L                                     ; $A454: 5D
    INC DE                                     ; $A455: 13  DE = byte 1 (Y)
    LD A,(DE)                                  ; $A456: 1A
    LD C,A                                     ; $A457: 4F
    LD A,(HL)                                  ; $A458: 7E
    LD (DE),A                                  ; $A459: 12  byte 1 = old X
    LD (HL),C                                  ; $A45A: 71  byte 0 = old Y
    LD A,L                                     ; $A45B: 7D
    ADD A,$05                                  ; $A45C: C6 05  5-byte record stride
    JR NC,L_A461                               ; $A45E: 30 01
    INC H                                      ; $A460: 24
L_A461:
    LD L,A                                     ; $A461: 6F
    DJNZ L_A453                                ; $A462: 10 EF
    RET                                        ; $A464: C9

; VERIFIED: Advance the 16-bit generator held in HL with the NextRandomByte recurrence:
; t = 2*H + carry, new L = t AND 255, new H = new L + old L + (t >> 8).
; Output: A = new H.  B = new L.  Carry is an input and an output.
; Evidence: instruction semantics; RespawnDust keeps the seed in AuxRandomSeed between calls.
AdvanceRandomHL:
    LD A,H                                     ; $A465: 7C
    ADC A,A                                    ; $A466: 8F
    LD B,A                                     ; $A467: 47
    ADC A,L                                    ; $A468: 8D
    LD H,A                                     ; $A469: 67
    LD L,B                                     ; $A46A: 68
    RET                                        ; $A46B: C9

; VERIFIED: 16 particle records of 5 bytes: X (bits 0..6 magnitude, bit 7 sign), Y (the same), Z
; depth, X fraction, Y fraction (the layout written by StoreAndPlotDust).
; MoveAndPlotDust walks them with DustRecordPointer; RespawnDust and RespawnDustSideView
; rebuild single records, SeedLaunchDust rebuilds all 16 at launch, SwapDustParticleXY swaps X/Y
; when the view changes.  The initial bytes have no meaning.
; Evidence: runtime reads and writes cover all 80 bytes; tools/check_routines.py
; dust/stardust-update, dust/launch-dust-respawn and dust/p5-side-view-respawn.
DustParticleRecords:
    defb $00,$10,$FF,$38,$4B                                                              ; $A46C ...8K
    defb $90,$10,$C8,$01,$41                                                              ; $A471 ....A
    defb $90,$00,$B4,$17,$01                                                              ; $A476 .....
    defb $90,$90,$A0,$02,$03                                                              ; $A47B .....
    defb $00,$90,$D2,$04,$39                                                              ; $A480 ....9
    defb $10,$90,$DC,$59,$06                                                              ; $A485 ...Y.
    defb $10,$00,$28,$22,$78                                                              ; $A48A ..("x
    defb $10,$10,$32,$64,$15                                                              ; $A48F ..2d.
    defb $02,$12,$23,$63,$79                                                              ; $A494 ..#cy
    defb $82,$06,$8C,$03,$79                                                              ; $A499 ....y
    defb $80,$03,$14,$7B,$15                                                              ; $A49E ...{.
    defb $6E,$78,$3C,$02,$22                                                              ; $A4A3 nx<."
    defb $04,$96,$4C,$64,$0C                                                              ; $A4A8 ..Ld.
    defb $05,$20,$EA,$2B,$66                                                              ; $A4AD . .+f
    defb $64,$38,$05,$69,$17                                                              ; $A4B2 d8.i.
    defb $04,$43,$38,$F3,$E7                                                              ; $A4B7 .C8..

; VERIFIED: Counter of the flashing condition colour: UpdateConditionIndicator increments it on
; every call while FlightCondition is $63; its bit 1 selects colour 2 or 0, so the colour
; changes every second call.
ConditionFlashPhase:
    defb $00                                                                              ; $A4BC .

; ============================================================================
; Cockpit status: condition colour, energy, damage, missiles, escape pod
; Per-frame flight instrument updates and their state variables.
; ============================================================================

; VERIFIED: Show FlightCondition (the condition colour) and leave it at 4 (green) for the next frame.
; 0 (docked): return at once.  An empty ForwardShield or AftShield makes it 2 (red) unless
; it is $63; $63 (set by UpdateEnergyAndShields while EnergyBank4 is not full) flashes:
; colour 2 or 0 from bit 1 of ConditionFlashPhase.
; Cockpit views (CurrentScreenId < 4): the colour becomes the attribute (ink on black) of
; the four encounter-circle cells, and the missile status cell (row 23, column 7) gets
; white ink on paper 0, 4 or 2 for MissileState 0, 1 or 2.
; Other screens: two characters at row 1, columns 28..29, in overwrite mode.  Screens 4..8
; print codes $21,$22 with attribute $17 for red, otherwise $23,$24 with attribute $10 +
; colour (colour 0 shown as 2); screens 9 and above print $23,$24 with the colour itself.
; Callers: PrintScreenTitle, ShowCommanderStatus, UpdateFlightMessage.
; Evidence: instruction semantics; FlightCondition values (see that variable).
UpdateConditionIndicator:
    LD HL,FlightCondition                      ; $A4BD: 21 62 70
    LD A,(HL)                                  ; $A4C0: 7E
    AND A                                      ; $A4C1: A7  docked: no condition indicator
    RET Z                                      ; $A4C2: C8
    LD A,(ForwardShield)                       ; $A4C3: 3A 46 70  fore shield empty?
    AND A                                      ; $A4C6: A7
    JR Z,L_A4CF                                ; $A4C7: 28 06
    LD A,(AftShield)                           ; $A4C9: 3A 48 70  aft shield empty?
    AND A                                      ; $A4CC: A7
    JR NZ,L_A4D6                               ; $A4CD: 20 07
L_A4CF:
    LD A,(HL)                                  ; $A4CF: 7E
    CP $63                                     ; $A4D0: FE 63  flashing ($63) has priority over red
    JR Z,L_A4D6                                ; $A4D2: 28 02
    LD (HL),$02                                ; $A4D4: 36 02  red: a shield is down
L_A4D6:
    LD A,(HL)                                  ; $A4D6: 7E
    CP $63                                     ; $A4D7: FE 63  $63: flashing red (EnergyBank4 not full)
    JR NZ,L_A4E8                               ; $A4D9: 20 0D
    LD HL,ConditionFlashPhase                  ; $A4DB: 21 BC A4  flash phase counter
    INC (HL)                                   ; $A4DE: 34
    BIT 1,(HL)                                 ; $A4DF: CB 4E  bit 1: colour 2 for two calls, 0 for two
    JR NZ,L_A4E6                               ; $A4E1: 20 03
    XOR A                                      ; $A4E3: AF
    JR L_A4E8                                  ; $A4E4: 18 02
L_A4E6:
    LD A,$02                                   ; $A4E6: 3E 02
L_A4E8:
    LD D,A                                     ; $A4E8: 57  D = colour: 0, 2 red, 4 green or 6 yellow
    LD A,(CurrentScreenId)                     ; $A4E9: 3A 41 70
    CP $04                                     ; $A4EC: FE 04  cockpit views 0..3?
    JR NC,L_A511                               ; $A4EE: 30 21
    LD HL,$5A28                                ; $A4F0: 21 28 5A  attribute cells of the encounter circle tiles (rows 17..18, columns 8..9)
    LD (HL),D                                  ; $A4F3: 72
    INC HL                                     ; $A4F4: 23
    LD (HL),D                                  ; $A4F5: 72
    LD HL,$5A48                                ; $A4F6: 21 48 5A  second row of the circle cells
    LD (HL),D                                  ; $A4F9: 72
    INC HL                                     ; $A4FA: 23
    LD (HL),D                                  ; $A4FB: 72
    CALL SetConditionGreen                     ; $A4FC: CD 53 A5  FlightCondition = 4 (green) for the next frame
    LD A,(MissileState)                        ; $A4FF: 3A 0F A8  missile status cell paper from MissileState (1 -> 4)
    CP $01                                     ; $A502: FE 01
    JR NZ,L_A508                               ; $A504: 20 02
    LD A,$04                                   ; $A506: 3E 04  armed and searching: green paper
L_A508:
    ADD A,A                                    ; $A508: 87
    ADD A,A                                    ; $A509: 87
    ADD A,A                                    ; $A50A: 87
    ADD A,$07                                  ; $A50B: C6 07  attribute = paper * 8 + white ink 7
    LD ($5AE7),A                               ; $A50D: 32 E7 5A  missile status cell: row 23, column 7
    RET                                        ; $A510: C9
L_A511:
    LD HL,CharacterBlendOpcode                 ; $A511: 21 BF BB  other screens: indicator in the title row
    LD (HL),$00                                ; $A514: 36 00  CharacterBlendOpcode = NOP (overwrite glyphs)
    LD HL,$011B                                ; $A516: 21 1B 01  TextColumn 27, row 1: characters land at columns 28..29
    LD (TextColumn),HL                         ; $A519: 22 0D A8
    CP $09                                     ; $A51C: FE 09  screens 9 and above: codes $23,$24 with the raw colour
    JR NC,L_A53C                               ; $A51E: 30 1C
    LD A,D                                     ; $A520: 7A
    AND A                                      ; $A521: A7
    JR Z,L_A536                                ; $A522: 28 12  dark flash phase: shown as 2, red ink on red paper
    CP $02                                     ; $A524: FE 02  red?
    JR NZ,L_A538                               ; $A526: 20 10
    LD A,$21                                   ; $A528: 3E 21  token: "!"
    CALL PrintToken                            ; $A52A: CD 9D BA
    LD A,$22                                   ; $A52D: 3E 22  token: """
    CALL PrintToken                            ; $A52F: CD 9D BA
    LD D,$17                                   ; $A532: 16 17  red: attribute $17, white ink on red paper
    JR L_A548                                  ; $A534: 18 12
L_A536:
    LD D,$02                                   ; $A536: 16 02
L_A538:
    LD A,$10                                   ; $A538: 3E 10  attribute $10 + colour: coloured ink on red paper
    ADD A,D                                    ; $A53A: 82
    LD D,A                                     ; $A53B: 57
L_A53C:
    PUSH DE                                    ; $A53C: D5  codes $23,$24 with attribute D
    LD A,$23                                   ; $A53D: 3E 23  token: "#"
    CALL PrintToken                            ; $A53F: CD 9D BA
    LD A,$24                                   ; $A542: 3E 24  token: "$"
    CALL PrintToken                            ; $A544: CD 9D BA
    POP DE                                     ; $A547: D1
L_A548:
    LD HL,$583C                                ; $A548: 21 3C 58  attributes of the two indicator cells at row 1, columns 28..29
    LD (HL),D                                  ; $A54B: 72
    INC HL                                     ; $A54C: 23
    LD (HL),D                                  ; $A54D: 72
    LD HL,CharacterBlendOpcode                 ; $A54E: 21 BF BB
    LD (HL),$A9                                ; $A551: 36 A9  CharacterBlendOpcode = XOR C (blend glyphs)

; VERIFIED: Set FlightCondition = 4 (green): the end of UpdateConditionIndicator, also called by it
; on the cockpit views.
SetConditionGreen:
    LD A,$04                                   ; $A553: 3E 04
    LD (FlightCondition),A                     ; $A555: 32 62 70
    RET                                        ; $A558: C9

; VERIFIED: Cockpit-view frame update: return unless CurrentScreenId < 4; draw the
; indicators, run UpdateMissileControl, UpdateEscapePod and UseEnergyBomb, clear
; the one-shot key bits 1, 2, 3, 5 and 6 (T, F, U, W, Q) of KeyFlagsCombat, then continue
; at UpdateEnergyAndShields.  Caller: L_72FD.
UpdateCockpitSystems:
    LD A,(CurrentScreenId)                     ; $A559: 3A 41 70
    CP $04                                     ; $A55C: FE 04  cockpit views 0..3 only
    RET NC                                     ; $A55E: D0
    CALL DrawCockpitIndicators                 ; $A55F: CD 60 A6
    CALL UpdateMissileControl                  ; $A562: CD 06 A7
    CALL UpdateEscapePod                       ; $A565: CD 7B A7
    CALL UseEnergyBomb                         ; $A568: CD 60 92
    LD HL,KeyFlagsCombat                       ; $A56B: 21 11 FC
    LD A,(HL)                                  ; $A56E: 7E
    AND $91                                    ; $A56F: E6 91  keep fire, E and C (bits 0, 4, 7); drop T, F, U, W, Q
    LD (HL),A                                  ; $A571: 77

; VERIFIED: Energy and shield update, also called directly by L_72D2 on the non-view screens.
; Docked (FlightCondition = 0): return.  EnergyBank4 below $A0 requests the flashing
; condition ($63).  Then one RechargeEnergyBanks step, fore damage FrontDamageThisUpdate
; applied to ForwardShield and aft damage RearDamageThisUpdate to AftShield
; (ApplyShieldDamage), and finally the drain units EnergyDrainThisUpdate (+1 while CloakingDeviceActive)
; taken four times from the banks (DrainEnergyBanks).
; Evidence: instruction semantics; dashboard variables documented in their own entries.
UpdateEnergyAndShields:
    LD HL,FlightCondition                      ; $A572: 21 62 70
    XOR A                                      ; $A575: AF
    CP (HL)                                    ; $A576: BE
    RET Z                                      ; $A577: C8  docked: nothing to do
    LD A,(EnergyBank4)                         ; $A578: 3A 5A 70
    CP $A0                                     ; $A57B: FE A0  is the last energy bank full ($A0)?
    JR Z,L_A584                                ; $A57D: 28 05
    LD A,$63                                   ; $A57F: 3E 63  no: flashing condition ($63)
    LD (FlightCondition),A                     ; $A581: 32 62 70
L_A584:
    CALL RechargeEnergyBanks                   ; $A584: CD 3A A6
    LD HL,ForwardShield                        ; $A587: 21 46 70  fore shield
    LD A,(FrontDamageThisUpdate)               ; $A58A: 3A 18 DA  fore damage of this update
    CALL ApplyShieldDamage                     ; $A58D: CD C0 A5
    LD HL,AftShield                            ; $A590: 21 48 70  aft shield
    LD A,(RearDamageThisUpdate)                ; $A593: 3A 19 DA  aft damage of this update
    CALL ApplyShieldDamage                     ; $A596: CD C0 A5
    LD A,(CloakingDeviceActive)                ; $A599: 3A 0C A8  cloaking device on: one more unit of drain
    AND A                                      ; $A59C: A7
    LD A,(EnergyDrainThisUpdate)               ; $A59D: 3A 17 DA  drain units of this update (laser, ECM)
    JR Z,L_A5A3                                ; $A5A0: 28 01
    INC A                                      ; $A5A2: 3C
L_A5A3:
    LD C,A                                     ; $A5A3: 4F
    LD B,$04                                   ; $A5A4: 06 04  drain C four times

; VERIFIED: Take C from the energy banks B times, starting with EnergyBank1.  A bank holding less
; than C is set to 0 (its rest is lost) and the next bank (2 bytes on) pays C instead;
; later repetitions continue with the current bank.  When no bank is left PlayerDeadFlag
; = 1 (the game ends) and the routine returns.
; Input: B = repetitions, C = amount.  Clobbers: A, B, D, HL.
DrainEnergyBanks:
    LD HL,EnergyBank1                          ; $A5A6: 21 54 70
    LD D,$04                                   ; $A5A9: 16 04  D = banks left to draw on
L_A5AB:
    LD A,(HL)                                  ; $A5AB: 7E
    SUB C                                      ; $A5AC: 91
    JR NC,L_A5BC                               ; $A5AD: 30 0D
    LD (HL),$00                                ; $A5AF: 36 00  bank cannot pay C: empty it, its rest is lost
    INC HL                                     ; $A5B1: 23  next bank
    INC HL                                     ; $A5B2: 23
    DEC D                                      ; $A5B3: 15
    JR NZ,L_A5AB                               ; $A5B4: 20 F5
    LD A,$01                                   ; $A5B6: 3E 01  all four banks empty
    LD (PlayerDeadFlag),A                      ; $A5B8: 32 7A 70  the ship is lost: the game ends
    RET                                        ; $A5BB: C9
L_A5BC:
    LD (HL),A                                  ; $A5BC: 77  bank keeps the rest; the same bank pays next time
    DJNZ L_A5AB                                ; $A5BD: 10 EC
    RET                                        ; $A5BF: C9

; VERIFIED: Apply damage A to the shield at HL (ForwardShield or AftShield).
; A = 0: DamageCounter decays by one (not below zero) and return.  A >= $46 first runs
; DamageEquipmentOrCargo.  The shield then loses A up to five times; if it cannot pay it
; becomes 0, the remaining repetitions (if any) drain A from the energy banks
; (DrainEnergyBanks) and DamageCounter grows by 5; at 13 or more DamageEquipmentOrCargo
; runs (fall-through).  Clobbers: A, B, C, D, E, HL.
ApplyShieldDamage:
    LD C,A                                     ; $A5C0: 4F
    AND A                                      ; $A5C1: A7
    JR NZ,L_A5CC                               ; $A5C2: 20 08  damage this update?
    LD HL,DamageCounter                        ; $A5C4: 21 39 A6  none: DamageCounter decays by one
    LD A,(HL)                                  ; $A5C7: 7E
    AND A                                      ; $A5C8: A7
    RET Z                                      ; $A5C9: C8
    DEC (HL)                                   ; $A5CA: 35
    RET                                        ; $A5CB: C9
L_A5CC:
    PUSH BC                                    ; $A5CC: C5
    PUSH HL                                    ; $A5CD: E5
    CP $46                                     ; $A5CE: FE 46  damage >= $46: chance of equipment damage
    CALL NC,DamageEquipmentOrCargo             ; $A5D0: D4 F0 A5  heavy hit: random equipment or cargo loss
    POP HL                                     ; $A5D3: E1
    POP BC                                     ; $A5D4: C1
    LD B,$05                                   ; $A5D5: 06 05  subtract the damage up to five times
L_A5D7:
    LD A,(HL)                                  ; $A5D7: 7E
    SUB C                                      ; $A5D8: 91
    JR C,L_A5DF                                ; $A5D9: 38 04
    LD (HL),A                                  ; $A5DB: 77
    DJNZ L_A5D7                                ; $A5DC: 10 F9
    RET                                        ; $A5DE: C9
L_A5DF:
    LD (HL),$00                                ; $A5DF: 36 00  shield exhausted
    DEC B                                      ; $A5E1: 05  that was the last repetition: no energy loss
    RET Z                                      ; $A5E2: C8
    CALL DrainEnergyBanks                      ; $A5E3: CD A6 A5  remaining repetitions drain the banks
    LD HL,DamageCounter                        ; $A5E6: 21 39 A6
    LD A,(HL)                                  ; $A5E9: 7E
    ADD A,$05                                  ; $A5EA: C6 05  DamageCounter += 5; equipment damage from 13
    LD (HL),A                                  ; $A5EC: 77
    CP $0D                                     ; $A5ED: FE 0D  13 or more: fall into DamageEquipmentOrCargo
    RET C                                      ; $A5EF: D8

; VERIFIED: Random damage effect, chosen from bits 2..7 of AuxRandomSeed (n = 0..63):
;   0      fuel leak (TriggerFuelLeak: fuel = 0, "FUEL LEAK*")
;   1..6   destroy E.C.M., fuel scoops, escape pod, energy bomb, energy unit or
;          docking computers (if fitted) and raise "<item> DESTROYED"
;   7..16  lose one ton of cargo 2..11 (RADIOACTIVES..FURS), if any is carried
;   17..63 nothing
; Returns at once while a " DESTROYED" message is pending (FlightMessageToken = $FD).
; Evidence: tokens $6C+offset and $D0+commodity passed to the message system.
DamageEquipmentOrCargo:
    LD A,(FlightMessageToken)                  ; $A5F0: 3A 48 D4  equipment-destroyed message still pending?
    CP $FD                                     ; $A5F3: FE FD
    RET Z                                      ; $A5F5: C8
    LD A,(AuxRandomSeed)                       ; $A5F6: 3A 63 70  random byte (low byte of AuxRandomSeed)
    RRCA                                       ; $A5F9: 0F
    RRCA                                       ; $A5FA: 0F
    AND $3F                                    ; $A5FB: E6 3F  n = bits 2..7: 0..63
    JP Z,TriggerFuelLeak                       ; $A5FD: CA 62 D8  0: fuel leak
    CP $11                                     ; $A600: FE 11  >= $11: nothing
    RET NC                                     ; $A602: D0
    DEC A                                      ; $A603: 3D
    CP $06                                     ; $A604: FE 06  7..16: lose cargo
    JR NC,L_A626                               ; $A606: 30 1E
    LD HL,EcmFitted                            ; $A608: 21 47 A8  equipment base EcmFitted; offsets 0 and 3..7 follow
    AND A                                      ; $A60B: A7
    JR Z,L_A610                                ; $A60C: 28 02
    ADD A,$02                                  ; $A60E: C6 02  n = 2..6: offsets 3..7 (the two unused bytes are skipped)
L_A610:
    CALL AddAToHL                              ; $A610: CD 19 B7
    LD A,(HL)                                  ; $A613: 7E  fitted?
    AND A                                      ; $A614: A7
    RET Z                                      ; $A615: C8
    LD (HL),D                                  ; $A616: 72  D = 0 after AddAToHL: the item is destroyed
    LD A,E                                     ; $A617: 7B
    ADD A,$6C                                  ; $A618: C6 6C  token $6C+offset: E.C.M.SYSTEM .. DOCKING COMPUTERS
L_A61A:
    LD (DestroyedItemToken),A                  ; $A61A: 32 4B D4  item token for the " DESTROYED" message
    CALL ColourInstrumentBlocks                ; $A61D: CD 6E 9A  recolour the instruments (colour shows EscapePodFitted)
    LD HL,EquipmentDestroyedMessage            ; $A620: 21 85 A8  raise the " DESTROYED" message
    SET 7,(HL)                                 ; $A623: CB FE
    RET                                        ; $A625: C9
L_A626:
    LD HL,CargoHold-4                          ; $A626: 21 29 A8  A = 6..15 selects CargoHold+2..CargoHold+11
    CALL AddAToHL                              ; $A629: CD 19 B7
    LD A,(HL)                                  ; $A62C: 7E  carried?
    AND A                                      ; $A62D: A7
    RET Z                                      ; $A62E: C8
    DEC (HL)                                   ; $A62F: 35  lose one ton
    LD HL,CargoFreeSpace                       ; $A630: 21 3E A8  and gain one ton of free space
    INC (HL)                                   ; $A633: 34
    LD A,$CC                                   ; $A634: 3E CC  token $CC+A = $D0+commodity
    ADD A,E                                    ; $A636: 83
    JR L_A61A                                  ; $A637: 18 E1

; VERIFIED: Damage counter: +5 each time damage exhausts ForwardShield/AftShield (ApplyShieldDamage), -1 per
; damage-free call; 13 or more triggers DamageEquipmentOrCargo.
DamageCounter:
    defb $00                                                                              ; $A639 .

; VERIFIED: Recharge one step, twice when EnergyUnitFitted is nonzero (CALL NZ then fall-through).
; One step (RechargeStep): increment the first bank below $A0, scanning from EnergyBank4 down
; to EnergyBank1 in steps of 2; when all four are full, increment ForwardShield and AftShield up to $A0.
; Evidence: instruction semantics; the status screen (L_D161) prints ENERGY UNIT for it.
RechargeEnergyBanks:
    LD A,(EnergyUnitFitted)                    ; $A63A: 3A 4D A8  energy unit fitted: recharge twice
    AND A                                      ; $A63D: A7
    CALL NZ,RechargeStep                       ; $A63E: C4 41 A6

; VERIFIED: One recharge step of RechargeEnergyBanks (see there).
RechargeStep:
    LD HL,EnergyBank4                          ; $A641: 21 5A 70
    LD B,$04                                   ; $A644: 06 04  four banks, EnergyBank4 first
L_A646:
    LD A,(HL)                                  ; $A646: 7E
    CP $A0                                     ; $A647: FE A0  bank full?
    JR Z,L_A64D                                ; $A649: 28 02
    INC (HL)                                   ; $A64B: 34  one unit into that bank
    RET                                        ; $A64C: C9
L_A64D:
    DEC HL                                     ; $A64D: 2B  previous bank
    DEC HL                                     ; $A64E: 2B
    DJNZ L_A646                                ; $A64F: 10 F5
    LD HL,ForwardShield                        ; $A651: 21 46 70  all banks full: fore shield + 1
    CALL IncrementUpToFull                     ; $A654: CD 5A A6
    LD HL,AftShield                            ; $A657: 21 48 70  aft shield + 1

; VERIFIED: Increment the byte at HL unless it is already $A0 (full).
IncrementUpToFull:
    LD A,(HL)                                  ; $A65A: 7E
    CP $A0                                     ; $A65B: FE A0
    RET Z                                      ; $A65D: C8
    INC (HL)                                   ; $A65E: 34
    RET                                        ; $A65F: C9

; VERIFIED: Draw the encounter circle, ECM E and station S indicators, then restore XOR text mode.
; The original character-renderer path overwrites the scanner pixel under the E tile.
; scannerpixelfix=yes uses the same-size replacement that preserves that background bit.
DrawCockpitIndicators:
IF SCANNER_PIXEL_FIX
    INCLUDE "scanner-pixel-fix.asm"
ELSE
    LD HL,CharacterBlendOpcode                 ; $A660: 21 BF BB
    LD (HL),$00                                ; $A663: 36 00  CharacterBlendOpcode = NOP (overwrite glyphs)
    LD HL,$1108                                ; $A665: 21 08 11  circle top: row 17, column 9
    LD (TextColumn),HL                         ; $A668: 22 0D A8
    LD A,$26                                   ; $A66B: 3E 26  token: "&"
    CALL PrintToken                            ; $A66D: CD 9D BA
    LD HL,$1208                                ; $A670: 21 08 12  circle bottom: row 18, column 9
    LD (TextColumn),HL                         ; $A673: 22 0D A8
    LD A,$24                                   ; $A676: 3E 24  token: "$"
    CALL PrintToken                            ; $A678: CD 9D BA
    LD HL,$1607                                ; $A67B: 21 07 16  E indicator: rows 22..23, columns 8..9
    LD A,(EcmTimer)                            ; $A67E: 3A 16 DA  ECM active?
    AND A                                      ; $A681: A7
    JR Z,L_A689                                ; $A682: 28 05
    LD DE,EcmOnIndicatorTiles                  ; $A684: 11 C3 A6
    JR L_A68C                                  ; $A687: 18 03
L_A689:
    LD DE,EcmOffIndicatorTiles                 ; $A689: 11 C7 A6
L_A68C:
    CALL PrintTileSquare                       ; $A68C: CD A9 A6
    LD HL,$1615                                ; $A68F: 21 15 16  S indicator: rows 22..23, columns 22..23
    LD A,(StationPresent)                      ; $A692: 3A 77 70  station present?
    AND A                                      ; $A695: A7
    JR Z,L_A69D                                ; $A696: 28 05
    LD DE,StationOnIndicatorTiles              ; $A698: 11 CB A6
    JR L_A6A0                                  ; $A69B: 18 03
L_A69D:
    LD DE,StationOffIndicatorTiles             ; $A69D: 11 CF A6
L_A6A0:
    CALL PrintTileSquare                       ; $A6A0: CD A9 A6
    LD HL,CharacterBlendOpcode                 ; $A6A3: 21 BF BB
    LD (HL),$A9                                ; $A6A6: 36 A9  CharacterBlendOpcode = XOR C (blend glyphs)
    RET                                        ; $A6A8: C9

; VERIFIED: Draw a 2x2 tile: four PrintToken codes at DE, top row at column L, row H, then
; the next row.  Returns DE advanced by 4 and H + 2.
PrintTileSquare:
    CALL PrintTileRow                          ; $A6A9: CD AC A6

; VERIFIED: Set TextColumn/TextRow from HL, print two codes from DE, then H = H + 1.
PrintTileRow:
    LD (TextColumn),HL                         ; $A6AC: 22 0D A8
    PUSH HL                                    ; $A6AF: E5
    CALL PrintTwoTileCodes                     ; $A6B0: CD B6 A6
    POP HL                                     ; $A6B3: E1
    INC H                                      ; $A6B4: 24  next tile row
    RET                                        ; $A6B5: C9

; VERIFIED: Print two PrintToken codes from DE (falls into PrintTileCode).
PrintTwoTileCodes:
    CALL PrintTileCode                         ; $A6B6: CD B9 A6

; VERIFIED: Print the PrintToken code at DE, then DE = DE + 1.
PrintTileCode:
    LD A,(DE)                                  ; $A6B9: 1A
    PUSH DE                                    ; $A6BA: D5
    CALL PrintToken                            ; $A6BB: CD 9D BA
    POP DE                                     ; $A6BE: D1
    INC DE                                     ; $A6BF: 13
    RET                                        ; $A6C0: C9

; VERIFIED: Two bytes $26,$24: the same codes as the encounter-circle tiles that
; DrawCockpitIndicators prints from immediates.  No word in the image points here and
; no runtime access was recorded.  INFERRED: an unused copy.
L_A6C1:
    defb $26,$24                                                                          ; $A6C1 &$

; VERIFIED: 2x2 tile codes for PrintTileSquare: E indicator with EcmTimer nonzero.
EcmOnIndicatorTiles:
    defb $3B,$3C,$3D,$3E                                                                  ; $A6C3 ;<=>

; VERIFIED: 2x2 tile codes: E indicator position with EcmTimer zero.
EcmOffIndicatorTiles:
    defb $20,$20,$40,$40                                                                  ; $A6C7   @@

; VERIFIED: 2x2 tile codes: S indicator with StationPresent nonzero.
StationOnIndicatorTiles:
    defb $5B,$5C,$5D,$5E                                                                  ; $A6CB [\]^

; VERIFIED: 2x2 tile codes: S indicator position with StationPresent zero.
StationOffIndicatorTiles:
    defb $20,$5F,$40,$2B                                                                  ; $A6CF  _@+

; VERIFIED: Draw the four missile slots from the commander missile count.
; Returns in overwrite mode with all four missiles present, otherwise in XOR mode.
; Both original and scannerpixelfix implementations preserve this return convention.
DrawMissileIndicators:
    LD HL,$1702                                ; $A6D3: 21 02 17  row 23, column 2: slots at columns 3..6
    LD (TextColumn),HL                         ; $A6D6: 22 0D A8
    LD HL,CharacterBlendOpcode                 ; $A6D9: 21 BF BB
    LD (HL),$00                                ; $A6DC: 36 00  CharacterBlendOpcode = NOP (overwrite glyphs)
    LD A,(MissileCount)                        ; $A6DE: 3A 45 A8  one missile character per missile
    AND A                                      ; $A6E1: A7
    JR Z,L_A6EE                                ; $A6E2: 28 0A
    LD B,A                                     ; $A6E4: 47
L_A6E5:
    PUSH BC                                    ; $A6E5: C5
    LD A,$25                                   ; $A6E6: 3E 25  token: "%"
    CALL PrintToken                            ; $A6E8: CD 9D BA
    POP BC                                     ; $A6EB: C1
    DJNZ L_A6E5                                ; $A6EC: 10 F7
L_A6EE:
    LD A,(MissileCount)                        ; $A6EE: 3A 45 A8  then 4 - MissileCount empty slots
    NEG                                        ; $A6F1: ED 44
    ADD A,$04                                  ; $A6F3: C6 04
    RET Z                                      ; $A6F5: C8  four missiles: return in overwrite mode
    LD B,A                                     ; $A6F6: 47  B = empty slots
L_A6F7:
    PUSH BC                                    ; $A6F7: C5
    LD A,$40                                   ; $A6F8: 3E 40  token: "@"
    CALL PrintToken                            ; $A6FA: CD 9D BA
    POP BC                                     ; $A6FD: C1
    DJNZ L_A6F7                                ; $A6FE: 10 F7
    LD HL,CharacterBlendOpcode                 ; $A700: 21 BF BB
    LD (HL),$A9                                ; $A703: 36 A9  CharacterBlendOpcode = XOR C (blend glyphs)
    RET                                        ; $A705: C9
ENDIF
assert $-GameImage = CockpitIndicatorsLimit-$6048

; VERIFIED: Missile state machine (MissileState: 0 idle, 1 armed and searching, 2 locked).
; No missiles: return.  State 1 with MissileTarget zero and TargetedObjectCounter nonzero: lock
; (MissileTarget = TargetedObjectCounter, state 2, ROM BEEPER tone).  Then the one-shot key bits
; of KeyFlagsCombat: bit 1 arms (state 1 unless locked), bit 3 disarms (state 0), bit 2
; fires a locked missile: DispatchShipEvent(MissileTarget*16 + 2); on success
; state 0, SoundEffectRequests bit 1 set, MissileCount - 1 and the indicators are redrawn,
; otherwise "MISSILE JAMMED" is raised.
; Evidence: instruction semantics; DrawMissileIndicators reads MissileCount.
UpdateMissileControl:
    LD A,(MissileCount)                        ; $A706: 3A 45 A8  no missiles: nothing to do
    AND A                                      ; $A709: A7
    RET Z                                      ; $A70A: C8
    LD A,(MissileState)                        ; $A70B: 3A 0F A8
    CP $01                                     ; $A70E: FE 01  searching (state 1)?
    JR NZ,L_A72E                               ; $A710: 20 1C
    LD HL,MissileTarget                        ; $A712: 21 9A A8  no target locked yet?
    LD A,(HL)                                  ; $A715: 7E
    AND A                                      ; $A716: A7
    JR NZ,L_A72E                               ; $A717: 20 15
    LD A,(TargetedObjectCounter)               ; $A719: 3A 12 DA  object in the sights (8 - slot), 0 = none
    AND A                                      ; $A71C: A7
    JR Z,L_A72E                                ; $A71D: 28 0F
    LD (HL),A                                  ; $A71F: 77  lock on to it
    LD HL,MissileState                         ; $A720: 21 0F A8
    LD (HL),$02                                ; $A723: 36 02  locked (state 2)
    LD HL,$0070                                ; $A725: 21 70 00  ROM BEEPER pitch value
    LD DE,$0060                                ; $A728: 11 60 00  ROM BEEPER length in cycles
    CALL $03B5                                 ; $A72B: CD B5 03  ROM BEEPER: lock tone
L_A72E:
    LD HL,KeyFlagsCombat                       ; $A72E: 21 11 FC  latched combat keys
    LD A,(HL)                                  ; $A731: 7E
    LD HL,MissileState                         ; $A732: 21 0F A8
    SRL A                                      ; $A735: CB 3F  key bits into carry, bit 0 first
    SRL A                                      ; $A737: CB 3F
    JR C,L_A744                                ; $A739: 38 09  T (bit 1): arm
    SRL A                                      ; $A73B: CB 3F
    JR C,L_A752                                ; $A73D: 38 13  F (bit 2): fire
    SRL A                                      ; $A73F: CB 3F
    JR C,L_A74F                                ; $A741: 38 0C  U (bit 3): disarm
    RET                                        ; $A743: C9
L_A744:
    LD A,(HL)                                  ; $A744: 7E  already locked: T changes nothing
    CP $02                                     ; $A745: FE 02
    RET Z                                      ; $A747: C8
    LD (HL),$01                                ; $A748: 36 01  armed, searching (unless already locked)
    XOR A                                      ; $A74A: AF
    LD (MissileTarget),A                       ; $A74B: 32 9A A8  searching starts without a target
    RET                                        ; $A74E: C9
L_A74F:
    LD (HL),$00                                ; $A74F: 36 00  disarmed
    RET                                        ; $A751: C9
L_A752:
    LD A,(HL)                                  ; $A752: 7E  fire only when locked
    CP $02                                     ; $A753: FE 02
    RET NZ                                     ; $A755: C0
    LD A,(MissileTarget)                       ; $A756: 3A 9A A8
    ADD A,A                                    ; $A759: 87
    ADD A,A                                    ; $A75A: 87
    ADD A,A                                    ; $A75B: 87
    ADD A,A                                    ; $A75C: 87
    OR $02                                     ; $A75D: F6 02  event 2 with the target slot in the high nibble
    PUSH HL                                    ; $A75F: E5
    CALL DispatchShipEvent                     ; $A760: CD CA F2
    POP HL                                     ; $A763: E1
    JR Z,L_A76C                                ; $A764: 28 06  Z: launched
    LD HL,PendingMessageTable                  ; $A766: 21 7F A8  launch failed: raise "MISSILE JAMMED"
    SET 7,(HL)                                 ; $A769: CB FE
    RET                                        ; $A76B: C9
L_A76C:
    LD (HL),$00                                ; $A76C: 36 00  launched: state 0
    LD HL,SoundEffectRequests                  ; $A76E: 21 7D 70  sound request bit 1: missile launch
    SET 1,(HL)                                 ; $A771: CB CE
    LD HL,MissileCount                         ; $A773: 21 45 A8
    DEC (HL)                                   ; $A776: 35  one missile fewer
L_A777:
    JP DrawMissileIndicators                   ; $A777: C3 D3 A6  redraw the missile slots

; VERIFIED: Escape-pod countdown in frames: UpdateEscapePod sets 24 at launch and jumps to
; StartDockingSequence when it reaches zero.
EscapePodTimer:
    defb $00                                                                              ; $A77A .

; VERIFIED: While EscapePodTimer runs, count it down and jump to StartDockingSequence at zero.
; Otherwise launch when key bit 6 of KeyFlagsCombat is set, EscapePodFitted is nonzero and
; WitchspaceFlag is zero: timer 24, SpeedControl = $0010, legal score 0, pod used up, 17 bytes
; from MarketFluctuation cleared (alien items stay), CommanderFlags bit 5 cleared,
; free space 20 or 35 tons, ship event $17, chart cursor = current system.
; Evidence: ESCAPE POD token for EscapePodFitted (PrintInlineTokenIfSet list); runtime escape-pod
; scenario; tools/check_routines.py commander/p5-escape-pod.
UpdateEscapePod:
    LD HL,EscapePodTimer                       ; $A77B: 21 7A A7
    LD A,(HL)                                  ; $A77E: 7E
    AND A                                      ; $A77F: A7
    JR Z,L_A788                                ; $A780: 28 06  pod not launched: check the key
    DEC A                                      ; $A782: 3D
    LD (HL),A                                  ; $A783: 77
    JP Z,StartDockingSequence                  ; $A784: CA 02 71  timer expired
    RET                                        ; $A787: C9
L_A788:
    LD A,(KeyFlagsCombat)                      ; $A788: 3A 11 FC
    BIT 6,A                                    ; $A78B: CB 77  bit 6 of KeyFlagsCombat (Q): launch escape pod
    RET Z                                      ; $A78D: C8
    LD A,(EscapePodFitted)                     ; $A78E: 3A 4B A8  escape pod fitted?
    AND A                                      ; $A791: A7
    RET Z                                      ; $A792: C8
    LD A,(WitchspaceFlag)                      ; $A793: 3A 61 70  never in witchspace (WitchspaceFlag)
    AND A                                      ; $A796: A7
    RET NZ                                     ; $A797: C0
    LD A,$18                                   ; $A798: 3E 18  24 frames until StartDockingSequence
    LD (EscapePodTimer),A                      ; $A79A: 32 7A A7
    LD HL,$0010                                ; $A79D: 21 10 00  SpeedControl = $0010: speed 0
    LD (SpeedControl),HL                       ; $A7A0: 22 0C FF
    XOR A                                      ; $A7A3: AF
    LD (PlayerLegalScore),A                    ; $A7A4: 32 21 A8  escape pod clears the legal score
    LD (EscapePodFitted),A                     ; $A7A7: 32 4B A8  and is used up
    LD HL,MarketFluctuation                    ; $A7AA: 21 2C A8  17 bytes: fluctuation and CargoHold+0..15 (alien items kept)
    LD B,$11                                   ; $A7AD: 06 11
L_A7AF:
    LD (HL),A                                  ; $A7AF: 77
    INC HL                                     ; $A7B0: 23
    DJNZ L_A7AF                                ; $A7B1: 10 FC
    LD HL,CommanderFlags                       ; $A7B3: 21 72 A8  refugees (bit 5) are lost with the ship
    LD A,(HL)                                  ; $A7B6: 7E
    AND $DF                                    ; $A7B7: E6 DF  clear bit 5 of CommanderFlags
    LD (HL),A                                  ; $A7B9: 77
    LD HL,CargoFreeSpace                       ; $A7BA: 21 3E A8  free space of an empty hold
    LD A,(LargeCargoBayFitted)                 ; $A7BD: 3A 46 A8
    AND A                                      ; $A7C0: A7
    LD A,$14                                   ; $A7C1: 3E 14  free space 20 tons, or 35 with the large cargo bay
    JR Z,L_A7C7                                ; $A7C3: 28 02
    LD A,$23                                   ; $A7C5: 3E 23  large cargo bay: 35 tons
L_A7C7:
    LD (HL),A                                  ; $A7C7: 77
    LD A,$17                                   ; $A7C8: 3E 17  ship event $17
    CALL DispatchShipEvent                     ; $A7CA: CD CA F2
    LD A,(CurrentSystemX)                      ; $A7CD: 3A 5B A8  chart cursor = current system
    LD (ChartCursorX),A                        ; $A7D0: 32 7D A8
    LD A,(CurrentSystemY)                      ; $A7D3: 3A 59 A8
    LD (ChartCursorY),A                        ; $A7D6: 32 7E A8
    RET                                        ; $A7D9: C9

