; VERIFIED: Object slot locked by the missile (from TargetedObjectCounter); 0 = none.  Read by L_EB8C.
MissileTarget:
    defb $00                                                                              ; $A89A .

; VERIFIED: Dormant vector: JP ScoopCargoItem (see L_A897).
L_A89B:
    JP ScoopCargoItem                          ; $A89B: C3 B7 A8  dormant vector: ScoopCargoItem

; VERIFIED: Dormant vector: JP AwardBounty (see L_A897).
L_A89E:
    JP AwardBounty                             ; $A89E: C3 00 A9  dormant vector: AwardBounty

; VERIFIED: Dormant vector: JP AddCombatScore (see L_A897).
L_A8A1:
    JP AddCombatScore                          ; $A8A1: C3 EE A8  dormant vector: AddCombatScore

; VERIFIED: Three bytes without any code or runtime reference.
L_A8A4:
    defb $A7,$CD,$E4                                                                      ; $A8A4 ...

; VERIFIED: Dormant vector: JP DamageEquipmentOrCargo (see L_A897).
L_A8A7:
    JP DamageEquipmentOrCargo                  ; $A8A7: C3 F0 A5  dormant vector: DamageEquipmentOrCargo

; VERIFIED: Scooped item $FF (the canister of the special Asp): set CommanderFlags bit 6 (cloaking
; device), add 256 to the combat score and post token CLOAKING DEVICE in the scooped-cargo
; message; the contraband check that follows ignores $FF.
ScoopCloakingDevice:
    LD HL,CommanderFlags                       ; $A8AA: 21 72 A8
    SET 6,(HL)                                 ; $A8AD: CB F6  cloaking device (CommanderFlags bit 6)
    LD HL,CombatScoreHigh                      ; $A8AF: 21 24 A8
    INC (HL)                                   ; $A8B2: 34  +256 combat score
    LD A,$7D                                   ; $A8B3: 3E 7D  token CLOAKING DEVICE
    JR L_A8CA                                  ; $A8B5: 18 13

; VERIFIED: Entered by JP from L_EAD5 after the fuel-scoop and free-space checks, with A =
; commodity 0..16 or $FF.  Commodity: CargoFreeSpace - 1, CargoHold+A + 1, post
; the scooped message with token $D0+A, then AddContrabandPenalty for one ton.
ScoopCargoItem:
    PUSH AF                                    ; $A8B7: F5
    CP $FF                                     ; $A8B8: FE FF  $FF: the cloaking-device canister
    JR Z,ScoopCloakingDevice                   ; $A8BA: 28 EE
    LD HL,CargoFreeSpace                       ; $A8BC: 21 3E A8
    DEC (HL)                                   ; $A8BF: 35  one ton less free space
    LD E,A                                     ; $A8C0: 5F
    LD D,$00                                   ; $A8C1: 16 00
    LD HL,CargoHold                            ; $A8C3: 21 2D A8  CargoHold + commodity
    ADD HL,DE                                  ; $A8C6: 19
    INC (HL)                                   ; $A8C7: 34  one ton more of commodity A
    ADD A,$D0                                  ; $A8C8: C6 D0  commodity name token
L_A8CA:
    LD HL,CargoScoopedMessage                  ; $A8CA: 21 89 A8  scooped-cargo message slot
    SET 7,(HL)                                 ; $A8CD: CB FE  raise the scooped-cargo message with token A
    INC HL                                     ; $A8CF: 23
    LD (HL),A                                  ; $A8D0: 77
    POP AF                                     ; $A8D1: F1  A = commodity again ($FF: no penalty applies)
    LD B,$01                                   ; $A8D2: 06 01  quantity 1 for the contraband check

; VERIFIED: Raise PlayerLegalScore for B tons of commodity A: slaves (3) and narcotics (6)
; add 4*B, firearms (10) add 2*B, others nothing; saturates at 255.
; Callers: ScoopCargoItem, L_B3CE (buying).
; Evidence: tools/check_routines.py economy/contraband-penalty.
AddContrabandPenalty:
    CP $0A                                     ; $A8D4: FE 0A  firearms: 2 per ton
    JR Z,L_A8E1                                ; $A8D6: 28 09
    CP $03                                     ; $A8D8: FE 03  slaves: 4 per ton
    JR Z,L_A8DF                                ; $A8DA: 28 03
    CP $06                                     ; $A8DC: FE 06  narcotics: 4 per ton
    RET NZ                                     ; $A8DE: C0
L_A8DF:
    SLA B                                      ; $A8DF: CB 20  x2 again for slaves and narcotics
L_A8E1:
    SLA B                                      ; $A8E1: CB 20  B = 2 * tons
    LD HL,PlayerLegalScore                     ; $A8E3: 21 21 A8  legal score + penalty
    LD A,(HL)                                  ; $A8E6: 7E
    ADD A,B                                    ; $A8E7: 80
    JR NC,L_A8EC                               ; $A8E8: 30 02
    LD A,$FF                                   ; $A8EA: 3E FF  saturate at 255
L_A8EC:
    LD (HL),A                                  ; $A8EC: 77
    RET                                        ; $A8ED: C9

; VERIFIED: Add DE to the 24-bit combat score (fraction, low byte with carry); a carry into
; CombatScoreHigh increments it and raises "RIGHT ON COMMANDER*".
; Callers: L_DB43 (kill), L_F94A.
AddCombatScore:
    LD HL,CombatScoreFraction                  ; $A8EE: 21 22 A8
    LD A,(HL)                                  ; $A8F1: 7E
    ADD A,E                                    ; $A8F2: 83  fraction byte + E
    LD (HL),A                                  ; $A8F3: 77
    INC HL                                     ; $A8F4: 23
    LD A,(HL)                                  ; $A8F5: 7E
    ADC A,D                                    ; $A8F6: 8A  low byte + D + carry
    LD (HL),A                                  ; $A8F7: 77
    RET NC                                     ; $A8F8: D0
    INC HL                                     ; $A8F9: 23
    INC (HL)                                   ; $A8FA: 34  carry out of the low byte: high byte +1
    LD HL,RightOnCommanderMessage              ; $A8FB: 21 8B A8  raise "RIGHT ON COMMANDER*"
    JR L_A90D                                  ; $A8FE: 18 0D

; VERIFIED: DE = bounty in tenths of a credit (blueprint +8, L_DB43).  Zero: return.
; Otherwise keep it in LastBountyAmount, add it to the cash (AddCash) and raise " CR".
AwardBounty:
    LD A,D                                     ; $A900: 7A
    OR E                                       ; $A901: B3
    RET Z                                      ; $A902: C8
    LD (LastBountyAmount),DE                   ; $A903: ED 53 49 D4  amount printed with the " CR" message
    CALL AddCash                               ; $A907: CD 4D B8  cash += DE tenths of a credit
    LD HL,BountyMessage                        ; $A90A: 21 87 A8  raise the " CR" message
L_A90D:
    SET 7,(HL)                                 ; $A90D: CB FE
    RET                                        ; $A90F: C9

; KNOWN DATA: VERIFIED DATA: initial 102-byte JAMESON template; copied to ActiveCommanderRecord for a new game and reused as a mutable tape-workflow copy.
    INCLUDE "data/default-commander.asm"


; ============================================================================
; New commander, charts and the system generator
; Short-range and galactic charts, nearest-system selection, name search and the
; per-system data derived from the three 16-bit seeds.
; ============================================================================

; VERIFIED: Start a commander from CommanderTemplateBuffer (called by StartNewGame): clear the
; pending messages, copy the 102 template bytes (CopyCommanderTemplate), put the chart cursor on
; the current system and select it, recompute the prices only (L_AF01 patched to
; NOP keeps the saved stock), copy the selected name to CurrentSystemName, copy
; template +$5D (9 bytes) to SunPosition and clear HyperspaceCountdown.
InitialiseCommander:
    CALL ClearPendingFlightMessages            ; $A976: CD 63 D5  clear all pending messages
    CALL CopyCommanderTemplate                 ; $A979: CD 2D 7C  copy the 102-byte template to ActiveCommanderRecord
    LD A,(CurrentSystemX)                      ; $A97C: 3A 5B A8  chart cursor on the current system
    LD (ChartCursorX),A                        ; $A97F: 32 7D A8
    LD A,(CurrentSystemY)                      ; $A982: 3A 59 A8
    LD (ChartCursorY),A                        ; $A985: 32 7E A8
    CALL SelectNearestSystem                   ; $A988: CD C7 AC  select the system under the cursor (the current system)
    LD HL,L_AF01                               ; $A98B: 21 01 AF
    LD (HL),$00                                ; $A98E: 36 00  patch L_AF01 to NOP: ComputeMarket keeps the saved stock
    PUSH HL                                    ; $A990: E5
    CALL ComputeMarket                         ; $A991: CD 9C AE  prices for the saved market
    POP HL                                     ; $A994: E1
    LD (HL),$77                                ; $A995: 36 77  restore LD (HL),A at L_AF01
    LD HL,SelectedSystemName                   ; $A997: 21 40 AC  selected name -> current name (8 characters)
    LD DE,CurrentSystemName                    ; $A99A: 11 37 AC
    LD BC,$0008                                ; $A99D: 01 08 00
    LDIR                                       ; $A9A0: ED B0
    LD HL,L_A96D                               ; $A9A2: 21 6D A9  template +$5D, 9 bytes -> SunPosition
    LD DE,SunPosition                          ; $A9A5: 11 65 70
    LD BC,$0009                                ; $A9A8: 01 09 00
    LDIR                                       ; $A9AB: ED B0
    XOR A                                      ; $A9AD: AF
    LD (HyperspaceCountdown),A                 ; $A9AE: 32 73 D5  no hyperspace countdown
    RET                                        ; $A9B1: C9

; VERIFIED: 24 row-used flags for the short-range chart names, cleared by DrawShortRangeChart
; and set to $FF by PrintNameInFreeRow.  The initial bytes are stale code.
ShortRangeChartRows:
    defb $C9,$CD,$8C,$A9,$32,$D3,$A9,$11                                                  ; $A9B2 ....2...
    defb $A0,$91,$3A,$37,$AB,$E6,$18,$83                                                  ; $A9BA ..:7....
    defb $5F,$30,$01,$14,$06,$08,$C5,$3A                                                  ; $A9C2 _0.....:

; VERIFIED: Short-range chart (screen function 4): clear the row flags and screen, print token
; SHORT RANGE CHART, patch the window X-19..X+19 / Y-34..Y+34 around the current
; system, draw the centre cross (DrawXorCrosshair), the markers and names of all systems in the
; window (ForEachChartSystem), the fuel circle (DrawScreenCircle) and the cursor (DrawChartCursor).
; Evidence: runtime local-chart scenario.
DrawShortRangeChart:
    XOR A                                      ; $A9CA: AF
    LD B,$18                                   ; $A9CB: 06 18  24 text rows
    LD HL,ShortRangeChartRows                  ; $A9CD: 21 B2 A9
L_A9D0:
    LD (HL),A                                  ; $A9D0: 77
    INC HL                                     ; $A9D1: 23
    DJNZ L_A9D0                                ; $A9D2: 10 FC
    CALL ClearScreenAndFrame                   ; $A9D4: CD 9E BC
    LD A,$BE                                   ; $A9D7: 3E BE  token SHORT RANGE CHART
    CALL PrintBannerTitle                      ; $A9D9: CD 3E B7
    CALL ColourPromptRow                       ; $A9DC: CD C6 BB  colour the prompt row 21
    LD A,(CurrentSystemX)                      ; $A9DF: 3A 5B A8
    SUB $13                                    ; $A9E2: D6 13  window: X-19, 0 on underflow
    CALL C,ClampToZero                         ; $A9E4: DC 0A AC
    LD (L_AA51),A                              ; $A9E7: 32 51 AA  patch window X minimum at L_AA51
    LD A,(CurrentSystemX)                      ; $A9EA: 3A 5B A8
    ADD A,$13                                  ; $A9ED: C6 13  X+19, $FF on overflow
    CALL C,ClampToFF                           ; $A9EF: DC 0C AC
    LD (L_AA55),A                              ; $A9F2: 32 55 AA  patch window X limit at L_AA55
    LD A,(CurrentSystemY)                      ; $A9F5: 3A 59 A8
    SUB $22                                    ; $A9F8: D6 22  Y-34
    CALL C,ClampToZero                         ; $A9FA: DC 0A AC
    LD (L_AA5C),A                              ; $A9FD: 32 5C AA  patch window Y minimum at L_AA5C
    LD A,(CurrentSystemY)                      ; $AA00: 3A 59 A8
    ADD A,$22                                  ; $AA03: C6 22  Y+34
    CALL C,ClampToFF                           ; $AA05: DC 0C AC
    LD (L_AA60),A                              ; $AA08: 32 60 AA  patch window Y limit at L_AA60
    LD A,$18                                   ; $AA0B: 3E 18
    LD ($00C0),A                               ; $AA0D: 32 C0 00  store to ROM address $00C0: no effect on a 48K Spectrum
    LD A,$A7                                   ; $AA10: 3E A7  cross-hair vertical clip row $A7
    LD (CrosshairBottomLimit),A                ; $AA12: 32 85 D8
    LD A,$18                                   ; $AA15: 3E 18  centre mark arm length 24
    LD (CrosshairSize),A                       ; $AA17: 32 83 D8
    LD A,$61                                   ; $AA1A: 3E 61  chart centre: pixel x $61, y $60
    LD (ShapeCentreX),A                        ; $AA1C: 32 13 A8
    LD A,$60                                   ; $AA1F: 3E 60
    LD (ShapeCentreY),A                        ; $AA21: 32 14 A8
    CALL DrawXorCrosshair                      ; $AA24: CD 86 D8  centre mark on the current system
    LD HL,DrawShortRangeSystemMarker           ; $AA27: 21 96 AA  pass 1: system markers
    CALL ForEachChartSystem                    ; $AA2A: CD 44 AA
    LD HL,PrintShortRangeSystemName            ; $AA2D: 21 E7 AA  pass 2: system names
    CALL ForEachChartSystem                    ; $AA30: CD 44 AA
    LD A,(FuelLevel)                           ; $AA33: 3A 44 A8  radius in pixels = fuel in tenths (4 pixels per X unit)
    LD (ShapeSize),A                           ; $AA36: 32 15 A8
    CALL DrawScreenCircle                      ; $AA39: CD 61 84
    LD A,$10                                   ; $AA3C: 3E 10  cursor arm length 16
    LD (CrosshairSize),A                       ; $AA3E: 32 83 D8
    JP DrawChartCursor                         ; $AA41: C3 C0 B1  draw the chart cursor

; VERIFIED: Walk the 256 systems of the galaxy: call routine HL (patched into L_AA64) for each
; system whose X/Y lie in the patched window; otherwise advance with
; NextGeneratorSystem.  The called routine must advance the seeds itself.
ForEachChartSystem:
    LD (L_AA64),HL                             ; $AA44: 22 64 AA  patch the CALL operand at L_AA64 with HL
    CALL LoadGalaxySeedsToGenerator            ; $AA47: CD 79 AE  generator at system 0
    LD B,$00                                   ; $AA4A: 06 00  256 systems
L_AA4C:
    PUSH BC                                    ; $AA4C: C5
    LD A,(GeneratorSystemX)                    ; $AA4D: 3A 18 AC
L_AA50:
defc L_AA51 = L_AA50 + 1 ; byte inside instruction at $AA50
    CP $00                                     ; $AA50: FE 00  SMC: X >= window minimum (patched by DrawShortRangeChart)
    JR C,L_AA68                                ; $AA52: 38 14
L_AA54:
defc L_AA55 = L_AA54 + 1 ; byte inside instruction at $AA54
    CP $00                                     ; $AA54: FE 00  SMC: X < window limit (patched by DrawShortRangeChart)
    JR NC,L_AA68                               ; $AA56: 30 10
    LD A,(GeneratorSystemY)                    ; $AA58: 3A 16 AC
L_AA5B:
defc L_AA5C = L_AA5B + 1 ; byte inside instruction at $AA5B
    CP $00                                     ; $AA5B: FE 00  SMC: Y >= window minimum (patched by DrawShortRangeChart)
    JR C,L_AA68                                ; $AA5D: 38 09
L_AA5F:
defc L_AA60 = L_AA5F + 1 ; byte inside instruction at $AA5F
    CP $00                                     ; $AA5F: FE 00  SMC: Y < window limit (patched by DrawShortRangeChart)
    JR NC,L_AA68                               ; $AA61: 30 05
L_AA63:
defc L_AA64 = L_AA63 + 1 ; byte inside instruction at $AA63
    CALL L_AA63                                ; $AA63: CD 63 AA  SMC: target patched by ForEachChartSystem; it advances the seeds
    JR L_AA6B                                  ; $AA66: 18 03
L_AA68:
    CALL NextGeneratorSystem                   ; $AA68: CD 17 AD  outside the window: next system
L_AA6B:
    POP BC                                     ; $AA6B: C1
    DJNZ L_AA4C                                ; $AA6C: 10 DE
    RET                                        ; $AA6E: C9

; VERIFIED: Screen position of the generator's system on the short-range chart:
; C = 4*(X - CurrentSystemX) + $5E, B = $52 - 2*(Y - CurrentSystemY) (ROM y),
; then ROM PIXEL-ADD.  Output: HL screen byte, A pixel 0..7, BC kept.
GetShortRangeChartPixel:
    LD C,$61                                   ; $AA6F: 0E 61  centre column $61
    LD A,(CurrentSystemX)                      ; $AA71: 3A 5B A8
    LD B,A                                     ; $AA74: 47
    LD A,(GeneratorSystemX)                    ; $AA75: 3A 18 AC
    SUB B                                      ; $AA78: 90
    ADD A,A                                    ; $AA79: 87
    ADD A,A                                    ; $AA7A: 87
    ADD A,C                                    ; $AA7B: 81  C = 4*(X-current X) + $61 - 3
    SUB $03                                    ; $AA7C: D6 03
    LD C,A                                     ; $AA7E: 4F
    LD D,$60                                   ; $AA7F: 16 60  centre row $60 (top-down)
    LD A,(CurrentSystemY)                      ; $AA81: 3A 59 A8
    LD B,A                                     ; $AA84: 47
    LD A,(GeneratorSystemY)                    ; $AA85: 3A 16 AC
    SUB B                                      ; $AA88: 90
    ADD A,A                                    ; $AA89: 87
    NEG                                        ; $AA8A: ED 44
    ADD A,D                                    ; $AA8C: 82
    SUB $0E                                    ; $AA8D: D6 0E
    LD B,A                                     ; $AA8F: 47  B = $60 - 2*(Y-current Y) - $0E (ROM y is bottom-up)
    PUSH BC                                    ; $AA90: C5
    CALL $22AA                                 ; $AA91: CD AA 22  ROM PIXEL-ADD: HL = screen byte, A = pixel within the byte
    POP BC                                     ; $AA94: C1
    RET                                        ; $AA95: C9

; VERIFIED: XOR an 8-row marker (one of four 8-byte shapes at ChartDiscGlyphs, chosen by bits 3..4 of
; GeneratorSeed2High) at the system position, then NextGeneratorSystem.
DrawShortRangeSystemMarker:
    CALL GetShortRangeChartPixel               ; $AA96: CD 6F AA
    LD (L_AAB6),A                              ; $AA99: 32 B6 AA  patch the shift count at L_AAB6
    LD DE,ChartDiscGlyphs                      ; $AA9C: 11 D2 91  four 8-row marker shapes; s2 high bits 3..4 select one
    LD A,(GeneratorSeed2High)                  ; $AA9F: 3A 1A AC
    AND $18                                    ; $AAA2: E6 18  shape offset 0, 8, 16 or 24
    ADD A,E                                    ; $AAA4: 83
    LD E,A                                     ; $AAA5: 5F
    JR NC,L_AAA9                               ; $AAA6: 30 01
    INC D                                      ; $AAA8: 14
L_AAA9:
    LD B,$08                                   ; $AAA9: 06 08  8 pixel rows
L_AAAB:
    PUSH BC                                    ; $AAAB: C5
    LD A,(L_AAB6)                              ; $AAAC: 3A B6 AA
    AND A                                      ; $AAAF: A7
    LD A,(DE)                                  ; $AAB0: 1A
    LD C,$00                                   ; $AAB1: 0E 00
    JR Z,L_AABD                                ; $AAB3: 28 08  pixel 0: no shift
L_AAB5:
defc L_AAB6 = L_AAB5 + 1 ; byte inside instruction at $AAB5
    LD B,$01                                   ; $AAB5: 06 01  SMC: B = pixel offset 1..7 (patched by DrawShortRangeSystemMarker)
L_AAB7:
    SRL A                                      ; $AAB7: CB 3F  shift the row right, spilling into C
    RR C                                       ; $AAB9: CB 19
    DJNZ L_AAB7                                ; $AABB: 10 FA
L_AABD:
    LD B,A                                     ; $AABD: 47
    LD A,(HL)                                  ; $AABE: 7E
    XOR B                                      ; $AABF: A8  XOR into the screen byte
    LD (HL),A                                  ; $AAC0: 77
    INC HL                                     ; $AAC1: 23
    LD A,(HL)                                  ; $AAC2: 7E
    XOR C                                      ; $AAC3: A9  and the spill into the next byte
    LD (HL),A                                  ; $AAC4: 77
    DEC HL                                     ; $AAC5: 2B
    LD A,H                                     ; $AAC6: 7C  next pixel line of the screen
    INC A                                      ; $AAC7: 3C
    AND $07                                    ; $AAC8: E6 07
    JR NZ,L_AADC                               ; $AACA: 20 10
    LD A,H                                     ; $AACC: 7C
    AND $F8                                    ; $AACD: E6 F8
    LD H,A                                     ; $AACF: 67
    LD A,$20                                   ; $AAD0: 3E 20  next character row: L + 32
    ADD A,L                                    ; $AAD2: 85
    LD L,A                                     ; $AAD3: 6F
    JR NC,L_AADD                               ; $AAD4: 30 07
    LD A,$08                                   ; $AAD6: 3E 08  next third: H + 8
    ADD A,H                                    ; $AAD8: 84
    LD H,A                                     ; $AAD9: 67
    JR L_AADD                                  ; $AADA: 18 01
L_AADC:
    INC H                                      ; $AADC: 24
L_AADD:
    INC DE                                     ; $AADD: 13
    POP BC                                     ; $AADE: C1
    DJNZ L_AAAB                                ; $AADF: 10 CA
    JP NextGeneratorSystem                     ; $AAE1: C3 17 AD  next system

; VERIFIED: Two bytes without any code or runtime reference.
L_AAE4:
    defb $00,$00                                                                          ; $AAE4 ..

; VERIFIED: Name length stored by PrintShortRangeSystemName; never read.
L_AAE6:
    defb $00                                                                              ; $AAE6 .

; VERIFIED: Print the generator system's name near its marker: GenerateSystemName (advances
; the seeds), column x/8+1, row 22-y/8, else the row above (if >= 3), else below.
PrintShortRangeSystemName:
    CALL GetShortRangeChartPixel               ; $AAE7: CD 6F AA
    PUSH BC                                    ; $AAEA: C5  keep the marker position
    CALL GenerateSystemName                    ; $AAEB: CD 6F AD  build the name; advances the seeds
    LD BC,$0009                                ; $AAEE: 01 09 00
    LD HL,GeneratedSystemName                  ; $AAF1: 21 2E AC
    XOR A                                      ; $AAF4: AF
    CPIR                                       ; $AAF5: ED B1  find the terminator: C = 8 - length
    LD A,C                                     ; $AAF7: 79
    XOR $07                                    ; $AAF8: EE 07  length = (C XOR 7) + 1 for 4..8 letters
    INC A                                      ; $AAFA: 3C
    LD (L_AAE6),A                              ; $AAFB: 32 E6 AA  written but never read
    POP BC                                     ; $AAFE: C1
    LD A,C                                     ; $AAFF: 79  x pixel / 8
    RRA                                        ; $AB00: 1F
    RRA                                        ; $AB01: 1F
    RRA                                        ; $AB02: 1F
    AND $1F                                    ; $AB03: E6 1F
    INC A                                      ; $AB05: 3C
    LD (TextColumn),A                          ; $AB06: 32 0D A8  text column = x/8 + 1
    LD A,B                                     ; $AB09: 78  ROM y / 8, rounded
    SRL A                                      ; $AB0A: CB 3F
    SRL A                                      ; $AB0C: CB 3F
    SRL A                                      ; $AB0E: CB 3F
    JR NC,L_AB13                               ; $AB10: 30 01
    INC A                                      ; $AB12: 3C
L_AB13:
    NEG                                        ; $AB13: ED 44
    ADD A,$16                                  ; $AB15: C6 16  text row = 22 - rounded y/8
    LD (TextRow),A                             ; $AB17: 32 0E A8
    CALL PrintNameInFreeRow                    ; $AB1A: CD 34 AB  row free?
    RET C                                      ; $AB1D: D8
    LD HL,TextRow                              ; $AB1E: 21 0E A8
    DEC (HL)                                   ; $AB21: 35
    LD A,(HL)                                  ; $AB22: 7E
    CP $03                                     ; $AB23: FE 03  row above, unless it reaches the title rows
    JR C,L_AB2B                                ; $AB25: 38 04
    CALL PrintNameInFreeRow                    ; $AB27: CD 34 AB
    RET C                                      ; $AB2A: D8
L_AB2B:
    LD HL,TextRow                              ; $AB2B: 21 0E A8
    INC (HL)                                   ; $AB2E: 34
    INC (HL)                                   ; $AB2F: 34
    LD A,(HL)                                  ; $AB30: 7E
    CP $17                                     ; $AB31: FE 17  row below
    RET NC                                     ; $AB33: D0

; VERIFIED: If ShortRangeChartRows[TextRow] is zero, mark it and print GeneratedSystemName
; with a capital first letter; returns carry set.  Occupied: carry clear.
PrintNameInFreeRow:
    LD A,(TextRow)                             ; $AB34: 3A 0E A8
    LD HL,ShortRangeChartRows                  ; $AB37: 21 B2 A9  row flag of TextRow
    CALL AddAToHL                              ; $AB3A: CD 19 B7
    LD A,(HL)                                  ; $AB3D: 7E
    AND A                                      ; $AB3E: A7
    RET NZ                                     ; $AB3F: C0
    LD A,$FF                                   ; $AB40: 3E FF  mark the row as used
    LD (HL),A                                  ; $AB42: 77
    LD A,$01                                   ; $AB43: 3E 01  capital first letter
    LD (CapitaliseNextFlag),A                  ; $AB45: 32 92 A8
    LD HL,GeneratedSystemName                  ; $AB48: 21 2E AC
    JP PrintTokenString                        ; $AB4B: C3 62 B0

; VERIFIED: Galactic chart (screen function 3): clear, cross at the current system (x, 24+y/2),
; fuel circle (radius FuelLevel/4), clear character rows 0..2 and 19..23 with
; ClearScreenLinesWithStack (trimming the cross and the circle to the chart area),
; frame, cursor, token GALACTIC CHART, colours, a line at pixel row 152, then plot all
; 256 systems (PlotGalacticChartSystem).  Evidence: runtime galactic-chart scenario.
DrawGalacticChart:
    CALL ClearScreenAndFrame                   ; $AB4E: CD 9E BC
    LD A,$18                                   ; $AB51: 3E 18
    LD ($00C0),A                               ; $AB53: 32 C0 00  store to ROM address $00C0: no effect on a 48K Spectrum
    LD A,$98                                   ; $AB56: 3E 98  cross-hair vertical clip row $98
    LD (CrosshairBottomLimit),A                ; $AB58: 32 85 D8
    LD A,$10                                   ; $AB5B: 3E 10  centre mark arm length 16
    LD (CrosshairSize),A                       ; $AB5D: 32 83 D8
    LD A,(CurrentSystemX)                      ; $AB60: 3A 5B A8  cross at the current system (y halved, 24 pixels down)
    LD (ShapeCentreX),A                        ; $AB63: 32 13 A8
    LD A,(CurrentSystemY)                      ; $AB66: 3A 59 A8
    SRL A                                      ; $AB69: CB 3F
    ADD A,$18                                  ; $AB6B: C6 18
    LD (ShapeCentreY),A                        ; $AB6D: 32 14 A8
    CALL DrawXorCrosshair                      ; $AB70: CD 86 D8
    LD A,(FuelLevel)                           ; $AB73: 3A 44 A8  fuel range / 4 for DrawScreenCircle
    SRL A                                      ; $AB76: CB 3F
    SRL A                                      ; $AB78: CB 3F
    LD (ShapeSize),A                           ; $AB7A: 32 15 A8
    CALL DrawScreenCircle                      ; $AB7D: CD 61 84  fuel range circle
    LD HL,$4060                                ; $AB80: 21 60 40  trim the drawings: clear character rows 0..2
    LD A,$03                                   ; $AB83: 3E 03
    CALL ClearScreenLinesWithStack             ; $AB85: CD C0 AB
    LD HL,$5100                                ; $AB88: 21 00 51  and character rows 19..23 below the chart
    LD A,$05                                   ; $AB8B: 3E 05
    CALL ClearScreenLinesWithStack             ; $AB8D: CD C0 AB
    CALL DrawScreenFrame                       ; $AB90: CD C7 BC  redraw the screen frame
    LD A,$0A                                   ; $AB93: 3E 0A  cursor arm length 10 (DrawChartCursor: galactic mapping)
    LD (CrosshairSize),A                       ; $AB95: 32 83 D8
    CALL DrawChartCursor                       ; $AB98: CD C0 B1
    LD A,$C7                                   ; $AB9B: 3E C7  token GALACTIC CHART
    CALL PrintBannerTitle                      ; $AB9D: CD 3E B7
    LD A,$17                                   ; $ABA0: 3E 17  colour 160 attribute cells from $5A60
    LD HL,$5A60                                ; $ABA2: 21 60 5A
    LD B,$A0                                   ; $ABA5: 06 A0
    CALL FillBytes                             ; $ABA7: CD DA BB
    LD HL,$5060                                ; $ABAA: 21 60 50  line under the chart: pixel row 152
    CALL DrawFullWidthLine                     ; $ABAD: CD D6 BB
    CALL LoadGalaxySeedsToGenerator            ; $ABB0: CD 79 AE  generator at system 0
    LD B,$00                                   ; $ABB3: 06 00  256 systems
L_ABB5:
    PUSH BC                                    ; $ABB5: C5
    CALL PlotGalacticChartSystem               ; $ABB6: CD E6 AB
    CALL NextGeneratorSystem                   ; $ABB9: CD 17 AD
    POP BC                                     ; $ABBC: C1
    DJNZ L_ABB5                                ; $ABBD: 10 F6
    RET                                        ; $ABBF: C9

; VERIFIED: Clear the A*32 bytes below HL (HL-A*32..HL-1), then the same range in the next seven
; pixel lines (H+1..H+7), by pushing zero words with SP.  Interrupts are disabled
; meanwhile; SP is saved in StackClearSavedSP.  Clobbers A, B, C, D, E, H.
ClearScreenLinesWithStack:
    DI                                         ; $ABC0: F3
    LD (StackClearSavedSP),SP                  ; $ABC1: ED 73 E4 AB  save SP
    LD (StackClearBlockCount),A                ; $ABC5: 32 E3 AB
    LD C,$08                                   ; $ABC8: 0E 08  8 pixel lines
    LD DE,$0000                                ; $ABCA: 11 00 00
L_ABCD:
    LD SP,HL                                   ; $ABCD: F9  SP = end of the area in this pixel line
    LD A,(StackClearBlockCount)                ; $ABCE: 3A E3 AB
L_ABD1:
    LD B,$10                                   ; $ABD1: 06 10  16 pushes = 32 bytes per block
L_ABD3:
    PUSH DE                                    ; $ABD3: D5
    DJNZ L_ABD3                                ; $ABD4: 10 FD
    DEC A                                      ; $ABD6: 3D
    JR NZ,L_ABD1                               ; $ABD7: 20 F8
    INC H                                      ; $ABD9: 24  next pixel line
    DEC C                                      ; $ABDA: 0D
    JR NZ,L_ABCD                               ; $ABDB: 20 F0
    LD SP,(StackClearSavedSP)                  ; $ABDD: ED 7B E4 AB
    EI                                         ; $ABE1: FB
    RET                                        ; $ABE2: C9

; VERIFIED: Block count A of ClearScreenLinesWithStack.
StackClearBlockCount:
    defb $00                                                                              ; $ABE3 .

; VERIFIED: Stack pointer saved by ClearScreenLinesWithStack.
StackClearSavedSP:
    defw $0000                                                                            ; $ABE4

; VERIFIED: XOR one pixel at (GeneratorSystemX, 24 + GeneratorSystemY/2) using ROM PIXEL-ADD
; and a patched SET n,B instruction.
PlotGalacticChartSystem:
    LD A,(GeneratorSystemY)                    ; $ABE6: 3A 16 AC
    SRL A                                      ; $ABE9: CB 3F  Y / 2
    XOR $7F                                    ; $ABEB: EE 7F  B = ROM y (bottom-up) of 24 + Y/2
    ADD A,$18                                  ; $ABED: C6 18
    LD B,A                                     ; $ABEF: 47
    LD A,(GeneratorSystemX)                    ; $ABF0: 3A 18 AC  C = x pixel = system X
    LD C,A                                     ; $ABF3: 4F
    CALL $22AA                                 ; $ABF4: CD AA 22  ROM PIXEL-ADD
    XOR $07                                    ; $ABF7: EE 07  bit number n = 7 - pixel
    ADD A,A                                    ; $ABF9: 87
    ADD A,A                                    ; $ABFA: 87
    ADD A,A                                    ; $ABFB: 87
    OR $C0                                     ; $ABFC: F6 C0  opcode byte of SET n,B with n = 7 - pixel
    LD DE,L_AC05                               ; $ABFE: 11 05 AC
    LD (DE),A                                  ; $AC01: 12  patch L_AC05
    LD B,$00                                   ; $AC02: 06 00
L_AC04:
defc L_AC05 = L_AC04 + 1 ; byte inside instruction at $AC04
    SET 1,B                                    ; $AC04: CB C8  SMC: SET n,B (opcode byte patched just above)
    LD A,(HL)                                  ; $AC06: 7E
    XOR B                                      ; $AC07: A8  XOR the pixel
    LD (HL),A                                  ; $AC08: 77
    RET                                        ; $AC09: C9

; VERIFIED: Return A = 0 (window bound below zero).
ClampToZero:
    XOR A                                      ; $AC0A: AF
    RET                                        ; $AC0B: C9

; VERIFIED: Return A = $FF (window bound above 255).
ClampToFF:
    LD A,$FF                                   ; $AC0C: 3E FF
    RET                                        ; $AC0E: C9

; VERIFIED: Seeds s0, s1, s2 of the selected (hyperspace target) system, set by
; DeriveSelectedSystemData and copied to CurrentSystemSeeds on arrival (ArriveInTargetSystem).
SelectedSystemSeeds:
    defw $0000                                                                            ; $AC0F

; VERIFIED: Selected system s1 (word).
SelectedSystemSeed1:
    defw $0000                                                                            ; $AC11

; VERIFIED: Selected system s2 (word); PrintSpecies reads it for the species text.
SelectedSystemSeed2:
    defw $0000                                                                            ; $AC13

; VERIFIED: Working seeds s0, s1, s2 of the system generator; TwistGeneratorSeeds advances
; them, four twists per system.
GeneratorSeeds:
    defb $00                                                                              ; $AC15 .

; VERIFIED: Generator s0 high byte: the system Y.
GeneratorSystemY:
    defb $00                                                                              ; $AC16 .

; VERIFIED: Generator s1 (word).
GeneratorSeed1:
    defb $00                                                                              ; $AC17 .

; VERIFIED: Generator s1 high byte: the system X.
GeneratorSystemX:
    defb $00                                                                              ; $AC18 .

; VERIFIED: Generator s2 (word); its high byte selects name letter pairs.
GeneratorSeed2:
    defb $00                                                                              ; $AC19 .

; VERIFIED: Generator s2 high byte.
GeneratorSeed2High:
    defb $00                                                                              ; $AC1A .

; VERIFIED: Copy of GeneratorSeeds (SaveGeneratorSeeds / RestoreGeneratorSeeds).
SavedGeneratorSeeds:
    defw $0000,$0000,$0000                                                                ; $AC1B

; VERIFIED: First word of the planet-description generator (NextDescriptionRandom).
DescriptionSeed1:
    defw $0000                                                                            ; $AC21

; VERIFIED: Second word of the planet-description generator.
DescriptionSeed2:
    defw $0000                                                                            ; $AC23

; VERIFIED: Typed name, zero-terminated: the system name searched by FindSystemByName
; (function 15, PromptFindSystem) and the tape-load name check in LoadCommanderRecord.
NameInputBuffer:
    defm "JAMESON"
    defb $09,$00                                                                          ; $AC25

; VERIFIED: Name built by GenerateSystemName (8 characters + zero).
GeneratedSystemName:
    defm "TEMPNAME"
    defb $00                                                                              ; $AC2E

; VERIFIED: Name of the current system; cleared by the witchspace path EnterHyperspaceMisjump.
CurrentSystemName:
    defm "LAVE"
    defb $00,$00,$00,$00,$00                                                              ; $AC37

; VERIFIED: Name of the selected system (CopyGeneratedNameToSelected).
SelectedSystemName:
    defm "LAVE"
    defb $00,$00,$00,$00,$00                                                              ; $AC40

; VERIFIED: Distance from the current system to the cursor in tenths of a light year,
; printed by PrintSelectedSystemDistance; compared with FuelLevel by NormalHyperspaceJump.
SelectedSystemDistance:
    defw $0000                                                                            ; $AC49

; VERIFIED: Economy 0..7 of the selected system (data screen: RICH/AVERAGE/POOR/MAINLY +
; INDUSTRIAL/AGRICULTURAL); also the market economy term.
SelectedSystemEconomy:
    defb $00                                                                              ; $AC4B .

; VERIFIED: Government 0..7 (data screen token $B1+value: ANARCHY .. CORPORATE STATE).
SelectedSystemGovernment:
    defb $00                                                                              ; $AC4C .

; VERIFIED: Tech level (data screen prints value + 1 after TECH.LEVEL).
SelectedSystemTechLevel:
    defb $00                                                                              ; $AC4D .

; VERIFIED: Population in tenths of a billion (data screen).
SelectedSystemPopulation:
    defb $00                                                                              ; $AC4E .

; VERIFIED: Gross productivity word in M CR (data screen).
SelectedSystemProductivity:
    defw $0000                                                                            ; $AC4F

; VERIFIED: Two bytes without any code or runtime reference.
L_AC51:
    defb $00,$00                                                                          ; $AC51 ..

; VERIFIED: System counter of FindSystemByName (256 tries).
NameSearchCounter:
    defb $00                                                                              ; $AC53 .

; VERIFIED: Output pointer of GenerateSystemName.
NameWritePointer:
    defw $0000                                                                            ; $AC54

; VERIFIED: Dormant code: CurrentGalaxy = (CurrentGalaxy + 1) AND 7, then rotate each byte of the
; three GalaxySeeds words left (L_AC6D per word): the same galaxy step as
; GalacticHyperspaceJump, without its other effects.  No word in the image points here
; and it never runs in the recorded scenarios.  INFERRED: a superseded copy.
; stationslotfix=yes replaces these 33 bytes (with L_AC6D) with StationSlotRoof.
L_AC56:
assert $-GameImage = StationSlotRoofStart-GameLoadAddress
IF STATION_SLOT_FIX
    StationSlotRoofCode
ELSE
    LD HL,CurrentGalaxy                        ; $AC56: 21 27 A8
    LD A,(HL)                                  ; $AC59: 7E
    INC A                                      ; $AC5A: 3C
    AND $07                                    ; $AC5B: E6 07
    LD (HL),A                                  ; $AC5D: 77
    LD HL,GalaxySeeds                          ; $AC5E: 21 52 A8
    CALL L_AC6D                                ; $AC61: CD 6D AC
    LD HL,GalaxySeeds+2                        ; $AC64: 21 54 A8
    CALL L_AC6D                                ; $AC67: CD 6D AC
    LD HL,GalaxySeeds+4                        ; $AC6A: 21 56 A8

; VERIFIED: Dormant: RLC both bytes of the word at HL (HL ends on the high byte).  Used only by
; the dormant L_AC56.
L_AC6D:
    LD E,(HL)                                  ; $AC6D: 5E
    RLC E                                      ; $AC6E: CB 03
    LD (HL),E                                  ; $AC70: 73
    INC HL                                     ; $AC71: 23
    LD D,(HL)                                  ; $AC72: 56
    RLC D                                      ; $AC73: CB 02
    LD (HL),D                                  ; $AC75: 72
    RET                                        ; $AC76: C9
ENDIF
assert $-GameImage = StationSlotRoofLimit-GameLoadAddress

; VERIFIED: Search the galaxy for the system named in NameInputBuffer.  Found: select it
; (seeds, data, cursor redrawn, SelectedSystemName, distance) and return carry
; clear.  Not found after 256 systems: carry set.
; Evidence: tools/check_routines.py economy/find-system-and-distance (LAVE found at X 20,
; Y 173; an unknown name returns carry).
FindSystemByName:
    CALL LoadGalaxySeedsToGenerator            ; $AC77: CD 79 AE
    XOR A                                      ; $AC7A: AF
    LD (NameSearchCounter),A                   ; $AC7B: 32 53 AC
L_AC7E:
    CALL SaveGeneratorSeeds                    ; $AC7E: CD 81 AE  remember this system's seeds
    CALL GenerateSystemName                    ; $AC81: CD 6F AD  its name; advances the seeds
    LD HL,NameInputBuffer                      ; $AC84: 21 25 AC
    LD DE,GeneratedSystemName                  ; $AC87: 11 2E AC
L_AC8A:
    LD B,(HL)                                  ; $AC8A: 46
    LD A,(DE)                                  ; $AC8B: 1A
    CP B                                       ; $AC8C: B8  compare with the typed name
    JR NZ,L_AC96                               ; $AC8D: 20 07
    AND A                                      ; $AC8F: A7
    JR Z,L_AC9F                                ; $AC90: 28 0D  both ended together: match
    INC HL                                     ; $AC92: 23
    INC DE                                     ; $AC93: 13
    JR L_AC8A                                  ; $AC94: 18 F4
L_AC96:
    LD HL,NameSearchCounter                    ; $AC96: 21 53 AC
    INC (HL)                                   ; $AC99: 34
    JP NZ,L_AC7E                               ; $AC9A: C2 7E AC  try all 256 systems
    SCF                                        ; $AC9D: 37  carry: not found
    RET                                        ; $AC9E: C9
L_AC9F:
    CALL RestoreGeneratorSeeds                 ; $AC9F: CD 89 AE  back to the matching system
    CALL DrawChartCursor                       ; $ACA2: CD C0 B1  erase cursor, select, redraw cursor
    CALL DeriveSelectedSystemData              ; $ACA5: CD DF AD
    CALL DrawChartCursor                       ; $ACA8: CD C0 B1
    CALL CopyGeneratedNameToSelected           ; $ACAB: CD D3 AD
    JP UpdateSelectedSystemDistance            ; $ACAE: C3 08 AD

; VERIFIED: Smallest squared cursor distance found by SelectNearestSystem.
NearestSystemDistance:
    defw $0000                                                                            ; $ACB1

; VERIFIED: SelectNearestSystem, erasing and redrawing the cursor (DrawChartCursor) when
; CurrentScreenId is 7 or 8 (the galactic and the short-range chart: screen keys I and O
; reach screen functions 3 and 4).  Callers: DisplaySystemData, L_D5A6, L_D62B,
; function 14.
SnapCursorToNearestSystem:
    LD A,(CurrentScreenId)                     ; $ACB3: 3A 41 70
    CP $07                                     ; $ACB6: FE 07  screens 7 and 8 (the two charts) show the cursor
    JR C,SelectNearestSystem                   ; $ACB8: 38 0D
    CP $09                                     ; $ACBA: FE 09
    JR NC,SelectNearestSystem                  ; $ACBC: 30 09
    CALL DrawChartCursor                       ; $ACBE: CD C0 B1
    CALL SelectNearestSystem                   ; $ACC1: CD C7 AC
    JP DrawChartCursor                         ; $ACC4: C3 C0 B1

; VERIFIED: Select the system nearest to ChartCursorX/Y (dx^2 + (dy/2)^2; ties go to the later
; system): its seeds become SelectedSystemSeeds, its data is derived, the cursor
; moves onto it, its name goes to SelectedSystemName, then the distance from the
; current system is computed (falls into UpdateSelectedSystemDistance).
SelectNearestSystem:
    CALL LoadGalaxySeedsToGenerator            ; $ACC7: CD 79 AE
    LD HL,$FFFF                                ; $ACCA: 21 FF FF  best squared distance so far
    LD (NearestSystemDistance),HL              ; $ACCD: 22 B1 AC
    LD B,$00                                   ; $ACD0: 06 00  256 systems
L_ACD2:
    PUSH BC                                    ; $ACD2: C5
    LD A,(GeneratorSystemX)                    ; $ACD3: 3A 18 AC
    LD B,A                                     ; $ACD6: 47
    LD A,(GeneratorSystemY)                    ; $ACD7: 3A 16 AC
    CALL ChartDistanceSquared                  ; $ACDA: CD 21 AD
    JR C,L_ACEF                                ; $ACDD: 38 10  overflow: too far to compete
    EX DE,HL                                   ; $ACDF: EB
    LD HL,(NearestSystemDistance)              ; $ACE0: 2A B1 AC
    AND A                                      ; $ACE3: A7
    SBC HL,DE                                  ; $ACE4: ED 52  keep the nearest (ties: the later system)
    JR C,L_ACEF                                ; $ACE6: 38 07
    LD (NearestSystemDistance),DE              ; $ACE8: ED 53 B1 AC
    CALL SaveGeneratorSeeds                    ; $ACEC: CD 81 AE  remember its seeds
L_ACEF:
    CALL NextGeneratorSystem                   ; $ACEF: CD 17 AD
    POP BC                                     ; $ACF2: C1
    DJNZ L_ACD2                                ; $ACF3: 10 DD
    LD HL,(NearestSystemDistance)              ; $ACF5: 2A B1 AC
    AND A                                      ; $ACF8: A7
    CALL StoreSystemDistance                   ; $ACF9: CD 45 AD  overwritten by UpdateSelectedSystemDistance below
    CALL RestoreGeneratorSeeds                 ; $ACFC: CD 89 AE  seeds of the nearest system
    CALL DeriveSelectedSystemData              ; $ACFF: CD DF AD
    CALL GenerateSystemName                    ; $AD02: CD 6F AD  its name
    CALL CopyGeneratedNameToSelected           ; $AD05: CD D3 AD

; VERIFIED: SelectedSystemDistance = 4 * isqrt(dx^2 + (dy/2)^2) between the current system
; and the cursor.  Returns carry clear.
; Evidence: tools/check_routines.py economy/find-system-and-distance (Lave to TIBEDIED
; = 176).
UpdateSelectedSystemDistance:
    LD A,(CurrentSystemX)                      ; $AD08: 3A 5B A8
    LD B,A                                     ; $AD0B: 47
    LD A,(CurrentSystemY)                      ; $AD0C: 3A 59 A8
    CALL ChartDistanceSquared                  ; $AD0F: CD 21 AD  from the current system to the cursor
    CALL StoreSystemDistance                   ; $AD12: CD 45 AD
    AND A                                      ; $AD15: A7
    RET                                        ; $AD16: C9

; VERIFIED: Advance GeneratorSeeds to the next system (four twists).
NextGeneratorSystem:
    LD B,$04                                   ; $AD17: 06 04  four twists per system
L_AD19:
    PUSH BC                                    ; $AD19: C5
    CALL TwistGeneratorSeeds                   ; $AD1A: CD B6 AD
    POP BC                                     ; $AD1D: C1
    DJNZ L_AD19                                ; $AD1E: 10 F9
    RET                                        ; $AD20: C9

; VERIFIED: HL = (ChartCursorX - B)^2 + ((ChartCursorY - A)/2)^2 with absolute differences.
; Carry set on 16-bit overflow.
ChartDistanceSquared:
    PUSH AF                                    ; $AD21: F5
    LD A,(ChartCursorX)                        ; $AD22: 3A 7D A8
    CALL AbsoluteDifference                    ; $AD25: CD 3D AD  |cursor X - B|
    LD D,A                                     ; $AD28: 57
    CALL MultiplyAByD                          ; $AD29: CD 5C AD  dx^2
    POP BC                                     ; $AD2C: C1
    PUSH HL                                    ; $AD2D: E5
    LD A,(ChartCursorY)                        ; $AD2E: 3A 7E A8
    CALL AbsoluteDifference                    ; $AD31: CD 3D AD  |cursor Y - A|
    SRL A                                      ; $AD34: CB 3F  half the Y difference
    LD D,A                                     ; $AD36: 57
    CALL MultiplyAByD                          ; $AD37: CD 5C AD  (dy/2)^2
    POP DE                                     ; $AD3A: D1
    ADD HL,DE                                  ; $AD3B: 19  sum; carry on overflow
    RET                                        ; $AD3C: C9

; VERIFIED: A = |A - B| (B is changed when A < B).
AbsoluteDifference:
    CP B                                       ; $AD3D: B8
    JR NC,L_AD43                               ; $AD3E: 30 03
    LD C,B                                     ; $AD40: 48
    LD B,A                                     ; $AD41: 47
    LD A,C                                     ; $AD42: 79
L_AD43:
    SUB B                                      ; $AD43: 90
    RET                                        ; $AD44: C9

; VERIFIED: SelectedSystemDistance from the squared distance in HL (carry: overflow, use $FFFF):
; 0 stays 0, otherwise 4 * (integer part of sqrt(HL)) from SquareRootHL (256*sqrt in HL).
StoreSystemDistance:
    JR C,L_AD49                                ; $AD45: 38 02
    JR L_AD4C                                  ; $AD47: 18 03
L_AD49:
    LD HL,$FFFF                                ; $AD49: 21 FF FF  overflow: use $FFFF
L_AD4C:
    LD A,H                                     ; $AD4C: 7C
    OR L                                       ; $AD4D: B5
    JR Z,L_AD58                                ; $AD4E: 28 08  zero distance stays 0
    CALL SquareRootHL                          ; $AD50: CD 53 DC  H = integer part of sqrt(HL) (SquareRootHL gives 256*sqrt)
    LD L,H                                     ; $AD53: 6C
    LD H,$00                                   ; $AD54: 26 00
    ADD HL,HL                                  ; $AD56: 29  distance * 4 = tenths of a light year
    ADD HL,HL                                  ; $AD57: 29
L_AD58:
    LD (SelectedSystemDistance),HL             ; $AD58: 22 49 AC
    RET                                        ; $AD5B: C9

; VERIFIED: HL = A * D (8 x 8 bits, shift and add).  Clobbers A, B (0), D, E.
MultiplyAByD:
    LD E,$00                                   ; $AD5C: 1E 00
    LD B,$08                                   ; $AD5E: 06 08
    LD HL,$0000                                ; $AD60: 21 00 00
L_AD63:
    SRL D                                      ; $AD63: CB 3A
    RR E                                       ; $AD65: CB 1B
    RL A                                       ; $AD67: CB 17  next multiplier bit, most significant first
    JR NC,L_AD6C                               ; $AD69: 30 01
    ADD HL,DE                                  ; $AD6B: 19
L_AD6C:
    DJNZ L_AD63                                ; $AD6C: 10 F5
    RET                                        ; $AD6E: C9

; VERIFIED: Build the generator system's name in GeneratedSystemName: three letter pairs, or
; four when bit 6 of s0 low is set, taken from the pair table TokenPairTable by s2 high AND
; $1F (0 adds nothing; a '?' second letter is dropped).  Leaves the seeds advanced
; to the next system.  Evidence: tools/check_routines.py economy/galaxy-system-names
; (systems 0 and 7 are TIBEDIED and LAVE).
GenerateSystemName:
    LD HL,GeneratedSystemName                  ; $AD6F: 21 2E AC
    LD (NameWritePointer),HL                   ; $AD72: 22 54 AC
    LD B,$08                                   ; $AD75: 06 08  clear the 8 name bytes
L_AD77:
    LD (HL),$00                                ; $AD77: 36 00
    INC HL                                     ; $AD79: 23
    DJNZ L_AD77                                ; $AD7A: 10 FB
    LD HL,(GeneratorSeeds)                     ; $AD7C: 2A 15 AC
    LD A,L                                     ; $AD7F: 7D
    AND $40                                    ; $AD80: E6 40  bit 6 of s0 low: four letter pairs, else three
    AND A                                      ; $AD82: A7
    PUSH AF                                    ; $AD83: F5
    CALL AppendNameLetterPair                  ; $AD84: CD 90 AD
    CALL AppendNameLetterPair                  ; $AD87: CD 90 AD
    CALL AppendNameLetterPair                  ; $AD8A: CD 90 AD
    POP AF                                     ; $AD8D: F1
    JR Z,TwistGeneratorSeeds                   ; $AD8E: 28 26  three pairs: only the fourth twist

; VERIFIED: Append the pair selected by s2 high AND $1F (if nonzero), then twist the seeds.
AppendNameLetterPair:
    LD HL,(GeneratorSeed2)                     ; $AD90: 2A 19 AC
    LD A,H                                     ; $AD93: 7C
    AND $1F                                    ; $AD94: E6 1F  pair index from s2 high; 0 adds nothing
    AND A                                      ; $AD96: A7
    JR Z,TwistGeneratorSeeds                   ; $AD97: 28 1D
    LD HL,TokenPairTable                       ; $AD99: 21 C3 FB  two letters per index
    ADD A,A                                    ; $AD9C: 87
    LD D,$00                                   ; $AD9D: 16 00
    LD E,A                                     ; $AD9F: 5F
    ADD HL,DE                                  ; $ADA0: 19
    LD A,(HL)                                  ; $ADA1: 7E
    INC HL                                     ; $ADA2: 23
    PUSH HL                                    ; $ADA3: E5
    LD HL,(NameWritePointer)                   ; $ADA4: 2A 54 AC  store the first letter
    LD (HL),A                                  ; $ADA7: 77
    INC HL                                     ; $ADA8: 23
    EX DE,HL                                   ; $ADA9: EB
    POP HL                                     ; $ADAA: E1
    LD A,(HL)                                  ; $ADAB: 7E
    EX DE,HL                                   ; $ADAC: EB
    CP $3F                                     ; $ADAD: FE 3F  a "?" second letter is not stored
    JR Z,L_ADB3                                ; $ADAF: 28 02
    LD (HL),A                                  ; $ADB1: 77
    INC HL                                     ; $ADB2: 23
L_ADB3:
    LD (NameWritePointer),HL                   ; $ADB3: 22 54 AC  advance the write pointer

; VERIFIED: s0, s1, s2 = s1, s2, s0 + s1 + s2 (16-bit words, carry discarded).
TwistGeneratorSeeds:
    LD HL,(GeneratorSeeds)                     ; $ADB6: 2A 15 AC
    LD DE,(GeneratorSeed1)                     ; $ADB9: ED 5B 17 AC
    ADD HL,DE                                  ; $ADBD: 19  s0 + s1
    EX DE,HL                                   ; $ADBE: EB
    LD HL,(GeneratorSeed1)                     ; $ADBF: 2A 17 AC
    LD (GeneratorSeeds),HL                     ; $ADC2: 22 15 AC
    LD HL,(GeneratorSeed2)                     ; $ADC5: 2A 19 AC
    LD (GeneratorSeed1),HL                     ; $ADC8: 22 17 AC
    LD HL,(GeneratorSeed1)                     ; $ADCB: 2A 17 AC
    ADD HL,DE                                  ; $ADCE: 19  s2 = s0 + s1 + s2; s0 = s1; s1 = s2
    LD (GeneratorSeed2),HL                     ; $ADCF: 22 19 AC
    RET                                        ; $ADD2: C9

; VERIFIED: Copy 8 bytes from GeneratedSystemName to SelectedSystemName.
CopyGeneratedNameToSelected:
    LD BC,$0008                                ; $ADD3: 01 08 00
    LD HL,GeneratedSystemName                  ; $ADD6: 21 2E AC
    LD DE,SelectedSystemName                   ; $ADD9: 11 40 AC
    LDIR                                       ; $ADDC: ED B0
    RET                                        ; $ADDE: C9

; VERIFIED: From GeneratorSeeds: SelectedSystemSeeds, ChartCursorY = s0 high, ChartCursorX =
; s1 high, economy, government, tech level, population and productivity.
; Evidence: data-screen tokens; tools/check_routines.py economy/find-system-and-distance
; gives Lave 5, 3, 4, 25, 7000.
DeriveSelectedSystemData:
    LD HL,(GeneratorSeeds)                     ; $ADDF: 2A 15 AC
    LD (SelectedSystemSeeds),HL                ; $ADE2: 22 0F AC  selected seeds s0
    LD A,H                                     ; $ADE5: 7C
    LD (ChartCursorY),A                        ; $ADE6: 32 7E A8  cursor Y = s0 high
    AND $07                                    ; $ADE9: E6 07  economy = s0 high AND 7
    LD (SelectedSystemEconomy),A               ; $ADEB: 32 4B AC
    LD HL,(GeneratorSeed1)                     ; $ADEE: 2A 17 AC
    LD (SelectedSystemSeed1),HL                ; $ADF1: 22 11 AC  selected seeds s1
    LD A,H                                     ; $ADF4: 7C
    LD (ChartCursorX),A                        ; $ADF5: 32 7D A8  cursor X = s1 high
    LD A,L                                     ; $ADF8: 7D
    SRL A                                      ; $ADF9: CB 3F
    SRL A                                      ; $ADFB: CB 3F
    SRL A                                      ; $ADFD: CB 3F
    AND $07                                    ; $ADFF: E6 07  government = (s1 low >> 3) AND 7
    LD (SelectedSystemGovernment),A            ; $AE01: 32 4C AC
    SRL A                                      ; $AE04: CB 3F  government 0 or 1?
    JR NZ,L_AE10                               ; $AE06: 20 08
    LD A,(SelectedSystemEconomy)               ; $AE08: 3A 4B AC
    OR $02                                     ; $AE0B: F6 02  governments 0..1 force economy bit 1
    LD (SelectedSystemEconomy),A               ; $AE0D: 32 4B AC
L_AE10:
    LD A,(SelectedSystemEconomy)               ; $AE10: 3A 4B AC
    XOR $07                                    ; $AE13: EE 07  eco XOR 7, carry clear
    AND A                                      ; $AE15: A7
    LD B,A                                     ; $AE16: 47
    LD A,H                                     ; $AE17: 7C
    AND $03                                    ; $AE18: E6 03  + (s1 high AND 3)
    ADD A,B                                    ; $AE1A: 80
    LD B,A                                     ; $AE1B: 47
    LD A,(SelectedSystemGovernment)            ; $AE1C: 3A 4C AC
    SRL A                                      ; $AE1F: CB 3F
    ADC A,B                                    ; $AE21: 88  + gov/2 rounded up (carry = gov bit 0)
    LD (SelectedSystemTechLevel),A             ; $AE22: 32 4D AC  tech = (eco XOR 7) + (s1 high AND 3) + ceil(gov/2)
    ADD A,A                                    ; $AE25: 87
    ADD A,A                                    ; $AE26: 87
    LD B,A                                     ; $AE27: 47
    LD A,(SelectedSystemGovernment)            ; $AE28: 3A 4C AC
    LD C,A                                     ; $AE2B: 4F
    LD A,(SelectedSystemEconomy)               ; $AE2C: 3A 4B AC
    ADC A,B                                    ; $AE2F: 88  4*tech + eco
    ADC A,C                                    ; $AE30: 89
    ADC A,$01                                  ; $AE31: CE 01
    LD (SelectedSystemPopulation),A            ; $AE33: 32 4E AC  population = 4*tech + eco + gov + 1
    LD A,(SelectedSystemEconomy)               ; $AE36: 3A 4B AC
    XOR $07                                    ; $AE39: EE 07
    ADC A,$03                                  ; $AE3B: CE 03  (eco XOR 7) + 3
    LD D,A                                     ; $AE3D: 57
    LD A,(SelectedSystemGovernment)            ; $AE3E: 3A 4C AC
    ADC A,$04                                  ; $AE41: CE 04  gov + 4
    CALL MultiplyAByD                          ; $AE43: CD 5C AD  HL = (gov+4) * ((eco XOR 7)+3)
    LD A,(SelectedSystemPopulation)            ; $AE46: 3A 4E AC
    LD D,L                                     ; $AE49: 55
    CALL MultiplyAByD                          ; $AE4A: CD 5C AD  * population
    ADD HL,HL                                  ; $AE4D: 29
    ADD HL,HL                                  ; $AE4E: 29
    ADD HL,HL                                  ; $AE4F: 29
    LD (SelectedSystemProductivity),HL         ; $AE50: 22 4F AC  productivity = ((eco XOR 7)+3)*(gov+4)*population*8
    LD HL,(GeneratorSeed2)                     ; $AE53: 2A 19 AC
    LD (SelectedSystemSeed2),HL                ; $AE56: 22 13 AC  selected seeds s2
    RET                                        ; $AE59: C9

; VERIFIED: If SelectedSystemDistance is nonzero print DISTANCE: n.n LIGHT YEARS; then
; NewLine.
PrintSelectedSystemDistance:
    LD HL,(SelectedSystemDistance)             ; $AE5A: 2A 49 AC
    LD A,H                                     ; $AE5D: 7C
    OR L                                       ; $AE5E: B5
    JR Z,L_AE76                                ; $AE5F: 28 15  zero: only the new line
    LD A,$BF                                   ; $AE61: 3E BF  token DISTANCE
    CALL PrintTokenColon                       ; $AE63: CD E8 AF
    LD A,$04                                   ; $AE66: 3E 04  4-character field
    LD (NumberFieldWidth),A                    ; $AE68: 32 8E A8
    LD HL,(SelectedSystemDistance)             ; $AE6B: 2A 49 AC
    SCF                                        ; $AE6E: 37  carry: print n.n
    CALL PrintDecimalHL                        ; $AE6F: CD 60 B7
    CALL PrintInlineToken                      ; $AE72: CD 99 BA
    defb $C3                                   ; $AE75: C3  PrintInlineToken argument: " LIGHT YEARS"
L_AE76:
    JP NewLine                                 ; $AE76: C3 FA AF

; VERIFIED: Copy GalaxySeeds to GeneratorSeeds (system 0).
LoadGalaxySeedsToGenerator:
    LD HL,GalaxySeeds                          ; $AE79: 21 52 A8
    LD DE,GeneratorSeeds                       ; $AE7C: 11 15 AC
    JR L_AE8F                                  ; $AE7F: 18 0E

; VERIFIED: Copy GeneratorSeeds to SavedGeneratorSeeds.
SaveGeneratorSeeds:
    LD HL,GeneratorSeeds                       ; $AE81: 21 15 AC
    LD DE,SavedGeneratorSeeds                  ; $AE84: 11 1B AC
    JR L_AE8F                                  ; $AE87: 18 06

; VERIFIED: Copy SavedGeneratorSeeds to GeneratorSeeds.
RestoreGeneratorSeeds:
    LD HL,SavedGeneratorSeeds                  ; $AE89: 21 1B AC
    LD DE,GeneratorSeeds                       ; $AE8C: 11 15 AC
L_AE8F:
    LD BC,$0006                                ; $AE8F: 01 06 00
    LDIR                                       ; $AE92: ED B0
    RET                                        ; $AE94: C9

; VERIFIED: Economy factor * SelectedSystemEconomy for the current commodity (ComputeMarket).
MarketEconomyTerm:
    defb $00                                                                              ; $AE95 .

; ============================================================================
; Market prices and trading-screen lines
; Price/stock generation from the commodity table and the line printers.
; ============================================================================

; VERIFIED: MarketFluctuation = low byte of AuxRandomSeed (the dust generator state), then
; ComputeMarket.  Called on arrival by ArriveInTargetSystem, so the market changes once
; per jump.
RandomiseMarket:
    LD A,(AuxRandomSeed)                       ; $AE96: 3A 63 70  low byte of the dust generator state
    LD (MarketFluctuation),A                   ; $AE99: 32 2C A8  fluctuation for this arrival

; VERIFIED: For the 17 four-byte commodity records at CommodityTable (base price, byte 1 = bit 7
; sign + bits 0..4 economy factor, base quantity, mask), with term = factor *
; SelectedSystemEconomy and f = MarketFluctuation AND mask (all 8-bit):
;   stock = base quantity + f - (term + 1) if bit 7 is clear, + term if set; 0 when the
;           result has bit 7 set, then AND $3F -> MarketStock;
;   price = base price + f + term if bit 7 is clear, - (term + 1) if set; 4 * price
;           (tenths of a credit) -> MarketPrices.
; Alien items (MarketStock+16) are then set to 0.  L_AF01 can be patched to NOP to keep
; the stock (InitialiseCommander).
; Evidence: tools/check_routines.py economy/market and economy/p5-market-model (model of
; all 17 records for every economy and 64 fluctuations).
ComputeMarket:
    LD HL,MarketStock                          ; $AE9C: 21 60 A8  stock destination (kept in the alternate HL)
    LD DE,MarketPrices                         ; $AE9F: 11 0E AF  price destination (alternate DE)
    EXX                                        ; $AEA2: D9
    LD HL,CommodityTable                       ; $AEA3: 21 F2 91  17 commodity records of 4 bytes at CommodityTable
    LD B,$11                                   ; $AEA6: 06 11
L_AEA8:
    PUSH BC                                    ; $AEA8: C5
    LD E,(HL)                                  ; $AEA9: 5E  E = base price
    INC HL                                     ; $AEAA: 23
    LD A,(HL)                                  ; $AEAB: 7E
    LD D,A                                     ; $AEAC: 57
    AND $1F                                    ; $AEAD: E6 1F  economy factor (bits 0..4 of byte 1)
    JR Z,L_AEBA                                ; $AEAF: 28 09
    LD B,A                                     ; $AEB1: 47
    LD A,(SelectedSystemEconomy)               ; $AEB2: 3A 4B AC  economy 0..7 of the selected system
    LD C,A                                     ; $AEB5: 4F
    XOR A                                      ; $AEB6: AF
L_AEB7:
    ADD A,C                                    ; $AEB7: 81  factor * economy
    DJNZ L_AEB7                                ; $AEB8: 10 FD
L_AEBA:
    LD (MarketEconomyTerm),A                   ; $AEBA: 32 95 AE
    INC HL                                     ; $AEBD: 23
    LD B,(HL)                                  ; $AEBE: 46  B = base quantity
    INC HL                                     ; $AEBF: 23
    LD C,(HL)                                  ; $AEC0: 4E  C = fluctuation mask
    INC HL                                     ; $AEC1: 23
    LD A,(MarketFluctuation)                   ; $AEC2: 3A 2C A8  (fluctuation AND mask) + base quantity
    AND C                                      ; $AEC5: A1
    ADD A,B                                    ; $AEC6: 80
    LD B,A                                     ; $AEC7: 47
    LD A,(MarketEconomyTerm)                   ; $AEC8: 3A 95 AE
    BIT 7,D                                    ; $AECB: CB 7A  bit 7 of byte 1 clear: subtract the economy term
    JR NZ,L_AED2                               ; $AECD: 20 03
    INC A                                      ; $AECF: 3C  subtract term + 1 (INC before NEG)
    NEG                                        ; $AED0: ED 44
L_AED2:
    ADD A,B                                    ; $AED2: 80
    BIT 7,A                                    ; $AED3: CB 7F
    JR Z,L_AED8                                ; $AED5: 28 01
    XOR A                                      ; $AED7: AF  negative: stock 0
L_AED8:
    AND $3F                                    ; $AED8: E6 3F  stock quantity 0..63
    PUSH AF                                    ; $AEDA: F5
    LD A,(MarketFluctuation)                   ; $AEDB: 3A 2C A8  (fluctuation AND mask) + base price
    AND C                                      ; $AEDE: A1
    ADD A,E                                    ; $AEDF: 83
    LD B,A                                     ; $AEE0: 47
    LD A,(MarketEconomyTerm)                   ; $AEE1: 3A 95 AE
    BIT 7,D                                    ; $AEE4: CB 7A  bit 7 set: subtract the economy term
    JR Z,L_AEEB                                ; $AEE6: 28 03
    INC A                                      ; $AEE8: 3C  subtract term + 1 (INC before NEG)
    NEG                                        ; $AEE9: ED 44
L_AEEB:
    ADD A,B                                    ; $AEEB: 80
    LD C,A                                     ; $AEEC: 4F
    LD B,$00                                   ; $AEED: 06 00
    SLA C                                      ; $AEEF: CB 21  price * 4 = tenths of a credit
    RL B                                       ; $AEF1: CB 10
    SLA C                                      ; $AEF3: CB 21
    RL B                                       ; $AEF5: CB 10
    PUSH BC                                    ; $AEF7: C5
    EXX                                        ; $AEF8: D9
    POP BC                                     ; $AEF9: C1
    LD A,C                                     ; $AEFA: 79
    LD (DE),A                                  ; $AEFB: 12  store the price word
    INC DE                                     ; $AEFC: 13
    LD A,B                                     ; $AEFD: 78
    LD (DE),A                                  ; $AEFE: 12
    INC DE                                     ; $AEFF: 13
    POP AF                                     ; $AF00: F1
L_AF01:
    LD (HL),A                                  ; $AF01: 77  SMC: NOP while InitialiseCommander recomputes prices only
    INC HL                                     ; $AF02: 23
    EXX                                        ; $AF03: D9
    POP BC                                     ; $AF04: C1
    DJNZ L_AEA8                                ; $AF05: 10 A1
    LD HL,MarketStock+16                       ; $AF07: 21 70 A8  alien items are never stocked
    LD (HL),B                                  ; $AF0A: 70
    RET                                        ; $AF0B: C9

; VERIFIED: Two bytes without a direct access.  ResetCommodityPointers and ShowMarketPrices load this address as
; MarketPrices - 2 for the pre-incremented PricePointer.
L_AF0C:
    defb $00,$00                                                                          ; $AF0C ..

; VERIFIED: 17 price words in tenths of a credit (ComputeMarket); the initial bytes are stale.
MarketPrices:
    defw $3EBA                                                                            ; $AF0E  price 0: FOOD
    defw $C320                                                                            ; $AF10  price 1: TEXTILES
    defw $BA07                                                                            ; $AF12  price 2: RADIOACTIVES
    defw $07CD                                                                            ; $AF14  price 3: SLAVES
    defw $3EBA                                                                            ; $AF16  price 4: LIQUOR/WINES
    defw $3201                                                                            ; $AF18  price 5: LUXURIES
    defw $A7A7                                                                            ; $AF1A  price 6: NARCOTICS
    defw $25CD                                                                            ; $AF1C  price 7: COMPUTERS
    defw $3AAF                                                                            ; $AF1E  price 8: MACHINERY
    defw $A723                                                                            ; $AF20  price 9: ALLOYS
    defw $183C                                                                            ; $AF22  price 10: FIREARMS
    defw $AF11                                                                            ; $AF24  price 11: FURS
    defw $2232                                                                            ; $AF26  price 12: MINERALS
    defw $C9A7                                                                            ; $AF28  price 13: GOLD
    defw $7EE1                                                                            ; $AF2A  price 14: PLATINUM
    defw $E523                                                                            ; $AF2C  price 15: GEM-STONES
    defw $2232                                                                            ; $AF2E  price 16: ALIEN ITEMS

; VERIFIED: Commodity index of the printed line: token $D0 + value names it.
CurrentCommodity:
    defb $00                                                                              ; $AF30 .

; VERIFIED: Pre-incremented pointer into CargoHold for PrintCargoLine.
CargoPointer:
    defw $0000                                                                            ; $AF31

; VERIFIED: Pointer into MarketPrices, advanced by 2 before each use (PrintMarketLine).
PricePointer:
    defw $0000                                                                            ; $AF33

; VERIFIED: Pointer into MarketStock, advanced by 1 before each use.
StockPointer:
    defw $0000                                                                            ; $AF35

; VERIFIED: TextColumn/TextRow word saved by SaveTextCursor and restored by RestoreTextCursor.
SavedTextPosition:
    defw $0000                                                                            ; $AF37

; VERIFIED: If bit 7 of ControlOptions (sound) is set, sound ROM BEEPER with HL = $0080 (pitch),
; DE = $0060 (length).  Used after messages, prompts and errors.
BeepIfSoundOn:
    LD A,(ControlOptions)                      ; $AF39: 3A 14 FC
    BIT 7,A                                    ; $AF3C: CB 7F  sound on (ControlOptions bit 7)?
    RET Z                                      ; $AF3E: C8
    LD HL,$0080                                ; $AF3F: 21 80 00  ROM BEEPER pitch value
    LD DE,$0060                                ; $AF42: 11 60 00  ROM BEEPER length in cycles
    JP $03B5                                   ; $AF45: C3 B5 03  ROM BEEPER

; VERIFIED: Wait 20 frames (Wait20Frames), clear the input flags, then wait until LastKeyCode is not $FF.
; Output: A = LastKeyCode (AccessMenuKeyLoop compares it with the digits '1'..'3').
WaitForKeyPress:
    CALL Wait20Frames                          ; $AF48: CD AB B0
    CALL ClearInputFlags                       ; $AF4B: CD 56 AF
L_AF4E:
    LD A,(LastKeyCode)                         ; $AF4E: 3A 13 FC
    CP $FF                                     ; $AF51: FE FF  $FF: no key yet
    JR Z,L_AF4E                                ; $AF53: 28 F9
    RET                                        ; $AF55: C9

; VERIFIED: With interrupts disabled, clear the four bytes KeyFlagsScreens..KeyFlagsCombat.
ClearInputFlags:
    DI                                         ; $AF56: F3
    LD HL,KeyFlagsScreens                      ; $AF57: 21 0E FC  KeyFlagsScreens and the next three latch bytes
    LD B,$04                                   ; $AF5A: 06 04
L_AF5C:
    LD (HL),$00                                ; $AF5C: 36 00
    INC HL                                     ; $AF5E: 23
    DJNZ L_AF5C                                ; $AF5F: 10 FB
    EI                                         ; $AF61: FB
    RET                                        ; $AF62: C9

; VERIFIED: One market line for CurrentCommodity: name, unit (PrintCommodityUnit), price from
; PricePointer + 2 (n.n), stock from StockPointer + 1 with its unit, or '-' when
; zero (then carry set; otherwise carry clear).  Caller: L_D0AB.
PrintMarketLine:
    LD A,(CurrentCommodity)                    ; $AF63: 3A 30 AF
    ADD A,$D0                                  ; $AF66: C6 D0  commodity name token
    CALL PrintToken                            ; $AF68: CD 9D BA
    CALL SetTextColumnInline                   ; $AF6B: CD 0D B0
    defb $0D                                   ; $AF6E: 0D  SetTextColumnInline argument: text column 13
    CALL PrintCommodityUnit                    ; $AF6F: CD 6F B0
    CALL SetTextColumnInline                   ; $AF72: CD 0D B0
    defb $0F                                   ; $AF75: 0F  SetTextColumnInline argument: text column 15
    LD HL,(PricePointer)                       ; $AF76: 2A 33 AF  next price word
    INC HL                                     ; $AF79: 23
    INC HL                                     ; $AF7A: 23
    LD (PricePointer),HL                       ; $AF7B: 22 33 AF
    LD E,(HL)                                  ; $AF7E: 5E
    INC HL                                     ; $AF7F: 23
    LD D,(HL)                                  ; $AF80: 56
    EX DE,HL                                   ; $AF81: EB
    SCF                                        ; $AF82: 37  carry: one decimal place
    LD A,$04                                   ; $AF83: 3E 04  4-character price field
    LD (NumberFieldWidth),A                    ; $AF85: 32 8E A8
    CALL PrintDecimalHL                        ; $AF88: CD 60 B7
    CALL SetTextColumnInline                   ; $AF8B: CD 0D B0
    defb $17                                   ; $AF8E: 17  SetTextColumnInline argument: text column 23
    LD HL,(StockPointer)                       ; $AF8F: 2A 35 AF  next stock byte
    INC HL                                     ; $AF92: 23
    LD A,(HL)                                  ; $AF93: 7E
    LD (StockPointer),HL                       ; $AF94: 22 35 AF
    AND A                                      ; $AF97: A7
    JR NZ,L_AFA5                               ; $AF98: 20 0B  stock zero: print "-"
    CALL PrintInlineToken                      ; $AF9A: CD 99 BA
    defb $20                                   ; $AF9D: 20  PrintInlineToken argument: " "
    LD A,$2D                                   ; $AF9E: 3E 2D  token: "-"
    CALL PrintTokenNewLine                     ; $AFA0: CD F7 AF
    SCF                                        ; $AFA3: 37  carry: not available here
    RET                                        ; $AFA4: C9
L_AFA5:
    LD A,$02                                   ; $AFA5: 3E 02  2-character stock field
    LD (NumberFieldWidth),A                    ; $AFA7: 32 8E A8
    LD HL,(StockPointer)                       ; $AFAA: 2A 35 AF
    LD A,(HL)                                  ; $AFAD: 7E
    CALL PrintDecimalA                         ; $AFAE: CD 5C B7
    CALL PrintCommodityUnit                    ; $AFB1: CD 6F B0
    CALL NewLine                               ; $AFB4: CD FA AF
    AND A                                      ; $AFB7: A7  carry clear: line printed
    RET                                        ; $AFB8: C9

; VERIFIED: CargoPointer + 1: if that cargo quantity is zero return carry set; otherwise
; print the commodity name, the quantity at column 13 and its unit; carry clear.
PrintCargoLine:
    LD HL,(CargoPointer)                       ; $AFB9: 2A 31 AF
    INC HL                                     ; $AFBC: 23  pre-increment to this commodity
    LD (CargoPointer),HL                       ; $AFBD: 22 31 AF
    LD A,(HL)                                  ; $AFC0: 7E
    AND A                                      ; $AFC1: A7
    JR Z,L_AFE1                                ; $AFC2: 28 1D  none carried: carry set, nothing printed
    LD A,(CurrentCommodity)                    ; $AFC4: 3A 30 AF
    ADD A,$D0                                  ; $AFC7: C6 D0  commodity name token
    CALL PrintToken                            ; $AFC9: CD 9D BA
    CALL SetTextColumnInline                   ; $AFCC: CD 0D B0
    defb $0D                                   ; $AFCF: 0D  SetTextColumnInline argument: text column 13
    LD A,$03                                   ; $AFD0: 3E 03  3-character quantity field
    LD (NumberFieldWidth),A                    ; $AFD2: 32 8E A8
    LD HL,(CargoPointer)                       ; $AFD5: 2A 31 AF
    LD A,(HL)                                  ; $AFD8: 7E
    CALL PrintDecimalA                         ; $AFD9: CD 5C B7
    CALL PrintCommodityUnit                    ; $AFDC: CD 6F B0
    AND A                                      ; $AFDF: A7  carry clear: line printed
    RET                                        ; $AFE0: C9
L_AFE1:
    SCF                                        ; $AFE1: 37
    RET                                        ; $AFE2: C9

; VERIFIED: Print message A followed by ':'.
PrintMessageColon:
    CALL PrintMessage                          ; $AFE3: CD D7 BA
    JR L_AFEB                                  ; $AFE6: 18 03

; VERIFIED: Print token A followed by ':'.
PrintTokenColon:
    CALL PrintToken                            ; $AFE8: CD 9D BA
L_AFEB:
    LD A,$3A                                   ; $AFEB: 3E 3A  ':' after the text
    JR L_AFF4                                  ; $AFED: 18 05

; VERIFIED: Print token A followed by a space.
PrintTokenSpace:
    CALL PrintToken                            ; $AFEF: CD 9D BA
    LD A,$20                                   ; $AFF2: 3E 20  token: " "
L_AFF4:
    JP PrintToken                              ; $AFF4: C3 9D BA

; VERIFIED: Print token A, then fall into NewLine.
PrintTokenNewLine:
    CALL PrintToken                            ; $AFF7: CD 9D BA

; VERIFIED: Start a new text line: request a capital for the next letter (CapitaliseNextFlag=1),
; set column zero and advance the row.
NewLine:
    LD A,$01                                   ; $AFFA: 3E 01
    LD (CapitaliseNextFlag),A                  ; $AFFC: 32 92 A8  capitalise the next letter
    CALL ResetTextColumn                       ; $AFFF: CD 08 B0  column 0

; VERIFIED: Move to the next text row (TextRow+1, wrapping through SetTextRow).
NextTextRow:
    LD A,(TextRow)                             ; $B002: 3A 0E A8
    INC A                                      ; $B005: 3C
    JR SetTextRow                              ; $B006: 18 11  SetTextRow wraps rows 24+ back to row 1

; VERIFIED: Set TextColumn to zero.
ResetTextColumn:
    XOR A                                      ; $B008: AF
    LD (TextColumn),A                          ; $B009: 32 0D A8
    RET                                        ; $B00C: C9

; VERIFIED: Set TextColumn from the byte that follows the CALL (inline argument) and
; return after it.  Falls into SetTextColumn.
SetTextColumnInline:
    POP HL                                     ; $B00D: E1
    LD A,(HL)                                  ; $B00E: 7E
    INC HL                                     ; $B00F: 23
    PUSH HL                                    ; $B010: E5

; VERIFIED: Set TextColumn to A.  A column of 32 or more starts a new line instead.
SetTextColumn:
    LD (TextColumn),A                          ; $B011: 32 0D A8
    CP $20                                     ; $B014: FE 20  32 columns per text row
    RET C                                      ; $B016: D8
    JR NewLine                                 ; $B017: 18 E1  column 32 or more: start a new line instead

; VERIFIED: Set TextRow to A.  A row of 24 or more wraps to row 1 and resets the
; column (via ResetTextColumn).
SetTextRow:
    LD (TextRow),A                             ; $B019: 32 0E A8
    CP $18                                     ; $B01C: FE 18  24 text rows
    RET C                                      ; $B01E: D8
    LD A,$01                                   ; $B01F: 3E 01  past the bottom: wrap to row 1
    LD (TextRow),A                             ; $B021: 32 0E A8
    JR ResetTextColumn                         ; $B024: 18 E2  and column 0

; ============================================================================
; Docked-screen helpers: prompt lines, text input and chart cursor
; Prompt rows 21/22, string input, frame waits, commodity units and the
; chart cross-hair key handlers reached through the jump table at $A7F5.
; ============================================================================

; VERIFIED: Backspace on the prompt rows: if TextColumn is nonzero, decrement it and clear
; the 8 pixel bytes of that character cell on text row 21 (TextRow = 21) or
; otherwise row 22.  The cell address is patched into the LD HL at L_B03E.
; Input: TextRow, TextColumn.  Clobbers: A, B, HL.
; Evidence: callers InputString (delete key) and InputQuantity (L_B32B).
EraseInputCharacter:
    LD A,(TextRow)                             ; $B026: 3A 0E A8
    LD B,$A1                                   ; $B029: 06 A1  B = low byte of the row-21 cell base + 1 ($50A1)
    CP $15                                     ; $B02B: FE 15  prompt row 21?
    JR Z,L_B031                                ; $B02D: 28 02
    LD B,$C1                                   ; $B02F: 06 C1  row 22: $50C1
L_B031:
    LD A,(TextColumn)                          ; $B031: 3A 0D A8
    AND A                                      ; $B034: A7
    RET Z                                      ; $B035: C8  column 0: nothing to erase
    DEC A                                      ; $B036: 3D
    LD (TextColumn),A                          ; $B037: 32 0D A8  cursor back one cell
    ADD A,B                                    ; $B03A: 80  row base + 1 + new column = cell of the last character
    LD (L_B03F),A                              ; $B03B: 32 3F B0  patch the low byte of LD HL at L_B03E

; VERIFIED: Self-modified: the low byte of LD HL,$5000 is written at $B03B with
; $A1/$C1 + new column, giving the screen cell of the erased character.
L_B03E:
defc L_B03F = L_B03E + 1 ; byte inside instruction at $B03E
    LD HL,$5000                                ; $B03E: 21 00 50  self-modified low byte: erased character cell
    XOR A                                      ; $B041: AF
    LD B,$08                                   ; $B042: 06 08  8 pixel lines per character cell
L_B044:
    LD (HL),A                                  ; $B044: 77
    INC H                                      ; $B045: 24  next pixel line of the cell (+$100)
    DJNZ L_B044                                ; $B046: 10 FC
    RET                                        ; $B048: C9

; VERIFIED: Print token A between control codes 6 (capitals on) and 8 (title case):
; PrintToken(6), PrintToken(A), PrintToken(8).  Clobbers: A, BC, DE, HL.
; Evidence: instruction semantics; TokenControlTable entries 6 and 8.
PrintTokenInCapitals:
    PUSH AF                                    ; $B049: F5
    CALL PrintInlineToken                      ; $B04A: CD 99 BA
    defb $06                                   ; $B04D: 06  PrintInlineToken argument: "{caps}"
    POP AF                                     ; $B04E: F1
    CALL PrintToken                            ; $B04F: CD 9D BA
    LD A,$08                                   ; $B052: 3E 08  token: "{title-case}"
    JP PrintToken                              ; $B054: C3 9D BA

; VERIFIED: Print token A in capitals (PrintTokenInCapitals), call UpdateConditionIndicator, then print
; token $77 ({cr}{cr}{cr}).  Input: A = title token.
; Evidence: callers print "DATA ON", " CARGO" (after "SELL"), "INVENTORY" and
; "<system> MARKET PRICES" titles.
PrintScreenTitle:
    CALL PrintTokenInCapitals                  ; $B057: CD 49 B0
    CALL UpdateConditionIndicator              ; $B05A: CD BD A4  update the alert colour (row-1 tiles off the cockpit views)
    LD A,$77                                   ; $B05D: 3E 77  token: "{cr}{cr}{cr}"
    JP PrintToken                              ; $B05F: C3 9D BA

; VERIFIED: Print the zero-terminated string of PrintToken codes at HL.
; Returns with carry set, A = 0 and HL pointing at the terminating zero.
PrintTokenString:
    LD A,(HL)                                  ; $B062: 7E
    CP $00                                     ; $B063: FE 00  zero terminator?
    SCF                                        ; $B065: 37  end of string: carry set, A = 0
    RET Z                                      ; $B066: C8
    INC HL                                     ; $B067: 23
    PUSH HL                                    ; $B068: E5  PrintToken does not preserve HL
    CALL PrintToken                            ; $B069: CD 9D BA
    POP HL                                     ; $B06C: E1
    JR PrintTokenString                        ; $B06D: 18 F3

; VERIFIED: Print the unit of commodity CurrentCommodity in lower case (clears CapitaliseNextFlag first):
; 0..12 and 16 "t", 13..14 "kg", 15 "g", 17 or more "km" (used for the
; planet radius).  Evidence: simulator run of all indexes 0..17 (a simulator
; check in tools/check_routines.py).
PrintCommodityUnit:
    LD A,$00                                   ; $B06F: 3E 00
    LD (CapitaliseNextFlag),A                  ; $B071: 32 92 A8  no capital for the unit letters
    LD A,(CurrentCommodity)                    ; $B074: 3A 30 AF
    CP $0D                                     ; $B077: FE 0D  indexes 0..12: tonnes
    JR C,L_B087                                ; $B079: 38 0C
    CP $0F                                     ; $B07B: FE 0F  13, 14: kilograms
    JR C,L_B08B                                ; $B07D: 38 0C
    JR Z,L_B090                                ; $B07F: 28 0F  15: grams
    CP $11                                     ; $B081: FE 11  16 (alien items): tonnes; 17 or more: km
    JR C,L_B087                                ; $B083: 38 02
    JR L_B094                                  ; $B085: 18 0D
L_B087:
    LD A,$54                                   ; $B087: 3E 54  'T', printed as 't' (CapitaliseNextFlag cleared)
    JR L_B09A                                  ; $B089: 18 0F
L_B08B:
    LD A,$4B                                   ; $B08B: 3E 4B  'K' of "kg"
    CALL PrintToken                            ; $B08D: CD 9D BA
L_B090:
    LD A,$47                                   ; $B090: 3E 47  'G', printed as 'g'
    JR L_B09A                                  ; $B092: 18 06
L_B094:
    CALL PrintInlineToken                      ; $B094: CD 99 BA  index 17+: "km" (only the planet radius uses it)
    defb $4B                                   ; $B097: 4B  PrintInlineToken argument: "K"
    LD A,$4D                                   ; $B098: 3E 4D  token: "M"
L_B09A:
    JP PrintToken                              ; $B09A: C3 9D BA

; VERIFIED: Carry set when commodity CurrentCommodity is measured in tonnes (indexes 0..12 and 16),
; clear for 13..15 (kg/g).  Only tonne goods change the free cargo space
; CargoFreeSpace.  Evidence: simulator run of indexes 0..17; callers BuyCommodity/SellCommodity.
TestCommodityTonnes:
    LD A,(CurrentCommodity)                    ; $B09D: 3A 30 AF
    CP $0D                                     ; $B0A0: FE 0D  0..12: carry set (tonnes)
    RET C                                      ; $B0A2: D8
    CP $10                                     ; $B0A3: FE 10  16 is also measured in tonnes
    JR NZ,L_B0A9                               ; $B0A5: 20 02
    SCF                                        ; $B0A7: 37
    RET                                        ; $B0A8: C9
L_B0A9:
    AND A                                      ; $B0A9: A7  13..15 and 17+: carry clear
    RET                                        ; $B0AA: C9

; VERIFIED: Wait for 20 interrupts (HALT loop, about 0.4 s).  Clobbers: B.
Wait20Frames:
    LD B,$14                                   ; $B0AB: 06 14  20 frames
    JR WaitFrames                              ; $B0AD: 18 02

; VERIFIED: Wait for 36 interrupts (HALT loop, about 0.7 s).  Clobbers: B.
Wait36Frames:
    LD B,$24                                   ; $B0AF: 06 24  36 frames

; VERIFIED: Wait for B interrupts with HALT.  Clobbers: B.
WaitFrames:
    HALT                                       ; $B0B1: 76  wait for the next interrupt
    DJNZ WaitFrames                            ; $B0B2: 10 FD
    RET                                        ; $B0B4: C9

; VERIFIED: Copy the TextColumn/TextRow word to SavedTextPosition.  Clobbers: HL.
SaveTextCursor:
    LD HL,(TextColumn)                         ; $B0B5: 2A 0D A8  TextColumn and TextRow (adjacent bytes) as one word
    LD (SavedTextPosition),HL                  ; $B0B8: 22 37 AF
    RET                                        ; $B0BB: C9

; VERIFIED: Set TextRow 21 and column 0, then clear text rows 21 and 22, columns 1..30
; (pixel bytes only).  Clobbers: A, BC, HL.
; Evidence: simulator (480 bytes from $50A1 cleared); message control 21.
ClearPromptLines:
    LD A,$15                                   ; $B0BC: 3E 15  prompt row 21
    CALL SetTextRow                            ; $B0BE: CD 19 B0
    CALL ResetTextColumn                       ; $B0C1: CD 08 B0
    XOR A                                      ; $B0C4: AF  fill byte 0: blank pixels
    LD HL,$50A1                                ; $B0C5: 21 A1 50  screen: text row 21, column 1, pixel line 0
    CALL FillCharacterRow30                    ; $B0C8: CD CE B0

; VERIFIED: Fill text row 22, columns 1..30, all 8 pixel lines with A.  Falls into
; FillCharacterRow30.  Evidence: instruction semantics.
FillPromptRow22:
    LD HL,$50C1                                ; $B0CB: 21 C1 50  screen: text row 22, column 1, pixel line 0

; VERIFIED: Fill 30 bytes on each of the 8 pixel lines of the character row at HL
; (INC H per line) with A.  Clobbers: B, HL.
FillCharacterRow30:
    LD B,$08                                   ; $B0CE: 06 08  8 pixel lines
L_B0D0:
    PUSH BC                                    ; $B0D0: C5
    LD B,$1E                                   ; $B0D1: 06 1E  30 cells (columns 1..30)
    PUSH HL                                    ; $B0D3: E5
L_B0D4:
    LD (HL),A                                  ; $B0D4: 77
    INC HL                                     ; $B0D5: 23
    DJNZ L_B0D4                                ; $B0D6: 10 FC
    POP HL                                     ; $B0D8: E1
    INC H                                      ; $B0D9: 24  next pixel line of the row (+$100)
    POP BC                                     ; $B0DA: C1
    DJNZ L_B0D0                                ; $B0DB: 10 F3
    RET                                        ; $B0DD: C9

; VERIFIED: Restore TextColumn/TextRow from SavedTextPosition (see SaveTextCursor).  Clobbers: HL.
RestoreTextCursor:
    LD HL,(SavedTextPosition)                  ; $B0DE: 2A 37 AF
    LD (TextColumn),HL                         ; $B0E1: 22 0D A8  column and row restored together
    RET                                        ; $B0E4: C9

; VERIFIED: InputString: number of characters entered so far (0..limit).
InputLength:
    defb $00                                                                              ; $B0E5 .

; VERIFIED: InputString: address where the next character is stored.
InputWritePointer:
    defw $0000                                                                            ; $B0E6

; VERIFIED: InputString: last key code returned by WaitForKeyPress.
InputKey:
    defb $00                                                                              ; $B0E8 .

; VERIFIED: Chart key handler (JP from $A807): prompt with message 14 "PLANET NAME?",
; read up to 8 characters into NameInputBuffer with InputString, and search with
; FindSystemByName.  Empty input clears the prompt; carry from FindSystemByName prints the name
; and " NOT FOUND" and beeps; otherwise PrintSelectedSystemSummary.
; Evidence: decoded messages/tokens; jump-table entry next to the docked screens.
PromptFindSystem:
    LD A,$0E                                   ; $B0E9: 3E 0E  message 14: "{prompt}PLANET NAME? {nop}"
    LD B,$08                                   ; $B0EB: 06 08  at most 8 characters
    LD HL,NameInputBuffer                      ; $B0ED: 21 25 AC  typed name buffer
    CALL InputString                           ; $B0F0: CD 1D B1
    LD A,(InputLength)                         ; $B0F3: 3A E5 B0  anything typed?
    AND A                                      ; $B0F6: A7
    JP Z,ClearPromptLines                      ; $B0F7: CA BC B0  empty input: just clear the prompt rows
    CALL FindSystemByName                      ; $B0FA: CD 77 AC  carry: no system of this galaxy has that name
    JR NC,L_B113                               ; $B0FD: 30 14
    LD HL,NameInputBuffer                      ; $B0FF: 21 25 AC  echo the typed name
    CALL PrintTokenString                      ; $B102: CD 62 B0
    CALL PrintInlineToken                      ; $B105: CD 99 BA
    defb $08                                   ; $B108: 08  PrintInlineToken argument: "{title-case}"
    CALL PrintInlineToken                      ; $B109: CD 99 BA
    defb $E1                                   ; $B10C: E1  PrintInlineToken argument: " NOT FOUND"
    CALL BeepIfSoundOn                         ; $B10D: CD 39 AF  beep (only with sound enabled)
    JP ClearInputFlags                         ; $B110: C3 56 AF  clear the key state and return

; VERIFIED: PromptFindSystem, name found (FindSystemByName returned carry clear and has selected the
; system): back to title case, then PrintSelectedSystemSummary shows its name,
; the distance line and beeps.
L_B113:
    CALL PrintInlineToken                      ; $B113: CD 99 BA
    defb $08                                   ; $B116: 08  PrintInlineToken argument: "{title-case}"
    JP PrintSelectedSystemSummary              ; $B117: C3 AF B1  found: name, distance line and beep

; VERIFIED: InputString: message number printed as the prompt.
InputPromptMessage:
    defb $00                                                                              ; $B11A .

; VERIFIED: InputString: start address of the destination buffer.
InputBufferStart:
    defw $0000                                                                            ; $B11B

; VERIFIED: Read a string on the prompt rows.  Input: A = prompt message, B = maximum
; length (patched into InputLimitCompare), HL = buffer.  Accepts '0'..'9' and '@'..'Z';
; key $FE deletes (then pauses 8 frames), Enter ($0D) ends.  A character typed
; while the buffer already holds the maximum also ends the input, like Enter, and
; is not stored.  The buffer is zero-terminated; on exit InputLength holds the
; length.  Waits for Enter to be released, then clears the key state (ClearInputFlags).
; Evidence: instruction semantics; callers $B0E9, $D429; a simulator check in
; tools/check_routines.py (full buffer, rejected keys, delete).
InputString:
    LD (InputPromptMessage),A                  ; $B11D: 32 1A B1
    LD A,B                                     ; $B120: 78  maximum length
    LD (L_B164),A                              ; $B121: 32 64 B1  patch the maximum length into InputLimitCompare
    LD (InputBufferStart),HL                   ; $B124: 22 1B B1
    LD HL,(InputBufferStart)                   ; $B127: 2A 1B B1  write pointer starts at the buffer
    LD (InputWritePointer),HL                  ; $B12A: 22 E6 B0
    XOR A                                      ; $B12D: AF
    LD (InputLength),A                         ; $B12E: 32 E5 B0  no characters yet
    CALL ClearPromptLines                      ; $B131: CD BC B0  clear rows 21/22, cursor to row 21 column 0
    CALL PrintInlineToken                      ; $B134: CD 99 BA  prompt and echo in capitals
    defb $06                                   ; $B137: 06  PrintInlineToken argument: "{caps}"
    LD A,(InputPromptMessage)                  ; $B138: 3A 1A B1
    CALL PrintMessage                          ; $B13B: CD D7 BA  print the prompt message
L_B13E:
    CALL WaitForKeyPress                       ; $B13E: CD 48 AF  next key code
    LD (InputKey),A                            ; $B141: 32 E8 B0
    CP $0D                                     ; $B144: FE 0D  Enter ends the input
    JR Z,L_B197                                ; $B146: 28 4F
    CP $FE                                     ; $B148: FE FE  $FE = delete key
    JR Z,L_B179                                ; $B14A: 28 2D
    LD A,(InputKey)                            ; $B14C: 3A E8 B0
    CP $30                                     ; $B14F: FE 30  below '0': ignored
    JR C,L_B13E                                ; $B151: 38 EB
    CP $5B                                     ; $B153: FE 5B  beyond 'Z': ignored
    JR NC,L_B13E                               ; $B155: 30 E7
    CP $3A                                     ; $B157: FE 3A  '0'..'9': accepted
    JR C,L_B15F                                ; $B159: 38 04
    CP $40                                     ; $B15B: FE 40  ':'..'?' ignored; '@'..'Z' accepted
    JR C,L_B13E                                ; $B15D: 38 DF
L_B15F:
    LD D,A                                     ; $B15F: 57  keep the character
    LD A,(InputLength)                         ; $B160: 3A E5 B0

; VERIFIED: Self-modified CP n: the operand is the maximum input length, written at $B121
; by InputString from B on entry ($0A in the image).
InputLimitCompare:
defc L_B164 = InputLimitCompare + 1 ; byte inside instruction at $B163
    CP $0A                                     ; $B163: FE 0A  self-modified: maximum length (from B)
    JR NC,L_B197                               ; $B165: 30 30  buffer full: a further character ends the input like Enter
    INC A                                      ; $B167: 3C
    LD (InputLength),A                         ; $B168: 32 E5 B0
    LD A,D                                     ; $B16B: 7A
    LD HL,(InputWritePointer)                  ; $B16C: 2A E6 B0
    LD (HL),A                                  ; $B16F: 77  store the character
    INC HL                                     ; $B170: 23
    LD (InputWritePointer),HL                  ; $B171: 22 E6 B0
    CALL PrintToken                            ; $B174: CD 9D BA  echo it on the prompt row
    JR L_B13E                                  ; $B177: 18 C5
L_B179:
    LD A,(InputLength)                         ; $B179: 3A E5 B0
    AND A                                      ; $B17C: A7
    JR Z,L_B13E                                ; $B17D: 28 BF  delete with nothing typed: ignored
    DEC A                                      ; $B17F: 3D
    LD (InputLength),A                         ; $B180: 32 E5 B0
    LD HL,(InputWritePointer)                  ; $B183: 2A E6 B0
    DEC HL                                     ; $B186: 2B  step the write pointer back
    LD (InputWritePointer),HL                  ; $B187: 22 E6 B0
    CALL EraseInputCharacter                   ; $B18A: CD 26 B0  erase the last character cell
    LD B,$08                                   ; $B18D: 06 08  pause 8 frames before the next key
L_B18F:
    HALT                                       ; $B18F: 76
    DJNZ L_B18F                                ; $B190: 10 FD
    CALL ClearInputFlags                       ; $B192: CD 56 AF  clear the key state
    JR L_B13E                                  ; $B195: 18 A7
L_B197:
    LD HL,(InputWritePointer)                  ; $B197: 2A E6 B0
    LD (HL),$00                                ; $B19A: 36 00  zero-terminate the string
    CALL NewLine                               ; $B19C: CD FA AF
    CALL Wait20Frames                          ; $B19F: CD AB B0  pause 20 frames
L_B1A2:
    LD A,(LastKeyCode)                         ; $B1A2: 3A 13 FC  wait until Enter is released
    CP $0D                                     ; $B1A5: FE 0D
    JR Z,L_B1A2                                ; $B1A7: 28 F9
    JP ClearInputFlags                         ; $B1A9: C3 56 AF  clear the key state and return

; VERIFIED: Chart key handler (JP from $A804): select the system nearest to the chart
; cursor with SnapCursorToNearestSystem (the cursor moves onto it; on the chart screens 7 and 8 the
; cross-hair is erased and redrawn), then fall into PrintSelectedSystemSummary:
; its name in capitals on prompt row 21, the distance line and a beep.
; Evidence: executed in the chart-cursor trace; a simulator check in
; tools/check_routines.py (cursor (3, 92) selects TIBEDIED at (2, 90), cursor
; (21, 171) selects LAVE at (20, 173), both names printed).
SelectSystemAtCursor:
    CALL SnapCursorToNearestSystem             ; $B1AC: CD B3 AC  select the system nearest the cursor (moves the cursor onto it)

; VERIFIED: Clear the prompt rows, print the selected system name in capitals (token
; control 3 through PrintTokenInCapitals), a new line and the distance line
; (PrintSelectedSystemDistance), then beep (BeepIfSoundOn).
PrintSelectedSystemSummary:
    CALL ClearPromptLines                      ; $B1AF: CD BC B0  clear rows 21/22
    LD A,$03                                   ; $B1B2: 3E 03  token: "{selected-system}"
    CALL PrintTokenInCapitals                  ; $B1B4: CD 49 B0
    CALL NewLine                               ; $B1B7: CD FA AF
    CALL PrintSelectedSystemDistance           ; $B1BA: CD 5A AE  DISTANCE line (only when nonzero)
    JP BeepIfSoundOn                           ; $B1BD: C3 39 AF  beep (only with sound enabled)

; VERIFIED: Draw the chart cross-hair for cursor ChartCursorX (x) / ChartCursorY (y) via DrawXorCrosshair.
; With CrosshairSize = $0A (the value the galactic chart DrawGalacticChart leaves) the screen
; position is (x, y/2+$18); otherwise it is relative to the current system
; CurrentSystemX/CurrentSystemY: ($61 + 4*dx, $60 + 2*dy).  Returns without drawing when the
; position overflows or y is outside $19..$A6.  Output: ShapeCentreX/ShapeCentreY.
; Called before and after each cursor move, so the drawing toggles (XOR).
; Evidence: chart-cursor and chart traces; instruction semantics.
DrawChartCursor:
    LD A,(CrosshairSize)                       ; $B1C0: 3A 83 D8
    CP $0A                                     ; $B1C3: FE 0A  $0A: galactic chart cross-hair size
    JR Z,L_B211                                ; $B1C5: 28 4A
    LD A,(CurrentSystemX)                      ; $B1C7: 3A 5B A8  short-range chart: relative to the current system
    LD B,A                                     ; $B1CA: 47
    LD A,(ChartCursorX)                        ; $B1CB: 3A 7D A8
    SUB B                                      ; $B1CE: 90  dx = cursor x - current x
    JR C,L_B1DC                                ; $B1CF: 38 0B  cursor left of the current system
    ADD A,A                                    ; $B1D1: 87  2*dx; carry: off the chart
    RET C                                      ; $B1D2: D8
    ADD A,A                                    ; $B1D3: 87  4*dx: 4 pixels per x unit
    RET C                                      ; $B1D4: D8
    LD B,A                                     ; $B1D5: 47
    LD A,$61                                   ; $B1D6: 3E 61  short-range chart x centre
    ADD A,B                                    ; $B1D8: 80
    RET C                                      ; $B1D9: D8  beyond the right edge: not drawn
    JR L_B1E7                                  ; $B1DA: 18 0B
L_B1DC:
    NEG                                        ; $B1DC: ED 44  |dx|
    ADD A,A                                    ; $B1DE: 87
    RET C                                      ; $B1DF: D8
    ADD A,A                                    ; $B1E0: 87
    RET C                                      ; $B1E1: D8
    LD B,A                                     ; $B1E2: 47
    LD A,$61                                   ; $B1E3: 3E 61  x centre again
    SUB B                                      ; $B1E5: 90  x = $61 - 4*|dx|
    RET C                                      ; $B1E6: D8  beyond the left edge: not drawn
L_B1E7:
    LD (ShapeCentreX),A                        ; $B1E7: 32 13 A8  cross-hair centre x
    LD A,(CurrentSystemY)                      ; $B1EA: 3A 59 A8
    LD B,A                                     ; $B1ED: 47
    LD A,(ChartCursorY)                        ; $B1EE: 3A 7E A8
    SUB B                                      ; $B1F1: 90  dy = cursor y - current y
    JR C,L_B1FD                                ; $B1F2: 38 09
    ADD A,A                                    ; $B1F4: 87  2*dy: 2 pixels per y unit
    RET C                                      ; $B1F5: D8
    LD B,A                                     ; $B1F6: 47
    LD A,$60                                   ; $B1F7: 3E 60  short-range chart y centre
    ADD A,B                                    ; $B1F9: 80  y = $60 + 2*dy
    RET C                                      ; $B1FA: D8
    JR L_B206                                  ; $B1FB: 18 09
L_B1FD:
    NEG                                        ; $B1FD: ED 44  |dy|
    ADD A,A                                    ; $B1FF: 87
    RET C                                      ; $B200: D8
    LD B,A                                     ; $B201: 47
    LD A,$60                                   ; $B202: 3E 60  y centre again
    SUB B                                      ; $B204: 90  y = $60 - 2*|dy|
    RET C                                      ; $B205: D8
L_B206:
    CP $19                                     ; $B206: FE 19  above pixel row 25: not drawn
    RET C                                      ; $B208: D8
    CP $A7                                     ; $B209: FE A7  pixel row 167 or below: not drawn
    RET NC                                     ; $B20B: D0
    LD (ShapeCentreY),A                        ; $B20C: 32 14 A8  cross-hair centre y
    JR L_B221                                  ; $B20F: 18 10
L_B211:
    LD A,(ChartCursorX)                        ; $B211: 3A 7D A8  galactic chart: x = cursor x (1 pixel per unit)
    LD (ShapeCentreX),A                        ; $B214: 32 13 A8
    LD A,(ChartCursorY)                        ; $B217: 3A 7E A8
    SRL A                                      ; $B21A: CB 3F  half height: y/2
    ADD A,$18                                  ; $B21C: C6 18  galactic chart: y/2 + 24
    LD (ShapeCentreY),A                        ; $B21E: 32 14 A8
L_B221:
    JP DrawXorCrosshair                        ; $B221: C3 86 D8  XOR the cross-hair (a second call erases it)

; VERIFIED: Chart key handler (JP from $A7FE): erase cursor, ChartCursorY -= 2 (clamped to 0),
; redraw.  Evidence: executed in the chart-cursor trace.
MoveChartCursorUp:
    CALL DrawChartCursor                       ; $B224: CD C0 B1  erase the cross-hair at the old position
    LD A,(ChartCursorY)                        ; $B227: 3A 7E A8
    DEC A                                      ; $B22A: 3D  two units up
    DEC A                                      ; $B22B: 3D
    CP $FE                                     ; $B22C: FE FE  $FE/$FF: moved past 0
    JR C,L_B231                                ; $B22E: 38 01
    XOR A                                      ; $B230: AF  clamp at 0
L_B231:
    LD (ChartCursorY),A                        ; $B231: 32 7E A8
    JR L_B256                                  ; $B234: 18 20

; VERIFIED: Chart key handler (JP from $A7FB): erase cursor, ChartCursorY += 2 (clamped to
; 255), redraw.  Evidence: executed in the chart-cursor trace.
MoveChartCursorDown:
    CALL DrawChartCursor                       ; $B236: CD C0 B1  erase the cross-hair at the old position
    LD A,(ChartCursorY)                        ; $B239: 3A 7E A8
    INC A                                      ; $B23C: 3C  two units down
    INC A                                      ; $B23D: 3C
    CP $02                                     ; $B23E: FE 02  0/1: moved past 255
    JR NC,L_B244                               ; $B240: 30 02
    LD A,$FF                                   ; $B242: 3E FF  clamp at 255
L_B244:
    LD (ChartCursorY),A                        ; $B244: 32 7E A8
    JR L_B256                                  ; $B247: 18 0D

; VERIFIED: Chart key handler (JP from $A7F5): erase cursor, ChartCursorX -= 1 (minimum 1),
; redraw.  Evidence: executed in the chart-cursor trace.
MoveChartCursorLeft:
    CALL DrawChartCursor                       ; $B249: CD C0 B1  erase the cross-hair at the old position
    LD A,(ChartCursorX)                        ; $B24C: 3A 7D A8
    DEC A                                      ; $B24F: 3D  one unit left
    JR NZ,L_B253                               ; $B250: 20 01
    INC A                                      ; $B252: 3C  x 0 is not allowed: back to 1
L_B253:
    LD (ChartCursorX),A                        ; $B253: 32 7D A8

; VERIFIED: Common tail of the cursor handlers: redraw the cursor (JP DrawChartCursor).
L_B256:
    JP DrawChartCursor                         ; $B256: C3 C0 B1  draw the cross-hair at the new position

; VERIFIED: Chart key handler (JP from $A7F8): erase cursor, ChartCursorX += 1 (maximum 254),
; redraw.  Evidence: executed in the chart-cursor trace.
MoveChartCursorRight:
    CALL DrawChartCursor                       ; $B259: CD C0 B1  erase the cross-hair at the old position
    LD A,(ChartCursorX)                        ; $B25C: 3A 7D A8
    INC A                                      ; $B25F: 3C  one unit right
    CP $FF                                     ; $B260: FE FF  255 is not allowed
    JR NZ,L_B265                               ; $B262: 20 01
    DEC A                                      ; $B264: 3D  back to 254
L_B265:
    LD (ChartCursorX),A                        ; $B265: 32 7D A8
    JR L_B256                                  ; $B268: 18 EC

; VERIFIED: Chart key handler (JP from $A801): erase cursor, move it to the current
; system (CurrentSystemX -> ChartCursorX, CurrentSystemY -> ChartCursorY), redraw.
; Evidence: executed in the chart-cursor trace.
ResetChartCursor:
    CALL DrawChartCursor                       ; $B26A: CD C0 B1  erase the cross-hair at the old position
    LD A,(CurrentSystemX)                      ; $B26D: 3A 5B A8  cursor := current system coordinates
    LD (ChartCursorX),A                        ; $B270: 32 7D A8
    LD A,(CurrentSystemY)                      ; $B273: 3A 59 A8
    LD (ChartCursorY),A                        ; $B276: 32 7E A8
    JR L_B256                                  ; $B279: 18 DB

; ============================================================================
; Market and equipment screens, money and decimal output
; Buy/sell cargo, equip ship and laser mounting; the nova-mission offer and
; completion; base-10000 money arithmetic and the decimal printer.
; ============================================================================

; VERIFIED: Docked "buy cargo" key handler (JP from $A7DA).
; - bit 5 of CommanderFlags set: wait and show the inventory (ShowInventory);
; - NovaMissionActive nonzero: show message 91 "THE SUN IS GOING NOVA* WILL YOU SAVE US
;   (Y/N)?" with a drawing by DrawScreenCircle; on 'Y' set LargeCargoBayFitted, clear the cargo hold
;   (17 bytes at CargoHold), set free space CargoFreeSpace = 0 and bit 5 of CommanderFlags;
;   any other key declines without changes; both answers end at the inventory;
; - otherwise run the buy list (BuyCargoList).
; Bit 5 of CommanderFlags is the refugee flag: ShowInventory prints message 12
; "REFUGEES" while it is set, and it blocks buying until SellCargoScreen (or the
; escape pod) clears it.  Evidence: decoded messages 91/12; a simulator check in
; tools/check_routines.py (accept, decline, blocked).
; NovaMissionActive is NovaMissionActive (missions/p5-nova-offer-and-reward).
BuyCargoScreen:
    LD A,(CommanderFlags)                      ; $B27B: 3A 72 A8
    BIT 5,A                                    ; $B27E: CB 6F  bit 5: refugees aboard (ShowInventory lists REFUGEES)
    JR NZ,L_B2BF                               ; $B280: 20 3D  refugees aboard: no market, pause and show the inventory
    LD A,(NovaMissionActive)                   ; $B282: 3A 43 A8  NovaMissionActive nonzero: nova refugee offer instead of the buy list
    AND A                                      ; $B285: A7
    JR Z,BuyCargoList                          ; $B286: 28 3F  zero: normal buy list
    LD DE,$5B17                                ; $B288: 11 17 5B  D = message 91 (nova offer), E = attribute $17
    LD HL,$0201                                ; $B28B: 21 01 02  text column 1, row 2
    CALL ShowColouredMessageScreen             ; $B28E: CD 58 D2  blank screen, all attributes $17, message 91
    LD A,$B6                                   ; $B291: 3E B6  circle centre x
    LD (ShapeCentreX),A                        ; $B293: 32 13 A8
    LD A,$76                                   ; $B296: 3E 76  circle centre y
    LD (ShapeCentreY),A                        ; $B298: 32 14 A8
    LD A,$3D                                   ; $B29B: 3E 3D  circle radius
    LD (ShapeSize),A                           ; $B29D: 32 15 A8
    CALL DrawScreenCircle                      ; $B2A0: CD 61 84  draw the circle straight on the screen
    CALL WaitForKeyPress                       ; $B2A3: CD 48 AF  read the answer
    CP $59                                     ; $B2A6: FE 59  'Y' accepts
    JR NZ,L_B2BF                               ; $B2A8: 20 15  any other key declines
    LD (LargeCargoBayFitted),A                 ; $B2AA: 32 46 A8  accept: large cargo bay byte := 'Y' (nonzero)
    XOR A                                      ; $B2AD: AF
    LD (CargoFreeSpace),A                      ; $B2AE: 32 3E A8  no free cargo space
    LD HL,CargoHold                            ; $B2B1: 21 2D A8  empty all 17 hold bytes
    LD B,$11                                   ; $B2B4: 06 11  17 commodities
L_B2B6:
    LD (HL),A                                  ; $B2B6: 77
    INC HL                                     ; $B2B7: 23
    DJNZ L_B2B6                                ; $B2B8: 10 FC
    LD HL,CommanderFlags                       ; $B2BA: 21 72 A8
    SET 5,(HL)                                 ; $B2BD: CB EE  refugees aboard
L_B2BF:
    CALL Wait36Frames                          ; $B2BF: CD AF B0  pause, then the inventory
    JP ShowInventory                           ; $B2C2: C3 79 D2

; VERIFIED: ColourAttributeStrips data for the buy list: 30 cells with $05 on text rows 1
; and 2 ($F1 = 30 cells then one row down, $F0 = 30 cells and end).
; Evidence: simulator run of ColourAttributeStrips with this table.
BuyScreenAttributeStrips:
    defb $F1,$F0                                                                          ; $B2C5 ..

; VERIFIED: Clear the screen and print token $FF (column headings), colour the title and
; prompt rows, then for each of the 17 commodities: print its market line
; (PrintMarketLine; carry skips it), prompt for a quantity and run InputQuantity with
; BuyCommodity.  Result 1 retries, 2 skips; any other key leaves to ShowInventory.
; Evidence: docked-market trace; decoded tokens.
BuyCargoList:
    CALL ClearScreenAndFrame                   ; $B2C7: CD 9E BC  blank framed screen, cursor at row 1
    CALL SetTextColumnInline                   ; $B2CA: CD 0D B0
    defb $10                                   ; $B2CD: 10  SetTextColumnInline argument: text column 16
    LD A,$FF                                   ; $B2CE: 3E FF  token: "{caps}UNIT  QUANTITY{cr}PRODUCT    UNIT PRICE FOR SALE{title-case}{cr}"
    CALL PrintTokenNewLine                     ; $B2D0: CD F7 AF
    LD DE,BuyScreenAttributeStrips             ; $B2D3: 11 C5 B2
    CALL ColourAttributeStrips                 ; $B2D6: CD DF BB  colour text rows 1 and 2
    CALL ColourPromptRow                       ; $B2D9: CD C6 BB  colour the prompt row 21
    CALL ResetCommodityPointers                ; $B2DC: CD 2E B5  commodity 0; hold and price pointers
    LD HL,MarketStock-1                        ; $B2DF: 21 5F A8  station stock, pre-incremented per commodity
    LD (StockPointer),HL                       ; $B2E2: 22 35 AF  PrintMarketLine advances it per commodity
L_B2E5:
    LD HL,(CargoPointer)                       ; $B2E5: 2A 31 AF
    INC HL                                     ; $B2E8: 23  hold byte of this commodity
    LD (CargoPointer),HL                       ; $B2E9: 22 31 AF
    CALL PrintMarketLine                       ; $B2EC: CD 63 AF  name, unit, price and stock; carry: nothing in stock
    JR C,L_B30F                                ; $B2EF: 38 1E  out of stock: next commodity
    CALL SaveTextCursor                        ; $B2F1: CD B5 B0  cursor is at the start of the next market line
L_B2F4:
    CALL PromptCommodityQuantity               ; $B2F4: CD 44 B4  "QUANTITY OF ..." on the prompt row
    LD HL,BuyCommodity                         ; $B2F7: 21 A1 B3
    CALL InputQuantity                         ; $B2FA: CD 33 B3
    JR NC,L_B309                               ; $B2FD: 30 0A  bought: show the new cash
    CP $01                                     ; $B2FF: FE 01
    JR Z,L_B2F4                                ; $B301: 28 F1  A = 1: error, ask again
    CP $02                                     ; $B303: FE 02
    JR Z,L_B30C                                ; $B305: 28 05  A = 2: Enter, skip this commodity
    JR L_B318                                  ; $B307: 18 0F  any other key: leave to the inventory
L_B309:
    CALL ShowCashAfterTrade                    ; $B309: CD 95 B3
L_B30C:
    CALL RestoreTextCursor                     ; $B30C: CD DE B0  continue with the next market line
L_B30F:
    LD HL,CurrentCommodity                     ; $B30F: 21 30 AF
    INC (HL)                                   ; $B312: 34
    LD A,(HL)                                  ; $B313: 7E
    CP $11                                     ; $B314: FE 11  17 commodities
    JR C,L_B2E5                                ; $B316: 38 CD
L_B318:
    JP ShowInventory                           ; $B318: C3 79 D2

; INFERRED: Dormant routine, never referenced: fill the 768 attribute bytes from $5800
; with A (LD HL,$5800, two CALLs to the 256-byte loop at L_B324, then the loop
; itself).  Decoded as code because both internal CALL operands point exactly
; at the loop; no CALL/JP/pointer in the image targets $B31B.
L_B31B:
    LD HL,$5800                                ; $B31B: 21 00 58
    CALL L_B324                                ; $B31E: CD 24 B3
    CALL L_B324                                ; $B321: CD 24 B3
L_B324:
    LD B,$00                                   ; $B324: 06 00  256 bytes per call
L_B326:
    LD (HL),A                                  ; $B326: 77
    INC HL                                     ; $B327: 23
    DJNZ L_B326                                ; $B328: 10 FC
    RET                                        ; $B32A: C9

; VERIFIED: InputQuantity: delete after the first digit - erase it, undo the attempt
; (RestoreTradeState) and restart the number.
L_B32B:
    CALL EraseInputCharacter                   ; $B32B: CD 26 B0
    CALL RestoreTradeState                     ; $B32E: CD 23 B4  undo the first-digit attempt
    JR L_B336                                  ; $B331: 18 03

; VERIFIED: Read a quantity of one or two digits on the prompt row and try it with the
; handler HL (saved in QuantityHandler, called through CallHL).  The first
; digit must be 1..9; after every digit the previous attempt is undone and
; the handler is called with EnteredNumber.  Result:
;   NC          accepted (Enter after the digits, or a second digit);
;   C, A = 2    Enter before any digit (skip);
;   C, A = 1    the handler reported an error (retry);
;   C, other A  a non-digit key (leave the screen); after a first digit that
;               attempt is not undone, so its trade stays applied.
; Codes below '1' (first digit) or '0' (second) are ignored; delete before a
; digit is ignored, after it undoes the attempt and restarts (L_B32B).
; Evidence: instruction semantics; docked-market, trade-complete traces; a
; simulator check in tools/check_routines.py (scripted key sequences).
InputQuantity:
    LD (QuantityHandler),HL                    ; $B333: 22 72 B4
L_B336:
    XOR A                                      ; $B336: AF
    LD (EnteredNumber),A                       ; $B337: 32 71 B4  no number yet
L_B33A:
    CALL WaitForKeyPress                       ; $B33A: CD 48 AF
    CP $0D                                     ; $B33D: FE 0D  Enter before any digit
    JR Z,L_B391                                ; $B33F: 28 50
    CP $31                                     ; $B341: FE 31  first digit must be '1'..'9'
    JR C,L_B33A                                ; $B343: 38 F5  '0' and lower codes ignored
    CP $FE                                     ; $B345: FE FE
    JR Z,L_B33A                                ; $B347: 28 F1  delete before any digit: ignored
    CP $3A                                     ; $B349: FE 3A  any other key leaves the screen
    JR NC,L_B393                               ; $B34B: 30 46
    LD B,A                                     ; $B34D: 47
    SUB $30                                    ; $B34E: D6 30  digit value
    LD (EnteredNumber),A                       ; $B350: 32 71 B4
    LD A,B                                     ; $B353: 78
    CALL PrintToken                            ; $B354: CD 9D BA  echo the digit
    LD HL,(QuantityHandler)                    ; $B357: 2A 72 B4
    CALL CallHL                                ; $B35A: CD A0 B3  try the one-digit quantity
    JR C,L_B393                                ; $B35D: 38 34  refused: carry, A from the handler
L_B35F:
    CALL WaitForKeyPress                       ; $B35F: CD 48 AF
    CP $0D                                     ; $B362: FE 0D
    RET Z                                      ; $B364: C8  Enter: keep the one-digit result (carry clear)
    CP $30                                     ; $B365: FE 30
    JR C,L_B35F                                ; $B367: 38 F6  below '0': ignored
    CP $FE                                     ; $B369: FE FE
    JR Z,L_B32B                                ; $B36B: 28 BE  delete: undo and start again
    CP $3A                                     ; $B36D: FE 3A
    JR NC,L_B393                               ; $B36F: 30 22  other key: leave; the one-digit attempt stays applied
    LD D,A                                     ; $B371: 57
    SUB $30                                    ; $B372: D6 30
    LD B,A                                     ; $B374: 47
    LD HL,EnteredNumber                        ; $B375: 21 71 B4  EnteredNumber = EnteredNumber*10 + digit
    LD A,(HL)                                  ; $B378: 7E
    ADD A,A                                    ; $B379: 87
    LD C,A                                     ; $B37A: 4F
    ADD A,A                                    ; $B37B: 87
    ADD A,A                                    ; $B37C: 87
    ADD A,C                                    ; $B37D: 81
    ADD A,B                                    ; $B37E: 80
    LD (HL),A                                  ; $B37F: 77
    LD A,D                                     ; $B380: 7A
    CALL PrintToken                            ; $B381: CD 9D BA  echo the second digit
    CALL RestoreTradeState                     ; $B384: CD 23 B4  undo the one-digit attempt
    LD HL,(QuantityHandler)                    ; $B387: 2A 72 B4
    CALL CallHL                                ; $B38A: CD A0 B3  try the two-digit quantity
    JR C,L_B393                                ; $B38D: 38 04
    AND A                                      ; $B38F: A7  accepted: carry clear
    RET                                        ; $B390: C9

; VERIFIED: Enter before any digit: return A = 2 with carry set.
L_B391:
    LD A,$02                                   ; $B391: 3E 02
L_B393:
    SCF                                        ; $B393: 37
    RET                                        ; $B394: C9

; VERIFIED: Column 3, token control 7 (the "Cash: ... Cr" line), then BeepAndWait.
ShowCashAfterTrade:
    CALL SetTextColumnInline                   ; $B395: CD 0D B0
    defb $03                                   ; $B398: 03  SetTextColumnInline argument: text column 3
    CALL PrintInlineToken                      ; $B399: CD 99 BA
    defb $07                                   ; $B39C: 07  PrintInlineToken argument: "{cash}"
    JP BeepAndWait                             ; $B39D: C3 F8 B3

; VERIFIED: JP (HL): called by InputQuantity to run the transaction handler.
CallHL:
    JP (HL)                                    ; $B3A0: E9

; VERIFIED: InputQuantity handler for buying EnteredNumber units of commodity CurrentCommodity:
; take them from the station stock (StockPointer pointer), pay the price word
; (PricePointer pointer) once per unit with SubtractCash, reduce the free space
; CargoFreeSpace for tonne goods, add them to the hold (CargoPointer pointer) and report
; the purchase to AddContrabandPenalty.  Errors: "QUANTITY?", "CASH?" or " CARGO?".
BuyCommodity:
    CALL SaveTradeState                        ; $B3A1: CD 02 B4  checkpoint for RestoreTradeState
    LD A,(EnteredNumber)                       ; $B3A4: 3A 71 B4
    LD B,A                                     ; $B3A7: 47
    LD HL,(StockPointer)                       ; $B3A8: 2A 35 AF  station stock of this commodity
    LD A,(HL)                                  ; $B3AB: 7E
    SUB B                                      ; $B3AC: 90
    JR C,ReportQuantityError                   ; $B3AD: 38 2F  not enough in stock
    LD (HL),A                                  ; $B3AF: 77  stock reduced
L_B3B0:
    LD HL,(PricePointer)                       ; $B3B0: 2A 33 AF
    LD E,(HL)                                  ; $B3B3: 5E  unit price in tenths of a credit
    INC HL                                     ; $B3B4: 23
    LD D,(HL)                                  ; $B3B5: 56
    CALL SubtractCash                          ; $B3B6: CD 77 B8
    JR C,ReportCashError                       ; $B3B9: 38 27  not enough cash
    DJNZ L_B3B0                                ; $B3BB: 10 F3  pay once per unit (B = quantity)
    CALL TestCommodityTonnes                   ; $B3BD: CD 9D B0  carry: measured in tonnes
    LD A,(EnteredNumber)                       ; $B3C0: 3A 71 B4
    LD B,A                                     ; $B3C3: 47
    JR NC,L_B3CE                               ; $B3C4: 30 08  kg/g goods use no cargo space
    LD HL,CargoFreeSpace                       ; $B3C6: 21 3E A8
    LD A,(HL)                                  ; $B3C9: 7E
    SUB B                                      ; $B3CA: 90
    JR C,ReportCargoError                      ; $B3CB: 38 19  not enough free cargo space
    LD (HL),A                                  ; $B3CD: 77  free space reduced
L_B3CE:
    LD HL,(CargoPointer)                       ; $B3CE: 2A 31 AF  hold byte of this commodity
    LD A,(HL)                                  ; $B3D1: 7E
    ADD A,B                                    ; $B3D2: 80
    JR C,ReportCargoError                      ; $B3D3: 38 11  hold byte overflow
    LD (HL),A                                  ; $B3D5: 77
    LD A,(CurrentCommodity)                    ; $B3D6: 3A 30 AF
    CALL AddContrabandPenalty                  ; $B3D9: CD D4 A8  report the purchase (legal score for some goods)
    AND A                                      ; $B3DC: A7  success: carry clear
    RET                                        ; $B3DD: C9

; VERIFIED: Print "QUANTITY?" (token $B0) through PrintTradeError.
ReportQuantityError:
    LD A,$B0                                   ; $B3DE: 3E B0
    JR PrintTradeError                         ; $B3E0: 18 06

; VERIFIED: Print "CASH?" (token $C5) through PrintTradeError.
ReportCashError:
    LD A,$C5                                   ; $B3E2: 3E C5
    JR PrintTradeError                         ; $B3E4: 18 02

; VERIFIED: Print " CARGO?" (token $CE) through PrintTradeError.
ReportCargoError:
    LD A,$CE                                   ; $B3E6: 3E CE

; VERIFIED: At column 3 print token A and '?', undo the attempt (RestoreTradeState),
; then BeepAndWait (returns A = 1, carry set).
PrintTradeError:
    PUSH AF                                    ; $B3E8: F5
    CALL SetTextColumnInline                   ; $B3E9: CD 0D B0
    defb $03                                   ; $B3EC: 03  SetTextColumnInline argument: text column 3
    POP AF                                     ; $B3ED: F1
    CALL PrintToken                            ; $B3EE: CD 9D BA
    CALL PrintInlineToken                      ; $B3F1: CD 99 BA
    defb $3F                                   ; $B3F4: 3F  PrintInlineToken argument: "?"
    CALL RestoreTradeState                     ; $B3F5: CD 23 B4  undo the failed attempt

; VERIFIED: Beep if sound is enabled (BeepIfSoundOn), wait 36 frames, return A = 1 with carry
; set (the "retry" result of InputQuantity handlers).
BeepAndWait:
    CALL BeepIfSoundOn                         ; $B3F8: CD 39 AF
    CALL Wait36Frames                          ; $B3FB: CD AF B0
    LD A,$01                                   ; $B3FE: 3E 01  A = 1 with carry: the "retry" result
    SCF                                        ; $B400: 37
    RET                                        ; $B401: C9

; VERIFIED: Save the cash words (CashHigh, CashLow), the station stock byte at (StockPointer),
; the hold byte at (CargoPointer) and the free cargo space CargoFreeSpace in SavedCashLow..SavedCargoSpace.
; Clobbers: A, HL.
SaveTradeState:
    LD HL,(CashHigh)                           ; $B402: 2A 28 A8
    LD (SavedCashHigh),HL                      ; $B405: 22 6C B4
    LD HL,(CashLow)                            ; $B408: 2A 2A A8
    LD (SavedCashLow),HL                       ; $B40B: 22 6A B4
    LD HL,(StockPointer)                       ; $B40E: 2A 35 AF
    LD A,(HL)                                  ; $B411: 7E
    LD (SavedStockAmount),A                    ; $B412: 32 6F B4
    LD HL,(CargoPointer)                       ; $B415: 2A 31 AF
    LD A,(HL)                                  ; $B418: 7E
    LD (SavedHoldAmount),A                     ; $B419: 32 6E B4
    LD A,(CargoFreeSpace)                      ; $B41C: 3A 3E A8
    LD (SavedCargoSpace),A                     ; $B41F: 32 70 B4
    RET                                        ; $B422: C9

; VERIFIED: Restore everything saved by SaveTradeState (undo a trade attempt).
RestoreTradeState:
    LD HL,(SavedCashHigh)                      ; $B423: 2A 6C B4
    LD (CashHigh),HL                           ; $B426: 22 28 A8
    LD HL,(SavedCashLow)                       ; $B429: 2A 6A B4
    LD (CashLow),HL                            ; $B42C: 22 2A A8
    LD HL,(StockPointer)                       ; $B42F: 2A 35 AF
    LD A,(SavedStockAmount)                    ; $B432: 3A 6F B4
    LD (HL),A                                  ; $B435: 77
    LD HL,(CargoPointer)                       ; $B436: 2A 31 AF
    LD A,(SavedHoldAmount)                     ; $B439: 3A 6E B4
    LD (HL),A                                  ; $B43C: 77
    LD A,(SavedCargoSpace)                     ; $B43D: 3A 70 B4
    LD (CargoFreeSpace),A                      ; $B440: 32 3E A8
    RET                                        ; $B443: C9

; VERIFIED: Clear the prompt rows and print "QUANTITY OF <commodity>/<unit> ?" for
; commodity CurrentCommodity with a capital first letter, then a new line.
PromptCommodityQuantity:
    CALL ClearPromptLines                      ; $B444: CD BC B0
    LD A,$01                                   ; $B447: 3E 01  capitalise the first letter
    LD (CapitaliseNextFlag),A                  ; $B449: 32 92 A8
    CALL PrintInlineToken                      ; $B44C: CD 99 BA
    defb $CC                                   ; $B44F: CC  PrintInlineToken argument: "QUANTITY OF "
    LD A,$D0                                   ; $B450: 3E D0  commodity names are tokens $D0..$E0
    LD B,A                                     ; $B452: 47
    LD A,(CurrentCommodity)                    ; $B453: 3A 30 AF
    ADD A,B                                    ; $B456: 80
    CALL PrintToken                            ; $B457: CD 9D BA
    CALL PrintInlineToken                      ; $B45A: CD 99 BA
    defb $2F                                   ; $B45D: 2F  PrintInlineToken argument: "/"
    CALL PrintCommodityUnit                    ; $B45E: CD 6F B0  unit in lower case
    CALL PrintInlineToken                      ; $B461: CD 99 BA
    defb $20                                   ; $B464: 20  PrintInlineToken argument: " "
    LD A,$3F                                   ; $B465: 3E 3F  token: "?"
    JP PrintTokenNewLine                       ; $B467: C3 F7 AF

; VERIFIED: SaveTradeState copy of the low cash word CashLow.
SavedCashLow:
    defw $0000                                                                            ; $B46A

; VERIFIED: SaveTradeState copy of the high cash word CashHigh.
SavedCashHigh:
    defw $0000                                                                            ; $B46C

; VERIFIED: SaveTradeState copy of the hold byte at (CargoPointer).
SavedHoldAmount:
    defb $00                                                                              ; $B46E .

; VERIFIED: SaveTradeState copy of the station stock byte at (StockPointer).
SavedStockAmount:
    defb $00                                                                              ; $B46F .

; VERIFIED: SaveTradeState copy of the free cargo space CargoFreeSpace.
SavedCargoSpace:
    defb $00                                                                              ; $B470 .

; VERIFIED: Number typed into InputQuantity (1..99); also the selected equipment item.
EnteredNumber:
    defb $00                                                                              ; $B471 .

; VERIFIED: Address of the transaction handler called by InputQuantity.
QuantityHandler:
    defw $0000                                                                            ; $B472

; VERIFIED: Docked "sell cargo" key handler (JP from $A7DD).  When NovaMissionActive is zero and
; bit 5 of CommanderFlags (refugees aboard) is set: clear the bit, add 1 to the combat
; score high byte CombatScoreHigh, set the GEM-STONES hold byte CargoGemStones (commodity 15,
; token $DF, unit g) to 100 and the free space CargoFreeSpace to 35, show message 15
; "YOU HAVE SAVED OUR LIVES*..." and the inventory.  Otherwise run the sell
; list (SellCargoList).  Evidence: decoded tokens/messages; a simulator check in
; tools/check_routines.py (reward values; NovaMissionActive nonzero reaches SellCargoList).
; This is the completion of the nova mission: NovaMissionActive (NovaMissionActive) is cleared by
; the galactic jump the mission forces (missions/p5-nova-offer-and-reward).
SellCargoScreen:
    LD A,(NovaMissionActive)                   ; $B474: 3A 43 A8
    AND A                                      ; $B477: A7
    JR NZ,SellCargoList                        ; $B478: 20 36  nonzero: normal sell list
    LD HL,CommanderFlags                       ; $B47A: 21 72 A8
    LD A,(HL)                                  ; $B47D: 7E
    BIT 5,A                                    ; $B47E: CB 6F  refugees aboard?
    JR Z,SellCargoList                         ; $B480: 28 2E  no: normal sell list
    RES 5,(HL)                                 ; $B482: CB AE  refugees delivered
    LD HL,CombatScoreHigh                      ; $B484: 21 24 A8
    INC (HL)                                   ; $B487: 34  combat score high byte + 1
    LD A,$64                                   ; $B488: 3E 64  reward: 100 g of gem-stones (commodity 15)
    LD (CargoHold+15),A                        ; $B48A: 32 3C A8
    LD A,$23                                   ; $B48D: 3E 23  free space 35: the empty large cargo bay
    LD (CargoFreeSpace),A                      ; $B48F: 32 3E A8
    LD DE,$0F0F                                ; $B492: 11 0F 0F  D = message 15, E = attribute $0F
    LD HL,$0700                                ; $B495: 21 00 07  text column 0, row 7
    CALL ShowMessageScreenAndWait              ; $B498: CD 3E D2  message 15 and a key wait
    JP ShowInventory                           ; $B49B: C3 79 D2

; VERIFIED: ColourAttributeStrips data: 30 cells with $05 on text row 1, then end.
TradeScreenAttributeStrip:
    defb $F0                                                                              ; $B49E .

; VERIFIED: BeginTitledScreen, colour text row 1 (TradeScreenAttributeStrip) and the
; prompt row (ColourPromptRow).
BeginTradeScreen:
    CALL BeginTitledScreen                     ; $B49F: CD AB B4
    LD DE,TradeScreenAttributeStrip            ; $B4A2: 11 9E B4
    CALL ColourAttributeStrips                 ; $B4A5: CD DF BB
    JP ColourPromptRow                         ; $B4A8: C3 C6 BB

; VERIFIED: Print message 150: clear screen and frame, title rule, capitals, column 4
; with a capital (codes 9, 11, 1, 8).
BeginTitledScreen:
    LD A,$96                                   ; $B4AB: 3E 96  message 150: "{cls}{rule}{caps}{col4-cap}"
    JP PrintMessage                            ; $B4AD: C3 D7 BA

; VERIFIED: Title "SELL CARGO", then for each commodity: print the hold line (PrintCargoLine;
; carry skips it), prompt and run InputQuantity with SellCommodity.  Result 1
; retries, 2 skips, other keys leave; finally wait 40 frames and show the
; inventory (ShowInventory).  Evidence: trade-complete trace; decoded tokens.
SellCargoList:
    CALL BeginTradeScreen                      ; $B4B0: CD 9F B4
    CALL PrintInlineToken                      ; $B4B3: CD 99 BA
    defb $CD                                   ; $B4B6: CD  PrintInlineToken argument: "SELL"
    LD A,$CE                                   ; $B4B7: 3E CE  token: " CARGO"
    CALL PrintScreenTitle                      ; $B4B9: CD 57 B0
    CALL ColourPromptRow                       ; $B4BC: CD C6 BB  colour the prompt row 21
    CALL ResetCommodityPointers                ; $B4BF: CD 2E B5
L_B4C2:
    LD HL,(PricePointer)                       ; $B4C2: 2A 33 AF  price word of this commodity
    INC HL                                     ; $B4C5: 23
    INC HL                                     ; $B4C6: 23
    LD (PricePointer),HL                       ; $B4C7: 22 33 AF
    CALL PrintCargoLine                        ; $B4CA: CD B9 AF  carry: none of it in the hold
    JR C,L_B4E6                                ; $B4CD: 38 17  not held: next commodity
    CALL SaveTextCursor                        ; $B4CF: CD B5 B0
L_B4D2:
    CALL PromptCommodityQuantity               ; $B4D2: CD 44 B4
    LD HL,SellCommodity                        ; $B4D5: 21 01 B5
    CALL InputQuantity                         ; $B4D8: CD 33 B3  SellCommodity runs after every digit
    JR C,L_B4F8                                ; $B4DB: 38 1B  refused, skipped or left
    CALL ShowCashAfterTrade                    ; $B4DD: CD 95 B3  sold: show the new cash
L_B4E0:
    CALL RestoreTextCursor                     ; $B4E0: CD DE B0
    CALL NewLine                               ; $B4E3: CD FA AF
L_B4E6:
    LD HL,CurrentCommodity                     ; $B4E6: 21 30 AF
    INC (HL)                                   ; $B4E9: 34
    LD A,(HL)                                  ; $B4EA: 7E
    CP $11                                     ; $B4EB: FE 11  17 commodities
    JP C,L_B4C2                                ; $B4ED: DA C2 B4
    CALL Wait20Frames                          ; $B4F0: CD AB B0  40 frames in total
    CALL Wait20Frames                          ; $B4F3: CD AB B0
    JR L_B4FE                                  ; $B4F6: 18 06
L_B4F8:
    DEC A                                      ; $B4F8: 3D  A = 1: error, ask again
    JR Z,L_B4D2                                ; $B4F9: 28 D7
    DEC A                                      ; $B4FB: 3D  A = 2: Enter, skip this commodity
    JR Z,L_B4E0                                ; $B4FC: 28 E2
L_B4FE:
    JP ShowInventory                           ; $B4FE: C3 79 D2  other keys come straight here

; VERIFIED: InputQuantity handler for selling EnteredNumber units of commodity CurrentCommodity:
; remove them from the hold ("QUANTITY?" if too few), give back free space
; for tonne goods and add the price word (PricePointer pointer) once per unit with
; AddCash.  The station stock is not changed, and unlike BuyCommodity it does
; not call AddContrabandPenalty, so selling never changes the legal score.
SellCommodity:
    CALL SaveTradeState                        ; $B501: CD 02 B4  checkpoint for RestoreTradeState
    LD A,(EnteredNumber)                       ; $B504: 3A 71 B4
    LD B,A                                     ; $B507: 47
    LD HL,(CargoPointer)                       ; $B508: 2A 31 AF
    LD A,(HL)                                  ; $B50B: 7E
    SUB B                                      ; $B50C: 90
    JP C,ReportQuantityError                   ; $B50D: DA DE B3  more than held
    LD (HL),A                                  ; $B510: 77  hold reduced
    PUSH BC                                    ; $B511: C5
    CALL TestCommodityTonnes                   ; $B512: CD 9D B0
    POP BC                                     ; $B515: C1
    JR NC,L_B51F                               ; $B516: 30 07  kg/g goods free no cargo space
    LD A,(CargoFreeSpace)                      ; $B518: 3A 3E A8
    ADD A,B                                    ; $B51B: 80  free space += quantity
    LD (CargoFreeSpace),A                      ; $B51C: 32 3E A8
L_B51F:
    PUSH BC                                    ; $B51F: C5
    LD HL,(PricePointer)                       ; $B520: 2A 33 AF
    LD E,(HL)                                  ; $B523: 5E
    INC HL                                     ; $B524: 23
    LD D,(HL)                                  ; $B525: 56
    CALL AddCash                               ; $B526: CD 4D B8  paid once per unit
    POP BC                                     ; $B529: C1
    DJNZ L_B51F                                ; $B52A: 10 F3
    AND A                                      ; $B52C: A7  success: carry clear (no legal-score change when selling)
    RET                                        ; $B52D: C9

; VERIFIED: Set CargoPointer to the byte before the hold array, PricePointer to two bytes before
; the price words (both are pre-incremented per commodity) and CurrentCommodity = 0.
ResetCommodityPointers:
    LD HL,CargoHold-1                          ; $B52E: 21 2C A8  hold array starts at record +$17 (pointer pre-incremented)
    LD (CargoPointer),HL                       ; $B531: 22 31 AF
    LD HL,L_AF0C                               ; $B534: 21 0C AF  price words start two bytes later (pre-incremented by 2)
    LD (PricePointer),HL                       ; $B537: 22 33 AF
    XOR A                                      ; $B53A: AF
    LD (CurrentCommodity),A                    ; $B53B: 32 30 AF
    RET                                        ; $B53E: C9

; VERIFIED: Docked "equip ship" key handler (JP from $A7E0): title "EQUIP SHIP", then
; list EquipmentItemCount items (tech level CurrentTechLevel + 3, or all 14 from 9 up)
; with number, name (token $69+n) and price from the table at EquipmentPriceTable.
; Fuel (item 1) is not listed while NovaMissionActive is nonzero.
; Evidence: docked-equipment, buy-* and equip-tech10 traces.
EquipShipScreen:
    CALL BeginTradeScreen                      ; $B53F: CD 9F B4
    CALL PrintInlineToken                      ; $B542: CD 99 BA  title in capitals
    defb $06                                   ; $B545: 06  PrintInlineToken argument: "{caps}"
    LD A,$CF                                   ; $B546: 3E CF  token: "EQUIP"
    CALL PrintTokenSpace                       ; $B548: CD EF AF
    CALL PrintInlineToken                      ; $B54B: CD 99 BA
    defb $B9                                   ; $B54E: B9  PrintInlineToken argument: "SHIP"
    CALL PrintInlineToken                      ; $B54F: CD 99 BA
    defb $08                                   ; $B552: 08  PrintInlineToken argument: "{title-case}"
    CALL PrintBlankLine                        ; $B553: CD 5F BA  end the title line and leave a blank line
    LD HL,EquipmentPriceTable                  ; $B556: 21 36 92  first price entry (item 1)
    LD (EquipmentPricePointer),HL              ; $B559: 22 3B B7
    LD A,(CurrentTechLevel)                    ; $B55C: 3A 5E A8  tech level
    ADD A,$03                                  ; $B55F: C6 03
    CP $0C                                     ; $B561: FE 0C  tech level 9 or more offers all 14 items
    JR C,L_B567                                ; $B563: 38 02
    LD A,$0E                                   ; $B565: 3E 0E  counts 12 and 13 become 14: items 12..14 appear together
L_B567:
    LD (EquipmentItemCount),A                  ; $B567: 32 39 B7
    XOR A                                      ; $B56A: AF
L_B56B:
    LD (EquipmentListIndex),A                  ; $B56B: 32 3A B7
    AND A                                      ; $B56E: A7
    JR NZ,L_B577                               ; $B56F: 20 06  index 0 = item 1 (fuel)?
    LD A,(NovaMissionActive)                   ; $B571: 3A 43 A8  nonzero: fuel is not offered
    AND A                                      ; $B574: A7
    JR NZ,L_B5A9                               ; $B575: 20 32  fuel not listed
L_B577:
    LD A,$03                                   ; $B577: 3E 03
    LD (NumberFieldWidth),A                    ; $B579: 32 8E A8  item number in a 3-character field
    LD A,(EquipmentListIndex)                  ; $B57C: 3A 3A B7
    INC A                                      ; $B57F: 3C  items are numbered from 1
    CALL PrintDecimalA                         ; $B580: CD 5C B7
    CALL SetTextColumnInline                   ; $B583: CD 0D B0
    defb $04                                   ; $B586: 04  SetTextColumnInline argument: text column 4
    LD B,$69                                   ; $B587: 06 69  token $69+index: item name
    LD A,(EquipmentListIndex)                  ; $B589: 3A 3A B7
    ADD A,B                                    ; $B58C: 80
    CALL PrintToken                            ; $B58D: CD 9D BA
    CALL SetTextColumnInline                   ; $B590: CD 0D B0
    defb $16                                   ; $B593: 16  SetTextColumnInline argument: text column 22
    LD HL,(EquipmentPricePointer)              ; $B594: 2A 3B B7  price entry: high byte, then low word
    LD A,(HL)                                  ; $B597: 7E
    INC HL                                     ; $B598: 23
    LD E,(HL)                                  ; $B599: 5E
    INC HL                                     ; $B59A: 23
    LD D,(HL)                                  ; $B59B: 56
    INC HL                                     ; $B59C: 23
    LD (EquipmentPricePointer),HL              ; $B59D: 22 3B B7
    LD H,$00                                   ; $B5A0: 26 00  HL = high part (units of 10000 tenths)
    LD L,A                                     ; $B5A2: 6F
    CALL PrintMoney                            ; $B5A3: CD AF B7  price with one decimal place
    CALL NewLine                               ; $B5A6: CD FA AF
L_B5A9:
    LD A,(EquipmentItemCount)                  ; $B5A9: 3A 39 B7
    LD B,A                                     ; $B5AC: 47
    LD A,(EquipmentListIndex)                  ; $B5AD: 3A 3A B7
    INC A                                      ; $B5B0: 3C
    CP B                                       ; $B5B1: B8  all offered items listed?
    JR NZ,L_B56B                               ; $B5B2: 20 B7

; VERIFIED: Prompt "ITEM? ", read the number (InputQuantity with AcceptQuantity) and buy
; it: pay the price (SubtractCashHigh, SubtractCash; "CASH?" on failure),
; then fuel refills to 70 (SetFuelLevel), missiles up to 4, large cargo bay adds 15
; to CargoFreeSpace, lasers go to ChooseLaserView, other items set their byte to $FF;
; items already present print "... PRESENT".  Non-digit keys or an item out
; of range go to the status screen (ShowCommanderStatus).
; Quirk: item 1 (fuel) typed while NovaMissionActive is nonzero (the list hides it then) is
; paid for but refused: the code returns to the item prompt without undoing the
; payment, so the current fuel price is lost.
; Evidence: instruction semantics; a simulator check in tools/check_routines.py
; (fuel with and without NovaMissionActive, missiles at 4).
BuyEquipmentItem:
    CALL ClearPromptLines                      ; $B5B4: CD BC B0  clear rows 21/22
    CALL PrintInlineToken                      ; $B5B7: CD 99 BA
    defb $7F                                   ; $B5BA: 7F  PrintInlineToken argument: "ITEM"
    LD A,$3F                                   ; $B5BB: 3E 3F  token: "?"
    CALL PrintTokenSpace                       ; $B5BD: CD EF AF
    CALL SaveTradeState                        ; $B5C0: CD 02 B4  snapshot: InputQuantity may call RestoreTradeState
    LD HL,AcceptQuantity                       ; $B5C3: 21 08 B7
    CALL InputQuantity                         ; $B5C6: CD 33 B3
    JR C,L_B5DA                                ; $B5C9: 38 0F  non-digit key: status screen
    CALL NewLine                               ; $B5CB: CD FA AF
    LD A,(EnteredNumber)                       ; $B5CE: 3A 71 B4
    AND A                                      ; $B5D1: A7
    JP Z,ShowCommanderStatus                   ; $B5D2: CA B9 D0  item 0 (cannot be typed): status screen
    LD B,A                                     ; $B5D5: 47
    LD A,(EquipmentItemCount)                  ; $B5D6: 3A 39 B7
    CP B                                       ; $B5D9: B8  item beyond the offered list?
L_B5DA:
    JP C,ShowCommanderStatus                   ; $B5DA: DA B9 D0  non-digit key or item not offered: status screen
    CALL SaveTradeState                        ; $B5DD: CD 02 B4  checkpoint before paying
    LD A,(EnteredNumber)                       ; $B5E0: 3A 71 B4
    CALL GetEquipmentPriceEntry                ; $B5E3: CD 0A B7
    LD D,$00                                   ; $B5E6: 16 00
    LD E,(HL)                                  ; $B5E8: 5E  high part of the price
    PUSH HL                                    ; $B5E9: E5
    CALL SubtractCashHigh                      ; $B5EA: CD 69 B8  carry is clear here (ADD HL,DE in AddAToHL)
    POP HL                                     ; $B5ED: E1
    JR C,L_B5F7                                ; $B5EE: 38 07
    INC HL                                     ; $B5F0: 23
    LD E,(HL)                                  ; $B5F1: 5E  low part of the price (tenths)
    INC HL                                     ; $B5F2: 23
    LD D,(HL)                                  ; $B5F3: 56
    CALL SubtractCash                          ; $B5F4: CD 77 B8
L_B5F7:
    JP C,ReportEquipmentCashError              ; $B5F7: DA 02 B7  not enough cash: "CASH?", undo, ask again
    LD A,(EnteredNumber)                       ; $B5FA: 3A 71 B4
    CP $01                                     ; $B5FD: FE 01  item 1: fuel
    JR NZ,L_B616                               ; $B5FF: 20 15
    LD A,(NovaMissionActive)                   ; $B601: 3A 43 A8
    AND A                                      ; $B604: A7
    JR NZ,BuyEquipmentItem                     ; $B605: 20 AD  NovaMissionActive set: refused, the fuel price is not refunded
    XOR A                                      ; $B607: AF
    LD (L_9237),A                              ; $B608: 32 37 92  fuel price low byte := 0 (its high byte is always 0)
    CALL ShowCashAfterTrade                    ; $B60B: CD 95 B3
    LD A,$46                                   ; $B60E: 3E 46  fill the tank: 70 = 7.0 light years
    CALL SetFuelLevel                          ; $B610: CD 6D D8
    JP EquipShipScreen                         ; $B613: C3 3F B5  list the items again

; VERIFIED: BuyEquipmentItem, items 2..14 after payment: 2 adds a missile (at most 4,
; otherwise "ALL PRESENT"), 3 fits the large cargo bay (+15 free space, byte $FF), 4 and
; 7..12 set their commander byte (NovaMissionActive + item) to $FF unless it is already
; nonzero ("... PRESENT"), 5, 6, 13 and 14 are lasers (L_B65A).  Every refusal
; undoes the payment (RestoreTradeState in L_B729).
L_B616:
    CP $02                                     ; $B616: FE 02  item 2: missile
    JR NZ,L_B627                               ; $B618: 20 0D
    LD HL,MissileCount                         ; $B61A: 21 45 A8
    LD A,(HL)                                  ; $B61D: 7E
    CP $04                                     ; $B61E: FE 04  four missiles at most
    JP NC,ReportAllMissilesPresent             ; $B620: D2 1E B7
    INC A                                      ; $B623: 3C
    LD (HL),A                                  ; $B624: 77  one more missile
    JR L_B654                                  ; $B625: 18 2D
L_B627:
    CP $03                                     ; $B627: FE 03  item 3: large cargo bay
    JR NZ,L_B63B                               ; $B629: 20 10
    LD A,(LargeCargoBayFitted)                 ; $B62B: 3A 46 A8  large cargo bay already fitted?
    AND A                                      ; $B62E: A7
    JP NZ,ReportEquipmentPresent               ; $B62F: C2 22 B7
    LD HL,CargoFreeSpace                       ; $B632: 21 3E A8
    LD A,(HL)                                  ; $B635: 7E
    ADD A,$0F                                  ; $B636: C6 0F  free cargo space +15
    LD (HL),A                                  ; $B638: 77
    JR L_B64F                                  ; $B639: 18 14
L_B63B:
    CP $04                                     ; $B63B: FE 04  item 4: E.C.M. system
    JR Z,L_B647                                ; $B63D: 28 08
    CP $07                                     ; $B63F: FE 07  items 5 and 6: lasers
    JR C,L_B65A                                ; $B641: 38 17
    CP $0D                                     ; $B643: FE 0D  items 13 and 14: lasers; 7..12 fall through
    JR NC,L_B65A                               ; $B645: 30 13
L_B647:
    CALL GetEquipmentStatePointer              ; $B647: CD 13 B7  commander byte of the item
    LD A,(HL)                                  ; $B64A: 7E
    AND A                                      ; $B64B: A7
    JP NZ,ReportEquipmentPresent               ; $B64C: C2 22 B7  already fitted
L_B64F:
    CALL GetEquipmentStatePointer              ; $B64F: CD 13 B7
    LD (HL),$FF                                ; $B652: 36 FF  $FF: item fitted
L_B654:
    CALL ShowCashAfterTrade                    ; $B654: CD 95 B3  new cash, then the next item
    JP BuyEquipmentItem                        ; $B657: C3 B4 B5

; VERIFIED: Laser items: B = laser type 1 (item 5, pulse), 2 (item 6, beam),
; 3 (item 13, military) or 4 (item 14, mining).
L_B65A:
    LD B,$01                                   ; $B65A: 06 01
    CP $05                                     ; $B65C: FE 05
    JR Z,ChooseLaserView                       ; $B65E: 28 0B
    INC B                                      ; $B660: 04
    CP $06                                     ; $B661: FE 06
    JR Z,ChooseLaserView                       ; $B663: 28 06
    INC B                                      ; $B665: 04
    CP $0D                                     ; $B666: FE 0D
    JR Z,ChooseLaserView                       ; $B668: 28 01
    INC B                                      ; $B66A: 04

; VERIFIED: Store the laser type B in NewLaserType, clear the screen, print the laser
; name and the four views (0 FRONT .. 3 RIGHT), prompt " VIEW ?" and read a
; key.  '0'..'3' fits the laser to LaserMounts+view and refunds the laser that was
; there (item number from the table at L_FB99+type, price from EquipmentPriceTable);
; any other key undoes the purchase (L_B6FD).
ChooseLaserView:
    LD A,B                                     ; $B66B: 78
    LD (NewLaserType),A                        ; $B66C: 32 3D B7
    PUSH BC                                    ; $B66F: C5
    CALL ClearScreenAndFrame                   ; $B670: CD 9E BC  new screen for the view choice
    CALL ColourPromptRow                       ; $B673: CD C6 BB
    POP BC                                     ; $B676: C1
    LD A,$04                                   ; $B677: 3E 04  column 4 + laser type
    ADD A,B                                    ; $B679: 80
    CALL SetTextColumn                         ; $B67A: CD 11 B0
    LD A,$0E                                   ; $B67D: 3E 0E  row 14
    CALL SetTextRow                            ; $B67F: CD 19 B0
    LD A,(EnteredNumber)                       ; $B682: 3A 71 B4
    LD B,$68                                   ; $B685: 06 68  token $68+item: laser name
    ADD A,B                                    ; $B687: 80
    CALL PrintToken                            ; $B688: CD 9D BA
    LD A,$10                                   ; $B68B: 3E 10  views listed from row 16
    CALL SetTextRow                            ; $B68D: CD 19 B0
    XOR A                                      ; $B690: AF
L_B691:
    LD (EquipmentListIndex),A                  ; $B691: 32 3A B7
    CALL SetTextColumnInline                   ; $B694: CD 0D B0
    defb $0A                                   ; $B697: 0A  SetTextColumnInline argument: text column 10
    LD A,(EquipmentListIndex)                  ; $B698: 3A 3A B7
    ADD A,$30                                  ; $B69B: C6 30  view number '0'..'3'
    CALL PrintTokenSpace                       ; $B69D: CD EF AF
    LD A,(EquipmentListIndex)                  ; $B6A0: 3A 3A B7
    ADD A,$60                                  ; $B6A3: C6 60  token $60+view: FRONT, REAR, LEFT, RIGHT
    CALL PrintTokenNewLine                     ; $B6A5: CD F7 AF
    LD A,(EquipmentListIndex)                  ; $B6A8: 3A 3A B7
    INC A                                      ; $B6AB: 3C
    CP $04                                     ; $B6AC: FE 04  four views
    JR C,L_B691                                ; $B6AE: 38 E1
    CALL ClearPromptLines                      ; $B6B0: CD BC B0  clear rows 21/22
    CALL PrintInlineToken                      ; $B6B3: CD 99 BA
    defb $AF                                   ; $B6B6: AF  PrintInlineToken argument: " VIEW "
    CALL PrintInlineToken                      ; $B6B7: CD 99 BA
    defb $3F                                   ; $B6BA: 3F  PrintInlineToken argument: "?"
    CALL WaitForKeyPress                       ; $B6BB: CD 48 AF  view key
    CP $30                                     ; $B6BE: FE 30
    JP C,L_B6FD                                ; $B6C0: DA FD B6  below '0': cancel the purchase
    CP $34                                     ; $B6C3: FE 34
    JP NC,L_B6FD                               ; $B6C5: D2 FD B6  above '3': cancel the purchase
    PUSH AF                                    ; $B6C8: F5
    CALL PrintTokenNewLine                     ; $B6C9: CD F7 AF  echo the key
    POP AF                                     ; $B6CC: F1
    SUB $30                                    ; $B6CD: D6 30
    LD HL,LaserMounts                          ; $B6CF: 21 3F A8  laser type per view (4 bytes)
    CALL AddAToHL                              ; $B6D2: CD 19 B7
    LD B,(HL)                                  ; $B6D5: 46  laser type previously in this view
    LD A,(NewLaserType)                        ; $B6D6: 3A 3D B7
    LD (HL),A                                  ; $B6D9: 77  fit the new laser
    LD A,B                                     ; $B6DA: 78
    AND A                                      ; $B6DB: A7
    JR Z,L_B6F7                                ; $B6DC: 28 19  view was empty: nothing to refund
    LD HL,LaserTypeItemTable-1                 ; $B6DE: 21 99 FB  table of item numbers for laser types 1..4 (index 1-based)
    CALL AddAToHL                              ; $B6E1: CD 19 B7
    LD A,(HL)                                  ; $B6E4: 7E  item number of the old laser
    CALL GetEquipmentPriceEntry                ; $B6E5: CD 0A B7
    LD D,$00                                   ; $B6E8: 16 00
    LD E,(HL)                                  ; $B6EA: 5E  refund the high part of its price
    PUSH HL                                    ; $B6EB: E5
    CALL AddCashHigh                           ; $B6EC: CD 61 B8
    POP HL                                     ; $B6EF: E1
    INC HL                                     ; $B6F0: 23
    LD E,(HL)                                  ; $B6F1: 5E
    INC HL                                     ; $B6F2: 23
    LD D,(HL)                                  ; $B6F3: 56
    CALL AddCash                               ; $B6F4: CD 4D B8  refund the low part
L_B6F7:
    CALL ShowCashAfterTrade                    ; $B6F7: CD 95 B3  new cash, then the equipment list
    JP EquipShipScreen                         ; $B6FA: C3 3F B5

; VERIFIED: Cancel a laser purchase: RestoreTradeState, then the status screen.
L_B6FD:
    CALL RestoreTradeState                     ; $B6FD: CD 23 B4
    JR L_B736                                  ; $B700: 18 34

; VERIFIED: "CASH?" (ReportCashError) and back to the item prompt.
ReportEquipmentCashError:
    CALL ReportCashError                       ; $B702: CD E2 B3
    JP BuyEquipmentItem                        ; $B705: C3 B4 B5

; VERIFIED: InputQuantity handler that accepts any number: AND A (clear carry), RET.
AcceptQuantity:
    AND A                                      ; $B708: A7
    RET                                        ; $B709: C9

; VERIFIED: HL = EquipmentPriceTable + 3*(A-1): the 3-byte price entry of equipment item A
; (byte = high cash units of 10000 tenths, word = low tenths).
GetEquipmentPriceEntry:
    DEC A                                      ; $B70A: 3D  items are numbered from 1
    LD B,A                                     ; $B70B: 47
    ADD A,A                                    ; $B70C: 87
    ADD A,B                                    ; $B70D: 80  A = 3*(item-1)
    LD HL,EquipmentPriceTable                  ; $B70E: 21 36 92
    JR AddAToHL                                ; $B711: 18 06

; VERIFIED: HL = NovaMissionActive + EnteredNumber: the commander byte of the selected item
; (item 1 = fuel FuelLevel, 2 = missiles MissileCount, ...).
GetEquipmentStatePointer:
    LD HL,NovaMissionActive                    ; $B713: 21 43 A8  item n uses the byte at NovaMissionActive + n
    LD A,(EnteredNumber)                       ; $B716: 3A 71 B4

; VERIFIED: HL = HL + A (D = 0, E = A).  Clobbers: DE.
AddAToHL:
    LD D,$00                                   ; $B719: 16 00
    LD E,A                                     ; $B71B: 5F
    ADD HL,DE                                  ; $B71C: 19
    RET                                        ; $B71D: C9

; VERIFIED: Print "ALL PRESENT" (four missiles already fitted).
ReportAllMissilesPresent:
    LD A,$7C                                   ; $B71E: 3E 7C  token $7C: "ALL"
    JR L_B729                                  ; $B720: 18 07

; VERIFIED: Print "<item name> PRESENT" for item EnteredNumber (token $68+n).
ReportEquipmentPresent:
    LD A,$68                                   ; $B722: 3E 68  item names are tokens $69..$76
    LD B,A                                     ; $B724: 47
    LD A,(EnteredNumber)                       ; $B725: 3A 71 B4
    ADD A,B                                    ; $B728: 80

; VERIFIED: Print token A, " PRESENT", BeepAndWait, undo the purchase
; (RestoreTradeState) and show the status screen (ShowCommanderStatus).
L_B729:
    CALL PrintTokenSpace                       ; $B729: CD EF AF
    CALL PrintInlineToken                      ; $B72C: CD 99 BA
    defb $1E                                   ; $B72F: 1E  PrintInlineToken argument: "PRESENT"
    CALL BeepAndWait                           ; $B730: CD F8 B3
    CALL RestoreTradeState                     ; $B733: CD 23 B4  undo the purchase (cash)
L_B736:
    JP ShowCommanderStatus                     ; $B736: C3 B9 D0

; VERIFIED: Number of equipment items offered (3 + tech level, 14 when that is 12+).
EquipmentItemCount:
    defb $00                                                                              ; $B739 .

; VERIFIED: Loop index of the equipment list (also used by ChooseLaserView).
EquipmentListIndex:
    defb $00                                                                              ; $B73A .

; VERIFIED: Pointer into the equipment price table while listing (3 bytes per item).
EquipmentPricePointer:
    defw $0000                                                                            ; $B73B

; VERIFIED: Laser type 1..4 being fitted by ChooseLaserView.
NewLaserType:
    defb $00                                                                              ; $B73D .

; VERIFIED: Column 6, PrintScreenTitle(A), then ColourBannerRows with attribute $17.
; Evidence: callers in the short-range (L_A9D0) and galactic (DrawGalacticChart) charts.
PrintBannerTitle:
    PUSH AF                                    ; $B73E: F5
    CALL SetTextColumnInline                   ; $B73F: CD 0D B0
    defb $06                                   ; $B742: 06  SetTextColumnInline argument: text column 6
    POP AF                                     ; $B743: F1
    CALL PrintScreenTitle                      ; $B744: CD 57 B0
    LD A,$17                                   ; $B747: 3E 17  banner attribute $17

; VERIFIED: Fill attribute rows 0..2 with A and draw a full-width line at pixel row 23
; ($4740).  Clobbers: A, B, HL.
ColourBannerRows:
    LD HL,$5800                                ; $B749: 21 00 58  attribute row 0, column 0
    LD B,$60                                   ; $B74C: 06 60  96 cells: attribute rows 0..2
    CALL FillBytes                             ; $B74E: CD DA BB
    LD HL,$4740                                ; $B751: 21 40 47  pixel row 23
    JP DrawFullWidthLine                       ; $B754: C3 D6 BB

; VERIFIED: PrintDecimalHL: value still to be printed (remainder after each digit).
DecimalRemainder:
    defw $0000                                                                            ; $B757

; VERIFIED: Print A as an unsigned decimal number with one decimal place (A/10),
; for example 70 prints as 7.0.  Sets carry and joins PrintDecimalHL.
PrintDecimalTenths:
    SCF                                        ; $B759: 37
    JR L_B75D                                  ; $B75A: 18 01

; VERIFIED: Print A as an unsigned decimal number without a decimal point.
PrintDecimalA:
    AND A                                      ; $B75C: A7
L_B75D:
    LD H,$00                                   ; $B75D: 26 00
    LD L,A                                     ; $B75F: 6F

; VERIFIED: Print HL as an unsigned decimal number using the divisors 10000, 1000,
; 100 and 10.  PadDecimalField first pads to the field width in NumberFieldWidth: with spaces
; while LeadingZeroFlag (suppress leading zeros) is set, with zeros when it is clear
; (used for money).  Leading zero digits are skipped while LeadingZeroFlag is set.
; With carry set on entry a decimal point is printed before the last digit, so a
; value below 10 prints as 0.n.
; On exit NumberFieldWidth = 0 and LeadingZeroFlag = 1.
PrintDecimalHL:
    PUSH AF                                    ; $B760: F5
    PUSH HL                                    ; $B761: E5
    CALL PadDecimalField                       ; $B762: CD F7 B7  leading spaces or zeros up to the field width
    POP HL                                     ; $B765: E1
    LD A,$01                                   ; $B766: 3E 01  skip leading zero digits from here on
    LD (LeadingZeroFlag),A                     ; $B768: 32 8D A8
    LD (DecimalRemainder),HL                   ; $B76B: 22 57 B7  value still to be printed
    LD DE,$2710                                ; $B76E: 11 10 27  10000
    CALL PrintDecimalDigit                     ; $B771: CD D2 B7
    LD DE,$03E8                                ; $B774: 11 E8 03  1000
    CALL PrintDecimalDigit                     ; $B777: CD D2 B7
    LD DE,$0064                                ; $B77A: 11 64 00  100
    CALL PrintDecimalDigit                     ; $B77D: CD D2 B7
    LD DE,$000A                                ; $B780: 11 0A 00  10
    CALL PrintDecimalDigit                     ; $B783: CD D2 B7
    POP AF                                     ; $B786: F1
    JR NC,L_B798                               ; $B787: 30 0F  no decimal point requested
    LD A,(LeadingZeroFlag)                     ; $B789: 3A 8D A8
    AND A                                      ; $B78C: A7
    JP Z,L_B794                                ; $B78D: CA 94 B7  a digit was printed already
    XOR A                                      ; $B790: AF  value below 10: "0" before the point
    CALL PrintDigitA                           ; $B791: CD EB B7

; VERIFIED: Decimal point before the last digit.
L_B794:
    CALL PrintInlineToken                      ; $B794: CD 99 BA
    defb $2E                                   ; $B797: 2E  PrintInlineToken argument: "."
L_B798:
    LD HL,(DecimalRemainder)                   ; $B798: 2A 57 B7  units digit (the tenth when a point was printed)
    LD A,L                                     ; $B79B: 7D
    CALL PrintDigitA                           ; $B79C: CD EB B7
    XOR A                                      ; $B79F: AF
    LD (NumberFieldWidth),A                    ; $B7A0: 32 8E A8  reset the field width
    INC A                                      ; $B7A3: 3C
    LD (LeadingZeroFlag),A                     ; $B7A4: 32 8D A8  LeadingZeroFlag = 1 again
    RET                                        ; $B7A7: C9

; VERIFIED: Print the commander's cash: HL = high word CashHigh, DE = low word CashLow,
; then PrintMoney.  Evidence: token 7 "Cash:   100.0 Cr" in the simulator.
PrintCash:
    LD HL,(CashHigh)                           ; $B7A8: 2A 28 A8  high part: units of 10000 tenths
    LD DE,(CashLow)                            ; $B7AB: ED 5B 2A A8

; VERIFIED: Print HL*10000+DE tenths of a credit with one decimal place: if HL is
; nonzero print it (width 3) and DE zero-padded (4 digits), else DE in a
; 7-character field.  Clobbers: AF, BC, DE, HL.
PrintMoney:
    PUSH DE                                    ; $B7AF: D5
    LD A,L                                     ; $B7B0: 7D
    OR H                                       ; $B7B1: B4
    JR Z,L_B7C8                                ; $B7B2: 28 14  below 1000 Cr: a single field
    LD A,$03                                   ; $B7B4: 3E 03  high part in 3 characters
    LD (NumberFieldWidth),A                    ; $B7B6: 32 8E A8
    AND A                                      ; $B7B9: A7  no decimal point
    CALL PrintDecimalHL                        ; $B7BA: CD 60 B7
    XOR A                                      ; $B7BD: AF
    LD (LeadingZeroFlag),A                     ; $B7BE: 32 8D A8  low part padded with zeros
    LD A,$04                                   ; $B7C1: 3E 04  4 digits including the tenth
    LD (NumberFieldWidth),A                    ; $B7C3: 32 8E A8
    JR L_B7CD                                  ; $B7C6: 18 05
L_B7C8:
    LD A,$07                                   ; $B7C8: 3E 07  7 digits including the tenth, space-padded
    LD (NumberFieldWidth),A                    ; $B7CA: 32 8E A8
L_B7CD:
    POP HL                                     ; $B7CD: E1
    SCF                                        ; $B7CE: 37  with one decimal place
    JP PrintDecimalHL                          ; $B7CF: C3 60 B7

; VERIFIED: Divide DecimalRemainder by DE (repeated subtraction), keep the remainder
; and print the digit; a zero digit is skipped while LeadingZeroFlag is set.
PrintDecimalDigit:
    LD HL,(DecimalRemainder)                   ; $B7D2: 2A 57 B7
    XOR A                                      ; $B7D5: AF  digit 0, carry clear
    AND A                                      ; $B7D6: A7
L_B7D7:
    SBC HL,DE                                  ; $B7D7: ED 52  subtract the divisor until it goes negative
    JR C,L_B7DE                                ; $B7D9: 38 03
    INC A                                      ; $B7DB: 3C
    JR L_B7D7                                  ; $B7DC: 18 F9
L_B7DE:
    ADD HL,DE                                  ; $B7DE: 19  undo the last subtraction: remainder
    LD (DecimalRemainder),HL                   ; $B7DF: 22 57 B7
    AND A                                      ; $B7E2: A7
    JR Z,L_B7F0                                ; $B7E3: 28 0B  zero digit
    LD B,A                                     ; $B7E5: 47
    XOR A                                      ; $B7E6: AF
    LD (LeadingZeroFlag),A                     ; $B7E7: 32 8D A8  nonzero digit: stop skipping zeros
    LD A,B                                     ; $B7EA: 78

; VERIFIED: Print digit A (0..9) as a character.
PrintDigitA:
    ADD A,$30                                  ; $B7EB: C6 30  digit to '0'..'9'
    JP PrintToken                              ; $B7ED: C3 9D BA
L_B7F0:
    LD A,(LeadingZeroFlag)                     ; $B7F0: 3A 8D A8
    AND A                                      ; $B7F3: A7
    JR Z,PrintDigitA                           ; $B7F4: 28 F5  zero digit printed unless still leading
    RET                                        ; $B7F6: C9

; VERIFIED: Count the digits of HL (a value below 10 counts 2 when carry requests a
; decimal point) and print spaces (LeadingZeroFlag set) or zeros up to the field width
; in NumberFieldWidth.
PadDecimalField:
    LD B,$01                                   ; $B7F7: 06 01  at least one digit
    JR NC,L_B805                               ; $B7F9: 30 0A  no decimal point
    PUSH HL                                    ; $B7FB: E5
    AND A                                      ; $B7FC: A7
    LD DE,$000A                                ; $B7FD: 11 0A 00
    SBC HL,DE                                  ; $B800: ED 52
    POP HL                                     ; $B802: E1
    JR C,L_B829                                ; $B803: 38 24  below 10 with a point: 2 digits ("0.n")
L_B805:
    AND A                                      ; $B805: A7
    LD DE,$000A                                ; $B806: 11 0A 00
    CALL CompareHLDE                           ; $B809: CD 48 B8
    JR C,L_B82A                                ; $B80C: 38 1C  below 10: 1 digit
    LD DE,$0064                                ; $B80E: 11 64 00
    CALL CompareHLDE                           ; $B811: CD 48 B8
    JR C,L_B829                                ; $B814: 38 13  below 100: 2 digits
    LD DE,$03E8                                ; $B816: 11 E8 03
    CALL CompareHLDE                           ; $B819: CD 48 B8
    JR C,L_B828                                ; $B81C: 38 0A  below 1000: 3 digits
    LD DE,$2710                                ; $B81E: 11 10 27
    CALL CompareHLDE                           ; $B821: CD 48 B8
    JR C,L_B827                                ; $B824: 38 01  below 10000: 4 digits, otherwise 5
    INC B                                      ; $B826: 04
L_B827:
    INC B                                      ; $B827: 04
L_B828:
    INC B                                      ; $B828: 04
L_B829:
    INC B                                      ; $B829: 04
L_B82A:
    LD A,(NumberFieldWidth)                    ; $B82A: 3A 8E A8
    CP B                                       ; $B82D: B8
    RET Z                                      ; $B82E: C8  field not wider than the number: no padding
    RET C                                      ; $B82F: D8
    SUB B                                      ; $B830: 90  number of padding characters
    LD B,A                                     ; $B831: 47
L_B832:
    PUSH BC                                    ; $B832: C5
    LD A,(LeadingZeroFlag)                     ; $B833: 3A 8D A8
    AND A                                      ; $B836: A7
    JP Z,L_B83F                                ; $B837: CA 3F B8  flag clear: pad with zeros
    LD A,$20                                   ; $B83A: 3E 20  flag set: pad with spaces
    JP L_B841                                  ; $B83C: C3 41 B8
L_B83F:
    LD A,$30                                   ; $B83F: 3E 30  token: "0"
L_B841:
    CALL PrintToken                            ; $B841: CD 9D BA
    POP BC                                     ; $B844: C1
    DJNZ L_B832                                ; $B845: 10 EB
    RET                                        ; $B847: C9

; VERIFIED: Carry set when HL < DE (SBC with the incoming carry); HL is preserved.
CompareHLDE:
    PUSH HL                                    ; $B848: E5
    SBC HL,DE                                  ; $B849: ED 52
    POP HL                                     ; $B84B: E1
    RET                                        ; $B84C: C9

; VERIFIED: Add DE tenths to the low cash word; at 10000 or more subtract 10000 and add
; 1 to the high word (falls into AddCashHigh with DE = 1).
AddCash:
    LD HL,(CashLow)                            ; $B84D: 2A 2A A8
    ADD HL,DE                                  ; $B850: 19  add to the low word
    LD (CashLow),HL                            ; $B851: 22 2A A8
    AND A                                      ; $B854: A7
    LD DE,$2710                                ; $B855: 11 10 27  cash low word wraps at 10000 tenths
    SBC HL,DE                                  ; $B858: ED 52  10000 or more?
    RET C                                      ; $B85A: D8
    LD (CashLow),HL                            ; $B85B: 22 2A A8  keep the excess
    LD DE,$0001                                ; $B85E: 11 01 00  carry 1 into the high word

; VERIFIED: Add DE to the high cash word CashHigh.
AddCashHigh:
    LD HL,(CashHigh)                           ; $B861: 2A 28 A8
    ADD HL,DE                                  ; $B864: 19
    LD (CashHigh),HL                           ; $B865: 22 28 A8
    RET                                        ; $B868: C9

; VERIFIED: Subtract DE from the high cash word (SBC; carry must be clear on entry).
; Carry set and no change if it would go negative.
SubtractCashHigh:
    LD HL,(CashHigh)                           ; $B869: 2A 28 A8
    SBC HL,DE                                  ; $B86C: ED 52  carry: not enough
    JR C,L_B875                                ; $B86E: 38 05
    LD (CashHigh),HL                           ; $B870: 22 28 A8
    AND A                                      ; $B873: A7  success: carry clear
    RET                                        ; $B874: C9
L_B875:
    SCF                                        ; $B875: 37  not enough: carry set, cash unchanged
    RET                                        ; $B876: C9

; VERIFIED: Subtract DE tenths from the cash, borrowing 10000 from the high word when
; needed.  Carry set (unchanged cash) when the cash is insufficient.
SubtractCash:
    LD HL,(CashLow)                            ; $B877: 2A 2A A8
    AND A                                      ; $B87A: A7
    SBC HL,DE                                  ; $B87B: ED 52
    JR NC,L_B895                               ; $B87D: 30 16  the low word suffices
    LD HL,(CashHigh)                           ; $B87F: 2A 28 A8
    LD A,L                                     ; $B882: 7D
    OR H                                       ; $B883: B4
    SCF                                        ; $B884: 37
    RET Z                                      ; $B885: C8  high word 0 too: not enough (carry set)
    DEC HL                                     ; $B886: 2B  borrow one high unit
    LD (CashHigh),HL                           ; $B887: 22 28 A8
    LD HL,$2710                                ; $B88A: 21 10 27  borrow 10000 tenths from the high word
    AND A                                      ; $B88D: A7
    SBC HL,DE                                  ; $B88E: ED 52
    LD DE,(CashLow)                            ; $B890: ED 5B 2A A8
    ADD HL,DE                                  ; $B894: 19  low = low + 10000 - price
L_B895:
    LD (CashLow),HL                            ; $B895: 22 2A A8
    AND A                                      ; $B898: A7  success: carry clear
    RET                                        ; $B899: C9

; VERIFIED: Jump to message control handler A (0..31) from the word table at MessageControlTable.
DispatchMessageControl:
    LD HL,MessageControlTable                  ; $B89A: 21 BF 6F
    JR L_B8A2                                  ; $B89D: 18 03

; VERIFIED: Jump to token control handler A (0..13) from the word table at TokenControlTable.
DispatchTokenControl:
    LD HL,TokenControlTable                    ; $B89F: 21 A3 6F
L_B8A2:
    LD D,$00                                   ; $B8A2: 16 00
    ADD A,A                                    ; $B8A4: 87  two bytes per handler address
    LD E,A                                     ; $B8A5: 5F
    ADD HL,DE                                  ; $B8A6: 19
    LD E,(HL)                                  ; $B8A7: 5E
    INC HL                                     ; $B8A8: 23
    LD D,(HL)                                  ; $B8A9: 56
    EX DE,HL                                   ; $B8AA: EB
    JP (HL)                                    ; $B8AB: E9  jump to the handler

; ============================================================================
; Text control-code handlers and the system data screen
; Handlers reached through TokenControlTable (TokenControlTable) and
; MessageControlTable (MessageControlTable), then the "DATA ON" screen.
; ============================================================================

; VERIFIED: Message control 25: print message 216 (an empty message) and wait 36 frames.
; Not used by any message in the tables.
PrintEmptyMessageAndWait:
    LD A,$D8                                   ; $B8AC: 3E D8  message 216: ""
    CALL PrintMessage                          ; $B8AE: CD D7 BA
    JP Wait36Frames                            ; $B8B1: C3 AF B0

; VERIFIED: Token control 7: "Cash:" + PrintCash + " Cr" and a new line.
; Evidence: simulator prints "Cash:   100.0 Cr" for JAMESON.
PrintCashLine:
    LD A,$C5                                   ; $B8B4: 3E C5  token: "CASH"
    CALL PrintTokenColon                       ; $B8B6: CD E8 AF
    CALL PrintCash                             ; $B8B9: CD A8 B7  cash with one decimal place
    LD A,$E2                                   ; $B8BC: 3E E2  token $E2: " CR"
    JR L_B8DA                                  ; $B8BE: 18 1A  shared tail: token, then a new line

; VERIFIED: Token control 4 / message control 4: print the commander name (the
; zero-terminated token string at ActiveCommanderRecord).
; Evidence: simulator prints "Jameson".
PrintCommanderName:
    LD HL,ActiveCommanderRecord                ; $B8C0: 21 16 A8  the name is the first field of the record
    JR L_B90A                                  ; $B8C3: 18 45  print it as a token string

; VERIFIED: Token control 8 / message control 2: LetterCaseMode = 0 (title case: capital after
; any non-letter).  Evidence: simulator.
SetTitleCase:
    LD A,$00                                   ; $B8C5: 3E 00  mode 0: title case
    JR SetLetterCase                           ; $B8C7: 18 79

; VERIFIED: Token control 5: "Fuel: " + FuelLevel in tenths + " Light Years", new line.
; Evidence: simulator prints "Fuel: 7.0 Light Years".
PrintFuelLine:
    LD A,$69                                   ; $B8C9: 3E 69  token: "FUEL"
    CALL PrintTokenColon                       ; $B8CB: CD E8 AF
    CALL PrintInlineToken                      ; $B8CE: CD 99 BA
    defb $20                                   ; $B8D1: 20  PrintInlineToken argument: " "
    LD A,(FuelLevel)                           ; $B8D2: 3A 44 A8  tenths of a light year
    CALL PrintDecimalTenths                    ; $B8D5: CD 59 B7
    LD A,$C3                                   ; $B8D8: 3E C3  token: " LIGHT YEARS"
L_B8DA:
    JP PrintTokenNewLine                       ; $B8DA: C3 F7 AF

; VERIFIED: Token control 1: print CurrentGalaxy+1 in a 2-character field.
; Evidence: simulator prints " 1" and " 3" for galaxies 0 and 2.
PrintGalaxyNumber:
    LD A,$02                                   ; $B8DD: 3E 02
    LD (NumberFieldWidth),A                    ; $B8DF: 32 8E A8  field width 2
    LD A,(CurrentGalaxy)                       ; $B8E2: 3A 27 A8  galaxies 0..7 shown as 1..8
    INC A                                      ; $B8E5: 3C
    JP PrintDecimalA                           ; $B8E6: C3 5C B7

; VERIFIED: Token control 11 / message control 16: copy the 6 galaxy seed bytes GalaxySeeds
; to GeneratorSeeds, generate the system name (GenerateSystemName into GeneratedSystemName) and print it.
; The galaxy seeds are where LoadGalaxySeedsToGenerator starts the galaxy's system list, so this
; is the name of the first system.  Used by the Thargoid invasion texts: token
; $0F "MAYDAY* ... INVADED*" and messages 10 and 224.
; Evidence: simulator prints "Tibedied"; decoded tokens/messages.
PrintGalaxyFirstSystemName:
    LD HL,GalaxySeeds                          ; $B8E9: 21 52 A8
    LD DE,GeneratorSeeds                       ; $B8EC: 11 15 AC
    LD BC,$0006                                ; $B8EF: 01 06 00  six galaxy seed bytes
    LDIR                                       ; $B8F2: ED B0
    CALL GenerateSystemName                    ; $B8F4: CD 6F AD  name of the system with the galaxy seeds
    LD HL,GeneratedSystemName                  ; $B8F7: 21 2E AC
    JR L_B90A                                  ; $B8FA: 18 0E

; VERIFIED: Token control 2: capitalise the next letter and print the name at CurrentSystemName.
; Evidence: token "{present-system} MARKET PRICES"; CurrentSystemName is rewritten at
; $D6CB during hyperspace arrival.
PrintPresentSystemName:
    CALL CapitaliseNextLetter                  ; $B8FC: CD 11 B9
    LD HL,CurrentSystemName                    ; $B8FF: 21 37 AC  name of the system the ship is in
    JR L_B90A                                  ; $B902: 18 06

; VERIFIED: Token control 3 / message control 3: capitalise the next letter and print the
; name at SelectedSystemName.  Evidence: "DATA ON ..." and "HYPERSPACE -- ..." tokens.
PrintSelectedSystemName:
    CALL CapitaliseNextLetter                  ; $B904: CD 11 B9
    LD HL,SelectedSystemName                   ; $B907: 21 40 AC  name of the selected (target) system
L_B90A:
    JP PrintTokenString                        ; $B90A: C3 62 B0  print the name

; VERIFIED: Message control 8: TextColumn = 4, then CapitaliseNextLetter.
SetColumn4Capital:
    CALL SetTextColumnInline                   ; $B90D: CD 0D B0
    defb $04                                   ; $B910: 04  SetTextColumnInline argument: text column 4

; VERIFIED: Message control 19: CapitaliseOnce = 1, so PrintCharacter capitalises one letter.
CapitaliseNextLetter:
    LD A,$01                                   ; $B911: 3E 01
    LD (CapitaliseOnce),A                      ; $B913: 32 93 A8  capitalise the next letter once

; VERIFIED: RET: unused control codes (token 0, 12, 13; message 0, 20, 26..28, 30, 31).
IgnoreTextControl:
    RET                                        ; $B916: C9

; VERIFIED: Message control 18: capitalise the next letter, then print 1..4 letter
; pairs chosen by NextDescriptionRandom from the pair table at RandomNamePairTable
; (MessagePairTable + 2); a '?' second letter is not printed.
; Evidence: simulator prints words such as "Atainso", "Noreet".
PrintRandomName:
    CALL CapitaliseNextLetter                  ; $B917: CD 11 B9
    CALL NextDescriptionRandom                 ; $B91A: CD 58 BC  random byte
    AND $03                                    ; $B91D: E6 03  1..4 letter pairs
L_B91F:
    PUSH AF                                    ; $B91F: F5
    CALL NextDescriptionRandom                 ; $B920: CD 58 BC
    AND $3E                                    ; $B923: E6 3E  even offset: pair 1..32
    LD HL,RandomNamePairTable                  ; $B925: 21 AB FB
    LD D,$00                                   ; $B928: 16 00
    LD E,A                                     ; $B92A: 5F
    ADD HL,DE                                  ; $B92B: 19
    PUSH HL                                    ; $B92C: E5
    CALL PrintPairCharacter                    ; $B92D: CD 8A B9  first letter of the pair
    POP HL                                     ; $B930: E1
    INC HL                                     ; $B931: 23
    CALL PrintPairCharacter                    ; $B932: CD 8A B9  second letter ('?' is skipped)
    POP AF                                     ; $B935: F1
    AND A                                      ; $B936: A7
    RET Z                                      ; $B937: C8  last pair printed
    DEC A                                      ; $B938: 3D
    JR L_B91F                                  ; $B939: 18 E4

; VERIFIED: Message control 13: LetterCaseMode = 2 (letters in lower case).
SetLowerCase:
    LD A,$02                                   ; $B93B: 3E 02  mode 2: lower case
    JR SetLetterCase                           ; $B93D: 18 03

; VERIFIED: Unreachable byte $C9 (a RET opcode) between SetLowerCase and SetCapitals: no
; word anywhere in the image (control tables, CALL/JP operands, data) and no
; JR/DJNZ target points at it, and the instruction before it is the
; unconditional JR of SetLowerCase, so nothing falls through.  Kept as a byte.
; Evidence: a simulator check in tools/check_routines.py scans the image; never
; executed in the runtime traces.
L_B93F:
    defb $C9                                                                              ; $B93F .

; VERIFIED: Token control 6 / message control 1: LetterCaseMode = 1 (capitals).
SetCapitals:
    LD A,$01                                   ; $B940: 3E 01  mode 1: capitals

; VERIFIED: Store A in the letter-case mode LetterCaseMode.
SetLetterCase:
    LD (LetterCaseMode),A                      ; $B942: 32 91 A8
    RET                                        ; $B945: C9

; VERIFIED: Message control 17: print the selected system name (SelectedSystemName) and "IAN";
; when its last letter is a vowel (VowelTable) that letter is first removed
; from the justified-line buffer.  Only correct inside justified text.
; Evidence: simulator in justified mode: Lave -> "Lavian", Diso -> "Disian".
PrintSelectedSystemAdjective:
    CALL CapitaliseNextLetter                  ; $B946: CD 11 B9
    LD HL,SelectedSystemName                   ; $B949: 21 40 AC
    CALL PrintTokenString                      ; $B94C: CD 62 B0  print the name; HL ends at its terminator
    DEC HL                                     ; $B94F: 2B  last letter of the name
    LD A,(HL)                                  ; $B950: 7E
    LD B,$05                                   ; $B951: 06 05  five vowels
    LD HL,VowelTable                           ; $B953: 21 72 B9
L_B956:
    CP (HL)                                    ; $B956: BE  is it a vowel?
    JR Z,L_B961                                ; $B957: 28 08
    INC HL                                     ; $B959: 23
    DJNZ L_B956                                ; $B95A: 10 FA
L_B95C:
    LD HL,AdjectiveSuffix                      ; $B95C: 21 6E B9  then "IAN"
    JR L_B90A                                  ; $B95F: 18 A9
L_B961:
    LD HL,JustifyLineLength                    ; $B961: 21 F9 BC  drop the vowel from the justified line buffer
    DEC (HL)                                   ; $B964: 35  one character fewer in the line
    LD HL,(JustifyWritePointer)                ; $B965: 2A F6 BC
    DEC HL                                     ; $B968: 2B
    LD (JustifyWritePointer),HL                ; $B969: 22 F6 BC  the next character overwrites the vowel
    JR L_B95C                                  ; $B96C: 18 EE

; VERIFIED: Zero-terminated token string "IAN" printed by PrintSelectedSystemAdjective.
AdjectiveSuffix:
    defm "IAN"
    defb $00                                                                              ; $B96E

; VERIFIED: The five vowels "AEIOU" searched by PrintSelectedSystemAdjective (B = 5).
VowelTable:
    defm "AEIOU"                                                                          ; $B972

; VERIFIED: Token control 10 / message control 5: MessageDecodeMode = 1 (message interpretation).
SelectMessageMode:
    LD A,$01                                   ; $B977: 3E 01  mode 1: decode message bytes
    JR SetMessageMode                          ; $B979: 18 02

; VERIFIED: Message control 6: MessageDecodeMode = 0 (message bytes go to PrintToken).
SelectTokenMode:
    LD A,$00                                   ; $B97B: 3E 00  mode 0: message bytes are tokens

; VERIFIED: Store A in the message interpretation mode MessageDecodeMode.
SetMessageMode:
    LD (MessageDecodeMode),A                   ; $B97D: 32 98 BA
    RET                                        ; $B980: C9

; VERIFIED: Message control 29: SetTextRow(6).
SetTextRow6:
    LD A,$06                                   ; $B981: 3E 06
    JR L_B987                                  ; $B983: 18 02

; VERIFIED: Message control 23: SetTextRow(10).
SetTextRow10:
    LD A,$0A                                   ; $B985: 3E 0A
L_B987:
    JP SetTextRow                              ; $B987: C3 19 B0

; VERIFIED: Print the character at (HL) unless it is '?'.
PrintPairCharacter:
    LD A,(HL)                                  ; $B98A: 7E
    CP $3F                                     ; $B98B: FE 3F  '?': one-letter pair
    RET Z                                      ; $B98D: C8
    JP PrintToken                              ; $B98E: C3 9D BA

; VERIFIED: Docked "data on system" key handler (JP from $A7E9): select the system
; (SnapCursorToNearestSystem), title "DATA ON <selected system>", then distance, economy,
; government (token $B1+SelectedSystemGovernment), tech level (SelectedSystemTechLevel+1), population (SelectedSystemPopulation
; tenths + " BILLION"), species, gross productivity (SelectedSystemProductivity) and average
; radius (PrintPlanetRadius), followed by the Thargoid invasion message 222 (when InvasionMissionState
; is nonzero and the selected system is the galaxy's first one, i.e. CompareWithGalaxySeeds
; finds SelectedSystemSeeds equal to the galaxy seeds; rows 19/20 coloured $03) or the planet
; description (PrintPlanetDescription).  Evidence: docked-system-data trace.
DisplaySystemData:
    CALL SnapCursorToNearestSystem             ; $B991: CD B3 AC  select the system nearest the cursor
    CALL BeginTitledScreen                     ; $B994: CD AB B4  blank framed screen, title rule
    LD DE,SystemDataAttributeLayout            ; $B997: 11 03 FC  attribute bars of this screen
    CALL ColourAttributeStrips                 ; $B99A: CD DF BB
    LD A,$A3                                   ; $B99D: 3E A3  token: "{caps}DATA ON {selected-system}{title-case}"
    CALL PrintScreenTitle                      ; $B99F: CD 57 B0
    LD A,$03                                   ; $B9A2: 3E 03  first data line at row 3
    CALL SetTextRow                            ; $B9A4: CD 19 B0
    CALL PrintSelectedSystemDistance           ; $B9A7: CD 5A AE  DISTANCE line (only when nonzero)
    CALL NewLine                               ; $B9AA: CD FA AF
    CALL PrintEconomy                          ; $B9AD: CD 65 BA  Economy line and a blank line
    LD A,$A2                                   ; $B9B0: 3E A2  token: "GOVERNMENT"
    CALL PrintTokenColon                       ; $B9B2: CD E8 AF
    LD A,$B1                                   ; $B9B5: 3E B1  token $B1+government
    LD B,A                                     ; $B9B7: 47
    LD A,(SelectedSystemGovernment)            ; $B9B8: 3A 4C AC
    ADD A,B                                    ; $B9BB: 80
    CALL PrintTokenBlankLine                   ; $B9BC: CD 5A BA  government name and a blank line
    LD A,$C4                                   ; $B9BF: 3E C4  token: "TECH.LEVEL"
    CALL PrintTokenColon                       ; $B9C1: CD E8 AF
    LD A,$03                                   ; $B9C4: 3E 03
    LD (NumberFieldWidth),A                    ; $B9C6: 32 8E A8  field width 3
    LD A,(SelectedSystemTechLevel)             ; $B9C9: 3A 4D AC
    INC A                                      ; $B9CC: 3C  tech level shown from 1
    CALL PrintDecimalA                         ; $B9CD: CD 5C B7
    CALL PrintBlankLine                        ; $B9D0: CD 5F BA
    LD A,$D7                                   ; $B9D3: 3E D7  message 215: "POPULATION"
    CALL PrintMessageColon                     ; $B9D5: CD E3 AF
    LD A,(SelectedSystemPopulation)            ; $B9D8: 3A 4E AC
    CALL PrintDecimalTenths                    ; $B9DB: CD 59 B7  population in tenths of a billion
    LD A,$C6                                   ; $B9DE: 3E C6  token $C6: " BILLION"
    CALL PrintTokenBlankLine                   ; $B9E0: CD 5A BA
    CALL PrintInlineToken                      ; $B9E3: CD 99 BA
    defb $28                                   ; $B9E6: 28  PrintInlineToken argument: "("
    CALL PrintSpecies                          ; $B9E7: CD 8A BA  species, printed as "(...S)"
    CALL PrintInlineToken                      ; $B9EA: CD 99 BA
    defb $53                                   ; $B9ED: 53  PrintInlineToken argument: "S"
    LD A,$29                                   ; $B9EE: 3E 29  token: ")"
    CALL PrintTokenBlankLine                   ; $B9F0: CD 5A BA
    LD A,$6F                                   ; $B9F3: 3E 6F  message 111: "GROSS {token-mode}PRODUCT{msg-mode}IVITY"
    CALL PrintMessageColon                     ; $B9F5: CD E3 AF
    LD HL,(SelectedSystemProductivity)         ; $B9F8: 2A 4F AC  gross productivity
    LD A,$05                                   ; $B9FB: 3E 05
    LD (NumberFieldWidth),A                    ; $B9FD: 32 8E A8  field width 5
    AND A                                      ; $BA00: A7  no decimal point
    CALL PrintDecimalHL                        ; $BA01: CD 60 B7
    CALL PrintInlineToken                      ; $BA04: CD 99 BA
    defb $20                                   ; $BA07: 20  PrintInlineToken argument: " "
    CALL PrintInlineToken                      ; $BA08: CD 99 BA
    defb $4D                                   ; $BA0B: 4D  PrintInlineToken argument: "M"
    LD A,$E2                                   ; $BA0C: 3E E2  token $E2: " CR", in capitals
    CALL PrintTokenInCapitals                  ; $BA0E: CD 49 B0
    CALL PrintBlankLine                        ; $BA11: CD 5F BA
    LD A,$FA                                   ; $BA14: 3E FA  token: "AVERAGE RADIUS"
    CALL PrintTokenColon                       ; $BA16: CD E8 AF
    CALL PrintPlanetRadius                     ; $BA19: CD 56 D0  average radius, 5 characters
    CALL PrintInlineToken                      ; $BA1C: CD 99 BA
    defb $20                                   ; $BA1F: 20  PrintInlineToken argument: " "
    LD A,$11                                   ; $BA20: 3E 11  unit index 17 prints "km"
    LD (CurrentCommodity),A                    ; $BA22: 32 30 AF
    CALL PrintCommodityUnit                    ; $BA25: CD 6F B0  unit "km"
    CALL PrintBlankLine                        ; $BA28: CD 5F BA
    LD A,(InvasionMissionState)                ; $BA2B: 3A 71 A8
    AND A                                      ; $BA2E: A7  InvasionMissionState zero: planet description
    JR Z,PrintPlanetDescription                ; $BA2F: 28 18
    LD HL,SelectedSystemSeeds                  ; $BA31: 21 0F AC
    CALL CompareWithGalaxySeeds                ; $BA34: CD 6C D0  carry clear: it is the galaxy's first system
    JR C,PrintPlanetDescription                ; $BA37: 38 10  another system: planet description
    LD A,$03                                   ; $BA39: 3E 03  attribute $03 for text rows 19 and 20
    LD HL,$5A61                                ; $BA3B: 21 61 5A  attribute row 19, column 1
    CALL FillAttributeRow30                    ; $BA3E: CD CB BB
    CALL FillAttributeRow30                    ; $BA41: CD CB BB
    LD A,$DE                                   ; $BA44: 3E DE  message 222: "{lower}{justify}{cap-next}{caps}{selected-system} IS RESI..."
    JP PrintMessage                            ; $BA46: C3 D7 BA

; VERIFIED: Seed NextDescriptionRandom from the selected system seeds (SelectedSystemSeed1 -> DescriptionSeed1,
; SelectedSystemSeed2 -> DescriptionSeed2) and print message 5, the justified planet description.
PrintPlanetDescription:
    LD HL,(SelectedSystemSeed1)                ; $BA49: 2A 11 AC
    LD (DescriptionSeed1),HL                   ; $BA4C: 22 21 AC  description generator seeded per system
    LD HL,(SelectedSystemSeed2)                ; $BA4F: 2A 13 AC
    LD (DescriptionSeed2),HL                   ; $BA52: 22 23 AC
    LD A,$05                                   ; $BA55: 3E 05  message 5: "{lower}{justify}{cap-next}{{selected-system}|THE PLANET {..."
    JP PrintMessage                            ; $BA57: C3 D7 BA

; VERIFIED: PrintTokenNewLine(A), then one more NewLine.
PrintTokenBlankLine:
    CALL PrintTokenNewLine                     ; $BA5A: CD F7 AF
    JR L_BA62                                  ; $BA5D: 18 03

; VERIFIED: Two NewLines (end the current line and leave a blank one).
PrintBlankLine:
    CALL NewLine                               ; $BA5F: CD FA AF
L_BA62:
    JP NewLine                                 ; $BA62: C3 FA AF

; VERIFIED: Print "Economy:", an adjective and "Industrial"/"Agricultural" (token
; $A8 + SelectedSystemEconomy/4), then a new line and a blank line.  Economy 4 prints
; "Mainly"; every other value prints "Rich": the adjective comes from the inline
; token $AA, which replaces A, so the SUB 5 result is discarded.
; Evidence: simulator for economies 0..7.
; INFERRED: the intended code selected RICH/AVERAGE/POOR/MAINLY by A+$AA.
PrintEconomy:
    LD A,$70                                   ; $BA65: 3E 70  message 112: "ECONOMY"
    CALL PrintMessageColon                     ; $BA67: CD E3 AF
    LD A,(SelectedSystemEconomy)               ; $BA6A: 3A 4B AC  economy 0..7
    CP $04                                     ; $BA6D: FE 04
    JR Z,L_BA84                                ; $BA6F: 28 13  4: "MAINLY"
    JR C,L_BA75                                ; $BA71: 38 02  0..3: the same "RICH" path
    SUB $05                                    ; $BA73: D6 05  5..7: result unused (A is replaced)
L_BA75:
    CALL PrintInlineToken                      ; $BA75: CD 99 BA  always "RICH ": the inline token replaces A
    defb $AA                                   ; $BA78: AA  PrintInlineToken argument: "RICH "

; VERIFIED: PrintEconomy, second word: token $A8 INDUSTRIAL for economies 0..3 or $A9
; AGRICULTURAL for 4..7, then a new line and a blank line (PrintTokenBlankLine).
L_BA79:
    LD A,(SelectedSystemEconomy)               ; $BA79: 3A 4B AC
    SRL A                                      ; $BA7C: CB 3F  economy / 4: 0..3 industrial, 4..7 agricultural
    SRL A                                      ; $BA7E: CB 3F
    ADD A,$A8                                  ; $BA80: C6 A8  $A8 INDUSTRIAL, $A9 AGRICULTURAL
    JR PrintTokenBlankLine                     ; $BA82: 18 D6  type, new line and blank line
L_BA84:
    CALL PrintInlineToken                      ; $BA84: CD 99 BA
    defb $AD                                   ; $BA87: AD  PrintInlineToken argument: "MAINLY "
    JR L_BA79                                  ; $BA88: 18 EF  then the economy type

; VERIFIED: Print the species: "Human Colonial" (token $BC) when the low byte of the
; seed word SelectedSystemSeed2 is below $80, otherwise PrintAlienSpecies builds an alien species.
PrintSpecies:
    LD HL,(SelectedSystemSeed2)                ; $BA8A: 2A 13 AC
    LD A,L                                     ; $BA8D: 7D
    CP $80                                     ; $BA8E: FE 80  low seed byte $80 or more: alien species
    JP NC,PrintAlienSpecies                    ; $BA90: D2 0F D0
    LD A,$BC                                   ; $BA93: 3E BC  token $BC: "HUMAN COLONIAL"
    JP L_D053                                  ; $BA95: C3 53 D0

; VERIFIED: Message interpretation mode: nonzero (initially 1) makes PrintMessageByte
; decode message bytes itself; zero hands every byte to PrintToken.
; Message control 5 sets it to 1 (SelectMessageMode); message control 6 clears it (SelectTokenMode).
MessageDecodeMode:
    defb $01                                                                              ; $BA98 .

; VERIFIED: Print the byte that follows the CALL as a PrintToken code, then return
; after that byte.  The caller's return address is used as the data pointer:
;     CALL PrintInlineToken
;     defb code
; Every CALL site in the source is followed by its inline argument byte.
PrintInlineToken:
    POP HL                                     ; $BA99: E1
    LD A,(HL)                                  ; $BA9A: 7E
    INC HL                                     ; $BA9B: 23
    PUSH HL                                    ; $BA9C: E5

; VERIFIED: Print text code A (recursive token interpreter):
;   $00..$0D  control code: jump through TokenControlTable
;   $0E..$1F  dictionary token A+$72
;   $20..$5F  character, via PrintCharacter
;   $60..$7F  dictionary token A
;   $80..$9F  two-letter token A-$80, via PrintPairToken
;   $A0..$FF  dictionary token A-$A0
; Dictionary tokens are themselves strings of PrintToken codes.
PrintToken:
    CP $0E                                     ; $BA9D: FE 0E
    JP C,DispatchTokenControl                  ; $BA9F: DA 9F B8  codes 0..13: control handlers
    CP $20                                     ; $BAA2: FE 20
    JP C,L_BAB9                                ; $BAA4: DA B9 BA  14..31: dictionary tokens $80..$91
    CP $60                                     ; $BAA7: FE 60
    JP C,PrintCharacter                        ; $BAA9: DA 10 BB  32..95: characters
    CP $80                                     ; $BAAC: FE 80
    JR C,PrintDictionaryToken                  ; $BAAE: 38 0B  96..127: dictionary tokens 96..127
    CP $A0                                     ; $BAB0: FE A0
    JP C,PrintPairToken                        ; $BAB2: DA 13 BC  128..159: two-letter tokens
    SUB $A0                                    ; $BAB5: D6 A0  160..255: dictionary tokens 0..95
    JR PrintDictionaryToken                    ; $BAB7: 18 02

; VERIFIED: PrintToken codes $0E..$1F select dictionary tokens $80..$91.
L_BAB9:
    ADD A,$72                                  ; $BAB9: C6 72

; VERIFIED: Print dictionary token A: skip A zero-terminated strings of
; TextTokenDictionary with CPIR, then print each byte through PrintToken.
PrintDictionaryToken:
    LD HL,TextTokenDictionary                  ; $BABB: 21 9D 9A
    LD D,A                                     ; $BABE: 57
    INC D                                      ; $BABF: 14
L_BAC0:
    DEC D                                      ; $BAC0: 15
    JP Z,L_BACC                                ; $BAC1: CA CC BA  reached token A
    LD BC,$FFFF                                ; $BAC4: 01 FF FF
    XOR A                                      ; $BAC7: AF
    CPIR                                       ; $BAC8: ED B1  skip one zero-terminated token
    JR L_BAC0                                  ; $BACA: 18 F4
L_BACC:
    LD A,(HL)                                  ; $BACC: 7E
    AND A                                      ; $BACD: A7
    RET Z                                      ; $BACE: C8  zero: end of the token
    PUSH HL                                    ; $BACF: E5  tokens nest: HL is saved
    CALL PrintToken                            ; $BAD0: CD 9D BA
    POP HL                                     ; $BAD3: E1
    INC HL                                     ; $BAD4: 23
    JR L_BACC                                  ; $BAD5: 18 F5

; VERIFIED: Print message A (1-based) from the message table that starts at $92B7.
; Skip A-1 zero-terminated strings, then print each byte through
; PrintMessageByte.  Messages may nest: bytes $81..$D6 print another message.
; PrintMessage itself does not change MessageDecodeMode.
PrintMessage:
    LD HL,EncodedTextData                      ; $BAD7: 21 B7 92
    LD D,A                                     ; $BADA: 57
L_BADB:
    DEC D                                      ; $BADB: 15
    JR Z,L_BB05                                ; $BADC: 28 27  reached message A
    LD BC,$FFFF                                ; $BADE: 01 FF FF
    XOR A                                      ; $BAE1: AF
    CPIR                                       ; $BAE2: ED B1  skip one zero-terminated message
    JP L_BADB                                  ; $BAE4: C3 DB BA

; VERIFIED: Print one message byte in A.  While MessageDecodeMode is zero the byte is passed to
; PrintToken instead.  Otherwise:
;   $00..$1F  control code: jump through MessageControlTable
;   $20..$5A  character, via PrintCharacter
;   $5B..$80  random choice of five messages, via PrintRandomMessage
;   $81..$D6  nested message A, via PrintMessage
;   $D7..$FF  two-letter token from the $FBA9 table, via PrintMessagePairToken
PrintMessageByte:
    LD B,A                                     ; $BAE7: 47
    LD A,(MessageDecodeMode)                   ; $BAE8: 3A 98 BA
    CP $00                                     ; $BAEB: FE 00
    LD A,B                                     ; $BAED: 78
    JR Z,PrintToken                            ; $BAEE: 28 AD  mode 0: pass the byte to PrintToken
    CP $20                                     ; $BAF0: FE 20
    JP C,DispatchMessageControl                ; $BAF2: DA 9A B8  codes 0..31: control handlers
    CP $5B                                     ; $BAF5: FE 5B
    JR C,PrintCharacter                        ; $BAF7: 38 17  $20..$5A: characters
    CP $81                                     ; $BAF9: FE 81
    JP C,PrintRandomMessage                    ; $BAFB: DA 2B BC  $5B..$80: random choice of five messages
    CP $D7                                     ; $BAFE: FE D7
    JR C,PrintMessage                          ; $BB00: 38 D5  $81..$D6: nested message
    JP PrintMessagePairToken                   ; $BB02: C3 0C BC  $D7..$FF: two-letter token

; VERIFIED: Message loop of PrintMessage: print each byte at HL through PrintMessageByte up to
; the zero terminator.  Nested messages re-enter PrintMessage and return here.
L_BB05:
    LD A,(HL)                                  ; $BB05: 7E  print the message bytes up to the zero
    AND A                                      ; $BB06: A7
    RET Z                                      ; $BB07: C8
    PUSH HL                                    ; $BB08: E5
    CALL PrintMessageByte                      ; $BB09: CD E7 BA  messages nest: HL is saved
    POP HL                                     ; $BB0C: E1
    INC HL                                     ; $BB0D: 23
    JR L_BB05                                  ; $BB0E: 18 F5

; VERIFIED: Print character A ($20..$5F) with case conversion of the letters A..Z:
;   LetterCaseMode = 1   letters are printed unchanged (capitals);
;   LetterCaseMode = 2   letters are printed in lower case (+$20);
;   otherwise    title case: a letter is capitalised when CapitaliseNextFlag = 1,
;                which every non-letter sets, and lower case otherwise.
; CapitaliseOnce nonzero capitalises one letter in modes 0 and 2, then clears.
; If TextRedirectFlag = 1 the character goes to the justified-text buffer (BufferJustifiedCharacter);
; otherwise the screen path continues in PutCharacter (column advance and glyph).
PrintCharacter:
    CP $41                                     ; $BB10: FE 41
    JR C,L_BB49                                ; $BB12: 38 35  below 'A': not a letter
    CP $5B                                     ; $BB14: FE 5B
    JR NC,L_BB49                               ; $BB16: 30 31  above 'Z': not a letter
    PUSH AF                                    ; $BB18: F5
    LD A,(LetterCaseMode)                      ; $BB19: 3A 91 A8
    CP $01                                     ; $BB1C: FE 01
    JR Z,L_BB4F                                ; $BB1E: 28 2F  mode 1: letters unchanged (capitals)
    LD A,(CapitaliseOnce)                      ; $BB20: 3A 93 A8
    AND A                                      ; $BB23: A7
    JR Z,L_BB2F                                ; $BB24: 28 09  no one-shot capital pending
    XOR A                                      ; $BB26: AF
    LD (CapitaliseOnce),A                      ; $BB27: 32 93 A8  one-shot capital used up
    LD (CapitaliseNextFlag),A                  ; $BB2A: 32 92 A8  and the title-case request too
    JR L_BB4F                                  ; $BB2D: 18 20
L_BB2F:
    LD A,(CapitaliseNextFlag)                  ; $BB2F: 3A 92 A8
    CP $01                                     ; $BB32: FE 01
    JR NZ,L_BB43                               ; $BB34: 20 0D  no capital requested: lower case
    XOR A                                      ; $BB36: AF
    LD (CapitaliseNextFlag),A                  ; $BB37: 32 92 A8  title-case capital used up
    LD A,(LetterCaseMode)                      ; $BB3A: 3A 91 A8
    CP $02                                     ; $BB3D: FE 02
    JR Z,L_BB43                                ; $BB3F: 28 02  mode 2: lower case even after a non-letter
    JR L_BB4F                                  ; $BB41: 18 0C
L_BB43:
    POP AF                                     ; $BB43: F1
    ADD A,$20                                  ; $BB44: C6 20  to lower case
    PUSH AF                                    ; $BB46: F5
    JR L_BB4F                                  ; $BB47: 18 06
L_BB49:
    PUSH AF                                    ; $BB49: F5
    LD A,$01                                   ; $BB4A: 3E 01
    LD (CapitaliseNextFlag),A                  ; $BB4C: 32 92 A8  a non-letter requests a capital next
L_BB4F:
    LD A,(TextRedirectFlag)                    ; $BB4F: 3A 94 A8
    CP $01                                     ; $BB52: FE 01
    JP Z,BufferJustifiedCharacter              ; $BB54: CA FC BC  redirected into the justified-line buffer
    POP AF                                     ; $BB57: F1

; VERIFIED: Advance TextColumn (32 wraps to column 1 of the next row) and draw
; character A at the new cursor cell (falls into GetCharacterBitmap).
; Used directly by the justified-line printer to bypass case conversion.
PutCharacter:
    PUSH AF                                    ; $BB58: F5
    LD HL,TextColumn                           ; $BB59: 21 0D A8
    INC (HL)                                   ; $BB5C: 34  the cursor advances before drawing
    LD A,(HL)                                  ; $BB5D: 7E
    CP $20                                     ; $BB5E: FE 20  past column 31?
    JR C,L_BB68                                ; $BB60: 38 06
    LD A,$01                                   ; $BB62: 3E 01  wrap to column 1
    LD (HL),A                                  ; $BB64: 77
    CALL NextTextRow                           ; $BB65: CD 02 B0  of the next row
L_BB68:
    POP AF                                     ; $BB68: F1

; VERIFIED: FontRuntime + (A-FontFirstCode)*8 selects a relocated glyph.
GetCharacterBitmap:
    LD HL,FontRuntime                          ; $BB69: 21 70 5D
    SUB FontFirstCode                          ; $BB6C: D6 20
    LD C,A                                     ; $BB6E: 4F
    LD B,$00                                   ; $BB6F: 06 00
    SLA C                                      ; $BB71: CB 21  BC = 8 * glyph index
    RL B                                       ; $BB73: CB 10
    SLA C                                      ; $BB75: CB 21
    RL B                                       ; $BB77: CB 10
    SLA C                                      ; $BB79: CB 21
    RL B                                       ; $BB7B: CB 10
    ADD HL,BC                                  ; $BB7D: 09
    PUSH HL                                    ; $BB7E: E5

; VERIFIED: Self-modified LD HL,$4000: bit 7 of the high operand byte (L_BB81) is set by
; $7260/$7272/$D468 and cleared by $727A/$D483, so text is drawn into the
; view bitmap buffer at $C000 instead of the screen.
LoadCharacterScreenBase:
defc L_BB81 = LoadCharacterScreenBase + 2 ; byte inside instruction at $BB7F
    LD HL,$4000                                ; $BB7F: 21 00 40  self-modified high byte: $40 screen or $C0 view buffer
    LD A,(TextRow)                             ; $BB82: 3A 0E A8
    CP $10                                     ; $BB85: FE 10  rows 16..23: bottom third
    JP NC,L_BB93                               ; $BB87: D2 93 BB
    CP $08                                     ; $BB8A: FE 08  rows 8..15: middle third
    JP NC,L_BB9D                               ; $BB8C: D2 9D BB
    LD B,A                                     ; $BB8F: 47
    JP L_BBA4                                  ; $BB90: C3 A4 BB
L_BB93:
    SUB $10                                    ; $BB93: D6 10
    LD B,A                                     ; $BB95: 47
    LD DE,$1000                                ; $BB96: 11 00 10  bottom third starts $1000 later
    ADD HL,DE                                  ; $BB99: 19
    JP L_BBA4                                  ; $BB9A: C3 A4 BB
L_BB9D:
    SUB $08                                    ; $BB9D: D6 08
    LD B,A                                     ; $BB9F: 47
    LD DE,$0800                                ; $BBA0: 11 00 08  middle third starts $0800 later
    ADD HL,DE                                  ; $BBA3: 19
L_BBA4:
    LD C,$00                                   ; $BBA4: 0E 00
    SRL B                                      ; $BBA6: CB 38  BC = 32 * row within the third
    RR C                                       ; $BBA8: CB 19
    SRL B                                      ; $BBAA: CB 38
    RR C                                       ; $BBAC: CB 19
    SRL B                                      ; $BBAE: CB 38
    RR C                                       ; $BBB0: CB 19
    ADD HL,BC                                  ; $BBB2: 09
    LD B,$00                                   ; $BBB3: 06 00
    LD A,(TextColumn)                          ; $BBB5: 3A 0D A8
    LD C,A                                     ; $BBB8: 4F
    ADD HL,BC                                  ; $BBB9: 09  + column
    POP DE                                     ; $BBBA: D1
    LD B,FontGlyphHeight                       ; $BBBB: 06 08

; VERIFIED: XOR one font byte into a screen row, then advance glyph and screen pointers.
DrawCharacterRow:
    LD A,(DE)                                  ; $BBBD: 1A
    LD C,(HL)                                  ; $BBBE: 4E

; VERIFIED: Self-modified character-blending instruction, not a separate mode variable.
; $A9 is XOR C (combine glyph with old pixels); $00 is NOP (overwrite with glyph).
CharacterBlendOpcode:
    XOR C                                      ; $BBBF: A9
    LD (HL),A                                  ; $BBC0: 77
    INC H                                      ; $BBC1: 24  next pixel line of the cell (+$100)
    INC DE                                     ; $BBC2: 13
    DJNZ DrawCharacterRow                      ; $BBC3: 10 F8

; Eight character rows have been drawn.
CharacterDrawn:
    RET                                        ; $BBC5: C9

; ============================================================================
; Attribute strips, screen clear/frame and justified text
; Attribute fills, full-width rules, the clear-screen frame and the
; word-wrapping, fully justified output used by planet descriptions.
; ============================================================================

; VERIFIED: Set attributes of text row 21, columns 1..30, to $05; HL ends at $5AC1.
; Evidence: simulator (30 cells $5AA1..$5ABE).
ColourPromptRow:
    LD HL,$5AA1                                ; $BBC6: 21 A1 5A  text row 21, column 1
    LD A,$05                                   ; $BBC9: 3E 05  attribute $05

; VERIFIED: Fill 30 bytes at HL with A, then HL += 2 (column 1 of the next row).
FillAttributeRow30:
    LD B,$1E                                   ; $BBCB: 06 1E
    CALL FillBytes                             ; $BBCD: CD DA BB
    INC HL                                     ; $BBD0: 23  skip columns 31 and 0: next row, column 1
    INC HL                                     ; $BBD1: 23
    RET                                        ; $BBD2: C9

; VERIFIED: Message control 11: full-width line at pixel row 19 ($4340), under the title
; row.  Evidence: simulator (32 bytes $FF at $4340).
DrawTitleUnderline:
    LD HL,$4340                                ; $BBD3: 21 40 43  pixel row 19

; VERIFIED: Write 32 bytes of $FF from HL (one full-width pixel line).
DrawFullWidthLine:
    LD A,$FF                                   ; $BBD6: 3E FF  $FF: all 8 pixels set
    LD B,$20                                   ; $BBD8: 06 20  32 bytes: the full width

; VERIFIED: Write A to B bytes from HL; HL ends after the last byte.
FillBytes:
    LD (HL),A                                  ; $BBDA: 77
    INC HL                                     ; $BBDB: 23
    DJNZ FillBytes                             ; $BBDC: 10 FC
    RET                                        ; $BBDE: C9

; VERIFIED: Colour attribute strips from the list at DE, starting at $5821 (row 1,
; column 1).  Each byte: bits 7..3 = number of cells set to $05 from the strip
; start, bits 2..0 = rows to move down for the next strip; 0 rows ends the
; list.  Finally cells $5822 and $5823 are set to $07.
; Evidence: simulator with BuyScreenAttributeStrips and TradeScreenAttributeStrip.
ColourAttributeStrips:
    LD HL,$5821                                ; $BBDF: 21 21 58  text row 1, column 1
L_BBE2:
    LD A,(DE)                                  ; $BBE2: 1A  next strip byte
    INC DE                                     ; $BBE3: 13
    PUSH AF                                    ; $BBE4: F5
    AND $F8                                    ; $BBE5: E6 F8
    RRCA                                       ; $BBE7: 0F  cell count = bits 7..3
    RRCA                                       ; $BBE8: 0F
    RRCA                                       ; $BBE9: 0F
    LD B,A                                     ; $BBEA: 47
    PUSH HL                                    ; $BBEB: E5
    LD A,$05                                   ; $BBEC: 3E 05  strip attribute $05
    CALL FillBytes                             ; $BBEE: CD DA BB
    POP HL                                     ; $BBF1: E1
    POP AF                                     ; $BBF2: F1
    AND $07                                    ; $BBF3: E6 07  bits 2..0: rows down to the next strip
    JR Z,L_BC03                                ; $BBF5: 28 0C  0: end of the list
    LD B,A                                     ; $BBF7: 47
L_BBF8:
    LD A,$20                                   ; $BBF8: 3E 20  down one attribute row (32 bytes)
    ADD A,L                                    ; $BBFA: 85
    LD L,A                                     ; $BBFB: 6F
    JR NC,L_BBFF                               ; $BBFC: 30 01
    INC H                                      ; $BBFE: 24
L_BBFF:
    DJNZ L_BBF8                                ; $BBFF: 10 F7
    JR L_BBE2                                  ; $BC01: 18 DF
L_BC03:
    LD HL,$5822                                ; $BC03: 21 22 58  two cells at row 1, columns 2..3
    LD A,$07                                   ; $BC06: 3E 07
    LD (HL),A                                  ; $BC08: 77  cells 2 and 3 of row 1 set to $07
    INC HL                                     ; $BC09: 23
    LD (HL),A                                  ; $BC0A: 77
    RET                                        ; $BC0B: C9

; VERIFIED: Print two-letter message token A ($D7..$FF) from the pair table at MessagePairTable.
; Shares the pair printer with PrintPairToken.
PrintMessagePairToken:
    SUB $D7                                    ; $BC0C: D6 D7  pair index
    LD HL,MessagePairTable                     ; $BC0E: 21 A9 FB
    JR L_BC18                                  ; $BC11: 18 05

; VERIFIED: Print two-letter token A ($80..$9F) from the pair table at TokenPairTable.
; A second character of '?' is not printed.
PrintPairToken:
    SUB $80                                    ; $BC13: D6 80
    LD HL,TokenPairTable                       ; $BC15: 21 C3 FB
L_BC18:
    ADD A,A                                    ; $BC18: 87  two bytes per pair
    LD D,$00                                   ; $BC19: 16 00
    LD E,A                                     ; $BC1B: 5F
    ADD HL,DE                                  ; $BC1C: 19
    LD A,(HL)                                  ; $BC1D: 7E
    PUSH HL                                    ; $BC1E: E5
    CALL PrintCharacter                        ; $BC1F: CD 10 BB
    POP HL                                     ; $BC22: E1
    INC HL                                     ; $BC23: 23
    LD A,(HL)                                  ; $BC24: 7E
    CP $3F                                     ; $BC25: FE 3F  '?': one-letter pair
    RET Z                                      ; $BC27: C8
    JP PrintCharacter                          ; $BC28: C3 10 BB

; VERIFIED: Message codes $5B..$80: read a base message number from the table at
; RandomMessageTable, add 0..4 chosen by NextDescriptionRandom (thresholds $33, $66,
; $99, $CC) and print that message.  Used by the planet descriptions.
PrintRandomMessage:
    LD D,$00                                   ; $BC2B: 16 00
    SUB $5B                                    ; $BC2D: D6 5B  index into RandomMessageTable
    LD E,A                                     ; $BC2F: 5F
    LD HL,RandomMessageTable                   ; $BC30: 21 76 BC
    ADD HL,DE                                  ; $BC33: 19
    LD A,(HL)                                  ; $BC34: 7E
    PUSH AF                                    ; $BC35: F5
    CALL NextDescriptionRandom                 ; $BC36: CD 58 BC
    LD B,$00                                   ; $BC39: 06 00
    CP $33                                     ; $BC3B: FE 33  random below $33: choice 0
    JP C,L_BC53                                ; $BC3D: DA 53 BC
    CP $66                                     ; $BC40: FE 66  below $66: choice 1
    JP C,L_BC52                                ; $BC42: DA 52 BC
    CP $99                                     ; $BC45: FE 99  below $99: choice 2
    JP C,L_BC51                                ; $BC47: DA 51 BC
    CP $CC                                     ; $BC4A: FE CC  below $CC: choice 3, otherwise 4
    JP C,L_BC50                                ; $BC4C: DA 50 BC
    INC B                                      ; $BC4F: 04
L_BC50:
    INC B                                      ; $BC50: 04
L_BC51:
    INC B                                      ; $BC51: 04
L_BC52:
    INC B                                      ; $BC52: 04
L_BC53:
    POP AF                                     ; $BC53: F1
    ADD A,B                                    ; $BC54: 80  base message + choice
    JP PrintMessage                            ; $BC55: C3 D7 BA

; VERIFIED: Advance the four-byte description generator and return its new high byte
; in A.  With w1 = word at DescriptionSeed1 and w2 = word at DescriptionSeed2: shift the low byte
; of w1 left (carry c), then w1' = w2 + w1 + c and w2' = w1 (shifted).
; PrintPlanetDescription seeds both words from the selected system seeds (SelectedSystemSeed1/SelectedSystemSeed2)
; before a planet description is printed.
NextDescriptionRandom:
    LD HL,(DescriptionSeed1)                   ; $BC58: 2A 21 AC
    SLA L                                      ; $BC5B: CB 25  shift the low byte of w1 (carry out)
    EX DE,HL                                   ; $BC5D: EB
    LD HL,(DescriptionSeed2)                   ; $BC5E: 2A 23 AC
    ADC HL,DE                                  ; $BC61: ED 5A  w2 + w1 + carry
    LD A,H                                     ; $BC63: 7C  result: its high byte
    LD (DescriptionSeed1),HL                   ; $BC64: 22 21 AC
    EX DE,HL                                   ; $BC67: EB
    LD (DescriptionSeed2),HL                   ; $BC68: 22 23 AC  w2 := old w1 (shifted)
    RET                                        ; $BC6B: C9

; VERIFIED: C = (A AND $80) OR ((A << 1) AND $7E) OR carry-in: a sign-magnitude byte with
; its magnitude doubled.  Also A bit 0 := A bit 6, carry out = old bit 0.
; Evidence: simulator for all 256 values and both carry inputs (a simulator
; check in tools/check_routines.py).
DoubleSignMagnitude:
    LD C,A                                     ; $BC6C: 4F
    RL C                                       ; $BC6D: CB 11
    RRA                                        ; $BC6F: 1F
    RL C                                       ; $BC70: CB 11
    RLA                                        ; $BC72: 17
    RR C                                       ; $BC73: CB 19
    RET                                        ; $BC75: C9

; VERIFIED: Base message numbers for the random message codes $5B..$80 (38 bytes);
; PrintRandomMessage adds 0..4 to the selected entry.
RandomMessageTable:
    defb $10,$15,$1A,$1F,$9B,$A0,$2E,$A5                                                  ; $BC76 ........
    defb $24,$29,$3D,$33,$38,$AA,$42,$47                                                  ; $BC7E $)=38.BG
    defb $4C,$51,$56,$8C,$60,$65,$87,$82                                                  ; $BC86 LQV.`e..
    defb $5B,$6A,$B4,$B9,$BE,$E1,$E6,$EB                                                  ; $BC8E [j......
    defb $F0,$F5,$FA,$73,$78,$7D                                                          ; $BC96 ...sx}

; VERIFIED: Stack pointer saved while ClearScreenAndFrame fills the screen by PUSH.
ClearScreenSavedSP:
    defw $0000                                                                            ; $BC9C

; VERIFIED: Message control 9: with interrupts off and SP at $5B00, PUSH $0707 into all
; 768 attribute bytes and $0000 into the 6144 bitmap bytes, then fall into
; DrawScreenFrame.  Evidence: simulator (attributes 7, frame only).
ClearScreenAndFrame:
    DI                                         ; $BC9E: F3  no interrupts while SP points into the screen
    LD (ClearScreenSavedSP),SP                 ; $BC9F: ED 73 9C BC  save SP: the screen is filled by PUSH
    LD SP,$5B00                                ; $BCA3: 31 00 5B  SP = end of the attribute area
    LD DE,$0707                                ; $BCA6: 11 07 07  attribute $07 (white ink, black paper)
    LD C,$18                                   ; $BCA9: 0E 18  24 x 16 pushes = 768 attribute bytes
L_BCAB:
    LD B,$10                                   ; $BCAB: 06 10
L_BCAD:
    PUSH DE                                    ; $BCAD: D5
    DJNZ L_BCAD                                ; $BCAE: 10 FD
    DEC C                                      ; $BCB0: 0D
    JP NZ,L_BCAB                               ; $BCB1: C2 AB BC
    LD DE,$0000                                ; $BCB4: 11 00 00  bitmap: all pixels off
    LD C,$C0                                   ; $BCB7: 0E C0  192 x 16 pushes = 6144 bitmap bytes
L_BCB9:
    LD B,$10                                   ; $BCB9: 06 10
L_BCBB:
    PUSH DE                                    ; $BCBB: D5
    DJNZ L_BCBB                                ; $BCBC: 10 FD
    DEC C                                      ; $BCBE: 0D
    JP NZ,L_BCB9                               ; $BCBF: C2 B9 BC
    LD SP,(ClearScreenSavedSP)                 ; $BCC2: ED 7B 9C BC  restore the stack pointer
    EI                                         ; $BCC6: FB

; VERIFIED: Draw a one-pixel frame around the whole screen (left and right pixel
; columns, top and bottom lines) and set TextColumn = 0, TextRow = 1.
DrawScreenFrame:
    LD B,$C0                                   ; $BCC7: 06 C0  192 pixel lines
    LD DE,$0020                                ; $BCC9: 11 20 00
    LD HL,$4000                                ; $BCCC: 21 00 40  left byte column, from the top line
L_BCCF:
    LD A,(HL)                                  ; $BCCF: 7E
    OR $80                                     ; $BCD0: F6 80  leftmost pixel
    LD (HL),A                                  ; $BCD2: 77
    ADD HL,DE                                  ; $BCD3: 19  +32 bytes: column 0 of all 192 lines, in memory order
    DJNZ L_BCCF                                ; $BCD4: 10 F9
    LD B,$C0                                   ; $BCD6: 06 C0
    LD HL,$401F                                ; $BCD8: 21 1F 40  right-hand byte column
L_BCDB:
    LD A,(HL)                                  ; $BCDB: 7E
    OR $01                                     ; $BCDC: F6 01  rightmost pixel
    LD (HL),A                                  ; $BCDE: 77
    ADD HL,DE                                  ; $BCDF: 19
    DJNZ L_BCDB                                ; $BCE0: 10 F9
    LD HL,$4000                                ; $BCE2: 21 00 40  top pixel line
    CALL DrawFullWidthLine                     ; $BCE5: CD D6 BB
    LD HL,$57E0                                ; $BCE8: 21 E0 57  bottom pixel line
    CALL DrawFullWidthLine                     ; $BCEB: CD D6 BB
    XOR A                                      ; $BCEE: AF
    LD L,A                                     ; $BCEF: 6F
    INC A                                      ; $BCF0: 3C
    LD H,A                                     ; $BCF1: 67
    LD (TextColumn),HL                         ; $BCF2: 22 0D A8  TextColumn = 0, TextRow = 1
    RET                                        ; $BCF5: C9

; VERIFIED: Justified text: address of the last character stored in the line buffer
; (WrapLineBuffer..L_7021); also used as the scan position for inserting spaces.
JustifyWritePointer:
    defw $0000                                                                            ; $BCF6

; VERIFIED: Justified text: length of the partial word moved to the next line.
JustifyCarryLength:
    defb $00                                                                              ; $BCF8 .

; VERIFIED: Justified text: characters in the current line (a line holds 30).
JustifyLineLength:
    defb $00                                                                              ; $BCF9 .

; VERIFIED: Justified text: write pointer for the next line (WrapSentinelSpace + carried length).
JustifyNextWritePointer:
    defw $0000                                                                            ; $BCFA

; VERIFIED: PrintCharacter output while TextRedirectFlag = 1 (character on the stack): store it
; in the line buffer.  A '.' prints the line at once.  When the 31st
; character arrives, a space ends the line; otherwise the partial word is
; moved to the carry buffer WrapCarryBuffer, the line is padded by inserting spaces at
; earlier gaps (InsertSpaceInTextBuffer) and printed.  Quirk: a character other than a space that
; arrives as the 31st character is stored after the 30 printed ones and lost, so a
; line-ending '.' can disappear (text/justified-full-stop-loss).
; Evidence: docked-system-data trace; tools/check_routines.py text checks.
BufferJustifiedCharacter:
    LD HL,(JustifyWritePointer)                ; $BCFC: 2A F6 BC  advance to the next free position
    INC HL                                     ; $BCFF: 23
    LD (JustifyWritePointer),HL                ; $BD00: 22 F6 BC
    POP AF                                     ; $BD03: F1  character left on the stack by PrintCharacter
    LD (HL),A                                  ; $BD04: 77
    CP $2E                                     ; $BD05: FE 2E  '.' prints the line at once
    JP Z,PrintJustifiedLine                    ; $BD07: CA 5D BD
    LD B,A                                     ; $BD0A: 47
    LD A,(JustifyLineLength)                   ; $BD0B: 3A F9 BC  one more character in the line
    INC A                                      ; $BD0E: 3C
    LD (JustifyLineLength),A                   ; $BD0F: 32 F9 BC
    CP $1F                                     ; $BD12: FE 1F  line holds 30 characters
    RET C                                      ; $BD14: D8  line not full yet
    LD A,$20                                   ; $BD15: 3E 20  the 31st character: a space just ends the line
    CP B                                       ; $BD17: B8
    JP Z,PrintJustifiedLine                    ; $BD18: CA 5D BD
    CALL FindPreviousSpace                     ; $BD1B: CD C6 BD  B = length of the word cut by the line end
    LD A,B                                     ; $BD1E: 78
    LD (JustifyCarryLength),A                  ; $BD1F: 32 F8 BC
    AND A                                      ; $BD22: A7
    JR Z,L_BD52                                ; $BD23: 28 2D
    LD HL,(JustifyWritePointer)                ; $BD25: 2A F6 BC
    INC HL                                     ; $BD28: 23
    LD C,B                                     ; $BD29: 48
    LD B,$00                                   ; $BD2A: 06 00
    LD DE,WrapCarryBuffer                      ; $BD2C: 11 23 70  carry buffer for the partial word
    LDIR                                       ; $BD2F: ED B0  move the cut word to the carry buffer
    LD HL,WrapSentinelSpace                    ; $BD31: 21 03 70
    LD A,(JustifyCarryLength)                  ; $BD34: 3A F8 BC
    LD E,A                                     ; $BD37: 5F
    LD D,$00                                   ; $BD38: 16 00
    ADD HL,DE                                  ; $BD3A: 19
    LD (JustifyNextWritePointer),HL            ; $BD3B: 22 FA BC  the next line continues after it
    LD A,(JustifyCarryLength)                  ; $BD3E: 3A F8 BC
    CP $1F                                     ; $BD41: FE 1F  never taken: FindPreviousSpace returns B <= 30
    JP NC,PrintJustifiedLine                   ; $BD43: D2 5D BD
    LD HL,(JustifyWritePointer)                ; $BD46: 2A F6 BC
    LD B,A                                     ; $BD49: 47
L_BD4A:
    LD (HL),$00                                ; $BD4A: 36 00  zero the cut word and its space: free cells
    INC HL                                     ; $BD4C: 23
    DJNZ L_BD4A                                ; $BD4D: 10 FB
    LD A,(JustifyCarryLength)                  ; $BD4F: 3A F8 BC
L_BD52:
    PUSH AF                                    ; $BD52: F5  one extra space per freed cell
    CALL FindPreviousSpace                     ; $BD53: CD C6 BD  next gap to the left (wraps at the line start)
    CALL InsertSpaceInTextBuffer               ; $BD56: CD 00 D0  widen that gap by one space
    POP AF                                     ; $BD59: F1
    DEC A                                      ; $BD5A: 3D
    JR NZ,L_BD52                               ; $BD5B: 20 F5

; VERIFIED: Print the 30 buffered characters at WrapLineBuffer with PutCharacter, a new line,
; clear CapitaliseNextFlag, then StartNextJustifiedLine.
PrintJustifiedLine:
    LD HL,WrapLineBuffer                       ; $BD5D: 21 04 70
    LD B,$1E                                   ; $BD60: 06 1E  30 characters per line
L_BD62:
    PUSH BC                                    ; $BD62: C5
    PUSH HL                                    ; $BD63: E5
    LD A,(HL)                                  ; $BD64: 7E
    CALL PutCharacter                          ; $BD65: CD 58 BB  no case conversion: already applied when buffered
    POP HL                                     ; $BD68: E1
    INC HL                                     ; $BD69: 23
    POP BC                                     ; $BD6A: C1
    DJNZ L_BD62                                ; $BD6B: 10 F5
    CALL NewLine                               ; $BD6D: CD FA AF
    LD A,$00                                   ; $BD70: 3E 00
    LD (CapitaliseNextFlag),A                  ; $BD72: 32 92 A8  no capital at the start of the next line

; VERIFIED: Move the carried word (WrapCarryBuffer..) to the line buffer (WrapLineBuffer..), refill the
; carry buffer with spaces and reset the pointers and lengths.
StartNextJustifiedLine:
    LD HL,(JustifyNextWritePointer)            ; $BD75: 2A FA BC
    LD (JustifyWritePointer),HL                ; $BD78: 22 F6 BC  the line continues after the carried word
    LD HL,WrapSentinelSpace                    ; $BD7B: 21 03 70
    LD (JustifyNextWritePointer),HL            ; $BD7E: 22 FA BC
    LD A,(JustifyCarryLength)                  ; $BD81: 3A F8 BC
    LD (JustifyLineLength),A                   ; $BD84: 32 F9 BC  its length so far
    XOR A                                      ; $BD87: AF
    LD (JustifyCarryLength),A                  ; $BD88: 32 F8 BC
    LD B,$1E                                   ; $BD8B: 06 1E
    LD C,$20                                   ; $BD8D: 0E 20  refill value: space
    LD HL,WrapCarryBuffer                      ; $BD8F: 21 23 70
    LD DE,WrapLineBuffer                       ; $BD92: 11 04 70
L_BD95:
    LD A,(HL)                                  ; $BD95: 7E
    LD (DE),A                                  ; $BD96: 12  carried word to the line start
    LD (HL),C                                  ; $BD97: 71  carry buffer back to spaces
    INC HL                                     ; $BD98: 23
    INC DE                                     ; $BD99: 13
    DJNZ L_BD95                                ; $BD9A: 10 F9
    RET                                        ; $BD9C: C9

; VERIFIED: Message control 14: TextRedirectFlag = 1 (characters go to BufferJustifiedCharacter),
; fill 31 bytes from WrapCarryBuffer with spaces and start an empty line.
; NOTE: the 31st byte is $7041 (CurrentScreenId), written by $BDA9 at runtime.
StartJustifiedText:
    LD A,$01                                   ; $BD9D: 3E 01
    LD (TextRedirectFlag),A                    ; $BD9F: 32 94 A8
    LD B,$1F                                   ; $BDA2: 06 1F  31 bytes: $7023..$7041 (overwrites CurrentScreenId)
    LD A,$20                                   ; $BDA4: 3E 20
    LD HL,WrapCarryBuffer                      ; $BDA6: 21 23 70
L_BDA9:
    LD (HL),A                                  ; $BDA9: 77
    INC HL                                     ; $BDAA: 23
    DJNZ L_BDA9                                ; $BDAB: 10 FC
    LD HL,WrapSentinelSpace                    ; $BDAD: 21 03 70  no carried word yet
    LD (JustifyNextWritePointer),HL            ; $BDB0: 22 FA BC
    XOR A                                      ; $BDB3: AF
    LD (JustifyCarryLength),A                  ; $BDB4: 32 F8 BC
    JR StartNextJustifiedLine                  ; $BDB7: 18 BC

; VERIFIED: Message control 15: TextRedirectFlag = 0 and print any partly filled line.
EndJustifiedText:
    LD A,$00                                   ; $BDB9: 3E 00
    LD (TextRedirectFlag),A                    ; $BDBB: 32 94 A8
    LD A,(JustifyLineLength)                   ; $BDBE: 3A F9 BC
    AND A                                      ; $BDC1: A7
    CALL NZ,PrintJustifiedLine                 ; $BDC2: C4 5D BD  flush a partly filled line (not justified)
    RET                                        ; $BDC5: C9

; VERIFIED: Move JustifyWritePointer back to the previous space; B = distance.  Below
; WrapLineBuffer the scan restarts from the line end (WrapOverflowChar), so repeated calls visit
; the gaps of the line from right to left in a cycle.  A line without any space
; would make it scan for ever, so B is 1..30 whenever it returns.
FindPreviousSpace:
    LD HL,(JustifyWritePointer)                ; $BDC6: 2A F6 BC
    LD B,$00                                   ; $BDC9: 06 00
L_BDCB:
    DEC HL                                     ; $BDCB: 2B  scan backwards
    LD A,(HL)                                  ; $BDCC: 7E
    INC B                                      ; $BDCD: 04
    CP $20                                     ; $BDCE: FE 20
    JR NZ,L_BDCB                               ; $BDD0: 20 F9  until a space
    LD (JustifyWritePointer),HL                ; $BDD2: 22 F6 BC
    LD DE,WrapLineBuffer                       ; $BDD5: 11 04 70
    AND A                                      ; $BDD8: A7
    SBC HL,DE                                  ; $BDD9: ED 52
    RET NC                                     ; $BDDB: D0  still inside the line
    LD HL,WrapOverflowChar                     ; $BDDC: 21 22 70  passed the start: continue from the line end
    LD (JustifyWritePointer),HL                ; $BDDF: 22 F6 BC
    JR FindPreviousSpace                       ; $BDE2: 18 E2

; VERIFIED: Tail of the ECM update (JP from $ED9E when EcmTimer is zero): if an ECM is
; fitted (C = EcmFitted) and key bit 4 of KeyFlagsCombat was set (B), store C OR $80
; in EcmFitted and set EcmTimer = 10.  Evidence: ecm-bomb-pod trace ('E' key).
ActivatePlayerEcm:
    LD A,C                                     ; $BDE4: 79
    AND A                                      ; $BDE5: A7
    RET Z                                      ; $BDE6: C8  no ECM fitted
    BIT 4,B                                    ; $BDE7: CB 60  key bit 4 from KeyFlagsCombat
    RET Z                                      ; $BDE9: C8  ECM key not pressed
    OR $80                                     ; $BDEA: F6 80  bit 7: ECM active
    LD (EcmFitted),A                           ; $BDEC: 32 47 A8
    LD A,$0A                                   ; $BDEF: 3E 0A  EcmTimer = 10
    LD (EcmTimer),A                            ; $BDF1: 32 16 DA
    RET                                        ; $BDF4: C9

; INFERRED: Eleven zero bytes up to the page-aligned SquareLookupTables; no reference.
; Probably alignment padding.
L_BDF5:
    defs 11,0                                                                             ; $BDF5..$BDFF

; KNOWN DATA: VERIFIED DATA: 256 low bytes then 256 high bytes of n*n for n=0..255.
    INCLUDE "data/square-tables.asm"


; KNOWN DATA: VERIFIED font: startup copies this block to FontRuntime; character lookup uses (code-FontFirstCode)*8.
IF FONT_48
    INCLUDE "data/font-48.asm"
ELSE
IF FONT_128FIX
    INCLUDE "data/font-128fix.asm"
ELSE
IF FONT_128FIX_ECM_S
    INCLUDE "data/font-128fix_ecm_s.asm"
ELSE
    INCLUDE "data/font.asm"
ENDIF
ENDIF
ENDIF


; ============================================================================
; View-buffer area after the font: zero fill and a dormant loader
; Initial tape content only.  At runtime $C000..$CFFF is the view bitmap buffer;
; every byte of $C2D8..$C6FF is written and read there (view clear, line drawing,
; BlitViewBitmap).  No instruction of the game references $C2D8..$C6FF.
; ============================================================================

; VERIFIED: Zero fill in the reference image (120 bytes) between the font and the dormant loader.
; Runtime: part of the view bitmap buffer: cleared with PUSH at L_7485, drawn into by the
; pixel/line routines (stores at $86B8, $875E, $87BD, $A282, $F204, $F232, $F253, $F27F) and
; CharacterBlendOpcode, copied to the screen by BlitViewBitmap (LDI at $73C5).  Traces show
; every byte of this run written and read.  No static reference.
; INFERRED: the initial zeros are never needed, because the buffer is redrawn before use.
ViewBufferZerosAfterFont:
    defs 120,0                                                                            ; $C2D8..$C34F

; VERIFIED: Dormant self-relocating loader (188 bytes, $C350..$C40B), never referenced by the game
; and never executed in any 48K trace.  Entered with BC = its own address (BASIC USR
; convention), it patches the operands of its nine CALL DormantPortReceiveByte
; instructions, sets up I/O ports $DF/$5D/$FE, then repeatedly: waits for a '-' sync
; byte, receives destination (HL), length (BC) and execution address (pushed), receives
; the block with an additive checksum starting at $FF and RETurns into the loaded code
; when the check byte matches; otherwise it flashes the border until a key is pressed
; and waits for a new header.
; INFERRED: a development-system remnant (external parallel interface on ports
; $1F/$9F) left in memory when the image was saved; not the game's tape code (see
; RunAccessMenu).
DormantPortLoader:
    LD HL,DormantPortReceiveByte-DormantPortLoader ; $C350: 21 9E 00  DE = own address + receiver offset (BC = own address)
    ADD HL,BC                                  ; $C353: 09
    EX DE,HL                                   ; $C354: EB
    LD HL,L_C3A3+1-DormantPortLoader           ; $C355: 21 54 00  patch the operand of each CALL DormantPortReceiveByte
    ADD HL,BC                                  ; $C358: 09
    LD (HL),E                                  ; $C359: 73
    INC HL                                     ; $C35A: 23
    LD (HL),D                                  ; $C35B: 72
    LD HL,L_C3AB+1-DormantPortLoader           ; $C35C: 21 5C 00
    ADD HL,BC                                  ; $C35F: 09
    LD (HL),E                                  ; $C360: 73
    INC HL                                     ; $C361: 23
    LD (HL),D                                  ; $C362: 72
    LD HL,L_C3AF+1-DormantPortLoader           ; $C363: 21 60 00
    ADD HL,BC                                  ; $C366: 09
    LD (HL),E                                  ; $C367: 73
    INC HL                                     ; $C368: 23
    LD (HL),D                                  ; $C369: 72
    LD HL,L_C3B3+1-DormantPortLoader           ; $C36A: 21 64 00
    ADD HL,BC                                  ; $C36D: 09
    LD (HL),E                                  ; $C36E: 73
    INC HL                                     ; $C36F: 23
    LD (HL),D                                  ; $C370: 72
    LD HL,L_C3B7+1-DormantPortLoader           ; $C371: 21 68 00
    ADD HL,BC                                  ; $C374: 09
    LD (HL),E                                  ; $C375: 73
    INC HL                                     ; $C376: 23
    LD (HL),D                                  ; $C377: 72
    LD HL,L_C3BB+1-DormantPortLoader           ; $C378: 21 6C 00
    ADD HL,BC                                  ; $C37B: 09
    LD (HL),E                                  ; $C37C: 73
    INC HL                                     ; $C37D: 23
    LD (HL),D                                  ; $C37E: 72
    LD HL,L_C3BF+1-DormantPortLoader           ; $C37F: 21 70 00
    ADD HL,BC                                  ; $C382: 09
    LD (HL),E                                  ; $C383: 73
    INC HL                                     ; $C384: 23
    LD (HL),D                                  ; $C385: 72
    LD HL,L_C3C8+1-DormantPortLoader           ; $C386: 21 79 00
    ADD HL,BC                                  ; $C389: 09
    LD (HL),E                                  ; $C38A: 73
    INC HL                                     ; $C38B: 23
    LD (HL),D                                  ; $C38C: 72
    LD HL,L_C3D5+1-DormantPortLoader           ; $C38D: 21 86 00
    ADD HL,BC                                  ; $C390: 09
    LD (HL),E                                  ; $C391: 73
    INC HL                                     ; $C392: 23
    LD (HL),D                                  ; $C393: 72
    DI                                         ; $C394: F3  set up the external interface ports
    LD A,$FF                                   ; $C395: 3E FF
    OUT ($DF),A                                ; $C397: D3 DF
    OUT ($DF),A                                ; $C399: D3 DF
    OUT ($5D),A                                ; $C39B: D3 5D
    LD A,$FD                                   ; $C39D: 3E FD
    OUT ($5D),A                                ; $C39F: D3 5D
    OUT ($FE),A                                ; $C3A1: D3 FE
L_C3A3:
    CALL DormantPortReceiveByte                ; $C3A3: CD EE C3  wait for the header sync byte
    LD A,E                                     ; $C3A6: 7B
    CP $2D                                     ; $C3A7: FE 2D  '-'
    JR NZ,L_C3A3                               ; $C3A9: 20 F8
L_C3AB:
    CALL DormantPortReceiveByte                ; $C3AB: CD EE C3  destination address -> HL
    LD L,E                                     ; $C3AE: 6B
L_C3AF:
    CALL DormantPortReceiveByte                ; $C3AF: CD EE C3
    LD H,E                                     ; $C3B2: 63
L_C3B3:
    CALL DormantPortReceiveByte                ; $C3B3: CD EE C3  length -> BC
    LD C,E                                     ; $C3B6: 4B
L_C3B7:
    CALL DormantPortReceiveByte                ; $C3B7: CD EE C3
    LD B,E                                     ; $C3BA: 43
L_C3BB:
    CALL DormantPortReceiveByte                ; $C3BB: CD EE C3  execution address -> stack
    LD D,E                                     ; $C3BE: 53
L_C3BF:
    CALL DormantPortReceiveByte                ; $C3BF: CD EE C3
    LD A,E                                     ; $C3C2: 7B
    LD E,D                                     ; $C3C3: 5A
    LD D,A                                     ; $C3C4: 57
    PUSH DE                                    ; $C3C5: D5
    LD D,$FF                                   ; $C3C6: 16 FF  checksum starts at $FF
L_C3C8:
    CALL DormantPortReceiveByte                ; $C3C8: CD EE C3  receive the block, adding each byte to D
    LD (HL),E                                  ; $C3CB: 73
    INC HL                                     ; $C3CC: 23
    LD A,E                                     ; $C3CD: 7B
    ADD A,D                                    ; $C3CE: 82
    LD D,A                                     ; $C3CF: 57
    DEC BC                                     ; $C3D0: 0B
    LD A,B                                     ; $C3D1: 78
    OR C                                       ; $C3D2: B1
    JR NZ,L_C3C8                               ; $C3D3: 20 F3
L_C3D5:
    CALL DormantPortReceiveByte                ; $C3D5: CD EE C3  check byte
    LD A,E                                     ; $C3D8: 7B
    CP D                                       ; $C3D9: BA
    RET Z                                      ; $C3DA: C8  checksum matches: RET to the pushed execution address
    LD C,$1A                                   ; $C3DB: 0E 1A  error: flash the border until a key is pressed
L_C3DD:
    LD A,C                                     ; $C3DD: 79
    XOR $1A                                    ; $C3DE: EE 1A
    LD C,A                                     ; $C3E0: 4F
    OUT ($FE),A                                ; $C3E1: D3 FE
    XOR A                                      ; $C3E3: AF
    IN A,($FE)                                 ; $C3E4: DB FE
    CPL                                        ; $C3E6: 2F
    AND $1F                                    ; $C3E7: E6 1F
    JR Z,L_C3DD                                ; $C3E9: 28 F2
    POP DE                                     ; $C3EB: D1  discard the execution address and wait for a new header
    JR L_C3A3                                  ; $C3EC: 18 B5

; VERIFIED: Dormant byte receiver of DormantPortLoader: handshake through port $1F (bit 0),
; E = byte from port $9F, then border stripes from C.  Returns E.
DormantPortReceiveByte:
    XOR A                                      ; $C3EE: AF  handshake low
    OUT ($1F),A                                ; $C3EF: D3 1F
L_C3F1:
    IN A,($1F)                                 ; $C3F1: DB 1F
    AND $01                                    ; $C3F3: E6 01
    JR NZ,L_C3F1                               ; $C3F5: 20 FA
    IN A,($9F)                                 ; $C3F7: DB 9F  data byte
    LD E,A                                     ; $C3F9: 5F
    LD A,$02                                   ; $C3FA: 3E 02  handshake high
    OUT ($1F),A                                ; $C3FC: D3 1F
L_C3FE:
    IN A,($1F)                                 ; $C3FE: DB 1F
    AND $01                                    ; $C400: E6 01
    JR Z,L_C3FE                                ; $C402: 28 FA
    LD A,C                                     ; $C404: 79  border stripes from the length counter
    AND $07                                    ; $C405: E6 07
    OR $18                                     ; $C407: F6 18
    OUT ($FE),A                                ; $C409: D3 FE
    RET                                        ; $C40B: C9

; VERIFIED: Two residue bytes $F3,$AF in the reference image (DI, XOR A if decoded) after the
; receiver's RET.  Runtime: part of the view bitmap buffer like the surrounding zeros.
; No static reference.  In all seven 48K access traces their first access is the
; ClearViewBuffer write (PUSH HL at L_7485), so the stored values are never used.  Of
; $C000..$CFFF only the FontBitmap, CockpitAttributes and CockpitBitmap source bytes
; are read before a write.
; Evidence: memory_read_before_write_map of tools/run_runtime_scenarios.py --accesses;
; tools/check_routines.py dormant/unused-interrupt-routines (ClearViewBuffer zeroes them).
ViewBufferResidueAfterLoader:
    defb $F3,$AF                                                                          ; $C40C ..

; VERIFIED: Zero fill in the reference image (498 bytes) up to the optional Adder startup area.
; Runtime: part of the view bitmap buffer like ViewBufferZerosAfterFont (cleared by L_7485, drawn into,
; copied by BlitViewBitmap).  No static reference.
ViewBufferZerosAfterLoader:
    defs 498,0                                                                            ; $C40E..$C5FF

; VERIFIED: 64 zero bytes kept in place for the optional ship=adder startup (src/adder-startup.asm,
; docs/BUILD-VARIANTS.md); the default build emits the original zeros.  Runtime: part of
; the view bitmap buffer like the surrounding bytes.
L_C600:
IF SHIP_ADDER
    INCLUDE "adder-startup.asm"
ENDIF
    defs (VariantStartupLimit-GameLoadAddress)-($-GameImage),0

; VERIFIED: Zero fill in the reference image (192 bytes) up to CockpitAttributes.  Runtime: part of
; the view bitmap buffer like ViewBufferZerosAfterFont (cleared by L_7485, drawn into, copied by BlitViewBitmap).
ViewBufferZerosBeforeCockpit:
    defs 192,0                                                                            ; $C640..$C6FF

; KNOWN DATA: VERIFIED initial cockpit colours: 32 columns x 8 character rows. Copied to CockpitAttributesRuntime at startup.
    INCLUDE "data/cockpit-attributes.asm"


; KNOWN DATA: VERIFIED initial cockpit bitmap: 256 x 64 pixels in Spectrum screen order. Copied to ScreenCockpitBitmap.
    INCLUDE "data/cockpit-bitmap.asm"


; ============================================================================
; Docked information screens and text helpers
; System-data helpers (species, radius, seed compare), market prices,
; commander status, inventory, and the full-screen mission/boarding messages.
; ============================================================================

; VERIFIED: Insert a space at the address held in the pointer word JustifyWritePointer: each byte from there up
; to and including the first zero moves up one position (the zero is overwritten by the
; byte before it, so the buffer must continue with zeros).  JustifyWritePointer is unchanged.
; Input: JustifyWritePointer.  Clobbers: A, B, C, HL, flags.
; Only caller: L_BD52 in the justified printer.  When a word wraps to the next line it calls
; FindPreviousSpace and then this routine once for every column the shortened line in WrapLineBuffer
; lacks, so the word gaps widen from right to left until the line is 30 characters wide again.
; Evidence: instruction semantics; tools/check_routines.py text/insert-space and
; text/p7-justify-padding (calls = padding spaces, every full line exactly 30 characters).
InsertSpaceInTextBuffer:
    LD B,$20                                   ; $D000: 06 20  B = the space to insert
    LD HL,(JustifyWritePointer)                ; $D002: 2A F6 BC  HL = insertion point
L_D005:
    LD A,(HL)                                  ; $D005: 7E
    LD C,A                                     ; $D006: 4F
    LD (HL),B                                  ; $D007: 70  store the carried byte, carry the old one
    LD B,C                                     ; $D008: 41
    INC HL                                     ; $D009: 23
    XOR A                                      ; $D00A: AF
    CP C                                       ; $D00B: B9  stop after moving the first zero byte
    JR NZ,L_D005                               ; $D00C: 20 F7
    RET                                        ; $D00E: C9

; VERIFIED: Print the inhabitant species of a system whose seed byte SelectedSystemSeed2 is >= $80
; (entered by JP from PrintSpecies with H = high byte of word SelectedSystemSeed2):
;   (H >> 2) AND 7 < 3  -> token $E3+n LARGE/FIERCE/SMALL and a space
;   H >> 5 < 6          -> token $E6+n GREEN/RED/YELLOW/BLUE/BLACK/HARMLESS and a space
;   (hi SelectedSystemSeeds XOR hi SelectedSystemSeed1) AND 7 = m < 6 -> token $EC+m SLIMY..FURRY and a space
;   ((m + (hi SelectedSystemSeed2 AND 3)) AND 7) -> token $F2.. RODENT/FROG/LIZARD/LOBSTER/BIRD/
;                                      HUMANOID/FELINE/INSECT (tail jump to PrintToken)
; An adjective whose value is outside its range is left out; the species noun is always printed.
; Only path: DisplaySystemData -> PrintSpecies (a seed byte below $80 prints HUMAN COLONIAL
; instead).  Clobbers: A, B, HL, flags.
; Evidence: decoded tokens; the system-data screen DisplaySystemData prints "(" species "S)".
PrintAlienSpecies:
    LD A,H                                     ; $D00F: 7C  H = high byte of word SelectedSystemSeed2 (from PrintSpecies)
    SRL A                                      ; $D010: CB 3F
    SRL A                                      ; $D012: CB 3F
    PUSH AF                                    ; $D014: F5
    AND $07                                    ; $D015: E6 07
    CP $03                                     ; $D017: FE 03  size 0..2: LARGE, FIERCE, SMALL
    JR NC,L_D020                               ; $D019: 30 05
    ADD A,$E3                                  ; $D01B: C6 E3
    CALL PrintTokenSpace                       ; $D01D: CD EF AF  size adjective and a space
L_D020:
    POP AF                                     ; $D020: F1
    SRL A                                      ; $D021: CB 3F
    SRL A                                      ; $D023: CB 3F
    SRL A                                      ; $D025: CB 3F
    CP $06                                     ; $D027: FE 06  colour 0..5: GREEN .. HARMLESS
    JR NC,L_D030                               ; $D029: 30 05
    ADD A,$E6                                  ; $D02B: C6 E6
    CALL PrintTokenSpace                       ; $D02D: CD EF AF  colour adjective and a space
L_D030:
    LD HL,(SelectedSystemSeeds)                ; $D030: 2A 0F AC  high byte of word SelectedSystemSeeds
    LD A,H                                     ; $D033: 7C
    LD B,A                                     ; $D034: 47
    LD HL,(SelectedSystemSeed1)                ; $D035: 2A 11 AC  high byte of word SelectedSystemSeed1
    LD A,H                                     ; $D038: 7C
    XOR B                                      ; $D039: A8
    AND $07                                    ; $D03A: E6 07
    PUSH AF                                    ; $D03C: F5
    CP $06                                     ; $D03D: FE 06  skin 0..5: SLIMY .. FURRY
    JR NC,L_D046                               ; $D03F: 30 05
    ADD A,$EC                                  ; $D041: C6 EC
    CALL PrintTokenSpace                       ; $D043: CD EF AF  skin adjective and a space
L_D046:
    LD HL,(SelectedSystemSeed2)                ; $D046: 2A 13 AC  high byte of word SelectedSystemSeed2, bits 0..1
    LD A,H                                     ; $D049: 7C
    AND $03                                    ; $D04A: E6 03
    LD B,A                                     ; $D04C: 47
    POP AF                                     ; $D04D: F1
    ADD A,B                                    ; $D04E: 80
    AND $07                                    ; $D04F: E6 07
    ADD A,$F2                                  ; $D051: C6 F2  species token $F2..$F9

; VERIFIED: Shared tail JP PrintToken; PrintSpecies enters here with A = $BC "HUMAN COLONIAL".
L_D053:
    JP PrintToken                              ; $D053: C3 9D BA

; VERIFIED: Print HL = ((hi SelectedSystemSeed2 AND $0F) + $0B) * 256 + hi SelectedSystemSeed1 as a five-character decimal
; number (NumberFieldWidth = 5, carry clear: no decimal point); the value range is 2816..6911.
; Tail jump to PrintDecimalHL.
; Evidence: the only caller (DisplaySystemData) prints token $FA "AVERAGE RADIUS:" first and " km"
; (PrintCommodityUnit with unit 17) after it; runtime docked-system-data.
PrintPlanetRadius:
    LD HL,(SelectedSystemSeed2)                ; $D056: 2A 13 AC
    LD A,H                                     ; $D059: 7C
    AND $0F                                    ; $D05A: E6 0F
    ADD A,$0B                                  ; $D05C: C6 0B  radius high byte = (seed AND $0F) + $0B
    LD HL,(SelectedSystemSeed1)                ; $D05E: 2A 11 AC
    LD L,H                                     ; $D061: 6C  radius low byte = high byte of word SelectedSystemSeed1
    LD H,A                                     ; $D062: 67
    LD A,$05                                   ; $D063: 3E 05  field width 5 (NumberFieldWidth)
    LD (NumberFieldWidth),A                    ; $D065: 32 8E A8  pad the radius to five characters
    AND A                                      ; $D068: A7  carry clear: no decimal point
    JP PrintDecimalHL                          ; $D069: C3 60 B7  tail jump: print HL and return to DisplaySystemData

; VERIFIED: Compare the six bytes at HL with the galaxy seeds GalaxySeeds..L_A857.
; Output: carry clear if all six are equal, carry set otherwise.  Clobbers: A, B, DE, HL.
; The galaxy seeds are also the seeds of the galaxy's first system (system 0, the name that
; message control 16 prints), so a match identifies that system: the special-mission target,
; where L_D7E1 sets mission-3 state 4 and the data screen shows the Thargoid message $DE.
; Evidence: tools/check_routines.py commander/galaxy-seed-compare; GalaxySeeds..L_A857 are rotated
; one bit per byte by galactic hyperspace (L_D63A/RotateSeedWordLeft).  Callers pass SelectedSystemSeeds (system shown
; on the data screen, DisplaySystemData) and CurrentSystemSeeds (current system, L_D7E1).
CompareWithGalaxySeeds:
    LD DE,GalaxySeeds                          ; $D06C: 11 52 A8
    LD B,$06                                   ; $D06F: 06 06  six seed bytes
L_D071:
    LD A,(DE)                                  ; $D071: 1A
    CP (HL)                                    ; $D072: BE
    JR NZ,L_D07B                               ; $D073: 20 06
    INC DE                                     ; $D075: 13
    INC HL                                     ; $D076: 23
    DJNZ L_D071                                ; $D077: 10 F8
    AND A                                      ; $D079: A7  equal: carry clear
    RET                                        ; $D07A: C9
L_D07B:
    SCF                                        ; $D07B: 37  different: carry set
    RET                                        ; $D07C: C9

; VERIFIED: Market prices screen (screen function 6, L_A7EC): BeginTitledScreen clears the screen and
; draws the frame and title rule; title token $A7 "{t2} MARKET PRICES" on row 1, column header
; token $FF at column 16, row 3 (two lines), attribute bars from MarketPricesAttributeLayout.  Unless WitchspaceFlag is
; nonzero (witchspace), list the 17 trade goods from row 6 through PrintMarketLine with item index
; CurrentCommodity = 0..16, price pointer PricePointer and station stock pointer StockPointer.
; Evidence: decoded tokens; runtime docked-market (executed through $D0B7).
ShowMarketPrices:
    CALL BeginTitledScreen                     ; $D07D: CD AB B4  clear the screen, frame and title rule (message 150)
    LD A,$A7                                   ; $D080: 3E A7  token: "{present-system} MARKET PRICES"
    CALL PrintScreenTitle                      ; $D082: CD 57 B0  title in capitals on row 1, then three new lines
    LD HL,$0310                                ; $D085: 21 10 03  column 16, row 3
    LD (TextColumn),HL                         ; $D088: 22 0D A8
    LD A,$FF                                   ; $D08B: 3E FF  token: "{caps}UNIT  QUANTITY{cr}PRODUCT    UNIT PRICE FOR SALE{title-case}{cr}"
    CALL PrintTokenNewLine                     ; $D08D: CD F7 AF  header rows 3 and 4; the goods start on row 6
    LD DE,MarketPricesAttributeLayout          ; $D090: 11 0B FC  attribute bar list for ColourAttributeStrips
    CALL ColourAttributeStrips                 ; $D093: CD DF BB
    LD A,(WitchspaceFlag)                      ; $D096: 3A 61 70  goods listed only while WitchspaceFlag is zero
    AND A                                      ; $D099: A7
    RET NZ                                     ; $D09A: C0
    XOR A                                      ; $D09B: AF  item index CurrentCommodity = 0
    LD (CurrentCommodity),A                    ; $D09C: 32 30 AF
    LD HL,MarketPrices-2                       ; $D09F: 21 0C AF  price word pointer (PrintMarketLine adds 2 first)
    LD (PricePointer),HL                       ; $D0A2: 22 33 AF
    LD HL,MarketStock-1                        ; $D0A5: 21 5F A8  station stock pointer (PrintMarketLine adds 1 first)
    LD (StockPointer),HL                       ; $D0A8: 22 35 AF
L_D0AB:
    CALL PrintMarketLine                       ; $D0AB: CD 63 AF  print one market line for item CurrentCommodity
    LD HL,CurrentCommodity                     ; $D0AE: 21 30 AF  next commodity
    INC (HL)                                   ; $D0B1: 34
    LD A,(HL)                                  ; $D0B2: 7E
    CP $11                                     ; $D0B3: FE 11  17 trade goods
    JR C,L_D0AB                                ; $D0B5: 38 F4
    RET                                        ; $D0B7: C9

; VERIFIED: Laser mount index while the status screen lists lasers: set to $FF at $D17D and
; incremented by PrintLaserMount before each mount (0 front, 1 rear, 2 left, 3 right).
StatusLaserMountIndex:
    defb $00                                                                              ; $D0B8 .

; VERIFIED: Commander status screen (CurrentScreenId = $0B): token $7E "COMMANDER {name}" with the
; labels PRESENT SYSTEM and HYPERSPACE SYSTEM, their names (token controls 2 and 3) at
; column 21, then FUEL (control 5), CASH (control 7), LEGAL STATUS, RATING and the
; EQUIPMENT list, and finally the screen frame (DrawScreenFrame).  Rows: name 1, systems 4..5, fuel 6,
; cash 7, legal status 8, rating 9, EQUIPMENT 11, items from row 12 at column 5.
; Callers: screen function 7 (L_A7EF), StartNewGame, the docked main loop after an access menu
; that read nothing (L_72A2), BuyEquipmentItem (L_B5DA, L_B736) and the hyperspace key while
; docked (L_D5D6).  UpdateConditionIndicator adds the condition tiles at column 27, row 1 only in flight.
; Evidence: decoded tokens/messages; runtime docked screens (executed to $D1DF);
; tools/check_routines.py commander/p7-docked-screen-text (text and rows, three equipment sets).
ShowCommanderStatus:
    LD A,$0B                                   ; $D0B9: 3E 0B  screen id $0B: commander status
    LD (CurrentScreenId),A                     ; $D0BB: 32 41 70
    LD A,$96                                   ; $D0BE: 3E 96  message 150: "{cls}{rule}{caps}{col4-cap}"
    CALL PrintMessage                          ; $D0C0: CD D7 BA  clear the screen, frame and title rule, capitals
    CALL UpdateConditionIndicator              ; $D0C3: CD BD A4  condition tiles at column 27, row 1 (in flight only)
    LD DE,StatusScreenAttributeLayout          ; $D0C6: 11 9E FB  attribute bar list for ColourAttributeStrips
    CALL ColourAttributeStrips                 ; $D0C9: CD DF BB
    CALL SetTextColumnInline                   ; $D0CC: CD 0D B0
    defb $06                                   ; $D0CF: 06  SetTextColumnInline argument: text column 6
    CALL PrintInlineToken                      ; $D0D0: CD 99 BA  COMMANDER name on row 1, system labels on rows 4 and 5
    defb $7E                                   ; $D0D3: 7E  PrintInlineToken argument: "{caps}COMMANDER {commander}{title-case}{cr}{cr}{cr}PRESEN..."

; VERIFIED: Status screen: the present and hyperspace system names after their labels on rows 4 and 5
; (PrintColonTokenAtColumn21: ':' at column 21, token control 2 or 3, new line).
L_D0D4:
    LD A,$04                                   ; $D0D4: 3E 04  row 4
    CALL SetTextRow                            ; $D0D6: CD 19 B0
    LD A,$02                                   ; $D0D9: 3E 02  token control 2: present system name
    CALL PrintColonTokenAtColumn21             ; $D0DB: CD D5 D1  row 4, column 21
    LD A,$03                                   ; $D0DE: 3E 03  token control 3: hyperspace system name
    CALL PrintColonTokenAtColumn21             ; $D0E0: CD D5 D1  row 5, column 21
    LD A,$06                                   ; $D0E3: 3E 06  row 6
    CALL SetTextRow                            ; $D0E5: CD 19 B0
    CALL PrintInlineToken                      ; $D0E8: CD 99 BA  FUEL line on row 6
    defb $05                                   ; $D0EB: 05  PrintInlineToken argument: token control 5, "FUEL: n.n LIGHT YEARS"

; VERIFIED: Status screen: the CASH line (token control 7) on row 7, below the FUEL line of row 6.
L_D0EC:
    CALL PrintInlineToken                      ; $D0EC: CD 99 BA
    defb $07                                   ; $D0EF: 07  PrintInlineToken argument: token control 7, "CASH: ... CR"

; VERIFIED: Status screen: "LEGAL STATUS:" on row 8 (message $71 and ':'); PrintLegalStatus and
; SelectLegalStatusToken follow with CLEAN, OFFENDER or FUGITIVE.
L_D0F0:
    LD A,$71                                   ; $D0F0: 3E 71  message 113: "LEGAL STATUS"
    CALL PrintMessageColon                     ; $D0F2: CD E3 AF  "LEGAL STATUS:" on row 8

; VERIFIED: Status-screen block: print the inline space through PrintInlineToken, then load B=$12.
; The bytes $20,$06,$12 are a text byte followed by LD B,$12, not JR NZ / LD (DE),A.
; Fall through to SelectLegalStatusToken and the remaining status-screen output.
; Evidence: original block-5 bytes and all 256 legal scores in tools/check_bounty_hunters.py.
PrintLegalStatus:
    CALL PrintInlineToken                      ; $D0F5: CD 99 BA
    defb $20                                   ; $D0F8: 20  PrintInlineToken argument: " "
    LD B,$12                                   ; $D0F9: 06 12  B = token $12 CLEAN; +1 OFFENDER, +2 FUGITIVE

; VERIFIED: B is the Clean text-token index ($12), set immediately before this entry.
; Read PlayerLegalScore: keep B for zero, add one for 1..49, two for 50..255.
; Continue into text output at L_D107; this is a status-screen block, not a standalone subroutine.
; Evidence: all 256 scores in tools/check_bounty_hunters.py.
SelectLegalStatusToken:
    LD A,(PlayerLegalScore)                    ; $D0FB: 3A 21 A8
    AND A                                      ; $D0FE: A7
    JR Z,L_D107                                ; $D0FF: 28 06
    CP $32                                     ; $D101: FE 32  scores 1..49: OFFENDER, 50..255: FUGITIVE
    JR C,L_D106                                ; $D103: 38 01
    INC B                                      ; $D105: 04
L_D106:
    INC B                                      ; $D106: 04
L_D107:
    LD A,B                                     ; $D107: 78
    CALL PrintTokenNewLine                     ; $D108: CD F7 AF  legal status token, then a new line
    LD A,$72                                   ; $D10B: 3E 72  message 114: "RATING"
    CALL PrintMessageColon                     ; $D10D: CD E3 AF  "RATING:" on row 9
    CALL PrintInlineToken                      ; $D110: CD 99 BA
    defb $20                                   ; $D113: 20  PrintInlineToken argument: " "

; VERIFIED: Status screen: rating.  A kill count (word CombatScoreLow) below 256 is looked up by its low byte in
; RatingKillThresholdsLow starting with token $15, a larger one by its high byte in
; RatingKillThresholdsHigh starting with token $1A.  B advances one token for every
; threshold below the byte; the first threshold >= the byte (at the latest the $FF end
; marker) selects token B.
; Evidence: tools/check_routines.py commander/rating-thresholds.
L_D114:
    LD HL,CombatScoreHigh                      ; $D114: 21 24 A8  kill count high byte (word CombatScoreLow)
    LD A,(HL)                                  ; $D117: 7E
    AND A                                      ; $D118: A7
    JR NZ,L_D123                               ; $D119: 20 08
    DEC HL                                     ; $D11B: 2B  below 256: compare the low byte
    LD DE,RatingKillThresholdsLow              ; $D11C: 11 E2 D1
    LD B,$15                                   ; $D11F: 06 15  token $15 HARMLESS
    JR L_D128                                  ; $D121: 18 05
L_D123:
    LD DE,RatingKillThresholdsHigh             ; $D123: 11 E8 D1
    LD B,$1A                                   ; $D126: 06 1A  token $1A COMPETENT
L_D128:
    LD A,(DE)                                  ; $D128: 1A
    CP (HL)                                    ; $D129: BE
    JR NC,L_D130                               ; $D12A: 30 04  threshold >= count: rating found
    INC B                                      ; $D12C: 04  next rating token
    INC DE                                     ; $D12D: 13
    JR L_D128                                  ; $D12E: 18 F8
L_D130:
    LD A,B                                     ; $D130: 78
    CALL PrintTokenBlankLine                   ; $D131: CD 5A BA  print the rating token and a blank line (PrintTokenBlankLine)
    CALL PrintInlineToken                      ; $D134: CD 99 BA
    defb $11                                   ; $D137: 11  PrintInlineToken argument: "{caps}EQUIPMENT{title-case}:"

; VERIFIED: Status screen: equipment list below "EQUIPMENT:" (row 11), one item per line at column 5
; (NewLineAtColumn5).  Order: large cargo bay, fuel scoops, E.C.M. system or jammer, energy
; bomb, energy unit, docking computers, galactic hyperspace, the laser mounts and the
; cloaking device.  Each record byte is printed when nonzero (PrintInlineTokenIfSet).
L_D138:
    CALL NewLineAtColumn5                      ; $D138: CD A6 D1
    LD A,(LargeCargoBayFitted)                 ; $D13B: 3A 46 A8  LargeCargoBayFitted: large cargo bay
    CALL PrintInlineTokenIfSet                 ; $D13E: CD 9C D1  printed only when A is nonzero
    defb $6B                                   ; $D141: 6B  PrintInlineTokenIfSet argument: "LARGE CARGO BAY"

; VERIFIED: Equipment list: FUEL SCOOPS when FuelScoopsFitted is nonzero.
L_D142:
    LD A,(FuelScoopsFitted)                    ; $D142: 3A 4A A8  FuelScoopsFitted: fuel scoops
    CALL PrintInlineTokenIfSet                 ; $D145: CD 9C D1
    defb $6F                                   ; $D148: 6F  PrintInlineTokenIfSet argument: "FUEL SCOOPS"

; VERIFIED: Equipment list: with CommanderFlags bit 7 (the jammer that OfferSpecialMission gives) print
; message $CF "E.C.M.SYSTEM JAMMER" instead of the plain E.C.M. SYSTEM line, whether or not
; EcmFitted is set; otherwise E.C.M. SYSTEM when EcmFitted is nonzero.
L_D149:
    LD A,(CommanderFlags)                      ; $D149: 3A 72 A8  CommanderFlags bit 7: E.C.M. jammer replaces the E.C.M. line
    BIT 7,A                                    ; $D14C: CB 7F
    JR Z,L_D15A                                ; $D14E: 28 0A
    LD A,$CF                                   ; $D150: 3E CF  message 207: "{title-case}{token-mode}E.C.M.SYSTEM{msg-mode} JAMMER"
    CALL PrintMessage                          ; $D152: CD D7 BA
    CALL NewLineAtColumn5                      ; $D155: CD A6 D1  next line at column 5
    JR L_D161                                  ; $D158: 18 07
L_D15A:
    LD A,(EcmFitted)                           ; $D15A: 3A 47 A8  EcmFitted: E.C.M. system
    CALL PrintInlineTokenIfSet                 ; $D15D: CD 9C D1
    defb $6C                                   ; $D160: 6C  PrintInlineTokenIfSet argument: "E.C.M.SYSTEM"

; VERIFIED: Equipment list: ENERGY BOMB when EnergyBombFitted is nonzero; both E.C.M. paths join here.
L_D161:
    LD A,(EnergyBombFitted)                    ; $D161: 3A 4C A8  EnergyBombFitted: energy bomb
    CALL PrintInlineTokenIfSet                 ; $D164: CD 9C D1
    defb $71                                   ; $D167: 71  PrintInlineTokenIfSet argument: "ENERGY BOMB"

; VERIFIED: Equipment list: ENERGY UNIT when EnergyUnitFitted is nonzero.
L_D168:
    LD A,(EnergyUnitFitted)                    ; $D168: 3A 4D A8  EnergyUnitFitted: energy unit
    CALL PrintInlineTokenIfSet                 ; $D16B: CD 9C D1
    defb $72                                   ; $D16E: 72  PrintInlineTokenIfSet argument: "ENERGY UNIT"

; VERIFIED: Equipment list: DOCKING COMPUTERS when DockingComputerFitted is nonzero.
L_D16F:
    LD A,(DockingComputerFitted)               ; $D16F: 3A 4E A8  DockingComputerFitted: docking computers
    CALL PrintInlineTokenIfSet                 ; $D172: CD 9C D1
    defb $73                                   ; $D175: 73  PrintInlineTokenIfSet argument: "DOCKING COMPUTERS"

; VERIFIED: Equipment list: GALACTIC HYPERSPACE when GalacticHyperdriveFitted is nonzero.
L_D176:
    LD A,(GalacticHyperdriveFitted)            ; $D176: 3A 4F A8  GalacticHyperdriveFitted: galactic hyperspace
    CALL PrintInlineTokenIfSet                 ; $D179: CD 9C D1
    defb $74                                   ; $D17C: 74  PrintInlineTokenIfSet argument: "GALACTIC HYPERSPACE"

; VERIFIED: Equipment list: one PrintLaserMount call for each byte of LaserMounts..L_A842 (front, rear,
; left, right; StatusLaserMountIndex starts at $FF), then CLOAKING DEVICE for CommanderFlags
; bit 6 (last line, no new line) and the screen frame (tail jump to DrawScreenFrame).
L_D17D:
    LD A,$FF                                   ; $D17D: 3E FF  mount index -1: first increment selects FRONT
    LD (StatusLaserMountIndex),A               ; $D17F: 32 B8 D0
    LD HL,LaserMounts                          ; $D182: 21 3F A8  laser type per mount: front, rear, left, right
    LD B,$04                                   ; $D185: 06 04
L_D187:
    PUSH BC                                    ; $D187: C5
    CALL PrintLaserMount                       ; $D188: CD AE D1  one mount; HL advances to the next byte
    POP BC                                     ; $D18B: C1
    DJNZ L_D187                                ; $D18C: 10 F9
    LD A,(CommanderFlags)                      ; $D18E: 3A 72 A8  CommanderFlags bit 6: cloaking device
    BIT 6,A                                    ; $D191: CB 77
    JR Z,L_D199                                ; $D193: 28 04
    CALL PrintInlineToken                      ; $D195: CD 99 BA  last line: no new line follows
    defb $7D                                   ; $D198: 7D  PrintInlineToken argument: "CLOAKING DEVICE"
L_D199:
    JP DrawScreenFrame                         ; $D199: C3 C7 BC  draw the screen frame and return (DrawScreenFrame)

; VERIFIED: Read the inline token byte after the CALL; if A is nonzero print that token and fall
; into NewLineAtColumn5, else return after the inline byte without printing.
; Used for equipment items: A = the item's commander-record byte (any nonzero value prints).
; Clobbers: B, HL, flags; when the item is printed also what PrintToken and NewLine change.
; Evidence: tools/check_routines.py commander/p7-docked-screen-text.
PrintInlineTokenIfSet:
    POP HL                                     ; $D19C: E1
    LD B,(HL)                                  ; $D19D: 46  B = inline token code
    INC HL                                     ; $D19E: 23
    PUSH HL                                    ; $D19F: E5
    AND A                                      ; $D1A0: A7  A = 0: item not fitted, skip it
    RET Z                                      ; $D1A1: C8
    LD A,B                                     ; $D1A2: 78
    CALL PrintToken                            ; $D1A3: CD 9D BA  print the item name

; VERIFIED: NewLine, then text column 5 (the indentation of the equipment list).
NewLineAtColumn5:
    CALL NewLine                               ; $D1A6: CD FA AF
    LD A,$05                                   ; $D1A9: 3E 05  equipment indentation: column 5
    JP SetTextColumn                           ; $D1AB: C3 11 B0  tail jump: TextColumn = 5

; VERIFIED: Advance StatusLaserMountIndex, read the laser type at HL (HL+1 on return).  Type 0: no
; output.  Otherwise print token $60+index (FRONT/REAR/LEFT/RIGHT) and a space, then the
; laser: type 1..2 -> token $66+type (PULSE LASER, BEAM LASER), type 3..4 -> token
; $72+type (MILITARY LASER, MINING LASER), and NewLineAtColumn5.
; Input: HL = the mount's byte in LaserMounts..L_A842.  Output: HL + 1 (kept across the printing).
; Evidence: decoded tokens; caller loops over LaserMounts..L_A842; tools/check_routines.py
; commander/p7-docked-screen-text (all four types on all four mounts).
PrintLaserMount:
    LD A,(StatusLaserMountIndex)               ; $D1AE: 3A B8 D0
    INC A                                      ; $D1B1: 3C
    LD (StatusLaserMountIndex),A               ; $D1B2: 32 B8 D0
    LD A,(HL)                                  ; $D1B5: 7E  laser type of this mount; 0 = none
    INC HL                                     ; $D1B6: 23
    AND A                                      ; $D1B7: A7
    RET Z                                      ; $D1B8: C8
    PUSH HL                                    ; $D1B9: E5
    PUSH AF                                    ; $D1BA: F5
    LD A,(StatusLaserMountIndex)               ; $D1BB: 3A B8 D0
    ADD A,$60                                  ; $D1BE: C6 60  tokens $60..$63: FRONT, REAR, LEFT, RIGHT
    CALL PrintTokenSpace                       ; $D1C0: CD EF AF  mount name and a space
    POP AF                                     ; $D1C3: F1
    CP $03                                     ; $D1C4: FE 03
    JR C,L_D1CC                                ; $D1C6: 38 04
    LD B,$72                                   ; $D1C8: 06 72  types 3..4: MILITARY/MINING LASER ($75/$76)
    JR L_D1CE                                  ; $D1CA: 18 02
L_D1CC:
    LD B,$66                                   ; $D1CC: 06 66  types 1..2: PULSE/BEAM LASER ($67/$68)
L_D1CE:
    ADD A,B                                    ; $D1CE: 80
    CALL PrintToken                            ; $D1CF: CD 9D BA  laser name
    POP HL                                     ; $D1D2: E1  HL = next mount byte
    JR NewLineAtColumn5                        ; $D1D3: 18 D1

; VERIFIED: Set text column 21, print ':' and then token A followed by a new line.
; Token A waits in the alternate AF (EX AF,AF') while the column and ':' are printed.
; Callers: ShowCommanderStatus with A = 2 (present system) and A = 3 (hyperspace system).
PrintColonTokenAtColumn21:
    EX AF,AF'                                  ; $D1D5: 08  keep token A
    CALL SetTextColumnInline                   ; $D1D6: CD 0D B0
    defb $15                                   ; $D1D9: 15  SetTextColumnInline argument: text column 21
    CALL PrintInlineToken                      ; $D1DA: CD 99 BA
    defb $3A                                   ; $D1DD: 3A  PrintInlineToken argument: ":"
    EX AF,AF'                                  ; $D1DE: 08
    JP PrintTokenNewLine                       ; $D1DF: C3 F7 AF  tail jump: token A and a new line

; VERIFIED: Rating thresholds for a kill count below 256 (compared with the low byte CombatScoreLow):
; count <= 8 HARMLESS ($15), <= 16 MOSTLY HARMLESS, <= 32 POOR, <= 64 AVERAGE,
; <= 128 ABOVE AVERAGE, otherwise COMPETENT ($1A).  The $FF entry ends the search.
; Evidence: tools/check_routines.py commander/rating-thresholds checks all bands.
RatingKillThresholdsLow:
    defb $08                                                                              ; $D1E2 .  kills 0..8: HARMLESS
    defb $10                                                                              ; $D1E3 .  9..16: MOSTLY HARMLESS
    defb $20                                                                              ; $D1E4    17..32: POOR
    defb $40                                                                              ; $D1E5 @  33..64: AVERAGE
    defb $80                                                                              ; $D1E6 .  65..128: ABOVE AVERAGE
    defb $FF                                                                              ; $D1E7 .  end marker: 129..255 COMPETENT

; VERIFIED: Rating thresholds for a kill count of 256 or more (compared with the high byte CombatScoreHigh):
; high byte <= 2 COMPETENT ($1A), <= 10 DANGEROUS, <= 25 DEADLY, otherwise
; "---- E L I T E ----" ($1D); i.e. counts 768, 2816 and 6656 start the higher ratings.
RatingKillThresholdsHigh:
    defb $02                                                                              ; $D1E8 .  high byte 1..2 (256..767): COMPETENT
    defb $0A                                                                              ; $D1E9 .  high byte 3..10 (768..2815): DANGEROUS
    defb $19                                                                              ; $D1EA .  high byte 11..25 (2816..6655): DEADLY
    defb $FF                                                                              ; $D1EB .  end marker: 6656 and more ELITE

; VERIFIED: Full-screen message on white/red (attribute $17): "SHIP BOARDED BY" at column 3, row 7,
; message A (the boarders: 13 "PIRATE" from CheckPirateGameOver or $D4 "THARGON" from L_7832), "S",
; then "THEY SHOW NO MERCY..." at column 4, row 11; wait for a key and continue at L_D20A.
; Only caller: EndGameWithMessage at docking, when pirates boarded the station during the last
; hyperspace arrival (CheckPirateGameOver) or when docking at the station the Thargons hold
; (mission-3 state 4, CheckMissionStateOnDocking).  The caller then restarts through RunTitleScreen.
ShowShipBoardedScreen:
    PUSH AF                                    ; $D1EC: F5
    LD DE,$0B17                                ; $D1ED: 11 17 0B  D = message $0B "SHIP BOARDED BY", E = attribute $17
    LD HL,$0703                                ; $D1F0: 21 03 07  column 3, row 7
    CALL ShowColouredMessageScreen             ; $D1F3: CD 58 D2  clear, colour every cell $17, print "SHIP BOARDED BY"
    POP AF                                     ; $D1F6: F1
    CALL PrintMessage                          ; $D1F7: CD D7 BA  message A: PIRATE or THARGON
    LD A,$5D                                   ; $D1FA: 3E 5D  plural "S", then two 36-frame pauses (message $5D)
    CALL PrintMessage                          ; $D1FC: CD D7 BA
    LD HL,$0B04                                ; $D1FF: 21 04 0B  column 4, row 11
    LD (TextColumn),HL                         ; $D202: 22 0D A8
    LD A,$FF                                   ; $D205: 3E FF  message 255: "THEY SHOW NO MERCY..."
    CALL PrintMessage                          ; $D207: CD D7 BA

; VERIFIED: Shared end of the message screens: beep if enabled (BeepIfSoundOn), wait for a key (WaitForKeyPress),
; clear the screen (ClearScreenAndFrame), call Wait36Frames and continue at ResetFlightInputs.
L_D20A:
    CALL BeepIfSoundOn                         ; $D20A: CD 39 AF  beep if sound is enabled
    CALL WaitForKeyPress                       ; $D20D: CD 48 AF  wait for a key
    CALL ClearScreenAndFrame                   ; $D210: CD 9E BC  clear the screen
    CALL Wait36Frames                          ; $D213: CD AF B0  36-frame pause
    JP ResetFlightInputs                       ; $D216: C3 FF 7B  tail jump: reset the flight inputs and key state

; VERIFIED: Show message $DF "WANTED BY GALCOP: A BRAVE COMMANDER FOR A SPECIAL MISSION ...
; ARE YOU INTERESTED (Y/N)?" on attribute $1F and wait for a key.  Not 'Y': InvasionMissionState = 0 and
; return.  'Y': set CommanderFlags bit 7, InvasionMissionState = 3 and show the briefing message
; $E0 ("THE THARGONS ARE USING THE SPACE STATION AT ... YOUR MISSION: TO DESTROY THE SPACE
; STATION ...") on attribute $17, then wait for a key (ShowMessageScreenAndWait).
; Reached at docking (CheckMissionStateOnDocking) while the mission-3 state InvasionMissionState is 1 or 2.  The states, from
; the code that writes and tests InvasionMissionState: 1 set by the trigger at 254 jumps (L_D853, which also
; sets CommanderFlags bit 2, so a declined offer never returns), 2 after the next arrival;
; 0 declined here; 3 accepted here; 4 on arrival in the galaxy's first system (L_D7E1),
; 3 again on leaving it; 5 on the arrival after a missile hit the station there
; (UpdateMissileGuidance, L_D7AC).  Docking with 4 ends the game (Thargons board, message $D4),
; docking with 5 calls AwardHighestHonour.  L_ED83 tests CommanderFlags bit 7 in state 4.
; Evidence: decoded messages; the status screen prints "E.C.M.SYSTEM JAMMER" for bit 7;
; instruction semantics of the writers named above; tools/check_routines.py
; missions/hyperspace-arrival for the arrival transitions.
OfferSpecialMission:
    LD DE,$DF1F                                ; $D219: 11 1F DF  D = message $DF (mission offer), E = attribute $1F
    LD HL,$0405                                ; $D21C: 21 05 04  column 5, row 4
    CALL ShowColouredMessageScreen             ; $D21F: CD 58 D2
    CALL WaitForKeyPress                       ; $D222: CD 48 AF  A = key code
    CP $59                                     ; $D225: FE 59  'Y' accepts
    JR Z,L_D22E                                ; $D227: 28 05
    XOR A                                      ; $D229: AF  declined: InvasionMissionState = 0
    LD (InvasionMissionState),A                ; $D22A: 32 71 A8
    RET                                        ; $D22D: C9
L_D22E:
    LD HL,CommanderFlags                       ; $D22E: 21 72 A8
    SET 7,(HL)                                 ; $D231: CB FE  CommanderFlags bit 7: E.C.M. jammer (status screen)
    LD A,$03                                   ; $D233: 3E 03  accepted: InvasionMissionState = 3
    LD (InvasionMissionState),A                ; $D235: 32 71 A8
    LD DE,$E017                                ; $D238: 11 17 E0  D = message $E0 (mission briefing), E = attribute $17
    LD HL,$0200                                ; $D23B: 21 00 02  column 0, row 2

; VERIFIED: ShowColouredMessageScreen (D = message, E = attribute, L = column, H = row), then the
; shared key wait at L_D20A.  Also called by SellCargoScreen for message $0F "YOU HAVE SAVED OUR
; LIVES".  Returns through ResetFlightInputs.
ShowMessageScreenAndWait:
    CALL ShowColouredMessageScreen             ; $D23E: CD 58 D2
    JR L_D20A                                  ; $D241: 18 C7

; VERIFIED: Add 256 to the kill count (INC CombatScoreHigh), clear InvasionMissionState, set CommanderFlags bit 3
; and show message $0A "IN APPRECIATION OF YOUR EXCEPTIONAL COURAGE THE INHABITANTS OF ...
; AWARD YOU THEIR HIGHEST HONOUR." on attribute $0F (white on blue).  Entered from L_7832 at
; docking with mission-3 state 5 (see OfferSpecialMission): the end of the special mission.
; CommanderFlags bit 3 is also an input of the save security number (AccessMenuSave).
AwardHighestHonour:
    LD HL,CombatScoreHigh                      ; $D243: 21 24 A8
    INC (HL)                                   ; $D246: 34  kill count high byte + 1: 256 kill points
    XOR A                                      ; $D247: AF  InvasionMissionState = 0
    LD (InvasionMissionState),A                ; $D248: 32 71 A8
    LD HL,CommanderFlags                       ; $D24B: 21 72 A8
    SET 3,(HL)                                 ; $D24E: CB DE  CommanderFlags bit 3
    LD DE,$0A0F                                ; $D250: 11 0F 0A  D = message $0A (highest honour), E = attribute $0F
    LD HL,$0500                                ; $D253: 21 00 05  column 0, row 5
    JR ShowMessageScreenAndWait                ; $D256: 18 E6

; VERIFIED: Clear the screen (ClearScreenAndFrame), print message $5C (control 19: capitalise the next letter), set
; the text position from HL (L = column, H = row), fill all 768 attribute cells from $5800 with
; E and print message D (tail jump to PrintMessage).
; Callers: BuyCargoScreen (message $5B "THE SUN IS GOING NOVA"), ShowShipBoardedScreen,
; OfferSpecialMission, ShowMessageScreenAndWait.
ShowColouredMessageScreen:
    PUSH HL                                    ; $D258: E5
    PUSH DE                                    ; $D259: D5
    CALL ClearScreenAndFrame                   ; $D25A: CD 9E BC  clear the screen (attributes $07) and draw the frame
    LD A,$5C                                   ; $D25D: 3E 5C  message $5C: capitalise the next letter
    CALL PrintMessage                          ; $D25F: CD D7 BA
    POP DE                                     ; $D262: D1
    POP HL                                     ; $D263: E1
    LD (TextColumn),HL                         ; $D264: 22 0D A8  L = column, H = row
    LD HL,$5800                                ; $D267: 21 00 58  attribute area: 768 cells
    LD BC,$0300                                ; $D26A: 01 00 03
L_D26D:
    LD (HL),E                                  ; $D26D: 73  B = 3 outer passes of 256 (C starts at 0)
    INC HL                                     ; $D26E: 23
    DEC C                                      ; $D26F: 0D
    JR NZ,L_D26D                               ; $D270: 20 FB
    DEC B                                      ; $D272: 05
    JR NZ,L_D26D                               ; $D273: 20 F8
    LD A,D                                     ; $D275: 7A  print message D
    JP PrintMessage                            ; $D276: C3 D7 BA  tail jump

; VERIFIED: Inventory screen (CurrentScreenId = $0C): title token $A4 "INVENTORY", FUEL and CASH
; (token controls 5 and 7), "LARGE CARGO BAY" with an attribute bar when LargeCargoBayFitted is set,
; "REFUGEES" when CommanderFlags bit 5 is set, then each held cargo item (PrintCargoLine, items 0..16).
; Rows: FUEL 3, CASH 4, LARGE CARGO BAY 6 (attributes $05, columns 1..30), REFUGEES 7, cargo
; from row 8, or row 7 without refugees (row 6 stays empty without the cargo bay).
; Callers: screen function 8 (L_A7F2) and the ends of the cargo screens (L_B2BF, L_B318,
; SellCargoScreen, L_B4FE).
; Evidence: decoded tokens/messages; runtime docked-inventory; tools/check_routines.py
; commander/p7-docked-screen-text.
ShowInventory:
    LD A,$0C                                   ; $D279: 3E 0C  screen id $0C: inventory
    LD (CurrentScreenId),A                     ; $D27B: 32 41 70
    LD A,$96                                   ; $D27E: 3E 96  message 150: "{cls}{rule}{caps}{col4-cap}"
    CALL PrintMessage                          ; $D280: CD D7 BA  clear the screen, frame and title rule, capitals
    LD A,$A4                                   ; $D283: 3E A4  token $A4 "INVENTORY" as the title (PrintScreenTitle)
    CALL PrintScreenTitle                      ; $D285: CD 57 B0
    LD DE,InventoryAttributeLayout             ; $D288: 11 A6 FB  attribute bar list for ColourAttributeStrips
    CALL ColourAttributeStrips                 ; $D28B: CD DF BB
    LD A,$03                                   ; $D28E: 3E 03  row 3
    CALL SetTextRow                            ; $D290: CD 19 B0
    CALL PrintInlineToken                      ; $D293: CD 99 BA
    defb $05                                   ; $D296: 05  PrintInlineToken argument: token control 5, FUEL line
    LD A,$07                                   ; $D297: 3E 07  token control 7: CASH line
    CALL PrintTokenNewLine                     ; $D299: CD F7 AF  CASH line on row 4, then a new line (row 6 next)
    LD A,(LargeCargoBayFitted)                 ; $D29C: 3A 46 A8  LargeCargoBayFitted: large cargo bay
    AND A                                      ; $D29F: A7
    JR Z,L_D2AE                                ; $D2A0: 28 0C
    LD HL,$58C1                                ; $D2A2: 21 C1 58  attribute cell row 6, column 1
    LD A,$05                                   ; $D2A5: 3E 05
    CALL FillAttributeRow30                    ; $D2A7: CD CB BB  columns 1..30 of row 6 in attribute $05
    CALL PrintInlineToken                      ; $D2AA: CD 99 BA  LARGE CARGO BAY on row 6
    defb $6B                                   ; $D2AD: 6B  PrintInlineToken argument: "LARGE CARGO BAY"
L_D2AE:
    CALL NewLine                               ; $D2AE: CD FA AF  row 7 next, even without the cargo bay
    LD A,(CommanderFlags)                      ; $D2B1: 3A 72 A8  CommanderFlags bit 5: refugees on board
    BIT 5,A                                    ; $D2B4: CB 6F
    JR Z,L_D2C0                                ; $D2B6: 28 08
    LD A,$0C                                   ; $D2B8: 3E 0C  message 12: "REFUGEES"
    CALL PrintMessage                          ; $D2BA: CD D7 BA
    CALL NewLine                               ; $D2BD: CD FA AF  cargo starts on the next row
L_D2C0:
    XOR A                                      ; $D2C0: AF
    LD (CurrentCommodity),A                    ; $D2C1: 32 30 AF
    LD HL,CargoHold-1                          ; $D2C4: 21 2C A8  cargo count pointer (PrintCargoLine adds 1 first)
    LD (CargoPointer),HL                       ; $D2C7: 22 31 AF
L_D2CA:
    CALL PrintCargoLine                        ; $D2CA: CD B9 AF  print item CurrentCommodity if held (carry clear)
    CALL NC,NewLine                            ; $D2CD: D4 FA AF  held item: new line
    LD HL,CurrentCommodity                     ; $D2D0: 21 30 AF  next commodity
    INC (HL)                                   ; $D2D3: 34
    LD A,(HL)                                  ; $D2D4: 7E
    CP $11                                     ; $D2D5: FE 11  17 cargo items
    JR C,L_D2CA                                ; $D2D7: 38 F1
    RET                                        ; $D2D9: C9

; ============================================================================
; Access menu: commander tape load and save
; Message 1 "ACCESS MENU": 1 load, 2 save, 3 exit.  The 104-byte commander record
; at ActiveCommanderRecord is transferred by the ROM tape routines.
; ============================================================================

; INFERRED: Two zero bytes with no static or runtime reference; unused padding.
L_D2DA:
    defs 2,0                                                                              ; $D2DA..$D2DB

; VERIFIED: Attribute bar list for ColourAttributeStrips (access menu): each byte = (cells << 3) + rows to move
; down; ColourAttributeStrips colours that many cells with attribute 5 from column 1 and stops after an
; entry with zero rows.  Bars: 1 cell (row 1), 2 cells (rows 5, 7 and 9), 16 cells (row 12,
; behind the "SECURITY NUMBER:" label that AccessMenuSave prints at column 1, row 12).  Like
; every list, ColourAttributeStrips then sets $5822/$5823 to $07 (already $07 after the clear).
AccessMenuAttributeBars:
    defb $0C                                                                              ; $D2DC .  $0C: 1 cell on row 1, then 4 rows down
    defb $12                                                                              ; $D2DD .  $12: 2 cells on row 5, then 2 rows down
    defb $12                                                                              ; $D2DE .  $12: 2 cells on row 7, then 2 rows down
    defb $13                                                                              ; $D2DF .  $13: 2 cells on row 9, then 3 rows down
    defb $80                                                                              ; $D2E0 .  $80: 16 cells on row 12; 0 rows ends the list

; VERIFIED: Access menu result: cleared on entry, set to 1 whenever a record has been read from tape,
; even one that LoadCommanderRecord then rejects for its name; returned in A (and as NZ) when
; the menu exits.  Evidence: tools/check_routines.py commander/p7-tape-load-paths.
CommanderLoadedFlag:
    defb $00                                                                              ; $D2E1 .

; VERIFIED: Stack pointer saved on entry to the access menu (LD (nn),SP at $D2FD) and restored at
; the top of every key loop iteration, so the tape paths can jump back to AccessMenuKeyLoop.
AccessMenuStackPointer:
    defw $0000                                                                            ; $D2E2

; VERIFIED: Access menu: clear the screen, colour bars, print message 1 ("ACCESS MENU ... 1 LOAD NEW
; COMMANDER ... 2 SAVE COMMANDER ... 3 EXIT") and loop on keys '1' (load), '2' (save) and
; '3' (exit).  Output: A = CommanderLoadedFlag, NZ if any record was read from tape.
; Callers: the title prompt "LOAD NEW COMMANDER (Y/N)?" on 'Y' (L_71A2), continuing at L_71BE;
; and the docked main loop's access-menu key (L_72A2), which restarts through L_71BE on NZ (the
; next game starts from CommanderTemplateBuffer) and otherwise shows the status screen and stays
; docked with ActiveCommanderRecord as it is.
; Evidence: decoded message; runtime access-menu scenario (keys 1 and 3).
RunAccessMenu:
    CALL ClearScreenAndFrame                   ; $D2E4: CD 9E BC  clear the screen
    LD DE,AccessMenuAttributeBars              ; $D2E7: 11 DC D2  access-menu attribute bars
    CALL ColourAttributeStrips                 ; $D2EA: CD DF BB
    CALL ColourPromptRow                       ; $D2ED: CD C6 BB  attribute bar on row 21
    LD A,$0F                                   ; $D2F0: 3E 0F  attribute $0F for rows 0..2 (ColourBannerRows)
    CALL ColourBannerRows                      ; $D2F2: CD 49 B7  plus a full-width line at pixel row 23
    XOR A                                      ; $D2F5: AF  no commander loaded yet
    LD (CommanderLoadedFlag),A                 ; $D2F6: 32 E1 D2
    INC A                                      ; $D2F9: 3C
    CALL PrintMessage                          ; $D2FA: CD D7 BA  message 1: ACCESS MENU
    LD (AccessMenuStackPointer),SP             ; $D2FD: ED 73 E2 D2  remember the stack for the key loop

; VERIFIED: Restore the menu stack (AccessMenuStackPointer) and wait for a key.
AccessMenuKeyLoop:
    LD SP,(AccessMenuStackPointer)             ; $D301: ED 7B E2 D2  tape paths jump back here with any stack depth
    CALL WaitForKeyPress                       ; $D305: CD 48 AF  wait for a key
    SUB $31                                    ; $D308: D6 31  '1': load
    JR Z,AccessMenuLoad                        ; $D30A: 28 14
    DEC A                                      ; $D30C: 3D  '2': save
    JP Z,AccessMenuSave                        ; $D30D: CA 5A D3
    DEC A                                      ; $D310: 3D  '3': exit; other keys are ignored
    JR NZ,AccessMenuKeyLoop                    ; $D311: 20 EE
    CALL BeepAndWait                           ; $D313: CD F8 B3  beep and redraw (BeepAndWait)
    CALL ClearInputFlags                       ; $D316: CD 56 AF  clear the key state
    LD A,(CommanderLoadedFlag)                 ; $D319: 3A E1 D2  A = 1 and NZ if a commander was loaded
    AND A                                      ; $D31C: A7
    RET NZ                                     ; $D31D: C0
    XOR A                                      ; $D31E: AF  A = 0 and Z
    RET                                        ; $D31F: C9

; VERIFIED: Load: ask for the commander name into NameInputBuffer (PromptCommanderName, message 8 "COMMANDER'S NAME? ",
; at most 10 characters), then load records until one matches.
AccessMenuLoad:
    LD HL,NameInputBuffer                      ; $D320: 21 25 AC  typed commander name buffer
    CALL PromptCommanderName                   ; $D323: CD 25 D4  input the name (message 8, up to 10 characters)

; VERIFIED: Load one headerless 104-byte record (flag $FF) into ActiveCommanderRecord through the
; ROM LD-BYTES loop.  The ROM prologue (INC D / EX AF,AF' / DEC D / DI) is repeated here and the
; ROM is entered at $0562, skipping its white border and the SA/LD-RET exit (which would
; restore the border from BORDCR and raise the BASIC "BREAK" error).
; Success: CommanderLoadedFlag = 1, message $D6 "FOUND COMMANDER {name}", then compare the
; typed name with the loaded one: an empty typed name or equal names (up to 11 bytes
; including the zero terminator) accept the record (CopyCommanderToTemplate); otherwise the
; next record is loaded over it.  Failure: TapeLoadFailed.
; Evidence: ROM entry points; tools/check_routines.py commander/p7-tape-load-paths (LD-BYTES
; stubbed: register set, name matching, flag, template copy).
LoadCommanderRecord:
    CALL SetCommanderTapeParameters            ; $D326: CD 1B D4  IX = ActiveCommanderRecord, DE = 104, A = $FF
    SCF                                        ; $D329: 37  carry set: LOAD rather than VERIFY
    INC D                                      ; $D32A: 14  ROM LD-BYTES prologue ($0556..$0559)
    EX AF,AF'                                  ; $D32B: 08
    DEC D                                      ; $D32C: 15
    DI                                         ; $D32D: F3
    CALL RomLdBytesAfterSetup                  ; $D32E: CD 62 05  load 104 bytes; carry set on success
    EI                                         ; $D331: FB
    JP NC,TapeLoadFailed                       ; $D332: D2 FF D3  tape error or BREAK
    LD A,$01                                   ; $D335: 3E 01  CommanderLoadedFlag = 1
    LD (CommanderLoadedFlag),A                 ; $D337: 32 E1 D2  set for any record read, even if rejected below
    LD A,$D6                                   ; $D33A: 3E D6  message $D6: "FOUND COMMANDER" and the loaded name
    CALL PrintStatusLineMessage                ; $D33C: CD 2C D4  bottom status line (row 22), beep if enabled
    LD HL,NameInputBuffer                      ; $D33F: 21 25 AC  typed name
    LD DE,ActiveCommanderRecord                ; $D342: 11 16 A8  loaded name (record +0)
    LD A,(HL)                                  ; $D345: 7E
    AND A                                      ; $D346: A7
    JP Z,CopyCommanderToTemplate               ; $D347: CA E2 D3  empty typed name: accept any record
    LD B,$0B                                   ; $D34A: 06 0B  at most 11 bytes including the terminator
L_D34C:
    LD A,(DE)                                  ; $D34C: 1A
    CP (HL)                                    ; $D34D: BE
    JR NZ,LoadCommanderRecord                  ; $D34E: 20 D6  names differ: load the next record
    OR (HL)                                    ; $D350: B6  equal bytes: zero means both names ended
    JP Z,CopyCommanderToTemplate               ; $D351: CA E2 D3
    INC HL                                     ; $D354: 23
    INC DE                                     ; $D355: 13
    DJNZ L_D34C                                ; $D356: 10 F4
    JR LoadCommanderRecord                     ; $D358: 18 CC  no terminator within 11 bytes: load the next record

; VERIFIED: Save: input the commander name straight into the record (PromptCommanderName), copy the nine bytes at
; SunPosition into record bytes +$5D..+$65 (SavedSunPosition), print message 2 "START TAPE, THEN PRESS ANY
; KEY", wait for a key and write the 104-byte record with ROM SA-BYTES entered at $04C6
; (after its SA/LD-RET push).  Black border, EI.  BREAK: ReportTapeBreak.  Success: message $97
; "COMMANDER SAVED", then "SECURITY NUMBER: " and two decimal numbers (HL, then DE with
; leading zeros) computed from the kill count, galaxy, CommanderFlags bits 3/6 and word CashHigh,
; and CopyCommanderToTemplate (a save also becomes the restart snapshot).
; The two numbers appear as one digit string: HL is printed with the field width and leading
; zero state that PrintDecimalHL leaves behind (0 and suppressed), DE as exactly five digits.
; On BREAK the typed name and the nine sun bytes are already in the record; the template is
; not updated.
; Evidence: decoded messages, ROM entry points; tools/check_routines.py
; commander/security-number (Python model of HL and DE) and commander/p7-security-number-print
; (printed text).
AccessMenuSave:
    LD HL,ActiveCommanderRecord                ; $D35A: 21 16 A8  name field of the active record
    CALL PromptCommanderName                   ; $D35D: CD 25 D4  input the name into the record
    LD HL,SunPosition                          ; $D360: 21 65 70  nine bytes at SunPosition
    LD DE,SavedSunPosition                     ; $D363: 11 73 A8  to record +$5D..+$65
    LD BC,$0009                                ; $D366: 01 09 00
    LDIR                                       ; $D369: ED B0
    LD A,$02                                   ; $D36B: 3E 02  message 2: START TAPE, THEN PRESS ANY KEY
    CALL PrintStatusLineMessage                ; $D36D: CD 2C D4  bottom status line (row 22), beep if enabled
    CALL WaitForKeyPress                       ; $D370: CD 48 AF  wait for a key
    CALL SetCommanderTapeParameters            ; $D373: CD 1B D4  IX = ActiveCommanderRecord, DE = 104, A = $FF
    CALL RomSaBytesAfterSetup                  ; $D376: CD C6 04  save 104 bytes
    LD A,$00                                   ; $D379: 3E 00  black border
    OUT ($FE),A                                ; $D37B: D3 FE
    EI                                         ; $D37D: FB
    JP NC,ReportTapeBreak                      ; $D37E: D2 07 D4  BREAK: message "BREAK"
    LD A,$97                                   ; $D381: 3E 97  message $97: COMMANDER SAVED
    CALL PrintStatusLineMessage                ; $D383: CD 2C D4  bottom status line (row 22), beep if enabled
    LD HL,$0C01                                ; $D386: 21 01 0C  column 1, row 12
    LD (TextColumn),HL                         ; $D389: 22 0D A8
    LD A,$04                                   ; $D38C: 3E 04  message 4: "SECURITY NUMBER: "
    CALL PrintMessage                          ; $D38E: CD D7 BA  label on row 12 (coloured by AccessMenuAttributeBars)
    LD HL,(CombatScoreLow)                     ; $D391: 2A 23 A8  kill count word
    RL L                                       ; $D394: CB 15  carry = bit 7 of the low byte
    LD E,H                                     ; $D396: 5C
    RL E                                       ; $D397: CB 13  E = kill count >> 7 (low eight bits)
    LD A,(CurrentGalaxy)                       ; $D399: 3A 27 A8  galaxy number
    LD HL,CommanderFlags                       ; $D39C: 21 72 A8  mission flags
    BIT 3,(HL)                                 ; $D39F: CB 5E  CommanderFlags bit 3 -> bit 3
    JR Z,L_D3A5                                ; $D3A1: 28 02
    SET 3,A                                    ; $D3A3: CB DF
L_D3A5:
    BIT 6,(HL)                                 ; $D3A5: CB 76  CommanderFlags bit 6 -> bit 4
    JR Z,L_D3AB                                ; $D3A7: 28 02
    SET 4,A                                    ; $D3A9: CB E7
L_D3AB:
    LD HL,(CashHigh)                           ; $D3AB: 2A 28 A8  word CashHigh
    RLCA                                       ; $D3AE: 07  D = (galaxy and flags) rotated left three times
    RLCA                                       ; $D3AF: 07
    RLCA                                       ; $D3B0: 07
    LD D,A                                     ; $D3B1: 57
    LD A,E                                     ; $D3B2: 7B
    CALL RotateParityIntoD                     ; $D3B3: CD F0 D3  parity of E into D
    LD A,H                                     ; $D3B6: 7C
    CALL RotateParityIntoD                     ; $D3B7: CD F0 D3  parity of H into D
    LD A,L                                     ; $D3BA: 7D
    CALL RotateParityIntoD                     ; $D3BB: CD F0 D3  parity of L into D
    LD A,L                                     ; $D3BE: 7D
    XOR D                                      ; $D3BF: AA
    ADD A,$3D                                  ; $D3C0: C6 3D  D = (L XOR D) + $3D
    LD D,A                                     ; $D3C2: 57
    XOR E                                      ; $D3C3: AB
    ADD A,$66                                  ; $D3C4: C6 66  E = (D XOR E) + $66
    LD E,A                                     ; $D3C6: 5F
    XOR H                                      ; $D3C7: AC
    ADD A,$8F                                  ; $D3C8: C6 8F  H = (E XOR H) + $8F
    LD H,A                                     ; $D3CA: 67
    XOR L                                      ; $D3CB: AD
    ADD A,$C7                                  ; $D3CC: C6 C7  L = (H XOR L) + $C7
    LD L,A                                     ; $D3CE: 6F
    PUSH DE                                    ; $D3CF: D5  second number
    AND A                                      ; $D3D0: A7
    CALL PrintDecimalHL                        ; $D3D1: CD 60 B7  first number: HL
    LD A,$05                                   ; $D3D4: 3E 05  field width 5
    LD (NumberFieldWidth),A                    ; $D3D6: 32 8E A8  second number: exactly five digits
    XOR A                                      ; $D3D9: AF  print leading zeros
    LD (LeadingZeroFlag),A                     ; $D3DA: 32 8D A8
    POP HL                                     ; $D3DD: E1
    AND A                                      ; $D3DE: A7
    CALL PrintDecimalHL                        ; $D3DF: CD 60 B7  second number (the pushed DE)

; VERIFIED: Copy the 102 persistent bytes of ActiveCommanderRecord to CommanderTemplateBuffer (the
; restart snapshot) after a successful load or save, then return to AccessMenuKeyLoop.
; This is the only writer of the template (static references and all runtime traces); a new
; game (InitialiseCommander) starts from it and a tape loading error restores it.
CopyCommanderToTemplate:
    LD HL,ActiveCommanderRecord                ; $D3E2: 21 16 A8
    LD DE,CommanderTemplateBuffer              ; $D3E5: 11 10 A9  restart snapshot (InitialiseCommander starts from it)
    LD BC,CommanderTemplateBufferSize          ; $D3E8: 01 66 00  102 persistent record bytes
    LDIR                                       ; $D3EB: ED B0

; VERIFIED: Return to AccessMenuKeyLoop (target of the tape message paths at ReportTapeBreak/ReportTapeLoadingError).
L_D3ED:
    JP AccessMenuKeyLoop                       ; $D3ED: C3 01 D3

; VERIFIED: Count the set bits of A in C (B = 8 RRA steps) and rotate the parity (bit 0 of C) into
; bit 7 of D (RR C / RR D).  Clobbers: A, B, C, flags.  Used by the security number.
RotateParityIntoD:
    LD B,$08                                   ; $D3F0: 06 08
    LD C,$00                                   ; $D3F2: 0E 00  C = number of set bits
L_D3F4:
    RRA                                        ; $D3F4: 1F
    JR NC,L_D3F8                               ; $D3F5: 30 01
    INC C                                      ; $D3F7: 0C
L_D3F8:
    DJNZ L_D3F4                                ; $D3F8: 10 FA
    RR C                                       ; $D3FA: CB 19  carry = parity
    RR D                                       ; $D3FC: CB 1A  parity into bit 7 of D
    RET                                        ; $D3FE: C9

; VERIFIED: LD-BYTES returned with carry clear: HALT for the next keyboard scan; if the key code
; LastKeyCode is ' ' (BREAK) print "BREAK" (ReportTapeBreak), otherwise "TAPE LOADING ERROR" and restore
; the active record from the snapshot via CopyCommanderTemplate (ReportTapeLoadingError); both return to the menu loop.
; After BREAK the bytes LD-BYTES had already stored stay in ActiveCommanderRecord.  After an
; error the record returns to CommanderTemplateBuffer, the state of the last load, save or
; game start, so a docked commander loses the progress made since then.
; Evidence: tools/check_routines.py commander/p7-tape-load-paths (stubbed LD-BYTES with a
; partial record).
TapeLoadFailed:
    HALT                                       ; $D3FF: 76  wait for the interrupt keyboard scan
    LD A,(LastKeyCode)                         ; $D400: 3A 13 FC  key code after a failed load ($FF = none)
    CP $20                                     ; $D403: FE 20  key code $20 -> BREAK, otherwise TAPE LOADING ERROR
    JR NZ,ReportTapeLoadingError               ; $D405: 20 0A

; VERIFIED: Stop a tape operation: clear the status lines (ClearPromptLines), print message $C7
; "BREAK" on the status line and return to the access-menu loop at L_D3ED.
; Reached by JP NC after a failed ROM save ($D37E) and after a failed load when the key
; code in LastKeyCode is $20.  The active record is not restored: after a BREAK during a
; load the bytes already read stay in ActiveCommanderRecord.
; Evidence: decoded message $C7; tools/check_routines.py commander/p7-tape-load-paths.
ReportTapeBreak:
    CALL ClearPromptLines                      ; $D407: CD BC B0
    LD A,$C7                                   ; $D40A: 3E C7  message 199: "BREAK"
    CALL PrintStatusLineMessage                ; $D40C: CD 2C D4
    JR L_D3ED                                  ; $D40F: 18 DC  back to the access-menu loop

; VERIFIED: Failed load: print message 3 "TAPE LOADING ERROR", copy the commander snapshot back into
; ActiveCommanderRecord (CopyCommanderTemplate) and return to the access-menu loop at L_D3ED.
; Evidence: decoded message 3; docs/COMMANDER-STATE.md for CopyCommanderTemplate.
ReportTapeLoadingError:
    LD A,$03                                   ; $D411: 3E 03  message 3: "TAPE LOADING ERROR"
    CALL PrintStatusLineMessage                ; $D413: CD 2C D4
    CALL CopyCommanderTemplate                 ; $D416: CD 2D 7C  restore ActiveCommanderRecord from the snapshot
    JR L_D3ED                                  ; $D419: 18 D2

; VERIFIED: IX = ActiveCommanderRecord, DE = ActiveCommanderRecordSize (104 bytes), A = $FF (data
; block flag): the register set of the ROM LD-BYTES ($0562) and SA-BYTES ($04C6) entries.
; Changes only A, DE and IX.
; Evidence: both callers (LoadCommanderRecord, $D373) enter the ROM directly after this call.
SetCommanderTapeParameters:
    LD IX,ActiveCommanderRecord                ; $D41B: DD 21 16 A8
    LD DE,ActiveCommanderRecordSize            ; $D41F: 11 68 00  tape block length: 104 bytes
    LD A,$FF                                   ; $D422: 3E FF  flag byte $FF: data block
    RET                                        ; $D424: C9

; VERIFIED: Read a commander name: A = message 8 "COMMANDER'S NAME? ", B = 10 characters maximum,
; HL = destination supplied by the caller; tail-jump to the line-input routine InputString
; (stores the typed characters at HL followed by a zero byte).
; Callers: AccessMenuLoad (search name in NameInputBuffer before a load),
; AccessMenuSave (ActiveCommanderRecord).
PromptCommanderName:
    LD B,$0A                                   ; $D425: 06 0A  at most 10 characters
    LD A,$08                                   ; $D427: 3E 08  message 8 "COMMANDER'S NAME? "
    JP InputString                             ; $D429: C3 1D B1  tail call: prompt, read and zero-terminate the name

; VERIFIED: Print message A on the bottom status line: LetterCaseMode = 0 (title case),
; TextColumn = 0, TextRow = $16, clear that text line (FillPromptRow22 with A = 0),
; print the message, NewLine, then BeepIfSoundOn (ROM beep when bit 7 of ControlOptions is set).
; Used for the tape messages FOUND COMMANDER, START TAPE..., COMMANDER SAVED, BREAK and
; TAPE LOADING ERROR.  Clobbers AF, BC, DE, HL.
PrintStatusLineMessage:
    PUSH AF                                    ; $D42C: F5
    XOR A                                      ; $D42D: AF
    LD (LetterCaseMode),A                      ; $D42E: 32 91 A8  LetterCaseMode 0: title case
    LD HL,$1600                                ; $D431: 21 00 16  column 0, row $16
    LD (TextColumn),HL                         ; $D434: 22 0D A8
    CALL FillPromptRow22                       ; $D437: CD CB B0  clear the status text line (A = 0)
    POP AF                                     ; $D43A: F1
    CALL PrintMessage                          ; $D43B: CD D7 BA  message A
    CALL NewLine                               ; $D43E: CD FA AF
    JP BeepIfSoundOn                           ; $D441: C3 39 AF  tail call: beep if sound is on

; VERIFIED: Delay between mission MAYDAY broadcasts.
; When zero, CheckFlightWarnings reloads it with 70 and tests the mission states;
; otherwise each idle warning check only decrements it.
MissionMessageDelay:
    defb $00                                                                              ; $D444 .

; VERIFIED: Updates remaining for the current flight message.
; 14 for ordinary messages (ShowFlightMessage), 21 for the hyperspace messages (L_D5C2).
; The text is printed only while the value before the decrement is 4 or more, so the
; last three updates leave the line empty.
FlightMessageTimer:
    defb $00                                                                              ; $D445 .

; VERIFIED: Incremented whenever no message is shown; bit 0 alternates between the status-warning
; check (CheckFlightWarnings, odd) and the scan of the pending-message table PendingMessageTable (even).
FlightMessageAlternator:
    defb $00                                                                              ; $D446 .

; VERIFIED: Text column of the current flight message (row 14).
FlightMessageColumn:
    defb $00                                                                              ; $D447 .

; VERIFIED: Token of the current flight message.
; $FD (" DESTROYED") follows the item token in DestroyedItemToken; $E2 (" CR") follows
; LastBountyAmount.  DamageEquipmentOrCargo suppresses a new equipment loss while $FD is shown;
; ClearPendingFlightMessages zeroes it.
FlightMessageToken:
    defb $00                                                                              ; $D448 .

; VERIFIED: Bounty word in tenths of a credit for the " CR" message, stored by AwardBounty when nonzero.
; L_DB43 passes blueprint bytes +8/+9 (bounty, docs/SHIPS.md) to AwardBounty.
LastBountyAmount:
    defw $0000                                                                            ; $D449

; VERIFIED: Token printed before " DESTROYED": L_A61A stores $6C+item for a lost equipment item
; ($73 = "DOCKING COMPUTERS", printed without the 3-column indent).
DestroyedItemToken:
    defb $F5                                                                              ; $D44B .

; ============================================================================
; Flight view title and message line
; View name overlay, timed in-flight messages, warnings and mission MAYDAY calls.
; ============================================================================

; VERIFIED: Text overlay for the current screen.
; Flight views (CurrentScreenId 0..3): set bit 7 of the character renderer's screen-base
; high byte (L_BB81, operand of LD HL,$4000 at LoadCharacterScreenBase) so text goes to
; ViewBitmapBuffer, print token $60+view ("FRONT".."RIGHT") and " VIEW " at column 10
; row 1, update the message line (UpdateFlightMessage), then restore the $40 screen base.
; Other screens: patch CharacterBlendOpcode to NOP (overwrite), run UpdateFlightMessage and
; restore XOR C ($A9).  Also sets LetterCaseMode = 0 (title case).
; Runtime: every flight-view trace.
PrintViewTitleAndMessages:
    XOR A                                      ; $D44C: AF
    LD (LetterCaseMode),A                      ; $D44D: 32 91 A8  LetterCaseMode 0: title case
    LD A,(CurrentScreenId)                     ; $D450: 3A 41 70
    CP $04                                     ; $D453: FE 04  flight views are 0..3
    JR C,L_D465                                ; $D455: 38 0E  flight view: title and message into the view buffer
    LD HL,CharacterBlendOpcode                 ; $D457: 21 BF BB
    LD (HL),$00                                ; $D45A: 36 00  SMC: CharacterBlendOpcode = NOP, characters overwrite
    CALL UpdateFlightMessage                   ; $D45C: CD 86 D4  message line in overwrite mode
    LD HL,CharacterBlendOpcode                 ; $D45F: 21 BF BB
    LD (HL),$A9                                ; $D462: 36 A9  SMC: restore XOR C ($A9)
    RET                                        ; $D464: C9
L_D465:
    LD HL,L_BB81                               ; $D465: 21 81 BB  flight views: title into the view buffer
    SET 7,(HL)                                 ; $D468: CB FE  SMC: screen base $40xx -> $C0xx, text into ViewBitmapBuffer
    LD HL,$010A                                ; $D46A: 21 0A 01  column 10, row 1
    LD (TextColumn),HL                         ; $D46D: 22 0D A8
    LD A,(CurrentScreenId)                     ; $D470: 3A 41 70
    ADD A,$60                                  ; $D473: C6 60  tokens $60..$63: FRONT, REAR, LEFT, RIGHT
    CALL PrintToken                            ; $D475: CD 9D BA
    LD A,$AF                                   ; $D478: 3E AF  token: " VIEW "
    CALL PrintTokenNewLine                     ; $D47A: CD F7 AF
    CALL UpdateFlightMessage                   ; $D47D: CD 86 D4  message line into the view buffer too
    LD HL,L_BB81                               ; $D480: 21 81 BB
    RES 7,(HL)                                 ; $D483: CB BE  SMC: restore screen base $40xx
    RET                                        ; $D485: C9

; VERIFIED: Once per main-loop pass: UpdateHyperspaceCountdown and UpdateConditionIndicator, then the message line.
; While FlightMessageTimer is nonzero, decrement it and redraw the message.
; Otherwise toggle FlightMessageAlternator: odd -> CheckFlightWarnings; even -> take the
; first pending entry of the 9-entry table PendingMessageTable (bit 7 of the column byte = pending,
; next byte = token), clear its bit 7 and show it with a beep.  At most one pending
; message is taken per call; nothing pending: return.
UpdateFlightMessage:
    CALL UpdateHyperspaceCountdown             ; $D486: CD F5 D5  countdown digits; may start the jump
    CALL UpdateConditionIndicator              ; $D489: CD BD A4  condition colour and missile cell
    LD HL,FlightMessageTimer                   ; $D48C: 21 45 D4
    LD A,(HL)                                  ; $D48F: 7E  A = remaining updates of the current message
    AND A                                      ; $D490: A7
    JR NZ,L_D4C1                               ; $D491: 20 2E  a message is being shown
    LD HL,FlightMessageAlternator              ; $D493: 21 46 D4
    INC (HL)                                   ; $D496: 34  count idle updates
    BIT 0,(HL)                                 ; $D497: CB 46  odd: status warnings
    JR NZ,CheckFlightWarnings                  ; $D499: 20 65
    LD B,$09                                   ; $D49B: 06 09  9 entries of (column+pending bit 7, token)
    LD HL,PendingMessageTable                  ; $D49D: 21 7F A8
L_D4A0:
    BIT 7,(HL)                                 ; $D4A0: CB 7E  bit 7 = pending
    JR NZ,L_D4A9                               ; $D4A2: 20 05
    INC HL                                     ; $D4A4: 23  next 2-byte entry
    INC HL                                     ; $D4A5: 23
    DJNZ L_D4A0                                ; $D4A6: 10 F8
    RET                                        ; $D4A8: C9  nothing pending
L_D4A9:
    RES 7,(HL)                                 ; $D4A9: CB BE  take this message
    LD C,(HL)                                  ; $D4AB: 4E  C = text column
    INC HL                                     ; $D4AC: 23
    LD B,(HL)                                  ; $D4AD: 46  B = token

; VERIFIED: Beep (BeepIfSoundOn), then show token B at column C (falls into ShowFlightMessage).
BeepAndShowFlightMessage:
    PUSH BC                                    ; $D4AE: C5
    CALL BeepIfSoundOn                         ; $D4AF: CD 39 AF  beep (if sound is on)
    POP BC                                     ; $D4B2: C1

; VERIFIED: FlightMessageTimer = 14, then fall into SetFlightMessageText.
ShowFlightMessage:
    LD A,$0E                                   ; $D4B3: 3E 0E  show for 14 updates
    LD (FlightMessageTimer),A                  ; $D4B5: 32 45 D4

; VERIFIED: FlightMessageColumn = C, FlightMessageToken = B.
SetFlightMessageText:
    LD A,C                                     ; $D4B8: 79
    LD (FlightMessageColumn),A                 ; $D4B9: 32 47 D4
    LD A,B                                     ; $D4BC: 78
    LD (FlightMessageToken),A                  ; $D4BD: 32 48 D4
    RET                                        ; $D4C0: C9

; VERIFIED: Message shown: decrement FlightMessageTimer.
; Print only if the old value >= 4 and a flight view is shown: row 14, column
; FlightMessageColumn; tokens $FD and $E2 as described at FlightMessageToken.
L_D4C1:
    DEC (HL)                                   ; $D4C1: 35  one update less; A still holds the old value
    CP $04                                     ; $D4C2: FE 04  old timer value < 4: leave the line empty
    RET C                                      ; $D4C4: D8
    LD A,(CurrentScreenId)                     ; $D4C5: 3A 41 70
    CP $04                                     ; $D4C8: FE 04  only on the four flight views
    RET NC                                     ; $D4CA: D0
    LD A,(FlightMessageColumn)                 ; $D4CB: 3A 47 D4
    LD L,A                                     ; $D4CE: 6F
    LD H,$0E                                   ; $D4CF: 26 0E  row 14
    LD (TextColumn),HL                         ; $D4D1: 22 0D A8
    LD A,(FlightMessageToken)                  ; $D4D4: 3A 48 D4
    CP $FD                                     ; $D4D7: FE FD  " DESTROYED": print the item first
    JR Z,L_D4E5                                ; $D4D9: 28 0A
    CP $E2                                     ; $D4DB: FE E2  " CR": print the bounty first
    JR Z,L_D4F7                                ; $D4DD: 28 18
L_D4DF:
    LD A,(FlightMessageToken)                  ; $D4DF: 3A 48 D4  the message token itself
    JP PrintTokenNewLine                       ; $D4E2: C3 F7 AF  tail call: token and newline
L_D4E5:
    LD A,(DestroyedItemToken)                  ; $D4E5: 3A 4B D4  lost equipment item
    CP $73                                     ; $D4E8: FE 73  "DOCKING COMPUTERS" is printed without the indent
    JR Z,L_D4F2                                ; $D4EA: 28 06
    LD HL,TextColumn                           ; $D4EC: 21 0D A8  indent by three columns
    INC (HL)                                   ; $D4EF: 34
    INC (HL)                                   ; $D4F0: 34
    INC (HL)                                   ; $D4F1: 34
L_D4F2:
    CALL PrintToken                            ; $D4F2: CD 9D BA  print the item name
    JR L_D4DF                                  ; $D4F5: 18 E8
L_D4F7:
    LD HL,(LastBountyAmount)                   ; $D4F7: 2A 49 D4  bounty in tenths of a credit
    SCF                                        ; $D4FA: 37  carry: one decimal place
    CALL PrintDecimalHL                        ; $D4FB: CD 60 B7  print the bounty
    JR L_D4DF                                  ; $D4FE: 18 DF

; VERIFIED: Status warnings, in priority order (B = token, C = column):
; - EnergyBank4 < $9F: switch the cloak off (CloakingDeviceActive = 0), set the view
;   window attributes to L = 7 with FillViewAttributes on a flight view, "ENERGY LOW" at
;   column 10.
; - FuelScoopRangeFlag nonzero (sun within fuel-scoop range) and FuelScoopsFitted:
;   fuel + 1 tenth (SetFuelLevel, capped at 70), "FUEL SCOOPS ON".  Without scoops: nothing.
; - DockingComputerFlag nonzero: "DOCKING COMPUTERS ON".
; - Otherwise every 70th check (MissionMessageDelay): mission-3 state InvasionMissionState = 1 ->
;   "MAYDAY * <name> INVADED*"; mission 1 active (NovaMissionActive) and ExpandingSunActive zero (not yet set
;   by ArmExpandingSun) -> "MAYDAY * CORIOLIS IN DANGER*".
; Runtime: energy/fuel-scoop paths not traced.
CheckFlightWarnings:
    LD A,(EnergyBank4)                         ; $D500: 3A 5A 70  last energy bank
    CP $9F                                     ; $D503: FE 9F  below $9F: ENERGY LOW
    JR C,L_D550                                ; $D505: 38 49
    LD A,(FuelScoopRangeFlag)                  ; $D507: 3A 79 70  set within fuel-scoop range of the sun
    AND A                                      ; $D50A: A7
    JR NZ,L_D53E                               ; $D50B: 20 31
    LD A,(DockingComputerFlag)                 ; $D50D: 3A 7E 70  docking computer active
    AND A                                      ; $D510: A7
    JR NZ,L_D539                               ; $D511: 20 26  active: show "DOCKING COMPUTERS ON"
    LD HL,MissionMessageDelay                  ; $D513: 21 44 D4
    LD A,(HL)                                  ; $D516: 7E
    AND A                                      ; $D517: A7
    JR NZ,L_D532                               ; $D518: 20 18  not due yet: count down
    LD A,$46                                   ; $D51A: 3E 46  next mission broadcast after 70 checks
    LD (HL),A                                  ; $D51C: 77
    LD A,(InvasionMissionState)                ; $D51D: 3A 71 A8  mission-3 state 1?
    DEC A                                      ; $D520: 3D
    JR Z,L_D534                                ; $D521: 28 11  state 1: INVADED broadcast
    LD A,(NovaMissionActive)                   ; $D523: 3A 43 A8  mission 1 active?
    AND A                                      ; $D526: A7
    RET Z                                      ; $D527: C8
    LD A,(ExpandingSunActive)                  ; $D528: 3A 7C A8  set by ArmExpandingSun: broadcasts end
    AND A                                      ; $D52B: A7
    RET NZ                                     ; $D52C: C0
    LD BC,$C202                                ; $D52D: 01 02 C2  token $C2 "MAYDAY * CORIOLIS IN DANGER*", column 2
    JR L_D54D                                  ; $D530: 18 1B
L_D532:
    DEC (HL)                                   ; $D532: 35
    RET                                        ; $D533: C9
L_D534:
    LD BC,$0F03                                ; $D534: 01 03 0F  token $0F "MAYDAY * <name> INVADED*", column 3
    JR L_D54D                                  ; $D537: 18 14
L_D539:
    LD BC,$7B05                                ; $D539: 01 05 7B  token $7B "DOCKING COMPUTERS ON", column 5
    JR L_D54D                                  ; $D53C: 18 0F
L_D53E:
    LD A,(FuelScoopsFitted)                    ; $D53E: 3A 4A A8  fuel scoops fitted?
    AND A                                      ; $D541: A7
    RET Z                                      ; $D542: C8
    LD A,(FuelLevel)                           ; $D543: 3A 44 A8  tenths of a light year
    INC A                                      ; $D546: 3C
    CALL SetFuelLevel                          ; $D547: CD 6D D8  fuel + 1 tenth, capped at 70
    LD BC,$A008                                ; $D54A: 01 08 A0  token $A0 "FUEL SCOOPS ON ", column 8
L_D54D:
    JP ShowFlightMessage                       ; $D54D: C3 B3 D4
L_D550:
    XOR A                                      ; $D550: AF
    LD (CloakingDeviceActive),A                ; $D551: 32 0C A8  low energy switches the cloak off
    LD L,$07                                   ; $D554: 2E 07  attribute colour 7
    LD A,(CurrentScreenId)                     ; $D556: 3A 41 70
    CP $04                                     ; $D559: FE 04
    CALL C,FillViewAttributes                  ; $D55B: DC 87 92  flight view only: view window attributes = L
    LD BC,$640A                                ; $D55E: 01 0A 64  token $64 "ENERGY LOW", column 10
    JR L_D54D                                  ; $D561: 18 EA

; VERIFIED: Clear the pending bit 7 of all 9 entries of PendingMessageTable and zero
; FlightMessageToken (the timer is not changed).  Exit: A = 0, B = 0, HL = end of the
; table.  Callers: PrepareShipForLaunch, InitialiseCommander (new game), ExecuteHyperspaceJump.
ClearPendingFlightMessages:
    LD B,$09                                   ; $D563: 06 09  9 message entries
    LD HL,PendingMessageTable                  ; $D565: 21 7F A8  pending-message table
L_D568:
    RES 7,(HL)                                 ; $D568: CB BE  clear the pending bit
    INC HL                                     ; $D56A: 23
    INC HL                                     ; $D56B: 23
    DJNZ L_D568                                ; $D56C: 10 FA
    XOR A                                      ; $D56E: AF
    LD (FlightMessageToken),A                  ; $D56F: 32 48 D4  no current flight message
    RET                                        ; $D572: C9

; VERIFIED: Hyperspace countdown in message-line updates: 21 when a jump is accepted, 0 when idle.
; UpdateHyperspaceCountdown prints value/2 (10..1) and jumps when it reaches zero.
; Also written by $A9AE.
HyperspaceCountdown:
    defb $00                                                                              ; $D573 .

; ============================================================================
; Hyperspace: keys, countdown, jump and arrival
; Normal and galactic jumps, mis-jump, new-system set-up, jump counter,
; mission triggers and the pirate boarding test.
; ============================================================================

; VERIFIED: Main-loop key check (L_72A2).  If KeyFlagsViews bit 4 (H) or bit 5 (G) is set, both
; are cleared and HyperspaceKeyLatch = 1, before any other test, so a request that is then ignored
; also sets it (CheckDocking returns while it is set; only an arrival or the game-over
; path clears it).  Ignored while HyperspaceCountdown runs.  Docked (FlightCondition = 0):
; print "DOCKED" and show the status screen.  G needs H as well (G alone is consumed
; without effect) and GalacticHyperdriveFitted: JumpTunnelMode = 2, "GALACTIC HYPERSPACE".
; H alone: SnapCursorToNearestSystem selects the target; SelectedSystemDistance 0 is
; ignored silently, >= 256 or above FuelLevel gives "HYPERSPACE RANGE ?"; otherwise
; JumpTunnelMode = 1 and "HYPERSPACE -- <name>".
; An accepted jump sets HyperspaceCountdown = FlightMessageTimer = 21 and beeps.
; Evidence: hyperspace traces press H (bit 4 path); the galactic trace holds G with H;
; tools/check_routines.py missions/r8-docking-contact (G alone sets HyperspaceKeyLatch).
CheckHyperspaceKeys:
    LD HL,KeyFlagsViews                        ; $D574: 21 10 FC
    LD A,(HL)                                  ; $D577: 7E
    AND $30                                    ; $D578: E6 30  bits 4/5: H and G keys
    RET Z                                      ; $D57A: C8
    LD B,A                                     ; $D57B: 47  B = requested key bits
    LD A,(HL)                                  ; $D57C: 7E
    AND $CF                                    ; $D57D: E6 CF  consume both key bits
    LD (HL),A                                  ; $D57F: 77
    LD A,$01                                   ; $D580: 3E 01
    LD (HyperspaceKeyLatch),A                  ; $D582: 32 39 7C  jump-request latch: CheckDocking now returns at once
    LD A,(HyperspaceCountdown)                 ; $D585: 3A 73 D5  countdown already running
    AND A                                      ; $D588: A7
    RET NZ                                     ; $D589: C0
    LD A,(FlightCondition)                     ; $D58A: 3A 62 70  zero while docked
    AND A                                      ; $D58D: A7
    JR Z,L_D5D6                                ; $D58E: 28 46  docked: DOCKED message
    BIT 5,B                                    ; $D590: CB 68  G (bit 5) pressed?
    JR Z,L_D5A6                                ; $D592: 28 12  H alone: normal hyperspace
    BIT 4,B                                    ; $D594: CB 60
    RET Z                                      ; $D596: C8  G without H: ignored
    LD A,(GalacticHyperdriveFitted)            ; $D597: 3A 4F A8  galactic hyperdrive fitted?
    AND A                                      ; $D59A: A7
    RET Z                                      ; $D59B: C8  none fitted: ignored
    LD A,$02                                   ; $D59C: 3E 02  JumpTunnelMode = 2: galactic jump
    LD (JumpTunnelMode),A                      ; $D59E: 32 0A A8
    LD BC,$7406                                ; $D5A1: 01 06 74  token $74 "GALACTIC HYPERSPACE", column 6
    JR L_D5C2                                  ; $D5A4: 18 1C
L_D5A6:
    CALL SnapCursorToNearestSystem             ; $D5A6: CD B3 AC  select the system nearest the chart cursor
    LD HL,(SelectedSystemDistance)             ; $D5A9: 2A 49 AC  distance to the target in tenths of a light year
    LD A,H                                     ; $D5AC: 7C
    AND A                                      ; $D5AD: A7
    JR NZ,L_D5D0                               ; $D5AE: 20 20  25.6 light years or more: out of range
    LD A,L                                     ; $D5B0: 7D
    AND A                                      ; $D5B1: A7
    RET Z                                      ; $D5B2: C8  distance 0 (current system): no jump, no message
    LD B,A                                     ; $D5B3: 47
    LD A,(FuelLevel)                           ; $D5B4: 3A 44 A8  fuel
    SUB B                                      ; $D5B7: 90
    JR C,L_D5D0                                ; $D5B8: 38 16  not enough fuel: out of range
    LD A,$01                                   ; $D5BA: 3E 01  JumpTunnelMode = 1: normal jump
    LD (JumpTunnelMode),A                      ; $D5BC: 32 0A A8
    LD BC,$C005                                ; $D5BF: 01 05 C0  token $C0 "HYPERSPACE -- <name>", column 5
L_D5C2:
    LD A,$15                                   ; $D5C2: 3E 15  21 updates: countdown 10..1
    LD (HyperspaceCountdown),A                 ; $D5C4: 32 73 D5
    LD (FlightMessageTimer),A                  ; $D5C7: 32 45 D4  message stays for the whole countdown
    CALL SetFlightMessageText                  ; $D5CA: CD B8 D4  B = token, C = column
    JP BeepIfSoundOn                           ; $D5CD: C3 39 AF  tail call: beep

; VERIFIED: Target out of range: beep and show "HYPERSPACE RANGE ?" at column 6.
L_D5D0:
    LD BC,$C106                                ; $D5D0: 01 06 C1
    JP BeepAndShowFlightMessage                ; $D5D3: C3 AE D4

; VERIFIED: Hyperspace key while docked: print message $CD "DOCKED" at column 11 row 7, beep and
; continue at the status screen ShowCommanderStatus.
L_D5D6:
    CALL ClearScreenAndFrame                   ; $D5D6: CD 9E BC  clear the screen and draw the frame
    LD HL,$070B                                ; $D5D9: 21 0B 07  column 11, row 7
    LD (TextColumn),HL                         ; $D5DC: 22 0D A8
    LD A,$01                                   ; $D5DF: 3E 01
    LD (LetterCaseMode),A                      ; $D5E1: 32 91 A8  LetterCaseMode 1: capitals
    LD A,$CD                                   ; $D5E4: 3E CD  message 205: "DOCKED"
    CALL PrintMessage                          ; $D5E6: CD D7 BA
    CALL BeepIfSoundOn                         ; $D5E9: CD 39 AF  beep
    CALL Wait36Frames                          ; $D5EC: CD AF B0  pause
    CALL ClearInputFlags                       ; $D5EF: CD 56 AF  drop the key state
    JP ShowCommanderStatus                     ; $D5F2: C3 B9 D0  continue with the status screen

; VERIFIED: If HyperspaceCountdown is nonzero, decrement it; at zero continue with
; ExecuteHyperspaceJump, otherwise print the old value / 2 in a 2-digit field (NumberFieldWidth) at
; column 1 row 1.
UpdateHyperspaceCountdown:
    LD HL,HyperspaceCountdown                  ; $D5F5: 21 73 D5
    LD A,(HL)                                  ; $D5F8: 7E
    AND A                                      ; $D5F9: A7
    RET Z                                      ; $D5FA: C8
    DEC (HL)                                   ; $D5FB: 35
    JR Z,ExecuteHyperspaceJump                 ; $D5FC: 28 12  reached zero: jump now
    LD B,A                                     ; $D5FE: 47  B = old value
    LD A,$02                                   ; $D5FF: 3E 02  two-digit field
    LD (NumberFieldWidth),A                    ; $D601: 32 8E A8
    LD HL,$0101                                ; $D604: 21 01 01  column 1, row 1
    LD (TextColumn),HL                         ; $D607: 22 0D A8
    LD A,B                                     ; $D60A: 78
    SRL A                                      ; $D60B: CB 3F  display 10..1
    JP PrintDecimalA                           ; $D60D: C3 5C B7  tail call: print without a decimal point

; VERIFIED: Countdown expired: ClearPendingFlightMessages.
; JumpTunnelMode = 2 -> GalacticHyperspaceJump, any other value -> NormalHyperspaceJump.
; Runtime: hyperspace and galactic traces.
ExecuteHyperspaceJump:
    CALL ClearPendingFlightMessages            ; $D610: CD 63 D5
    LD A,(JumpTunnelMode)                      ; $D613: 3A 0A A8  jump type: 1 normal, 2 galactic
    SUB $02                                    ; $D616: D6 02
    JR NZ,NormalHyperspaceJump                 ; $D618: 20 40  not 2: normal jump

; VERIFIED: Clear the mission-3 state (InvasionMissionState); if mission 1 is active (NovaMissionActive) clear NovaMissionActive
; and ExpandingSunActive; clear GalacticHyperdriveFitted (always, also when forced by mission 1).
; L_9237 = old galaxy + 1, CurrentGalaxy = (galaxy + 1) AND 7, rotate every byte of the
; three galaxy seed words at GalaxySeeds left by one bit, clear PlayerLegalScore, select
; the system nearest the chart cursor in the new galaxy (SnapCursorToNearestSystem), then
; ArriveInTargetSystem.  No fuel is used.
GalacticHyperspaceJump:
    XOR A                                      ; $D61A: AF
    LD (InvasionMissionState),A                ; $D61B: 32 71 A8  clear mission-3 state
    LD A,(NovaMissionActive)                   ; $D61E: 3A 43 A8  mission 1 active?
    AND A                                      ; $D621: A7
    JR Z,L_D62B                                ; $D622: 28 07
    XOR A                                      ; $D624: AF
    LD (NovaMissionActive),A                   ; $D625: 32 43 A8  mission 1 ends with the forced galactic jump
    LD (ExpandingSunActive),A                  ; $D628: 32 7C A8
L_D62B:
    LD (GalacticHyperdriveFitted),A            ; $D62B: 32 4F A8  galactic hyperdrive used up (A = 0)
    LD A,(CurrentGalaxy)                       ; $D62E: 3A 27 A8
    INC A                                      ; $D631: 3C
    LD (L_9237),A                              ; $D632: 32 37 92  fuel price byte = old galaxy + 1
    AND $07                                    ; $D635: E6 07  eight galaxies
    LD (CurrentGalaxy),A                       ; $D637: 32 27 A8
    LD HL,GalaxySeeds                          ; $D63A: 21 52 A8  three galaxy seed words
    CALL RotateSeedWordLeft                    ; $D63D: CD 4F D6  seed word 0
    CALL RotateSeedWordLeft                    ; $D640: CD 4F D6  seed word 1
    CALL RotateSeedWordLeft                    ; $D643: CD 4F D6  seed word 2
    XOR A                                      ; $D646: AF
    LD (PlayerLegalScore),A                    ; $D647: 32 21 A8  Clean after a galactic jump
    CALL SnapCursorToNearestSystem             ; $D64A: CD B3 AC  target: system nearest the cursor in the new galaxy
    JR ArriveInTargetSystem                    ; $D64D: 18 64  arrive there

; VERIFIED: RLC both bytes of the word at HL; HL += 2.  Clobbers DE.
; Evidence: tools/check_routines.py numbers/fuel-and-seed-helpers.
RotateSeedWordLeft:
    LD E,(HL)                                  ; $D64F: 5E
    RLC E                                      ; $D650: CB 03
    LD (HL),E                                  ; $D652: 73
    INC HL                                     ; $D653: 23
    LD D,(HL)                                  ; $D654: 56
    RLC D                                      ; $D655: CB 02
    LD (HL),D                                  ; $D657: 72
    INC HL                                     ; $D658: 23
    RET                                        ; $D659: C9

; VERIFIED: While mission 1 is active (NovaMissionActive) every jump is a galactic jump.  Otherwise
; fuel = fuel - distance (low byte of SelectedSystemDistance) via SetFuelLevel,
; L_9237 = 2*SelectedSystemEconomy + (70 - new fuel), PlayerLegalScore halved.
; Bit 6 of ControlOptions, or a byte of $F9 at AuxRandomSeed, selects
; EnterHyperspaceMisjump; otherwise ArriveInTargetSystem.
NormalHyperspaceJump:
    LD A,(NovaMissionActive)                   ; $D65A: 3A 43 A8  mission 1 forces a galactic jump
    AND A                                      ; $D65D: A7
    JR NZ,GalacticHyperspaceJump               ; $D65E: 20 BA
    LD A,(SelectedSystemDistance)              ; $D660: 3A 49 AC  distance (low byte)
    LD B,A                                     ; $D663: 47
    LD A,(FuelLevel)                           ; $D664: 3A 44 A8
    SUB B                                      ; $D667: 90
    LD C,A                                     ; $D668: 4F  C = remaining fuel
    CALL SetFuelLevel                          ; $D669: CD 6D D8  fuel = fuel - distance
    LD A,$46                                   ; $D66C: 3E 46  70 = full tank
    SUB C                                      ; $D66E: 91
    LD B,A                                     ; $D66F: 47  B = 70 - remaining fuel
    LD A,(SelectedSystemEconomy)               ; $D670: 3A 4B AC  target economy
    ADD A,A                                    ; $D673: 87
    ADD A,B                                    ; $D674: 80
    LD (L_9237),A                              ; $D675: 32 37 92  fuel price byte = 2*economy + 70 - fuel
    LD HL,PlayerLegalScore                     ; $D678: 21 21 A8
    SRL (HL)                                   ; $D67B: CB 3E  legal score halved by every normal jump
    LD A,(ControlOptions)                      ; $D67D: 3A 14 FC
    BIT 6,A                                    ; $D680: CB 77  forced mis-jump option bit
    JR NZ,EnterHyperspaceMisjump               ; $D682: 20 07
    LD A,(AuxRandomSeed)                       ; $D684: 3A 63 70  random byte
    CP $F9                                     ; $D687: FE F9  mis-jump when the byte is $F9
    JR NZ,ArriveInTargetSystem                 ; $D689: 20 28  normal arrival

; VERIFIED: Mis-jump: WitchspaceFlag = A+1 ($FA, or the option byte + 1 when forced by
; ControlOptions bit 6).  The galactic x/y bytes CurrentSystemX/ChartCursorX and
; CurrentSystemY/ChartCursorY are both set to the 9-bit average of current and target;
; StationPresent = CurrentSystemName = SelectedSystemName = 0; then
; FinishHyperspaceArrival (no new system, no mission or pirate test).
; INFERRED: witchspace; WitchspaceFlag nonzero suppresses the ordinary encounter event
; in UpdateObjects.
EnterHyperspaceMisjump:
    INC A                                      ; $D68B: 3C  $FA, or the option byte + 1
    LD (WitchspaceFlag),A                      ; $D68C: 32 61 70  nonzero: mis-jump state
    LD HL,CurrentSystemX                       ; $D68F: 21 5B A8  x: average of current and target
    LD DE,ChartCursorX                         ; $D692: 11 7D A8
    LD A,(DE)                                  ; $D695: 1A
    ADD A,(HL)                                 ; $D696: 86
    RRA                                        ; $D697: 1F  RRA keeps the carry: 9-bit average
    LD (HL),A                                  ; $D698: 77  both become the midpoint
    LD (DE),A                                  ; $D699: 12
    LD HL,CurrentSystemY                       ; $D69A: 21 59 A8  y: average of current and target
    LD DE,ChartCursorY                         ; $D69D: 11 7E A8
    LD A,(DE)                                  ; $D6A0: 1A
    ADD A,(HL)                                 ; $D6A1: 86
    RR A                                       ; $D6A2: CB 1F
    LD (HL),A                                  ; $D6A4: 77
    LD (DE),A                                  ; $D6A5: 12
    XOR A                                      ; $D6A6: AF
    LD (StationPresent),A                      ; $D6A7: 32 77 70  no station
    LD (CurrentSystemName),A                   ; $D6AA: 32 37 AC  no current system name
    LD (SelectedSystemName),A                  ; $D6AD: 32 40 AC  no selected system name
    JP FinishHyperspaceArrival                 ; $D6B0: C3 14 D8  no new system, no missions or pirates

; VERIFIED: WitchspaceFlag = 0; the target seeds SelectedSystemSeeds (6 bytes) become
; CurrentSystemSeeds; copy the 8-byte name SelectedSystemName -> CurrentSystemName;
; CurrentTechLevel = SelectedSystemTechLevel, CurrentGovernment =
; SelectedSystemGovernment; new market (RandomiseMarket).
; Clear SunPosition and PlanetPosition (9 bytes each), StationDormantFlag = $FF (station
; dormant), then set only their sign/high bytes from the target seeds s0, s1, s2:
; sun x = s2.hi, y = s2.lo (AND $83, OR 1), z = -(((s1.hi OR s1.lo) AND 7) + 4, OR 1);
; planet x = s0.lo, y = s1.lo (AND $83, OR 1), z = +(((s0.hi OR s0.lo) AND 7) + 3).
; The station (slot 0) is placed at the planet position offset by $18000 along z (s2
; bit 0 set) or x, away from the origin when s2 bit 1 is set, otherwise towards it
; (crossing zero for a high magnitude of 1).  Its orientation becomes Y = (0, 1, 0), the
; Z (nose) axis along the offset axis and X along the other horizontal axis; the nose
; points to + when the station's high byte is below the planet's (raw byte compare, sign
; bit included), else to -.  For positive coordinates (always for z) that is towards the
; planet.  For a negative planet x the raw compare is reversed, and so is the
; nose: the docking slot then faces directly away from the planet.
; Over all 2048 systems the offset is along z in galaxies 1, 3, 5 and 8 (all slots face
; the planet) and along x in galaxies 2, 4, 6 and 7, where 464 systems get the reversed
; slot.  Then L_D7B4.
; Evidence: tools/check_routines.py station/arrival-slot-direction.
ArriveInTargetSystem:
    XOR A                                      ; $D6B3: AF
    LD (WitchspaceFlag),A                      ; $D6B4: 32 61 70  leave the mis-jump state
    LD HL,SelectedSystemSeeds                  ; $D6B7: 21 0F AC  target seeds -> current seeds
    LD DE,CurrentSystemSeeds                   ; $D6BA: 11 58 A8
    LD BC,$0006                                ; $D6BD: 01 06 00
    LDIR                                       ; $D6C0: ED B0
    LD HL,SelectedSystemName                   ; $D6C2: 21 40 AC  8-byte name: selected -> current
    LD DE,CurrentSystemName                    ; $D6C5: 11 37 AC
    LD BC,$0008                                ; $D6C8: 01 08 00
    LDIR                                       ; $D6CB: ED B0
    LD A,(SelectedSystemTechLevel)             ; $D6CD: 3A 4D AC  tech level
    LD (CurrentTechLevel),A                    ; $D6D0: 32 5E A8
    LD A,(SelectedSystemGovernment)            ; $D6D3: 3A 4C AC  government
    LD (CurrentGovernment),A                   ; $D6D6: 32 5F A8
    CALL RandomiseMarket                       ; $D6D9: CD 96 AE  new market, fluctuation from AuxRandomSeed
    LD B,$12                                   ; $D6DC: 06 12  sun and planet positions, 9 bytes each
    XOR A                                      ; $D6DE: AF
    LD HL,SunPosition                          ; $D6DF: 21 65 70
L_D6E2:
    LD (HL),A                                  ; $D6E2: 77
    INC HL                                     ; $D6E3: 23
    DJNZ L_D6E2                                ; $D6E4: 10 FC
    LD A,$FF                                   ; $D6E6: 3E FF  station dormant until the player is near it
    LD (StationDormantFlag),A                  ; $D6E8: 32 78 70
    LD HL,(SelectedSystemSeeds)                ; $D6EB: 2A 0F AC  HL = seed s0
    LD DE,(SelectedSystemSeed1)                ; $D6EE: ED 5B 11 AC  DE = seed s1
    LD BC,(SelectedSystemSeed2)                ; $D6F2: ED 4B 13 AC  BC = seed s2
    LD A,B                                     ; $D6F6: 78  sun x from s2 high byte
    AND $83                                    ; $D6F7: E6 83  keep sign bit and two magnitude bits, at least 1
    OR $01                                     ; $D6F9: F6 01
    LD (SunXHigh),A                            ; $D6FB: 32 67 70
    LD A,C                                     ; $D6FE: 79  sun y from s2 low byte
    AND $83                                    ; $D6FF: E6 83
    OR $01                                     ; $D701: F6 01
    LD (SunYHigh),A                            ; $D703: 32 6A 70
    LD A,D                                     ; $D706: 7A  sun z from s1
    OR E                                       ; $D707: B3
    AND $07                                    ; $D708: E6 07
    ADD A,$04                                  ; $D70A: C6 04  magnitude 4..11
    OR $81                                     ; $D70C: F6 81  sign set (behind the player), odd: 5..11
    LD (SunZHigh),A                            ; $D70E: 32 6D 70
    LD A,L                                     ; $D711: 7D  planet x from s0 low byte
    AND $83                                    ; $D712: E6 83
    OR $01                                     ; $D714: F6 01
    LD (PlanetXHigh),A                         ; $D716: 32 70 70
    LD A,E                                     ; $D719: 7B  planet y from s1 low byte
    AND $83                                    ; $D71A: E6 83
    OR $01                                     ; $D71C: F6 01
    LD (PlanetYHigh),A                         ; $D71E: 32 73 70
    LD A,H                                     ; $D721: 7C  planet z from s0
    OR L                                       ; $D722: B5
    AND $07                                    ; $D723: E6 07
    ADD A,$03                                  ; $D725: C6 03  3..10, positive (ahead)
    LD (PlanetZHigh),A                         ; $D727: 32 76 70
    PUSH BC                                    ; $D72A: C5  keep s2 low byte (C) for the station offset
    LD BC,$0009                                ; $D72B: 01 09 00  station position = planet position
    LD HL,PlanetPosition                       ; $D72E: 21 6E 70
    LD DE,InitialRuntimeState                  ; $D731: 11 48 60
    LDIR                                       ; $D734: ED B0
    POP BC                                     ; $D736: C1
    LD A,(PlanetZHigh)                         ; $D737: 3A 76 70  A = planet z high byte
    LD HL,InitialRuntimeState+InstanceZ+1      ; $D73A: 21 4F 60  HL = station z mid byte
    SRL C                                      ; $D73D: CB 39  s2 bit 0 set: offset along z, else along x
    JR C,L_D747                                ; $D73F: 38 06
    LD A,(PlanetXHigh)                         ; $D741: 3A 70 70  offset along x instead
    LD HL,InitialRuntimeState+InstanceX+1      ; $D744: 21 49 60
L_D747:
    SET 7,(HL)                                 ; $D747: CB FE  mid byte $80: $8000 of the offset
    LD B,A                                     ; $D749: 47  B = high byte with sign
    AND $7F                                    ; $D74A: E6 7F  A = high magnitude
    SRL C                                      ; $D74C: CB 39  s2 bit 1 set: away from the origin
    JR C,L_D760                                ; $D74E: 38 10
    CP $01                                     ; $D750: FE 01  magnitude 1: the station crosses zero
    JR NZ,L_D75C                               ; $D752: 20 08
    LD D,A                                     ; $D754: 57
    LD A,B                                     ; $D755: 78
    XOR $80                                    ; $D756: EE 80  flip the sign
    LD B,A                                     ; $D758: 47
    LD A,D                                     ; $D759: 7A
    JR L_D75D                                  ; $D75A: 18 01
L_D75C:
    DEC A                                      ; $D75C: 3D
L_D75D:
    DEC A                                      ; $D75D: 3D  magnitude - 2: $18000 nearer the origin
    JR L_D761                                  ; $D75E: 18 01
L_D760:
    INC A                                      ; $D760: 3C  magnitude + 1: $18000 farther out
L_D761:
    ADD A,A                                    ; $D761: 87  put the sign back into bit 7
    SLA B                                      ; $D762: CB 20
    RR A                                       ; $D764: CB 1F
    INC HL                                     ; $D766: 23
    LD (HL),A                                  ; $D767: 77  station high byte on the offset axis
    XOR A                                      ; $D768: AF
    LD HL,InitialRuntimeState+InstanceAxisZ    ; $D769: 21 51 60  clear the station orientation
    LD B,$12                                   ; $D76C: 06 12
L_D76E:
    LD (HL),A                                  ; $D76E: 77
    INC HL                                     ; $D76F: 23
    DJNZ L_D76E                                ; $D770: 10 FC
    LD HL,PlanetZWord                          ; $D772: 21 75 70  did the offset change the z mid byte?
    LD A,(InitialRuntimeState+InstanceZ+1)     ; $D775: 3A 4F 60
    CP (HL)                                    ; $D778: BE
    LD A,$7F                                   ; $D779: 3E 7F  $7F: unit vector component
    LD (InitialRuntimeState+InstanceAxisY+3),A ; $D77B: 32 5A 60  Y axis = (0, 1, 0)
    JR NZ,L_D799                               ; $D77E: 20 19  z offset
    LD BC,InitialRuntimeState+InstanceAxisX+5  ; $D780: 01 62 60  x offset: X axis z and Z axis x components
    LD DE,InitialRuntimeState+InstanceAxisZ+1  ; $D783: 11 52 60
    LD (BC),A                                  ; $D786: 02  X = (0, 0, 1), Z = (1, 0, 0)
    LD (DE),A                                  ; $D787: 12
    LD HL,PlanetXHigh                          ; $D788: 21 70 70
    LD A,(InitialRuntimeState+InstanceX+2)     ; $D78B: 3A 4A 60
    CP (HL)                                    ; $D78E: BE  x high bytes compared raw (sign included): wrong for negative x
    LD A,$FF                                   ; $D78F: 3E FF
    JR C,L_D796                                ; $D791: 38 03  station below: X axis z = -1
    LD (DE),A                                  ; $D793: 12  otherwise Z axis x = -1
    JR L_D7B4                                  ; $D794: 18 1E
L_D796:
    LD (BC),A                                  ; $D796: 02
    JR L_D7B4                                  ; $D797: 18 1B
L_D799:
    LD BC,InitialRuntimeState+InstanceAxisX+1  ; $D799: 01 5E 60  z offset: X axis x and Z axis z components
    LD DE,InitialRuntimeState+InstanceAxisZ+5  ; $D79C: 11 56 60
    LD HL,PlanetZHigh                          ; $D79F: 21 76 70
    LD A,(InitialRuntimeState+InstanceZ+2)     ; $D7A2: 3A 50 60
    CP (HL)                                    ; $D7A5: BE  station and planet z high bytes
    JR C,L_D7B0                                ; $D7A6: 38 08  station below: both +1
    LD A,$FF                                   ; $D7A8: 3E FF  otherwise both -1
    JR L_D7B2                                  ; $D7AA: 18 06
L_D7AC:
    LD A,$05                                   ; $D7AC: 3E 05  station +$26 bit 7 was set: mission-3 state 5
    JR L_D7EB                                  ; $D7AE: 18 3B
L_D7B0:
    LD A,$7F                                   ; $D7B0: 3E 7F
L_D7B2:
    LD (BC),A                                  ; $D7B2: 02
    LD (DE),A                                  ; $D7B3: 12

; VERIFIED: Arrival tail.
; Copy the galactic x/y bytes ChartCursorX -> CurrentSystemX and ChartCursorY ->
; CurrentSystemY, then the galaxy gate.  In galaxy 0 skip directly to
; FinishHyperspaceArrival.  Otherwise:
; - station +$26 bit 7 set -> clear it, mission-3 state InvasionMissionState = 5;
; - InvasionMissionState 1 -> 2, 4 -> 3; then any nonzero state becomes 4 at the system whose seeds
;   equal the galaxy seeds (CompareWithGalaxySeeds), where UpdateObjects makes the
;   station hostile.
; Evidence: tools/check_routines.py missions/hyperspace-arrival.
L_D7B4:
    LD A,(ChartCursorX)                        ; $D7B4: 3A 7D A8  galactic x/y of the arrival position
    LD (CurrentSystemX),A                      ; $D7B7: 32 5B A8
    LD A,(ChartCursorY)                        ; $D7BA: 3A 7E A8
    LD (CurrentSystemY),A                      ; $D7BD: 32 59 A8
    LD A,(CurrentGalaxy)                       ; $D7C0: 3A 27 A8  galaxy 0: no missions or pirates
    AND A                                      ; $D7C3: A7

; VERIFIED: Galaxy gate.
; CurrentGalaxy = 0 branches to FinishHyperspaceArrival, skipping the jump counter,
; mission triggers and pirate test.  The POKE that changes MissionGalaxyGateOperand
; from $4E to 0 makes this JR fall through, enabling them in galaxy 0.
; Evidence: tools/check_routines.py missions/hyperspace-arrival.
L_D7C4:
; POKE reference: JR offset of the galaxy gate; with 0 the jump counter, missions and pirates also run in galaxy 1 (CurrentGalaxy 0). Original byte $4E.
defc MissionGalaxyGateOperand = L_D7C4 + 1 ; byte inside instruction at $D7C4
    JR Z,FinishHyperspaceArrival               ; $D7C4: 28 4E
    LD HL,InitialRuntimeState+InstanceRoleFlags ; $D7C6: 21 6E 60
    BIT 7,(HL)                                 ; $D7C9: CB 7E  station +$26 bit 7 at arrival
    RES 7,(HL)                                 ; $D7CB: CB BE  clear it
    JR NZ,L_D7AC                               ; $D7CD: 20 DD
    LD HL,InvasionMissionState                 ; $D7CF: 21 71 A8  mission-3 state
    LD A,(HL)                                  ; $D7D2: 7E
    AND A                                      ; $D7D3: A7
    JR Z,L_D7EE                                ; $D7D4: 28 18  state 0: nothing to step
    DEC A                                      ; $D7D6: 3D
    JR NZ,L_D7DC                               ; $D7D7: 20 03
    INC (HL)                                   ; $D7D9: 34  state 1 -> 2
    JR L_D7E1                                  ; $D7DA: 18 05
L_D7DC:
    CP $03                                     ; $D7DC: FE 03  state 4?
    JR NZ,L_D7E1                               ; $D7DE: 20 01
    LD (HL),A                                  ; $D7E0: 77  state 4 -> 3
L_D7E1:
    LD HL,CurrentSystemSeeds                   ; $D7E1: 21 58 A8  current seeds equal to the galaxy seeds?
    CALL CompareWithGalaxySeeds                ; $D7E4: CD 6C D0  carry clear when all six are equal
    JR C,L_D7EE                                ; $D7E7: 38 05  another system: keep the state
    LD A,$04                                   ; $D7E9: 3E 04  state 4: station hostile (UpdateObjects)
L_D7EB:
    LD (InvasionMissionState),A                ; $D7EB: 32 71 A8  store the new mission-3 state

; VERIFIED: Increment the 16-bit jump counter JumpCounter (counted only outside galaxy 0) and test the
; first clear mission flag of CommanderFlags against the counter's low byte:
; bit 0 at >= $20 (mission 1), bit 1 at >= $80, bit 2 at >= $FE.  A trigger skips the
; pirate test; otherwise (or with all three bits set) the pirate test follows.
L_D7EE:
    LD HL,(JumpCounter)                        ; $D7EE: 2A 25 A8  jump counter (outside galaxy 0 only)
    INC HL                                     ; $D7F1: 23
    LD (JumpCounter),HL                        ; $D7F2: 22 25 A8
    LD DE,CommanderFlags                       ; $D7F5: 11 72 A8  mission flags
    LD A,(DE)                                  ; $D7F8: 1A
    RRCA                                       ; $D7F9: 0F
    JR NC,L_D832                               ; $D7FA: 30 36  bit 0 clear: mission 1 test
    RRCA                                       ; $D7FC: 0F
    JR NC,L_D849                               ; $D7FD: 30 4A  bit 1 clear: mission 2 test
    RRCA                                       ; $D7FF: 0F
    JR NC,L_D853                               ; $D800: 30 51  bit 2 clear: mission 3 test

; POKE reference: 3-byte pirate escape patch site; keep original bytes.
; VERIFIED: Pirate boarding test: board when the byte at AuxRandomSeed <= 7 - government
; (CurrentGovernment), i.e. (8 - government) of 256 values.  Boarding clears bit 7
; (continuous roll) of the station's +$1D roll byte, so the station stops rotating;
; CheckPirateGameOver ends the game at docking with the "PIRATES" message when that bit
; is clear.  AuxRandomSeed is the low byte of the dust generator state (AdvanceRandomHL),
; used here as a random byte.
; Evidence: tools/check_routines.py missions/hyperspace-arrival.
PirateEscapePatchSite:
    LD HL,AuxRandomSeed                        ; $D802: 21 63 70
    LD A,(CurrentGovernment)                   ; $D805: 3A 5F A8  government 0..7
    XOR $FF                                    ; $D808: EE FF  7 - government
    AND $07                                    ; $D80A: E6 07
    CP (HL)                                    ; $D80C: BE  compare with the pseudo-random byte

; VERIFIED: Boarding chance branch.
; PirateChanceOperand ($05) skips the boarding store; the POKE value 0 makes every
; non-mission jump outside galaxy 0 board the station.
L_D80D:
; POKE reference: forcing boarding changes this original $05 byte to $00.
defc PirateChanceOperand = L_D80D + 1 ; byte inside instruction at $D80D
    JR C,FinishHyperspaceArrival               ; $D80D: 38 05
    LD HL,InitialRuntimeState+InstanceRoll     ; $D80F: 21 65 60  station roll byte +$1D

; VERIFIED: Boarding store RES 7,(HL); PirateBoardingCompare is its second opcode byte.  The POKE
; $BE -> $FE turns it into SET 7,(HL), so boarding never takes effect.
L_D812:
; POKE reference: disable boarding by changing the original $BE byte to $FE.
defc PirateBoardingCompare = L_D812 + 1 ; byte inside instruction at $D812
    RES 7,(HL)                                 ; $D812: CB BE

; VERIFIED: Common exit of every jump path.
; TunnelLoopActive = 1, CurrentScreenId = 0 (front view); clear CabinTemperature,
; FuelScoopRangeFlag, MissileState, MissionAspEncounterState and the jump-request latch
; HyperspaceKeyLatch; AltitudeGauge = $A0.
FinishHyperspaceArrival:
    LD A,$01                                   ; $D814: 3E 01  TunnelLoopActive = 1
    LD (TunnelLoopActive),A                    ; $D816: 32 0B A8
    XOR A                                      ; $D819: AF
    LD (CurrentScreenId),A                     ; $D81A: 32 41 70  front view
    LD (CabinTemperature),A                    ; $D81D: 32 4C 70  cabin temperature 0
    LD (FuelScoopRangeFlag),A                  ; $D820: 32 79 70  not within fuel-scoop range
    LD (MissileState),A                        ; $D823: 32 0F A8  missile state
    LD (MissionAspEncounterState),A            ; $D826: 32 0C DA  end any mission Asp encounter
    LD (HyperspaceKeyLatch),A                  ; $D829: 32 39 7C  release the jump-request latch
    LD A,$A0                                   ; $D82C: 3E A0
    LD (AltitudeGauge),A                       ; $D82E: 32 50 70  altitude bar full
    RET                                        ; $D831: C9

; VERIFIED: Mission 1 trigger (low byte of the jump counter >= $20): set CommanderFlags bit 0,
; NovaMissionActive = 1, fill the view attributes with colour 2 (FillViewAttributes, L=2) and
; TriggerFuelLeak.
L_D832:
    LD A,L                                     ; $D832: 7D
    CP $20                                     ; $D833: FE 20  mission 1 at 32 jumps
    JR C,PirateEscapePatchSite                 ; $D835: 38 CB  not yet: pirate test
    EX DE,HL                                   ; $D837: EB  HL = mission flags
    SET 0,(HL)                                 ; $D838: CB C6  mission 1 flag
    LD A,$01                                   ; $D83A: 3E 01
    LD (NovaMissionActive),A                   ; $D83C: 32 43 A8  mission 1 active: every jump becomes galactic
    LD L,$02                                   ; $D83F: 2E 02  attribute colour 2
    CALL FillViewAttributes                    ; $D841: CD 87 92  view attributes red
    CALL TriggerFuelLeak                       ; $D844: CD 62 D8  lose all fuel
    JR FinishHyperspaceArrival                 ; $D847: 18 CB

; VERIFIED: Mission 2 trigger (>= $80): set CommanderFlags bit 1.  This bit (with bit 6 clear)
; enables the Asp Mk II encounter at $F62C, tracked by MissionAspEncounterState.
L_D849:
    LD A,L                                     ; $D849: 7D
    CP $80                                     ; $D84A: FE 80  mission 2 at 128 jumps
    JR C,PirateEscapePatchSite                 ; $D84C: 38 B4
    EX DE,HL                                   ; $D84E: EB
    SET 1,(HL)                                 ; $D84F: CB CE  mission 2 flag
    JR FinishHyperspaceArrival                 ; $D851: 18 C1

; VERIFIED: Mission 3 trigger (>= $FE): set CommanderFlags bit 2 and mission-3 state InvasionMissionState = 1.
L_D853:
    LD A,L                                     ; $D853: 7D
    CP $FE                                     ; $D854: FE FE  mission 3 at 254 jumps
    JR C,PirateEscapePatchSite                 ; $D856: 38 AA
    EX DE,HL                                   ; $D858: EB
    SET 2,(HL)                                 ; $D859: CB D6  mission 3 flag
    LD A,$01                                   ; $D85B: 3E 01  mission-3 state 1: MAYDAY INVADED broadcasts
    LD (InvasionMissionState),A                ; $D85D: 32 71 A8
    JR FinishHyperspaceArrival                 ; $D860: 18 B2

; VERIFIED: If fuel (FuelLevel) is nonzero: mark the pending "FUEL LEAK*" message (bit 7 of
; FuelLeakMessage) and set fuel to 0 through SetFuelLevel.
; Callers: mission 1 trigger, damage path DamageEquipmentOrCargo.
TriggerFuelLeak:
    LD A,(FuelLevel)                           ; $D862: 3A 44 A8
    AND A                                      ; $D865: A7
    RET Z                                      ; $D866: C8  no fuel: no message
    LD HL,FuelLeakMessage                      ; $D867: 21 8F A8  pending "FUEL LEAK*" message
    SET 7,(HL)                                 ; $D86A: CB FE
    XOR A                                      ; $D86C: AF  fuel 0 (falls into SetFuelLevel)

; VERIFIED: FuelLevel = min(A, 70) in tenths of a light year; FU bar FuelGauge =
; 2*fuel + (2*fuel >> 3) (70 -> 157).  Clobbers A, B, F.
; Evidence: tools/check_routines.py numbers/fuel-and-seed-helpers (all A).
SetFuelLevel:
    CP $47                                     ; $D86D: FE 47  70 = 7.0 light years
    JR C,L_D873                                ; $D86F: 38 02
    LD A,$46                                   ; $D871: 3E 46  cap at 70
L_D873:
    LD (FuelLevel),A                           ; $D873: 32 44 A8
    ADD A,A                                    ; $D876: 87
    LD B,A                                     ; $D877: 47  B = 2*fuel
    SRL A                                      ; $D878: CB 3F
    SRL A                                      ; $D87A: CB 3F
    SRL A                                      ; $D87C: CB 3F
    ADD A,B                                    ; $D87E: 80  2*fuel + 2*fuel/8
    LD (FuelGauge),A                           ; $D87F: 32 4A 70  FU bar value: 70 -> 157
    RET                                        ; $D882: C9

; ============================================================================
; Chart crosshair
; XOR crosshair with screen-edge and vertical clipping, drawn by the chart screens.
; ============================================================================

; VERIFIED: Arm length of the XOR crosshair in pixels: $18 for the short-range chart centre mark,
; $10 for the cursor (callers L_A9D0, DrawGalacticChart); DrawChartCursor compares it with $0A.
CrosshairSize:
    defb $00                                                                              ; $D883 .

; VERIFIED: First screen row the vertical arm may use.  Only read (stays 0 in the reference).
CrosshairTopLimit:
    defb $00                                                                              ; $D884 .

; VERIFIED: Vertical-arm clip row: $A7 (short-range chart), $98 (galactic chart).
CrosshairBottomLimit:
    defb $00                                                                              ; $D885 .

; VERIFIED: XOR a "+" of size CrosshairSize centred on pixel (ShapeCentreX, ShapeCentreY) of the
; screen at $4000.  The horizontal arm runs from x - size/2; it is clipped at the screen
; edges, and a clipped arm leaves column 0 (left) or 255 (right) untouched.  The vertical
; arm is clipped to CrosshairTopLimit..CrosshairBottomLimit; the centre pixel is toggled
; twice (left clear).  Calling it again erases it.  Clobbers AF, BC, DE, HL.
; Evidence: tools/check_routines.py screen/xor-crosshair.  Callers: chart screens L_A9D0,
; DrawGalacticChart and L_B221.
DrawXorCrosshair:
    LD A,(CrosshairSize)                       ; $D886: 3A 83 D8
    SRL A                                      ; $D889: CB 3F  half arm length
    LD B,A                                     ; $D88B: 47
    LD A,(ShapeCentreX)                        ; $D88C: 3A 13 A8
    SUB B                                      ; $D88F: 90  left end x = centre - size/2
    JR C,L_D8C8                                ; $D890: 38 36
    JR Z,L_D8C8                                ; $D892: 28 34  left end at or beyond the left edge
    LD D,A                                     ; $D894: 57  D = left end x
    LD A,(ShapeCentreY)                        ; $D895: 3A 14 A8
    LD C,A                                     ; $D898: 4F
    LD A,D                                     ; $D899: 7A
    CALL GetPixelScreenAddress                 ; $D89A: CD 7D D9  HL = byte holding the left end
    LD A,(ShapeCentreX)                        ; $D89D: 3A 13 A8
    ADD A,B                                    ; $D8A0: 80  right end x = centre + size/2
    JR C,L_D8EE                                ; $D8A1: 38 4B  beyond the right edge
    AND $07                                    ; $D8A3: E6 07  E = pixels in the right end byte (0 counts as 8)
    JR NZ,L_D8A9                               ; $D8A5: 20 02
    LD A,$08                                   ; $D8A7: 3E 08
L_D8A9:
    LD E,A                                     ; $D8A9: 5F
    LD A,(CrosshairSize)                       ; $D8AA: 3A 83 D8
    SUB E                                      ; $D8AD: 93  C = size - E: pixels before the right end byte
    LD C,A                                     ; $D8AE: 4F
    AND $07                                    ; $D8AF: E6 07  D = pixels in the left end byte (0 counts as 8)
    JR NZ,L_D8B9                               ; $D8B1: 20 06
    LD D,$08                                   ; $D8B3: 16 08
    LD A,C                                     ; $D8B5: 79
    SUB D                                      ; $D8B6: 92
    JR L_D8BB                                  ; $D8B7: 18 02
L_D8B9:
    LD D,A                                     ; $D8B9: 57
    LD A,C                                     ; $D8BA: 79
L_D8BB:
    AND $F8                                    ; $D8BB: E6 F8  full bytes in between
    JR Z,L_D90F                                ; $D8BD: 28 50  none: two adjacent partial bytes
    SRL A                                      ; $D8BF: CB 3F
    SRL A                                      ; $D8C1: CB 3F
    SRL A                                      ; $D8C3: CB 3F  A = number of full bytes
    JP L_D92A                                  ; $D8C5: C3 2A D9
L_D8C8:
    LD A,(ShapeCentreY)                        ; $D8C8: 3A 14 A8  clipped at the left edge: start at x = 0
    LD C,A                                     ; $D8CB: 4F
    XOR A                                      ; $D8CC: AF
    CALL GetPixelScreenAddress                 ; $D8CD: CD 7D D9  HL = byte at x = 0
    LD A,(ShapeCentreX)                        ; $D8D0: 3A 13 A8
    ADD A,B                                    ; $D8D3: 80
    LD C,A                                     ; $D8D4: 4F
    AND $07                                    ; $D8D5: E6 07
    JR NZ,L_D8DF                               ; $D8D7: 20 06
    LD E,$08                                   ; $D8D9: 1E 08
    LD A,C                                     ; $D8DB: 79
    SUB E                                      ; $D8DC: 93
    JR L_D8E1                                  ; $D8DD: 18 02
L_D8DF:
    LD E,A                                     ; $D8DF: 5F
    LD A,C                                     ; $D8E0: 79
L_D8E1:
    AND $F8                                    ; $D8E1: E6 F8
    JR Z,L_D91B                                ; $D8E3: 28 36  right end in the first byte
    SRL A                                      ; $D8E5: CB 3F
    SRL A                                      ; $D8E7: CB 3F
    SRL A                                      ; $D8E9: CB 3F
    JP L_D93F                                  ; $D8EB: C3 3F D9
L_D8EE:
    LD A,(ShapeCentreX)                        ; $D8EE: 3A 13 A8  clipped at the right edge
    LD C,A                                     ; $D8F1: 4F
    XOR A                                      ; $D8F2: AF
    SUB C                                      ; $D8F3: 91
    ADD A,B                                    ; $D8F4: 80  pixels from the left end to the right edge
    LD C,A                                     ; $D8F5: 4F
    AND $07                                    ; $D8F6: E6 07
    JR NZ,L_D900                               ; $D8F8: 20 06
    LD D,$08                                   ; $D8FA: 16 08
    LD A,C                                     ; $D8FC: 79
    SUB D                                      ; $D8FD: 92
    JR L_D902                                  ; $D8FE: 18 02
L_D900:
    LD D,A                                     ; $D900: 57
    LD A,C                                     ; $D901: 79
L_D902:
    AND $F8                                    ; $D902: E6 F8
    JR Z,L_D922                                ; $D904: 28 1C
    SRL A                                      ; $D906: CB 3F
    SRL A                                      ; $D908: CB 3F
    SRL A                                      ; $D90A: CB 3F
    JP L_D954                                  ; $D90C: C3 54 D9
L_D90F:
    CALL MakeLeftPixelMask                     ; $D90F: CD 6D D9  masks for the two partial bytes
    CALL MakeRightPixelMask                    ; $D912: CD 75 D9
    LD A,(HL)                                  ; $D915: 7E  first byte: rightmost D pixels
    XOR D                                      ; $D916: AA
    LD (HL),A                                  ; $D917: 77
    INC HL                                     ; $D918: 23
    JR L_D93C                                  ; $D919: 18 21
L_D91B:
    CALL MakeLeftPixelMask                     ; $D91B: CD 6D D9  left-clipped arm within one byte
    RES 7,E                                    ; $D91E: CB BB  pixel x = 0 left untouched
    JR L_D93C                                  ; $D920: 18 1A
L_D922:
    CALL MakeRightPixelMask                    ; $D922: CD 75 D9  right-clipped arm within one byte
    RES 0,D                                    ; $D925: CB 82  pixel x = 255 left untouched
    JP L_D9A2                                  ; $D927: C3 A2 D9
L_D92A:
    LD B,A                                     ; $D92A: 47  B = full bytes
    CALL MakeLeftPixelMask                     ; $D92B: CD 6D D9
    CALL MakeRightPixelMask                    ; $D92E: CD 75 D9
    LD A,(HL)                                  ; $D931: 7E  first byte: rightmost D pixels
    XOR D                                      ; $D932: AA
    LD (HL),A                                  ; $D933: 77
    INC HL                                     ; $D934: 23
L_D935:
    LD A,(HL)                                  ; $D935: 7E
    XOR $FF                                    ; $D936: EE FF  full byte: all eight pixels
    LD (HL),A                                  ; $D938: 77
    INC HL                                     ; $D939: 23
    DJNZ L_D935                                ; $D93A: 10 F9
L_D93C:
    JP L_D99D                                  ; $D93C: C3 9D D9  last byte, then the vertical arm
L_D93F:
    LD B,A                                     ; $D93F: 47
    CALL MakeLeftPixelMask                     ; $D940: CD 6D D9
    LD A,(HL)                                  ; $D943: 7E
    XOR $7F                                    ; $D944: EE 7F  first byte without pixel x = 0
    LD (HL),A                                  ; $D946: 77
    INC HL                                     ; $D947: 23
    DEC B                                      ; $D948: 05
    JR Z,L_D93C                                ; $D949: 28 F1
L_D94B:
    LD A,(HL)                                  ; $D94B: 7E
    XOR $FF                                    ; $D94C: EE FF
    LD (HL),A                                  ; $D94E: 77
    INC HL                                     ; $D94F: 23
    DJNZ L_D94B                                ; $D950: 10 F9
    JR L_D93C                                  ; $D952: 18 E8
L_D954:
    LD B,A                                     ; $D954: 47
    CALL MakeRightPixelMask                    ; $D955: CD 75 D9
    LD A,(HL)                                  ; $D958: 7E
    XOR D                                      ; $D959: AA
    LD (HL),A                                  ; $D95A: 77
    INC HL                                     ; $D95B: 23
    DEC B                                      ; $D95C: 05
    JR Z,L_D966                                ; $D95D: 28 07
L_D95F:
    LD A,(HL)                                  ; $D95F: 7E
    XOR $FF                                    ; $D960: EE FF
    LD (HL),A                                  ; $D962: 77
    INC HL                                     ; $D963: 23
    DJNZ L_D95F                                ; $D964: 10 F9
L_D966:
    LD A,(HL)                                  ; $D966: 7E
    XOR $FE                                    ; $D967: EE FE  last byte without pixel x = 255
    LD (HL),A                                  ; $D969: 77
    JP L_D9A5                                  ; $D96A: C3 A5 D9  then the vertical arm

; VERIFIED: E = byte with its E leftmost bits set (E = 1..8).  A is also the mask.
MakeLeftPixelMask:
    XOR A                                      ; $D96D: AF
L_D96E:
    SCF                                        ; $D96E: 37  shift a set bit in from the left
    RRA                                        ; $D96F: 1F
    DEC E                                      ; $D970: 1D
    JR NZ,L_D96E                               ; $D971: 20 FB
    LD E,A                                     ; $D973: 5F
    RET                                        ; $D974: C9

; VERIFIED: D = byte with its D rightmost bits set (D = 1..8).  A is also the mask.
MakeRightPixelMask:
    XOR A                                      ; $D975: AF
L_D976:
    SCF                                        ; $D976: 37  shift a set bit in from the right
    RLA                                        ; $D977: 17
    DEC D                                      ; $D978: 15
    JR NZ,L_D976                               ; $D979: 20 FB
    LD D,A                                     ; $D97B: 57
    RET                                        ; $D97C: C9

; VERIFIED: HL = screen bitmap address of the byte holding pixel x = A, y = C.
; Evidence: tools/check_routines.py screen/pixel-screen-address.
GetPixelScreenAddress:
    SRL A                                      ; $D97D: CB 3F
    SRL A                                      ; $D97F: CB 3F
    SRL A                                      ; $D981: CB 3F  L = column (x / 8)
    LD L,A                                     ; $D983: 6F
    LD A,C                                     ; $D984: 79
    AND $38                                    ; $D985: E6 38  y bits 3..5 -> L bits 5..7
    ADD A,A                                    ; $D987: 87
    ADD A,A                                    ; $D988: 87
    OR L                                       ; $D989: B5
    LD L,A                                     ; $D98A: 6F
    LD A,C                                     ; $D98B: 79
    AND $07                                    ; $D98C: E6 07  y bits 0..2 -> H bits 0..2
    OR $40                                     ; $D98E: F6 40  screen at $4000
    LD H,A                                     ; $D990: 67
    LD A,C                                     ; $D991: 79
    AND $C0                                    ; $D992: E6 C0  y bits 6..7 -> H bits 3..4 (screen third)
    SRL A                                      ; $D994: CB 3F
    SRL A                                      ; $D996: CB 3F
    SRL A                                      ; $D998: CB 3F
    OR H                                       ; $D99A: B4
    LD H,A                                     ; $D99B: 67
    RET                                        ; $D99C: C9
L_D99D:
    LD A,(HL)                                  ; $D99D: 7E
    XOR E                                      ; $D99E: AB  last byte: leftmost E pixels
    LD (HL),A                                  ; $D99F: 77
    JR L_D9A5                                  ; $D9A0: 18 03
L_D9A2:
    LD A,(HL)                                  ; $D9A2: 7E
    XOR D                                      ; $D9A3: AA  first byte: rightmost D pixels
    LD (HL),A                                  ; $D9A4: 77

; VERIFIED: Vertical arm of DrawXorCrosshair, clipped to CrosshairTopLimit/CrosshairBottomLimit.
L_D9A5:
    LD A,(CrosshairSize)                       ; $D9A5: 3A 83 D8
    SRL A                                      ; $D9A8: CB 3F  half arm length
    LD B,A                                     ; $D9AA: 47
    LD A,(CrosshairTopLimit)                   ; $D9AB: 3A 84 D8
    LD C,A                                     ; $D9AE: 4F
    LD A,(ShapeCentreY)                        ; $D9AF: 3A 14 A8
    SUB B                                      ; $D9B2: 90  top end y = centre - size/2
    JR C,L_D9D2                                ; $D9B3: 38 1D  above row 0: clip
    CP C                                       ; $D9B5: B9
    JR C,L_D9D2                                ; $D9B6: 38 1A  above the top limit: clip
    LD C,A                                     ; $D9B8: 4F
    LD A,(ShapeCentreX)                        ; $D9B9: 3A 13 A8
    CALL GetPixelScreenAddress                 ; $D9BC: CD 7D D9  HL = top end
    LD A,(CrosshairBottomLimit)                ; $D9BF: 3A 85 D8
    LD C,A                                     ; $D9C2: 4F
    LD A,(ShapeCentreY)                        ; $D9C3: 3A 14 A8
    ADD A,B                                    ; $D9C6: 80
    SUB C                                      ; $D9C7: 91  rows beyond the bottom limit
    LD C,A                                     ; $D9C8: 4F
    LD A,(CrosshairSize)                       ; $D9C9: 3A 83 D8
    JR C,L_D9CF                                ; $D9CC: 38 01  none: the whole arm
    SUB C                                      ; $D9CE: 91  shorten by the overhang
L_D9CF:
    LD B,A                                     ; $D9CF: 47
    JR L_D9E1                                  ; $D9D0: 18 0F
L_D9D2:
    LD D,A                                     ; $D9D2: 57
    LD A,C                                     ; $D9D3: 79
    SUB D                                      ; $D9D4: 92  overhang above the top limit
    LD D,A                                     ; $D9D5: 57
    LD A,(CrosshairSize)                       ; $D9D6: 3A 83 D8
    SUB D                                      ; $D9D9: 92  size - overhang
    LD B,A                                     ; $D9DA: 47
    LD A,(ShapeCentreX)                        ; $D9DB: 3A 13 A8
    CALL GetPixelScreenAddress                 ; $D9DE: CD 7D D9  start at the top limit row (C)
L_D9E1:
    LD A,(ShapeCentreX)                        ; $D9E1: 3A 13 A8
    AND $07                                    ; $D9E4: E6 07  single-pixel mask for x AND 7
    INC A                                      ; $D9E6: 3C
    LD C,A                                     ; $D9E7: 4F
    XOR A                                      ; $D9E8: AF
    SCF                                        ; $D9E9: 37
    RRA                                        ; $D9EA: 1F  bit 7 set, shifted right x AND 7 times
    DEC C                                      ; $D9EB: 0D
    JR Z,L_D9F3                                ; $D9EC: 28 05
L_D9EE:
    SRL A                                      ; $D9EE: CB 3F
    DEC C                                      ; $D9F0: 0D
    JR NZ,L_D9EE                               ; $D9F1: 20 FB
L_D9F3:
    LD E,A                                     ; $D9F3: 5F
L_D9F4:
    LD A,(HL)                                  ; $D9F4: 7E
    XOR E                                      ; $D9F5: AB  toggle one pixel per row
    LD (HL),A                                  ; $D9F6: 77
    INC H                                      ; $D9F7: 24  next pixel row
    LD A,H                                     ; $D9F8: 7C
    AND $07                                    ; $D9F9: E6 07
    CALL Z,AdjustScreenAddressCellRow          ; $D9FB: CC 01 DA  crossed a character cell boundary
    DJNZ L_D9F4                                ; $D9FE: 10 F4
    RET                                        ; $DA00: C9

; VERIFIED: After INC H stepped HL out of a character cell: L += $20, and H -= 8 unless that carried
; into the next screen third.  Evidence: tools/check_routines.py screen/pixel-screen-address.
AdjustScreenAddressCellRow:
    LD A,L                                     ; $DA01: 7D
    ADD A,$20                                  ; $DA02: C6 20  next character row
    LD L,A                                     ; $DA04: 6F
    RET C                                      ; $DA05: D8  carry: next screen third, H already right
    LD A,H                                     ; $DA06: 7C
    SUB $08                                    ; $DA07: D6 08  back to the top pixel line of the cell
    LD H,A                                     ; $DA09: 67
    RET                                        ; $DA0A: C9

; ============================================================================
; Object update loop
; Per-update variables, the eight-slot object loop, removal/explosion handling.
; ============================================================================

; VERIFIED: Projected size of the object being drawn: min(255, 256 * blueprint +1 (size) / depth),
; computed by DivideRatioByte at $E094 once the depth exceeds the size (otherwise the
; object is not drawn and the byte keeps its old value).  L_E0B5 compares the projected
; centre with it (crosshair test); RecordExplosionPosition copies it to instance +$1F when an object with
; +$20 bit 4 set has its screen position recorded.
; Evidence: tools/check_routines.py pipeline/r8-projected-object-size (5 blueprints, 4 views,
; 6 depths: equal to the DivideRatioByte model, copied to +$1F).
ProjectedObjectSize:
    defb $00                                                                              ; $DA0B .

; VERIFIED: Mission Asp encounter state.
; 0 none; 1 set by $F62C when it spawns an Asp Mk II (blueprint 13) marked with
; +$26 bit 6, only if CommanderFlags AND $42 = $02 (mission-2 flag set, bit 6 clear);
; L_F745 switches 1 <-> 2;
; 3 after the marked ship is destroyed ($EC9B).  Cleared on arrival and when the marked
; ship is removed in states 1/2.  INFERRED: the cloaked-Asp mission encounter.
MissionAspEncounterState:
    defb $00                                                                              ; $DA0C .

; INFERRED: Unused byte: no static reference and no access in any runtime trace.
L_DA0D:
    defb $00                                                                              ; $DA0D .

; VERIFIED: Decremented by every UpdateObjects call, so it wraps every 256 updates.
; Reaching 0 dispatches event 0 (random encounter) when allowed.
; Also schedules AI per slot (L_DB71) and gates laser firing ($EC0C).
; HandleTorusJumpKey (Torus jump) sets it to 1, so that the next update dispatches an encounter,
; but only when AlternatingBits was $AA (dust respawns rotate the same byte).
ObjectUpdateCounter:
    defb $00                                                                              ; $DA0E .

; VERIFIED: Set to 1 during UpdateObjects when an active slot has +$26 bit 3 clear: any object
; except the station (initial +$26 = $0C) and the children made by L_F592/L_F5B8 with
; +$26 = $0A (escape capsules, cargo canisters, splinters); ordinary ships, asteroids and
; missiles count (InitialiseShipFromBlueprint clears +$26).  Cleared at the start of
; every update.  Nonzero makes HandleTorusJumpKey refuse the Torus jump; zero after the
; slot loop clears SharedHostilityAlert.
; Evidence: tools/check_routines.py missions/r8-object-presence-flags, dust/torus-jump.
TorusJumpInhibitFlag:
    defb $00                                                                              ; $DA0F .

; VERIFIED: Energy bomb request.
; Set by UseEnergyBomb (key bit 5 of KeyFlagsCombat with EnergyBombFitted, which is used
; up).  The next UpdateObjects sets the explosion bit 4 of +$20 in every active slot
; without +$26 bit 2, unless the blueprint in IY has maximum speed 39 (Thargoid), then
; clears this byte.
; NOTE: IY still holds the previously processed slot's blueprint at that test, so the
; slot after a Thargoid is spared and the Thargoid is not.
; Evidence: tools/check_routines.py missions/energy-bomb-exemption.
EnergyBombPending:
    defb $00                                                                              ; $DA10 .

; VERIFIED: Cleared by UpdateObjects, then set to the energy of each active slot: nonzero when at
; least one slot is active (the station counts).
; Read by DrawFlaggedObjectDiscs and DrawScannerContacts.
LastActiveObjectEnergy:
    defb $00                                                                              ; $DA11 .

; VERIFIED: Slot-loop counter (8 - slot index) of the object found by the projection test at $E0C8,
; 0 = none; cleared every update.  The laser hit at $EC3C converts it back to an instance
; (ApplyPlayerLaserHit) and missile targeting ($A719) locks it into MissileTarget.
TargetedObjectCounter:
    defb $00                                                                              ; $DA12 .

; INFERRED: Unused byte: no static reference and no access in any runtime trace.
L_DA13:
    defb $00                                                                              ; $DA13 .

; VERIFIED: Shared alert raised by an already hostile ship with behaviour bits $20 or $40.
; Trader records and Viper carry those bits; UpdateSharedHostility propagates the alert.
; Separate from PlayerLegalScore; a Clean player can therefore provoke other ships.
; Evidence: $DAD8..$DAF6 and tools/check_bounty_hunters.py.
SharedHostilityAlert:
    defb $00                                                                              ; $DA14 .

; VERIFIED: Manual docking accepted.  Set to 1 only at $EB0C: the player touched the station (an
; object with +$26 bit 2, within its size on all axes) while it is in front, not hostile,
; its nose (Z axis z component) points at the player and |Z.x|, |Z.y| (high bytes) are
; both below $1E.  CheckDocking clears it and docks (DockWithStation), unless the
; jump-request latch HyperspaceKeyLatch is set: then it returns first and the flag stays set.
; LaunchFromStation clears it.  Wider misalignment below $6E costs front damage
; (12 + 2*speed) instead; worse alignment, a hostile station or approach from behind
; sets PlayerDeadFlag = $0F.
; Evidence: tools/check_routines.py missions/r8-docking-contact.
DockingContactFlag:
    defb $00                                                                              ; $DA15 .

; VERIFIED: ECM activity countdown: nonzero lights the E indicator and inhibits AI payload launch.
; Player/AI activation sets this to 10; the ECM update decrements it.
EcmTimer:
    defb $00                                                                              ; $DA16 .

; VERIFIED: Energy drain units collected during one update.
; Cleared by UpdateObjects; +1 for each player laser shot (L_EC11) and for each update with
; the player's ECM running (L_EDA9).  $A59D adds 1 while the cloaking device is on and
; subtracts the total four times from the energy banks (DrainEnergyBanks), bank 1 first.
; Evidence: tools/check_routines.py missions/r8-energy-drain.
EnergyDrainThisUpdate:
    defb $00                                                                              ; $DA17 .

; VERIFIED: Damage collected this update from objects with z >= 0.
; Sources: collisions (L_EB10/L_EB5E) and AI lasers (L_FAF0).  L_A584 subtracts it from
; ForwardShield; overflow drains the energy banks.
FrontDamageThisUpdate:
    defb $00                                                                              ; $DA18 .

; VERIFIED: As FrontDamageThisUpdate for objects with negative z (+8 bit 7); applied to AftShield.
RearDamageThisUpdate:
    defb $00                                                                              ; $DA19 .

; VERIFIED: Cleared by UpdateObjects, then set to the energy of each active slot without +$26 bit 2
; (every object except the station): nonzero when such an object is present.  SetConditionYellowForShips then
; sets the yellow condition (FlightCondition = 6) unless it is red (2) or flashing ($63).
; Evidence: tools/check_routines.py missions/r8-object-presence-flags.
LastNonStationObjectEnergy:
    defb $00                                                                              ; $DA1A .

; VERIFIED: Encounter/traffic count across six allocatable slots; station slot zero is excluded.
; Count only instances with nonzero energy (+$22) and bit 6 set in byte +$20.
; This is not a count of every occupied slot.
; The traffic/encounter gates reject new launches at a count of four or more.
EncounterShipCount:
    defb $00                                                                              ; $DA1B .

; VERIFIED: Counter of the slot being updated: 8 for slot 0 down to 1 for slot 7.  ReleaseTargetLocks compares
; it with +$25 of the other instances and with the locked missile target MissileTarget.
ObjectLoopCounter:
    defb $00                                                                              ; $DA1C .

; VERIFIED: Per-frame object update, called from the flight loops.
; - Mission-3 state 4: set the station's hostile bit (+$21 bit 2).
; - Patch the four pixel-combine opcodes of the line renderer (SteepUpPlotOp, ShallowUpPlotOp, SteepDownPlotOp,
;   ShallowDownPlotOp): OR C ($B1) when LargeSunFlag is zero, XOR C ($A9) otherwise.
; - Decrement ObjectUpdateCounter; at 0 (every 256th update) dispatch event 0 (random
;   encounter) unless the station is present, WitchspaceFlag is set or EncounterShipCount >= 4.
; - Clear the per-update variables, recount EncounterShipCount, then update all 8 slots
;   (L_DA9A); afterwards clear EnergyBombPending and maybe SharedHostilityAlert.
; Clobbers all registers including IX and IY.
UpdateObjects:
    LD A,(InvasionMissionState)                ; $DA1D: 3A 71 A8  mission-3 state
    CP $04                                     ; $DA20: FE 04  mission-3 state 4?
    JR NZ,L_DA29                               ; $DA22: 20 05
    LD HL,InitialRuntimeState+InstanceBehaviour ; $DA24: 21 69 60
    SET 2,(HL)                                 ; $DA27: CB D6  station hostile (+$21 bit 2)
L_DA29:
    LD A,(LargeSunFlag)                        ; $DA29: 3A 7B 70  large sun on screen?
    AND A                                      ; $DA2C: A7
    LD A,$B1                                   ; $DA2D: 3E B1  $B1 = OR C
    JR Z,L_DA33                                ; $DA2F: 28 02  no large sun: OR C
    LD A,$A9                                   ; $DA31: 3E A9  $A9 = XOR C
L_DA33:
    LD (SteepUpPlotOp),A                       ; $DA33: 32 03 F2  SMC: pixel-combine opcode in the line renderer
    LD (ShallowUpPlotOp),A                     ; $DA36: 32 31 F2  SMC: same opcode, second plot loop
    LD (ShallowDownPlotOp),A                   ; $DA39: 32 7E F2  SMC: same opcode, third plot loop
    LD (SteepDownPlotOp),A                     ; $DA3C: 32 52 F2  SMC: same opcode, fourth plot loop
    LD A,(ObjectUpdateCounter)                 ; $DA3F: 3A 0E DA
    DEC A                                      ; $DA42: 3D
    LD (ObjectUpdateCounter),A                 ; $DA43: 32 0E DA
    LD B,A                                     ; $DA46: 47  B = counter: zero once every 256 updates
    LD A,(StationPresent)                      ; $DA47: 3A 77 70  no encounter while the station is present
    AND A                                      ; $DA4A: A7
    JR NZ,L_DA5F                               ; $DA4B: 20 12
    LD A,(WitchspaceFlag)                      ; $DA4D: 3A 61 70  or in the mis-jump state
    AND A                                      ; $DA50: A7
    JR NZ,L_DA5F                               ; $DA51: 20 0C
    LD A,(EncounterShipCount)                  ; $DA53: 3A 1B DA
    CP $04                                     ; $DA56: FE 04  or with four or more ships
    JR NC,L_DA5F                               ; $DA58: 30 05
    LD A,B                                     ; $DA5A: 78
    AND A                                      ; $DA5B: A7
    CALL Z,DispatchShipEvent                   ; $DA5C: CC CA F2  A = 0: random encounter event
L_DA5F:
    XOR A                                      ; $DA5F: AF  clear the per-update totals and flags
    LD (EnergyDrainThisUpdate),A               ; $DA60: 32 17 DA
    LD (RearDamageThisUpdate),A                ; $DA63: 32 19 DA
    LD (FrontDamageThisUpdate),A               ; $DA66: 32 18 DA
    LD (TargetedObjectCounter),A               ; $DA69: 32 12 DA
    LD (LastNonStationObjectEnergy),A          ; $DA6C: 32 1A DA
    LD (LastActiveObjectEnergy),A              ; $DA6F: 32 11 DA
    LD (TorusJumpInhibitFlag),A                ; $DA72: 32 0F DA
    LD C,A                                     ; $DA75: 4F  C = ship count
    LD IX,InitialRuntimeState                  ; $DA76: DD 21 48 60  slot 0; counting starts at slot 1
    LD DE,InstanceSize                         ; $DA7A: 11 27 00
    LD B,$06                                   ; $DA7D: 06 06  six allocatable slots
L_DA7F:
    ADD IX,DE                                  ; $DA7F: DD 19
    LD A,(IX+$22)                              ; $DA81: DD 7E 22
    AND A                                      ; $DA84: A7
    JR Z,L_DA8E                                ; $DA85: 28 07  free slot
    BIT 6,(IX+$20)                             ; $DA87: DD CB 20 76  +$20 bit 6: counted
    JR Z,L_DA8E                                ; $DA8B: 28 01
    INC C                                      ; $DA8D: 0C
L_DA8E:
    DJNZ L_DA7F                                ; $DA8E: 10 EF
    LD A,C                                     ; $DA90: 79
    LD (EncounterShipCount),A                  ; $DA91: 32 1B DA
    LD IX,InitialRuntimeState                  ; $DA94: DD 21 48 60  slot 0 again
    LD A,$08                                   ; $DA98: 3E 08  all eight slots

; VERIFIED: Slot loop: A = ObjectLoopCounter (8..1) is kept on the stack; IX = instance.  Skip slots
; with zero energy.  Record LastActiveObjectEnergy / LastNonStationObjectEnergy /
; TorusJumpInhibitFlag, apply the energy bomb, then UpdateSharedHostility and the state
; dispatch at L_DAFA.  B = counter and C = ObjectUpdateCounter stay set for the AI phase.
L_DA9A:
    PUSH AF                                    ; $DA9A: F5  counter kept for the next slot
    LD B,A                                     ; $DA9B: 47  B = counter (AI phase)
    LD (ObjectLoopCounter),A                   ; $DA9C: 32 1C DA
    LD A,(IX+$22)                              ; $DA9F: DD 7E 22
    AND A                                      ; $DAA2: A7
    JP Z,L_DBBE                                ; $DAA3: CA BE DB  energy 0: free slot
    LD (LastActiveObjectEnergy),A              ; $DAA6: 32 11 DA
    BIT 2,(IX+$26)                             ; $DAA9: DD CB 26 56  not the station: LastNonStationObjectEnergy
    JR NZ,L_DAB2                               ; $DAAD: 20 03
    LD (LastNonStationObjectEnergy),A          ; $DAAF: 32 1A DA
L_DAB2:
    LD A,(ObjectUpdateCounter)                 ; $DAB2: 3A 0E DA
    LD C,A                                     ; $DAB5: 4F  C = ObjectUpdateCounter (AI phase)
    BIT 3,(IX+$26)                             ; $DAB6: DD CB 26 5E  not station or debris: TorusJumpInhibitFlag
    JR NZ,L_DAC1                               ; $DABA: 20 05
    LD A,$01                                   ; $DABC: 3E 01
    LD (TorusJumpInhibitFlag),A                ; $DABE: 32 0F DA
L_DAC1:
    LD A,(EnergyBombPending)                   ; $DAC1: 3A 10 DA  energy bomb pending?
    AND A                                      ; $DAC4: A7
    JR Z,UpdateSharedHostility                 ; $DAC5: 28 11
    BIT 2,(IX+$26)                             ; $DAC7: DD CB 26 56  the station is not affected
    JR NZ,UpdateSharedHostility                ; $DACB: 20 0B
    LD A,(IY+$06)                              ; $DACD: FD 7E 06  NOTE: IY is still the previous slot's blueprint
    CP $27                                     ; $DAD0: FE 27  maximum speed 39: Thargoid
    JR Z,UpdateSharedHostility                 ; $DAD2: 28 04
    SET 4,(IX+$20)                             ; $DAD4: DD CB 20 E6  start the explosion

; VERIFIED: Per-instance update block; IX points at the current ship.
; If it is hostile and has behaviour bits $20/$40, raise SharedHostilityAlert.
; Set its hostility bit 2 when that alert or PlayerMissileEnergy is nonzero.
; There is no legal-score test here. Fall through into the remaining object update.
; Evidence: Clean-player alert and missile fixtures in tools/check_bounty_hunters.py.
UpdateSharedHostility:
    BIT 2,(IX+$21)                             ; $DAD8: DD CB 21 56  hostile?
    JR Z,L_DAEA                                ; $DADC: 28 0C
    LD A,(IX+$21)                              ; $DADE: DD 7E 21
    AND $60                                    ; $DAE1: E6 60  behaviour bits $20/$40
    JR Z,L_DAEA                                ; $DAE3: 28 05
    LD A,$01                                   ; $DAE5: 3E 01  raise the shared alert
    LD (SharedHostilityAlert),A                ; $DAE7: 32 14 DA
L_DAEA:
    LD A,(PlayerMissileEnergy)                 ; $DAEA: 3A 7B 61  player missile in flight?
    AND A                                      ; $DAED: A7
    JR NZ,L_DAF6                               ; $DAEE: 20 06
    LD A,(SharedHostilityAlert)                ; $DAF0: 3A 14 DA  or the shared alert raised?
    AND A                                      ; $DAF3: A7
    JR Z,L_DAFA                                ; $DAF4: 28 04
L_DAF6:
    SET 2,(IX+$21)                             ; $DAF6: DD CB 21 D6  make this object hostile

; VERIFIED: IY = blueprint (+$23/+$24).  +$20 bits 5:4 select: 00 alive (L_DB71), 10 remove and
; credit (L_DB0F), 01/11 exploding: only L_DBA3.
L_DAFA:
    LD H,(IX+$24)                              ; $DAFA: DD 66 24
    LD L,(IX+$23)                              ; $DAFD: DD 6E 23
    PUSH HL                                    ; $DB00: E5
    POP IY                                     ; $DB01: FD E1  IY = blueprint
    LD A,(IX+$20)                              ; $DB03: DD 7E 20
    AND $30                                    ; $DB06: E6 30  state bits 5:4
    JR Z,L_DB71                                ; $DB08: 28 67  00: alive
    SUB $20                                    ; $DB0A: D6 20
    JP NZ,L_DBA3                               ; $DB0C: C2 A3 DB  01 or 11: exploding

; VERIFIED: Remove a destroyed object: clear +$20 bit 5, +$1E = 0, +$1D = $C0.  Unless +$26 bit 0:
; set SoundEffectRequests bit 2 and end MissionAspEncounterState when the marked ship (+$26 bit 6) goes
; in state 1/2, or in state 3 when blueprint +1 is $1E (no reference blueprint has $1E).
; Always continues at L_DB43, which frees the slot.
L_DB0F:
    RES 5,(IX+$20)                             ; $DB0F: DD CB 20 AE
    LD (IX+$1E),A                              ; $DB13: DD 77 1E  pitch counter 0 (A = 0)
    LD A,$C0                                   ; $DB16: 3E C0  $C0: continuous roll
    LD (IX+$1D),A                              ; $DB18: DD 77 1D
    BIT 0,(IX+$26)                             ; $DB1B: DD CB 26 46  missile: no sound, no mission check
    JR NZ,L_DB43                               ; $DB1F: 20 22
    LD HL,SoundEffectRequests                  ; $DB21: 21 7D 70
    SET 2,(HL)                                 ; $DB24: CB D6  SoundEffectRequests bit 2
    LD A,(MissionAspEncounterState)            ; $DB26: 3A 0C DA  mission Asp state
    AND A                                      ; $DB29: A7
    JR Z,L_DB43                                ; $DB2A: 28 17  state 0: just free the slot
    CP $03                                     ; $DB2C: FE 03  state 3?
    JR Z,L_DB38                                ; $DB2E: 28 08
    BIT 6,(IX+$26)                             ; $DB30: DD CB 26 76  states 1/2: only the marked Asp ends it
    JR Z,L_DB43                                ; $DB34: 28 0D  not the marked Asp
    JR L_DB3F                                  ; $DB36: 18 07
L_DB38:
    LD A,(IY+$01)                              ; $DB38: FD 7E 01
    CP $1E                                     ; $DB3B: FE 1E  blueprint size $1E: none in the reference
    JR NZ,L_DB43                               ; $DB3D: 20 04
L_DB3F:
    XOR A                                      ; $DB3F: AF
    LD (MissionAspEncounterState),A            ; $DB40: 32 0C DA  end the Asp encounter

; VERIFIED: Free the slot (energy 0), release references (ReleaseTargetLocks), add the blueprint bounty (+8/+9)
; via AwardBounty and half the word at +$15/+$16 via AddCombatScore.  Behaviour +$21 AND $60 nonzero
; (trader records, rock hermit, Viper): PlayerLegalScore OR $40.
L_DB43:
    XOR A                                      ; $DB43: AF
    LD (IX+$22),A                              ; $DB44: DD 77 22  free the slot
    CALL ReleaseTargetLocks                    ; $DB47: CD 65 EB  release missiles and the lock aimed at it
    LD D,(IY+$09)                              ; $DB4A: FD 56 09  blueprint bounty
    LD E,(IY+$08)                              ; $DB4D: FD 5E 08
    CALL AwardBounty                           ; $DB50: CD 00 A9  credit it (zero: nothing)
    LD D,(IY+$16)                              ; $DB53: FD 56 16  blueprint word +$15/+$16, halved
    LD E,(IY+$15)                              ; $DB56: FD 5E 15
    SRL D                                      ; $DB59: CB 3A
    RR E                                       ; $DB5B: CB 1B
    CALL AddCombatScore                        ; $DB5D: CD EE A8  add to the combat score
    LD A,(IX+$21)                              ; $DB60: DD 7E 21
    AND $60                                    ; $DB63: E6 60  trader/police behaviour bits
    JR Z,L_DBBE                                ; $DB65: 28 57  no legal consequence
    LD A,(PlayerLegalScore)                    ; $DB67: 3A 21 A8
    OR $40                                     ; $DB6A: F6 40  at least 64: Fugitive
    LD (PlayerLegalScore),A                    ; $DB6C: 32 21 A8
    JR L_DBBE                                  ; $DB6F: 18 4D

; VERIFIED: Alive object: if +$20 bit 6, run AI - UpdateMissileGuidance every update when +$26
; bit 0 is set (INFERRED: missile), otherwise UpdateShipTactics when
; (counter XOR ObjectUpdateCounter) AND 3 = 0, so the ships take turns, each on one
; update in four.  Then MoveObject, OrthogonaliseYVector and RenormaliseOrientationVector
; for the three vectors at +9.
L_DB71:
    LD A,B                                     ; $DB71: 78
    XOR C                                      ; $DB72: A9
    AND $0F                                    ; $DB73: E6 0F  AI phase of this slot
    BIT 6,(IX+$20)                             ; $DB75: DD CB 20 76
    JR Z,L_DB8B                                ; $DB79: 28 10  not counted: no AI
    BIT 0,(IX+$26)                             ; $DB7B: DD CB 26 46
    JR Z,L_DB86                                ; $DB7F: 28 05  not a missile
    CALL UpdateMissileGuidance                 ; $DB81: CD 28 F9  missile guidance every update
    JR L_DB8B                                  ; $DB84: 18 05
L_DB86:
    AND $03                                    ; $DB86: E6 03
    CALL Z,UpdateShipTactics                   ; $DB88: CC 33 F7  AI every fourth update
L_DB8B:
    CALL MoveObject                            ; $DB8B: CD E0 DC  move and rotate
    CALL OrthogonaliseYVector                  ; $DB8E: CD 91 E7  keep Y orthogonal to Z
    PUSH IX                                    ; $DB91: DD E5
    LD DE,$0009                                ; $DB93: 11 09 00  orientation vectors at +9
    ADD IX,DE                                  ; $DB96: DD 19
    CALL RenormaliseOrientationVector          ; $DB98: CD A3 DC  Z axis
    CALL RenormaliseOrientationVector          ; $DB9B: CD A3 DC  Y axis
    CALL RenormaliseOrientationVector          ; $DB9E: CD A3 DC  X axis
    POP IX                                     ; $DBA1: DD E1

; VERIFIED: HandleObjectContact (collision, scooping, docking contact), draw/project (DrawObjectInView), clear
; +$20 bit 3; an explosion state 01 advances to 10.
L_DBA3:
    CALL HandleObjectContact                   ; $DBA3: CD 51 EA  collision, scooping, docking contact
    CALL DrawObjectInView                      ; $DBA6: CD 08 E0  draw, or record the screen position
    RES 3,(IX+$20)                             ; $DBA9: DD CB 20 9E  AI laser-fired flag consumed
    LD A,(IX+$20)                              ; $DBAD: DD 7E 20
    AND $30                                    ; $DBB0: E6 30
    CP $10                                     ; $DBB2: FE 10  explosion state 01 -> 10
    JR NZ,L_DBBE                               ; $DBB4: 20 08
    SET 5,(IX+$20)                             ; $DBB6: DD CB 20 EE
    RES 4,(IX+$20)                             ; $DBBA: DD CB 20 A6

; VERIFIED: Next slot (IX += InstanceSize).  After slot 7 clear EnergyBombPending; clear
; SharedHostilityAlert when TorusJumpInhibitFlag is zero.
L_DBBE:
    POP AF                                     ; $DBBE: F1  A = counter of this slot
    LD DE,InstanceSize                         ; $DBBF: 11 27 00
    ADD IX,DE                                  ; $DBC2: DD 19
    DEC A                                      ; $DBC4: 3D
    JP NZ,L_DA9A                               ; $DBC5: C2 9A DA  more slots
    XOR A                                      ; $DBC8: AF
    LD (EnergyBombPending),A                   ; $DBC9: 32 10 DA  bomb applied to every slot
    LD A,(TorusJumpInhibitFlag)                ; $DBCC: 3A 0F DA
    AND A                                      ; $DBCF: A7
    RET NZ                                     ; $DBD0: C0  ships present: keep the shared alert
    LD (SharedHostilityAlert),A                ; $DBD1: 32 14 DA  none: clear the shared alert
    RET                                        ; $DBD4: C9

; ============================================================================
; Vector and object-motion arithmetic
; Vector normalisation, square root, orientation rotation and position updates.
; ============================================================================

; VERIFIED: IX -> three sign-magnitude words (bit 15 = sign).  Scale the vector to length $8000
; (about 3% error): each component becomes |c| * 32768 / length with its sign kept.
; Return DE = the original length (SquareRootHL of the summed squares / 65536).
; A component not smaller than the computed length overflows the division
; (DivideWordFraction needs HL < DE).  IX preserved; A = 0; clobbers BC, HL.
; Evidence: tools/check_routines.py maths/square-root-and-normalise.  Caller ApplySteeringVector.
NormaliseVector:
    PUSH IX                                    ; $DBD5: DD E5
    CALL SquareVectorComponent                 ; $DBD7: CD FA DB  x^2 / 65536
    PUSH HL                                    ; $DBDA: E5
    CALL SquareVectorComponent                 ; $DBDB: CD FA DB  y^2 / 65536
    PUSH HL                                    ; $DBDE: E5
    CALL SquareVectorComponent                 ; $DBDF: CD FA DB  z^2 / 65536
    POP DE                                     ; $DBE2: D1
    ADD HL,DE                                  ; $DBE3: 19
    POP DE                                     ; $DBE4: D1
    ADD HL,DE                                  ; $DBE5: 19  HL = sum of squares / 65536
    POP IX                                     ; $DBE6: DD E1
    CALL SquareRootHL                          ; $DBE8: CD 53 DC  HL = 256*sqrt: the length
    EX DE,HL                                   ; $DBEB: EB  DE = length
    PUSH IX                                    ; $DBEC: DD E5
    CALL DivideVectorComponent                 ; $DBEE: CD 31 DC  each component * 32768 / length
    CALL DivideVectorComponent                 ; $DBF1: CD 31 DC  y component
    CALL DivideVectorComponent                 ; $DBF4: CD 31 DC  z component
    POP IX                                     ; $DBF7: DD E1
    RET                                        ; $DBF9: C9

; VERIFIED: HL = (|word at IX|)^2 >> 16 using MultiplyUnsigned and the square tables; IX += 2.
; The square is assembled as B^2*65536 + 2*B*C*256 + C^2 for the word B:C.
SquareVectorComponent:
    LD B,(IX+$01)                              ; $DBFA: DD 46 01
    LD C,(IX+$00)                              ; $DBFD: DD 4E 00
    RES 7,B                                    ; $DC00: CB B8  B = high magnitude, C = low byte
    PUSH IX                                    ; $DC02: DD E5
    LD IX,$0000                                ; $DC04: DD 21 00 00  IX accumulates the high word
    CALL MultiplyUnsigned                      ; $DC08: CD 5D E4  HL = B*C
    XOR A                                      ; $DC0B: AF
    LD D,A                                     ; $DC0C: 57
    ADD HL,HL                                  ; $DC0D: 29
    RL D                                       ; $DC0E: CB 12
    LD E,H                                     ; $DC10: 5C
    ADD IX,DE                                  ; $DC11: DD 19  high word += 2*B*C >> 8
    LD H,L                                     ; $DC13: 65
    LD L,A                                     ; $DC14: 6F  HL = low byte of 2*B*C, times 256
    PUSH HL                                    ; $DC15: E5
    LD H,SquareLookupTables >> 8               ; $DC16: 26 BE
    LD L,B                                     ; $DC18: 68
    LD E,(HL)                                  ; $DC19: 5E
    INC H                                      ; $DC1A: 24
    LD D,(HL)                                  ; $DC1B: 56
    DEC H                                      ; $DC1C: 25
    ADD IX,DE                                  ; $DC1D: DD 19  high word += B^2
    LD L,C                                     ; $DC1F: 69
    LD E,(HL)                                  ; $DC20: 5E
    INC H                                      ; $DC21: 24
    LD D,(HL)                                  ; $DC22: 56
    POP HL                                     ; $DC23: E1
    ADD HL,DE                                  ; $DC24: 19  HL += C^2
    JR NC,L_DC29                               ; $DC25: 30 02
    INC IX                                     ; $DC27: DD 23  carry into the high word
L_DC29:
    EX (SP),IX                                 ; $DC29: DD E3  restore IX, high word to the stack
    POP HL                                     ; $DC2B: E1  HL = word^2 >> 16
    INC IX                                     ; $DC2C: DD 23
    INC IX                                     ; $DC2E: DD 23
    RET                                        ; $DC30: C9

; VERIFIED: Word at IX = sign-preserving (|word| / DE) via DivideWordFraction, halved; IX += 2.
; With A = 0 (as in NormaliseVector) the new magnitude is |word| * 32768 / DE; BC returns
; the new word.
DivideVectorComponent:
    LD H,(IX+$01)                              ; $DC31: DD 66 01
    LD L,(IX+$00)                              ; $DC34: DD 6E 00
    PUSH HL                                    ; $DC37: E5
    RES 7,H                                    ; $DC38: CB BC  HL = magnitude
    CALL DivideWordFraction                    ; $DC3A: CD CF E8  BC = magnitude * 65536 / DE (A = 0)
    SRL B                                      ; $DC3D: CB 38
    RR C                                       ; $DC3F: CB 19  halved
    POP HL                                     ; $DC41: E1
    BIT 7,H                                    ; $DC42: CB 7C
    JR Z,L_DC48                                ; $DC44: 28 02
    SET 7,B                                    ; $DC46: CB F8  copy the sign
L_DC48:
    LD (IX+$00),C                              ; $DC48: DD 71 00
    LD (IX+$01),B                              ; $DC4B: DD 70 01
    INC IX                                     ; $DC4E: DD 23
    INC IX                                     ; $DC50: DD 23
    RET                                        ; $DC52: C9

; VERIFIED: HL = 256 * sqrt(HL), approximately; A = 0 on return, BC and DE clobbered.
; Within 3.5% for HL >= 16, coarser below.  HL < $1000 is pre-scaled by 16 (result / 4),
; HL < $100 by 256 (result / 16) before L_DC7A.
; Evidence: tools/check_routines.py maths/square-root-and-normalise, maths/r8-motion-helpers
; (A = 0 on return).
SquareRootHL:
    LD A,H                                     ; $DC53: 7C
    CP $10                                     ; $DC54: FE 10
    JR NC,L_DC7A                               ; $DC56: 30 22  HL >= $1000: direct
    AND A                                      ; $DC58: A7
    JR Z,L_DC6C                                ; $DC59: 28 11  HL < $100
    LD B,$04                                   ; $DC5B: 06 04
L_DC5D:
    ADD HL,HL                                  ; $DC5D: 29  HL < $1000: scale by 16
    DJNZ L_DC5D                                ; $DC5E: 10 FD
    CALL L_DC7A                                ; $DC60: CD 7A DC
    SRL H                                      ; $DC63: CB 3C  result / 4
    RR L                                       ; $DC65: CB 1D
    SRL H                                      ; $DC67: CB 3C
    RR L                                       ; $DC69: CB 1D
    RET                                        ; $DC6B: C9
L_DC6C:
    LD H,L                                     ; $DC6C: 65  HL < $100: scale by 256
    LD L,A                                     ; $DC6D: 6F
    CALL L_DC7A                                ; $DC6E: CD 7A DC
    LD B,$04                                   ; $DC71: 06 04
L_DC73:
    SRL H                                      ; $DC73: CB 3C  result / 16
    RR L                                       ; $DC75: CB 1D
    DJNZ L_DC73                                ; $DC77: 10 FA
    RET                                        ; $DC79: C9

; VERIFIED: Square-root core for N = HL: three Newton steps x' = (x + 16384*N/x) / 2 towards
; x = 128*sqrt(N), starting from x = $8000 (L_DC97/L_DC8D, using DivideWordFraction).  Each step
; returns HL = 2*x', so the result is HL ~ 256*sqrt(N).
L_DC7A:
    XOR A                                      ; $DC7A: AF
    PUSH HL                                    ; $DC7B: E5
    PUSH HL                                    ; $DC7C: E5  keep N for the second and third steps
    SRL H                                      ; $DC7D: CB 3C
    RR L                                       ; $DC7F: CB 1D
    RRA                                        ; $DC81: 1F  HL.A = N/2
    LD DE,$8000                                ; $DC82: 11 00 80  initial square-root guess
    CALL L_DC97                                ; $DC85: CD 97 DC  first step: HL = 2*x1
    POP DE                                     ; $DC88: D1
    CALL L_DC8D                                ; $DC89: CD 8D DC  second step
    POP DE                                     ; $DC8C: D1  N for the third step (falls through)

; VERIFIED: One Newton step of the square-root core (second and third iterations): halve the previous
; HL (17 bits with the carry) to get x, then L_DC97 with N from DE.
L_DC8D:
    RR H                                       ; $DC8D: CB 1C
    RR L                                       ; $DC8F: CB 1D  x = HL/2 (17 bits with the carry)
    EX DE,HL                                   ; $DC91: EB  DE = x, HL = N
    SRL H                                      ; $DC92: CB 3C
    RR L                                       ; $DC94: CB 1D
    RRA                                        ; $DC96: 1F  HL.A = N/2

; VERIFIED: Newton step: HL = DE + (quotient from DivideWordFraction) / 2, with DE = x and
; HL.A = N/2 on entry, i.e. HL = x + 16384*N/x; A = 0 on return.
L_DC97:
    PUSH DE                                    ; $DC97: D5
    CALL DivideWordFraction                    ; $DC98: CD CF E8  BC = N * 32768 / x
    SRL B                                      ; $DC9B: CB 38
    RR C                                       ; $DC9D: CB 19  halved
    XOR A                                      ; $DC9F: AF  A = 0 on return
    POP HL                                     ; $DCA0: E1
    ADD HL,BC                                  ; $DCA1: 09  HL = x + 16384*N/x = 2 * next x
    RET                                        ; $DCA2: C9

; VERIFIED: IX -> three words (high bytes, bit 7 = sign).  Scale the high bytes by B/128 with
; B = $80 - S/4, where S is the 8-bit sum of the squared doubled magnitudes / 256
; (= |v|^2/64) taken as a signed value: S wraps to 0 at length 128, so lengths just below
; grow and lengths above shrink (the check measures 127.0..128.2 after four calls).
; Signs are kept; IX += 6.  Evidence: tools/check_routines.py maths/rotation-helpers.
RenormaliseOrientationVector:
    LD H,(SquareLookupTables >> 8) + 1         ; $DCA3: 26 BF
    LD L,(IX+$01)                              ; $DCA5: DD 6E 01  H selects the square table high bytes
    SLA L                                      ; $DCA8: CB 25
    LD A,(HL)                                  ; $DCAA: 7E  (2*|x|)^2 / 256
    LD L,(IX+$03)                              ; $DCAB: DD 6E 03
    SLA L                                      ; $DCAE: CB 25
    ADD A,(HL)                                 ; $DCB0: 86
    LD L,(IX+$05)                              ; $DCB1: DD 6E 05
    SLA L                                      ; $DCB4: CB 25
    ADD A,(HL)                                 ; $DCB6: 86  + the y and z terms: |v|^2/64 (8-bit, wraps)
    SRA A                                      ; $DCB7: CB 2F
    SRA A                                      ; $DCB9: CB 2F  signed sum / 4
    NEG                                        ; $DCBB: ED 44
    XOR $80                                    ; $DCBD: EE 80  B = $80 - sum/4
    LD B,A                                     ; $DCBF: 47
    CALL L_DCC6                                ; $DCC0: CD C6 DC
    CALL L_DCC6                                ; $DCC3: CD C6 DC

; VERIFIED: Scale one high byte by B/128 (MultiplyUnsigned of B and twice the magnitude), keep its
; sign; IX += 2.
L_DCC6:
    LD C,(IX+$01)                              ; $DCC6: DD 4E 01
    SLA C                                      ; $DCC9: CB 21  C = 2*magnitude, sign shifted out
    CALL MultiplyUnsigned                      ; $DCCB: CD 5D E4  HL = B * 2*magnitude
    SLA H                                      ; $DCCE: CB 24
    SLA (IX+$01)                               ; $DCD0: DD CB 01 26
    RR H                                       ; $DCD4: CB 1C  old sign into bit 7
    LD (IX+$01),H                              ; $DCD6: DD 74 01  new high byte: magnitude * B / 128
    INC IX                                     ; $DCD9: DD 23
    INC IX                                     ; $DCDB: DD 23
    RET                                        ; $DCDD: C9

; VERIFIED: Angle for rotation in the x-y plane (z is the view depth): first the player's PlayerRoll,
; then the object's own roll from +$1D ($0C, sign $80).
; Read by RotateVectorRollPitch and RotateOrientationComponent.
RollRotationAngle:
    defb $00                                                                              ; $DCDE .

; VERIFIED: Angle for rotation in the y-z plane: the player's PlayerPitch, then the object's +$1E ($08).
PitchRotationAngle:
    defb $00                                                                              ; $DCDF .

; VERIFIED: Move one object: IX = instance, IY = blueprint.
; ApplyPlayerMotion; remove (energy 0, ReleaseTargetLocks) objects with nonzero x/y/z high
; magnitude, or z mid byte >= $60 without +$26 bit 2.  Otherwise rotate the orientation
; by the player's roll/pitch, then by the object's own +$1D/+$1E counters (bit 7 =
; continuous, bit 6 = sign, low nibble = remaining steps), update the speed and move the
; position along the vector at +9 (L_DD92).
; On removal ReleaseTargetLocks releases the references to the slot given by ObjectLoopCounter, so
; callers outside the slot loop (L_77B0) depend on its current value.
; A removed object skips the orientation step.  For the dormant station, which
; UpdateStationDormancy moves while it is far away, the position therefore follows the
; player's motion but the axes do not.
; Evidence: tools/check_routines.py station/dormant-orientation-frozen.
MoveObject:
    CALL ApplyPlayerMotion                     ; $DCE0: CD D1 DE  HL = z sign/high and mid bytes afterwards
    BIT 2,(IX+$26)                             ; $DCE3: DD CB 26 56  the station has no z distance limit
    JR NZ,L_DCEE                               ; $DCE7: 20 05
    LD A,L                                     ; $DCE9: 7D  z mid byte
    CP $60                                     ; $DCEA: FE 60  too far away
    JR NC,L_DCF3                               ; $DCEC: 30 05
L_DCEE:
    LD A,H                                     ; $DCEE: 7C
    AND $7F                                    ; $DCEF: E6 7F
    JR Z,L_DCFA                                ; $DCF1: 28 07  z high magnitude zero?

; VERIFIED: Remove the object: energy +$22 = 0, then tail-jump to ReleaseTargetLocks.
L_DCF3:
    XOR A                                      ; $DCF3: AF
    LD (IX+$22),A                              ; $DCF4: DD 77 22
    JP ReleaseTargetLocks                      ; $DCF7: C3 65 EB  release references to this slot
L_DCFA:
    LD A,(IX+$02)                              ; $DCFA: DD 7E 02
    AND $7F                                    ; $DCFD: E6 7F  x high magnitude must be zero
    JR NZ,L_DCF3                               ; $DCFF: 20 F2
    LD A,(IX+$05)                              ; $DD01: DD 7E 05
    AND $7F                                    ; $DD04: E6 7F  y high magnitude must be zero
    JR NZ,L_DCF3                               ; $DD06: 20 EB
    LD HL,(PlayerRoll)                         ; $DD08: 2A 42 70  player roll and pitch
    LD (RollRotationAngle),HL                  ; $DD0B: 22 DE DC  roll and pitch angles of this pass
    PUSH IX                                    ; $DD0E: DD E5
    LD DE,$0009                                ; $DD10: 11 09 00  three orientation vectors
    ADD IX,DE                                  ; $DD13: DD 19
    CALL RotateVectorRollPitch                 ; $DD15: CD 0B DE  Z, Y and X axes
    CALL RotateVectorRollPitch                 ; $DD18: CD 0B DE
    CALL RotateVectorRollPitch                 ; $DD1B: CD 0B DE
    POP IX                                     ; $DD1E: DD E1
    LD A,(IX+$1D)                              ; $DD20: DD 7E 1D  own roll counter +$1D
    LD B,A                                     ; $DD23: 47
    BIT 7,A                                    ; $DD24: CB 7F  bit 7: keep rolling
    JR NZ,L_DD33                               ; $DD26: 20 0B
    AND $0F                                    ; $DD28: E6 0F  remaining steps (low nibble)
    LD A,$00                                   ; $DD2A: 3E 00
    JR Z,L_DD3D                                ; $DD2C: 28 0F  none: angle 0
    LD A,B                                     ; $DD2E: 78
    DEC A                                      ; $DD2F: 3D  one step used
    LD (IX+$1D),A                              ; $DD30: DD 77 1D
L_DD33:
    LD A,$0C                                   ; $DD33: 3E 0C  roll angle 12
    BIT 6,(IX+$1D)                             ; $DD35: DD CB 1D 76  bit 6: direction
    JR Z,L_DD3D                                ; $DD39: 28 02
    ADD A,$80                                  ; $DD3B: C6 80  sign bit
L_DD3D:
    LD (RollRotationAngle),A                   ; $DD3D: 32 DE DC  object roll angle for this pass
    LD A,(IX+$1E)                              ; $DD40: DD 7E 1E  own pitch counter +$1E
    LD B,A                                     ; $DD43: 47
    BIT 7,A                                    ; $DD44: CB 7F  bit 7: keep pitching
    JR NZ,L_DD53                               ; $DD46: 20 0B
    AND $0F                                    ; $DD48: E6 0F  remaining steps (low nibble)
    LD A,$00                                   ; $DD4A: 3E 00
    JR Z,L_DD5D                                ; $DD4C: 28 0F  none: angle 0
    LD A,B                                     ; $DD4E: 78
    DEC A                                      ; $DD4F: 3D  one step used
    LD (IX+$1E),A                              ; $DD50: DD 77 1E
L_DD53:
    LD A,$08                                   ; $DD53: 3E 08  pitch angle 8
    BIT 6,(IX+$1E)                             ; $DD55: DD CB 1E 76  bit 6: direction
    JR Z,L_DD5D                                ; $DD59: 28 02
    ADD A,$80                                  ; $DD5B: C6 80  sign bit

; VERIFIED: Entry with PitchRotationAngle = A.
; Rotate the orientation by the object's angles (RotateOrientationComponent x3).
; Add +$1C (acceleration) to +$1B (speed), clamped to 0..blueprint +6 (x4 when +$21
; bit 0), then move along the vector at +9 by the speed.
L_DD5D:
    LD (PitchRotationAngle),A                  ; $DD5D: 32 DF DC
    PUSH IX                                    ; $DD60: DD E5
    CALL RotateOrientationComponent            ; $DD62: CD 88 DE  rotate about the object's own axes
    CALL RotateOrientationComponent            ; $DD65: CD 88 DE
    CALL RotateOrientationComponent            ; $DD68: CD 88 DE
    POP IX                                     ; $DD6B: DD E1
    LD A,(IX+$1C)                              ; $DD6D: DD 7E 1C  acceleration
    AND A                                      ; $DD70: A7
    JR Z,L_DD92                                ; $DD71: 28 1F  none: keep the speed
    LD B,(IX+$1B)                              ; $DD73: DD 46 1B
    ADD A,B                                    ; $DD76: 80  speed + acceleration
    BIT 7,A                                    ; $DD77: CB 7F  negative: stop
    JR Z,L_DD7E                                ; $DD79: 28 03
    XOR A                                      ; $DD7B: AF
    JR L_DD8F                                  ; $DD7C: 18 11
L_DD7E:
    LD C,(IY+$06)                              ; $DD7E: FD 4E 06  blueprint maximum speed
    BIT 0,(IX+$21)                             ; $DD81: DD CB 21 46
    JR Z,L_DD8B                                ; $DD85: 28 04
    SLA C                                      ; $DD87: CB 21  x4 when +$21 bit 0
    SLA C                                      ; $DD89: CB 21
L_DD8B:
    CP C                                       ; $DD8B: B9
    JR C,L_DD8F                                ; $DD8C: 38 01  cap at the maximum
    LD A,C                                     ; $DD8E: 79
L_DD8F:
    LD (IX+$1B),A                              ; $DD8F: DD 77 1B  new speed

; VERIFIED: Move: C = speed (+$1B); MoveCoordinateAlongNose for x, y and z (IY = instance).
; Each coordinate changes by about Z-axis component * speed / 64 / 256 (rounded up).
; IX and IY preserved.
L_DD92:
    PUSH IX                                    ; $DD92: DD E5
    PUSH IY                                    ; $DD94: FD E5
    LD C,(IX+$1B)                              ; $DD96: DD 4E 1B  C = speed
    PUSH IX                                    ; $DD99: DD E5
    POP IY                                     ; $DD9B: FD E1  IY = instance coordinates
    CALL MoveCoordinateAlongNose               ; $DD9D: CD AB DD  x += nose x * speed
    CALL MoveCoordinateAlongNose               ; $DDA0: CD AB DD  y += nose y * speed
    CALL MoveCoordinateAlongNose               ; $DDA3: CD AB DD  z += nose z * speed
    POP IY                                     ; $DDA6: FD E1
    POP IX                                     ; $DDA8: DD E1
    RET                                        ; $DDAA: C9

; VERIFIED: 24-bit coordinate at IY += ScaleComponentBySpeed(word at IX+9, C) via AddToCoordinate;
; IY += 3, IX += 2.  BC preserved.
MoveCoordinateAlongNose:
    PUSH BC                                    ; $DDAB: C5
    LD D,(IX+$0A)                              ; $DDAC: DD 56 0A
    LD E,(IX+$09)                              ; $DDAF: DD 5E 09  DE = Z axis (nose) component
    CALL ScaleComponentBySpeed                 ; $DDB2: CD D6 DD  E = step magnitude, D = sign
    LD A,(IY+$02)                              ; $DDB5: FD 7E 02
    LD H,(IY+$01)                              ; $DDB8: FD 66 01
    LD L,(IY+$00)                              ; $DDBB: FD 6E 00  A = sign/high byte, HL = low 16 bits
    CALL AddToCoordinate                       ; $DDBE: CD F8 DD  add the signed step
    LD (IY+$02),B                              ; $DDC1: FD 70 02  store the new coordinate
    LD (IY+$01),H                              ; $DDC4: FD 74 01
    LD (IY+$00),L                              ; $DDC7: FD 75 00
    INC IY                                     ; $DDCA: FD 23
    INC IY                                     ; $DDCC: FD 23
    INC IY                                     ; $DDCE: FD 23
    INC IX                                     ; $DDD0: DD 23
    INC IX                                     ; $DDD2: DD 23
    POP BC                                     ; $DDD4: C1
    RET                                        ; $DDD5: C9

; VERIFIED: DE = sign-magnitude word (bit 15 = sign), C = speed (bits 0..5 used).
; E = (sum over speed bits k = 5..0 of (|DE| >> (6 - k)) + $FF) >> 8, i.e. about
; |DE| * speed / 64 / 256 rounded up; D = sign bit only; B = 0.
; Evidence: tools/check_routines.py maths/r8-motion-helpers (exact model).
ScaleComponentBySpeed:
    SLA D                                      ; $DDD6: CB 22  sign into carry
    RL C                                       ; $DDD8: CB 11
    RL C                                       ; $DDDA: CB 11  C << 2: speed bits 5..0 at the top
    SRL D                                      ; $DDDC: CB 3A  D = magnitude high byte
    LD HL,$0000                                ; $DDDE: 21 00 00
    LD B,$06                                   ; $DDE1: 06 06  six speed bits
L_DDE3:
    SRL D                                      ; $DDE3: CB 3A
    RR E                                       ; $DDE5: CB 1B  DE = magnitude >> k
    SLA C                                      ; $DDE7: CB 21  next speed bit (bit 5 first)
    JR NC,L_DDEC                               ; $DDE9: 30 01
    ADD HL,DE                                  ; $DDEB: 19  add the scaled magnitude
L_DDEC:
    DJNZ L_DDE3                                ; $DDEC: 10 F5
    LD DE,$00FF                                ; $DDEE: 11 FF 00  round up
    ADD HL,DE                                  ; $DDF1: 19
    LD E,H                                     ; $DDF2: 5C  E = high byte of the sum
    SLA C                                      ; $DDF3: CB 21
    RR D                                       ; $DDF5: CB 1A  D = sign bit only
    RET                                        ; $DDF7: C9

; VERIFIED: Add signed DE (bit 15 = sign) to a 24-bit coordinate.
; A = sign/high byte, HL = low 16 bits of the magnitude.  If A equals D (same sign and a
; zero high magnitude): HL += DE, without carry into the high byte.  Otherwise HL -= DE;
; when that borrows, HL = DE - HL and the result takes D (sign of DE, high magnitude 0).
; Returns B (sign/high byte) and HL; C = old D.  MoveObject removes objects with a
; nonzero high magnitude first, so the comparison acts as a sign test there.
; Evidence: tools/check_routines.py maths/r8-motion-helpers (exact model).
AddToCoordinate:
    LD B,A                                     ; $DDF8: 47
    LD C,D                                     ; $DDF9: 4A
    XOR C                                      ; $DDFA: A9  zero only when A equals D
    RES 7,D                                    ; $DDFB: CB BA  D = step magnitude
    JR NZ,L_DE01                               ; $DDFD: 20 02
    ADD HL,DE                                  ; $DDFF: 19  same sign: add (no carry into the high byte)
    RET                                        ; $DE00: C9
L_DE01:
    SBC HL,DE                                  ; $DE01: ED 52  different: subtract
    RET NC                                     ; $DE03: D0  no borrow: keep the sign
    ADD HL,DE                                  ; $DE04: 19
    EX DE,HL                                   ; $DE05: EB
    AND A                                      ; $DE06: A7
    SBC HL,DE                                  ; $DE07: ED 52  crossed zero: HL = step - old
    LD B,C                                     ; $DE09: 41  sign of the step
    RET                                        ; $DE0A: C9

; VERIFIED: Rotate one orientation vector by the roll and pitch angles.
; High bytes at IX+1/+3/+5 (x, y, z): z += y*(-pitch/2)/128, x += y*(-roll)/128,
; y += x*roll/128, y += z*(pitch/2)/128 (AddScaledSignMagnitude, updated values used at
; once); IX += 6, DE = 6.
; NOTE: these are the shear steps of ApplyPlayerMotion at the same scale, but pitch/2 is
; truncated.  At pitch 1 positions turn and the axes do not; an odd pitch turns the
; axes like the next lower even one.
; Evidence: tools/check_routines.py station/orientation-pitch-quantisation.
RotateVectorRollPitch:
    LD A,(PitchRotationAngle)                  ; $DE0B: 3A DF DC
    XOR $80                                    ; $DE0E: EE 80
    SRA A                                      ; $DE10: CB 2F
    RES 6,A                                    ; $DE12: CB B7  C = -pitch/2 (sign-magnitude)
    LD C,A                                     ; $DE14: 4F
    LD B,(IX+$03)                              ; $DE15: DD 46 03
    LD D,(IX+$05)                              ; $DE18: DD 56 05
    CALL AddScaledSignMagnitude                ; $DE1B: CD 5D DE  z += y * (-pitch/2) / 128
    LD (IX+$05),A                              ; $DE1E: DD 77 05
    LD A,(RollRotationAngle)                   ; $DE21: 3A DE DC
    XOR $80                                    ; $DE24: EE 80  C = -roll
    LD C,A                                     ; $DE26: 4F
    LD B,(IX+$03)                              ; $DE27: DD 46 03
    LD D,(IX+$01)                              ; $DE2A: DD 56 01
    CALL AddScaledSignMagnitude                ; $DE2D: CD 5D DE  x += y * (-roll) / 128
    LD (IX+$01),A                              ; $DE30: DD 77 01
    LD A,(RollRotationAngle)                   ; $DE33: 3A DE DC
    LD C,A                                     ; $DE36: 4F
    LD B,(IX+$01)                              ; $DE37: DD 46 01
    LD D,(IX+$03)                              ; $DE3A: DD 56 03
    CALL AddScaledSignMagnitude                ; $DE3D: CD 5D DE  y += x * roll / 128 (new x)
    LD (IX+$03),A                              ; $DE40: DD 77 03
    LD A,(PitchRotationAngle)                  ; $DE43: 3A DF DC
    SRA A                                      ; $DE46: CB 2F
    RES 6,A                                    ; $DE48: CB B7  C = pitch/2
    LD C,A                                     ; $DE4A: 4F
    LD B,(IX+$05)                              ; $DE4B: DD 46 05
    LD D,(IX+$03)                              ; $DE4E: DD 56 03
    CALL AddScaledSignMagnitude                ; $DE51: CD 5D DE  y += z * (pitch/2) / 128 (new z)
    LD (IX+$03),A                              ; $DE54: DD 77 03
    LD DE,$0006                                ; $DE57: 11 06 00  next vector
    ADD IX,DE                                  ; $DE5A: DD 19
    RET                                        ; $DE5C: C9

; VERIFIED: A = D + s*|B|*|C|/128 for sign-magnitude bytes, s = sign of (A XOR B), saturated at 127.
; Evidence: tools/check_routines.py maths/rotation-helpers (within 1.25 of the model).
AddScaledSignMagnitude:
    PUSH DE                                    ; $DE5D: D5
    XOR B                                      ; $DE5E: A8  bit 7: sign of the product
    SLA B                                      ; $DE5F: CB 20
    RES 7,C                                    ; $DE61: CB B9  C = |angle|
    LD E,A                                     ; $DE63: 5F
    CALL MultiplyUnsignedHigh                  ; $DE64: CD 34 E4  A = |B|*|C|/128
    POP BC                                     ; $DE67: C1  B = D (value)
    LD C,A                                     ; $DE68: 4F
    LD A,E                                     ; $DE69: 7B
    XOR B                                      ; $DE6A: A8  product sign XOR value sign
    SLA B                                      ; $DE6B: CB 20
    RR E                                       ; $DE6D: CB 1B
    SLA C                                      ; $DE6F: CB 21
    RLA                                        ; $DE71: 17
    LD A,B                                     ; $DE72: 78  A = 2*|value|
    JR C,L_DE7D                                ; $DE73: 38 08  signs differ: subtract
    ADD A,C                                    ; $DE75: 81  same signs: add
    JP NC,L_DE84                               ; $DE76: D2 84 DE
    LD A,$FF                                   ; $DE79: 3E FF  saturate
    JR L_DE84                                  ; $DE7B: 18 07
L_DE7D:
    SUB C                                      ; $DE7D: 91  subtract
    JR NC,L_DE84                               ; $DE7E: 30 04
    NEG                                        ; $DE80: ED 44  product larger: result takes its sign
    RL E                                       ; $DE82: CB 13
L_DE84:
    RL E                                       ; $DE84: CB 13
    RRA                                        ; $DE86: 1F  sign into bit 7, magnitude halved back
    RET                                        ; $DE87: C9

; VERIFIED: Rotate one component of the three orientation vectors (IX+$0A, +$10, +$16) by the
; object's angles: pitch couples +$0A/+$10, roll couples +$10/+$16; IX += 2.
; Applied to all three components this rotates the object about its own axes: pitch mixes
; its Z (nose) and Y (roof) vectors, roll mixes its X (side) and Y vectors.
RotateOrientationComponent:
    LD A,(PitchRotationAngle)                  ; $DE88: 3A DF DC
    XOR $80                                    ; $DE8B: EE 80
    LD C,A                                     ; $DE8D: 4F  C = -pitch
    LD B,(IX+$10)                              ; $DE8E: DD 46 10
    LD D,(IX+$0A)                              ; $DE91: DD 56 0A
    CALL AddScaledSignMagnitude                ; $DE94: CD 5D DE  Z += Y * (-pitch) / 128
    LD (IX+$0A),A                              ; $DE97: DD 77 0A
    LD A,(RollRotationAngle)                   ; $DE9A: 3A DE DC
    XOR $80                                    ; $DE9D: EE 80
    LD C,A                                     ; $DE9F: 4F  C = -roll
    LD B,(IX+$10)                              ; $DEA0: DD 46 10
    LD D,(IX+$16)                              ; $DEA3: DD 56 16
    CALL AddScaledSignMagnitude                ; $DEA6: CD 5D DE  X += Y * (-roll) / 128
    LD (IX+$16),A                              ; $DEA9: DD 77 16
    LD A,(RollRotationAngle)                   ; $DEAC: 3A DE DC
    LD C,A                                     ; $DEAF: 4F
    LD B,(IX+$16)                              ; $DEB0: DD 46 16
    LD D,(IX+$10)                              ; $DEB3: DD 56 10
    CALL AddScaledSignMagnitude                ; $DEB6: CD 5D DE  Y += X * roll / 128 (new X)
    LD (IX+$10),A                              ; $DEB9: DD 77 10
    LD A,(PitchRotationAngle)                  ; $DEBC: 3A DF DC
    LD C,A                                     ; $DEBF: 4F
    LD B,(IX+$0A)                              ; $DEC0: DD 46 0A
    LD D,(IX+$10)                              ; $DEC3: DD 56 10
    CALL AddScaledSignMagnitude                ; $DEC6: CD 5D DE  Y += Z * pitch / 128 (new Z)
    LD (IX+$10),A                              ; $DEC9: DD 77 10
    INC IX                                     ; $DECC: DD 23  next component
    INC IX                                     ; $DECE: DD 23
    RET                                        ; $DED0: C9

; VERIFIED: Rotate the 24-bit position at IX+0..8 by the player's pitch (PlayerPitch, y-z) and roll
; (PlayerRoll, x-y) with AddScaledCoordinate, then move z by 2*(PlayerSpeed+1): positive z decreases,
; negative z grows.  Returns HL = z sign/high and mid bytes.  Also used for SunPosition/PlanetPosition
; (MoveSunAndPlanet).  Crossing zero flips the sign; a negative magnitude overflowing $FFFF becomes
; +$7FFF.. (sign cleared).
; NOTE: each rotation is two shear steps in a fixed order (z, then y from the new z; x,
; then y from the new x).  One step is close to a rotation, but a roll or pitch in one
; direction is not undone by the same rate in the other.  Rolling alternately left and right
; pushes positions away from the view axis at unchanged depth (planet 4.98 times further
; after 20 cycles of 32 updates each way); one direction alone does not.
; Evidence: tools/check_routines.py maths/r8-motion-helpers (z step, zero crossing,
; overflow, returned HL), maths/roll-reversal-drift.
ApplyPlayerMotion:
    LD A,(PlayerPitch)                         ; $DED1: 3A 43 70
    XOR $80                                    ; $DED4: EE 80  C = -pitch
    LD C,A                                     ; $DED6: 4F
    LD DE,$0003                                ; $DED7: 11 03 00
    LD HL,$0006                                ; $DEDA: 21 06 00  source y (+3), destination z (+6)
    CALL AddScaledCoordinate                   ; $DEDD: CD 46 DF  z += y * (-pitch) / 256
    LD A,(PlayerRoll)                          ; $DEE0: 3A 42 70
    XOR $80                                    ; $DEE3: EE 80
    CALL DoubleSignMagnitude                   ; $DEE5: CD 6C BC  C = 2*(-roll)
    LD DE,$0003                                ; $DEE8: 11 03 00
    LD H,D                                     ; $DEEB: 62
    LD L,D                                     ; $DEEC: 6A
    CALL AddScaledCoordinate                   ; $DEED: CD 46 DF  x += y * 2*(-roll) / 256
    LD A,(PlayerRoll)                          ; $DEF0: 3A 42 70
    CALL DoubleSignMagnitude                   ; $DEF3: CD 6C BC  C = 2*roll
    LD HL,$0003                                ; $DEF6: 21 03 00
    LD D,H                                     ; $DEF9: 54
    LD E,H                                     ; $DEFA: 5C
    CALL AddScaledCoordinate                   ; $DEFB: CD 46 DF  y += x * 2*roll / 256 (new x)
    LD A,(PlayerPitch)                         ; $DEFE: 3A 43 70
    LD C,A                                     ; $DF01: 4F
    LD HL,$0003                                ; $DF02: 21 03 00
    LD DE,$0006                                ; $DF05: 11 06 00
    CALL AddScaledCoordinate                   ; $DF08: CD 46 DF  y += z * pitch / 256 (new z)
    LD A,(PlayerSpeed)                         ; $DF0B: 3A 44 70  player speed
    INC A                                      ; $DF0E: 3C
    ADD A,A                                    ; $DF0F: 87
    LD B,A                                     ; $DF10: 47  B = 2*(speed + 1)
    LD H,(IX+$08)                              ; $DF11: DD 66 08
    LD L,(IX+$07)                              ; $DF14: DD 6E 07
    LD A,(IX+$06)                              ; $DF17: DD 7E 06  HL = z sign/high and mid, A = low
    BIT 7,H                                    ; $DF1A: CB 7C  negative z: magnitude grows
    JR Z,L_DF2D                                ; $DF1C: 28 0F
    ADD A,B                                    ; $DF1E: 80
    LD (IX+$06),A                              ; $DF1F: DD 77 06
    RET NC                                     ; $DF22: D0  no carry: done
    INC HL                                     ; $DF23: 23  carry into the upper bytes
    BIT 7,H                                    ; $DF24: CB 7C
    JR NZ,L_DF3F                               ; $DF26: 20 17  still within range
    LD HL,$7FFF                                ; $DF28: 21 FF 7F  overflow: largest magnitude, sign cleared
    JR L_DF3A                                  ; $DF2B: 18 0D
L_DF2D:
    SUB B                                      ; $DF2D: 90  positive z: magnitude shrinks
    LD (IX+$06),A                              ; $DF2E: DD 77 06
    RET NC                                     ; $DF31: D0  no borrow: done
    DEC HL                                     ; $DF32: 2B  borrow from the upper bytes
    BIT 7,H                                    ; $DF33: CB 7C
    JR Z,L_DF3F                                ; $DF35: 28 08  still positive
    LD HL,$8000                                ; $DF37: 21 00 80  crossed zero: sign set, upper magnitude 0
L_DF3A:
    NEG                                        ; $DF3A: ED 44  low byte negated: distance past zero
    LD (IX+$06),A                              ; $DF3C: DD 77 06
L_DF3F:
    LD (IX+$08),H                              ; $DF3F: DD 74 08
    LD (IX+$07),L                              ; $DF42: DD 75 07
    RET                                        ; $DF45: C9

; VERIFIED: Coordinate at IX+HL += coordinate at IX+DE * |C| / 256, sign = sign(C) XOR source sign
; (24-bit sign-magnitude, approximate products).  IX/IY preserved.
; Evidence: tools/check_routines.py maths/rotation-helpers.
AddScaledCoordinate:
    PUSH IX                                    ; $DF46: DD E5
    PUSH IX                                    ; $DF48: DD E5
    EX (SP),IY                                 ; $DF4A: FD E3  IY = IX (both restored at exit)
    ADD IX,DE                                  ; $DF4C: DD 19  IX = source coordinate
    EX DE,HL                                   ; $DF4E: EB
    ADD IY,DE                                  ; $DF4F: FD 19  IY = destination coordinate
    LD A,(IX+$02)                              ; $DF51: DD 7E 02
    LD D,(IX+$01)                              ; $DF54: DD 56 01
    LD E,(IX+$00)                              ; $DF57: DD 5E 00
    LD B,A                                     ; $DF5A: 47
    XOR C                                      ; $DF5B: A9
    AND $80                                    ; $DF5C: E6 80  product sign = source sign XOR angle sign
    PUSH AF                                    ; $DF5E: F5
    RES 7,C                                    ; $DF5F: CB B9
    RES 7,B                                    ; $DF61: CB B8  magnitudes only
    PUSH DE                                    ; $DF63: D5
    CALL MultiplyUnsigned                      ; $DF64: CD 5D E4  high byte * |C|
    POP DE                                     ; $DF67: D1
    PUSH HL                                    ; $DF68: E5
    LD B,D                                     ; $DF69: 42
    PUSH DE                                    ; $DF6A: D5
    CALL MultiplyUnsigned                      ; $DF6B: CD 5D E4  mid byte * |C|
    POP DE                                     ; $DF6E: D1
    LD B,E                                     ; $DF6F: 43
    LD A,L                                     ; $DF70: 7D
    LD L,H                                     ; $DF71: 6C
    LD H,$00                                   ; $DF72: 26 00
    POP DE                                     ; $DF74: D1
    ADD HL,DE                                  ; $DF75: 19
    LD E,A                                     ; $DF76: 5F
    PUSH HL                                    ; $DF77: E5
    CALL MultiplyUnsignedHigh                  ; $DF78: CD 34 E4  low byte * |C| (high part)
    ADD A,E                                    ; $DF7B: 83
    POP HL                                     ; $DF7C: E1
    JR NC,L_DF80                               ; $DF7D: 30 01
    INC HL                                     ; $DF7F: 23
L_DF80:
    LD B,A                                     ; $DF80: 47
    LD A,H                                     ; $DF81: 7C
    LD H,L                                     ; $DF82: 65
    LD L,B                                     ; $DF83: 68
    POP BC                                     ; $DF84: C1
    LD C,B                                     ; $DF85: 48
    LD B,(IY+$02)                              ; $DF86: FD 46 02
    LD D,(IY+$01)                              ; $DF89: FD 56 01
    LD E,(IY+$00)                              ; $DF8C: FD 5E 00  destination coordinate
    PUSH AF                                    ; $DF8F: F5
    LD A,B                                     ; $DF90: 78
    XOR C                                      ; $DF91: A9
    RLC C                                      ; $DF92: CB 01
    RLC C                                      ; $DF94: CB 01
    RLA                                        ; $DF96: 17
    RR C                                       ; $DF97: CB 19
    RRC C                                      ; $DF99: CB 09
    SRL A                                      ; $DF9B: CB 3F
    LD B,A                                     ; $DF9D: 47
    POP AF                                     ; $DF9E: F1
    BIT 6,C                                    ; $DF9F: CB 71
    JR NZ,L_DFAE                               ; $DFA1: 20 0B  signs differ: subtract
    ADD A,A                                    ; $DFA3: 87
    SLA C                                      ; $DFA4: CB 21
    RRA                                        ; $DFA6: 1F
    ADD A,B                                    ; $DFA7: 80
    ADD HL,DE                                  ; $DFA8: 19  same sign: add
    JR NC,L_DFCF                               ; $DFA9: 30 24
    INC A                                      ; $DFAB: 3C
    JR L_DFCF                                  ; $DFAC: 18 21
L_DFAE:
    AND A                                      ; $DFAE: A7  subtract
    EX DE,HL                                   ; $DFAF: EB
    SBC HL,DE                                  ; $DFB0: ED 52
    JR NC,L_DFB5                               ; $DFB2: 30 01
    INC A                                      ; $DFB4: 3C
L_DFB5:
    LD D,A                                     ; $DFB5: 57
    LD A,B                                     ; $DFB6: 78
    SUB D                                      ; $DFB7: 92
    LD B,A                                     ; $DFB8: 47
    JR NC,L_DFC8                               ; $DFB9: 30 0D  no borrow: keep the sign
    CPL                                        ; $DFBB: 2F
    LD B,A                                     ; $DFBC: 47
    LD A,C                                     ; $DFBD: 79
    XOR $80                                    ; $DFBE: EE 80  crossed zero: flip the sign
    LD C,A                                     ; $DFC0: 4F
    EX DE,HL                                   ; $DFC1: EB
    AND A                                      ; $DFC2: A7
    LD HL,$0000                                ; $DFC3: 21 00 00
    SBC HL,DE                                  ; $DFC6: ED 52  and negate the magnitude
L_DFC8:
    LD A,B                                     ; $DFC8: 78
    RLA                                        ; $DFC9: 17
    SLA C                                      ; $DFCA: CB 21
    RRA                                        ; $DFCC: 1F
    XOR $80                                    ; $DFCD: EE 80
L_DFCF:
    LD (IY+$02),A                              ; $DFCF: FD 77 02  store the destination
    LD (IY+$01),H                              ; $DFD2: FD 74 01
    LD (IY+$00),L                              ; $DFD5: FD 75 00
    POP IY                                     ; $DFD8: FD E1
    POP IX                                     ; $DFDA: DD E1
    RET                                        ; $DFDC: C9

; VERIFIED: Title-screen ship update (callers L_71A2, L_71E5).
; IX = slot 7, IY = its blueprint, roll $94 / pitch $8C: rotate and move (L_DD5D),
; OrthogonaliseYVector, renormalise two orientation vectors (Z and Y), then draw (DrawObjectInView).
; Clobbers all registers.
RotateAndDrawTitleShip:
    LD IX,ObjectSlot7                          ; $DFDD: DD 21 59 61
    LD H,(IX+$24)                              ; $DFE1: DD 66 24
    LD L,(IX+$23)                              ; $DFE4: DD 6E 23
    PUSH HL                                    ; $DFE7: E5
    POP IY                                     ; $DFE8: FD E1  IY = its blueprint
    LD A,$94                                   ; $DFEA: 3E 94  fixed title roll
    LD (RollRotationAngle),A                   ; $DFEC: 32 DE DC
    LD A,$8C                                   ; $DFEF: 3E 8C  fixed title pitch
    CALL L_DD5D                                ; $DFF1: CD 5D DD  own rotation, speed and move
    CALL OrthogonaliseYVector                  ; $DFF4: CD 91 E7  keep Y orthogonal to Z
    LD IX,ObjectSlot7+InstanceAxisZ            ; $DFF7: DD 21 62 61  renormalise the Z and Y axes
    CALL RenormaliseOrientationVector          ; $DFFB: CD A3 DC
    CALL RenormaliseOrientationVector          ; $DFFE: CD A3 DC
    LD IX,ObjectSlot7                          ; $E001: DD 21 59 61  IX = slot 7 instance (title/demo object of RotateAndDrawTitleShip)
    JP DrawObjectInView                        ; $E005: C3 08 E0

; ============================================================================
; 3D object renderer
; Per-object view culling, projection of the object centre, dot or full
; wireframe drawing (rotation matrix, face visibility, vertex projection,
; edges), crosshair target detection, explosion position and AI laser beams.
; ============================================================================

; VERIFIED: Draw one object instance in the current space view.
; IX = instance, IY = its blueprint; the caller's pushed AF (A = ObjectLoopCounter of the
; object loop) lies just above the return address and is read by L_E0B5.
; Returns at once unless CurrentScreenId is 0..3 (front, rear, left, right views) and the
; object lies in front of that view: depth = z (front/rear) or x (left/right), and its
; sign must match the view (front z>=0, rear z<0, left x<0, right x>=0).  Depth must
; also exceed blueprint +1.  Projects the centre with DivideRatioByte (ProjectedX/ProjectedY =
; 256*offset/depth, quadrant bits in ProjectedQuadrant) and the size (ProjectedObjectSize =
; 256*(blueprint +1)/depth).  Off-screen objects (offset - size >= 128 across or 64
; down) only get their laser beam (DrawAiBeamFromCentre).  Near the centre the object becomes the
; crosshair target (L_E0B5) and may drop its avoidance flag (CancelAvoidanceInSights).
; (IX+$20) bit 4 (destroyed) records the explosion position (RecordExplosionPosition) instead of
; drawing; in MissionAspEncounterState 1 the marked ship (+$26 bit 6) is not drawn.
; Depth high byte >= blueprint +$0B: 2x2 XOR dot; otherwise full wireframe (DrawObjectWireframe).
; Clobbers AF, BC, DE, HL; IX and IY preserved.
; Evidence: pipeline check (vertex buffer within 4 units of a float model in 1287 of
; 1292 vertices) and the p9 explosion, beam and avoidance checks in
; tools/check_routines.py; runtime: every flight-view scenario.
; NOTE: entered by JP from RotateAndDrawTitleShip (title ship), the word above the return address is
; not a loop counter; it is only stored when the crosshair test passes.
DrawObjectInView:
    LD A,(CurrentScreenId)                     ; $E008: 3A 41 70  views 0..3 only (front, rear, left, right)
    LD B,A                                     ; $E00B: 47
    CP $04                                     ; $E00C: FE 04
    RET NC                                     ; $E00E: D0  other screens: nothing to draw
    PUSH IX                                    ; $E00F: DD E5
    POP HL                                     ; $E011: E1
    BIT 1,A                                    ; $E012: CB 4F  left/right view: depth axis is x (+0), else z (+6)
    JR NZ,L_E01A                               ; $E014: 20 04
    LD DE,$0006                                ; $E016: 11 06 00  front/rear views: depth is z
    ADD HL,DE                                  ; $E019: 19
L_E01A:
    LD E,(HL)                                  ; $E01A: 5E  DE = depth magnitude
    INC HL                                     ; $E01B: 23
    LD D,(HL)                                  ; $E01C: 56
    INC HL                                     ; $E01D: 23
    LD C,(HL)                                  ; $E01E: 4E  C = depth sign byte
    SRL A                                      ; $E01F: CB 3F  bit 7 = view bits 0 XOR 1 ...
    XOR B                                      ; $E021: A8
    RRCA                                       ; $E022: 0F
    XOR C                                      ; $E023: A9  ... XOR depth sign: set means behind the view
    AND $80                                    ; $E024: E6 80
    RET NZ                                     ; $E026: C0  behind this view: not drawn
    LD (ObjectViewDepth),DE                    ; $E027: ED 53 E0 E2  ObjectViewDepth = 16-bit depth magnitude
    LD H,$00                                   ; $E02B: 26 00
    LD L,(IY+$01)                              ; $E02D: FD 6E 01  blueprint +1: object radius
    PUSH HL                                    ; $E030: E5  radius kept for the size projection
    AND A                                      ; $E031: A7
    SBC HL,DE                                  ; $E032: ED 52
    JR C,L_E038                                ; $E034: 38 02  draw only when depth > radius
    POP HL                                     ; $E036: E1  too close: drop the radius, return
    RET                                        ; $E037: C9

; VERIFIED: Centre projection: depth (DE) is beyond blueprint +1.  Front/rear: ProjectedX =
; 256*|x|/depth, ProjectedY = 256*|y|/depth; left/right: ProjectedX = 256*|z|/depth.
; Pushes two copies of the depth above the stacked radius (blueprint +1).
L_E038:
    PUSH DE                                    ; $E038: D5  depth copies for the next two divisions
    PUSH DE                                    ; $E039: D5
    BIT 1,B                                    ; $E03A: CB 48
    JR NZ,L_E063                               ; $E03C: 20 25  left/right views use z across
    EX DE,HL                                   ; $E03E: EB  HL = depth (divisor)
    LD D,(IX+$01)                              ; $E03F: DD 56 01
    LD E,(IX+$00)                              ; $E042: DD 5E 00
    XOR A                                      ; $E045: AF  no fraction bytes (A, C = 0)
    LD C,A                                     ; $E046: 4F
    CALL DivideRatioByte                       ; $E047: CD 92 E5  ProjectedX = 256*|x|/depth
    LD A,C                                     ; $E04A: 79
    LD (ProjectedX),A                          ; $E04B: 32 E9 E2
    POP HL                                     ; $E04E: E1
    LD D,(IX+$04)                              ; $E04F: DD 56 04
    LD E,(IX+$03)                              ; $E052: DD 5E 03
    XOR A                                      ; $E055: AF
    LD C,A                                     ; $E056: 4F
    CALL DivideRatioByte                       ; $E057: CD 92 E5  ProjectedY = 256*|y|/depth
    LD A,C                                     ; $E05A: 79
    LD (ProjectedY),A                          ; $E05B: 32 EA E2
    LD B,(IX+$02)                              ; $E05E: DD 46 02  B = x sign byte (horizontal sign)
    JR L_E086                                  ; $E061: 18 23
L_E063:
    EX DE,HL                                   ; $E063: EB
    LD D,(IX+$07)                              ; $E064: DD 56 07
    LD E,(IX+$06)                              ; $E067: DD 5E 06
    XOR A                                      ; $E06A: AF
    LD C,A                                     ; $E06B: 4F
    CALL DivideRatioByte                       ; $E06C: CD 92 E5  ProjectedX = 256*|z|/depth (left/right views)
    LD A,C                                     ; $E06F: 79
    LD (ProjectedX),A                          ; $E070: 32 E9 E2
    POP HL                                     ; $E073: E1
    LD D,(IX+$04)                              ; $E074: DD 56 04
    LD E,(IX+$03)                              ; $E077: DD 5E 03
    XOR A                                      ; $E07A: AF
    LD C,A                                     ; $E07B: 4F
    CALL DivideRatioByte                       ; $E07C: CD 92 E5  ProjectedY = 256*|y|/depth
    LD A,C                                     ; $E07F: 79
    LD (ProjectedY),A                          ; $E080: 32 EA E2
    LD B,(IX+$08)                              ; $E083: DD 46 08  B = z sign byte (horizontal sign)
L_E086:
    LD A,(IX+$05)                              ; $E086: DD 7E 05  y sign byte; bit 1 = horizontal sign, bit 0 = y sign
    SLA B                                      ; $E089: CB 20
    RLA                                        ; $E08B: 17
    RLA                                        ; $E08C: 17
    LD (ProjectedQuadrant),A                   ; $E08D: 32 EB E2  raw signs: not mirrored for rear/right
    POP HL                                     ; $E090: E1  HL = depth, DE = radius
    POP DE                                     ; $E091: D1
    XOR A                                      ; $E092: AF
    LD C,A                                     ; $E093: 4F
    CALL DivideRatioByte                       ; $E094: CD 92 E5  projected size = 256*radius/depth
    LD H,C                                     ; $E097: 61
    LD A,C                                     ; $E098: 79
    LD (ProjectedObjectSize),A                 ; $E099: 32 0B DA  ProjectedObjectSize = projected size
    LD E,C                                     ; $E09C: 59
    LD A,(ProjectedY)                          ; $E09D: 3A EA E2
    LD C,A                                     ; $E0A0: 4F
    SUB H                                      ; $E0A1: 94
    JR C,L_E0A9                                ; $E0A2: 38 05  ProjectedY < size: overlaps row 63
    SUB $40                                    ; $E0A4: D6 40  ProjectedY - size >= 64: off-screen
    JP NC,DrawAiBeamFromCentre                 ; $E0A6: D2 06 E2  off-screen: only a laser beam
L_E0A9:
    LD A,(ProjectedX)                          ; $E0A9: 3A E9 E2
    LD B,A                                     ; $E0AC: 47
    SUB H                                      ; $E0AD: 94
    JR C,L_E0B5                                ; $E0AE: 38 05  ProjectedX < size: overlaps column 127
    SUB $80                                    ; $E0B0: D6 80  ProjectedX - size >= 128: off-screen
    JP NC,DrawAiBeamFromCentre                 ; $E0B2: D2 06 E2  off-screen: only a laser beam

; VERIFIED: Crosshair target: D = ProjectedX + ProjectedY.  If below the projected size (ProjectedObjectSize)
; and z high byte (IX+7) < $2C, store the caller's stacked AF high byte in TargetedObjectCounter
; (POP HL/POP AF/PUSH/PUSH reads below the return address).  From the object loop at
; $DBA6 that byte is the remaining-slot counter pushed at $DA9A.
; NOTE: (IX+7) is the z high byte even in the left/right views.
L_E0B5:
    LD A,B                                     ; $E0B5: 78
    ADD A,C                                    ; $E0B6: 81
    LD D,A                                     ; $E0B7: 57  D = ProjectedX + ProjectedY
    JR C,L_E0FA                                ; $E0B8: 38 40  over 255: far from the crosshair
    SUB E                                      ; $E0BA: 93  inside the projected size?
    JR NC,CancelAvoidanceInSights              ; $E0BB: 30 0E
    LD A,(IX+$07)                              ; $E0BD: DD 7E 07
    CP $2C                                     ; $E0C0: FE 2C  z high byte < $2C
    JR NC,CancelAvoidanceInSights              ; $E0C2: 30 07
    POP HL                                     ; $E0C4: E1  peek at the caller's stacked AF (update-loop counter)
    POP AF                                     ; $E0C5: F1
    PUSH AF                                    ; $E0C6: F5
    PUSH HL                                    ; $E0C7: E5
    LD (TargetedObjectCounter),A               ; $E0C8: 32 12 DA  TargetedObjectCounter = counter of the object under the crosshair

; VERIFIED: For counted (+$20 bit 6) hostile (+$21 bit 2) ships: if the local z axis component
; along the view axis (+$0E in front/rear views, +$0A in left/right views) has magnitude
; >= $40 (either sign) and ProjectedX+ProjectedY < $20, clear the avoidance flag
; (IX+$26) bit 5, so the steering at L_F8B3 uses only the small $0200 box again.
; B and E are loaded but unused.
; Evidence: tools/check_routines.py pipeline/p9-avoidance-in-sights (all four gates,
; both view axes).
CancelAvoidanceInSights:
    BIT 6,(IX+$20)                             ; $E0CB: DD CB 20 76
    JR Z,L_E0FA                                ; $E0CF: 28 29  not counted: skip
    BIT 2,(IX+$21)                             ; $E0D1: DD CB 21 56
    JR Z,L_E0FA                                ; $E0D5: 28 23  not hostile: skip
    LD A,(CurrentScreenId)                     ; $E0D7: 3A 41 70
    BIT 1,A                                    ; $E0DA: CB 4F
    LD A,(IX+$0E)                              ; $E0DC: DD 7E 0E  front/rear: local z axis, z part
    LD E,(IX+$07)                              ; $E0DF: DD 5E 07  E is not used
    JR Z,L_E0EA                                ; $E0E2: 28 06
    LD A,(IX+$0A)                              ; $E0E4: DD 7E 0A  left/right: local z axis, x part
    LD E,(IX+$01)                              ; $E0E7: DD 5E 01
L_E0EA:
    LD B,A                                     ; $E0EA: 47
    AND $7F                                    ; $E0EB: E6 7F
    CP $40                                     ; $E0ED: FE 40  |component| >= $40: aimed along the view axis
    JR C,L_E0FA                                ; $E0EF: 38 09
    LD A,D                                     ; $E0F1: 7A
    CP $20                                     ; $E0F2: FE 20  near the crosshair (sum < $20)
    JR NC,L_E0FA                               ; $E0F4: 30 04
    RES 5,(IX+$26)                             ; $E0F6: DD CB 26 AE  drop the avoidance flag
L_E0FA:
    BIT 4,(IX+$20)                             ; $E0FA: DD CB 20 66  bit 4: destroyed, record its position
    JP NZ,RecordExplosionPosition              ; $E0FE: C2 D4 E1
    LD A,(MissionAspEncounterState)            ; $E101: 3A 0C DA  state 1 hides the marked mission ship
    DEC A                                      ; $E104: 3D
    JR NZ,L_E10E                               ; $E105: 20 07
    BIT 6,(IX+$26)                             ; $E107: DD CB 26 76
    JP NZ,DrawAiBeamFromCentre                 ; $E10B: C2 06 E2  marked ship: beam only

; VERIFIED: Choose the drawing form: depth high byte < blueprint +$0B (visibility distance) ->
; full wireframe at DrawObjectWireframe.  Otherwise plot a 2x2 XOR dot at (127 +/- ProjectedX,
; 63 +/- ProjectedY) when ProjectedX < $7F and ProjectedY < $3F; the rear and right
; views mirror the horizontal sign (XOR 2).
; Either way the beam test (DrawAiBeamFromCentre) follows.
L_E10E:
    LD HL,(ObjectViewDepth)                    ; $E10E: 2A E0 E2
    LD A,H                                     ; $E111: 7C
    CP (IY+$0B)                                ; $E112: FD BE 0B  blueprint +$0B: wireframe when depth high byte below it
    JR C,DrawObjectWireframe                   ; $E115: 38 5E
    LD A,(ProjectedX)                          ; $E117: 3A E9 E2
    CP $7F                                     ; $E11A: FE 7F  dot only inside the view
    JP NC,DrawAiBeamFromCentre                 ; $E11C: D2 06 E2  too far off-centre for a dot: beam only
    LD C,A                                     ; $E11F: 4F
    LD A,(ProjectedY)                          ; $E120: 3A EA E2
    CP $3F                                     ; $E123: FE 3F  ProjectedY < $3F
    JP NC,DrawAiBeamFromCentre                 ; $E125: D2 06 E2
    LD B,A                                     ; $E128: 47
    LD A,(CurrentScreenId)                     ; $E129: 3A 41 70
    BIT 0,A                                    ; $E12C: CB 47  views 1 (rear) and 3 (right)
    LD A,(ProjectedQuadrant)                   ; $E12E: 3A EB E2
    JR Z,L_E135                                ; $E131: 28 02
    XOR $02                                    ; $E133: EE 02  rear/right view mirrors the horizontal sign
L_E135:
    LD D,A                                     ; $E135: 57
    BIT 1,D                                    ; $E136: CB 4A  bit 1: left of the centre
    JR NZ,L_E140                               ; $E138: 20 06
    LD A,C                                     ; $E13A: 79
    ADD A,$7F                                  ; $E13B: C6 7F  C = 127 + ProjectedX
    LD C,A                                     ; $E13D: 4F
    JR L_E144                                  ; $E13E: 18 04
L_E140:
    LD A,$7F                                   ; $E140: 3E 7F
    SUB C                                      ; $E142: 91  C = 127 - ProjectedX
    LD C,A                                     ; $E143: 4F
L_E144:
    BIT 0,D                                    ; $E144: CB 42  bit 0: below the centre
    JR Z,L_E14E                                ; $E146: 28 06
    LD A,B                                     ; $E148: 78
    ADD A,$3F                                  ; $E149: C6 3F  B = 63 + ProjectedY (row from the top)
    LD B,A                                     ; $E14B: 47
    JR L_E152                                  ; $E14C: 18 04
L_E14E:
    LD A,$3F                                   ; $E14E: 3E 3F
    SUB B                                      ; $E150: 90  B = 63 - ProjectedY
    LD B,A                                     ; $E151: 47
L_E152:
    CALL ToggleViewPixel                       ; $E152: CD 64 E1  2x2 dot: (C,B), (C,B+1), (C+1,B+1), (C+1,B)
    INC B                                      ; $E155: 04
    CALL ToggleViewPixel                       ; $E156: CD 64 E1
    INC C                                      ; $E159: 0C
    CALL ToggleViewPixel                       ; $E15A: CD 64 E1
    DEC B                                      ; $E15D: 05
    CALL ToggleViewPixel                       ; $E15E: CD 64 E1
    JP DrawAiBeamFromCentre                    ; $E161: C3 06 E2  then the beam if it fires

; VERIFIED: XOR one pixel into the view bitmap: C = column 0..255, B = row 0..127 from the top.
; Enters ROM PIXEL-ADD after its row inversion ($22B1: AND A first), so HL = screen
; address of (C,B); SET 7,H moves it from $4000.. to ViewBitmapBuffer ($C000..).
; Output: pixel toggled; B, C preserved; A = new byte; D, HL changed.
; Caller: the 2x2 dot of distant objects (L_E152).
; Evidence: a simulator check in tools/check_routines.py toggled 11008 (x,y) points,
; each exactly one expected bit.
ToggleViewPixel:
    LD A,B                                     ; $E164: 78
    CALL RomPixelAddRow                        ; $E165: CD B1 22  HL = screen address of (C,B), A = C AND 7
    LD D,A                                     ; $E168: 57
    INC D                                      ; $E169: 14  D = bit number + 1
    LD A,$01                                   ; $E16A: 3E 01
L_E16C:
    RRCA                                       ; $E16C: 0F  A = $80 >> (C AND 7)
    DEC D                                      ; $E16D: 15
    JR NZ,L_E16C                               ; $E16E: 20 FC
    SET 7,H                                    ; $E170: CB FC  $4000.. screen address -> $C000.. ViewBitmapBuffer
    XOR (HL)                                   ; $E172: AE  toggle the pixel
    LD (HL),A                                  ; $E173: 77
    RET                                        ; $E174: C9

; VERIFIED: Full wireframe: BuildRotationMatrix; ObjectViewDepth becomes the detail level
; min($1F, high byte of 2*depth) - 2 (not below 0); then ComputeFaceVisibility,
; ProjectVertices and DrawVisibleEdges.  If (IX+$20) bit 3 is set (the ship fired its
; laser this update, see TryFireAiLaser), draw the beam from the gun vertex (blueprint
; +$14) through DrawAiLaserBeam, which clears that bit.
; Evidence: pipeline checks in tools/check_routines.py (object-projection, p9-ai-laser-beam).
DrawObjectWireframe:
    PUSH IY                                    ; $E175: FD E5
    CALL BuildRotationMatrix                   ; $E177: CD F3 E7  clobbers IY
    POP IY                                     ; $E17A: FD E1
    LD HL,(ObjectViewDepth)                    ; $E17C: 2A E0 E2
    ADD HL,HL                                  ; $E17F: 29  HL = 2*depth; carry: beyond 16 bits
    LD B,$1F                                   ; $E180: 06 1F  detail level = min($1F, high byte of 2*depth) ...
    JR C,L_E189                                ; $E182: 38 05
    LD A,H                                     ; $E184: 7C
    CP B                                       ; $E185: B8
    JR NC,L_E189                               ; $E186: 30 01
    LD B,H                                     ; $E188: 44
L_E189:
    LD A,B                                     ; $E189: 78
    SUB $02                                    ; $E18A: D6 02  ... minus 2, not below 0
    JR NC,L_E18F                               ; $E18C: 30 01
    XOR A                                      ; $E18E: AF
L_E18F:
    LD (ObjectViewDepth),A                     ; $E18F: 32 E0 E2  from here the low byte is the detail level
    LD A,$FD                                   ; $E192: 3E FD  vertex buffer offset starts at -3
    LD (VertexBufferOffset),A                  ; $E194: 32 E2 E2
    CALL ComputeFaceVisibility                 ; $E197: CD 23 E9
    CALL ProjectVertices                       ; $E19A: CD F1 E2
    CALL DrawVisibleEdges                      ; $E19D: CD 29 E7
    BIT 3,(IX+$20)                             ; $E1A0: DD CB 20 5E  bit 3: this ship fires its laser
    RET Z                                      ; $E1A4: C8
    LD A,(IY+$14)                              ; $E1A5: FD 7E 14  blueprint +$14: gun vertex
    CALL GetProjectedVertex                    ; $E1A8: CD 78 E7  D,E = gun vertex, A = its quadrant
    LD C,A                                     ; $E1AB: 4F

; VERIFIED: Draw the laser beam of a firing ship: D,E = start (projected magnitudes), C = start
; quadrant (bit 1 left, bit 0 below).  The far end is (255-r, r) for a random r in the
; diagonally opposite quadrant, always beyond the view edge (255-r >= 128 or r >= 64),
; so DrawLine runs from the start to the border.  Then (IX+$20) bit 3 is cleared.
; L_F116 (the view-page operand $C0 of the plot address) is saved, given bit 7 and
; restored; bit 7 is already set in $C0, so this has no effect in this build.
; Clobbers all registers (DrawLine).
; Evidence: tools/check_routines.py combat/p9-ai-laser-beam: the buffer equals the plain
; drawing OR one DrawLine with these end points (dot, wireframe and off-screen cases).
DrawAiLaserBeam:
    CALL NextRandomByte                        ; $E1AC: CD 24 ED  r = random byte
    LD L,A                                     ; $E1AF: 6F  L = r: far end |y|
    SUB $FF                                    ; $E1B0: D6 FF  A = r - 255 ...
    NEG                                        ; $E1B2: ED 44
    LD H,A                                     ; $E1B4: 67  ... negated: H = 255 - r, far end |x|
    LD A,C                                     ; $E1B5: 79
    CPL                                        ; $E1B6: 2F  far end: opposite quadrant
    AND $03                                    ; $E1B7: E6 03
    SLA C                                      ; $E1B9: CB 21  start quadrant to bits 3..2
    SLA C                                      ; $E1BB: CB 21
    OR C                                       ; $E1BD: B1
    LD C,A                                     ; $E1BE: 4F
    LD A,(L_F116)                              ; $E1BF: 3A 16 F1  view page operand of the plot address
    PUSH AF                                    ; $E1C2: F5
    SET 7,A                                    ; $E1C3: CB FF  already set in $C0: no effect
    LD (L_F116),A                              ; $E1C5: 32 16 F1
    CALL DrawLine                              ; $E1C8: CD 10 EE  from the start (DE) to the view edge
    POP AF                                     ; $E1CB: F1
    LD (L_F116),A                              ; $E1CC: 32 16 F1  restore the operand
    RES 3,(IX+$20)                             ; $E1CF: DD CB 20 9E  beam drawn: clear the firing flag
    RET                                        ; $E1D3: C9

; VERIFIED: Object destroyed ((IX+$20) bit 4) and visible in this view: store its screen disc
; parameters for DrawFlaggedObjectDiscs instead of drawing it: (IX+$1C) = ProjectedX
; (CircleOffsetX), (IX+$1D) = ProjectedY (CircleOffsetY), (IX+$1F) = projected size
; ProjectedObjectSize (CircleRadius), (IX+$1E) = $0C + side bits (CircleFlags: bit 0 right of the
; centre, bit 1 above; mirrored in rear/right views).  Sets bit 5: state 11, which
; DrawFlaggedObjectDiscs draws as 15 growing filled discs and then ends with bit 4
; cleared (state 10: removed and credited by L_DB0F).  An object that is behind or off
; this view never gets here and the object loop turns state 01 into 10 directly.
; Evidence: tools/check_routines.py pipeline/p9-explosion-record (all four views).
RecordExplosionPosition:
    LD A,(ProjectedX)                          ; $E1D4: 3A E9 E2
    LD (IX+$1C),A                              ; $E1D7: DD 77 1C  +$1C: CircleOffsetX for the explosion discs
    LD A,(ProjectedY)                          ; $E1DA: 3A EA E2
    LD (IX+$1D),A                              ; $E1DD: DD 77 1D  +$1D: CircleOffsetY
    LD A,(ProjectedObjectSize)                 ; $E1E0: 3A 0B DA
    LD (IX+$1F),A                              ; $E1E3: DD 77 1F  +$1F: CircleRadius (projected size)
    LD A,(CurrentScreenId)                     ; $E1E6: 3A 41 70
    BIT 0,A                                    ; $E1E9: CB 47  views 1 and 3 mirror horizontally
    LD A,(ProjectedQuadrant)                   ; $E1EB: 3A EB E2
    JR Z,L_E1F2                                ; $E1EE: 28 02
    XOR $02                                    ; $E1F0: EE 02
L_E1F2:
    LD C,A                                     ; $E1F2: 4F
    XOR A                                      ; $E1F3: AF
    RR C                                       ; $E1F4: CB 19
    RLA                                        ; $E1F6: 17  vertical sign into A ...
    RR C                                       ; $E1F7: CB 19
    RLA                                        ; $E1F9: 17  ... then horizontal: bit 1 vert., bit 0 horiz.
    XOR $03                                    ; $E1FA: EE 03  invert: bit 0 right, bit 1 above
    ADD A,$0C                                  ; $E1FC: C6 0C  $0C + inverted quadrant bits
    LD (IX+$1E),A                              ; $E1FE: DD 77 1E  +$1E: CircleFlags
    SET 5,(IX+$20)                             ; $E201: DD CB 20 EE  bits 5:4 = 11: DrawFlaggedObjectDiscs draws it
    RET                                        ; $E205: C9

; VERIFIED: Object drawn as a dot, off-screen, or the marked ship in MissionAspEncounterState 1:
; if (IX+$20) bit 3 is set, draw the AI laser beam from the projected centre
; (ProjectedX, ProjectedY, ProjectedQuadrant mirrored in the rear/right views) via
; DrawAiLaserBeam.  Evidence: tools/check_routines.py combat/p9-ai-laser-beam.
DrawAiBeamFromCentre:
    BIT 3,(IX+$20)                             ; $E206: DD CB 20 5E
    RET Z                                      ; $E20A: C8
    LD A,(ProjectedX)                          ; $E20B: 3A E9 E2
    LD D,A                                     ; $E20E: 57  D = horizontal offset of the centre
    LD A,(ProjectedY)                          ; $E20F: 3A EA E2
    LD E,A                                     ; $E212: 5F  E = vertical offset
    LD A,(CurrentScreenId)                     ; $E213: 3A 41 70
    BIT 0,A                                    ; $E216: CB 47  views 1 and 3 mirror horizontally
    LD A,(ProjectedQuadrant)                   ; $E218: 3A EB E2
    JR Z,L_E21F                                ; $E21B: 28 02
    XOR $02                                    ; $E21D: EE 02
L_E21F:
    LD C,A                                     ; $E21F: 4F
    JR DrawAiLaserBeam                         ; $E220: 18 8A  beam from the object centre

; ============================================================================
; 3D renderer workspace
; Projected-vertex buffer, face-visibility flags, rotation matrix, row
; product cache and per-vertex scratch variables used by DrawObjectInView.
; ============================================================================

; VERIFIED: Projected vertices, 3 bytes each, indexed by vertex number: ProjectedX, ProjectedY,
; then quadrant bits (bit 1 = left of centre, bit 0 = below centre) or $FF when the
; vertex is behind the view.  Written at $E6FC, read by GetProjectedVertex.  138 bytes = room for
; 46 vertices; the largest blueprint has 28 (runtime writes cover $E222..$E275).
; The first 8 initial bytes repeat code bytes $E21A..$E221: stale assembly leftovers,
; overwritten before use.
ProjectedVertexBuffer:
    defb $E2,$28,$02,$EE,$02,$4F,$18,$8A,$00,$00,$00,$00                                  ; $E222 .(...O......
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E22E ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E23A ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E246 ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E252 ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E25E ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E26A ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E276 ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E282 ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E28E ............
    defb $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00                                  ; $E29A ............
    defb $00,$00,$00,$00,$00,$00                                                          ; $E2A6 ......

; VERIFIED: One byte per face index 0..15: 1 = visible, 0 = hidden.
; ComputeFaceVisibility writes entries 0..face count-1 (at most 14); entries 14 and
; 15 keep their initial 1, so face nibble
; 15 in vertex/edge records means 'always visible'.  A blueprint without faces (alloy
; plate) sets entry 0 to 1.  Read through TestFaceVisible.
FaceVisibilityFlags:
    defb $01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01,$01                  ; $E2AC ................

; VERIFIED: 3 rows of 3 words (row stride 6): row r holds the r-th components of orientation
; vectors X, Y, Z (instance +$16/+$10/+$0A + 2r).  Only the high (odd) bytes are
; written, by BuildRotationMatrix; the even bytes are unused (initial bytes stale).
; Rotated vertex coordinate r = x*row[0] + y*row[1] + z*row[2] (RotateRow).
RotationMatrix:
    defb $7E,$32,$81,$8D,$F3,$24                                                          ; $E2BC ~2...$
    defb $81,$8D,$7E,$32,$F3,$24                                                          ; $E2C2 ..~2.$
    defb $F2,$A4,$F2,$A4,$F3,$24                                                          ; $E2C8 .....$

; VERIFIED: Per matrix row, three terms (magnitude byte, sign byte) of the last rotated vertex,
; written by RotateRow/L_E3B4 at IY+$12..$17.  Reused with sign flips
; (ReuseRowProducts, RotateRowPrecise) when the next vertex has the same magnitudes
; (RowCacheInvalid = 0).  The initial bytes are stale.
RowProductCache:
    defb $F3,$24,$F2,$A4,$F2,$A4                                                          ; $E2CE .$....
    defb $F3,$24,$00,$00,$00,$00                                                          ; $E2D4 .$....
    defb $00,$00,$00,$00,$00,$00                                                          ; $E2DA ......

; VERIFIED: Word: depth magnitude of the object centre (z or x, see DrawObjectInView).
; After $E18F the low byte is the detail level min($1F, high(2*depth)) - 2, clamped at 0, compared
; with vertex/face/edge visibility thresholds (drawn when threshold = $1F or level
; < threshold); levels 0..3 select the precise vertex path (L_E5CB).
ObjectViewDepth:
    defw $0000                                                                            ; $E2E0

; VERIFIED: Byte offset of the current vertex in ProjectedVertexBuffer; set to $FD before the
; vertex loop and advanced by 3 per vertex at $E306.
VertexBufferOffset:
    defb $01                                                                              ; $E2E2 .

; VERIFIED: Rotated, then (L_E607) view-relative vertex x as 16-bit sign-magnitude (bit 15 sign).
; In left/right views x is the depth axis.
VertexX:
    defw $0000                                                                            ; $E2E3

; VERIFIED: Rotated, then view-relative vertex y (16-bit sign-magnitude).
VertexY:
    defw $0000                                                                            ; $E2E5

; VERIFIED: Rotated, then view-relative vertex z (16-bit sign-magnitude).
VertexZ:
    defw $0000                                                                            ; $E2E7

; VERIFIED: Horizontal screen offset magnitude from the view centre: min(255, 256*h/depth) with
; h = x (front/rear) or z (left/right).  Also used for the object centre.
ProjectedX:
    defb $00                                                                              ; $E2E9 .

; VERIFIED: Vertical screen offset magnitude: min(255, 256*|y|/depth).
ProjectedY:
    defb $00                                                                              ; $E2EA .

; VERIFIED: Bit 1 = horizontal sign, bit 0 = vertical sign of the projected point.  For vertices
; the stored value is masked to 2 bits and already mirrored for the rear/right views;
; for the object centre ($E086) the raw sign bits are stored and consumers mirror.
ProjectedQuadrant:
    defb $00                                                                              ; $E2EB .

; VERIFIED: Sign byte (bit 7) of the view-relative VertexX from TranslateVertexAxis.
VertexSignX:
    defb $00                                                                              ; $E2EC .

; VERIFIED: Sign byte (bit 7) of the view-relative VertexY.
VertexSignY:
    defb $00                                                                              ; $E2ED .

; VERIFIED: Sign byte (bit 7) of the view-relative VertexZ.
VertexSignZ:
    defb $00                                                                              ; $E2EE .

; VERIFIED: Precise vertex path: number of leading zero bits of |x| OR |y| OR |z| of the
; model vertex (1..7).  Coordinates are shifted left by it before the 8-bit
; multiplications (L_E447) and the sums shifted back with fraction bits (L_E40C).
VertexNormaliseShift:
    defb $00                                                                              ; $E2EF .

; VERIFIED: 0 = RowProductCache holds the products of the previous vertex; nonzero after a
; vertex was skipped ($E330), so the next vertex recomputes its products.
RowCacheInvalid:
    defb $00                                                                              ; $E2F0 .

; VERIFIED: Rotate, translate and project every vertex of the blueprint into
; ProjectedVertexBuffer.  IX = instance, IY = blueprint; RotationMatrix,
; FaceVisibilityFlags and ObjectViewDepth (detail level) must be prepared.
; A vertex is processed when its threshold allows the detail level and one of its four
; faces (two nibbles in each of bytes 4 and 5) is visible; other entries keep stale
; data (edges test the same faces).  Each processed vertex goes through L_E5CB
; (rotation, precise or normal) and L_E607 (translation, projection, buffer entry).
; Output: buffer filled, RowCacheInvalid updated; IX, IY restored.  Clobbers AF, BC, DE, HL.
; Evidence: pipeline check against a float model; runtime flight scenarios.
ProjectVertices:
    PUSH IY                                    ; $E2F1: FD E5
    PUSH IY                                    ; $E2F3: FD E5  second copy becomes IX ...
    LD A,(IY+$03)                              ; $E2F5: FD 7E 03  blueprint +3: vertex count
    EX (SP),IX                                 ; $E2F8: DD E3  ... IX = blueprint, instance saved
    LD D,(IY+$0D)                              ; $E2FA: FD 56 0D  blueprint +$0C/$0D: vertex table offset
    LD E,(IY+$0C)                              ; $E2FD: FD 5E 0C
    ADD IX,DE                                  ; $E300: DD 19  IX = first vertex record
    LD IY,RotationMatrix                       ; $E302: FD 21 BC E2  IY = matrix row 0

; VERIFIED: Per-vertex loop: A = vertices left (pushed), IX = vertex record, IY = RotationMatrix.
L_E306:
    PUSH AF                                    ; $E306: F5
    LD A,(VertexBufferOffset)                  ; $E307: 3A E2 E2
    ADD A,$03                                  ; $E30A: C6 03  three bytes per projected vertex
    LD (VertexBufferOffset),A                  ; $E30C: 32 E2 E2
    LD A,(IX+$03)                              ; $E30F: DD 7E 03  vertex visibility threshold (bits 0..4)
    AND $1F                                    ; $E312: E6 1F
    CP $1F                                     ; $E314: FE 1F  $1F: visible at any distance
    JR Z,L_E31F                                ; $E316: 28 07
    LD B,A                                     ; $E318: 47
    LD A,(ObjectViewDepth)                     ; $E319: 3A E0 E2
    CP B                                       ; $E31C: B8
    JR NC,L_E330                               ; $E31D: 30 11  detail level >= threshold: skip
L_E31F:
    LD A,(IX+$04)                              ; $E31F: DD 7E 04  face nibbles of the vertex (bytes 4 and 5)
    CALL TestFacePairVisible                   ; $E322: CD 38 E3
    JR NZ,L_E32D                               ; $E325: 20 06
    LD A,(IX+$05)                              ; $E327: DD 7E 05
    CALL TestFacePairVisible                   ; $E32A: CD 38 E3
L_E32D:
    JP NZ,L_E5CB                               ; $E32D: C2 CB E5  a face is visible: transform it
L_E330:
    INC A                                      ; $E330: 3C  skipped: RowCacheInvalid becomes nonzero
    LD (RowCacheInvalid),A                     ; $E331: 32 F0 E2
    POP AF                                     ; $E334: F1  A = vertices left
    JP L_E71A                                  ; $E335: C3 1A E7

; VERIFIED: A = byte with two face nibbles.  NZ if FaceVisibilityFlags of either nibble is set
; (low nibble tested first, high nibble returned in B and tested second); A = the last
; flag read.  Clobbers A, B, HL.
TestFacePairVisible:
    LD B,A                                     ; $E338: 47
    SRL B                                      ; $E339: CB 38  B = high nibble
    SRL B                                      ; $E33B: CB 38
    SRL B                                      ; $E33D: CB 38
    SRL B                                      ; $E33F: CB 38
    AND $0F                                    ; $E341: E6 0F  A = low nibble
    CALL TestFaceVisible                       ; $E343: CD 48 E3
    RET NZ                                     ; $E346: C0  first face visible: NZ
    LD A,B                                     ; $E347: 78  then the high-nibble face

; VERIFIED: A = face index 0..15.  A = FaceVisibilityFlags[index], Z if hidden.  HL = entry.
TestFaceVisible:
    LD HL,FaceVisibilityFlags                  ; $E348: 21 AC E2
    ADD A,L                                    ; $E34B: 85  HL = FaceVisibilityFlags + A
    LD L,A                                     ; $E34C: 6F
    JR NC,L_E350                               ; $E34D: 30 01
    INC H                                      ; $E34F: 24
L_E350:
    LD A,(HL)                                  ; $E350: 7E
    AND A                                      ; $E351: A7  Z: hidden
    RET                                        ; $E352: C9

; VERIFIED: Precise path, one matrix row (IY = row, IX = vertex record): sum of the three
; products of the vertex magnitudes shifted left by VertexNormaliseShift with the row's
; sign-magnitude bytes; reuses RowProductCache when RowCacheInvalid = 0 and the
; vertex magnitudes equal the previous record's (IX-6..IX-4).  Shifts back in L_E40C:
; HL = 16-bit sign-magnitude sum, A = fraction bits.  IY advances by 6.
RotateRowPrecise:
    LD A,(RowCacheInvalid)                     ; $E353: 3A F0 E2  cache valid only after a processed vertex
    AND A                                      ; $E356: A7
    JR NZ,L_E3B4                               ; $E357: 20 5B
    LD A,(IX+$00)                              ; $E359: DD 7E 00  same magnitudes as the previous vertex?
    CP (IX-$06)                                ; $E35C: DD BE FA
    JR NZ,L_E3B4                               ; $E35F: 20 53
    LD A,(IX+$01)                              ; $E361: DD 7E 01
    CP (IX-$05)                                ; $E364: DD BE FB
    JR NZ,L_E3B4                               ; $E367: 20 4B
    LD A,(IX+$02)                              ; $E369: DD 7E 02
    CP (IX-$04)                                ; $E36C: DD BE FC
    JR NZ,L_E3B4                               ; $E36F: 20 43
    LD A,(IX+$03)                              ; $E371: DD 7E 03  B = sign differences from the previous vertex
    XOR (IX-$03)                               ; $E374: DD AE FD
    LD B,A                                     ; $E377: 47
    LD L,(IY+$12)                              ; $E378: FD 6E 12  cached x term (magnitude, sign)
    LD H,(IY+$13)                              ; $E37B: FD 66 13
    LD E,(IY+$14)                              ; $E37E: FD 5E 14  cached y term
    LD D,(IY+$15)                              ; $E381: FD 56 15
    XOR H                                      ; $E384: AC  flip the x term where the x signs differ
    AND $80                                    ; $E385: E6 80
    LD H,A                                     ; $E387: 67
    LD (IY+$13),H                              ; $E388: FD 74 13
    RL B                                       ; $E38B: CB 10  y sign difference to bit 7
    LD A,B                                     ; $E38D: 78
    XOR D                                      ; $E38E: AA
    AND $80                                    ; $E38F: E6 80
    LD D,A                                     ; $E391: 57
    LD (IY+$15),D                              ; $E392: FD 72 15
    CALL AddSignMagnitude                      ; $E395: CD 24 E4  x term + y term
    LD L,A                                     ; $E398: 6F
    LD E,(IY+$16)                              ; $E399: FD 5E 16  cached z term
    LD D,(IY+$17)                              ; $E39C: FD 56 17
    LD A,B                                     ; $E39F: 78
    RLA                                        ; $E3A0: 17  z sign difference to bit 7
    XOR D                                      ; $E3A1: AA
    AND $80                                    ; $E3A2: E6 80
    LD D,A                                     ; $E3A4: 57
    LD (IY+$17),D                              ; $E3A5: FD 72 17
    CALL AddSignMagnitude                      ; $E3A8: CD 24 E4  + z term
    LD L,A                                     ; $E3AB: 6F
    LD DE,$0006                                ; $E3AC: 11 06 00  next matrix row
    ADD IY,DE                                  ; $E3AF: FD 19
    JP L_E40C                                  ; $E3B1: C3 0C E4  scale the sum back
L_E3B4:
    LD B,(IX+$00)                              ; $E3B4: DD 46 00  x magnitude
    CALL L_E447                                ; $E3B7: CD 47 E4  L = (|x| << shift) * |row x| / 256
    LD A,(IX+$03)                              ; $E3BA: DD 7E 03  term sign = x sign XOR row sign
    XOR (IY+$01)                               ; $E3BD: FD AE 01
    RLA                                        ; $E3C0: 17
    RR H                                       ; $E3C1: CB 1C
    LD (IY+$12),L                              ; $E3C3: FD 75 12  cache the x term
    LD (IY+$13),H                              ; $E3C6: FD 74 13
    EX DE,HL                                   ; $E3C9: EB  DE = x term
    INC IY                                     ; $E3CA: FD 23
    INC IY                                     ; $E3CC: FD 23
    LD B,(IX+$01)                              ; $E3CE: DD 46 01  y magnitude
    CALL L_E447                                ; $E3D1: CD 47 E4  same for y
    LD A,(IX+$03)                              ; $E3D4: DD 7E 03  y sign (bit 6) XOR row sign
    RLA                                        ; $E3D7: 17
    XOR (IY+$01)                               ; $E3D8: FD AE 01
    RLA                                        ; $E3DB: 17
    RR H                                       ; $E3DC: CB 1C
    LD (IY+$12),L                              ; $E3DE: FD 75 12
    LD (IY+$13),H                              ; $E3E1: FD 74 13
    CALL AddSignMagnitude                      ; $E3E4: CD 24 E4  x term + y term
    LD L,A                                     ; $E3E7: 6F
    EX DE,HL                                   ; $E3E8: EB
    INC IY                                     ; $E3E9: FD 23
    INC IY                                     ; $E3EB: FD 23
    LD B,(IX+$02)                              ; $E3ED: DD 46 02  z magnitude
    CALL L_E447                                ; $E3F0: CD 47 E4  same for z
    LD A,(IX+$03)                              ; $E3F3: DD 7E 03  z sign (bit 5) XOR row sign
    RLA                                        ; $E3F6: 17
    RLA                                        ; $E3F7: 17
    XOR (IY+$01)                               ; $E3F8: FD AE 01
    RLA                                        ; $E3FB: 17
    RR H                                       ; $E3FC: CB 1C
    LD (IY+$12),L                              ; $E3FE: FD 75 12
    LD (IY+$13),H                              ; $E401: FD 74 13
    CALL AddSignMagnitude                      ; $E404: CD 24 E4  + z term
    LD L,A                                     ; $E407: 6F
    INC IY                                     ; $E408: FD 23
    INC IY                                     ; $E40A: FD 23

; VERIFIED: Shift HL right by VertexNormaliseShift, collecting the dropped bits in A (fraction),
; then restore the sign from the original H bit 7.  The INC HL rounding branch
; cannot be taken because the shift count is at most 7.
L_E40C:
    LD A,(VertexNormaliseShift)                ; $E40C: 3A EF E2
    LD B,A                                     ; $E40F: 47  B = shift count
    XOR A                                      ; $E410: AF
    LD C,H                                     ; $E411: 4C  C = sign byte
    RES 7,H                                    ; $E412: CB BC
L_E414:
    SRL H                                      ; $E414: CB 3C  shift right, dropped bits into A
    RR L                                       ; $E416: CB 1D
    RRA                                        ; $E418: 1F
    DJNZ L_E414                                ; $E419: 10 F9
    JR NC,L_E41E                               ; $E41B: 30 01  never taken: at most 7 shifts
    INC HL                                     ; $E41D: 23
L_E41E:
    BIT 7,C                                    ; $E41E: CB 79  restore the sign
    RET Z                                      ; $E420: C8
    SET 7,H                                    ; $E421: CB FC
    RET                                        ; $E423: C9

; VERIFIED: Add two sign-magnitude bytes: magnitudes L and E, signs in bit 7 of H and D.
; Same signs: A = L+E (sign stays in H); carry is set only when this sum
; overflows 255.  Different signs: A = |L-E|, carry clear, and H takes the sign
; of the larger magnitude (D's sign when E > L).
AddSignMagnitude:
    LD A,H                                     ; $E424: 7C
    XOR D                                      ; $E425: AA
    RLA                                        ; $E426: 17  carry = signs differ
    JR C,L_E42C                                ; $E427: 38 03
    LD A,L                                     ; $E429: 7D
    ADD A,E                                    ; $E42A: 83  same signs: L + E, carry = overflow
    RET                                        ; $E42B: C9
L_E42C:
    LD A,L                                     ; $E42C: 7D
    SUB E                                      ; $E42D: 93  different signs: L - E
    RET NC                                     ; $E42E: D0  L >= E: H keeps its sign
    NEG                                        ; $E42F: ED 44  E > L: magnitude E - L ...
    AND A                                      ; $E431: A7
    LD H,D                                     ; $E432: 62  ... with D's sign
    RET                                        ; $E433: C9

; VERIFIED: A = high byte of the quarter-square product of B and C: high(s*s) -
; high(d*d) with s and d as in MultiplyUnsigned.  The low-byte borrow is
; ignored, so A can be one more than the high byte of MultiplyUnsigned.
MultiplyUnsignedHigh:
    LD A,B                                     ; $E434: 78
    SUB C                                      ; $E435: 91
    JR NC,L_E43A                               ; $E436: 30 02
    NEG                                        ; $E438: ED 44  |B - C|
L_E43A:
    SRL A                                      ; $E43A: CB 3F  d = |B - C| >> 1
    LD H,(SquareLookupTables >> 8) + 1         ; $E43C: 26 BF
    LD L,A                                     ; $E43E: 6F
    LD D,(HL)                                  ; $E43F: 56  D = high byte of d*d
    LD A,B                                     ; $E440: 78
    ADD A,C                                    ; $E441: 81
    RRA                                        ; $E442: 1F  s = (B + C) >> 1 with the 9th bit
    LD L,A                                     ; $E443: 6F
    LD A,(HL)                                  ; $E444: 7E
    SUB D                                      ; $E445: 92  A = high(s*s) - high(d*d)
    RET                                        ; $E446: C9

; VERIFIED: B = vertex magnitude << VertexNormaliseShift, C = |row entry (IY+1)|;
; HL = MultiplyUnsignedHigh(B, C) (H = 0).  DE preserved.
L_E447:
    LD A,(VertexNormaliseShift)                ; $E447: 3A EF E2
L_E44A:
    SLA B                                      ; $E44A: CB 20  B <<= VertexNormaliseShift
    DEC A                                      ; $E44C: 3D
    JR NZ,L_E44A                               ; $E44D: 20 FB
    LD C,(IY+$01)                              ; $E44F: FD 4E 01  C = |matrix entry|
    RES 7,C                                    ; $E452: CB B9
    PUSH DE                                    ; $E454: D5
    CALL MultiplyUnsignedHigh                  ; $E455: CD 34 E4
    LD L,A                                     ; $E458: 6F  HL = product high byte
    LD H,$00                                   ; $E459: 26 00
    POP DE                                     ; $E45B: D1
    RET                                        ; $E45C: C9

; VERIFIED: HL = B*C by quarter squares: s = (B+C) >> 1 (9-bit sum), d = |B-C| >> 1,
; HL = s*s - d*d from the square tables.  Exact when B+C is even; when it is
; odd the result is B*C - min(B,C).  A, D, E and flags are also changed.
MultiplyUnsigned:
    LD A,B                                     ; $E45D: 78
    SUB C                                      ; $E45E: 91
    JR NC,L_E463                               ; $E45F: 30 02
    NEG                                        ; $E461: ED 44
L_E463:
    SRL A                                      ; $E463: CB 3F  d = |B - C| >> 1
    LD H,SquareLookupTables >> 8               ; $E465: 26 BE
    LD L,A                                     ; $E467: 6F
    LD E,(HL)                                  ; $E468: 5E  DE = d*d
    INC H                                      ; $E469: 24
    LD D,(HL)                                  ; $E46A: 56
    DEC H                                      ; $E46B: 25
    LD A,B                                     ; $E46C: 78
    ADD A,C                                    ; $E46D: 81
    RRA                                        ; $E46E: 1F  s = (B + C) >> 1 with the 9th bit
    LD L,A                                     ; $E46F: 6F
    LD A,(HL)                                  ; $E470: 7E  HL = s*s
    INC H                                      ; $E471: 24
    LD H,(HL)                                  ; $E472: 66
    LD L,A                                     ; $E473: 6F
    AND A                                      ; $E474: A7
    SBC HL,DE                                  ; $E475: ED 52  HL = s*s - d*d
    RET                                        ; $E477: C9

; VERIFIED: Add a rotated vertex term to an instance coordinate.  HL = 16-bit magnitude, B = sign
; byte (bit 7) of the instance coordinate; DE = rotated value (sign-magnitude), doubled
; with the caller's carry (fraction bit 7) as new bit 0.  Output: HL = |sum|, A = sign.
; When the coordinate is the larger magnitude of a difference, it subtracts the fraction
; too: it negates the fraction in the caller's stacked AF (POP DE/POP AF/NEG/PUSH AF/
; PUSH DE) and decrements HL (also when that fraction is 0, one unit low then).
TranslateVertexAxis:
    LD C,D                                     ; $E478: 4A  C = sign of the rotated value
    RL E                                       ; $E479: CB 13  DE = 2*|value| + caller's carry
    RL D                                       ; $E47B: CB 12
    LD A,B                                     ; $E47D: 78
    XOR C                                      ; $E47E: A9
    JR NZ,L_E484                               ; $E47F: 20 03  signs differ?
    ADD HL,DE                                  ; $E481: 19  same signs: add magnitudes
    LD A,B                                     ; $E482: 78
    RET                                        ; $E483: C9
L_E484:
    SBC HL,DE                                  ; $E484: ED 52  coordinate - value
    JR NC,L_E48F                               ; $E486: 30 07
    ADD HL,DE                                  ; $E488: 19  value larger: value - coordinate ...
    EX DE,HL                                   ; $E489: EB
    AND A                                      ; $E48A: A7
    SBC HL,DE                                  ; $E48B: ED 52
    LD A,C                                     ; $E48D: 79  ... with the value's sign
    RET                                        ; $E48E: C9
L_E48F:
    LD A,H                                     ; $E48F: 7C  difference 0: no borrow
    OR L                                       ; $E490: B5
    LD A,C                                     ; $E491: 79
    RET Z                                      ; $E492: C8
    POP DE                                     ; $E493: D1  borrow from the fraction in the ...
    POP AF                                     ; $E494: F1
    NEG                                        ; $E495: ED 44  ... caller's stacked A
    PUSH AF                                    ; $E497: F5
    PUSH DE                                    ; $E498: D5
    DEC HL                                     ; $E499: 2B  integer part - 1
    LD A,B                                     ; $E49A: 78  A = coordinate sign
    RET                                        ; $E49B: C9

; VERIFIED: Normal-precision path (detail level >= 4, or a vertex whose largest magnitude already
; uses bit 7): three RotateRow row products (ReuseRowProducts for a vertex with the
; previous record's magnitudes) into VertexX/Y/Z; fraction bytes cleared; continues
; at L_E607.
L_E49C:
    LD A,(RowCacheInvalid)                     ; $E49C: 3A F0 E2  cache usable?
    AND A                                      ; $E49F: A7
    PUSH IX                                    ; $E4A0: DD E5
    JR NZ,L_E4C8                               ; $E4A2: 20 24
    LD B,$03                                   ; $E4A4: 06 03  compare the three magnitudes
L_E4A6:
    LD A,(IX+$00)                              ; $E4A6: DD 7E 00
    CP (IX-$06)                                ; $E4A9: DD BE FA
    JR NZ,L_E4C8                               ; $E4AC: 20 1A
    INC IX                                     ; $E4AE: DD 23
    DJNZ L_E4A6                                ; $E4B0: 10 F4
    POP IX                                     ; $E4B2: DD E1
    CALL ReuseRowProducts                      ; $E4B4: CD E9 E4  same magnitudes: re-sign the cache
    LD (VertexX),HL                            ; $E4B7: 22 E3 E2
    CALL ReuseRowProducts                      ; $E4BA: CD E9 E4
    LD (VertexY),HL                            ; $E4BD: 22 E5 E2
    CALL ReuseRowProducts                      ; $E4C0: CD E9 E4
    LD (VertexZ),HL                            ; $E4C3: 22 E7 E2
    JR L_E4DC                                  ; $E4C6: 18 14
L_E4C8:
    POP IX                                     ; $E4C8: DD E1
    CALL RotateRow                             ; $E4CA: CD 2A E5  VertexX = row 0 . v
    LD (VertexX),HL                            ; $E4CD: 22 E3 E2
    CALL RotateRow                             ; $E4D0: CD 2A E5  VertexY = row 1 . v
    LD (VertexY),HL                            ; $E4D3: 22 E5 E2
    CALL RotateRow                             ; $E4D6: CD 2A E5  VertexZ = row 2 . v
    LD (VertexZ),HL                            ; $E4D9: 22 E7 E2
L_E4DC:
    XOR A                                      ; $E4DC: AF  normal path: no fraction bits
    LD (VertexFractionX),A                     ; $E4DD: 32 C8 E5
    LD (VertexFractionY),A                     ; $E4E0: 32 C9 E5
    LD (VertexFractionZ),A                     ; $E4E3: 32 CA E5
    JP L_E607                                  ; $E4E6: C3 07 E6  translate and project

; VERIFIED: Mirrored-vertex shortcut: the vertex at IX has the same magnitudes as the previous
; record (IX-6), so flip the signs of the cached RowProductCache terms where the sign
; bits differ ((IX+3) XOR (IX-3)) and re-add them.  HL = L magnitude, H sign; IY += 6.
ReuseRowProducts:
    LD A,(IX+$03)                              ; $E4E9: DD 7E 03  sign differences from the previous vertex
    XOR (IX-$03)                               ; $E4EC: DD AE FD
    LD B,A                                     ; $E4EF: 47
    LD L,(IY+$12)                              ; $E4F0: FD 6E 12  cached x term
    LD H,(IY+$13)                              ; $E4F3: FD 66 13
    LD E,(IY+$14)                              ; $E4F6: FD 5E 14  cached y term
    LD D,(IY+$15)                              ; $E4F9: FD 56 15
    XOR H                                      ; $E4FC: AC  flip the x term where the signs differ
    AND $80                                    ; $E4FD: E6 80
    LD H,A                                     ; $E4FF: 67
    LD (IY+$13),H                              ; $E500: FD 74 13
    RL B                                       ; $E503: CB 10  y sign difference to bit 7
    LD A,B                                     ; $E505: 78
    XOR D                                      ; $E506: AA
    AND $80                                    ; $E507: E6 80
    LD D,A                                     ; $E509: 57
    LD (IY+$15),D                              ; $E50A: FD 72 15
    CALL AddSignMagnitude                      ; $E50D: CD 24 E4  x term + y term
    LD L,A                                     ; $E510: 6F
    LD E,(IY+$16)                              ; $E511: FD 5E 16  cached z term
    LD D,(IY+$17)                              ; $E514: FD 56 17
    LD A,B                                     ; $E517: 78
    RLA                                        ; $E518: 17  z sign difference to bit 7
    XOR D                                      ; $E519: AA
    AND $80                                    ; $E51A: E6 80
    LD D,A                                     ; $E51C: 57
    LD (IY+$17),D                              ; $E51D: FD 72 17
    CALL AddSignMagnitude                      ; $E520: CD 24 E4  + z term
    LD L,A                                     ; $E523: 6F
    LD DE,$0006                                ; $E524: 11 06 00  next matrix row
    ADD IY,DE                                  ; $E527: FD 19
    RET                                        ; $E529: C9

; VERIFIED: One matrix row times the vector at IX (bytes 0..2 magnitudes, byte 3 bits 7/6/5
; signs): HL = sum of MultiplyUnsignedHigh(|v_i|, |row_i|) with signs (L = magnitude,
; H bit 7 = sign); the three terms are cached at IY+$12..$17.  IY = row, advanced by 6.
; With row entries of about 127 the result is about half the vector component.
; Used for vertices and, through ComputeFaceAxis, for face normals.
RotateRow:
    LD B,(IX+$00)                              ; $E52A: DD 46 00  x magnitude
    LD C,(IY+$01)                              ; $E52D: FD 4E 01  |row x|
    RES 7,C                                    ; $E530: CB B9
    CALL MultiplyUnsignedHigh                  ; $E532: CD 34 E4  L = |x|*|row x|/256
    LD L,A                                     ; $E535: 6F
    LD A,(IX+$03)                              ; $E536: DD 7E 03  term sign = x sign XOR row sign
    XOR (IY+$01)                               ; $E539: FD AE 01
    AND $80                                    ; $E53C: E6 80
    LD H,A                                     ; $E53E: 67
    LD (IY+$12),L                              ; $E53F: FD 75 12  cache term 1
    LD (IY+$13),H                              ; $E542: FD 74 13
    EX DE,HL                                   ; $E545: EB  DE = term 1
    LD B,(IX+$01)                              ; $E546: DD 46 01  y magnitude
    LD C,(IY+$03)                              ; $E549: FD 4E 03  |row y|
    RES 7,C                                    ; $E54C: CB B9
    PUSH DE                                    ; $E54E: D5
    CALL MultiplyUnsignedHigh                  ; $E54F: CD 34 E4
    POP DE                                     ; $E552: D1
    LD L,A                                     ; $E553: 6F
    LD A,(IX+$03)                              ; $E554: DD 7E 03  y sign (bit 6) XOR row sign
    RLA                                        ; $E557: 17
    XOR (IY+$03)                               ; $E558: FD AE 03
    AND $80                                    ; $E55B: E6 80
    LD H,A                                     ; $E55D: 67
    LD (IY+$14),L                              ; $E55E: FD 75 14  cache term 2
    LD (IY+$15),H                              ; $E561: FD 74 15
    CALL AddSignMagnitude                      ; $E564: CD 24 E4  term 1 + term 2
    LD L,A                                     ; $E567: 6F
    EX DE,HL                                   ; $E568: EB
    LD B,(IX+$02)                              ; $E569: DD 46 02  z magnitude
    LD C,(IY+$05)                              ; $E56C: FD 4E 05  |row z|
    RES 7,C                                    ; $E56F: CB B9
    PUSH DE                                    ; $E571: D5
    CALL MultiplyUnsignedHigh                  ; $E572: CD 34 E4
    POP DE                                     ; $E575: D1
    LD L,A                                     ; $E576: 6F
    LD A,(IX+$03)                              ; $E577: DD 7E 03  z sign (bit 5) XOR row sign
    RLA                                        ; $E57A: 17
    RLA                                        ; $E57B: 17
    XOR (IY+$05)                               ; $E57C: FD AE 05
    AND $80                                    ; $E57F: E6 80
    LD H,A                                     ; $E581: 67
    LD (IY+$16),L                              ; $E582: FD 75 16  cache term 3
    LD (IY+$17),H                              ; $E585: FD 74 17
    CALL AddSignMagnitude                      ; $E588: CD 24 E4  + term 3
    LD L,A                                     ; $E58B: 6F
    LD DE,$0006                                ; $E58C: 11 06 00  next matrix row
    ADD IY,DE                                  ; $E58F: FD 19
    RET                                        ; $E591: C9

; VERIFIED: C = 256 * (DE:C) / (HL:A), saturated to 255.  Both 24-bit values are shifted left
; together (at most 8 steps) until the divisor fills HL, then the top 16 dividend bits
; are divided by H (DivideByteFraction).  When the divisor normalises first, a quotient >= 1
; returns 255 and smaller ones are exact or 1..3 too high (divisor truncated to H; less
; accurate when the divisor is still below $8000 after the 8 shifts).
; NOTE: a dividend with more significant bits than the divisor takes the overflow path
; ($E5A4), whose SCF re-inserts a set top bit into the divisor.  About half of these
; inputs still return 255; the others return values below 255 for true ratios >= 1
; (for example 144..249 for ratios 1.2..3.6).
; Clobbers A, B, DE, HL.
; Evidence: tools/check_routines.py (maths group), random cases against a Python model.
DivideRatioByte:
    LD B,$09                                   ; $E592: 06 09  at most 8 normalising shifts
L_E594:
    DEC B                                      ; $E594: 05
    JR Z,L_E5AD                                ; $E595: 28 16  divisor not normalised after 8
    RLA                                        ; $E597: 17  divisor HL:A << 1
    ADC HL,HL                                  ; $E598: ED 6A
    JR C,L_E5A9                                ; $E59A: 38 0D  top bit left HL: normalised
    RL C                                       ; $E59C: CB 11  dividend DE:C << 1
    RL E                                       ; $E59E: CB 13
    RL D                                       ; $E5A0: CB 12
    JR NC,L_E594                               ; $E5A2: 30 F0  no dividend overflow: next step
    RR D                                       ; $E5A4: CB 1A  dividend overflow: undo its shift ...
    RR E                                       ; $E5A6: CB 1B
    SCF                                        ; $E5A8: 37  ... and set the divisor top bit
L_E5A9:
    RR H                                       ; $E5A9: CB 1C  divisor >> 1 with carry in bit 15
    RR L                                       ; $E5AB: CB 1D
L_E5AD:
    LD A,D                                     ; $E5AD: 7A
    LD C,$FF                                   ; $E5AE: 0E FF  255 when not below the divisor
    CP H                                       ; $E5B0: BC
    RET NC                                     ; $E5B1: D0
    LD B,H                                     ; $E5B2: 44  B = divisor high byte
    DEC C                                      ; $E5B3: 0D  C = $FE: 8 quotient bits

; VERIFIED: Restoring division loop: A:E / B with A < B; quotient bits are shifted into C until
; the 0 bit of the initial C leaves it (C = $FE gives 8 bits).  DivideToFractionC enters here with
; E = 0, C = $FE: C = A*256/B (the line slope of DrawLine).
; Evidence: tools/check_routines.py (maths group), exact on all sampled cases.
DivideByteFraction:
    SLA E                                      ; $E5B4: CB 23  next dividend bit into A
    RLA                                        ; $E5B6: 17
    JR C,L_E5C1                                ; $E5B7: 38 08  A overflowed: subtract
    CP B                                       ; $E5B9: B8  A >= B: subtract
    JR NC,L_E5C1                               ; $E5BA: 30 05
    SLA C                                      ; $E5BC: CB 21  quotient bit 0
    RET NC                                     ; $E5BE: D0  sentinel left C: done
    JR DivideByteFraction                      ; $E5BF: 18 F3
L_E5C1:
    SUB B                                      ; $E5C1: 90  subtract the divisor
    SCF                                        ; $E5C2: 37
    RL C                                       ; $E5C3: CB 11  quotient bit 1
    RET NC                                     ; $E5C5: D0
    JR DivideByteFraction                      ; $E5C6: 18 EC

; VERIFIED: Fraction byte of VertexX from the precise path (0 in the normal path).
VertexFractionX:
    defb $00                                                                              ; $E5C8 .

; VERIFIED: Fraction byte of VertexY.
VertexFractionY:
    defb $00                                                                              ; $E5C9 .

; VERIFIED: Fraction byte of VertexZ.
VertexFractionZ:
    defb $00                                                                              ; $E5CA .

; VERIFIED: Transform one visible vertex (IX = vertex record), entered by JP from ProjectVertices
; with the vertex counter and the instance on the stack.  Detail level ObjectViewDepth
; < 4 and a vertex whose largest magnitude is below $80 use the precise path (RotateRowPrecise,
; coordinates scaled up by VertexNormaliseShift), otherwise L_E49C; both continue at
; L_E607.
; NOTE: an all-zero vertex at levels 0..3 would loop forever at $E5E0; none of the 19
; default blueprints has one.
L_E5CB:
    PUSH IY                                    ; $E5CB: FD E5
    LD A,(ObjectViewDepth)                     ; $E5CD: 3A E0 E2
    CP $04                                     ; $E5D0: FE 04  detail levels 0..3: precise path
    JP NC,L_E49C                               ; $E5D2: D2 9C E4
    LD A,(IX+$00)                              ; $E5D5: DD 7E 00  leading zero bits of |x| OR |y| OR |z|
    OR (IX+$01)                                ; $E5D8: DD B6 01
    OR (IX+$02)                                ; $E5DB: DD B6 02
    LD B,$FF                                   ; $E5DE: 06 FF
L_E5E0:
    INC B                                      ; $E5E0: 04
    ADD A,A                                    ; $E5E1: 87  until the top set bit leaves A
    JR NC,L_E5E0                               ; $E5E2: 30 FC
    LD A,B                                     ; $E5E4: 78
    LD (VertexNormaliseShift),A                ; $E5E5: 32 EF E2
    AND A                                      ; $E5E8: A7
    JP Z,L_E49C                                ; $E5E9: CA 9C E4  bit 7 already used: normal path
    CALL RotateRowPrecise                      ; $E5EC: CD 53 E3  VertexX = row 0 . v
    LD (VertexFractionX),A                     ; $E5EF: 32 C8 E5
    LD (VertexX),HL                            ; $E5F2: 22 E3 E2
    CALL RotateRowPrecise                      ; $E5F5: CD 53 E3  VertexY = row 1 . v
    LD (VertexFractionY),A                     ; $E5F8: 32 C9 E5
    LD (VertexY),HL                            ; $E5FB: 22 E5 E2
    CALL RotateRowPrecise                      ; $E5FE: CD 53 E3  VertexZ = row 2 . v
    LD (VertexFractionZ),A                     ; $E601: 32 CA E5
    LD (VertexZ),HL                            ; $E604: 22 E7 E2

; VERIFIED: Translate: VertexX/Y/Z = instance position + 2 * rotated vertex
; (TranslateVertexAxis), then project: front/rear ProjectedX = 256*x/z,
; ProjectedY = 256*y/z; left/right (L_E6AA) ProjectedX = 256*z/x, ProjectedY =
; 256*y/x.  Store the entry in ProjectedVertexBuffer ($FF quadrant when the depth
; sign is behind the view).
L_E607:
    XOR A                                      ; $E607: AF  the next vertex may use the cache
    LD (RowCacheInvalid),A                     ; $E608: 32 F0 E2
    POP IY                                     ; $E60B: FD E1  IY = RotationMatrix again
    POP HL                                     ; $E60D: E1  HL = vertex counter (AF)
    EX (SP),IX                                 ; $E60E: DD E3  IX = instance, vertex pointer saved
    PUSH HL                                    ; $E610: E5
    LD L,(IX+$00)                              ; $E611: DD 6E 00  instance x (16-bit magnitude, sign byte)
    LD H,(IX+$01)                              ; $E614: DD 66 01
    LD B,(IX+$02)                              ; $E617: DD 46 02
    LD DE,(VertexX)                            ; $E61A: ED 5B E3 E2  DE = rotated x
    LD A,(VertexFractionX)                     ; $E61E: 3A C8 E5
    RLA                                        ; $E621: 17  carry = fraction bit 7, consumed by TranslateVertexAxis
    PUSH AF                                    ; $E622: F5
    CALL TranslateVertexAxis                   ; $E623: CD 78 E4  HL = |x + 2*rotated|, A = sign
    LD (VertexX),HL                            ; $E626: 22 E3 E2
    LD (VertexSignX),A                         ; $E629: 32 EC E2
    POP AF                                     ; $E62C: F1  doubled (or borrowed) fraction
    LD (VertexFractionX),A                     ; $E62D: 32 C8 E5
    LD L,(IX+$03)                              ; $E630: DD 6E 03  instance y
    LD H,(IX+$04)                              ; $E633: DD 66 04
    LD B,(IX+$05)                              ; $E636: DD 46 05
    LD DE,(VertexY)                            ; $E639: ED 5B E5 E2
    LD A,(VertexFractionY)                     ; $E63D: 3A C9 E5
    RLA                                        ; $E640: 17
    PUSH AF                                    ; $E641: F5
    CALL TranslateVertexAxis                   ; $E642: CD 78 E4
    LD (VertexY),HL                            ; $E645: 22 E5 E2
    LD (VertexSignY),A                         ; $E648: 32 ED E2
    POP AF                                     ; $E64B: F1
    LD (VertexFractionY),A                     ; $E64C: 32 C9 E5
    LD L,(IX+$06)                              ; $E64F: DD 6E 06  instance z
    LD H,(IX+$07)                              ; $E652: DD 66 07
    LD B,(IX+$08)                              ; $E655: DD 46 08
    LD DE,(VertexZ)                            ; $E658: ED 5B E7 E2
    LD A,(VertexFractionZ)                     ; $E65C: 3A CA E5
    RLA                                        ; $E65F: 17
    PUSH AF                                    ; $E660: F5
    CALL TranslateVertexAxis                   ; $E661: CD 78 E4
    LD (VertexZ),HL                            ; $E664: 22 E7 E2
    LD (VertexSignZ),A                         ; $E667: 32 EE E2
    POP AF                                     ; $E66A: F1
    LD (VertexFractionZ),A                     ; $E66B: 32 CA E5
    LD A,(CurrentScreenId)                     ; $E66E: 3A 41 70  left/right view: depth axis is x
    BIT 1,A                                    ; $E671: CB 4F
    JR NZ,L_E6AA                               ; $E673: 20 35
    LD DE,(VertexX)                            ; $E675: ED 5B E3 E2
    LD A,(VertexFractionX)                     ; $E679: 3A C8 E5
    LD C,A                                     ; $E67C: 4F
    LD A,(VertexFractionZ)                     ; $E67D: 3A CA E5  divisor z: HL from the last TranslateVertexAxis
    CALL DivideRatioByte                       ; $E680: CD 92 E5  ProjectedX = 256*x/z
    LD A,C                                     ; $E683: 79
    LD (ProjectedX),A                          ; $E684: 32 E9 E2
    LD DE,(VertexY)                            ; $E687: ED 5B E5 E2
    LD HL,(VertexZ)                            ; $E68B: 2A E7 E2
    LD A,(VertexFractionY)                     ; $E68E: 3A C9 E5
    LD C,A                                     ; $E691: 4F
    LD A,(VertexFractionZ)                     ; $E692: 3A CA E5
    CALL DivideRatioByte                       ; $E695: CD 92 E5  ProjectedY = 256*y/z
    LD A,C                                     ; $E698: 79
    LD (ProjectedY),A                          ; $E699: 32 EA E2
    LD A,(VertexSignX)                         ; $E69C: 3A EC E2
    RLA                                        ; $E69F: 17
    RL C                                       ; $E6A0: CB 11  C bit 0 = x sign (across)
    LD A,(VertexSignZ)                         ; $E6A2: 3A EE E2
    RLA                                        ; $E6A5: 17
    RL B                                       ; $E6A6: CB 10  B bit 0 = z sign (depth)
    JR L_E6DD                                  ; $E6A8: 18 33
L_E6AA:
    EX DE,HL                                   ; $E6AA: EB  DE = |z| (across)
    LD HL,(VertexX)                            ; $E6AB: 2A E3 E2
    LD A,(VertexFractionZ)                     ; $E6AE: 3A CA E5
    LD C,A                                     ; $E6B1: 4F
    LD A,(VertexFractionX)                     ; $E6B2: 3A C8 E5
    CALL DivideRatioByte                       ; $E6B5: CD 92 E5  ProjectedX = 256*z/x
    LD A,C                                     ; $E6B8: 79
    LD (ProjectedX),A                          ; $E6B9: 32 E9 E2
    LD DE,(VertexY)                            ; $E6BC: ED 5B E5 E2
    LD HL,(VertexX)                            ; $E6C0: 2A E3 E2
    LD A,(VertexFractionY)                     ; $E6C3: 3A C9 E5
    LD C,A                                     ; $E6C6: 4F
    LD A,(VertexFractionX)                     ; $E6C7: 3A C8 E5
    CALL DivideRatioByte                       ; $E6CA: CD 92 E5  ProjectedY = 256*y/x
    LD A,C                                     ; $E6CD: 79
    LD (ProjectedY),A                          ; $E6CE: 32 EA E2
    LD A,(VertexSignX)                         ; $E6D1: 3A EC E2
    RLA                                        ; $E6D4: 17
    RL B                                       ; $E6D5: CB 10  B bit 0 = x sign (depth)
    LD A,(VertexSignZ)                         ; $E6D7: 3A EE E2
    RLA                                        ; $E6DA: 17
    RL C                                       ; $E6DB: CB 11  C bit 0 = z sign (across)
L_E6DD:
    LD A,(VertexSignY)                         ; $E6DD: 3A ED E2
    RLA                                        ; $E6E0: 17
    RL C                                       ; $E6E1: CB 11  C bit 1 = across sign, bit 0 = y sign
    LD A,(CurrentScreenId)                     ; $E6E3: 3A 41 70
    BIT 0,A                                    ; $E6E6: CB 47
    LD A,C                                     ; $E6E8: 79
    JR Z,L_E6ED                                ; $E6E9: 28 02
    XOR $02                                    ; $E6EB: EE 02  rear/right view mirrors the horizontal sign
L_E6ED:
    AND $03                                    ; $E6ED: E6 03  quadrant bits only
    LD (ProjectedQuadrant),A                   ; $E6EF: 32 EB E2
    LD A,(VertexBufferOffset)                  ; $E6F2: 3A E2 E2
    LD HL,ProjectedVertexBuffer                ; $E6F5: 21 22 E2  HL = ProjectedVertexBuffer + VertexBufferOffset
    ADD A,L                                    ; $E6F8: 85
    JR NC,L_E6FC                               ; $E6F9: 30 01
    INC H                                      ; $E6FB: 24
L_E6FC:
    LD L,A                                     ; $E6FC: 6F
    LD A,(ProjectedX)                          ; $E6FD: 3A E9 E2
    LD (HL),A                                  ; $E700: 77  entry +0: ProjectedX
    INC HL                                     ; $E701: 23
    LD A,(ProjectedY)                          ; $E702: 3A EA E2
    LD (HL),A                                  ; $E705: 77  entry +1: ProjectedY
    INC HL                                     ; $E706: 23
    LD A,(CurrentScreenId)                     ; $E707: 3A 41 70
    LD C,A                                     ; $E70A: 4F
    RRA                                        ; $E70B: 1F  carry = view bits 0 XOR 1 XOR depth sign
    XOR C                                      ; $E70C: A9
    XOR B                                      ; $E70D: A8
    RRA                                        ; $E70E: 1F
    LD A,(ProjectedQuadrant)                   ; $E70F: 3A EB E2
    JR NC,L_E716                               ; $E712: 30 02
    LD A,$FF                                   ; $E714: 3E FF  $FF: vertex behind the view
L_E716:
    LD (HL),A                                  ; $E716: 77  entry +2: quadrant or $FF
    POP AF                                     ; $E717: F1
    EX (SP),IX                                 ; $E718: DD E3  IX = vertex record, instance saved

; VERIFIED: Next vertex record (6 bytes).  INC DE has no effect on the result.
L_E71A:
    LD BC,$0006                                ; $E71A: 01 06 00  vertex records are 6 bytes
    ADD IX,BC                                  ; $E71D: DD 09
    INC DE                                     ; $E71F: 13  unused
    DEC A                                      ; $E720: 3D
    JP NZ,L_E306                               ; $E721: C2 06 E3
    POP IX                                     ; $E724: DD E1  IX = instance
    POP IY                                     ; $E726: FD E1
    RET                                        ; $E728: C9

; VERIFIED: Draw every edge of the blueprint at IY whose visibility threshold allows the
; detail level (ObjectViewDepth), one of whose two faces is visible and whose two
; vertices are in front of the view.  Calls DrawLine with DE = vertex 1 (D across,
; E down), HL = vertex 2, C = quadrant bits (bits 3..2 vertex 1, bits 1..0 vertex 2).
; IX preserved.  Evidence: code; runtime flight scenarios.
DrawVisibleEdges:
    LD E,(IY+$0E)                              ; $E729: FD 5E 0E  blueprint +$0E/$0F: edge table offset
    LD D,(IY+$0F)                              ; $E72C: FD 56 0F
    LD B,(IY+$04)                              ; $E72F: FD 46 04  blueprint +4: edge count
    PUSH IY                                    ; $E732: FD E5
    EX (SP),IX                                 ; $E734: DD E3  IX = blueprint, instance saved
    ADD IX,DE                                  ; $E736: DD 19  IX = first edge record
L_E738:
    PUSH BC                                    ; $E738: C5
    LD A,(IX+$00)                              ; $E739: DD 7E 00  edge visibility threshold
    CP $1F                                     ; $E73C: FE 1F  $1F: drawn at any distance
    JR Z,L_E747                                ; $E73E: 28 07
    LD C,A                                     ; $E740: 4F
    LD A,(ObjectViewDepth)                     ; $E741: 3A E0 E2
    CP C                                       ; $E744: B9
    JR NC,L_E76D                               ; $E745: 30 26  detail level >= threshold: skip
L_E747:
    LD A,(IX+$03)                              ; $E747: DD 7E 03  face nibbles of the edge
    CALL TestFacePairVisible                   ; $E74A: CD 38 E3
    JR Z,L_E76D                                ; $E74D: 28 1E  both faces hidden: skip
    LD A,(IX+$01)                              ; $E74F: DD 7E 01  vertex 1
    CALL GetProjectedVertex                    ; $E752: CD 78 E7
    JR NZ,L_E76D                               ; $E755: 20 16  behind the view: skip
    LD C,A                                     ; $E757: 4F  C = vertex 1 quadrant
    PUSH DE                                    ; $E758: D5
    LD A,(IX+$02)                              ; $E759: DD 7E 02  vertex 2
    CALL GetProjectedVertex                    ; $E75C: CD 78 E7
    EX DE,HL                                   ; $E75F: EB  HL = vertex 2, DE = vertex 1
    POP DE                                     ; $E760: D1
    JR NZ,L_E76D                               ; $E761: 20 0A  behind the view: skip
    RRCA                                       ; $E763: 0F  C = quadrants: vertex 1 bits 3..2, vertex 2 bits 1..0
    RRA                                        ; $E764: 1F
    RL C                                       ; $E765: CB 11
    RLA                                        ; $E767: 17
    RL C                                       ; $E768: CB 11
    CALL DrawLine                              ; $E76A: CD 10 EE  from vertex 1 to vertex 2
L_E76D:
    POP BC                                     ; $E76D: C1  B = edges left
    LD DE,$0004                                ; $E76E: 11 04 00  edge records are 4 bytes
    ADD IX,DE                                  ; $E771: DD 19
    DJNZ L_E738                                ; $E773: 10 C3
    POP IX                                     ; $E775: DD E1  IX = instance
    RET                                        ; $E777: C9

; VERIFIED: A = vertex index.  HL = ProjectedVertexBuffer + 3*A (+2 on return), D = ProjectedX,
; E = ProjectedY, A = quadrant byte; NZ when bit 7 is set ($FF: behind the view).
; B = index.
GetProjectedVertex:
    LD B,A                                     ; $E778: 47
    ADD A,A                                    ; $E779: 87  HL = buffer + 3*index
    LD HL,ProjectedVertexBuffer                ; $E77A: 21 22 E2
    JR NC,L_E780                               ; $E77D: 30 01
    INC H                                      ; $E77F: 24
L_E780:
    ADD A,B                                    ; $E780: 80
    JR NC,L_E784                               ; $E781: 30 01
    INC H                                      ; $E783: 24
L_E784:
    ADD A,L                                    ; $E784: 85
    LD L,A                                     ; $E785: 6F
    JR NC,L_E789                               ; $E786: 30 01
    INC H                                      ; $E788: 24
L_E789:
    LD D,(HL)                                  ; $E789: 56  D = ProjectedX
    INC HL                                     ; $E78A: 23
    LD E,(HL)                                  ; $E78B: 5E  E = ProjectedY
    INC HL                                     ; $E78C: 23
    LD A,(HL)                                  ; $E78D: 7E  A = quadrant byte
    BIT 7,A                                    ; $E78E: CB 7F  NZ: $FF, behind the view
    RET                                        ; $E790: C9

; VERIFIED: IX = instance.  Remove from orientation vector Y (+$10/+$12/+$14) its component
; along vector Z (+$0A/+$0C/+$0E): ComputeNegatedDotProduct gives k = -(Z.Y)/128 (sign-magnitude),
; then Y_i += k*Z_i/128 for each axis (L_E7B2).  Only the high bytes change.
; IX, IY preserved (the per-axis helper advances copies of them).
; Evidence: a simulator check in tools/check_routines.py: |cos(Z,Y)| up to 0.5 before,
; at most 0.029 after (3000 cases).
OrthogonaliseYVector:
    PUSH IX                                    ; $E791: DD E5
    PUSH IX                                    ; $E793: DD E5
    EX (SP),IY                                 ; $E795: FD E3  IY = instance, caller's IY saved
    LD DE,$0009                                ; $E797: 11 09 00  IX+1 = vector Z (+$0A)
    ADD IX,DE                                  ; $E79A: DD 19
    LD E,$0F                                   ; $E79C: 1E 0F  IY+1 = vector Y (+$10)
    ADD IY,DE                                  ; $E79E: FD 19
    CALL ComputeNegatedDotProduct              ; $E7A0: CD 1F FB  A = -(Z.Y)/128, sign-magnitude
    LD E,A                                     ; $E7A3: 5F  E = k
    CALL L_E7B2                                ; $E7A4: CD B2 E7  Y.x += k*Z.x/128
    CALL L_E7B2                                ; $E7A7: CD B2 E7  Y.y += k*Z.y/128
    CALL L_E7B2                                ; $E7AA: CD B2 E7  Y.z += k*Z.z/128
    POP IY                                     ; $E7AD: FD E1
    POP IX                                     ; $E7AF: DD E1
    RET                                        ; $E7B1: C9

; VERIFIED: One axis of OrthogonaliseYVector: (IY+1) += E*(IX+1)/128 in sign-magnitude,
; saturating at 127; IX and IY advance by 2.
L_E7B2:
    LD C,(IX+$01)                              ; $E7B2: DD 4E 01  C = Z component
    LD B,E                                     ; $E7B5: 43
    SLA B                                      ; $E7B6: CB 20  B = 2|k|
    SLA C                                      ; $E7B8: CB 21  C = 2|Z component|
    CALL MultiplyUnsignedHigh                  ; $E7BA: CD 34 E4  A = |k*Z|/64
    LD C,A                                     ; $E7BD: 4F
    LD A,E                                     ; $E7BE: 7B
    XOR (IX+$01)                               ; $E7BF: DD AE 01  sign of k*Z
    RLA                                        ; $E7C2: 17
    RR C                                       ; $E7C3: CB 19  C = k*Z/128, sign-magnitude
    LD B,(IY+$01)                              ; $E7C5: FD 46 01  B = Y component
    LD A,B                                     ; $E7C8: 78
    XOR C                                      ; $E7C9: A9  A bit 7 = signs differ
    SLA C                                      ; $E7CA: CB 21  C = 2|term|, H bit 0 = term sign
    RL H                                       ; $E7CC: CB 14
    SLA B                                      ; $E7CE: CB 20  B = 2|Y|, H bit 0 = Y sign
    RL H                                       ; $E7D0: CB 14
    RLA                                        ; $E7D2: 17  carry = signs differ
    LD A,B                                     ; $E7D3: 78
    JR C,L_E7DD                                ; $E7D4: 38 07
    ADD A,C                                    ; $E7D6: 81  same signs: 2|Y| + 2|term| ...
    JR NC,L_E7E4                               ; $E7D7: 30 0B
    LD A,$FF                                   ; $E7D9: 3E FF  ... saturating
    JR L_E7E4                                  ; $E7DB: 18 07
L_E7DD:
    SUB C                                      ; $E7DD: 91  different: 2|Y| - 2|term|
    JR NC,L_E7E4                               ; $E7DE: 30 04
    NEG                                        ; $E7E0: ED 44  term larger: negate, term sign
    RR H                                       ; $E7E2: CB 1C
L_E7E4:
    RR H                                       ; $E7E4: CB 1C  carry = result sign
    RRA                                        ; $E7E6: 1F  halve and attach the sign
    LD (IY+$01),A                              ; $E7E7: FD 77 01  new Y component (high byte)
    INC IX                                     ; $E7EA: DD 23
    INC IX                                     ; $E7EC: DD 23
    INC IY                                     ; $E7EE: FD 23
    INC IY                                     ; $E7F0: FD 23
    RET                                        ; $E7F2: C9

; VERIFIED: IX = instance.  Compute orientation vector X = Y x Z / 128 (high bytes +$16, +$18,
; +$1A, via ComputeCrossProductTerm) and fill RotationMatrix rows with (X_r, Y_r, Z_r): only those
; three entries are products; the other six are copies of Y and Z.
; Clobbers IY (= RotationMatrix), AF, BC, DE, HL.
; Evidence: pipeline check: X within 1 unit of the float cross product.
BuildRotationMatrix:
    LD IY,RotationMatrix                       ; $E7F3: FD 21 BC E2  rows of 6 bytes; odd bytes used
    LD B,(IX+$0C)                              ; $E7F7: DD 46 0C  Z.y and Y.z
    LD C,(IX+$14)                              ; $E7FA: DD 4E 14
    LD D,(IX+$0E)                              ; $E7FD: DD 56 0E  Z.z and Y.y
    LD E,(IX+$12)                              ; $E800: DD 5E 12
    CALL ComputeCrossProductTerm               ; $E803: CD 49 E8
    LD (IX+$16),H                              ; $E806: DD 74 16  X.x = Y.y*Z.z - Y.z*Z.y (scaled)
    LD (IY+$01),H                              ; $E809: FD 74 01  row 0 entry 1: X.x
    LD B,(IX+$0E)                              ; $E80C: DD 46 0E
    LD (IY+$11),B                              ; $E80F: FD 70 11  row 2 entry 3: Z.z
    LD C,(IX+$10)                              ; $E812: DD 4E 10
    LD (IY+$03),C                              ; $E815: FD 71 03  row 0 entry 2: Y.x
    LD D,(IX+$0A)                              ; $E818: DD 56 0A
    LD E,(IX+$14)                              ; $E81B: DD 5E 14
    LD (IY+$0F),E                              ; $E81E: FD 73 0F  row 2 entry 2: Y.z
    CALL ComputeCrossProductTerm               ; $E821: CD 49 E8
    LD (IX+$18),H                              ; $E824: DD 74 18  X.y
    LD (IY+$07),H                              ; $E827: FD 74 07  row 1 entry 1: X.y
    LD B,(IX+$0A)                              ; $E82A: DD 46 0A
    LD (IY+$05),B                              ; $E82D: FD 70 05  row 0 entry 3: Z.x
    LD C,(IX+$12)                              ; $E830: DD 4E 12
    LD (IY+$09),C                              ; $E833: FD 71 09  row 1 entry 2: Y.y
    LD D,(IX+$0C)                              ; $E836: DD 56 0C
    LD (IY+$0B),D                              ; $E839: FD 72 0B  row 1 entry 3: Z.y
    LD E,(IX+$10)                              ; $E83C: DD 5E 10
    CALL ComputeCrossProductTerm               ; $E83F: CD 49 E8
    LD (IX+$1A),H                              ; $E842: DD 74 1A  X.z
    LD (IY+$0D),H                              ; $E845: FD 74 0D  row 2 entry 1: X.z
    RET                                        ; $E848: C9

; VERIFIED: B, C, D, E = sign-magnitude bytes.  HL = D*E - B*C as 16-bit sign-magnitude, where
; the magnitudes are 2|a|*2|b| (MultiplyUnsigned) halved: |HL| = 2*|D*E - B*C|,
; saturating at $7FFF.  H is the sign-magnitude high byte used by BuildRotationMatrix.
; Evidence: tools/check_routines.py (maths group).
ComputeCrossProductTerm:
    SLA B                                      ; $E849: CB 20  B = 2|b|; sign of b ...
    RRA                                        ; $E84B: 1F
    XOR C                                      ; $E84C: A9  ... XOR sign of c
    SLA C                                      ; $E84D: CB 21
    AND $80                                    ; $E84F: E6 80
    LD H,A                                     ; $E851: 67  H bit 7 = sign of B*C
    SLA D                                      ; $E852: CB 22
    RRA                                        ; $E854: 1F
    XOR E                                      ; $E855: AB
    SLA E                                      ; $E856: CB 23
    AND $80                                    ; $E858: E6 80  A bit 7 = sign of D*E
    XOR H                                      ; $E85A: AC  A bit 7 = signs differ
    SLA H                                      ; $E85B: CB 24
    RRA                                        ; $E85D: 1F
    XOR $80                                    ; $E85E: EE 80  bit 7 = sign of -B*C, bit 6 = differ
    PUSH AF                                    ; $E860: F5
    PUSH DE                                    ; $E861: D5
    CALL MultiplyUnsigned                      ; $E862: CD 5D E4  HL = 2|b| * 2|c|
    POP BC                                     ; $E865: C1
    PUSH HL                                    ; $E866: E5
    CALL MultiplyUnsigned                      ; $E867: CD 5D E4  HL = 2|d| * 2|e|
    POP DE                                     ; $E86A: D1
    POP AF                                     ; $E86B: F1
    BIT 6,A                                    ; $E86C: CB 77  signs differ: add magnitudes
    JR Z,L_E878                                ; $E86E: 28 08
    ADD HL,DE                                  ; $E870: 19
    JR NC,L_E885                               ; $E871: 30 12
    LD HL,$FFFF                                ; $E873: 21 FF FF  saturate
    JR L_E885                                  ; $E876: 18 0D
L_E878:
    EX DE,HL                                   ; $E878: EB  |B*C| - |D*E| with -B*C's sign
    AND A                                      ; $E879: A7
    SBC HL,DE                                  ; $E87A: ED 52
    JR NC,L_E885                               ; $E87C: 30 07
    ADD HL,DE                                  ; $E87E: 19  D*E larger: other order ...
    EX DE,HL                                   ; $E87F: EB
    AND A                                      ; $E880: A7
    SBC HL,DE                                  ; $E881: ED 52
    XOR $80                                    ; $E883: EE 80  ... with D*E's sign
L_E885:
    RLA                                        ; $E885: 17  halve; sign into bit 15
    RR H                                       ; $E886: CB 1C
    RR L                                       ; $E888: CB 1D
    RET                                        ; $E88A: C9

; VERIFIED: Unreferenced (no static, pointer or runtime reference) but complete routine:
; HL = high word of (A:C) * (D:E) built from four MultiplyUnsigned partial products
; (the low word accumulates in IX, which is restored).  Inherits the quarter-square
; error, so HL can be lower than the exact high word.
; Evidence: tools/check_routines.py (maths group) matches the partial-product model exactly.
; stationslotfix=yes replaces these 68 bytes with StationSlotAlign.
UnusedMultiplyWordHigh:
assert $-GameImage = StationSlotAlignStart-GameLoadAddress
IF STATION_SLOT_FIX
    StationSlotAlignCode
ELSE
    PUSH IX                                    ; $E88B: DD E5
    LD IX,$0000                                ; $E88D: DD 21 00 00  IX accumulates the low word
    LD B,A                                     ; $E891: 47
    PUSH BC                                    ; $E892: C5
    PUSH DE                                    ; $E893: D5
    PUSH BC                                    ; $E894: C5
    PUSH DE                                    ; $E895: D5
    PUSH BC                                    ; $E896: C5
    PUSH DE                                    ; $E897: D5
    LD B,E                                     ; $E898: 43
    CALL MultiplyUnsigned                      ; $E899: CD 5D E4  C*E
    EX DE,HL                                   ; $E89C: EB
    ADD IX,DE                                  ; $E89D: DD 19
    POP DE                                     ; $E89F: D1
    POP BC                                     ; $E8A0: C1
    LD B,D                                     ; $E8A1: 42
    CALL MultiplyUnsigned                      ; $E8A2: CD 5D E4  C*D
    LD E,$00                                   ; $E8A5: 1E 00
    LD D,L                                     ; $E8A7: 55
    ADD IX,DE                                  ; $E8A8: DD 19
    LD L,H                                     ; $E8AA: 6C
    LD H,E                                     ; $E8AB: 63
    JR NC,L_E8AF                               ; $E8AC: 30 01
    INC HL                                     ; $E8AE: 23
L_E8AF:
    POP BC                                     ; $E8AF: C1
    POP DE                                     ; $E8B0: D1
    PUSH HL                                    ; $E8B1: E5
    LD B,D                                     ; $E8B2: 42
    CALL MultiplyUnsigned                      ; $E8B3: CD 5D E4  A*E
    LD E,$00                                   ; $E8B6: 1E 00
    LD D,L                                     ; $E8B8: 55
    ADD IX,DE                                  ; $E8B9: DD 19
    POP DE                                     ; $E8BB: D1
    LD L,H                                     ; $E8BC: 6C
    LD H,$00                                   ; $E8BD: 26 00
    JR NC,L_E8C2                               ; $E8BF: 30 01
    INC HL                                     ; $E8C1: 23
L_E8C2:
    ADD HL,DE                                  ; $E8C2: 19
    POP BC                                     ; $E8C3: C1
    POP DE                                     ; $E8C4: D1
    LD C,D                                     ; $E8C5: 4A
    PUSH HL                                    ; $E8C6: E5
    CALL MultiplyUnsigned                      ; $E8C7: CD 5D E4  A*D
    POP DE                                     ; $E8CA: D1
    ADD HL,DE                                  ; $E8CB: 19
    POP IX                                     ; $E8CC: DD E1
    RET                                        ; $E8CE: C9
ENDIF
assert $-GameImage = StationSlotAlignLimit-GameLoadAddress

; ============================================================================
; Arithmetic helpers
; Division, sign-magnitude averaging and face-normal dot products.
; ============================================================================

; VERIFIED: BC = (HL*65536 + A*256) / DE, HL = remainder; requires HL < DE (otherwise the
; quotient overflows and is wrong).  16 restoring-division steps; the sentinel 0 bit in
; BC = $FFFE ends the loop.  Clobbers A, F.
; Evidence: tools/check_routines.py (maths group): exact except on the overflow cases.
DivideWordFraction:
    LD BC,$FFFE                                ; $E8CF: 01 FE FF  sentinel 0 bit: 16 quotient bits
L_E8D2:
    ADD A,A                                    ; $E8D2: 87  HL:A << 1
    RL L                                       ; $E8D3: CB 15
    RL H                                       ; $E8D5: CB 14
    JR C,L_E8E5                                ; $E8D7: 38 0C  bit out of HL: subtract anyway
    SBC HL,DE                                  ; $E8D9: ED 52  remainder - divisor
    JR NC,L_E8E8                               ; $E8DB: 30 0B  fits: quotient bit 1
    ADD HL,DE                                  ; $E8DD: 19  restore: quotient bit 0
    SLA C                                      ; $E8DE: CB 21
    RL B                                       ; $E8E0: CB 10
    RET NC                                     ; $E8E2: D0  sentinel left B: done
    JR L_E8D2                                  ; $E8E3: 18 ED
L_E8E5:
    AND A                                      ; $E8E5: A7
    SBC HL,DE                                  ; $E8E6: ED 52
L_E8E8:
    SCF                                        ; $E8E8: 37  quotient bit 1
    RL C                                       ; $E8E9: CB 11
    RL B                                       ; $E8EB: CB 10
    RET NC                                     ; $E8ED: D0
    JR L_E8D2                                  ; $E8EE: 18 E2

; VERIFIED: HL = (HL - DE) / 2 for 16-bit sign-magnitude values (bit 15 sign): negates DE's sign
; and continues in HalveSumSignMagnitude.
; Callers form half the per-axis difference of two positions
; (HalveCoordinateDifference: sun minus station; L_F9B2: missile target minus missile); bit 15 of the
; result is set when the first position is the smaller one.
HalveDifferenceSignMagnitude:
    LD A,D                                     ; $E8F0: 7A
    XOR $80                                    ; $E8F1: EE 80  negate DE's sign
    LD D,A                                     ; $E8F3: 57

; VERIFIED: HL = (HL + DE) / 2 for 16-bit sign-magnitude values (bit 15 sign); the result takes
; the sign of the larger magnitude (HL's on a tie), B bit 7 = that sign, carry = the
; dropped bit.  Evidence: tools/check_routines.py (maths group), both entries.
HalveSumSignMagnitude:
    LD A,H                                     ; $E8F4: 7C
    XOR D                                      ; $E8F5: AA  signs differ?
    LD B,H                                     ; $E8F6: 44  B, C = original sign bytes
    LD C,D                                     ; $E8F7: 4A
    RES 7,H                                    ; $E8F8: CB BC  magnitudes only
    RES 7,D                                    ; $E8FA: CB BA
    AND $80                                    ; $E8FC: E6 80
    JR NZ,L_E903                               ; $E8FE: 20 03
    ADD HL,DE                                  ; $E900: 19  same signs: add
    JR L_E90D                                  ; $E901: 18 0A
L_E903:
    SBC HL,DE                                  ; $E903: ED 52  different: |HL| - |DE|
    JR NC,L_E90D                               ; $E905: 30 06  HL larger: its sign
    ADD HL,DE                                  ; $E907: 19  DE larger: |DE| - |HL| ...
    EX DE,HL                                   ; $E908: EB
    AND A                                      ; $E909: A7
    SBC HL,DE                                  ; $E90A: ED 52
    LD B,C                                     ; $E90C: 41  ... with DE's sign
L_E90D:
    SRL H                                      ; $E90D: CB 3C  halve, carry = dropped bit
    RR L                                       ; $E90F: CB 1D
    BIT 7,B                                    ; $E911: CB 78  attach the sign
    RET Z                                      ; $E913: C8
    SET 7,H                                    ; $E914: CB FC
    RET                                        ; $E916: C9

; VERIFIED: Instance pointer saved by ComputeFaceVisibility; ComputeFaceAxis walks it
; through x, y, z.
FaceInstancePointer:
    defw $0000                                                                            ; $E917

; VERIFIED: Blueprint +$13 copied by ComputeFaceVisibility: face normals are scaled by 2/2^n
; before being added to the object position (ComputeFaceAxis).
NormalScaleShift:
    defb $00                                                                              ; $E919 .

; VERIFIED: (object x + 2*normal x / 2^NormalScaleShift) / 2, 16-bit sign-magnitude; read by
; ComputeFaceDotProduct through IY.
FacePointX:
    defw $0000                                                                            ; $E91A

; VERIFIED: Same for y.
FacePointY:
    defw $0000                                                                            ; $E91C

; VERIFIED: Same for z.
FacePointZ:
    defw $0000                                                                            ; $E91E

; VERIFIED: Rotated face normal x (sign-magnitude byte from RotateRow); read by
; ComputeFaceDotProduct through IX.
FaceNormalX:
    defb $00                                                                              ; $E920 .

; VERIFIED: Rotated face normal y.
FaceNormalY:
    defb $00                                                                              ; $E921 .

; VERIFIED: Rotated face normal z.
FaceNormalZ:
    defb $00                                                                              ; $E922 .

; VERIFIED: IX = instance, IY = blueprint, RotationMatrix and the detail level ready.  For each
; face: hidden (0) when its threshold excludes the detail level, otherwise rotate the
; normal, form FacePoint = (position + scaled normal)/2 and set the flag to 1 when
; the dot product with the rotated normal is negative (facing the viewer).
; Output: FaceVisibilityFlags; RowProductCache is overwritten by the normal rotations.
; IX, IY restored.
; Evidence: pipeline check: 1341 of 1353 faces match the float model; the others
; have small rotated normals where the 8-bit truncations decide; runtime flight.
ComputeFaceVisibility:
    PUSH IX                                    ; $E923: DD E5
    PUSH IY                                    ; $E925: FD E5
    PUSH IY                                    ; $E927: FD E5
    EX (SP),IX                                 ; $E929: DD E3  IX = blueprint, instance on the stack
    POP HL                                     ; $E92B: E1  HL = instance
    LD (FaceInstancePointer),HL                ; $E92C: 22 17 E9  FaceInstancePointer = instance
    LD D,(IX+$11)                              ; $E92F: DD 56 11  blueprint +$10/$11: face table offset
    LD E,(IX+$10)                              ; $E932: DD 5E 10
    ADD IX,DE                                  ; $E935: DD 19  IX = first face record
    LD DE,FaceVisibilityFlags                  ; $E937: 11 AC E2  DE = first output flag
    LD A,(IY+$13)                              ; $E93A: FD 7E 13  blueprint +$13: normal scale shift
    LD (NormalScaleShift),A                    ; $E93D: 32 19 E9
    LD A,(IY+$05)                              ; $E940: FD 7E 05  blueprint +5: face count
    AND A                                      ; $E943: A7
    LD IY,RotationMatrix                       ; $E944: FD 21 BC E2  IY = matrix row 0
    JR NZ,L_E94E                               ; $E948: 20 04
    INC A                                      ; $E94A: 3C  no faces: face 0 visible
    LD (DE),A                                  ; $E94B: 12
    JR L_E9A9                                  ; $E94C: 18 5B
L_E94E:
    PUSH AF                                    ; $E94E: F5  faces left
    PUSH DE                                    ; $E94F: D5
    LD A,(IX+$03)                              ; $E950: DD 7E 03  face visibility threshold
    AND $1F                                    ; $E953: E6 1F
    CP $1F                                     ; $E955: FE 1F  $1F: any distance
    JR Z,L_E964                                ; $E957: 28 0B
    LD B,A                                     ; $E959: 47
    LD A,(ObjectViewDepth)                     ; $E95A: 3A E0 E2
    CP B                                       ; $E95D: B8
    JR C,L_E964                                ; $E95E: 38 04  detail level below threshold: test it
    POP DE                                     ; $E960: D1
    XOR A                                      ; $E961: AF  hidden at this detail level
    JR L_E99E                                  ; $E962: 18 3A
L_E964:
    PUSH IY                                    ; $E964: FD E5
    LD HL,(FaceInstancePointer)                ; $E966: 2A 17 E9  instance pointer for ComputeFaceAxis
    PUSH HL                                    ; $E969: E5
    CALL ComputeFaceAxis                       ; $E96A: CD 03 EA  rotated normal x, face point x
    LD (FaceNormalX),A                         ; $E96D: 32 20 E9
    LD (FacePointX),HL                         ; $E970: 22 1A E9
    CALL ComputeFaceAxis                       ; $E973: CD 03 EA  y
    LD (FaceNormalY),A                         ; $E976: 32 21 E9
    LD (FacePointY),HL                         ; $E979: 22 1C E9
    CALL ComputeFaceAxis                       ; $E97C: CD 03 EA  z
    LD (FaceNormalZ),A                         ; $E97F: 32 22 E9
    LD (FacePointZ),HL                         ; $E982: 22 1E E9
    POP HL                                     ; $E985: E1  drop the advanced pointer
    PUSH IX                                    ; $E986: DD E5
    LD IY,FacePointX                           ; $E988: FD 21 1A E9
    LD IX,FaceNormalX                          ; $E98C: DD 21 20 E9
    CALL ComputeFaceDotProduct                 ; $E990: CD AE E9  HL = (normal . point) / 256
    POP IX                                     ; $E993: DD E1
    POP IY                                     ; $E995: FD E1
    POP DE                                     ; $E997: D1
    XOR A                                      ; $E998: AF
    SLA H                                      ; $E999: CB 24  negative dot product: visible
    JR NC,L_E99E                               ; $E99B: 30 01
    INC A                                      ; $E99D: 3C
L_E99E:
    LD (DE),A                                  ; $E99E: 12  store this face's flag
    INC DE                                     ; $E99F: 13
    LD BC,$0004                                ; $E9A0: 01 04 00  face records are 4 bytes
    ADD IX,BC                                  ; $E9A3: DD 09
    POP AF                                     ; $E9A5: F1
    DEC A                                      ; $E9A6: 3D
    JR NZ,L_E94E                               ; $E9A7: 20 A5
L_E9A9:
    POP IY                                     ; $E9A9: FD E1
    POP IX                                     ; $E9AB: DD E1
    RET                                        ; $E9AD: C9

; VERIFIED: IX = 3 sign-magnitude bytes (normal), IY = 3 sign-magnitude words (point):
; HL = (n_x*p_x + n_y*p_y + n_z*p_z) / 128 / 2 in 16-bit sign-magnitude, via
; MultiplyNormalByCoordinate and HalveSumSignMagnitude (the y+z partial sum is
; doubled back, so only the final sum is halved).  ComputeFaceVisibility uses only
; the sign.
ComputeFaceDotProduct:
    LD E,(IY+$01)                              ; $E9AE: FD 5E 01  E:C = point x
    LD C,(IY+$00)                              ; $E9B1: FD 4E 00
    LD A,(IX+$00)                              ; $E9B4: DD 7E 00  A = normal x
    CALL MultiplyNormalByCoordinate            ; $E9B7: CD E4 E9  HL = n_x*p_x/128
    PUSH HL                                    ; $E9BA: E5
    LD E,(IY+$03)                              ; $E9BB: FD 5E 03
    LD C,(IY+$02)                              ; $E9BE: FD 4E 02
    LD A,(IX+$01)                              ; $E9C1: DD 7E 01
    CALL MultiplyNormalByCoordinate            ; $E9C4: CD E4 E9  n_y*p_y/128
    PUSH HL                                    ; $E9C7: E5
    LD E,(IY+$05)                              ; $E9C8: FD 5E 05
    LD C,(IY+$04)                              ; $E9CB: FD 4E 04
    LD A,(IX+$02)                              ; $E9CE: DD 7E 02
    CALL MultiplyNormalByCoordinate            ; $E9D1: CD E4 E9  n_z*p_z/128
    POP DE                                     ; $E9D4: D1
    CALL HalveSumSignMagnitude                 ; $E9D5: CD F4 E8  HL = (z + y)/2, carry = dropped bit
    ADC HL,HL                                  ; $E9D8: ED 6A  undo the halving ...
    BIT 7,B                                    ; $E9DA: CB 78  ... and restore the sign
    JR Z,L_E9E0                                ; $E9DC: 28 02
    SET 7,H                                    ; $E9DE: CB FC
L_E9E0:
    POP DE                                     ; $E9E0: D1  DE = x product
    JP HalveSumSignMagnitude                   ; $E9E1: C3 F4 E8  HL = (x + y + z)/2

; VERIFIED: A = sign-magnitude byte n, E:C = sign-magnitude word p.  HL ~ |n|*|p|/128 (2|n|
; times p_hi plus the high byte of 2|n| times p_lo; quarter-square rounding can make
; it up to 128 lower) with bit 15 = sign(n) XOR sign(p), bit 15 of the product lost.
; Evidence: tools/check_routines.py (maths group) matches this model exactly.
MultiplyNormalByCoordinate:
    LD B,A                                     ; $E9E4: 47
    SLA B                                      ; $E9E5: CB 20  B = 2|n|
    AND $80                                    ; $E9E7: E6 80
    XOR E                                      ; $E9E9: AB  E bit 7 = product sign
    LD E,A                                     ; $E9EA: 5F
    CALL MultiplyUnsignedHigh                  ; $E9EB: CD 34 E4  A = 2|n| * p_lo / 256
    LD D,E                                     ; $E9EE: 53
    LD E,A                                     ; $E9EF: 5F
    LD C,D                                     ; $E9F0: 4A  C = |p_hi|
    RES 7,C                                    ; $E9F1: CB B9
    PUSH DE                                    ; $E9F3: D5
    CALL MultiplyUnsigned                      ; $E9F4: CD 5D E4  HL = 2|n| * |p_hi|
    POP DE                                     ; $E9F7: D1
    LD A,D                                     ; $E9F8: 7A
    LD D,$00                                   ; $E9F9: 16 00
    ADD HL,DE                                  ; $E9FB: 19  + the low partial
    ADD HL,HL                                  ; $E9FC: 29  drop bit 15 ...
    RLA                                        ; $E9FD: 17  ... carry = product sign ...
    RR H                                       ; $E9FE: CB 1C  ... into bit 15
    RR L                                       ; $EA00: CB 1D
    RET                                        ; $EA02: C9

; VERIFIED: One axis of a face: rotate the normal by the current matrix row (RotateRow, IY += 6),
; read the next instance coordinate through the pointer below the return address
; (advanced by 3), and return A = rotated normal component and HL = (coordinate +
; 2*normal/2^NormalScaleShift)/2, both sign-magnitude.
ComputeFaceAxis:
    CALL RotateRow                             ; $EA03: CD 2A E5  L = |rotated normal|, H = sign
    POP BC                                     ; $EA06: C1  return address; the instance pointer is below it
    EX (SP),IX                                 ; $EA07: DD E3
    LD E,(IX+$00)                              ; $EA09: DD 5E 00  DE = |coordinate|
    LD D,(IX+$01)                              ; $EA0C: DD 56 01
    LD A,(IX+$02)                              ; $EA0F: DD 7E 02  A = its sign byte
    INC IX                                     ; $EA12: DD 23  pointer to the next coordinate
    INC IX                                     ; $EA14: DD 23
    INC IX                                     ; $EA16: DD 23
    EX (SP),IX                                 ; $EA18: DD E3
    PUSH BC                                    ; $EA1A: C5
    LD C,A                                     ; $EA1B: 4F  C = coordinate sign
    LD A,(NormalScaleShift)                    ; $EA1C: 3A 19 E9  NormalScaleShift
    SLA L                                      ; $EA1F: CB 25  L = 2|normal|
    PUSH HL                                    ; $EA21: E5  kept for the return value
    LD B,A                                     ; $EA22: 47
    INC B                                      ; $EA23: 04
L_EA24:
    SRL L                                      ; $EA24: CB 3D  L >>= shift + 1 ...
    DJNZ L_EA24                                ; $EA26: 10 FC
    RL L                                       ; $EA28: CB 15  ... << 1: 2|n| / 2^shift
    LD A,C                                     ; $EA2A: 79
    XOR H                                      ; $EA2B: AC  signs differ?
    SLA H                                      ; $EA2C: CB 24
    RLA                                        ; $EA2E: 17
    JR C,L_EA34                                ; $EA2F: 38 03
    ADD HL,DE                                  ; $EA31: 19  same signs: add magnitudes
    JR L_EA43                                  ; $EA32: 18 0F
L_EA34:
    EX DE,HL                                   ; $EA34: EB  different: |coordinate| - |n|
    AND A                                      ; $EA35: A7
    SBC HL,DE                                  ; $EA36: ED 52
    JR NC,L_EA43                               ; $EA38: 30 09
    ADD HL,DE                                  ; $EA3A: 19  normal larger: other order, its sign
    EX DE,HL                                   ; $EA3B: EB
    AND A                                      ; $EA3C: A7
    SBC HL,DE                                  ; $EA3D: ED 52
    LD A,C                                     ; $EA3F: 79
    XOR $80                                    ; $EA40: EE 80
    LD C,A                                     ; $EA42: 4F
L_EA43:
    SLA C                                      ; $EA43: CB 21  halve, sign into bit 15
    RR H                                       ; $EA45: CB 1C
    RR L                                       ; $EA47: CB 1D
    POP DE                                     ; $EA49: D1
    LD A,E                                     ; $EA4A: 7B  A = rotated normal, sign-magnitude
    RL D                                       ; $EA4B: CB 12
    RRA                                        ; $EA4D: 1F
    RET                                        ; $EA4E: C9

; VERIFIED: Random quadrant bits (random byte AND $0C = DrawLine bits 3..2 of the first end)
; stored by DrawLaser and reused for its later beam lines.
LaserBeamQuadrant:
    defb $00                                                                              ; $EA4F .

; VERIFIED: 1 = the previous UpdatePlayerLaser call accepted a fire request (key, temperature and
; a laser on the current view), whether or not the rate test then let it fire; 0 = no
; request.  UpdatePlayerLaser reads and clears it on every call.  While it is set,
; pulse and mining lasers fire only on frames where ObjectUpdateCounter AND 1 / AND 7
; is 0; a fresh press fires at once.
; Evidence: tools/check_routines.py combat/p9-player-laser-rate.
LaserTriggerHeld:
    defb $00                                                                              ; $EA50 .

; ============================================================================
; Object contact and player laser
; Collision, fuel scooping and docking when an object reaches the player,
; release of missile locks on removed objects, ship-slot reset and the
; per-frame player laser update.
; ============================================================================

; VERIFIED: Contact between the player and the object at IX (blueprint IY), called by the object
; loop (L_DBA3) before drawing.  Nothing happens while PlayerDeadFlag is set or unless
; |x|, |y| and |z| (16-bit magnitudes; z must also have no higher bits) are all below
; the contact radius: blueprint +1; +256 for a missile (+$26 bit 0) whose target code
; +$25 is 0 (the player); $B4 for scoopable objects (+$26 bit 1: set with $0A on the
; canisters, capsules, splinters and alloy plates launched from a parent by L_F592 and
; L_F5B8, and on orphaned Thargons at L_F80C).
; Scoopable objects below the player (y < 0) with FuelScoopsFitted are removed
; (energy 0, ReleaseTargetLocks) and, if CargoFreeSpace is nonzero, added through
; ScoopCargoItem: commodity (blueprint +0 >> 4) + 1 (capsule slaves, alloy plate
; alloys, splinter minerals, Thargon alien items); nibble 0 (canister): random 0..7, or
; the cloaking device ($FF) when MissionAspEncounterState is 3 (state then 0).
; Otherwise: the station (+$26 bit 2) runs TestStationDocking, everything else
; CollideWithObject (also a scoopable object above the player, without fuel scoops
; or with a full hold).
; Evidence: tools/check_routines.py contact/p9-object-contact, contact/p9-scooping and
; contact/p9-station-docking; runtime: entry executed in every flight scenario.
HandleObjectContact:
    LD A,(PlayerDeadFlag)                      ; $EA51: 3A 7A 70  nonzero: player dying, skip
    AND A                                      ; $EA54: A7
    RET NZ                                     ; $EA55: C0
    LD D,$00                                   ; $EA56: 16 00  D = 0: radius below 256
    LD E,(IY+$01)                              ; $EA58: FD 5E 01  blueprint +1: radius
    BIT 0,(IX+$26)                             ; $EA5B: DD CB 26 46  missile?
    JR Z,L_EA69                                ; $EA5F: 28 08
    LD A,(IX+$25)                              ; $EA61: DD 7E 25  target code 0: the player
    AND A                                      ; $EA64: A7
    JR NZ,L_EA69                               ; $EA65: 20 02
    LD D,$01                                   ; $EA67: 16 01  missile at the player: radius + 256
L_EA69:
    BIT 1,(IX+$26)                             ; $EA69: DD CB 26 4E  scoopable?
    JR Z,L_EA71                                ; $EA6D: 28 02
    LD E,$B4                                   ; $EA6F: 1E B4  radius 180 for (IX+$26) bit 1 objects
L_EA71:
    LD L,(IX+$00)                              ; $EA71: DD 6E 00
    LD H,(IX+$01)                              ; $EA74: DD 66 01
    SBC HL,DE                                  ; $EA77: ED 52
    RET NC                                     ; $EA79: D0  |x| >= radius: no contact
    AND A                                      ; $EA7A: A7
    LD L,(IX+$03)                              ; $EA7B: DD 6E 03
    LD H,(IX+$04)                              ; $EA7E: DD 66 04
    SBC HL,DE                                  ; $EA81: ED 52
    RET NC                                     ; $EA83: D0  |y| >= radius: no contact
    AND A                                      ; $EA84: A7
    LD L,(IX+$06)                              ; $EA85: DD 6E 06
    LD H,(IX+$07)                              ; $EA88: DD 66 07
    SBC HL,DE                                  ; $EA8B: ED 52
    RET NC                                     ; $EA8D: D0  |z| >= radius: no contact
    LD A,(IX+$08)                              ; $EA8E: DD 7E 08  z sign byte bits 0..6 must be clear
    AND $7F                                    ; $EA91: E6 7F
    RET NZ                                     ; $EA93: C0
    BIT 1,(IX+$26)                             ; $EA94: DD CB 26 4E
    JR Z,TestStationDocking                    ; $EA98: 28 3E  not scoopable: station or collision
    BIT 7,(IX+$05)                             ; $EA9A: DD CB 05 7E  y sign: object below the player?
    JP Z,CollideWithObject                     ; $EA9E: CA 23 EB  above: collision
    LD A,(FuelScoopsFitted)                    ; $EAA1: 3A 4A A8
    AND A                                      ; $EAA4: A7
    JP Z,CollideWithObject                     ; $EAA5: CA 23 EB  no fuel scoops: collision
    XOR A                                      ; $EAA8: AF
    LD (IX+$22),A                              ; $EAA9: DD 77 22  scooped: object removed
    CALL ReleaseTargetLocks                    ; $EAAC: CD 65 EB  release locks on it
    LD A,(CargoFreeSpace)                      ; $EAAF: 3A 3E A8
    AND A                                      ; $EAB2: A7
    JR Z,CollideWithObject                     ; $EAB3: 28 6E  hold full: collision damage
    LD A,(IY+$00)                              ; $EAB5: FD 7E 00  blueprint +0 high nibble
    AND $F0                                    ; $EAB8: E6 F0
    JR Z,L_EAC3                                ; $EABA: 28 07
    RRCA                                       ; $EABC: 0F
    RRCA                                       ; $EABD: 0F
    RRCA                                       ; $EABE: 0F
    RRCA                                       ; $EABF: 0F
    INC A                                      ; $EAC0: 3C  commodity = nibble + 1
    JR L_EAD5                                  ; $EAC1: 18 12
L_EAC3:
    LD A,(MissionAspEncounterState)            ; $EAC3: 3A 0C DA  canister: mission ship destroyed?
    SUB $03                                    ; $EAC6: D6 03
    JR NZ,L_EAD0                               ; $EAC8: 20 06
    LD (MissionAspEncounterState),A            ; $EACA: 32 0C DA  state 0 ...
    DEC A                                      ; $EACD: 3D  ... item $FF: cloaking device
    JR L_EAD5                                  ; $EACE: 18 05
L_EAD0:
    CALL NextRandomByte                        ; $EAD0: CD 24 ED
    AND $07                                    ; $EAD3: E6 07  random commodity 0..7
L_EAD5:
    JP ScoopCargoItem                          ; $EAD5: C3 B7 A8  add one ton (or the special item)

; VERIFIED: Station contact ((IX+$26) bit 2; other objects go to CollideWithObject).
; Crash (CrashIntoStation) unless the station's local z axis points at the player
; (+$0E sign set), the station is ahead (z sign clear), it is not hostile (+$21 bit 2)
; and |Z.x|, |Z.y| < $6E (compared as 2*magnitude with $DC).  Both below $1E: DockingContactFlag =
; 1, and CheckDocking docks on its next call.  Otherwise a scrape: SoundEffectRequests
; bit 6 and FrontDamageThisUpdate += 12 + 2*PlayerSpeed (again on every update while
; in contact).  The contact box, not the slot position, decides; the roll of the
; station is not tested.  The station keeps its energy.
; Evidence: tools/check_routines.py contact/p9-station-docking.
TestStationDocking:
    BIT 2,(IX+$26)                             ; $EAD8: DD CB 26 56
    JR Z,CollideWithObject                     ; $EADC: 28 45  not the station: collision
    BIT 7,(IX+$0E)                             ; $EADE: DD CB 0E 7E  local z axis must point at the player
    JR Z,CrashIntoStation                      ; $EAE2: 28 74
    BIT 7,(IX+$08)                             ; $EAE4: DD CB 08 7E  station must be in front (z positive)
    JR NZ,CrashIntoStation                     ; $EAE8: 20 6E
    BIT 2,(IX+$21)                             ; $EAEA: DD CB 21 56  hostile station?
    JR NZ,CrashIntoStation                     ; $EAEE: 20 68
    LD A,(IX+$0A)                              ; $EAF0: DD 7E 0A
    ADD A,A                                    ; $EAF3: 87  2*|Z.x| (sign shifted out)
    CP $DC                                     ; $EAF4: FE DC  2*|Z.x| < $DC
    JR NC,CrashIntoStation                     ; $EAF6: 30 60
    LD B,A                                     ; $EAF8: 47
    LD A,(IX+$0C)                              ; $EAF9: DD 7E 0C
    ADD A,A                                    ; $EAFC: 87
    CP $DC                                     ; $EAFD: FE DC  2*|Z.y| < $DC
    JR NC,CrashIntoStation                     ; $EAFF: 30 57
    CP $3C                                     ; $EB01: FE 3C  |Z.y| >= $1E: scrape
    JR NC,L_EB10                               ; $EB03: 30 0B
    LD A,B                                     ; $EB05: 78
    CP $3C                                     ; $EB06: FE 3C  |Z.x| >= $1E: scrape
    JR NC,L_EB10                               ; $EB08: 30 06
    LD A,$01                                   ; $EB0A: 3E 01
    LD (DockingContactFlag),A                  ; $EB0C: 32 15 DA  DockingContactFlag = 1: CheckDocking docks
    RET                                        ; $EB0F: C9
L_EB10:
    LD HL,SoundEffectRequests                  ; $EB10: 21 7D 70
    SET 6,(HL)                                 ; $EB13: CB F6  sound request bit 6
    LD HL,PlayerSpeed                          ; $EB15: 21 44 70
    LD A,(FrontDamageThisUpdate)               ; $EB18: 3A 18 DA
    ADD A,$0C                                  ; $EB1B: C6 0C  front damage 12 + 2*PlayerSpeed
    ADD A,(HL)                                 ; $EB1D: 86
    ADD A,(HL)                                 ; $EB1E: 86
    LD (FrontDamageThisUpdate),A               ; $EB1F: 32 18 DA
    RET                                        ; $EB22: C9

; VERIFIED: Collision with the object at IX: it is removed (energy 0).  Damage B = $50, plus the
; object's energy for a missile (+$26 bit 0).  The marked mission ship (+$26 bit 6)
; also ends MissionAspEncounterState.  SoundEffectRequests bit 2 is requested and B is
; added to RearDamageThisUpdate (object behind, z negative) or FrontDamageThisUpdate
; (L_EB5E); both paths end in ReleaseTargetLocks.
; NOTE: the station never comes here; CrashIntoStation is its crash path.
; Evidence: tools/check_routines.py contact/p9-object-contact and contact/p9-scooping.
CollideWithObject:
    LD B,(IX+$22)                              ; $EB23: DD 46 22  B = its energy
    XOR A                                      ; $EB26: AF
    LD (IX+$22),A                              ; $EB27: DD 77 22  object destroyed
    BIT 0,(IX+$26)                             ; $EB2A: DD CB 26 46  missile: its energy adds to the damage
    JR Z,L_EB31                                ; $EB2E: 28 01
    LD A,B                                     ; $EB30: 78
L_EB31:
    ADD A,$50                                  ; $EB31: C6 50  damage $50 (+ energy for bit 0 objects)
    LD B,A                                     ; $EB33: 47
    BIT 6,(IX+$26)                             ; $EB34: DD CB 26 76  marked mission ship?
    JR Z,L_EB44                                ; $EB38: 28 0A
    LD A,(MissionAspEncounterState)            ; $EB3A: 3A 0C DA
    AND A                                      ; $EB3D: A7  already 0: nothing to clear
    JR Z,L_EB44                                ; $EB3E: 28 04
    XOR A                                      ; $EB40: AF
    LD (MissionAspEncounterState),A            ; $EB41: 32 0C DA  MissionAspEncounterState = 0
L_EB44:
    LD HL,SoundEffectRequests                  ; $EB44: 21 7D 70
    SET 2,(HL)                                 ; $EB47: CB D6  sound request bit 2
    BIT 7,(IX+$08)                             ; $EB49: DD CB 08 7E  z sign: object behind the player
    JR Z,L_EB5E                                ; $EB4D: 28 0F
    LD A,(RearDamageThisUpdate)                ; $EB4F: 3A 19 DA
    ADD A,B                                    ; $EB52: 80
    LD (RearDamageThisUpdate),A                ; $EB53: 32 19 DA  rear damage
    JR ReleaseTargetLocks                      ; $EB56: 18 0D  release locks on it

; VERIFIED: Failed docking: PlayerDeadFlag = $0F, so the main loop starts RunGameOverSequence.
; Evidence: tools/check_routines.py contact/p9-station-docking (bad alignment, station
; behind, slot facing away, hostile station).
CrashIntoStation:
    LD A,$0F                                   ; $EB58: 3E 0F
    LD (PlayerDeadFlag),A                      ; $EB5A: 32 7A 70  PlayerDeadFlag = $0F: game over
    RET                                        ; $EB5D: C9
L_EB5E:
    LD A,(FrontDamageThisUpdate)               ; $EB5E: 3A 18 DA
    ADD A,B                                    ; $EB61: 80
    LD (FrontDamageThisUpdate),A               ; $EB62: 32 18 DA  front damage, then release locks

; VERIFIED: An object is being removed (destroyed, scooped, collided or out of range); H =
; ObjectLoopCounter, the counter of that object.  If the removed object IX is itself a
; missile (+$26 bit 0), every live object in slots 1..7 whose +$25 equals H gets
; +$20 bit 4 (explosion).  Then, if MissileState = 2 and MissileTarget = H, the
; player's missile lock ends: MissileState = 0 and TargetLostMessage bit 7 raised.
; IY preserved; returns DE = InstanceSize, B = 0.
; NOTE: the bit 0 test reads the removed object, not the scanned slot.  A missile
; locked on a removed ship therefore survives, and a ship whose +$25 AI state happens
; to equal the counter of a removed missile explodes.
; Evidence: tools/check_routines.py contact/p9-release-target-locks; runtime: executed
; in the flight scenarios (callers L_DB43, L_DCF3, L_EAAC and the collision path).
ReleaseTargetLocks:
    LD A,(ObjectLoopCounter)                   ; $EB65: 3A 1C DA  H = counter of the removed object
    LD H,A                                     ; $EB68: 67
    PUSH IY                                    ; $EB69: FD E5  caller's IY kept
    LD IY,InitialRuntimeState                  ; $EB6B: FD 21 48 60  IY = slot 0; advanced before each test
    LD DE,InstanceSize                         ; $EB6F: 11 27 00  slot size
    LD B,$07                                   ; $EB72: 06 07  slots 1..7
L_EB74:
    ADD IY,DE                                  ; $EB74: FD 19
    LD A,(IY+$22)                              ; $EB76: FD 7E 22  live slot (energy nonzero)?
    AND A                                      ; $EB79: A7
    JR Z,L_EB8C                                ; $EB7A: 28 10
    LD A,(IY+$25)                              ; $EB7C: FD 7E 25  its +$25 equals the removed counter?
    CP H                                       ; $EB7F: BC
    JR NZ,L_EB8C                               ; $EB80: 20 0A
    BIT 0,(IX+$26)                             ; $EB82: DD CB 26 46  tests the removed object, not this slot
    JR Z,L_EB8C                                ; $EB86: 28 04
    SET 4,(IY+$20)                             ; $EB88: FD CB 20 E6  start this object's explosion
L_EB8C:
    DJNZ L_EB74                                ; $EB8C: 10 E6
    POP IY                                     ; $EB8E: FD E1
    LD A,(MissileState)                        ; $EB90: 3A 0F A8  missile locked (state 2) ...
    CP $02                                     ; $EB93: FE 02
    RET NZ                                     ; $EB95: C0
    LD A,(MissileTarget)                       ; $EB96: 3A 9A A8  ... on the removed object?
    SUB H                                      ; $EB99: 94
    RET NZ                                     ; $EB9A: C0
    LD (MissileState),A                        ; $EB9B: 32 0F A8  MissileState = 0
    LD HL,TargetLostMessage                    ; $EB9E: 21 83 A8
    SET 7,(HL)                                 ; $EBA1: CB FE  raise TARGET LOST
    RET                                        ; $EBA3: C9

; VERIFIED: Set SoundEffectRequests bit 2, select the front view (CurrentScreenId = 0), zero the
; energy byte (+$22) of all 8 ship slots (energy 0 = free slot: FindFreeShipSlot,
; update loop $DA9F), then DispatchShipEvent $16 (one cargo canister near the player,
; SpawnCargoCanister with C odd) and $15 (two alloy plates near the player,
; SpawnAlloyPlatePair with C odd): the wreckage shown after the player's death.
; Evidence: only caller is the GAME OVER sequence at $7348.
ClearAllShipSlots:
    LD HL,SoundEffectRequests                  ; $EBA4: 21 7D 70
    SET 2,(HL)                                 ; $EBA7: CB D6  sound request bit 2
    XOR A                                      ; $EBA9: AF
    LD (CurrentScreenId),A                     ; $EBAA: 32 41 70  front view
    LD IX,InitialRuntimeState-InstanceSize     ; $EBAD: DD 21 21 60  IX = slot -1; advanced before each store
    LD DE,InstanceSize                         ; $EBB1: 11 27 00  slot size
    LD B,$08                                   ; $EBB4: 06 08
L_EBB6:
    ADD IX,DE                                  ; $EBB6: DD 19
    LD (IX+$22),A                              ; $EBB8: DD 77 22  energy 0: slot free
    DJNZ L_EBB6                                ; $EBBB: 10 F9
    LD A,$16                                   ; $EBBD: 3E 16
    CALL DispatchShipEvent                     ; $EBBF: CD CA F2  event $16: canister near the player
    LD A,$15                                   ; $EBC2: 3E 15
    JP DispatchShipEvent                       ; $EBC4: C3 CA F2  event $15: two alloy plates

; VERIFIED: Per-frame player laser update (continues into ApplyPlayerLaserHit / DrawLaser).
; LaserTemperature -= 2, floored at 0.  Fires only when KeyFlagsCombat bit 0 is set
; (then cleared), LaserTemperature is then below $90 and the LaserMounts byte for
; CurrentScreenId (1 pulse, 2 beam, 3 military, 4 mining) is nonzero.  Then
; LaserTriggerHeld = 1.  Pulse lasers set D = 1, mining lasers D = 7: when
; LaserTriggerHeld was already set, (ObjectUpdateCounter AND D) must be 0.  Firing
; (L_EC11) increments EnergyDrainThisUpdate, sets SoundEffectRequests bit 4 and raises
; LaserTemperature by a type-dependent amount (capped at $A0).
; Evidence: tools/check_routines.py combat/p9-player-laser-rate (all types and views,
; key release, temperature limits).
UpdatePlayerLaser:
    LD A,(LaserTriggerHeld)                    ; $EBC7: 3A 50 EA  flag from the previous frame
    LD C,A                                     ; $EBCA: 4F
    XOR A                                      ; $EBCB: AF
    LD (LaserTriggerHeld),A                    ; $EBCC: 32 50 EA  cleared until a request is accepted
    LD A,(LaserTemperature)                    ; $EBCF: 3A 4E 70
    CP $02                                     ; $EBD2: FE 02
    JR NC,L_EBD8                               ; $EBD4: 30 02
    LD A,$02                                   ; $EBD6: 3E 02
L_EBD8:
    SUB $02                                    ; $EBD8: D6 02  LaserTemperature -= 2, not below 0
    LD (LaserTemperature),A                    ; $EBDA: 32 4E 70
    LD HL,KeyFlagsCombat                       ; $EBDD: 21 11 FC
    BIT 0,(HL)                                 ; $EBE0: CB 46  fire request
    RET Z                                      ; $EBE2: C8
    RES 0,(HL)                                 ; $EBE3: CB 86  consume the request
    CP $90                                     ; $EBE5: FE 90  LaserTemperature >= $90: no fire
    RET NC                                     ; $EBE7: D0
    LD B,A                                     ; $EBE8: 47  B = cooled temperature (heat base at L_EC2A)
    LD A,(CurrentScreenId)                     ; $EBE9: 3A 41 70
    LD HL,LaserMounts                          ; $EBEC: 21 3F A8  laser byte for this view
    LD D,$00                                   ; $EBEF: 16 00
    LD E,A                                     ; $EBF1: 5F
    ADD HL,DE                                  ; $EBF2: 19
    LD A,(HL)                                  ; $EBF3: 7E
    AND A                                      ; $EBF4: A7
    RET Z                                      ; $EBF5: C8  no laser on this view
    LD E,C                                     ; $EBF6: 59  E = previous flag, C = laser type
    LD C,A                                     ; $EBF7: 4F
    DEC A                                      ; $EBF8: 3D
    JR NZ,L_EBFD                               ; $EBF9: 20 02
    LD D,$01                                   ; $EBFB: 16 01  type 1: D = 1
L_EBFD:
    SUB $03                                    ; $EBFD: D6 03
    JR NZ,L_EC03                               ; $EBFF: 20 02
    LD D,$07                                   ; $EC01: 16 07  laser 4: D = 7 (laser 1: D = 1)
L_EC03:
    LD A,E                                     ; $EC03: 7B  E = previous fire state
    AND E                                      ; $EC04: A3
    LD A,$01                                   ; $EC05: 3E 01
    LD (LaserTriggerHeld),A                    ; $EC07: 32 50 EA  firing in this call
    JR Z,L_EC11                                ; $EC0A: 28 05
    LD A,(ObjectUpdateCounter)                 ; $EC0C: 3A 0E DA  held fire repeats when ObjectUpdateCounter AND D = 0
    AND D                                      ; $EC0F: A2
    RET NZ                                     ; $EC10: C0
L_EC11:
    LD A,(EnergyDrainThisUpdate)               ; $EC11: 3A 17 DA  one energy drain unit per shot
    INC A                                      ; $EC14: 3C
    LD (EnergyDrainThisUpdate),A               ; $EC15: 32 17 DA
    LD HL,SoundEffectRequests                  ; $EC18: 21 7D 70  laser-fire sound request:
    SET 4,(HL)                                 ; $EC1B: CB E6  bit 4 (set only here)
    LD A,C                                     ; $EC1D: 79  damage: laser 1/2 15, 3 23, 4 50
    SUB $03                                    ; $EC1E: D6 03
    LD A,$0F                                   ; $EC20: 3E 0F
    JR C,L_EC2A                                ; $EC22: 38 06  laser 1/2: 15
    JR Z,L_EC28                                ; $EC24: 28 02  laser 3: 15+8 = 23
    ADD A,$1B                                  ; $EC26: C6 1B  laser 4: 15+27+8 = 50
L_EC28:
    ADD A,$08                                  ; $EC28: C6 08
L_EC2A:
    LD C,A                                     ; $EC2A: 4F  C = damage per hit
    LD A,D                                     ; $EC2B: 7A  heat +10 (D = 0) or +8 (D = 1/7)
    DEC A                                      ; $EC2C: 3D
    AND $01                                    ; $EC2D: E6 01
    RLA                                        ; $EC2F: 17
    ADD A,$08                                  ; $EC30: C6 08
    ADD A,B                                    ; $EC32: 80
    CP $A0                                     ; $EC33: FE A0  cap heat at $A0
    JR C,L_EC39                                ; $EC35: 38 02
    LD A,$A0                                   ; $EC37: 3E A0
L_EC39:
    LD (LaserTemperature),A                    ; $EC39: 32 4E 70  new temperature
    LD A,(TargetedObjectCounter)               ; $EC3C: 3A 12 DA  8 - slot index of the target, 0 = none
    AND A                                      ; $EC3F: A7
    JP Z,DrawLaser                             ; $EC40: CA D4 EC  no target: beams only
    DEC A                                      ; $EC43: 3D
    SUB $09                                    ; $EC44: D6 09
    CPL                                        ; $EC46: 2F  A = 9 - TargetedObjectCounter -> slot 8 - TargetedObjectCounter
    LD IX,InitialRuntimeState                  ; $EC47: DD 21 48 60  slot 0, then 8 - TargetedObjectCounter steps
    LD DE,$0027                                ; $EC4B: 11 27 00  instance size
L_EC4E:
    DEC A                                      ; $EC4E: 3D
    JR Z,ApplyPlayerLaserHit                   ; $EC4F: 28 04  IX = targeted instance
    ADD IX,DE                                  ; $EC51: DD 19
    JR L_EC4E                                  ; $EC53: 18 F9

; ============================================================================
; Player laser hits, beam drawing, RNG and sights
; Laser damage and debris events, the four-line beam (DrawLaser), the shared random number
; generator and the per-frame sights/laser/ECM update.
; ============================================================================

; VERIFIED: IX is the laser-hit instance; C is the pending damage amount.
; Set hostility bit 2 unconditionally, even for a Clean player, before damage checks.
; Continue the hit handling and beam drawing; this is not a standalone subroutine.
; Evidence: a nonlethal Fer-de-Lance hit in tools/check_bounty_hunters.py.
; VERIFIED: Entered from UpdatePlayerLaser with damage C = 15 (laser 1/2), 23 (3) or 50 (4).
; Requests the laser-hit sound (SoundEffectRequests bit 3, set only here).
; No damage to the station (+$26 bit 2, set only in slot 0), to an object whose explosion
; stage has begun (+$20 bit 5, set at $DBB6/$E201) or once energy +$22 is $FF (destroyed).
; Each damaging hit lowers the AI threshold +$25 by 14; on borrow it becomes 6 or 7
; (bit 0, ECM fitted, survives) and bit 7 (fleeing) is kept.  L_F8E2 makes a hostile ship
; flee when +$25 AND $7F < 8, and L_F7B6 compares +$25 with a random byte before
; abandoning ship.  Energy reaching zero (or borrowing) continues at L_EC8C (destruction
; and debris events).  All paths end in DrawLaser.
; NOTE: a fleeing ship (bit 7 set) never borrows, so a value below 14 wraps to $72+value.
; Evidence: combat/r10-laser-hit-outcomes in tools/check_routines.py (every +$25 value,
; flags, energies, all 19 blueprints).
ApplyPlayerLaserHit:
    SET 2,(IX+$21)                             ; $EC55: DD CB 21 D6  the target turns hostile
    LD HL,SoundEffectRequests                  ; $EC59: 21 7D 70  laser-hit sound request (bit 3)
    SET 3,(HL)                                 ; $EC5C: CB DE
    BIT 2,(IX+$26)                             ; $EC5E: DD CB 26 56  the station (slot 0): no damage
    JR NZ,DrawLaser                            ; $EC62: 20 70
    BIT 5,(IX+$20)                             ; $EC64: DD CB 20 6E  explosion stage: no damage
    JR NZ,DrawLaser                            ; $EC68: 20 6A
    LD A,(IX+$25)                              ; $EC6A: DD 7E 25  AI threshold -14 (floor 6 + bit 0)
    LD B,A                                     ; $EC6D: 47
    SUB $0E                                    ; $EC6E: D6 0E
    JR NC,L_EC76                               ; $EC70: 30 04
    AND $01                                    ; $EC72: E6 01
    ADD A,$06                                  ; $EC74: C6 06
L_EC76:
    RLA                                        ; $EC76: 17  bits 0..6 new, bit 7 old
    SLA B                                      ; $EC77: CB 20
    RRA                                        ; $EC79: 1F
    LD (IX+$25),A                              ; $EC7A: DD 77 25
    LD A,(IX+$22)                              ; $EC7D: DD 7E 22  energy $FF: already destroyed
    CP $FF                                     ; $EC80: FE FF
    JR Z,DrawLaser                             ; $EC82: 28 50
    SUB C                                      ; $EC84: 91  subtract the damage
    LD (IX+$22),A                              ; $EC85: DD 77 22
    JR Z,L_EC8C                                ; $EC88: 28 02  zero (or borrow): destroyed
    JR NC,DrawLaser                            ; $EC8A: 30 48  still alive: beams only

; VERIFIED: Target destroyed: energy +$22 := $FF (later hits are ignored), set +$20 bit 4.
; The Asp marked with +$26 bit 6 by L_F62C, destroyed while MissionAspEncounterState is 1
; or 2, sets that state to 3 and drops one cargo canister (event 6) instead of the usual
; debris; in state 3 the next object scooped through L_EAC3 yields item $FF, which
; ScoopCargoItem turns into the cloaking device (CommanderFlags bit 6).
; State 0 or 3, or an unmarked ship: debris choice at L_ECAD.
; Evidence: combat/r10-laser-hit-outcomes; scoop code at L_EAC3.
L_EC8C:
    XOR A                                      ; $EC8C: AF
    DEC A                                      ; $EC8D: 3D
    SET 4,(IX+$20)                             ; $EC8E: DD CB 20 E6
    LD (IX+$22),A                              ; $EC92: DD 77 22
    BIT 6,(IX+$26)                             ; $EC95: DD CB 26 76  Asp marked by L_F62C?
    JR Z,L_ECAD                                ; $EC99: 28 12
    LD A,(MissionAspEncounterState)            ; $EC9B: 3A 0C DA  only in state 1 or 2
    AND A                                      ; $EC9E: A7
    JR Z,L_ECAD                                ; $EC9F: 28 0C
    CP $03                                     ; $ECA1: FE 03
    JR Z,L_ECAD                                ; $ECA3: 28 08
    LD A,$03                                   ; $ECA5: 3E 03
    LD (MissionAspEncounterState),A            ; $ECA7: 32 0C DA  MissionAspEncounterState := 3
    ADD A,A                                    ; $ECAA: 87  event 6: one canister
    JR L_ECD1                                  ; $ECAB: 18 24

; VERIFIED: Debris selection from the blueprint at instance +$23/+$24:
; blueprint +0 low nibble nonzero -> event 6 (one Cargo canister at the parent, SpawnCargoCanister);
; else blueprint energy +7 >= 85 -> event 5 (two Alloy plates, SpawnAlloyPlatePair);
; else energy 60 (Asteroid) hit with damage 50 -> event 8 (two Splinters, SpawnSplinterPair, see
; docs/SHIPS.md); otherwise no debris. The event high nibble is 0, so C = 0 in the handlers
; and the debris appears at the destroyed ship.  With the default blueprints: rock hermit,
; traders, pirates and Krait drop a canister; Viper, Asp, Fer-de-Lance and Thargoid drop
; alloys; an Asteroid splits only under the mining laser; the rest drop nothing.
; Evidence: combat/r10-laser-hit-outcomes (all 19 blueprint IDs).
L_ECAD:
    LD H,(IX+$24)                              ; $ECAD: DD 66 24
    LD L,(IX+$23)                              ; $ECB0: DD 6E 23  HL = blueprint
    LD A,(HL)                                  ; $ECB3: 7E
    AND $0F                                    ; $ECB4: E6 0F  canister nibble -> event 6
    LD A,$06                                   ; $ECB6: 3E 06
    JR NZ,L_ECD1                               ; $ECB8: 20 17
    LD DE,$0007                                ; $ECBA: 11 07 00
    ADD HL,DE                                  ; $ECBD: 19
    LD A,(HL)                                  ; $ECBE: 7E
    CP $55                                     ; $ECBF: FE 55  energy >= 85 -> event 5
    LD A,$05                                   ; $ECC1: 3E 05
    JR NC,L_ECD1                               ; $ECC3: 30 0C
    LD A,(HL)                                  ; $ECC5: 7E
    CP $3C                                     ; $ECC6: FE 3C  energy 60: Asteroid
    JR NZ,DrawLaser                            ; $ECC8: 20 0A
    LD A,C                                     ; $ECCA: 79
    CP $32                                     ; $ECCB: FE 32  damage 50 -> event 8 (Splinters)
    JR NZ,DrawLaser                            ; $ECCD: 20 05
    LD A,$08                                   ; $ECCF: 3E 08
L_ECD1:
    CALL DispatchShipEvent                     ; $ECD1: CD CA F2  event 5, 6 or 8; C = 0: at this ship

; VERIFIED: draw player laser beams with the original random endpoint wiggle.
; VERIFIED: Four DrawLine calls from the bottom view edge to a random point at the centre.
; Start magnitudes (84,63) and (64,63): screen x 43/211 and 63/191 at y 126. End magnitudes
; D,E in {0,2} with random quadrant bits (RNG AND $0C), kept in LaserBeamQuadrant for the later beams.
; The start (HL) pixel at y 126 is not plotted, so the beams begin at y 125.
; Evidence: tools/check_laser_variant.py and lines/sights-and-laser-lines.
DrawLaser:
    CALL NextRandomByte                        ; $ECD4: CD 24 ED
    LD B,A                                     ; $ECD7: 47  B = random byte
    AND $0C                                    ; $ECD8: E6 0C
    LD C,A                                     ; $ECDA: 4F
    LD (LaserBeamQuadrant),A                   ; $ECDB: 32 4F EA  centre-end quadrant bits
    LD A,B                                     ; $ECDE: 78
    AND $03                                    ; $ECDF: E6 03
    OR $01                                     ; $ECE1: F6 01
    SUB $01                                    ; $ECE3: D6 01
    LD D,A                                     ; $ECE5: 57  D = 0 or 2
    RLC B                                      ; $ECE6: CB 00
    RLC B                                      ; $ECE8: CB 00
    LD A,B                                     ; $ECEA: 78
    AND $03                                    ; $ECEB: E6 03
    OR $01                                     ; $ECED: F6 01
    SUB $01                                    ; $ECEF: D6 01
    LD E,A                                     ; $ECF1: 5F  E = 0 or 2

; Optional single-beam dispatch; default keeps the original multiple line calls.
LaserPatchSite:
IF LASER_SINGLE
    INCLUDE "single-laser.asm"
    defw DrawLine ; unreachable original CALL operand bytes; preserve the layout
ELSE
    PUSH DE                                    ; $ECF2: D5
    LD A,C                                     ; $ECF3: 79
    OR $03                                     ; $ECF4: F6 03
    LD C,A                                     ; $ECF6: 4F
    LD HL,$543F                                ; $ECF7: 21 3F 54  start (84,63): screen (43,126)
    PUSH HL                                    ; $ECFA: E5
    CALL DrawLine                              ; $ECFB: CD 10 EE
ENDIF

; Original first-beam continuation; unreachable with laser=single.
LaserOriginalContinuation:
IF LASER_SINGLE
    assert SingleLaserEnd+2 = LaserOriginalContinuation
ENDIF
    POP HL                                     ; $ECFE: E1
    POP DE                                     ; $ECFF: D1
    LD A,(LaserBeamQuadrant)                   ; $ED00: 3A 4F EA
    OR $01                                     ; $ED03: F6 01
    LD C,A                                     ; $ED05: 4F  screen (211,126)
    PUSH DE                                    ; $ED06: D5
    CALL DrawLine                              ; $ED07: CD 10 EE  beam 2
    POP DE                                     ; $ED0A: D1
    LD HL,$403F                                ; $ED0B: 21 3F 40  start (64,63): (63,126), (191,126)
    LD A,(LaserBeamQuadrant)                   ; $ED0E: 3A 4F EA
    OR $03                                     ; $ED11: F6 03
    LD C,A                                     ; $ED13: 4F
    PUSH HL                                    ; $ED14: E5
    PUSH DE                                    ; $ED15: D5
    CALL DrawLine                              ; $ED16: CD 10 EE  beam 3
    POP DE                                     ; $ED19: D1
    POP HL                                     ; $ED1A: E1
    LD A,(LaserBeamQuadrant)                   ; $ED1B: 3A 4F EA
    OR $01                                     ; $ED1E: F6 01
    LD C,A                                     ; $ED20: 4F
    JP DrawLine                                ; $ED21: C3 10 EE  beam 4

; VERIFIED: Advance the two-byte RandomSeed and return the new high seed byte in A.
; Incoming carry is an input to the generator; do not clear or set it casually.
; For old seed bytes H:L and input carry c: t=2*H+c, new L=t&255,
; new H=(new L+old L+(t>>8))&255. The final ADC also sets output carry.
; BC and HL are saved/restored; DE is untouched. A and flags are results.
; VERIFIED: RandomSeed is written only here (static and runtime cross-references); it starts from
; the tape value $F562 and nothing reseeds it from a clock, the R register or input.  It
; is separate from AuxRandomSeed (stardust and damage effects).  31 call sites draw from
; it: ship creation and positions, encounter, launch and AI decisions, debris placement,
; the player's laser beam end point and AI laser beams.  The sequence advances only
; through these calls, so it depends on what happened before (for example how often the
; laser fired).
NextRandomByte:
    PUSH HL                                    ; $ED24: E5
    PUSH BC                                    ; $ED25: C5
    LD HL,(RandomSeed)                         ; $ED26: 2A 35 ED
    LD A,H                                     ; $ED29: 7C
    ADC A,A                                    ; $ED2A: 8F  A = 2*H + incoming carry
    LD B,A                                     ; $ED2B: 47
    ADC A,L                                    ; $ED2C: 8D  A = new L + old L + carry
    LD H,A                                     ; $ED2D: 67  new high byte, returned in A
    LD L,B                                     ; $ED2E: 68  new low byte
    LD (RandomSeed),HL                         ; $ED2F: 22 35 ED
    POP BC                                     ; $ED32: C1
    POP HL                                     ; $ED33: E1
    RET                                        ; $ED34: C9

; VERIFIED: Little-endian two-byte RNG state; its high byte holds the last returned random value.
RandomSeed:
    defw $F562                                                                            ; $ED35  initial seed from the tape

; VERIFIED: PlayerDeadFlag path of UpdateSightsLaserAndEcm: clear PlayerPitch and PlayerSpeed and
; return, so no sights, laser or ECM update runs after death.
; Evidence: combat/r10-sights-and-ecm.
ClearPitchAndSpeed:
    XOR A                                      ; $ED37: AF
    LD (PlayerPitch),A                         ; $ED38: 32 43 70
    LD (PlayerSpeed),A                         ; $ED3B: 32 44 70
    RET                                        ; $ED3E: C9

; VERIFIED: Per-frame weapon update, called by L_72D2, L_72FD and L_7356.  No register inputs;
; clobbers A, BC, DE, HL, IX and the alternate set (DrawLine).
; PlayerDeadFlag nonzero: ClearPitchAndSpeed.  Other screens than views 0..3
; (CurrentScreenId) return at once, without the ECM update.
; If LaserMounts+view (front, rear, left, right) holds a laser: draw four 8-pixel sight
; marks around (127,63) (x 111..118 and 136..143 at y 63; y 48..55 and 71..78 at x 127),
; then run UpdatePlayerLaser (temperature, firing, ApplyPlayerLaserHit or DrawLaser).
; Then, with or without a laser, the ECM countdown at L_ED83.
; Evidence: lines/sights-and-laser-lines (sight pixels), combat/r10-sights-and-ecm;
; runtime: all flight scenarios.
UpdateSightsLaserAndEcm:
    LD A,(PlayerDeadFlag)                      ; $ED3F: 3A 7A 70  nonzero: no weapons this frame
    AND A                                      ; $ED42: A7
    JR NZ,ClearPitchAndSpeed                   ; $ED43: 20 F2
    LD A,(CurrentScreenId)                     ; $ED45: 3A 41 70
    CP $04                                     ; $ED48: FE 04  flight views only
    RET NC                                     ; $ED4A: D0
    LD HL,LaserMounts                          ; $ED4B: 21 3F A8  laser of the current view
    LD D,$00                                   ; $ED4E: 16 00
    LD E,A                                     ; $ED50: 5F
    ADD HL,DE                                  ; $ED51: 19
    LD A,(HL)                                  ; $ED52: 7E
    AND A                                      ; $ED53: A7
    JR Z,L_ED83                                ; $ED54: 28 2D
    LD HL,$0800                                ; $ED56: 21 00 08  left mark: x 111..118, y 63
    LD DE,$1000                                ; $ED59: 11 00 10
    LD C,$0A                                   ; $ED5C: 0E 0A
    CALL DrawLine                              ; $ED5E: CD 10 EE
    LD HL,$0800                                ; $ED61: 21 00 08  right mark: x 136..143, y 63
    LD DE,$1000                                ; $ED64: 11 00 10
    LD C,E                                     ; $ED67: 4B
    CALL DrawLine                              ; $ED68: CD 10 EE
    LD HL,$0010                                ; $ED6B: 21 10 00  upper mark: x 127, y 48..55
    LD DE,$0008                                ; $ED6E: 11 08 00
    LD C,D                                     ; $ED71: 4A
    CALL DrawLine                              ; $ED72: CD 10 EE
    LD HL,$0010                                ; $ED75: 21 10 00  lower mark: x 127, y 71..78
    LD DE,$0008                                ; $ED78: 11 08 00
    LD C,$05                                   ; $ED7B: 0E 05
    CALL DrawLine                              ; $ED7D: CD 10 EE
    CALL UpdatePlayerLaser                     ; $ED80: CD C7 EB  heat, firing and beams

; VERIFIED: ECM countdown.  Skipped (RET) with the ECM jammer (CommanderFlags bit 7) while
; InvasionMissionState = 4; the AI ECM decision at L_F815 tests the same condition.
; B = old KeyFlagsCombat (its bit 4, the E key, is cleared in memory), C = EcmFitted.
; EcmTimer zero: ActivatePlayerEcm (E with an ECM fitted sets EcmFitted bit 7 and
; EcmTimer = 10).  Otherwise decrement EcmTimer and at zero clear bit 7 of C (the
; player's pulse is over).  While the timer runs: request the ECM sound
; (SoundEffectRequests bit 5, set only here) and, if the player owns an ECM (C nonzero),
; store C back and add one energy drain unit (EnergyDrainThisUpdate, subtracted by UpdateEnergyAndShields).
; NOTE: the drain also applies while an AI ship's ECM pulse (L_F815) runs.
; Evidence: combat/r10-sights-and-ecm.
L_ED83:
    LD A,(CommanderFlags)                      ; $ED83: 3A 72 A8  bit 7: ECM jammer
    BIT 7,A                                    ; $ED86: CB 7F
    JR Z,L_ED90                                ; $ED88: 28 06
    LD A,(InvasionMissionState)                ; $ED8A: 3A 71 A8  and InvasionMissionState = 4: no ECM update
    CP $04                                     ; $ED8D: FE 04
    RET Z                                      ; $ED8F: C8
L_ED90:
    LD HL,KeyFlagsCombat                       ; $ED90: 21 11 FC  bit 4 = the E key
    LD B,(HL)                                  ; $ED93: 46  B = key bits before clearing
    RES 4,(HL)                                 ; $ED94: CB A6  consume the E (ECM) key
    LD A,(EcmFitted)                           ; $ED96: 3A 47 A8  C = ECM fitted, bit 7 player pulse
    LD C,A                                     ; $ED99: 4F
    LD A,(EcmTimer)                            ; $ED9A: 3A 16 DA  ECM pulse countdown
    AND A                                      ; $ED9D: A7
    JP Z,ActivatePlayerEcm                     ; $ED9E: CA E4 BD  idle: start on the E key
    DEC A                                      ; $EDA1: 3D
    LD (EcmTimer),A                            ; $EDA2: 32 16 DA
    JR NZ,L_EDA9                               ; $EDA5: 20 02
    RES 7,C                                    ; $EDA7: CB B9  pulse over: clear bit 7
L_EDA9:
    LD HL,SoundEffectRequests                  ; $EDA9: 21 7D 70
    SET 5,(HL)                                 ; $EDAC: CB EE  ECM sound request (set only here)
    LD A,C                                     ; $EDAE: 79
    AND A                                      ; $EDAF: A7
    RET Z                                      ; $EDB0: C8  no ECM owned: no cost
    LD (EcmFitted),A                           ; $EDB1: 32 47 A8  write back (bit 7 cleared at the end)
    LD A,(EnergyDrainThisUpdate)               ; $EDB4: 3A 17 DA
    INC A                                      ; $EDB7: 3C
    LD (EnergyDrainThisUpdate),A               ; $EDB8: 32 17 DA  one energy drain unit per update
    RET                                        ; $EDBB: C9

; ============================================================================
; Clipped line renderer
; DrawLine draws into ViewBitmapBuffer (256x128). Endpoints are magnitudes about the view
; centre (127,63) plus quadrant bits; region tables and slope comparisons clip lines to the
; view, then one of four self-modified plotting loops steps along the major axis.
; ============================================================================

; VERIFIED: Region number of an outside endpoint, indexed by the 4-bit outcode built by DrawLine:
; bit 0 = |x| >= 128, bit 1 = |y| >= 64 (outside), bit 2 = below centre, bit 3 = left.
; Regions clockwise from top-left: 1 TL, 2 T, 3 TR, 4 R, 5 BR, 6 B, 7 BL, 8 L (odd = corner).
; The values are ordinal numbers (they select a row/column of LineClipRegionPairTable),
; not direction bit sets.  Entries for inside outcodes (bits 0..1 clear) are 0 and are
; never read.
; Evidence: index code at L_EE41..L_EE5E; runtime readers $EE4F/$EE5E; lines/draw-line.
LineClipRegionTable:
    defb $00,$04,$02,$03                                                                  ; $EDBC ....  up/right: -, R, T, TR
    defb $00,$04,$06,$05                                                                  ; $EDC0 ....  down/right: -, R, B, BR
    defb $00,$08,$02,$01                                                                  ; $EDC4 ....  up/left: -, L, T, TL
    defb $00,$08,$06,$07                                                                  ; $EDC8 ....  down/left: -, L, B, BL

; VERIFIED: Symmetric 8x8 table for two outside endpoints: row = DE-end region, column = HL-end
; region (both 1..8, columns TL,T,TR,R,BR,B,BL,L), read at L_EE6D as
; LineClipRegionTable+8*row+column+7.
; 0 = both on the same outer side: nothing visible, DrawLine returns.
; 1 = opposite regions (ClipLineBothEndsOutside). 2 = regions whose line may cut one view corner (L_EFA5).
LineClipRegionPairTable:
    defb $00,$00,$00,$02,$01,$02,$00,$00                                                  ; $EDCC ........  DE TL
    defb $00,$00,$00,$02,$02,$01,$02,$02                                                  ; $EDD4 ........  DE T
    defb $00,$00,$00,$00,$00,$02,$01,$02                                                  ; $EDDC ........  DE TR
    defb $02,$02,$00,$00,$00,$02,$02,$01                                                  ; $EDE4 ........  DE R
    defb $01,$02,$00,$00,$00,$00,$00,$02                                                  ; $EDEC ........  DE BR
    defb $02,$01,$02,$02,$00,$00,$00,$02                                                  ; $EDF4 ........  DE B
    defb $00,$02,$01,$02,$00,$00,$00,$00                                                  ; $EDFC ........  DE BL
    defb $00,$02,$02,$01,$02,$02,$00,$00                                                  ; $EE04 ........  DE L

; VERIFIED: Both-outside clipping workspace: low byte = HL-end region, high byte = DE-end region.
; Written at L_EFA5 (re-written swapped when the endpoints are exchanged), read at L_F021.
LineClipEndpointRegions:
    defb $00,$00                                                                          ; $EE0C ..

; VERIFIED: Low byte = slope, high byte = ComputeLineDelta flags of the vector from a view corner
; (magnitudes 128,64) to the DE endpoint. Saved at $EF70/$F00B, compared with the line
; slope at $EF7A/$F015 to decide which view edge the line crosses.
LineClipCornerVector:
    defb $00,$00                                                                          ; $EE0E ..

; VERIFIED: shared clipped line renderer. HL/DE are endpoint magnitudes; C holds quadrant bits.
; VERIFIED: Inputs: H,L = |x|,|y| of endpoint 1; D,E = |x|,|y| of endpoint 2; C bits 0/1 =
; endpoint 1 below/left of centre, bits 2/3 = endpoint 2 below/left.
; Screen x = 127+-|x|, y = 63+-|y|; an endpoint with |x| >= 128 or |y| >= 64 is clipped.
; Pixels are ORed (XOR mode: see L_DA29) into ViewBitmapBuffer, starting at the DE end or
; its clipped point; the HL end pixel itself is not plotted.
; Nothing is drawn when x1 = y2 = $FF or y1 = x2 = $FF (H AND E or L AND D = $FF): the
; test pairs coordinates of different endpoints, so one endpoint at ($FF,$FF) alone is
; still drawn.  Projected coordinates saturate at 255 (DivideRatioByte).
; All registers are clobbered; a drawn line returns from a plotting loop in the
; alternate register set (odd EXX count), so callers save what they need.
; Callers (static and runtime, the only ones): DrawVisibleEdges (ship edges), DrawAiLaserBeam (AI
; laser beam), DrawLaser and the sight marks of UpdateSightsLaserAndEcm.
; Paths: both inside L_EE99; one outside L_EE8F/L_F130; both outside via the region tables.
; Evidence: a simulator check in tools/check_routines.py: 1500 inside lines equal a DDA
; model exactly; 1500 clipped lines stay within 3 px of the ideal segment and never
; write outside the buffer.  Deltas above 255 use halved 9-bit values; one of about 350
; such random lines was clipped visibly wrong.
DrawLine:
    LD A,H                                     ; $EE10: 7C  x1 = y2 = $FF: nothing
    AND E                                      ; $EE11: A3
    INC A                                      ; $EE12: 3C
    RET Z                                      ; $EE13: C8
    LD A,L                                     ; $EE14: 7D  y1 = x2 = $FF: nothing
    AND D                                      ; $EE15: A2
    INC A                                      ; $EE16: 3C
    RET Z                                      ; $EE17: C8
    PUSH DE                                    ; $EE18: D5
    PUSH HL                                    ; $EE19: E5
    PUSH BC                                    ; $EE1A: C5
    LD A,C                                     ; $EE1B: 79
    AND $0C                                    ; $EE1C: E6 0C  B = DE outcode
    LD B,A                                     ; $EE1E: 47
    LD A,D                                     ; $EE1F: 7A
    CP $80                                     ; $EE20: FE 80  |x2| >= 128
    JR C,L_EE26                                ; $EE22: 38 02
    SET 0,B                                    ; $EE24: CB C0
L_EE26:
    LD A,E                                     ; $EE26: 7B
    CP $40                                     ; $EE27: FE 40  |y2| >= 64
    JR C,L_EE2D                                ; $EE29: 38 02
    SET 1,B                                    ; $EE2B: CB C8
L_EE2D:
    LD A,C                                     ; $EE2D: 79
    AND $03                                    ; $EE2E: E6 03  C = HL outcode
    ADD A,A                                    ; $EE30: 87
    ADD A,A                                    ; $EE31: 87
    LD C,A                                     ; $EE32: 4F  HL quadrant in bits 3/2
    LD A,H                                     ; $EE33: 7C
    CP $80                                     ; $EE34: FE 80  |x1| >= 128
    JR C,L_EE3A                                ; $EE36: 38 02
    SET 0,C                                    ; $EE38: CB C1
L_EE3A:
    LD A,L                                     ; $EE3A: 7D
    CP $40                                     ; $EE3B: FE 40  |y1| >= 64
    JR C,L_EE41                                ; $EE3D: 38 02
    SET 1,C                                    ; $EE3F: CB C9
L_EE41:
    LD HL,LineClipRegionTable                  ; $EE41: 21 BC ED
    LD A,B                                     ; $EE44: 78
    AND $03                                    ; $EE45: E6 03  DE end inside?
    JR Z,L_EE87                                ; $EE47: 28 3E
    LD A,B                                     ; $EE49: 78
    ADD A,L                                    ; $EE4A: 85
    LD L,A                                     ; $EE4B: 6F
    JR NC,L_EE4F                               ; $EE4C: 30 01
    INC H                                      ; $EE4E: 24
L_EE4F:
    LD B,(HL)                                  ; $EE4F: 46  DE region 1..8
    LD HL,LineClipRegionTable                  ; $EE50: 21 BC ED
    LD A,C                                     ; $EE53: 79
    AND $03                                    ; $EE54: E6 03  HL end inside?
    JR Z,L_EE77                                ; $EE56: 28 1F  HL inside, DE outside: swap
    LD A,C                                     ; $EE58: 79
    ADD A,L                                    ; $EE59: 85
    LD L,A                                     ; $EE5A: 6F
    JR NC,L_EE5E                               ; $EE5B: 30 01
    INC H                                      ; $EE5D: 24
L_EE5E:
    LD C,(HL)                                  ; $EE5E: 4E  HL region 1..8
    LD A,B                                     ; $EE5F: 78
    ADD A,A                                    ; $EE60: 87
    ADD A,A                                    ; $EE61: 87
    ADD A,A                                    ; $EE62: 87
    ADD A,C                                    ; $EE63: 81  8*B + C
    LD HL,LineClipRegionTable                  ; $EE64: 21 BC ED
    ADD A,LineClipRegionPairTable-LineClipRegionTable-9 ; $EE67: C6 07  row B-1, column C-1
    ADD A,L                                    ; $EE69: 85
    JR NC,L_EE6D                               ; $EE6A: 30 01
    INC H                                      ; $EE6C: 24
L_EE6D:
    LD L,A                                     ; $EE6D: 6F
    LD A,(HL)                                  ; $EE6E: 7E  pair value; 0 = invisible
    AND A                                      ; $EE6F: A7
    JP NZ,ClipLineBothEndsOutside              ; $EE70: C2 58 EF  the line may cross the view
    POP HL                                     ; $EE73: E1  drop saved BC, HL, DE
    POP HL                                     ; $EE74: E1
    POP HL                                     ; $EE75: E1
    RET                                        ; $EE76: C9

; VERIFIED: DE end outside, HL end inside: swap the endpoints and the quadrant pairs in C,
; so that HL is the outside end and drawing starts from the inside end.
L_EE77:
    POP BC                                     ; $EE77: C1
    POP DE                                     ; $EE78: D1
    POP HL                                     ; $EE79: E1
    LD A,C                                     ; $EE7A: 79  swap the quadrant pairs
    ADD A,A                                    ; $EE7B: 87
    ADD A,A                                    ; $EE7C: 87
    SRL C                                      ; $EE7D: CB 39
    SRL C                                      ; $EE7F: CB 39
    OR C                                       ; $EE81: B1
    AND $0F                                    ; $EE82: E6 0F
    LD C,A                                     ; $EE84: 4F
    JR L_EE8F                                  ; $EE85: 18 08  one end (now HL) outside

; VERIFIED: DE end inside: both inside -> L_EE99; HL outside -> keep the order and clip (L_EE8F).
L_EE87:
    LD A,C                                     ; $EE87: 79
    AND $03                                    ; $EE88: E6 03
    JR Z,L_EE99                                ; $EE8A: 28 0D  both ends inside
    POP BC                                     ; $EE8C: C1
    POP HL                                     ; $EE8D: E1
    POP DE                                     ; $EE8E: D1

; VERIFIED: One end outside (HL), DE inside: delta and slope, plot start at DE, then L_F130
; limits the pixel count to the distance from DE to the view edge.
L_EE8F:
    LD B,C                                     ; $EE8F: 41
    CALL ComputeLineDelta                      ; $EE90: CD 75 F1  H,L = |dx|,|dy|; B flags; C slope
    CALL SetLinePlotStart                      ; $EE93: CD D6 F0  start address/mask at DE
    JP L_F130                                  ; $EE96: C3 30 F1  count up to the view edge

; VERIFIED: Both ends inside: plot from DE for max(|dx|,|dy|) pixels; the HL end pixel is omitted.
L_EE99:
    POP BC                                     ; $EE99: C1
    POP HL                                     ; $EE9A: E1
    POP DE                                     ; $EE9B: D1
    LD B,C                                     ; $EE9C: 41
    CALL ComputeLineDelta                      ; $EE9D: CD 75 F1
    CALL SetLinePlotStart                      ; $EEA0: CD D6 F0
    INC H                                      ; $EEA3: 24  pixel counts |dx|+1, |dy|+1
    INC L                                      ; $EEA4: 2C
    LD D,B                                     ; $EEA5: 50
    BIT 4,B                                    ; $EEA6: CB 60  x-major: count along x
    LD A,L                                     ; $EEA8: 7D
    JR Z,L_EEAC                                ; $EEA9: 28 01
    LD A,H                                     ; $EEAB: 7C

; VERIFIED: Common plot set-up. A = pixel count along the major axis; alternate HL/C/B/E come from
; SetLinePlotStart. Alternate D := max(A,2)-1 pixels, alternate E := $80 (error accumulator),
; and the slope becomes the ADD A,n operand of the selected loop. Flags AND $1C (bit 2 draw
; up, bit 3 draw right, bit 4 x-major) select the loop and patch its x step:
; RRC C ($CB $09) with INC L ($2C) steps right; RLC C ($CB $01) with DEC L ($2D) steps left.
; 0/8: PlotSteepLineDown, 4/$0C: PlotSteepLineUp, $10/$18: PlotShallowLineDown,
; $14/$1C: PlotShallowLineUp (the +8 values step right).
L_EEAC:
    EXX                                        ; $EEAC: D9
    CP $02                                     ; $EEAD: FE 02  at least one pixel
    JR NC,L_EEB3                               ; $EEAF: 30 02
    LD A,$02                                   ; $EEB1: 3E 02
L_EEB3:
    DEC A                                      ; $EEB3: 3D
    LD D,A                                     ; $EEB4: 57  pixels to plot
    LD A,E                                     ; $EEB5: 7B
    LD E,$80                                   ; $EEB6: 1E 80  error accumulator = 1/2
    EXX                                        ; $EEB8: D9
    LD B,A                                     ; $EEB9: 47
    LD A,D                                     ; $EEBA: 7A
    EXX                                        ; $EEBB: D9
    AND $1C                                    ; $EEBC: E6 1C  bit 2 up, 3 right, 4 x-major
    CP $0E                                     ; $EEBE: FE 0E  x-major: $10..$1C
    JR NC,L_EEFA                               ; $EEC0: 30 38
    CP $06                                     ; $EEC2: FE 06  cases 8 and $0C
    JR NC,L_EEE3                               ; $EEC4: 30 1D
    CP $02                                     ; $EEC6: FE 02  case 4 or 0
    JP NC,L_EED7                               ; $EEC8: D2 D7 EE
    LD A,$01                                   ; $EECB: 3E 01
    LD (SteepDownMaskRotate),A                 ; $EECD: 32 5D F2  case 0: RLC C (left)
    LD A,$2D                                   ; $EED0: 3E 2D
    LD (SteepDownByteStep),A                   ; $EED2: 32 75 F2  DEC L
    JR L_EEF1                                  ; $EED5: 18 1A
L_EED7:
    LD A,$01                                   ; $EED7: 3E 01
    LD (SteepUpMaskRotate),A                   ; $EED9: 32 0E F2  case 4: RLC C (left)
    LD A,$2D                                   ; $EEDC: 3E 2D
    LD (SteepUpByteStep),A                     ; $EEDE: 32 24 F2  DEC L
    JR L_EF3C                                  ; $EEE1: 18 59
L_EEE3:
    CP $0A                                     ; $EEE3: FE 0A  case $0C or 8
    JR NC,L_EF32                               ; $EEE5: 30 4B
    LD A,$09                                   ; $EEE7: 3E 09
    LD (SteepDownMaskRotate),A                 ; $EEE9: 32 5D F2  case 8: RRC C (right)
    LD A,$2C                                   ; $EEEC: 3E 2C
    LD (SteepDownByteStep),A                   ; $EEEE: 32 75 F2  INC L
L_EEF1:
    EXX                                        ; $EEF1: D9
    LD A,B                                     ; $EEF2: 78
    EXX                                        ; $EEF3: D9
    LD (SteepDownSlope),A                      ; $EEF4: 32 58 F2  slope
    JP PlotSteepLineDown                       ; $EEF7: C3 51 F2
L_EEFA:
    CP $16                                     ; $EEFA: FE 16  cases $18 and $1C
    JR NC,L_EF1A                               ; $EEFC: 30 1C
    CP $12                                     ; $EEFE: FE 12  case $14 or $10
    JR NC,L_EF0E                               ; $EF00: 30 0C
    LD A,$01                                   ; $EF02: 3E 01
    LD (ShallowDownMaskRotate),A               ; $EF04: 32 7A F2  case $10: RLC C (left)
    LD A,$2D                                   ; $EF07: 3E 2D
    LD (ShallowDownByteStep),A                 ; $EF09: 32 9D F2  DEC L
    JR L_EF29                                  ; $EF0C: 18 1B
L_EF0E:
    LD A,$01                                   ; $EF0E: 3E 01
    LD (ShallowUpMaskRotate),A                 ; $EF10: 32 2D F2  case $14: RLC C (left)
    LD A,$2D                                   ; $EF13: 3E 2D
    LD (ShallowUpByteStep),A                   ; $EF15: 32 28 F2  DEC L
    JR L_EF4F                                  ; $EF18: 18 35
L_EF1A:
    CP $1A                                     ; $EF1A: FE 1A  case $1C or $18
    JP NC,L_EF45                               ; $EF1C: D2 45 EF
    LD A,$09                                   ; $EF1F: 3E 09
    LD (ShallowDownMaskRotate),A               ; $EF21: 32 7A F2  case $18: RRC C (right)
    LD A,$2C                                   ; $EF24: 3E 2C
    LD (ShallowDownByteStep),A                 ; $EF26: 32 9D F2  INC L
L_EF29:
    EXX                                        ; $EF29: D9
    LD A,B                                     ; $EF2A: 78
    EXX                                        ; $EF2B: D9
    LD (ShallowDownSlope),A                    ; $EF2C: 32 84 F2  slope
    JP PlotShallowLineDown                     ; $EF2F: C3 7D F2
L_EF32:
    LD A,$09                                   ; $EF32: 3E 09
    LD (SteepUpMaskRotate),A                   ; $EF34: 32 0E F2  case $0C: RRC C (right)
    LD A,$2C                                   ; $EF37: 3E 2C
    LD (SteepUpByteStep),A                     ; $EF39: 32 24 F2  INC L
L_EF3C:
    EXX                                        ; $EF3C: D9
    LD A,B                                     ; $EF3D: 78
    EXX                                        ; $EF3E: D9
    LD (SteepUpSlope),A                        ; $EF3F: 32 09 F2  slope
    JP PlotSteepLineUp                         ; $EF42: C3 02 F2
L_EF45:
    LD A,$09                                   ; $EF45: 3E 09
    LD (ShallowUpMaskRotate),A                 ; $EF47: 32 2D F2  case $1C: RRC C (right)
    LD A,$2C                                   ; $EF4A: 3E 2C
    LD (ShallowUpByteStep),A                   ; $EF4C: 32 28 F2  INC L
L_EF4F:
    EXX                                        ; $EF4F: D9
    LD A,B                                     ; $EF50: 78
    EXX                                        ; $EF51: D9
    LD (ShallowUpSlope),A                      ; $EF52: 32 37 F2  slope
    JP PlotShallowLineUp                       ; $EF55: C3 30 F2

; VERIFIED: Both ends outside; A = pair value 1 or 2, L = saved quadrant bits.
; Value 1 (opposite regions): corner pairs compare the line slope with the vector from DE
; to the corner of its own quadrant; edge pairs (L_EF96) clip DE on its own edge.
; Value 2 continues at L_EFA5.
ClipLineBothEndsOutside:
    POP HL                                     ; $EF58: E1  L = saved quadrant bits
    PUSH HL                                    ; $EF59: E5
    DEC A                                      ; $EF5A: 3D
    JR NZ,L_EFA5                               ; $EF5B: 20 48
    BIT 0,B                                    ; $EF5D: CB 40  odd DE region: corner pair
    JR Z,L_EF96                                ; $EF5F: 28 35
    LD A,L                                     ; $EF61: 7D
    AND $0C                                    ; $EF62: E6 0C
    SRL L                                      ; $EF64: CB 3D
    SRL L                                      ; $EF66: CB 3D
    OR L                                       ; $EF68: B5  DE quadrant for both ends
    LD B,A                                     ; $EF69: 47
    LD HL,$8040                                ; $EF6A: 21 40 80  corner of the DE quadrant
    CALL ComputeLineDelta                      ; $EF6D: CD 75 F1
    LD (LineClipCornerVector),BC               ; $EF70: ED 43 0E EE  corner-to-DE flags/slope
    POP BC                                     ; $EF74: C1
    POP HL                                     ; $EF75: E1
    LD B,C                                     ; $EF76: 41
    CALL ComputeLineDelta                      ; $EF77: CD 75 F1  delta and slope of the line
    LD DE,(LineClipCornerVector)               ; $EF7A: ED 5B 0E EE
    LD A,B                                     ; $EF7E: 78
    XOR D                                      ; $EF7F: AA
    AND $10                                    ; $EF80: E6 10
    JR Z,L_EF86                                ; $EF82: 28 02
    LD E,$FF                                   ; $EF84: 1E FF  other major axis: slope $FF
L_EF86:
    BIT 4,B                                    ; $EF86: CB 60
    JR Z,L_EF8E                                ; $EF88: 28 04
    LD A,C                                     ; $EF8A: 79
    SUB E                                      ; $EF8B: 93
    JR L_EF90                                  ; $EF8C: 18 02
L_EF8E:
    LD A,E                                     ; $EF8E: 7B
    SUB C                                      ; $EF8F: 91
L_EF90:
    JP C,L_F042                                ; $EF90: DA 42 F0  slope test picks the edge
    JP L_F080                                  ; $EF93: C3 80 F0

; VERIFIED: Opposite edge regions: |y2| >= 64 (top/bottom pair) clips DE at the horizontal edge
; (L_F042); otherwise (left/right pair) at the vertical edge (L_F080).
L_EF96:
    POP BC                                     ; $EF96: C1
    POP HL                                     ; $EF97: E1
    LD B,C                                     ; $EF98: 41
    CALL ComputeLineDelta                      ; $EF99: CD 75 F1
    LD A,E                                     ; $EF9C: 7B
    CP $40                                     ; $EF9D: FE 40  top/bottom pair?
    JP NC,L_F042                               ; $EF9F: D2 42 F0
    JP L_F080                                  ; $EFA2: C3 80 F0

; VERIFIED: Pair value 2: save both region numbers in LineClipEndpointRegions and exchange the
; endpoints when the DE end lies in a corner region, so that DE is in an edge region.
; Then choose the view corner between the two regions as quadrant bits in H:
; 0 top-right, 1 bottom-right, 2 top-left, 3 bottom-left (sum and XOR tests at L_EFCC).
L_EFA5:
    LD (LineClipEndpointRegions),BC            ; $EFA5: ED 43 0C EE  C = HL region, B = DE region
    BIT 0,B                                    ; $EFA9: CB 40  DE in a corner: swap ends
    JR Z,L_EFCC                                ; $EFAB: 28 1F
    POP BC                                     ; $EFAD: C1
    POP DE                                     ; $EFAE: D1
    POP HL                                     ; $EFAF: E1
    PUSH DE                                    ; $EFB0: D5
    PUSH HL                                    ; $EFB1: E5
    LD A,C                                     ; $EFB2: 79
    SRL A                                      ; $EFB3: CB 3F
    SRL A                                      ; $EFB5: CB 3F
    SLA C                                      ; $EFB7: CB 21
    SLA C                                      ; $EFB9: CB 21
    OR C                                       ; $EFBB: B1
    AND $0F                                    ; $EFBC: E6 0F
    LD C,A                                     ; $EFBE: 4F
    LD L,C                                     ; $EFBF: 69
    PUSH BC                                    ; $EFC0: C5
    LD BC,(LineClipEndpointRegions)            ; $EFC1: ED 4B 0C EE
    LD A,B                                     ; $EFC5: 78
    LD B,C                                     ; $EFC6: 41
    LD C,A                                     ; $EFC7: 4F
    LD (LineClipEndpointRegions),BC            ; $EFC8: ED 43 0C EE  swapped regions
L_EFCC:
    LD A,B                                     ; $EFCC: 78
    ADD A,C                                    ; $EFCD: 81
    CP $07                                     ; $EFCE: FE 07  sum < 7: top-right
    LD H,$00                                   ; $EFD0: 26 00
    JR C,L_F000                                ; $EFD2: 38 2C
    CP $0C                                     ; $EFD4: FE 0C  sum >= 12: bottom-left
    LD H,$03                                   ; $EFD6: 26 03
    JR NC,L_F000                               ; $EFD8: 30 26
    LD A,B                                     ; $EFDA: 78
    XOR C                                      ; $EFDB: A9
    DEC H                                      ; $EFDC: 25
    CP $08                                     ; $EFDD: FE 08  XOR >= 8: top-left
    JR NC,L_F000                               ; $EFDF: 30 1F
    DEC H                                      ; $EFE1: 25
    CP $04                                     ; $EFE2: FE 04  XOR < 4: bottom-right
    JR C,L_F000                                ; $EFE4: 38 1A
    CP $05                                     ; $EFE6: FE 05  XOR 5: by DE region
    JR Z,L_EFFA                                ; $EFE8: 28 10
    LD A,B                                     ; $EFEA: 78
    XOR $06                                    ; $EFEB: EE 06  bottom-left or top-right
    LD H,$03                                   ; $EFED: 26 03
    AND C                                      ; $EFEF: A1
    JR Z,L_F000                                ; $EFF0: 28 0E
    CP $06                                     ; $EFF2: FE 06
    JR Z,L_F000                                ; $EFF4: 28 0A
    LD H,$00                                   ; $EFF6: 26 00
    JR L_F000                                  ; $EFF8: 18 06
L_EFFA:
    LD A,B                                     ; $EFFA: 78
    CP $02                                     ; $EFFB: FE 02
    JR NZ,L_F000                               ; $EFFD: 20 01
    INC H                                      ; $EFFF: 24

; VERIFIED: Build the corner-to-DE vector (LineClipCornerVector) and the line delta, then compare
; their slopes: a line passing outside the chosen corner is dropped (L_F040, nothing drawn);
; otherwise DE is clipped to its own edge (L_F042 or L_F080).
L_F000:
    LD A,L                                     ; $F000: 7D
    AND $0C                                    ; $F001: E6 0C  corner quadrant in bits 0/1
    OR H                                       ; $F003: B4
    LD B,A                                     ; $F004: 47
    LD HL,$8040                                ; $F005: 21 40 80  selected view corner
    CALL ComputeLineDelta                      ; $F008: CD 75 F1
    LD (LineClipCornerVector),BC               ; $F00B: ED 43 0E EE  corner-to-DE flags/slope
    POP BC                                     ; $F00F: C1
    POP HL                                     ; $F010: E1
    LD B,C                                     ; $F011: 41
    CALL ComputeLineDelta                      ; $F012: CD 75 F1  delta and slope of the line
    LD DE,(LineClipCornerVector)               ; $F015: ED 5B 0E EE
    LD A,B                                     ; $F019: 78
    XOR D                                      ; $F01A: AA
    AND $10                                    ; $F01B: E6 10
    JR Z,L_F021                                ; $F01D: 28 02
    LD E,$FF                                   ; $F01F: 1E FF  other major axis: slope $FF
L_F021:
    LD HL,(LineClipEndpointRegions)            ; $F021: 2A 0C EE  H = DE region, L = HL region
    BIT 4,B                                    ; $F024: CB 60
    JR Z,L_F02E                                ; $F026: 28 06
    BIT 1,H                                    ; $F028: CB 4C  DE on the top/bottom edge?
    JR NZ,L_F032                               ; $F02A: 20 06
    JR L_F03C                                  ; $F02C: 18 0E
L_F02E:
    BIT 1,H                                    ; $F02E: CB 4C
    JR NZ,L_F03C                               ; $F030: 20 0A
L_F032:
    LD A,E                                     ; $F032: 7B
    SUB C                                      ; $F033: 91
    JR NC,L_F040                               ; $F034: 30 0A
L_F036:
    BIT 1,H                                    ; $F036: CB 4C
    JR Z,L_F080                                ; $F038: 28 46
    JR L_F042                                  ; $F03A: 18 06
L_F03C:
    LD A,C                                     ; $F03C: 79
    SUB E                                      ; $F03D: 93
    JR C,L_F036                                ; $F03E: 38 F6
L_F040:
    POP HL                                     ; $F040: E1  misses the view: return
    RET                                        ; $F041: C9

; VERIFIED: Clip DE to the horizontal edge: move |x| by the y excess (|y|-64) times the slope
; (ScaleByFraction) or divided by it (DivideToFractionC), flipping the x quadrant bit
; when it crosses the centre; then |y| := 63 and |x| is clamped to 127.
; Plot from there; L_F130 sets the count.
L_F042:
    POP DE                                     ; $F042: D1
    PUSH BC                                    ; $F043: C5
    LD A,E                                     ; $F044: 7B
    SUB $40                                    ; $F045: D6 40  y excess beyond the edge
    LD E,A                                     ; $F047: 5F
    LD L,B                                     ; $F048: 68
    BIT 4,B                                    ; $F049: CB 60
    JR NZ,L_F052                               ; $F04B: 20 05
    CALL ScaleByFraction                       ; $F04D: CD BE F0  y-major: excess * slope
    JR L_F056                                  ; $F050: 18 04
L_F052:
    LD B,C                                     ; $F052: 41
    CALL DivideToFractionC                     ; $F053: CD CC F0  x-major: excess / slope
L_F056:
    LD A,L                                     ; $F056: 7D
    RRA                                        ; $F057: 1F
    RRA                                        ; $F058: 1F
    XOR L                                      ; $F059: AD
    AND $02                                    ; $F05A: E6 02  towards the centre?
    JR NZ,L_F07A                               ; $F05C: 20 1C
    LD A,D                                     ; $F05E: 7A
    SUB C                                      ; $F05F: 91
    LD D,A                                     ; $F060: 57
    POP BC                                     ; $F061: C1
    JR NC,L_F06B                               ; $F062: 30 07
    NEG                                        ; $F064: ED 44
    LD D,A                                     ; $F066: 57
    LD A,B                                     ; $F067: 78
    XOR $02                                    ; $F068: EE 02  crossed: flip x quadrant
    LD B,A                                     ; $F06A: 47
L_F06B:
    LD E,$3F                                   ; $F06B: 1E 3F  |y| := 63
    LD A,D                                     ; $F06D: 7A
    CP $80                                     ; $F06E: FE 80
    JR C,L_F074                                ; $F070: 38 02
    LD D,$7F                                   ; $F072: 16 7F  clamp |x| to 127
L_F074:
    CALL SetLinePlotStart                      ; $F074: CD D6 F0  plot start: the clipped DE
    JP L_F130                                  ; $F077: C3 30 F1  pixel count from there
L_F07A:
    LD A,D                                     ; $F07A: 7A
    ADD A,C                                    ; $F07B: 81
    LD D,A                                     ; $F07C: 57
    POP BC                                     ; $F07D: C1
    JR L_F06B                                  ; $F07E: 18 EB

; VERIFIED: Clip DE to the vertical edge: move |y| by the x excess (|x|-128) as in L_F042,
; flipping the y quadrant bit on crossing; then |x| := 127 and |y| is clamped to 63.
L_F080:
    POP DE                                     ; $F080: D1
    PUSH BC                                    ; $F081: C5
    LD A,D                                     ; $F082: 7A
    SUB $80                                    ; $F083: D6 80  x excess beyond the edge
    LD D,A                                     ; $F085: 57
    LD L,B                                     ; $F086: 68
    BIT 4,B                                    ; $F087: CB 60
    JR Z,L_F090                                ; $F089: 28 05
    CALL ScaleByFraction                       ; $F08B: CD BE F0  x-major: excess * slope
    JR L_F094                                  ; $F08E: 18 04
L_F090:
    LD B,C                                     ; $F090: 41
    CALL DivideToFractionC                     ; $F091: CD CC F0  y-major: excess / slope
L_F094:
    LD A,L                                     ; $F094: 7D
    RRA                                        ; $F095: 1F
    RRA                                        ; $F096: 1F
    XOR L                                      ; $F097: AD
    AND $01                                    ; $F098: E6 01  towards the centre?
    JR NZ,L_F0B8                               ; $F09A: 20 1C
    LD A,E                                     ; $F09C: 7B
    SUB C                                      ; $F09D: 91
    LD E,A                                     ; $F09E: 5F
    POP BC                                     ; $F09F: C1
    JR NC,L_F0A9                               ; $F0A0: 30 07
    NEG                                        ; $F0A2: ED 44
    LD E,A                                     ; $F0A4: 5F
    LD A,B                                     ; $F0A5: 78
    XOR $01                                    ; $F0A6: EE 01  crossed: flip y quadrant
    LD B,A                                     ; $F0A8: 47
L_F0A9:
    LD D,$7F                                   ; $F0A9: 16 7F  |x| := 127
    LD A,E                                     ; $F0AB: 7B
    CP $40                                     ; $F0AC: FE 40
    JR C,L_F0B2                                ; $F0AE: 38 02
    LD E,$3F                                   ; $F0B0: 1E 3F  clamp |y| to 63
L_F0B2:
    CALL SetLinePlotStart                      ; $F0B2: CD D6 F0  plot start: the clipped DE
    JP L_F130                                  ; $F0B5: C3 30 F1  pixel count from there
L_F0B8:
    LD A,E                                     ; $F0B8: 7B
    ADD A,C                                    ; $F0B9: 81
    LD E,A                                     ; $F0BA: 5F
    POP BC                                     ; $F0BB: C1
    JR L_F0A9                                  ; $F0BC: 18 EB

; VERIFIED: C = (MultiplyUnsigned(A,C) + $80) >> 8: A times the 8-bit fraction C, rounded.
; MultiplyUnsigned is exact when A+C is even. DE and HL preserved; A, B and flags changed.
; Used by the edge clipping (L_F042, L_F080) to move a coordinate by excess * slope.
; Evidence: a simulator check in tools/check_routines.py, 3000 random pairs.
ScaleByFraction:
    PUSH DE                                    ; $F0BE: D5
    PUSH HL                                    ; $F0BF: E5
    LD B,A                                     ; $F0C0: 47
    CALL MultiplyUnsigned                      ; $F0C1: CD 5D E4  HL = A*C (exact for even A+C)
    LD DE,$0080                                ; $F0C4: 11 80 00  round
    ADD HL,DE                                  ; $F0C7: 19
    LD C,H                                     ; $F0C8: 4C
    POP HL                                     ; $F0C9: E1
    POP DE                                     ; $F0CA: D1
    RET                                        ; $F0CB: C9

; VERIFIED: C = A*256/B (an 8-bit fraction) for A < B; $FF when A = B. Restoring division in
; DivideByteFraction with E = 0 and C = $FE as an 8-step sentinel. B and DE preserved.
; Used for the line slope (minor delta over major delta, ComputeLineDelta) and to convert
; a distance by a slope (L_F042, L_F080, L_F130).
; Evidence: a simulator check in tools/check_routines.py, 3000 random pairs with A <= B.
DivideToFractionC:
    LD C,$FE                                   ; $F0CC: 0E FE
    PUSH DE                                    ; $F0CE: D5
    LD E,$00                                   ; $F0CF: 1E 00
    CALL DivideByteFraction                    ; $F0D1: CD B4 E5
    POP DE                                     ; $F0D4: D1
    RET                                        ; $F0D5: C9

; VERIFIED: Convert the DE endpoint to its plot position in the alternate registers:
; x = 127+-D, y = 63+-E (left/below from B bits 1/0). HL' = ViewBitmapBuffer address,
; C' = pixel mask, E' = slope from C, B' = rows to the character-cell edge in the drawing
; direction (B bit 2 set, drawing up: (y AND 7)+1; clear: 8-(y AND 7)).  D' also holds
; the mask until L_EEAC replaces it with the pixel count.
; Returns in the main set with BC, DE and HL unchanged and A = B.
; Evidence: a simulator check in tools/check_routines.py, 3000 points.
SetLinePlotStart:
    PUSH BC                                    ; $F0D6: C5
    PUSH BC                                    ; $F0D7: C5
    PUSH DE                                    ; $F0D8: D5
    EXX                                        ; $F0D9: D9  B',C' = |x|,|y|; D',E' = flags, slope
    POP BC                                     ; $F0DA: C1
    POP DE                                     ; $F0DB: D1
    BIT 1,D                                    ; $F0DC: CB 4A
    JR NZ,L_F0E5                               ; $F0DE: 20 05
    LD A,$7F                                   ; $F0E0: 3E 7F  right: x = 127+|x|
    ADD A,B                                    ; $F0E2: 80
    JR L_F0E8                                  ; $F0E3: 18 03
L_F0E5:
    LD A,$7F                                   ; $F0E5: 3E 7F  left: x = 127-|x|
    SUB B                                      ; $F0E7: 90
L_F0E8:
    LD B,A                                     ; $F0E8: 47
    BIT 0,D                                    ; $F0E9: CB 42
    JR Z,L_F0F2                                ; $F0EB: 28 05
    LD A,$3F                                   ; $F0ED: 3E 3F  below: y = 63+|y|
    ADD A,C                                    ; $F0EF: 81
    JR L_F0F5                                  ; $F0F0: 18 03
L_F0F2:
    LD A,$3F                                   ; $F0F2: 3E 3F  above: y = 63-|y|
    SUB C                                      ; $F0F4: 91
L_F0F5:
    LD C,B                                     ; $F0F5: 48
    LD B,A                                     ; $F0F6: 47
    LD A,C                                     ; $F0F7: 79
    AND $07                                    ; $F0F8: E6 07
    LD D,B                                     ; $F0FA: 50
    LD B,A                                     ; $F0FB: 47
    INC B                                      ; $F0FC: 04
    LD A,$01                                   ; $F0FD: 3E 01  mask $80 >> (x AND 7)
L_F0FF:
    RRCA                                       ; $F0FF: 0F
    DJNZ L_F0FF                                ; $F100: 10 FD
    LD B,D                                     ; $F102: 42
    LD D,A                                     ; $F103: 57
    SRL C                                      ; $F104: CB 39
    SRL C                                      ; $F106: CB 39
    SRL C                                      ; $F108: CB 39
    LD A,B                                     ; $F10A: 78
    RRA                                        ; $F10B: 1F
    RRA                                        ; $F10C: 1F
    RRA                                        ; $F10D: 1F
    AND $18                                    ; $F10E: E6 18  y bits 6..7 and 0..2
    LD H,A                                     ; $F110: 67
    LD A,B                                     ; $F111: 78
    AND $07                                    ; $F112: E6 07
    OR H                                       ; $F114: B4
L_F115:
defc L_F116 = L_F115 + 1 ; byte inside instruction at $F115
    OR ViewBitmapBuffer >> 8                   ; $F115: F6 C0  buffer page (see DrawAiLaserBeam)
    LD H,A                                     ; $F117: 67
    LD A,B                                     ; $F118: 78
    AND $38                                    ; $F119: E6 38  y bits 3..5
    ADD A,A                                    ; $F11B: 87
    ADD A,A                                    ; $F11C: 87
    OR C                                       ; $F11D: B1
    LD L,A                                     ; $F11E: 6F
    LD A,H                                     ; $F11F: 7C
    AND $07                                    ; $F120: E6 07  up: (y AND 7)+1 rows
    INC A                                      ; $F122: 3C
    LD B,A                                     ; $F123: 47
    LD C,D                                     ; $F124: 4A
    POP AF                                     ; $F125: F1
    BIT 2,A                                    ; $F126: CB 57
    JR NZ,L_F12E                               ; $F128: 20 04
    LD A,$09                                   ; $F12A: 3E 09  down: 8-(y AND 7) rows
    SUB B                                      ; $F12C: 90
    LD B,A                                     ; $F12D: 47
L_F12E:
    EXX                                        ; $F12E: D9
    RET                                        ; $F12F: C9

; VERIFIED: Pixel count for a line that leaves the view.  Entered by JP after SetLinePlotStart has
; set the alternate registers for the start point; B/C = line flags/slope, DE = start.
; Take the view corner ahead in the drawing direction (magnitudes 128,64) and its delta
; and slope from the start (ComputeLineDelta). If the line is not steeper than that
; vector on its major axis (or the vector has the other major axis), count = major
; distance to the edge; otherwise count = (minor distance - 1) / slope (DivideToFractionC).
; Continue at L_EEAC with D/E = line flags/slope.
L_F130:
    PUSH BC                                    ; $F130: C5
    LD HL,$8040                                ; $F131: 21 40 80  view corner
    LD A,B                                     ; $F134: 78
    RRA                                        ; $F135: 1F
    RRA                                        ; $F136: 1F
    AND $03                                    ; $F137: E6 03
    SLA B                                      ; $F139: CB 20
    SLA B                                      ; $F13B: CB 20
    OR B                                       ; $F13D: B0
    XOR $03                                    ; $F13E: EE 03  corner ahead
    AND $0F                                    ; $F140: E6 0F
    LD B,A                                     ; $F142: 47
    CALL ComputeLineDelta                      ; $F143: CD 75 F1  H,L = distances to the corner
    POP DE                                     ; $F146: D1
    LD A,B                                     ; $F147: 78
    XOR D                                      ; $F148: AA
    AND $10                                    ; $F149: E6 10
    JR Z,L_F14F                                ; $F14B: 28 02
    LD C,$FF                                   ; $F14D: 0E FF  other major axis: slope $FF
L_F14F:
    BIT 4,D                                    ; $F14F: CB 62
    JR Z,L_F15F                                ; $F151: 28 0C
    LD A,E                                     ; $F153: 7B
    SUB C                                      ; $F154: 91
    LD A,H                                     ; $F155: 7C
    JP C,L_EEAC                                ; $F156: DA AC EE  count = x distance
    JP Z,L_EEAC                                ; $F159: CA AC EE
    LD A,L                                     ; $F15C: 7D
    JR L_F169                                  ; $F15D: 18 0A
L_F15F:
    LD A,E                                     ; $F15F: 7B
    SUB C                                      ; $F160: 91
    LD A,L                                     ; $F161: 7D
    JP C,L_EEAC                                ; $F162: DA AC EE  count = y distance
    JP Z,L_EEAC                                ; $F165: CA AC EE
    LD A,H                                     ; $F168: 7C
L_F169:
    LD B,E                                     ; $F169: 43  count = (distance-1)/slope
    AND A                                      ; $F16A: A7
    JR Z,L_F16E                                ; $F16B: 28 01
    DEC A                                      ; $F16D: 3D
L_F16E:
    CALL DivideToFractionC                     ; $F16E: CD CC F0
    LD A,C                                     ; $F171: 79
    JP L_EEAC                                  ; $F172: C3 AC EE  A = pixel count

; VERIFIED: Endpoint 1 = H,L and endpoint 2 = D,E magnitudes; B bits 0/1 = endpoint 1 below/left,
; bits 2/3 = endpoint 2 below/left. Returns H = |dx|, L = |dy| (low 8 bits),
; C = slope = minor*256/major (DivideToFractionC) and flags in B:
; bit 0/1 = endpoint 2 below/left, bit 2 = endpoint 2 lower than endpoint 1 (draw up),
; bit 3 = endpoint 2 left of endpoint 1 (draw right), bit 4 = x-major
; ((|dx|>>1) >= (|dy|>>1)), bit 5 = copy of bit 1, bits 6/7 = |dy|/|dx| above 255
; (the slope then uses halved deltas). DE preserved.
; The flags are built two bits higher and rotated into place at $F1D4/$F1D9.
; Evidence: a simulator check in tools/check_routines.py, 6000 random endpoint pairs.
ComputeLineDelta:
    LD A,B                                     ; $F175: 78
    SRL A                                      ; $F176: CB 3F
    SRL A                                      ; $F178: CB 3F
    XOR B                                      ; $F17A: A8
    ADD A,A                                    ; $F17B: 87  sign differences, ep2 signs
    ADD A,A                                    ; $F17C: 87
    ADD A,A                                    ; $F17D: 87
    ADD A,A                                    ; $F17E: 87
    OR B                                       ; $F17F: B0
    OR $03                                     ; $F180: F6 03
    LD B,A                                     ; $F182: 47
    RES 5,B                                    ; $F183: CB A8  draw right: bit 5 (ends as bit 3)
    AND $20                                    ; $F185: E6 20  x signs differ?
    LD A,D                                     ; $F187: 7A
    JR Z,L_F195                                ; $F188: 28 0B
    BIT 3,B                                    ; $F18A: CB 58
    JR Z,L_F190                                ; $F18C: 28 02
    SET 5,B                                    ; $F18E: CB E8  draw right
L_F190:
    ADD A,H                                    ; $F190: 84  |dx| = |x1|+|x2|, carry kept
    JR NC,L_F1A8                               ; $F191: 30 15
    JR L_F1AA                                  ; $F193: 18 15
L_F195:
    SUB H                                      ; $F195: 94  same x sign
    JR C,L_F1A0                                ; $F196: 38 08
    BIT 3,B                                    ; $F198: CB 58
    JR Z,L_F1A8                                ; $F19A: 28 0C
    SET 5,B                                    ; $F19C: CB E8  draw right
    JR L_F1A8                                  ; $F19E: 18 08
L_F1A0:
    NEG                                        ; $F1A0: ED 44
    BIT 3,B                                    ; $F1A2: CB 58
    JR NZ,L_F1A8                               ; $F1A4: 20 02
    SET 5,B                                    ; $F1A6: CB E8  draw right
L_F1A8:
    RES 1,B                                    ; $F1A8: CB 88  no |dx| overflow (bit 1, ends as 7)
L_F1AA:
    LD H,A                                     ; $F1AA: 67
    BIT 4,B                                    ; $F1AB: CB 60  y signs differ?
    LD A,E                                     ; $F1AD: 7B
    RES 4,B                                    ; $F1AE: CB A0  draw up: bit 4 (ends as bit 2)
    JR Z,L_F1BD                                ; $F1B0: 28 0B
    BIT 2,B                                    ; $F1B2: CB 50
    JR Z,L_F1B8                                ; $F1B4: 28 02
    SET 4,B                                    ; $F1B6: CB E0  draw up
L_F1B8:
    ADD A,L                                    ; $F1B8: 85  |dy| = |y1|+|y2|, carry kept
    JR NC,L_F1D0                               ; $F1B9: 30 15
    JR L_F1D2                                  ; $F1BB: 18 15
L_F1BD:
    SUB L                                      ; $F1BD: 95  same y sign
    JR C,L_F1C8                                ; $F1BE: 38 08
    BIT 2,B                                    ; $F1C0: CB 50
    JR Z,L_F1D0                                ; $F1C2: 28 0C
    SET 4,B                                    ; $F1C4: CB E0  draw up
    JR L_F1D0                                  ; $F1C6: 18 08
L_F1C8:
    NEG                                        ; $F1C8: ED 44
    BIT 2,B                                    ; $F1CA: CB 50
    JR NZ,L_F1D0                               ; $F1CC: 20 02
    SET 4,B                                    ; $F1CE: CB E0  draw up
L_F1D0:
    RES 0,B                                    ; $F1D0: CB 80  no |dy| overflow (bit 0, ends as 6)
L_F1D2:
    LD L,A                                     ; $F1D2: 6F
    LD C,L                                     ; $F1D3: 4D
    RRC B                                      ; $F1D4: CB 08  C = 9-bit |dy| / 2
    RR C                                       ; $F1D6: CB 19
    LD A,H                                     ; $F1D8: 7C
    RRC B                                      ; $F1D9: CB 08  A = 9-bit |dx| / 2
    RRA                                        ; $F1DB: 1F
    CP C                                       ; $F1DC: B9
    JR C,L_F1EA                                ; $F1DD: 38 0B
    SET 4,B                                    ; $F1DF: CB E0  x-major
    PUSH BC                                    ; $F1E1: C5
    BIT 7,B                                    ; $F1E2: CB 78  |dx| above 255?
    JR Z,L_F1F4                                ; $F1E4: 28 0E
    LD B,A                                     ; $F1E6: 47  halved deltas: dy/dx
    LD A,C                                     ; $F1E7: 79
    JR L_F1FA                                  ; $F1E8: 18 10
L_F1EA:
    RES 4,B                                    ; $F1EA: CB A0  y-major
    PUSH BC                                    ; $F1EC: C5
    BIT 6,B                                    ; $F1ED: CB 70  |dy| above 255?
    JR Z,L_F1F8                                ; $F1EF: 28 07
    LD B,C                                     ; $F1F1: 41  halved deltas: dx/dy
    JR L_F1FA                                  ; $F1F2: 18 06
L_F1F4:
    LD A,L                                     ; $F1F4: 7D  dy/dx
    LD B,H                                     ; $F1F5: 44
    JR L_F1FA                                  ; $F1F6: 18 02
L_F1F8:
    LD A,H                                     ; $F1F8: 7C  dx/dy
    LD B,L                                     ; $F1F9: 45
L_F1FA:
    CALL DivideToFractionC                     ; $F1FA: CD CC F0  slope = minor*256/major
    LD A,C                                     ; $F1FD: 79
    POP BC                                     ; $F1FE: C1
    LD C,A                                     ; $F1FF: 4F
    RET                                        ; $F200: C9

; VERIFIED: One pixel row up inside the character cell (DEC H), then plot (PlotSteepLineUp).
SteepUpNextRow:
    DEC H                                      ; $F201: 25  next row up

; VERIFIED: Y-major plotting loop drawing upwards, in the alternate registers:
; HL = buffer address, C = pixel mask, D = pixels left, E = error accumulator,
; B = rows left in the character cell. Plot (SteepUpPlotOp), return (RET Z) when D reaches
; zero, add the slope (SteepUpSlope) to E; on carry rotate the mask one pixel along x
; (SteepUpMaskRotate) and step a byte when it wraps (SteepUpByteStep); then one row up
; (SteepUpNextRow, or the cell change at L_F211).
; The plot op is patched by L_DA33, the other three bytes by the octant code at L_EEAC.
PlotSteepLineUp:
    LD A,(HL)                                  ; $F202: 7E
SteepUpPlotOp:
    OR C                                       ; $F203: B1  patched: OR C, or XOR C (L_DA33)
    LD (HL),A                                  ; $F204: 77
    DEC D                                      ; $F205: 15
    RET Z                                      ; $F206: C8
    LD A,E                                     ; $F207: 7B
L_F208:
defc SteepUpSlope = L_F208 + 1 ; byte inside instruction at $F208
    ADD A,$00                                  ; $F208: C6 00  patched slope
    LD E,A                                     ; $F20A: 5F
    JR NC,L_F211                               ; $F20B: 30 04  no carry: same column
L_F20D:
defc SteepUpMaskRotate = L_F20D + 1 ; byte inside instruction at $F20D
    RRC C                                      ; $F20D: CB 09  patched: RRC C right / RLC C left
    JR C,SteepUpByteStep                       ; $F20F: 38 13  mask wrapped: next byte

; VERIFIED: Count the row just plotted.  At the top of the character cell (B = 0) move to the bottom
; row of the character row above: H+7, L-32, and H-8 more when L borrows (third boundary).
L_F211:
    DJNZ SteepUpNextRow                        ; $F211: 10 EE  rows left in the cell
    LD B,$08                                   ; $F213: 06 08
    LD A,H                                     ; $F215: 7C
    ADD A,$07                                  ; $F216: C6 07  bottom row of the cell above
    LD H,A                                     ; $F218: 67
    LD A,L                                     ; $F219: 7D
    SUB $20                                    ; $F21A: D6 20  previous character row
    LD L,A                                     ; $F21C: 6F
    JR NC,PlotSteepLineUp                      ; $F21D: 30 E3  same third
    LD A,H                                     ; $F21F: 7C  crossed a third: H-8
    SUB B                                      ; $F220: 90
    LD H,A                                     ; $F221: 67
    JR PlotSteepLineUp                         ; $F222: 18 DE
SteepUpByteStep:
    INC L                                      ; $F224: 2C  patched: INC L right / DEC L left
    JP L_F211                                  ; $F225: C3 11 F2

; VERIFIED: The pixel mask wrapped past a byte edge: step the buffer address one byte along x
; (patched INC L / DEC L), then plot (PlotShallowLineUp).
ShallowUpByteStep:
    INC L                                      ; $F228: 2C  patched: INC L right / DEC L left
    JP PlotShallowLineUp                       ; $F229: C3 30 F2

; VERIFIED: Next pixel of PlotShallowLineUp: rotate the mask one pixel along x (patched RRC C /
; RLC C); carry means a byte edge (ShallowUpByteStep).
ShallowUpStepX:
defc ShallowUpMaskRotate = ShallowUpStepX + 1 ; byte inside instruction at $F22C
    RRC C                                      ; $F22C: CB 09  patched: RRC C right / RLC C left
    JR C,ShallowUpByteStep                     ; $F22E: 38 F8  mask wrapped: next byte

; VERIFIED: X-major plotting loop: one x step per pixel (ShallowUpStepX), one row up (DEC H) on
; accumulator carry. Registers as in PlotSteepLineUp.
; Self-modified: ShallowUpPlotOp, ShallowUpSlope, ShallowUpMaskRotate, ShallowUpByteStep.
PlotShallowLineUp:
    LD A,(HL)                                  ; $F230: 7E
ShallowUpPlotOp:
    OR C                                       ; $F231: B1  patched: OR C, or XOR C (L_DA33)
    LD (HL),A                                  ; $F232: 77
    DEC D                                      ; $F233: 15
    RET Z                                      ; $F234: C8
    LD A,E                                     ; $F235: 7B
L_F236:
defc ShallowUpSlope = L_F236 + 1 ; byte inside instruction at $F236
    ADD A,$00                                  ; $F236: C6 00  patched slope
    LD E,A                                     ; $F238: 5F
    JR NC,ShallowUpStepX                       ; $F239: 30 F1  no carry: same row
    DEC H                                      ; $F23B: 25  carry: one row up
    DJNZ ShallowUpStepX                        ; $F23C: 10 EE  still inside the cell
    LD B,$08                                   ; $F23E: 06 08
    LD A,H                                     ; $F240: 7C
    ADD A,B                                    ; $F241: 80  undo the borrow of DEC H: H+8
    LD H,A                                     ; $F242: 67
    LD A,L                                     ; $F243: 7D
    SUB $20                                    ; $F244: D6 20  previous character row
    LD L,A                                     ; $F246: 6F
    JP NC,ShallowUpStepX                       ; $F247: D2 2C F2  same third
    LD A,H                                     ; $F24A: 7C  crossed a third: H-8
    SUB B                                      ; $F24B: 90
    LD H,A                                     ; $F24C: 67
    JP ShallowUpStepX                          ; $F24D: C3 2C F2

; VERIFIED: One pixel row down inside the character cell (INC H), then plot (PlotSteepLineDown).
SteepDownNextRow:
    INC H                                      ; $F250: 24  next row down

; VERIFIED: Y-major plotting loop drawing downwards (SteepDownNextRow). Registers as in
; PlotSteepLineUp.  Self-modified: SteepDownPlotOp, SteepDownSlope, SteepDownMaskRotate,
; SteepDownByteStep.
PlotSteepLineDown:
    LD A,(HL)                                  ; $F251: 7E
SteepDownPlotOp:
    OR C                                       ; $F252: B1  patched: OR C, or XOR C (L_DA33)
    LD (HL),A                                  ; $F253: 77
    DEC D                                      ; $F254: 15
    RET Z                                      ; $F255: C8
    LD A,E                                     ; $F256: 7B
L_F257:
defc SteepDownSlope = L_F257 + 1 ; byte inside instruction at $F257
    ADD A,$00                                  ; $F257: C6 00  patched slope
    LD E,A                                     ; $F259: 5F
    JR NC,L_F260                               ; $F25A: 30 04  no carry: same column
L_F25C:
defc SteepDownMaskRotate = L_F25C + 1 ; byte inside instruction at $F25C
    RRC C                                      ; $F25C: CB 09  patched: RRC C right / RLC C left
    JR C,SteepDownByteStep                     ; $F25E: 38 15  mask wrapped: next byte

; VERIFIED: Count the row just plotted.  At the bottom of the character cell (B = 0) move to the top
; row of the next character row: H-7, L+32, and H+8 more when L carries (third boundary).
L_F260:
    DJNZ SteepDownNextRow                      ; $F260: 10 EE  rows left in the cell
    LD B,$08                                   ; $F262: 06 08  next character row:
    LD A,H                                     ; $F264: 7C
    SUB $07                                    ; $F265: D6 07  H-7: its top row
    LD H,A                                     ; $F267: 67
    LD A,L                                     ; $F268: 7D
    ADD A,$20                                  ; $F269: C6 20  L+32
    LD L,A                                     ; $F26B: 6F
    JP NC,PlotSteepLineDown                    ; $F26C: D2 51 F2  same third
    LD A,H                                     ; $F26F: 7C  crossed a third: H+8
    ADD A,B                                    ; $F270: 80
    LD H,A                                     ; $F271: 67
    JP PlotSteepLineDown                       ; $F272: C3 51 F2
SteepDownByteStep:
    INC L                                      ; $F275: 2C  patched: INC L right / DEC L left
    JP L_F260                                  ; $F276: C3 60 F2

; VERIFIED: Next pixel of PlotShallowLineDown: rotate the mask one pixel along x (patched RRC C /
; RLC C); carry means a byte edge (ShallowDownByteStep).
ShallowDownStepX:
defc ShallowDownMaskRotate = ShallowDownStepX + 1 ; byte inside instruction at $F279
    RRC C                                      ; $F279: CB 09  patched: RRC C right / RLC C left
    JR C,ShallowDownByteStep                   ; $F27B: 38 20  mask wrapped: next byte

; VERIFIED: X-major plotting loop: one x step per pixel (ShallowDownStepX), one row down (INC H) on
; accumulator carry.  Self-modified: ShallowDownPlotOp, ShallowDownSlope,
; ShallowDownMaskRotate, ShallowDownByteStep.
PlotShallowLineDown:
    LD A,(HL)                                  ; $F27D: 7E
ShallowDownPlotOp:
    OR C                                       ; $F27E: B1  patched: OR C, or XOR C (L_DA33)
    LD (HL),A                                  ; $F27F: 77
    DEC D                                      ; $F280: 15
    RET Z                                      ; $F281: C8
    LD A,E                                     ; $F282: 7B
L_F283:
defc ShallowDownSlope = L_F283 + 1 ; byte inside instruction at $F283
    ADD A,$00                                  ; $F283: C6 00  patched slope
    LD E,A                                     ; $F285: 5F
    JR NC,ShallowDownStepX                     ; $F286: 30 F1  no carry: same row
    INC H                                      ; $F288: 24  carry: one row down
    DJNZ ShallowDownStepX                      ; $F289: 10 EE  still inside the cell
    LD B,$08                                   ; $F28B: 06 08
    LD A,H                                     ; $F28D: 7C
    SUB B                                      ; $F28E: 90  undo the carry of INC H: H-8
    LD H,A                                     ; $F28F: 67
    LD A,L                                     ; $F290: 7D
    ADD A,$20                                  ; $F291: C6 20  next character row
    LD L,A                                     ; $F293: 6F
    JP NC,ShallowDownStepX                     ; $F294: D2 79 F2  same third
    LD A,H                                     ; $F297: 7C  crossed a third: H+8
    ADD A,B                                    ; $F298: 80
    LD H,A                                     ; $F299: 67
    JP ShallowDownStepX                        ; $F29A: C3 79 F2
ShallowDownByteStep:
    INC L                                      ; $F29D: 2C  patched: INC L right / DEC L left
    JP PlotShallowLineDown                     ; $F29E: C3 7D F2

; ============================================================================
; Ship instance template, event dispatch and slot allocation
; Default instance bytes, DispatchShipEvent, blueprint initialisation and free-slot search.
; ============================================================================

; VERIFIED: 31-byte default instance image (InstanceTemplateSize), copied by
; InitialiseShipFromBlueprint (LDIR at $F31E) over instance bytes +$00..+$1E before the
; blueprint fields are set.
; InstanceX/Y/Z = +$3200 each; the loader then randomises x and y, z stays +$3200
; unless the caller moves it.
; Axes in sign-magnitude words ($7FFF = +1, $FFFF = -1): InstanceAxisZ = (0,0,-1),
; InstanceAxisY = (0,+1,0), InstanceAxisX = (-1,0,0), so a new ship's forward axis points
; back at the player.  +$1B..+$1E are zero (the speed is set later).
; L_F3B3 clears bit 7 of +$0E/+$16 to turn the two -1 entries into +1.
; Evidence: Instance* field formats (objects); objects/r10-ship-creation.
ShipInstanceTemplate:
    defb $00,$32,$00                                                                      ; $F2A1 .2.  +$00: x = +$3200 (low, high, sign)
    defb $00,$32,$00                                                                      ; $F2A4 .2.  +$03: y = +$3200
    defb $00,$32,$00                                                                      ; $F2A7 .2.  +$06: z = +$3200
    defb $00,$00,$00,$00,$FF,$FF                                                          ; $F2AA ......  +$09: z axis = (0, 0, -1), $7FFF = 1.0
    defb $00,$00,$FF,$7F,$00,$00                                                          ; $F2B0 ......  +$0F: y axis = (0, +1, 0)
    defb $FF,$FF,$00,$00,$00,$00                                                          ; $F2B6 ......  +$15: x axis = (-1, 0, 0)
    defb $00,$00,$00,$00                                                                  ; $F2BC ....  +$1B..+$1E

; VERIFIED: Nine bytes copied by L_F616 (event 9, SetUpDisplayShip) to instance +$0A,+$0C,...,+$1A
; of slot 7: the sign-magnitude high bytes of InstanceAxisZ, InstanceAxisY and
; InstanceAxisX (the low bytes stay from the template).
; The rows have length 1.00..1.02 ($7F = 1), are orthogonal within 0.012 and X = Y x Z:
; a proper rotation, the fixed tilt of the slot-7 display ship (RunTitleScreen
; dispatches event $79, ship ID 9).
; Evidence: objects/r10-ship-creation.
ObjectSlot7OrientationBytes:
    defb $58,$44,$41,$98,$64,$CB,$5A,$A7,$D1                                              ; $F2C0 XDA.d.Z..  +$0A,+$0C,...,+$1A

; VERIFIED: Bit 0 toggled by AdjustChildLaunchOrientation on every non-station child launch; the
; new value selects the three-swap path (1) or the single swap at L_F4BB (0).
ChildLaunchOrientationToggle:
    defb $00                                                                              ; $F2C9 .

; VERIFIED: Dispatch A: low nibble selects an event, high nibble becomes its count/subtype in C.
; Verified cases: 0=random encounter, 1=Thargoid group, 2=missile, 4=parent launch.
; The low-nibble AND clears carry; the subsequent DEC chain preserves that carry.
; VERIFIED: C (the event high nibble) per handler: 0 unused (SpawnRandomEncounter overwrites it),
; 1 unused (SpawnThargoidGroup sets its count), 2 missile target code (0 = AI missile at
; IX), 4 launch subtype, 5/6 even = at the parent IX, odd = near the player, 7 even =
; escape capsule from IX, odd = the player's abandoned Cobra, 8 unused, 9 ship ID - 2 for
; slot 7.  Events 3 and 10..15 return at once.  Laser-kill debris (L_ECD1) uses C = 0.
DispatchShipEvent:
    LD C,A                                     ; $F2CA: 4F  C = high nibble
    SRL C                                      ; $F2CB: CB 39
    SRL C                                      ; $F2CD: CB 39
    SRL C                                      ; $F2CF: CB 39
    SRL C                                      ; $F2D1: CB 39
    AND $0F                                    ; $F2D3: E6 0F
    JP Z,SpawnRandomEncounter                  ; $F2D5: CA 1D F6  event 0
    DEC A                                      ; $F2D8: 3D
    JP Z,SpawnThargoidGroup                    ; $F2D9: CA CE F3  event 1
    DEC A                                      ; $F2DC: 3D
    JP Z,LaunchMissile                         ; $F2DD: CA 02 F4  event 2: missile
    DEC A                                      ; $F2E0: 3D
    RET Z                                      ; $F2E1: C8  event 3: none
    DEC A                                      ; $F2E2: 3D
    JP Z,SelectParentLaunchType                ; $F2E3: CA 4A F4  event 4
    DEC A                                      ; $F2E6: 3D
    JP Z,SpawnAlloyPlatePair                   ; $F2E7: CA F7 F4  event 5: two Alloy plates
    DEC A                                      ; $F2EA: 3D
    JP Z,SpawnCargoCanister                    ; $F2EB: CA 55 F5  event 6: Cargo canister
    DEC A                                      ; $F2EE: 3D
    JP Z,HandleEscapeCapsuleEvent              ; $F2EF: CA 5D F5  event 7: capsule (C even)
    DEC A                                      ; $F2F2: 3D
    JP Z,SpawnSplinterPair                     ; $F2F3: CA B0 F5  event 8: two Splinters
    DEC A                                      ; $F2F6: 3D
    JP Z,SetUpDisplayShip                      ; $F2F7: CA D8 F5  event 9: slot-7 ship C+2
    RET                                        ; $F2FA: C9  events 10..15: none

; VERIFIED: A supplies the ship ID in its low six bits; IX points to an already selected instance.
; Resolve the blueprint table, return its pointer in IY, and store it at IX+$23/$24.
; Copy instance defaults, then set energy, behaviour, payload count and half maximum speed.
; Blueprint byte +$12 AND $6F becomes instance +$21: bit 1 is legal-sensitive, bit 2 hostile.
; Fer-de-Lance starts with $02; Viper with $42. Neither starts hostile from its blueprint.
; Initial coordinates use the RNG. Parent launches overwrite the first 27 bytes afterwards.
; ship=adder uses compact two-byte pointers and replaces only blueprint slot 17.
; VERIFIED: Details: +$20 = blueprint +$0A bits 0..2 (payload count) + blueprint +$12 bit 7 + bit 6
; (counted); +$25 = $7E (AI threshold, no ECM, not fleeing); +$26 = 0.  Position: x and y
; low bytes and both signs are random; their high bytes are random 0..7 for a calm ship
; and keep the template $32 when +$21 bit 2 (hostile) is set; z stays +$3200.  Uses three
; or five NextRandomByte values.  Returns A = 0 with Z set; IX unchanged, BC/DE/HL changed.
; Evidence: objects/r10-ship-creation (all 19 blueprint IDs).
InitialiseShipFromBlueprint:
    LD HL,ShipBlueprintsAndDispatchTables      ; $F2FB: 21 80 61
    LD B,A                                     ; $F2FE: 47
    AND $3F                                    ; $F2FF: E6 3F  six-bit blueprint ID
    ADD A,A                                    ; $F301: 87
IF SHIP_ADDER
    NOP ; compact two-byte blueprint pointers
ELSE
    ADD A,A                                    ; $F302: 87
ENDIF
    ADD A,L                                    ; $F303: 85
    LD L,A                                     ; $F304: 6F
    JR NC,L_F308                               ; $F305: 30 01
    INC H                                      ; $F307: 24
L_F308:
IF SHIP_ADDER
    NOP ; compact two-byte blueprint pointers
ELSE
    INC HL                                     ; $F308: 23
ENDIF
    LD E,(HL)                                  ; $F309: 5E
    INC HL                                     ; $F30A: 23
    LD D,(HL)                                  ; $F30B: 56
    PUSH DE                                    ; $F30C: D5  IY = blueprint
    POP IY                                     ; $F30D: FD E1
    LD (IX+$24),D                              ; $F30F: DD 72 24
    LD (IX+$23),E                              ; $F312: DD 73 23
    PUSH IX                                    ; $F315: DD E5
    POP DE                                     ; $F317: D1
    LD BC,ObjectSlot7OrientationBytes-ShipInstanceTemplate ; $F318: 01 1F 00  template size
    LD HL,ShipInstanceTemplate                 ; $F31B: 21 A1 F2
    LDIR                                       ; $F31E: ED B0
    LD A,(IY+$07)                              ; $F320: FD 7E 07  energy
    LD (IX+$22),A                              ; $F323: DD 77 22
    LD A,(IY+$12)                              ; $F326: FD 7E 12  behaviour = +$12 AND $6F
    LD C,A                                     ; $F329: 4F
    AND $6F                                    ; $F32A: E6 6F
    LD (IX+$21),A                              ; $F32C: DD 77 21
    LD A,(IY+$0A)                              ; $F32F: FD 7E 0A  payload count, +$12 bit 7
    AND $07                                    ; $F332: E6 07
    RLA                                        ; $F334: 17
    RL C                                       ; $F335: CB 11
    RRA                                        ; $F337: 1F
    LD (IX+$20),A                              ; $F338: DD 77 20
    LD A,(IY+$06)                              ; $F33B: FD 7E 06  speed = maximum / 2
    SRL A                                      ; $F33E: CB 3F
    LD (IX+$1B),A                              ; $F340: DD 77 1B
    LD A,$7E                                   ; $F343: 3E 7E  +$25 = $7E: AI threshold
    LD (IX+$25),A                              ; $F345: DD 77 25
    XOR A                                      ; $F348: AF
    LD (IX+$26),A                              ; $F349: DD 77 26  +$26 = 0: no role flags
    SET 6,(IX+$20)                             ; $F34C: DD CB 20 F6  counted by EncounterShipCount
    BIT 2,(IX+$21)                             ; $F350: DD CB 21 56  hostile: keep high bytes $32
    JR NZ,L_F366                               ; $F354: 20 10
    CALL NextRandomByte                        ; $F356: CD 24 ED  calm: high bytes 0..7
    AND $07                                    ; $F359: E6 07
    LD (IX+$01),A                              ; $F35B: DD 77 01  x high byte
    CALL NextRandomByte                        ; $F35E: CD 24 ED
    AND $07                                    ; $F361: E6 07
    LD (IX+$04),A                              ; $F363: DD 77 04  y high byte
L_F366:
    CALL NextRandomByte                        ; $F366: CD 24 ED  random low bytes
    LD (IX+$00),A                              ; $F369: DD 77 00  x low byte
    CALL NextRandomByte                        ; $F36C: CD 24 ED
    LD (IX+$03),A                              ; $F36F: DD 77 03  y low byte
    CALL NextRandomByte                        ; $F372: CD 24 ED  random signs
    RRA                                        ; $F375: 1F
    RR (IX+$02)                                ; $F376: DD CB 02 1E  x sign
    RRA                                        ; $F37A: 1F
    RR (IX+$05)                                ; $F37B: DD CB 05 1E  y sign
    XOR A                                      ; $F37F: AF  A = 0, Z set
    RET                                        ; $F380: C9

; VERIFIED: A=child ship ID, IX=parent. Allocate and initialise a child, then copy parent bytes 0..26.
; Those bytes hold position and orientation; the child keeps its own blueprint and energy.
; On success IX points to the child and Z is set. NZ means no free slot.
; VERIFIED: The 27 copied bytes are InstanceX/Y/Z and the three axes; speed +$1B is not copied, so
; the child starts at half its own maximum speed (callers adjust it).
; Success: BC = 0, A = 0.  Failure (NZ): HL = the parent, but IX is left at slot 6 by
; FindFreeShipSlot.
; Evidence: objects/r10-ship-creation.
CreateShipAtParent:
    LD C,A                                     ; $F381: 4F
    PUSH IX                                    ; $F382: DD E5
    CALL FindFreeShipSlot                      ; $F384: CD 99 F3
    POP HL                                     ; $F387: E1  HL = parent
    RET NZ                                     ; $F388: C0  no slot: IX = slot 6
    PUSH HL                                    ; $F389: E5
    LD A,C                                     ; $F38A: 79
    CALL InitialiseShipFromBlueprint           ; $F38B: CD FB F2
    POP HL                                     ; $F38E: E1
    PUSH IX                                    ; $F38F: DD E5
    POP DE                                     ; $F391: D1
    LD BC,$001B                                ; $F392: 01 1B 00  parent +$00..+$1A
    LDIR                                       ; $F395: ED B0
    XOR A                                      ; $F397: AF  Z, A = 0 (BC = 0)
    RET                                        ; $F398: C9

; VERIFIED: Scan six 39-byte instances after persistent station slot zero.
; Energy at instance+$22 equal to zero marks a free slot. C is preserved.
; Return Z with IX pointing at the free instance, or NZ if all six are occupied.
; VERIFIED: Outputs: Z with IX = the first free slot (1..6) and A = 0; NZ with IX = slot 6, B = 1
; and A = its energy.  DE = InstanceSize in both cases; HL and IY are preserved as well.
; Evidence: objects/r10-ship-creation.
FindFreeShipSlot:
    LD IX,InitialRuntimeState                  ; $F399: DD 21 48 60  first ADD selects slot 1
    LD DE,$0027                                ; $F39D: 11 27 00  instance size
    LD B,$06                                   ; $F3A0: 06 06  six allocatable slots
L_F3A2:
    ADD IX,DE                                  ; $F3A2: DD 19
    LD A,(IX+$22)                              ; $F3A4: DD 7E 22  zero energy: free
    AND A                                      ; $F3A7: A7
    RET Z                                      ; $F3A8: C8
    DJNZ L_F3A2                                ; $F3A9: 10 F7
    INC B                                      ; $F3AB: 04  NZ: no free slot
    RET                                        ; $F3AC: C9

; VERIFIED: A = ship ID: allocate a slot (FindFreeShipSlot; NZ: none free, IX = slot 6), then
; L_F3B3.  Called by SpawnObjectNearPlayer, which then moves the object to a random
; nearby offset.
L_F3AD:
    LD C,A                                     ; $F3AD: 4F
    CALL FindFreeShipSlot                      ; $F3AE: CD 99 F3
    RET NZ                                     ; $F3B1: C0
    LD A,C                                     ; $F3B2: 79

; VERIFIED: Initialise ship A in slot IX (InitialiseShipFromBlueprint), clear bit 7 of +$0E and
; +$16, then zero +$00, +$01, +$04, +$06 and +$07 (A = 0 from the loader; returns Z).
; Result: identity orientation (all three axes +1, like the player's ship) at the player's
; position x = z = 0, except a random y low byte (0..255) and random x/y signs.  Callers
; then set the final position: the player missile (slot 7, L_F419), the abandoned Cobra
; (HandleEscapeCapsuleEvent) and debris near the player (SpawnObjectNearPlayer).
; Evidence: objects/r10-ship-creation.
L_F3B3:
    CALL InitialiseShipFromBlueprint           ; $F3B3: CD FB F2
    RES 7,(IX+$0E)                             ; $F3B6: DD CB 0E BE  z and x axes: -1 -> +1
    RES 7,(IX+$16)                             ; $F3BA: DD CB 16 BE
    LD (IX+$00),A                              ; $F3BE: DD 77 00  A = 0
    LD (IX+$01),A                              ; $F3C1: DD 77 01
    LD (IX+$04),A                              ; $F3C4: DD 77 04
    LD (IX+$06),A                              ; $F3C7: DD 77 06
    LD (IX+$07),A                              ; $F3CA: DD 77 07
    RET                                        ; $F3CD: C9

; VERIFIED: Event 1: create 3 or 4 Thargoids (ID 15; count = 3 + one random bit), stopping early
; when no slot is free.  Each gets +$25 bit 0 (ECM fitted), z high byte +$07 = random 0..15
; with bit 2 forced (4..7 or 12..15), x high byte +$01 = bit 3 of that value and y high
; byte +$04 = 0 (low bytes and signs random from the loader); then L_F4E6 randomises the
; high bytes +$0A/+$0C.  Returns Z when all were created, NZ when the slots ran out (C =
; Thargoids still missing).  Evidence: objects/r10-ship-creation.
SpawnThargoidGroup:
    CALL NextRandomByte                        ; $F3CE: CD 24 ED
    AND $01                                    ; $F3D1: E6 01
    ADD A,$03                                  ; $F3D3: C6 03  3 or 4 Thargoids
    LD C,A                                     ; $F3D5: 4F
L_F3D6:
    CALL FindFreeShipSlot                      ; $F3D6: CD 99 F3
    RET NZ                                     ; $F3D9: C0
    LD A,$0F                                   ; $F3DA: 3E 0F  Thargoid
    PUSH BC                                    ; $F3DC: C5
    CALL InitialiseShipFromBlueprint           ; $F3DD: CD FB F2
    SET 0,(IX+$25)                             ; $F3E0: DD CB 25 C6  +$25 bit 0: ECM fitted
    CALL NextRandomByte                        ; $F3E4: CD 24 ED
    AND $0F                                    ; $F3E7: E6 0F
    OR $04                                     ; $F3E9: F6 04  +$07 = 4..7 or 12..15
    LD (IX+$07),A                              ; $F3EB: DD 77 07
    RRA                                        ; $F3EE: 1F
    RRA                                        ; $F3EF: 1F
    RRA                                        ; $F3F0: 1F
    AND $01                                    ; $F3F1: E6 01  +$01 = bit 3
    LD (IX+$01),A                              ; $F3F3: DD 77 01
    XOR A                                      ; $F3F6: AF
    LD (IX+$04),A                              ; $F3F7: DD 77 04  +$04 = 0
    CALL L_F4E6                                ; $F3FA: CD E6 F4  random +$0A/+$0C high bytes
    POP BC                                     ; $F3FD: C1
    DEC C                                      ; $F3FE: 0D  next Thargoid
    JR NZ,L_F3D6                               ; $F3FF: 20 D5
    RET                                        ; $F401: C9

; ============================================================================
; Ship event handlers
; Targets of DispatchShipEvent: event 2 missile, 5..9 debris, canisters,
; escape capsule, splinters and the display ship.
; ============================================================================

; VERIFIED: Event 2: create a Missile (blueprint ID 1); C = high nibble of the event = target code.
; C = 0 (AI launch, event $02 from TryLaunchAiPayload): a child of the parent IX through
; CreateShipAtParent (position and orientation copied, not the speed), then speed +$1B +=
; PlayerSpeed.  The LDIR in CreateShipAtParent leaves C = 0, so the target stays the player.
; C <> 0 (player launch at $A760, event C*16+2): slot 7 (ObjectSlot7), or any free slot 1..6
; when slot 7 is busy; L_F3B3 clears the position bytes, then y = -$29 and z = +$6A.
; Both: instance +$25 = C, set +$26 bit 0 (missile flag).
; Out: Z and IX = the missile on success; NZ if no slot was free.
LaunchMissile:
    LD A,C                                     ; $F402: 79
    AND A                                      ; $F403: A7
    JR Z,L_F432                                ; $F404: 28 2C  C = 0: AI missile from the parent
    LD IX,InitialRuntimeState                  ; $F406: DD 21 48 60  slot array base
    LD DE,7*InstanceSize                       ; $F40A: 11 11 01  offset of slot 7, the player missile slot
    ADD IX,DE                                  ; $F40D: DD 19
    LD A,(IX+$22)                              ; $F40F: DD 7E 22  slot 7 energy: nonzero = occupied
    AND A                                      ; $F412: A7
    JR Z,L_F419                                ; $F413: 28 04  slot 7 free: use it
    CALL FindFreeShipSlot                      ; $F415: CD 99 F3  slot 7 busy: any free slot 1..6
    RET NZ                                     ; $F418: C0
L_F419:
    LD A,$01                                   ; $F419: 3E 01  blueprint 1: Missile
    PUSH BC                                    ; $F41B: C5  keep the target code
    CALL L_F3B3                                ; $F41C: CD B3 F3  create it with zero position bytes
    POP BC                                     ; $F41F: C1
    LD A,$6A                                   ; $F420: 3E 6A  z = +$6A: just ahead of the player
    LD (IX+$06),A                              ; $F422: DD 77 06
    LD A,$29                                   ; $F425: 3E 29  y = -$29 (sign set below)
    LD (IX+$03),A                              ; $F427: DD 77 03
    LD A,$80                                   ; $F42A: 3E 80
    LD (IX+$05),A                              ; $F42C: DD 77 05  y sign: negative
    LD A,C                                     ; $F42F: 79  A = target code
    JR L_F441                                  ; $F430: 18 0F
L_F432:
    LD A,$01                                   ; $F432: 3E 01  blueprint 1: Missile
    CALL CreateShipAtParent                    ; $F434: CD 81 F3  copy the parent position/orientation; IX = missile, BC = 0
    RET NZ                                     ; $F437: C0  NZ: no free slot
    LD A,(PlayerSpeed)                         ; $F438: 3A 44 70  add the player speed
    ADD A,(IX+$1B)                             ; $F43B: DD 86 1B  to the blueprint cruising speed
    LD (IX+$1B),A                              ; $F43E: DD 77 1B
L_F441:
    LD (IX+$25),C                              ; $F441: DD 71 25  target code (0 = the player; C = 0 after the LDIR)
    SET 0,(IX+$26)                             ; $F444: DD CB 26 C6  instance +$26 bit 0: missile flag
    XOR A                                      ; $F448: AF  Z: success
    RET                                        ; $F449: C9

; VERIFIED: IX=parent, C=launch subtype: 1 Viper, 2 Cobra/Python trader, 3 Thargon,
; 4 Thargoid, 5 Sidewinder/Krait (Adder instead of Krait with ship=adder).
; Viper selection bypasses the RNG; all valid choices continue at LaunchSelectedShip.
; The original subtype-2 RNG is correlated with the preceding station gate and always
; chooses Python there. stationrandomlaunchfix=yes repairs the choice in the same 38 bytes.
; VERIFIED: C = 0 or C > 5: return NZ without creating a ship.  Every C >= 2 calls NextRandomByte
; before the subtype is tested (subtype 5 calls it twice); the Viper path never does.
SelectParentLaunchType:
IF STATION_RANDOM_LAUNCH_FIX
    INCLUDE "station-random-launch-fix.asm"
ELSE
    LD A,$08                                   ; $F44A: 3E 08  $08: Viper
    DEC C                                      ; $F44C: 0D
    JR Z,LaunchSelectedShip                    ; $F44D: 28 21  subtype 1: Viper, no RNG call
    CALL NextRandomByte                        ; $F44F: CD 24 ED  every subtype >= 2 advances the RNG here
    AND $01                                    ; $F452: E6 01
    ADD A,$09                                  ; $F454: C6 09  $09/$0A: Cobra or Python trader
    DEC C                                      ; $F456: 0D
    JR Z,LaunchSelectedShip                    ; $F457: 28 17  subtype 2: trader
    LD A,$12                                   ; $F459: 3E 12  $12: Thargon
    DEC C                                      ; $F45B: 0D
    JR Z,LaunchSelectedShip                    ; $F45C: 28 12  subtype 3
    LD A,$0F                                   ; $F45E: 3E 0F  $0F: Thargoid
    DEC C                                      ; $F460: 0D
    JR Z,LaunchSelectedShip                    ; $F461: 28 0D  subtype 4
    DEC C                                      ; $F463: 0D
    RET NZ                                     ; $F464: C0  C = 0 or > 5: nothing created (NZ)
    CALL NextRandomByte                        ; $F465: CD 24 ED  subtype 5: second RNG call
    BIT 0,A                                    ; $F468: CB 47
    LD A,$10                                   ; $F46A: 3E 10  $10: Sidewinder
    JR Z,LaunchSelectedShip                    ; $F46C: 28 02  random bit 0 clear: Sidewinder
    LD A,$11                                   ; $F46E: 3E 11  $11: Krait (Adder with ship=adder)
ENDIF

; VERIFIED: A=selected child type, IX=parent. Create the child at its parent position/orientation.
; Adjust launch orientation only for a non-station parent, then inherit parent hostility.
; On success IX=child, IY=parent and Z is set; NZ reports allocation failure.
LaunchSelectedShip:
    assert SelectParentLaunchType-GameImage = ParentLaunchSelectionStart-$6048
    assert LaunchSelectedShip-GameImage = ParentLaunchSelectionLimit-$6048
    PUSH IX                                    ; $F470: DD E5  keep the parent
    CALL CreateShipAtParent                    ; $F472: CD 81 F3  child at the parent position/orientation
    POP IY                                     ; $F475: FD E1  IY = parent
    RET NZ                                     ; $F477: C0
    BIT 2,(IY+$26)                             ; $F478: FD CB 26 56  parent +$26 bit 2: a station
    CALL Z,AdjustChildLaunchOrientation        ; $F47C: CC 8A F4  turn the child unless a station launched it
    BIT 2,(IY+$21)                             ; $F47F: FD CB 21 56  parent hostile?
    RET Z                                      ; $F483: C8
    SET 2,(IX+$21)                             ; $F484: DD CB 21 D6  the child inherits the hostility bit
    XOR A                                      ; $F488: AF  Z: success
    RET                                        ; $F489: C9

; VERIFIED: Alternate between two child-orientation adjustments using the toggle at ChildLaunchOrientationToggle.
; Called for non-station parents only; station launches retain the copied orientation.
; VERIFIED: Toggle 1 (L_F4A2 three times): exchange the forward axis (InstanceAxisZ) and up axis
; (InstanceAxisY) components and reverse the side axis (InstanceAxisX), a half turn.
; Toggle 0 (L_F4BB): a quarter turn, new forward = -old up and new up = old forward.
; Only the high bytes of the axis words are moved; the fraction bytes stay in place.
AdjustChildLaunchOrientation:
    LD A,(ChildLaunchOrientationToggle)        ; $F48A: 3A C9 F2
    XOR $01                                    ; $F48D: EE 01  toggle bit 0
    LD (ChildLaunchOrientationToggle),A        ; $F48F: 32 C9 F2  store the new toggle value
    JR Z,L_F4BB                                ; $F492: 28 27  new value 0: quarter turn at L_F4BB
    PUSH IX                                    ; $F494: DD E5
    CALL L_F4A2                                ; $F496: CD A2 F4  x components: +$0A/+$10, +$16
    CALL L_F4A2                                ; $F499: CD A2 F4  y components: +$0C/+$12, +$18
    CALL L_F4A2                                ; $F49C: CD A2 F4  z components: +$0E/+$14, +$1A
    POP IX                                     ; $F49F: DD E1
    RET                                        ; $F4A1: C9

; VERIFIED: One component of the toggle-1 turn: exchange the high bytes +$0A (forward axis) and +$10
; (up axis), invert the sign bit of +$16 (side axis), then IX += 2 for the next component.
; Three calls cover +$0A/+$10/+$16, +$0C/+$12/+$18 and +$0E/+$14/+$1A.
L_F4A2:
    LD A,(IX+$0A)                              ; $F4A2: DD 7E 0A  forward axis component
    LD B,(IX+$10)                              ; $F4A5: DD 46 10  up axis component
    LD (IX+$10),A                              ; $F4A8: DD 77 10
    LD (IX+$0A),B                              ; $F4AB: DD 70 0A
    LD A,(IX+$16)                              ; $F4AE: DD 7E 16  side axis component: invert its sign
    XOR $80                                    ; $F4B1: EE 80
    LD (IX+$16),A                              ; $F4B3: DD 77 16
    INC IX                                     ; $F4B6: DD 23  next component word
    INC IX                                     ; $F4B8: DD 23
    RET                                        ; $F4BA: C9

; VERIFIED: Toggle-0 turn: for the component pairs (+$0A,+$10), (+$0C,+$12) and (+$0E,+$14) store
; -second into first and first into second, i.e. forward := -up and up := forward.
L_F4BB:
    LD A,(IX+$10)                              ; $F4BB: DD 7E 10  forward x := -up x
    XOR $80                                    ; $F4BE: EE 80
    LD B,(IX+$0A)                              ; $F4C0: DD 46 0A
    LD (IX+$0A),A                              ; $F4C3: DD 77 0A
    LD (IX+$10),B                              ; $F4C6: DD 70 10  up x := old forward x
    LD A,(IX+$12)                              ; $F4C9: DD 7E 12  forward y := -up y
    XOR $80                                    ; $F4CC: EE 80
    LD B,(IX+$0C)                              ; $F4CE: DD 46 0C
    LD (IX+$0C),A                              ; $F4D1: DD 77 0C
    LD (IX+$12),B                              ; $F4D4: DD 70 12  up y := old forward y
    LD A,(IX+$14)                              ; $F4D7: DD 7E 14  forward z := -up z
    XOR $80                                    ; $F4DA: EE 80
    LD B,(IX+$0E)                              ; $F4DC: DD 46 0E
    LD (IX+$0E),A                              ; $F4DF: DD 77 0E
    LD (IX+$14),B                              ; $F4E2: DD 70 14  up z := old forward z
    RET                                        ; $F4E5: C9

; VERIFIED: Tilt the forward axis (InstanceAxisZ) by small random x and y components:
; high bytes +$0A and +$0C = NextRandomByte AND $87 (random sign, magnitude 0..7 of 127),
; giving a slightly randomised heading.
; Input: IX = instance.  Clobbers A, flags; advances the RNG twice.
L_F4E6:
    CALL NextRandomByte                        ; $F4E6: CD 24 ED  forward axis x component
    AND $87                                    ; $F4E9: E6 87  random sign, magnitude 0..7
    LD (IX+$0A),A                              ; $F4EB: DD 77 0A
    CALL NextRandomByte                        ; $F4EE: CD 24 ED  forward axis y component
    AND $87                                    ; $F4F1: E6 87
    LD (IX+$0C),A                              ; $F4F3: DD 77 0C
    RET                                        ; $F4F6: C9

; VERIFIED: Event 5: create two Alloy plates (blueprint ID 3).  C odd: both near the player through
; SpawnObjectNearPlayer; C even: both at the parent IX through L_F5B8.
; Callers: event $05 from the laser kill code at $ECC1 (blueprint energy >= 85) and event
; $15 from ClearAllShipSlots at GAME OVER (debris around the player's own position).
; Out: Z if both were created, NZ as soon as no slot is free.
SpawnAlloyPlatePair:
    BIT 0,C                                    ; $F4F7: CB 41  C odd: near the player
    JR Z,L_F54B                                ; $F4F9: 28 50  C even: at the parent
    CALL L_F4FF                                ; $F4FB: CD FF F4  first plate near the player
    RET NZ                                     ; $F4FE: C0  no slot: stop (NZ)

; VERIFIED: A = 3 (Alloy plate), then SpawnObjectNearPlayer.  Called once and then fallen into, so
; SpawnAlloyPlatePair creates two plates (the second only if the first succeeded).
L_F4FF:
    LD A,$03                                   ; $F4FF: 3E 03  blueprint 3: Alloy plate

; VERIFIED: Create blueprint A in a free slot (L_F3AD) at a random offset around the origin (the
; player): random heading tilt (L_F4E6); x and y magnitudes 16..63, each with the sign
; opposite to the heading tilt in that axis; z = +$19; random roll byte +$1D; speed +$1B =
; 8..39; clear +$20 bit 6 (not counted).  Out: Z on success, NZ if no slot was free.
SpawnObjectNearPlayer:
    CALL L_F3AD                                ; $F501: CD AD F3  allocate; position bytes cleared
    RET NZ                                     ; $F504: C0  NZ: no free slot
    CALL L_F4E6                                ; $F505: CD E6 F4  random heading tilt
    RES 6,(IX+$20)                             ; $F508: DD CB 20 B6  not counted by EncounterShipCount
    CALL NextRandomByte                        ; $F50C: CD 24 ED  x magnitude 16..63
    AND $3F                                    ; $F50F: E6 3F
    OR $10                                     ; $F511: F6 10
    LD (IX+$00),A                              ; $F513: DD 77 00
    LD A,(IX+$0A)                              ; $F516: DD 7E 0A  x sign opposite to the heading x sign
    AND $80                                    ; $F519: E6 80
    XOR $80                                    ; $F51B: EE 80
    LD (IX+$02),A                              ; $F51D: DD 77 02
    CALL NextRandomByte                        ; $F520: CD 24 ED  y magnitude 16..63
    AND $3F                                    ; $F523: E6 3F
    OR $10                                     ; $F525: F6 10
    LD (IX+$03),A                              ; $F527: DD 77 03
    LD A,(IX+$0C)                              ; $F52A: DD 7E 0C  y sign opposite to the heading y sign
    AND $80                                    ; $F52D: E6 80
    XOR $80                                    ; $F52F: EE 80
    LD (IX+$05),A                              ; $F531: DD 77 05
    LD A,$19                                   ; $F534: 3E 19  z = $19
    LD (IX+$06),A                              ; $F536: DD 77 06
    CALL NextRandomByte                        ; $F539: CD 24 ED  random roll byte
    LD (IX+$1D),A                              ; $F53C: DD 77 1D
    CALL NextRandomByte                        ; $F53F: CD 24 ED  speed 8..39
    AND $1F                                    ; $F542: E6 1F
    OR $08                                     ; $F544: F6 08
    LD (IX+$1B),A                              ; $F546: DD 77 1B
    XOR A                                      ; $F549: AF  Z: success
    RET                                        ; $F54A: C9

; VERIFIED: SpawnAlloyPlatePair with C even: two Alloy plates (ID 3) at the parent through L_F5B8.
L_F54B:
    LD A,$03                                   ; $F54B: 3E 03  blueprint 3: Alloy plate
    CALL L_F5B8                                ; $F54D: CD B8 F5  first plate at the parent
    RET NZ                                     ; $F550: C0  no slot: stop (NZ)
    LD A,$03                                   ; $F551: 3E 03
    JR L_F5B8                                  ; $F553: 18 63  second plate

; VERIFIED: Event 6: create a Cargo canister (blueprint ID 4).  C even: at the parent through L_F592
; (an AI ship dumping cargo, L_F7D4; the laser kill code at $ECB6 when the blueprint canister
; nibble is nonzero; L_EC8C for the marked Asp).  C odd: near the player through
; SpawnObjectNearPlayer (event $16 from ClearAllShipSlots at GAME OVER).
SpawnCargoCanister:
    BIT 0,C                                    ; $F555: CB 41
    LD A,$04                                   ; $F557: 3E 04  blueprint 4: Cargo canister
    JR Z,L_F592                                ; $F559: 28 37  C even: at the parent
    JR SpawnObjectNearPlayer                   ; $F55B: 18 A4  C odd: near the player

; VERIFIED: Event 7.  C even (event $07 from L_F7B6): an AI ship launches an Escape capsule
; (blueprint ID 2) from its own position through L_F592.
; C odd (event $17, sent only by the escape-pod launch at $A7C8): slot 6 is overwritten with
; a Cobra Mk III (ID 9): L_F3B3 clears its position bytes, random heading tilt, y = -$1C,
; z = +$4C, pitch byte +$1E = $C0, speed += PlayerSpeed, not counted.  Returns Z.
; INFERRED: the Cobra shows the ship the player has just abandoned.
HandleEscapeCapsuleEvent:
    BIT 0,C                                    ; $F55D: CB 41
    LD A,$02                                   ; $F55F: 3E 02  blueprint 2: Escape capsule
    JR Z,L_F592                                ; $F561: 28 2F  C even: leaves the parent ship
    LD A,$09                                   ; $F563: 3E 09  blueprint 9: Cobra Mk III
    LD IX,ObjectSlot6                          ; $F565: DD 21 32 61  slot 6, overwritten whatever it holds
    CALL L_F3B3                                ; $F569: CD B3 F3  initialise there, position bytes cleared
    CALL L_F4E6                                ; $F56C: CD E6 F4  random heading tilt
    LD A,$80                                   ; $F56F: 3E 80  y sign: negative
    LD (IX+$05),A                              ; $F571: DD 77 05
    LD A,$1C                                   ; $F574: 3E 1C  y = -$1C
    LD (IX+$03),A                              ; $F576: DD 77 03
    RES 6,(IX+$20)                             ; $F579: DD CB 20 B6  not counted
    LD A,$4C                                   ; $F57D: 3E 4C  z = $4C
    LD (IX+$06),A                              ; $F57F: DD 77 06
    LD A,$C0                                   ; $F582: 3E C0  pitch byte $C0
    LD (IX+$1E),A                              ; $F584: DD 77 1E
    LD A,(PlayerSpeed)                         ; $F587: 3A 44 70  add the player speed
    ADD A,(IX+$1B)                             ; $F58A: DD 86 1B
    LD (IX+$1B),A                              ; $F58D: DD 77 1B
    XOR A                                      ; $F590: AF  Z: done
    RET                                        ; $F591: C9

; VERIFIED: Create child blueprint A at parent IX (CreateShipAtParent), then on the child: clear
; +$20 bit 6 (not counted), +$26 = $0A (bits 1 and 3: no laser fire, and the object does
; not set TorusJumpInhibitFlag in the object update), +$1D = $80.  IX is restored to the parent.
; Out: Z on success, NZ if no slot.  Used for escape capsules and cargo canisters.
L_F592:
    PUSH IX                                    ; $F592: DD E5  keep the parent
    CALL CreateShipAtParent                    ; $F594: CD 81 F3  child at the parent position/orientation
    EX (SP),IX                                 ; $F597: DD E3  IX = parent, child on the stack
    POP HL                                     ; $F599: E1  HL = child
    RET NZ                                     ; $F59A: C0  NZ: no free slot (IX = parent)
    PUSH HL                                    ; $F59B: E5
    EX (SP),IX                                 ; $F59C: DD E3  IX = child, parent on the stack
    RES 6,(IX+$20)                             ; $F59E: DD CB 20 B6  not counted
    LD A,$0A                                   ; $F5A2: 3E 0A  +$26 = $0A: bits 1 and 3
    LD (IX+$26),A                              ; $F5A4: DD 77 26
    LD A,$80                                   ; $F5A7: 3E 80  roll byte $80
    LD (IX+$1D),A                              ; $F5A9: DD 77 1D
    XOR A                                      ; $F5AC: AF  Z: success
    POP IX                                     ; $F5AD: DD E1  restore the parent
    RET                                        ; $F5AF: C9

; VERIFIED: Event 8: create two Splinters (blueprint ID 5) at the parent through L_F5B8.
; Evidence: caller $ECCF after a laser hit of damage 50 (the mining laser) destroys an
; Asteroid (blueprint energy 60); AGENTS.md: there is no separate Boulder blueprint.
SpawnSplinterPair:
    LD A,$05                                   ; $F5B0: 3E 05  blueprint 5: Splinter
    CALL L_F5B8                                ; $F5B2: CD B8 F5  first Splinter
    RET NZ                                     ; $F5B5: C0  no slot: stop (NZ)
    LD A,$05                                   ; $F5B6: 3E 05

; VERIFIED: Create child blueprint A at parent IX, turn it with AdjustChildLaunchOrientation, set
; +$26 = $0A (as L_F592), clear +$20 bit 6 (not counted) and set +$1D bit 7.  IX is restored
; to the parent.  Out: Z on success, NZ if no slot.
L_F5B8:
    PUSH IX                                    ; $F5B8: DD E5  keep the parent
    CALL CreateShipAtParent                    ; $F5BA: CD 81 F3  child at the parent position/orientation
    EX (SP),IX                                 ; $F5BD: DD E3
    POP HL                                     ; $F5BF: E1
    RET NZ                                     ; $F5C0: C0  NZ: no free slot (IX = parent)
    PUSH HL                                    ; $F5C1: E5
    EX (SP),IX                                 ; $F5C2: DD E3
    CALL AdjustChildLaunchOrientation          ; $F5C4: CD 8A F4  turn the child
    LD A,$0A                                   ; $F5C7: 3E 0A  +$26 = $0A: bits 1 and 3
    LD (IX+$26),A                              ; $F5C9: DD 77 26
    RES 6,(IX+$20)                             ; $F5CC: DD CB 20 B6  not counted
    SET 7,(IX+$1D)                             ; $F5D0: DD CB 1D FE  roll byte bit 7
    POP IX                                     ; $F5D4: DD E1
    XOR A                                      ; $F5D6: AF  Z: success
    RET                                        ; $F5D7: C9

; VERIFIED: Event 9: initialise instance slot 7 with blueprint ID C+2, not counted, x = y = 0 (the
; random coordinates of InitialiseShipFromBlueprint are overwritten; only a random x/y sign
; bit with zero magnitude remains), z = +$0200, speed 0, +$1D = +$1E = $C0, and copy the
; nine orientation high bytes from ObjectSlot7OrientationBytes into +$0A,+$0C,..,+$1A.
; Evidence: startup event $79 (ID 9, Cobra Mk III) at $718F; title loop at $71DC cycles
; event 16*n+9.  INFERRED: this is the rotating title-screen ship.
SetUpDisplayShip:
    LD IX,ObjectSlot7                          ; $F5D8: DD 21 59 61  slot 7
    LD A,C                                     ; $F5DC: 79
    ADD A,$02                                  ; $F5DD: C6 02  blueprint ID = C+2
    CALL InitialiseShipFromBlueprint           ; $F5DF: CD FB F2  random x/y are overwritten below
    LD A,$C0                                   ; $F5E2: 3E C0  roll and pitch bytes $C0
    LD (IX+$1D),A                              ; $F5E4: DD 77 1D
    LD (IX+$1E),A                              ; $F5E7: DD 77 1E
    XOR A                                      ; $F5EA: AF
    LD (IX+$06),A                              ; $F5EB: DD 77 06  z low byte
    LD (IX+$00),A                              ; $F5EE: DD 77 00  x = 0
    LD (IX+$01),A                              ; $F5F1: DD 77 01
    LD (IX+$03),A                              ; $F5F4: DD 77 03  y = 0
    LD (IX+$04),A                              ; $F5F7: DD 77 04
    LD (IX+$08),A                              ; $F5FA: DD 77 08  z sign byte
    LD (IX+$1B),A                              ; $F5FD: DD 77 1B  speed 0
    RES 6,(IX+$20)                             ; $F600: DD CB 20 B6  not counted
    INC A                                      ; $F604: 3C
    INC A                                      ; $F605: 3C
    LD (IX+$07),A                              ; $F606: DD 77 07  z high byte = 2: z = +$0200
    PUSH IX                                    ; $F609: DD E5
    POP HL                                     ; $F60B: E1
    LD DE,$0009                                ; $F60C: 11 09 00  offset 9 (first axis word) and count 9
    LD B,D                                     ; $F60F: 42  BC = 9 bytes
    LD C,E                                     ; $F610: 4B
    ADD HL,DE                                  ; $F611: 19
    EX DE,HL                                   ; $F612: EB  DE = instance+$09, the low byte of the first word
    LD HL,ObjectSlot7OrientationBytes          ; $F613: 21 C0 F2  nine orientation high bytes
L_F616:
    INC DE                                     ; $F616: 13  DE skips each low byte
    LDI                                        ; $F617: ED A0
    JP PE,L_F616                               ; $F619: EA 16 F6  until BC = 0
    RET                                        ; $F61C: C9

; ============================================================================
; Random space encounters
; Event 0: asteroids, traders, single ships and groups, weighted by contraband in the
; hold and by the government of the system; the special Asp Mk II encounter.
; ============================================================================

; VERIFIED: Event-zero encounter entry, reached from DispatchShipEvent.
; The later mixed single-ship path can create Fer-de-Lance regardless of PlayerLegalScore.
; Earlier cargo, government and special-state gates remain separate from ship hostility.
; Evidence: full event-zero executions in tools/check_bounty_hunters.py; docs/BOUNTY-HUNTERS.md.
; VERIFIED: C = 2*(SLAVES + NARCOTICS) + FIREARMS (CargoHold+3, +6, +10, 8-bit sum):
; contraband makes ship encounters more likely (L_F660).  The special Asp encounter needs
; MissionAspEncounterState = 0, NextRandomByte <> $FF and CommanderFlags AND $42 = $02.
; Evidence: tools/check_routines.py ai/p11-encounter-selection, missions/special-encounter.
SpawnRandomEncounter:
    LD A,(CargoHold+3)                         ; $F61D: 3A 30 A8  CargoHold+3: SLAVES
    LD C,A                                     ; $F620: 4F
    LD A,(CargoHold+6)                         ; $F621: 3A 33 A8  CargoHold+6: NARCOTICS
    ADD A,C                                    ; $F624: 81
    ADD A,A                                    ; $F625: 87  twice (slaves + narcotics)
    LD C,A                                     ; $F626: 4F
    LD A,(CargoHold+10)                        ; $F627: 3A 37 A8  CargoHold+10: FIREARMS
    ADD A,C                                    ; $F62A: 81
    LD C,A                                     ; $F62B: 4F  C = 2*(slaves+narcotics)+firearms
    LD A,(MissionAspEncounterState)            ; $F62C: 3A 0C DA  special encounter running or done?
    AND A                                      ; $F62F: A7
    JR NZ,L_F660                               ; $F630: 20 2E  yes: ordinary selection
    CALL NextRandomByte                        ; $F632: CD 24 ED
    CP $FF                                     ; $F635: FE FF  only $FF skips the special test
    JR NC,L_F660                               ; $F637: 30 27  random $FF: ordinary selection
    LD A,(CommanderFlags)                      ; $F639: 3A 72 A8  bit 1 set, bit 6 (cloaking device) clear
    AND $42                                    ; $F63C: E6 42
    CP $02                                     ; $F63E: FE 02
    JR NZ,L_F660                               ; $F640: 20 1E  otherwise ordinary selection
    DEC A                                      ; $F642: 3D
    LD (MissionAspEncounterState),A            ; $F643: 32 0C DA  MissionAspEncounterState = 1
    LD A,$0F                                   ; $F646: 3E 0F  pushed A: ID 15 makes it set +$25 bit 0
    LD HL,L_F655                               ; $F648: 21 55 F6  return address for InitialiseEncounterShip
    PUSH HL                                    ; $F64B: E5
    PUSH AF                                    ; $F64C: F5
    CALL FindFreeShipSlot                      ; $F64D: CD 99 F3  slot for the Asp
    RET NZ                                     ; $F650: C0  BUG: no free slot pops the pushed AF ($0F02) into PC (ROM)
    LD A,$0D                                   ; $F651: 3E 0D  Asp Mk II
    JR InitialiseEncounterShip                 ; $F653: 18 73  create it; its RET goes to L_F655

; VERIFIED: Special-encounter continuation: the RET of InitialiseEncounterShip returns here
; (address pushed at $F648).  Set +$26 bit 6 and +$20 bit 2 (payload count 1 -> 5) on the
; new Asp Mk II, then add a group of 2..4 Sidewinders/Kraits at L_F70E.
; +$26 bit 6 marks the ship that DrawObjectInView hides while MissionAspEncounterState = 1
; (L_E0FA) and whose destruction sets state 3 and drops a canister (L_EC8C).
; Evidence: missions/special-encounter (free slots): Asp $61CC with +$20=$C5, +$25=$7F,
; +$26=$40, then two Sidewinders.  INFERRED: the cloaked Asp of mission 2 (docs/info notes).
L_F655:
    SET 6,(IX+$26)                             ; $F655: DD CB 26 F6  +$26 bit 6 marks this ship
    SET 2,(IX+$20)                             ; $F659: DD CB 20 D6  payload count 1 -> 5
    JP L_F70E                                  ; $F65D: C3 0E F7  escort of 2..4 Sidewinders/Kraits

; VERIFIED: Ordinary encounter selection: r = NextRandomByte - C (C from SpawnRandomEncounter).
; No borrow: r >= $5A -> nothing; r = $50..$59 -> an Asteroid (ID 6), not counted, +$1D = $C0;
; r < $50 -> L_F684.  Borrow (random byte below C) -> L_F684 with the wrapped r.
L_F660:
    CALL NextRandomByte                        ; $F660: CD 24 ED
    SUB C                                      ; $F663: 91  r = random - contraband sum
    JR C,L_F684                                ; $F664: 38 1E  random below C: ship encounter
    CP $5A                                     ; $F666: FE 5A  r >= $5A: no encounter
    RET NC                                     ; $F668: D0
    CP $50                                     ; $F669: FE 50
    JR C,L_F684                                ; $F66B: 38 17  r < $50: ship encounter
    CALL FindFreeShipSlot                      ; $F66D: CD 99 F3  r = $50..$59: an Asteroid
    RET NZ                                     ; $F670: C0
    LD A,$06                                   ; $F671: 3E 06  Asteroid
    CALL InitialiseShipFromBlueprint           ; $F673: CD FB F2
    SET 7,(IX+$0E)                             ; $F676: DD CB 0E FE  no effect: the template already sets this bit
    RES 6,(IX+$20)                             ; $F67A: DD CB 20 B6  not counted
    LD A,$C0                                   ; $F67E: 3E C0  roll byte $C0
    LD (IX+$1D),A                              ; $F680: DD 77 1D
    RET                                        ; $F683: C9

; VERIFIED: B = r, E = r AND 7.  InvasionMissionState = 4 -> one Thargoid (ID 15); InvasionMissionState = 1 -> one Python trader
; (ID 10).  Otherwise g = CurrentGovernment AND 7 (0 anarchy .. 7 corporate state): for
; g <> 0, E becomes (r AND 7) + 1 and g >= E means no encounter; an anarchy always gets one.
; Then r bit 3 set -> SpawnMixedSingleShipEncounter, else L_F6E2 with E.
; Evidence: tools/check_routines.py ai/p11-encounter-selection.
L_F684:
    LD B,A                                     ; $F684: 47  B = r
    AND $07                                    ; $F685: E6 07
    LD E,A                                     ; $F687: 5F  E = r AND 7
    LD A,(InvasionMissionState)                ; $F688: 3A 71 A8  special state (InvasionMissionState)
    CP $04                                     ; $F68B: FE 04  InvasionMissionState = 4: Thargoid
    LD D,A                                     ; $F68D: 57
    LD C,$0F                                   ; $F68E: 0E 0F  C = 15: Thargoid
    JR Z,L_F6DB                                ; $F690: 28 49
    LD A,D                                     ; $F692: 7A
    CP $01                                     ; $F693: FE 01  InvasionMissionState = 1: Python trader
    LD C,$0A                                   ; $F695: 0E 0A  C = 10: Python trader
    JR Z,L_F6DB                                ; $F697: 28 42
    LD A,(CurrentGovernment)                   ; $F699: 3A 5F A8  government 0..7
    AND $07                                    ; $F69C: E6 07
    JR Z,L_F6A3                                ; $F69E: 28 03  anarchy: always an encounter
    INC E                                      ; $F6A0: 1C  E = (r AND 7) + 1
    CP E                                       ; $F6A1: BB
    RET NC                                     ; $F6A2: D0  government >= E: no encounter
L_F6A3:
    LD C,A                                     ; $F6A3: 4F  C = government (not read afterwards)
    BIT 3,B                                    ; $F6A4: CB 58  r bit 3: one mixed ship
    JP Z,L_F6E2                                ; $F6A6: CA E2 F6

; VERIFIED: Allocate one encounter slot, then fall through to SelectMixedEncounterShipType.
; Return NZ if all six allocatable slots are occupied. No legal-score gate.
; Evidence: full/free-slot cases in tools/check_bounty_hunters.py.
SpawnMixedSingleShipEncounter:
    CALL FindFreeShipSlot                      ; $F6A9: CD 99 F3
    RET NZ                                     ; $F6AC: C0

; VERIFIED: IX already identifies a free slot. Select using NextRandomByte AND $3F:
; 0 Thargoid (15); 1..11 Fer-de-Lance (14); 12..29 Asp (13);
; 30..45 pirate Cobra (12); 46..63 pirate Python (11).
; Continue into blueprint initialization; Fer-de-Lance alone starts calm in this group.
; These are selector outcomes, not per-frame probabilities; preceding RNG/gates still apply.
; Evidence: all 256 RNG byte values in tools/check_bounty_hunters.py.
SelectMixedEncounterShipType:
    CALL NextRandomByte                        ; $F6AD: CD 24 ED
    AND $3F                                    ; $F6B0: E6 3F  0..63
    LD B,$0F                                   ; $F6B2: 06 0F  0: Thargoid (15)
    JR Z,L_F6C6                                ; $F6B4: 28 10
    DEC B                                      ; $F6B6: 05  1..11: Fer-de-Lance (14)
    SUB $0C                                    ; $F6B7: D6 0C
    JR C,L_F6C6                                ; $F6B9: 38 0B
    DEC B                                      ; $F6BB: 05  12..29: Asp Mk II (13)
    SUB $12                                    ; $F6BC: D6 12
    JR C,L_F6C6                                ; $F6BE: 38 06
    DEC B                                      ; $F6C0: 05  30..45: pirate Cobra (12)
    SUB $10                                    ; $F6C1: D6 10
    JR C,L_F6C6                                ; $F6C3: 38 01
    DEC B                                      ; $F6C5: 05  46..63: pirate Python (11)
L_F6C6:
    LD A,B                                     ; $F6C6: 78
L_F6C7:
    PUSH AF                                    ; $F6C7: F5  keep the blueprint ID

; VERIFIED: A is the selected blueprint ID, IX the allocated slot; a saved AF word is on the stack.
; Initialize the instance, restore AF and optionally set bit 0 in instance +$25.
; That optional flag does not change hostility in +$21 or inspect PlayerLegalScore.
; Evidence: identical Fer-de-Lance spawn state across legal scores in tools/check_bounty_hunters.py.
InitialiseEncounterShip:
    CALL InitialiseShipFromBlueprint           ; $F6C8: CD FB F2
    POP AF                                     ; $F6CB: F1
    CP $0F                                     ; $F6CC: FE 0F  Thargoid: always +$25 bit 0
    JR Z,L_F6D6                                ; $F6CE: 28 06
    CALL NextRandomByte                        ; $F6D0: CD 24 ED
    CP $33                                     ; $F6D3: FE 33  others: 51 of 256
    RET NC                                     ; $F6D5: D0
L_F6D6:
    SET 0,(IX+$25)                             ; $F6D6: DD CB 25 C6  +$25 bit 0: ECM fitted (L_F815)
    RET                                        ; $F6DA: C9

; VERIFIED: Allocate a slot and create blueprint C (Thargoid or Python trader, from L_F684) through
; the shared InitialiseEncounterShip path.
L_F6DB:
    CALL FindFreeShipSlot                      ; $F6DB: CD 99 F3
    RET NZ                                     ; $F6DE: C0
    LD A,C                                     ; $F6DF: 79  A = Thargoid or Python trader
    JR L_F6C7                                  ; $F6E0: 18 E5

; VERIFIED: New random byte r2: (r2 AND 7) >= E -> group at L_F70E.  Otherwise allocate one slot and
; choose from bits 7..5 of r2 (rotated into C bits 2..0): 0..1 -> L_F706, 2..7 ->
; SelectEncounterTraderType (2..4 Cobra trader, 5..7 Python trader).
L_F6E2:
    CALL NextRandomByte                        ; $F6E2: CD 24 ED
    LD B,A                                     ; $F6E5: 47  B = r2
    AND $07                                    ; $F6E6: E6 07
    CP E                                       ; $F6E8: BB  compare with E
    JR NC,L_F70E                               ; $F6E9: 30 23  (r2 AND 7) >= E: a group
    RLC B                                      ; $F6EB: CB 00  rotate r2 left three times
    RLC B                                      ; $F6ED: CB 00
    RLC B                                      ; $F6EF: CB 00
    LD C,B                                     ; $F6F1: 48  C bits 2..0 = r2 bits 7..5; bit 7 = r2 bit 4
    CALL FindFreeShipSlot                      ; $F6F2: CD 99 F3  one slot
    RET NZ                                     ; $F6F5: C0
    LD A,C                                     ; $F6F6: 79
    AND $07                                    ; $F6F7: E6 07  r2 bits 7..5
    CP $02                                     ; $F6F9: FE 02
    JR C,L_F706                                ; $F6FB: 38 09  0..1: Rock hermit or Viper

; VERIFIED: Ordinary space encounter: A=2..7 selects Cobra trader (9) or Python trader (10).
; This path is separate from station launches and is not affected by stationrandomlaunchfix.
SelectEncounterTraderType:
    DEC A                                      ; $F6FD: 3D
    SRL A                                      ; $F6FE: CB 3F
    SRL A                                      ; $F700: CB 3F
    ADD A,$09                                  ; $F702: C6 09  2..4: Cobra trader (9), 5..7: Python trader (10)
    JR L_F6C7                                  ; $F704: 18 C1

; VERIFIED: Rock hermit (ID 7) or Viper (ID 8), chosen by bit 4 of r2 (bit 7 of the
; rotated copy in C), then created through InitialiseEncounterShip.
L_F706:
    LD A,C                                     ; $F706: 79
    RLCA                                       ; $F707: 07  r2 bit 4 to bit 0
    AND $01                                    ; $F708: E6 01
    ADD A,$07                                  ; $F70A: C6 07  7 Rock hermit, 8 Viper
    JR L_F6C7                                  ; $F70C: 18 B9

; VERIFIED: Create a group of 2 + ((r AND 3) >> 1) + (r AND 1) ships (2, 3, 3 or 4 for
; r AND 3 = 0..3), each a Sidewinder (ID 16) or Krait (ID 17; Adder with ship=adder)
; chosen by NextRandomByte bit 0.  Stops early (NZ) when no slot is free.  Also the tail
; of the special encounter.
; Evidence: tools/check_routines.py ai/p11-encounter-selection (all 256 group bytes).
L_F70E:
    CALL NextRandomByte                        ; $F70E: CD 24 ED
    AND $03                                    ; $F711: E6 03
    RRA                                        ; $F713: 1F  A = (r AND 3) >> 1, carry = r bit 0
    ADC A,$02                                  ; $F714: CE 02  count 2..4
    LD C,A                                     ; $F716: 4F
L_F717:
    CALL FindFreeShipSlot                      ; $F717: CD 99 F3  next slot
    RET NZ                                     ; $F71A: C0  no slot: stop (NZ)
    PUSH BC                                    ; $F71B: C5
    CALL NextRandomByte                        ; $F71C: CD 24 ED  type bit for this ship
    AND $01                                    ; $F71F: E6 01
    ADD A,$10                                  ; $F721: C6 10  Sidewinder (16) or Krait/Adder (17)
    CALL InitialiseShipFromBlueprint           ; $F723: CD FB F2
    POP BC                                     ; $F726: C1
    DEC C                                      ; $F727: 0D  next ship of the group
    JR NZ,L_F717                               ; $F728: 20 ED
    RET                                        ; $F72A: C9

; VERIFIED: Steering vector, x component: sign-magnitude word (bit 15 = sign) at a quarter of the
; coordinate scale.  Written by SteerShipAwayFromPlayer (+position/4), SteerShipTowardsPlayer
; (-position/4) and UpdateMissileGuidance ((target - missile)/4); NormaliseVector rescales
; the three words in place to length $8000 for ApplySteeringVector.
SteeringVectorX:
    defw $0000                                                                            ; $F72B

; VERIFIED: Steering vector, y component; same format as SteeringVectorX.
SteeringVectorY:
    defw $0000                                                                            ; $F72D

; VERIFIED: Steering vector, z component; same format as SteeringVectorX.
SteeringVectorZ:
    defw $0000                                                                            ; $F72F

; VERIFIED: Length of the steering vector before normalisation: DE returned by
; NormaliseVector, stored by ApplySteeringVector.  Within about 3.5% for vectors well
; above $100 (coarser for short ones).  Its high byte is the range R tested by
; ApplySteeringVector ($02..$12) and TryFireAiLaser ($0C, $04); in coordinate units R
; is about distance/1024.
; Evidence: tools/check_routines.py ai/p11-apply-steering-vector (the stored word equals
; NormaliseVector's result) and maths/square-root-and-normalise (accuracy).
SteeringVectorLength:
    defw $0000                                                                            ; $F731

; ============================================================================
; Ship AI: tactics, missile guidance and steering
; Per-ship energy regeneration and launch decisions, missile guidance and the
; shared steering calculation that turns a vector into roll/pitch/speed commands.
; ============================================================================

; VERIFIED: Per-ship AI step (L_DB86 calls it every fourth update per ship; missiles use
; UpdateMissileGuidance instead).  IX = instance, IY = blueprint.
; 1. Energy := min(blueprint energy +$07, energy + 1, or + 4 when the blueprint energy is
;    >= $F0).  Nothing (not even the energy) is stored while CloakingDeviceActive is
;    nonzero (the player's cloaking device is on).
; 2. MissionAspEncounterState 1 (marked Asp hidden) costs 2 energy per step, or switches to 2
;    below energy $34; state 2 returns to 1 at energy >= $50.  Every ship's step applies this.
; 3. Energy >= 128 or >= half the blueprint energy: no launch.  Energy >= 32 or >= 1/8:
;    TryLaunchAiPayload.  Below both: L_F7B6 (escape capsule or cargo canister).
; 4. Continue at L_F7DF (orphaned Thargon check) and L_F815 (ECM), then traffic/steering.
; Evidence: tools/check_routines.py ai/p11-ship-tactics-energy (steps 1 and 2).
UpdateShipTactics:
    LD A,(IY+$07)                              ; $F733: FD 7E 07  blueprint maximum energy
    LD C,(IX+$22)                              ; $F736: DD 4E 22  current energy
    INC C                                      ; $F739: 0C  +1
    CP $F0                                     ; $F73A: FE F0  large energy: regenerate 4 instead of 1
    JR C,L_F741                                ; $F73C: 38 03  below $F0: +1 only
    INC C                                      ; $F73E: 0C  +3 more
    INC C                                      ; $F73F: 0C
    INC C                                      ; $F740: 0C
L_F741:
    CP C                                       ; $F741: B9
    JR C,L_F745                                ; $F742: 38 01  above the maximum: cap it
    LD A,C                                     ; $F744: 79  otherwise the incremented energy
L_F745:
    LD B,A                                     ; $F745: 47  B = new energy
    LD A,(CloakingDeviceActive)                ; $F746: 3A 0C A8  player cloaked: no AI step at all
    AND A                                      ; $F749: A7
    RET NZ                                     ; $F74A: C0
    LD HL,MissionAspEncounterState             ; $F74B: 21 0C DA  marked-Asp cloak state
    LD A,B                                     ; $F74E: 78
    CP $50                                     ; $F74F: FE 50  energy >= $50?
    LD A,(HL)                                  ; $F751: 7E  A = state (flags kept)
    JR C,L_F759                                ; $F752: 38 05  below $50
    CP $02                                     ; $F754: FE 02  state 2 ...
    JR NZ,L_F759                               ; $F756: 20 01
    DEC (HL)                                   ; $F758: 35  ... -> 1 (A still 2: no cost this step)
L_F759:
    CP $01                                     ; $F759: FE 01  state 1: Asp hidden
    JR NZ,L_F76A                               ; $F75B: 20 0D
    LD A,B                                     ; $F75D: 78
    CP $34                                     ; $F75E: FE 34  energy >= $34: pay for it
    JR NC,L_F767                               ; $F760: 30 05
    LD A,$02                                   ; $F762: 3E 02  too little energy: state 2 (visible)
    LD (HL),A                                  ; $F764: 77
    JR L_F76A                                  ; $F765: 18 03
L_F767:
    SUB $02                                    ; $F767: D6 02  costs 2 energy
    LD B,A                                     ; $F769: 47
L_F76A:
    LD A,B                                     ; $F76A: 78
    LD (IX+$22),A                              ; $F76B: DD 77 22  store the new energy
    LD B,(IY+$07)                              ; $F76E: FD 46 07  B = blueprint energy
    ADD A,A                                    ; $F771: 87  2 * energy
    JR C,L_F7DF                                ; $F772: 38 6B  energy >= 128
    CP B                                       ; $F774: B8
    JR NC,L_F7DF                               ; $F775: 30 68  energy >= half maximum
    ADD A,A                                    ; $F777: 87  4 * energy
    JR C,TryLaunchAiPayload                    ; $F778: 38 06  energy >= 64
    ADD A,A                                    ; $F77A: 87  8 * energy
    JR C,TryLaunchAiPayload                    ; $F77B: 38 03  energy >= 32
    CP B                                       ; $F77D: B8
    JR C,L_F7B6                                ; $F77E: 38 36  energy < 1/8 maximum

; VERIFIED: AI payload attempt: IX=parent instance, IY=its blueprint. Require remaining payload,
; random result below $80 and inactive ECM. Blueprint byte $0A high nibble selects
; the launch subtype; rock hermits use 5, Thargoids use 3. Zero selects a missile event.
; Dispatch with IX/IY preserved; decrement the payload count only on successful creation.
; VERIFIED: Event = blueprint +$0A AND $F0 XOR 4: subtype n gives event n*16+4
; (SelectParentLaunchType); a zero high nibble gives 6 XOR 4 = event 2, a missile with
; target code 0 (the player).
TryLaunchAiPayload:
    LD A,(IX+$20)                              ; $F780: DD 7E 20
    AND $07                                    ; $F783: E6 07  payload count
    JR Z,L_F7DF                                ; $F785: 28 58  none left
    CALL NextRandomByte                        ; $F787: CD 24 ED
    CP $80                                     ; $F78A: FE 80
    JR NC,L_F7DF                               ; $F78C: 30 51  random >= $80: not this time
    LD A,(EcmTimer)                            ; $F78E: 3A 16 DA  any ECM running?
    AND A                                      ; $F791: A7
    JR NZ,L_F7DF                               ; $F792: 20 4B  no launch during ECM
    LD A,(IY+$0A)                              ; $F794: FD 7E 0A  blueprint +$0A high nibble: launch subtype
    AND $F0                                    ; $F797: E6 F0
    JR NZ,L_F79D                               ; $F799: 20 02
    OR $06                                     ; $F79B: F6 06  zero: 6, giving event 2 below
L_F79D:
    XOR $04                                    ; $F79D: EE 04  event n*16+4 (subtype n) or 2 (missile)
    LD B,A                                     ; $F79F: 47  B = event
    PUSH BC                                    ; $F7A0: C5
    CALL DispatchShipEventPreservingParent     ; $F7A1: CD 76 F8  dispatch with IX/IY kept
    POP BC                                     ; $F7A4: C1
    JR NZ,L_F7DF                               ; $F7A5: 20 38  nothing created: payload kept
    DEC (IX+$20)                               ; $F7A7: DD 35 20  one payload item used
    LD A,B                                     ; $F7AA: 78
    CP $02                                     ; $F7AB: FE 02  event 2: a missile
    JR NZ,L_F7DF                               ; $F7AD: 20 30
    LD HL,IncomingMissileMessage               ; $F7AF: 21 81 A8  raise INCOMING MISSILE
    SET 7,(HL)                                 ; $F7B2: CB FE
    JR L_F7DF                                  ; $F7B4: 18 29

; VERIFIED: Low-energy branch: nothing unless NextRandomByte >= instance +$25 (a fleeing ship, bit 7
; set, rarely passes).  With +$20 bit 7 (from blueprint +$12 bit 7) launch an escape capsule
; (event 7, C = 0) and clear +$20 bits 7 and 6: the abandoned ship is no longer counted and
; gets no further AI steps (L_DB71 needs bit 6); return without steering.  Otherwise, if the
; blueprint canister byte +$00 is nonzero, dump a cargo canister (event 6, C = 0).
L_F7B6:
    CALL NextRandomByte                        ; $F7B6: CD 24 ED
    CP (IX+$25)                                ; $F7B9: DD BE 25  instance +$25 as the threshold
    JR C,L_F815                                ; $F7BC: 38 57  random below it: keep going
    BIT 7,(IX+$20)                             ; $F7BE: DD CB 20 7E  +$20 bit 7: escape capsule available
    JR Z,L_F7D4                                ; $F7C2: 28 10  no capsule: maybe dump cargo
    LD A,$07                                   ; $F7C4: 3E 07  event 7, C=0: escape capsule from this ship
    CALL DispatchShipEventPreservingParent     ; $F7C6: CD 76 F8
    JR NZ,L_F7DF                               ; $F7C9: 20 14  no free slot
    RES 7,(IX+$20)                             ; $F7CB: DD CB 20 BE  capsule used
    RES 6,(IX+$20)                             ; $F7CF: DD CB 20 B6  abandoned: not counted, no more AI steps
    RET                                        ; $F7D3: C9  no steering
L_F7D4:
    LD A,(IY+$00)                              ; $F7D4: FD 7E 00  blueprint canister byte
    AND A                                      ; $F7D7: A7
    JR Z,L_F7DF                                ; $F7D8: 28 05  nothing to dump
    LD A,$06                                   ; $F7DA: 3E 06  event 6, C=0: canister from this ship
    CALL DispatchShipEventPreservingParent     ; $F7DC: CD 76 F8

; VERIFIED: Only for blueprint behaviour byte +$12 = 4 (the Thargon, ID 18): look for an active
; instance in slots 1..6 with +$21 = $0C (Thargoid; also the $8C pirate blueprints).
; Found: steer at once (no ECM step, no station traffic).  None found: clear +$20 bit 6 (not
; counted, and L_DB71 skips its AI from now on), set +$26 bit 1 (no laser fire) and halve
; the speed +$1B once: the Thargon drifts.  Every other ship continues at L_F815.
L_F7DF:
    LD A,(IY+$12)                              ; $F7DF: FD 7E 12  blueprint behaviour byte
    CP $04                                     ; $F7E2: FE 04  behaviour byte 4: Thargon
    JR NZ,L_F815                               ; $F7E4: 20 2F  other ships: ECM decision
    PUSH IX                                    ; $F7E6: DD E5  keep the Thargon
    LD IX,InitialRuntimeState                  ; $F7E8: DD 21 48 60  slot base; the loop adds a slot first
    LD DE,InstanceSize                         ; $F7EC: 11 27 00
    LD B,$06                                   ; $F7EF: 06 06  slots 1..6
L_F7F1:
    ADD IX,DE                                  ; $F7F1: DD 19
    LD A,(IX+$22)                              ; $F7F3: DD 7E 22  free slot?
    AND A                                      ; $F7F6: A7
    JR Z,L_F800                                ; $F7F7: 28 07
    LD A,(IX+$21)                              ; $F7F9: DD 7E 21  instance behaviour +$21
    SUB $0C                                    ; $F7FC: D6 0C  behaviour $0C (Thargoid)
    JR Z,L_F803                                ; $F7FE: 28 03  found one
L_F800:
    DJNZ L_F7F1                                ; $F800: 10 EF
    INC A                                      ; $F802: 3C  none: A = 1, NZ
L_F803:
    POP IX                                     ; $F803: DD E1
    JP Z,UpdateShipHostilityAndSteering        ; $F805: CA A2 F8  Thargoid present: steer (no ECM step)
    RES 6,(IX+$20)                             ; $F808: DD CB 20 B6  not counted: no further AI steps
    SET 1,(IX+$26)                             ; $F80C: DD CB 26 CE  no laser fire (+$26 bits 0..3)
    SRL (IX+$1B)                               ; $F810: DD CB 1B 3E  halve the speed
    RET                                        ; $F814: C9

; VERIFIED: ECM decision for ships with instance +$25 bit 0: when the player missile slot is active
; (PlayerMissileEnergy, slot 7, <> 0) and ECM is idle, set EcmTimer = $0A - except with
; InvasionMissionState = 4 and the ECM jammer (CommanderFlags bit 7).  The CP $A0 after NextRandomByte
; at $F83F has no effect: no branch tests it before TryLaunchStationTraffic overwrites the
; flags, so every such ship switches ECM on.  Then station traffic.
L_F815:
    BIT 0,(IX+$25)                             ; $F815: DD CB 25 46  instance +$25 bit 0: ECM fitted
    JR Z,TryLaunchStationTraffic               ; $F819: 28 2B  no ECM
    LD A,(InvasionMissionState)                ; $F81B: 3A 71 A8  special state 4?
    CP $04                                     ; $F81E: FE 04
    JR NZ,L_F829                               ; $F820: 20 07
    LD A,(CommanderFlags)                      ; $F822: 3A 72 A8  CommanderFlags bit 7: ECM jammer
    BIT 7,A                                    ; $F825: CB 7F
    JR NZ,TryLaunchStationTraffic              ; $F827: 20 1D  jammer in mode 4: no AI ECM
L_F829:
    LD A,(EcmTimer)                            ; $F829: 3A 16 DA
    AND A                                      ; $F82C: A7
    JR NZ,TryLaunchStationTraffic              ; $F82D: 20 17  ECM already running
    LD HL,PlayerMissileEnergy                  ; $F82F: 21 7B 61  slot 7 energy: player missile in flight?
    LD A,(HL)                                  ; $F832: 7E
    AND A                                      ; $F833: A7
    JR Z,TryLaunchStationTraffic               ; $F834: 28 10  no missile: no ECM
    BIT 2,(IX+$26)                             ; $F836: DD CB 26 56  station: skip the RNG call
    JR NZ,L_F841                               ; $F83A: 20 05
    CALL NextRandomByte                        ; $F83C: CD 24 ED  RNG advanced, result ignored
    CP $A0                                     ; $F83F: FE A0  result unused: no conditional branch follows
L_F841:
    LD A,$0A                                   ; $F841: 3E 0A  switch ECM on
    LD (EcmTimer),A                            ; $F843: 32 16 DA  EcmTimer = 10

; VERIFIED: Station traffic gate: require instance+$26 bit 2 and EncounterShipCount below four.
; The count comparison leaves carry set for the first NextRandomByte call.
; A calm station branches to TryLaunchStationTrader. A hostile station admits results
; below $24 and normally requests a Viper; mode value 4 uses an extra Thargoid gate.
TryLaunchStationTraffic:
    BIT 2,(IX+$26)                             ; $F846: DD CB 26 56  station traffic flag
    JR Z,UpdateShipHostilityAndSteering        ; $F84A: 28 56  not a station: steering
    LD A,(EncounterShipCount)                  ; $F84C: 3A 1B DA  counted ships
    CP $04                                     ; $F84F: FE 04
    RET NC                                     ; $F851: D0  four or more: no launch
    CALL NextRandomByte                        ; $F852: CD 24 ED  called with carry set
    BIT 2,(IX+$21)                             ; $F855: DD CB 21 56  station hostile?
    JR Z,TryLaunchStationTrader                ; $F859: 28 16  calm: trader gate
    CP $24                                     ; $F85B: FE 24  hostile: 36 of 256
    RET NC                                     ; $F85D: D0
    LD A,(InvasionMissionState)                ; $F85E: 3A 71 A8  special state
    CP $04                                     ; $F861: FE 04
    LD A,$14                                   ; $F863: 3E 14  event $14: parent launch subtype 1 (Viper)
    JR NZ,DispatchShipEventPreservingParent    ; $F865: 20 0F  not state 4: a Viper
    CALL NextRandomByte                        ; $F867: CD 24 ED  state 4
    CP $88                                     ; $F86A: FE 88  random below $88
    RET NC                                     ; $F86C: D0
    LD A,$44                                   ; $F86D: 3E 44  event $44: subtype 4 (Thargoid)
    JR DispatchShipEventPreservingParent       ; $F86F: 18 05

; VERIFIED: Continue with the station gate RNG result in A: only values 0 and 1 permit a trader.
; Event $24 means parent-launch event 4, subtype 2; it is not a ship ID.
TryLaunchStationTrader:
    CP $02                                     ; $F871: FE 02  only results 0 and 1
    RET NC                                     ; $F873: D0
    LD A,$24                                   ; $F874: 3E 24  event $24: subtype 2 (trader)

; VERIFIED: Dispatch the event in A while saving/restoring parent IX and IY.
; POP does not change flags, so the event success/failure result reaches the caller.
DispatchShipEventPreservingParent:
    PUSH IY                                    ; $F876: FD E5
    PUSH IX                                    ; $F878: DD E5
    CALL DispatchShipEvent                     ; $F87A: CD CA F2  event A; C = its high nibble
    POP IX                                     ; $F87D: DD E1
    POP IY                                     ; $F87F: FD E1
    RET                                        ; $F881: C9

; VERIFIED: Return carry if |x| < DE, |y| < DE and |z| < DE + $0200 for instance IX (16-bit
; magnitudes at +0/+1, +3/+4, +6/+7; the sign/high bytes +2/+5/+8 are ignored).  NC as
; soon as one axis is outside.  Clobbers HL, D (+2), flags.
CheckShipProximity:
    LD H,(IX+$01)                              ; $F882: DD 66 01  |x| (16-bit magnitude)
    LD L,(IX+$00)                              ; $F885: DD 6E 00
    AND A                                      ; $F888: A7
    SBC HL,DE                                  ; $F889: ED 52
    RET NC                                     ; $F88B: D0  |x| >= DE: outside
    LD H,(IX+$04)                              ; $F88C: DD 66 04  |y|
    LD L,(IX+$03)                              ; $F88F: DD 6E 03
    AND A                                      ; $F892: A7
    SBC HL,DE                                  ; $F893: ED 52
    RET NC                                     ; $F895: D0  |y| >= DE: outside
    LD H,(IX+$07)                              ; $F896: DD 66 07  |z|
    LD L,(IX+$06)                              ; $F899: DD 6E 06
    INC D                                      ; $F89C: 14  z limit DE + $0200
    INC D                                      ; $F89D: 14
    AND A                                      ; $F89E: A7
    SBC HL,DE                                  ; $F89F: ED 52  carry: inside the box
    RET                                        ; $F8A1: C9

; VERIFIED: For instance +$21 bit 1, set hostility bit 2 when PlayerLegalScore >= 40 ($28).
; Only Viper and Fer-de-Lance blueprints initially carry bit 1.
; Scores 1..39 already display Offender but do not trigger this legal-hostility check.
; The check never clears existing hostility. Continue into distance/steering decisions.
; Evidence: all 19 blueprints x 256 legal scores in tools/check_bounty_hunters.py.
UpdateShipHostilityAndSteering:
    BIT 1,(IX+$21)                             ; $F8A2: DD CB 21 4E  legal-sensitive ship?
    JR Z,L_F8B3                                ; $F8A6: 28 0B
    LD A,(PlayerLegalScore)                    ; $F8A8: 3A 21 A8  player legal score
    CP $28                                     ; $F8AB: FE 28  40 or more
    JR C,L_F8B3                                ; $F8AD: 38 04
    SET 2,(IX+$21)                             ; $F8AF: DD CB 21 D6  become hostile

; VERIFIED: Steering choice: inside the $0200 box (or the $0A00 box while +$26 bit 5 avoidance is
; set) -> SteerShipAwayFromPlayer, for calm ships too.  Otherwise calm ships (+$21 bit 2
; clear) return with their old roll/pitch commands.
L_F8B3:
    LD DE,$0200                                ; $F8B3: 11 00 02  box half-size $0200
    CALL CheckShipProximity                    ; $F8B6: CD 82 F8  x/y within $0200, z within $0400?
    JR C,SteerShipAwayFromPlayer               ; $F8B9: 38 34  too close: turn away
    BIT 5,(IX+$26)                             ; $F8BB: DD CB 26 6E  avoidance flag from an earlier step
    JR Z,L_F8C8                                ; $F8BF: 28 07
    LD D,$0A                                   ; $F8C1: 16 0A  $0A00 while avoiding
    CALL CheckShipProximity                    ; $F8C3: CD 82 F8  x/y within $0A00, z within $0C00?
    JR C,SteerShipAwayFromPlayer               ; $F8C6: 38 27  still close: keep turning away

; VERIFIED: Hostile ship: with InvasionMissionState <> 4 and a station in slot 0 (energy L_606A <> 0), +$21 bit 3
; selects away (set) or towards (clear).  Otherwise L_F8E2.
L_F8C8:
    BIT 2,(IX+$21)                             ; $F8C8: DD CB 21 56
    RET Z                                      ; $F8CC: C8  calm: old roll/pitch kept
    LD A,(InvasionMissionState)                ; $F8CD: 3A 71 A8  special state 4?
    CP $04                                     ; $F8D0: FE 04
    JR Z,L_F8E2                                ; $F8D2: 28 0E  state 4: courage test
    LD A,(InitialRuntimeState+InstanceEnergy)  ; $F8D4: 3A 6A 60  slot 0 (station) energy, instance +$22
    AND A                                      ; $F8D7: A7
    JR Z,L_F8E2                                ; $F8D8: 28 08  no station: courage test
    BIT 3,(IX+$21)                             ; $F8DA: DD CB 21 5E  behaviour bit 3
    JR Z,SteerShipTowardsPlayer                ; $F8DE: 28 2B  clear: attack
    JR SteerShipAwayFromPlayer                 ; $F8E0: 18 0D  set: keep away

; VERIFIED: (+$25 AND $7F) >= 8 -> SteerShipTowardsPlayer; else set +$25 bit 7 (fleeing, also makes
; ApplySteeringVector request acceleration 2) and steer away.  The low bits start at $7E and
; player laser hits lower them (ApplyPlayerLaserHit).
L_F8E2:
    LD A,(IX+$25)                              ; $F8E2: DD 7E 25
    AND $7F                                    ; $F8E5: E6 7F  courage: lowered by player laser hits
    CP $08                                     ; $F8E7: FE 08  below 8: flee
    JR NC,SteerShipTowardsPlayer               ; $F8E9: 30 20  8 or more: attack
    SET 7,(IX+$25)                             ; $F8EB: DD CB 25 FE  fleeing from now on

; VERIFIED: Build a scaled vector (position/4) from the ship position relative to the player, keeping its signs.
; Set instance +$26 bit 5 and continue to the shared steering calculation at ApplySteeringVector.
; This distance/avoidance path can be selected for a hostile ship as well.
; Evidence: coordinate readers at $F9DB..$F9F9; docs/BOUNTY-HUNTERS.md.
SteerShipAwayFromPlayer:
    PUSH IX                                    ; $F8EF: DD E5
    CALL L_F9E2                                ; $F8F1: CD E2 F9  x/4, sign kept
    LD (SteeringVectorX),HL                    ; $F8F4: 22 2B F7
    CALL L_F9E2                                ; $F8F7: CD E2 F9  y/4
    LD (SteeringVectorY),HL                    ; $F8FA: 22 2D F7
    CALL L_F9E2                                ; $F8FD: CD E2 F9  z/4
    LD (SteeringVectorZ),HL                    ; $F900: 22 2F F7
    POP IX                                     ; $F903: DD E1
    SET 5,(IX+$26)                             ; $F905: DD CB 26 EE  avoidance flag
    JR L_F925                                  ; $F909: 18 1A

; VERIFIED: Build a scaled vector (position/4) towards the player by reversing the position signs.
; Clear instance +$26 bit 5 and continue to shared steering at ApplySteeringVector.
; Also used by a player-targeting missile; this entry is not specific to bounty hunters.
; Evidence: coordinate readers at $F9DB..$F9F9 and Fer-de-Lance AI traces in tools/check_bounty_hunters.py.
SteerShipTowardsPlayer:
    PUSH IX                                    ; $F90B: DD E5
    CALL L_F9DB                                ; $F90D: CD DB F9  -x/4
    LD (SteeringVectorX),HL                    ; $F910: 22 2B F7
    CALL L_F9DB                                ; $F913: CD DB F9  -y/4
    LD (SteeringVectorY),HL                    ; $F916: 22 2D F7
    CALL L_F9DB                                ; $F919: CD DB F9  -z/4
    LD (SteeringVectorZ),HL                    ; $F91C: 22 2F F7
    POP IX                                     ; $F91F: DD E1
    RES 5,(IX+$26)                             ; $F921: DD CB 26 AE  avoidance ends
L_F925:
    JP ApplySteeringVector                     ; $F925: C3 FA F9

; VERIFIED: Missile AI (L_DB71 runs it every update for counted instances with +$26 bit 0).
; IX = missile.  EcmTimer nonzero: clear +$20 bit 6, set +$20 bit 4 (explosion state 01,
; after which the object update removes it) and return.
; Target code +$25 = 0: SteerShipTowardsPlayer.  Otherwise IY = slot 8 - code and
; SteeringVectorX/Y/Z = (target - missile)/4 (L_F9B2).
; Every component below $20 in magnitude (L_F9AA) = hit: +$20 bit 4 on the missile and,
; unless the target is a station (+$26 bit 2), on the target.  A station explodes only when
; InvasionMissionState = 4: InvasionMissionState bit 3 is set, the byte below it ($A870, station stock of ALIEN ITEMS)
; is cleared, AddCombatScore adds $FFFF and the station gets +$26 bit 7 (read at the next
; arrival, L_D7C4) and +$20 bit 4.  No hit: steering.
; Evidence: tools/check_routines.py ai/p11-missile-guidance.
UpdateMissileGuidance:
    LD A,(EcmTimer)                            ; $F928: 3A 16 DA  any ECM active?
    AND A                                      ; $F92B: A7
    JR Z,L_F937                                ; $F92C: 28 09  no: guide the missile
    RES 6,(IX+$20)                             ; $F92E: DD CB 20 B6  not counted
    SET 4,(IX+$20)                             ; $F932: DD CB 20 E6  explode (state 01)
    RET                                        ; $F936: C9
L_F937:
    LD A,(IX+$25)                              ; $F937: DD 7E 25  target code
    AND A                                      ; $F93A: A7
    JR Z,SteerShipTowardsPlayer                ; $F93B: 28 CE  0: the player
    PUSH IY                                    ; $F93D: FD E5  keep the blueprint pointer
    LD IY,InitialRuntimeState-InstanceSize     ; $F93F: FD 21 21 60  slot -1: the loop adds one slot per count
    LD DE,InstanceSize                         ; $F943: 11 27 00
    SUB $0A                                    ; $F946: D6 0A  code - 10
    CPL                                        ; $F948: 2F  A = 9 - code
    LD B,A                                     ; $F949: 47  B = loop count
L_F94A:
    ADD IY,DE                                  ; $F94A: FD 19
    DJNZ L_F94A                                ; $F94C: 10 FC  IY = slot 8 - code
    PUSH IX                                    ; $F94E: DD E5
    PUSH IY                                    ; $F950: FD E5
    CALL L_F9B2                                ; $F952: CD B2 F9  x: (target - missile)/4
    LD (SteeringVectorX),HL                    ; $F955: 22 2B F7
    CALL L_F9B2                                ; $F958: CD B2 F9  y: (target - missile)/4
    LD (SteeringVectorY),HL                    ; $F95B: 22 2D F7
    CALL L_F9B2                                ; $F95E: CD B2 F9  z: (target - missile)/4
    LD (SteeringVectorZ),HL                    ; $F961: 22 2F F7
    POP IY                                     ; $F964: FD E1  IY = target, IX = missile
    POP IX                                     ; $F966: DD E1
    CALL L_F9AA                                ; $F968: CD AA F9  z close?
    JR NZ,L_F9A5                               ; $F96B: 20 38  no: steer
    LD HL,(SteeringVectorY)                    ; $F96D: 2A 2D F7
    CALL L_F9AA                                ; $F970: CD AA F9  y close?
    JR NZ,L_F9A5                               ; $F973: 20 30
    LD HL,(SteeringVectorX)                    ; $F975: 2A 2B F7
    CALL L_F9AA                                ; $F978: CD AA F9  x close?
    JR NZ,L_F9A5                               ; $F97B: 20 28
    BIT 2,(IY+$26)                             ; $F97D: FD CB 26 56  hit: target a station?
    JR Z,L_F99A                                ; $F981: 28 17  no: destroy the target
    LD HL,InvasionMissionState                 ; $F983: 21 71 A8  station: only in state 4
    LD A,(HL)                                  ; $F986: 7E
    CP $04                                     ; $F987: FE 04
    JR NZ,L_F99E                               ; $F989: 20 13  otherwise only the missile explodes
    SET 3,(HL)                                 ; $F98B: CB DE  InvasionMissionState 4 -> $0C
    DEC L                                      ; $F98D: 2D  HL = $A870: station stock of ALIEN ITEMS
    XOR A                                      ; $F98E: AF
    LD (HL),A                                  ; $F98F: 77  cleared
    LD DE,$FFFF                                ; $F990: 11 FF FF  combat score + $FFFF
    CALL AddCombatScore                        ; $F993: CD EE A8
    SET 7,(IY+$26)                             ; $F996: FD CB 26 FE  station destroyed marker (read at arrival)
L_F99A:
    SET 4,(IY+$20)                             ; $F99A: FD CB 20 E6  target explodes (state 01)
L_F99E:
    POP IY                                     ; $F99E: FD E1  restore the blueprint pointer
    SET 4,(IX+$20)                             ; $F9A0: DD CB 20 E6  missile explodes (state 01)
    RET                                        ; $F9A4: C9
L_F9A5:
    POP IY                                     ; $F9A5: FD E1
    JP L_F925                                  ; $F9A7: C3 25 F9  steer towards the target

; VERIFIED: Hit test of one sign-magnitude component HL: Z if its magnitude is below $20 (ADD HL,HL
; drops the sign, then H and bits 7..6 of L must be clear), NZ otherwise.  Clobbers A, HL.
L_F9AA:
    ADD HL,HL                                  ; $F9AA: 29  drop the sign
    LD A,H                                     ; $F9AB: 7C
    AND A                                      ; $F9AC: A7
    RET NZ                                     ; $F9AD: C0  magnitude >= $80
    LD A,L                                     ; $F9AE: 7D
    AND $C0                                    ; $F9AF: E6 C0  magnitude bits 6..5 (doubled)
    RET                                        ; $F9B1: C9

; VERIFIED: HL = (target - object)/4 for one axis: the low 16 magnitude bits of each 24-bit sign-
; magnitude coordinate (target IY, object IX) are halved with the sign moved into bit 15,
; then HalveDifferenceSignMagnitude halves their difference.  Coordinate bits 16..22 are
; ignored.  IX and IY += 3.  Clobbers A, BC, DE.
L_F9B2:
    LD L,(IY+$00)                              ; $F9B2: FD 6E 00  target low 16 bits
    LD H,(IY+$01)                              ; $F9B5: FD 66 01
    LD C,(IY+$02)                              ; $F9B8: FD 4E 02  target sign byte
    LD E,(IX+$00)                              ; $F9BB: DD 5E 00  object low 16 bits
    LD D,(IX+$01)                              ; $F9BE: DD 56 01
    LD B,(IX+$02)                              ; $F9C1: DD 46 02  object sign byte
    SLA C                                      ; $F9C4: CB 21  sign to carry
    RR H                                       ; $F9C6: CB 1C  target/2, sign in bit 15
    RR L                                       ; $F9C8: CB 1D
    SLA B                                      ; $F9CA: CB 20
    RR D                                       ; $F9CC: CB 1A  object/2, sign in bit 15
    RR E                                       ; $F9CE: CB 1B
    CALL HalveDifferenceSignMagnitude          ; $F9D0: CD F0 E8  HL = (target/2 - object/2)/2
    LD DE,$0003                                ; $F9D3: 11 03 00  next coordinate
    ADD IX,DE                                  ; $F9D6: DD 19
    ADD IY,DE                                  ; $F9D8: FD 19
    RET                                        ; $F9DA: C9

; VERIFIED: As L_F9E2 with the sign inverted: HL = -coordinate/4, the vector towards the origin (the
; player).  IX += 3.
L_F9DB:
    LD A,(IX+$02)                              ; $F9DB: DD 7E 02
    XOR $80                                    ; $F9DE: EE 80  invert the sign
    JR L_F9E5                                  ; $F9E0: 18 03

; VERIFIED: HL = coordinate/4 as a sign-magnitude word: the low 16 magnitude bits (IX+0, IX+1)
; shifted right twice, the sign (bit 7 of IX+2) moved into bit 15; magnitude bits 16..22
; are ignored.  IX += 3.  Clobbers A, DE.
L_F9E2:
    LD A,(IX+$02)                              ; $F9E2: DD 7E 02
L_F9E5:
    LD L,(IX+$00)                              ; $F9E5: DD 6E 00  low 16 magnitude bits
    LD H,(IX+$01)                              ; $F9E8: DD 66 01
    SRL H                                      ; $F9EB: CB 3C  halve
    RR L                                       ; $F9ED: CB 1D
    RLA                                        ; $F9EF: 17  sign into carry
    RR H                                       ; $F9F0: CB 1C  halve again, sign into bit 15
    RR L                                       ; $F9F2: CB 1D
    LD DE,$0003                                ; $F9F4: 11 03 00  next coordinate
    ADD IX,DE                                  ; $F9F7: DD 19
    RET                                        ; $F9F9: C9

; VERIFIED: Shared steering.  IX = ship, IY = blueprint (both kept).  NormaliseVector rescales
; SteeringVectorX/Y/Z to length $8000; its length result goes to SteeringVectorLength.
; ComputeNegatedDotProduct with the forward (InstanceAxisZ), up (InstanceAxisY) and side
; (InstanceAxisX) axes gives H, L and D (about -127 * cosine; H bit 7 set = vector ahead).
; Roll +$1D: m = |D|; m = 0 keeps the old byte; else rate min(15, (m + m/8 + bit 2 of m)/4),
; direction bit 6 = sign(D) XOR sign(L), bit 7 clear.
; Pitch +$1E, skipped when that roll rate is 4 or more: bit 6 = sign(L), rate 15 when the
; vector is behind, else (103 - (|H|+80)/2)/8 (7 at a right angle, 0 straight ahead).
; Acceleration +$1C: 2 and return while fleeing (+$25 bit 7).  Otherwise, R = range (high
; byte of SteeringVectorLength): ahead: 0 below R = $0A ($02 for missiles, +$26 bit 0), else
; 1 (R >= $10) or 2, and every ahead case continues into TryFireAiLaser; behind (L_FAF9):
; 0 below $0B ($03), else -1 (R < $12) or -2.
; Evidence: tools/check_routines.py ai/p11-apply-steering-vector.
ApplySteeringVector:
    PUSH IY                                    ; $F9FA: FD E5  keep the blueprint pointer
    LD IY,SteeringVectorX                      ; $F9FC: FD 21 2B F7  IY = vector for the dot products
    PUSH IX                                    ; $FA00: DD E5
    LD IX,SteeringVectorX                      ; $FA02: DD 21 2B F7
    CALL NormaliseVector                       ; $FA06: CD D5 DB  scale to length $8000; DE = length
    POP IX                                     ; $FA09: DD E1
    LD (SteeringVectorLength),DE               ; $FA0B: ED 53 31 F7  SteeringVectorLength
    PUSH IX                                    ; $FA0F: DD E5
    LD DE,InstanceAxisZ                        ; $FA11: 11 09 00  forward axis offset
    ADD IX,DE                                  ; $FA14: DD 19  IX = forward axis
    CALL ComputeNegatedDotProduct              ; $FA16: CD 1F FB  H = -(forward . v)
    LD DE,InstanceAxisY-InstanceAxisZ          ; $FA19: 11 06 00  up axis is the next axis
    ADD IX,DE                                  ; $FA1C: DD 19  IX = up axis
    LD H,A                                     ; $FA1E: 67
    PUSH HL                                    ; $FA1F: E5
    CALL ComputeNegatedDotProduct              ; $FA20: CD 1F FB  L = -(up . v)
    POP HL                                     ; $FA23: E1
    LD L,A                                     ; $FA24: 6F
    PUSH HL                                    ; $FA25: E5
    LD DE,InstanceAxisX-InstanceAxisY          ; $FA26: 11 06 00  side axis is the next axis
    ADD IX,DE                                  ; $FA29: DD 19  IX = side axis
    CALL ComputeNegatedDotProduct              ; $FA2B: CD 1F FB  D = -(side . v)
    POP HL                                     ; $FA2E: E1
    POP IX                                     ; $FA2F: DD E1
    POP IY                                     ; $FA31: FD E1
    LD D,A                                     ; $FA33: 57
    AND $7F                                    ; $FA34: E6 7F  m = |D|
    JR Z,L_FA5A                                ; $FA36: 28 22  zero: keep the old roll byte
    LD C,A                                     ; $FA38: 4F
    SRL C                                      ; $FA39: CB 39  C = m/8, carry = bit 2 of m
    SRL C                                      ; $FA3B: CB 39
    SRL C                                      ; $FA3D: CB 39
    ADC A,C                                    ; $FA3F: 89  m + m/8 + carry
    SRL A                                      ; $FA40: CB 3F  /4
    SRL A                                      ; $FA42: CB 3F
    CP $0F                                     ; $FA44: FE 0F  cap at 15
    JR C,L_FA4A                                ; $FA46: 38 02
    LD A,$0F                                   ; $FA48: 3E 0F
L_FA4A:
    LD B,A                                     ; $FA4A: 47
    LD A,D                                     ; $FA4B: 7A  direction: sign(D) XOR sign(L)
    XOR L                                      ; $FA4C: AD
    AND $80                                    ; $FA4D: E6 80
    RRA                                        ; $FA4F: 1F  into bit 6
    OR B                                       ; $FA50: B0
    LD (IX+$1D),A                              ; $FA51: DD 77 1D  roll command
    AND $3F                                    ; $FA54: E6 3F  roll rate
    CP $04                                     ; $FA56: FE 04  4 or more: keep the old pitch
    JR NC,L_FA78                               ; $FA58: 30 1E
L_FA5A:
    LD A,H                                     ; $FA5A: 7C  forward term
    BIT 7,A                                    ; $FA5B: CB 7F
    JR Z,L_FA6E                                ; $FA5D: 28 0F  behind: largest rate
    AND $7F                                    ; $FA5F: E6 7F  |H|
    ADD A,$50                                  ; $FA61: C6 50  +80
    SRL A                                      ; $FA63: CB 3F  /2
    CPL                                        ; $FA65: 2F
    ADD A,$68                                  ; $FA66: C6 68  103 - (|H|+80)/2
    SRL A                                      ; $FA68: CB 3F  0..31
    CP $40                                     ; $FA6A: FE 40  never 64 or more
    JR C,L_FA70                                ; $FA6C: 38 02
L_FA6E:
    LD A,$3F                                   ; $FA6E: 3E 3F  behind: 63
L_FA70:
    SLA L                                      ; $FA70: CB 25  sign of L to carry
    RRA                                        ; $FA72: 1F  sign to bit 7
    SRL A                                      ; $FA73: CB 3F  sign to bit 6, rate/4
    LD (IX+$1E),A                              ; $FA75: DD 77 1E  pitch command
L_FA78:
    XOR A                                      ; $FA78: AF
    BIT 7,(IX+$25)                             ; $FA79: DD CB 25 7E  fleeing?
    JR Z,L_FA81                                ; $FA7D: 28 02
    LD A,$02                                   ; $FA7F: 3E 02  fleeing: accelerate
L_FA81:
    LD (IX+$1C),A                              ; $FA81: DD 77 1C  acceleration
    RET NZ                                     ; $FA84: C0  fleeing: no laser
    LD DE,(SteeringVectorLength)               ; $FA85: ED 5B 31 F7  SteeringVectorLength
    LD A,D                                     ; $FA89: 7A  A = range (high byte)
    SLA H                                      ; $FA8A: CB 24  H bit 7 to carry: ahead?
    JR NC,L_FAF9                               ; $FA8C: 30 6B  behind
    LD B,$0A                                   ; $FA8E: 06 0A  ships: $0A
    BIT 0,(IX+$26)                             ; $FA90: DD CB 26 46  missile: closer approach
    JR Z,L_FA98                                ; $FA94: 28 02
    LD B,$02                                   ; $FA96: 06 02  missiles: $02
L_FA98:
    CP B                                       ; $FA98: B8
    JR C,TryFireAiLaser                        ; $FA99: 38 0A  close: acceleration 0
    LD B,$01                                   ; $FA9B: 06 01  1 at range $10 or more
    CP $10                                     ; $FA9D: FE 10
    JR NC,L_FAA2                               ; $FA9F: 30 01
    INC B                                      ; $FAA1: 04  2 below $10
L_FAA2:
    LD (IX+$1C),B                              ; $FAA2: DD 70 1C  then the laser test as well

; VERIFIED: Firing block within the steering routine; require instance +$21 hostility bit 2.
; Facing, RNG, instance flags, range and alignment gates still apply after that check.
; The hit paths add seven to the corresponding player damage accumulator.
; Inputs include the preceding steering results in D/H and the blueprint in IY.
; Evidence: controlled calm/hostile firing cases in tools/check_bounty_hunters.py.
TryFireAiLaser:
    BIT 2,(IX+$21)                             ; $FAA5: DD CB 21 56  hostile?
    RET Z                                      ; $FAA9: C8
    LD A,(IX+$08)                              ; $FAAA: DD 7E 08  z sign of the ship
    XOR (IX+$0E)                               ; $FAAD: DD AE 0E  z sign of its forward axis
    AND $80                                    ; $FAB0: E6 80
    RET Z                                      ; $FAB2: C8  equal: nose away from the player side
    LD B,(IY+$02)                              ; $FAB3: FD 46 02  blueprint +$02: firing chance
    LD A,(CombatScoreHigh)                     ; $FAB6: 3A 24 A8  combat score high byte
    AND A                                      ; $FAB9: A7
    JR NZ,L_FABE                               ; $FABA: 20 02
    SRL B                                      ; $FABC: CB 38  still zero: half the chance
L_FABE:
    CALL NextRandomByte                        ; $FABE: CD 24 ED
    CP B                                       ; $FAC1: B8
    RET NC                                     ; $FAC2: D0  random >= chance: no shot
    LD A,(IX+$26)                              ; $FAC3: DD 7E 26  +$26 bits 0..3
    AND $0F                                    ; $FAC6: E6 0F
    RET NZ                                     ; $FAC8: C0  missiles, debris, orphaned Thargons: no laser
    LD A,D                                     ; $FAC9: 7A  range
    CP $0C                                     ; $FACA: FE 0C
    RET NC                                     ; $FACC: D0  range $0C or more: no shot
    SLA H                                      ; $FACD: CB 24  H bit 6: |H| >= 64
    RET NC                                     ; $FACF: D0  not aligned: no shot
    SET 3,(IX+$20)                             ; $FAD0: DD CB 20 DE  laser beam drawn (+$20 bit 3)
    LD A,D                                     ; $FAD4: 7A
    CP $04                                     ; $FAD5: FE 04  range below 4: a hit
    JR C,L_FADC                                ; $FAD7: 38 03
    SLA H                                      ; $FAD9: CB 24  H bit 5: |H| >= 96 needed
    RET NC                                     ; $FADB: D0  miss
L_FADC:
    LD HL,SoundEffectRequests                  ; $FADC: 21 7D 70  a hit
    SET 6,(HL)                                 ; $FADF: CB F6  sound request bit 6
    BIT 7,(IX+$08)                             ; $FAE1: DD CB 08 7E  ship behind the player (z < 0)?
    JR Z,L_FAF0                                ; $FAE5: 28 09
    LD A,(RearDamageThisUpdate)                ; $FAE7: 3A 19 DA  rear shield damage
    ADD A,$07                                  ; $FAEA: C6 07  +7
    LD (RearDamageThisUpdate),A                ; $FAEC: 32 19 DA
    RET                                        ; $FAEF: C9
L_FAF0:
    LD A,(FrontDamageThisUpdate)               ; $FAF0: 3A 18 DA  front shield damage
    ADD A,$07                                  ; $FAF3: C6 07  +7
    LD (FrontDamageThisUpdate),A               ; $FAF5: 32 18 DA
    RET                                        ; $FAF8: C9

; VERIFIED: Vector behind the ship (H bit 7 clear): range < $0B ($03 for missiles) keeps +$1C = 0;
; otherwise +$1C = $FF (range < $12) or $FE.
L_FAF9:
    LD B,$0B                                   ; $FAF9: 06 0B  ships: $0B
    BIT 0,(IX+$26)                             ; $FAFB: DD CB 26 46
    JR Z,L_FB03                                ; $FAFF: 28 02
    LD B,$03                                   ; $FB01: 06 03  missiles: $03
L_FB03:
    CP B                                       ; $FB03: B8
    RET C                                      ; $FB04: D8  close: acceleration stays 0
    LD B,$FF                                   ; $FB05: 06 FF  -1
    CP $12                                     ; $FB07: FE 12
    JR C,L_FB0C                                ; $FB09: 38 01
    DEC B                                      ; $FB0B: 05  -2 at range $12 or more
L_FB0C:
    LD (IX+$1C),B                              ; $FB0C: DD 70 1C
    RET                                        ; $FB0F: C9

; VERIFIED: One product term for ComputeNegatedDotProduct: A, B sign-magnitude bytes.  H bit 7 =
; NOT(sign A XOR sign B) (other H bits undefined), L = A = high byte of (2|A|)*(2|B|) from
; MultiplyUnsignedHigh, about |A|*|B|/64.
L_FB10:
    LD C,A                                     ; $FB10: 4F
    XOR B                                      ; $FB11: A8  sign A XOR sign B
    XOR $80                                    ; $FB12: EE 80  negated product sign
    SLA B                                      ; $FB14: CB 20  2|B|
    SLA C                                      ; $FB16: CB 21  2|A|
    PUSH AF                                    ; $FB18: F5  save the sign
    CALL MultiplyUnsignedHigh                  ; $FB19: CD 34 E4  A = high byte of 2|A| * 2|B|
    POP HL                                     ; $FB1C: E1  H bit 7 = sign
    LD L,A                                     ; $FB1D: 6F  L = magnitude
    RET                                        ; $FB1E: C9

; VERIFIED: A = -(IX+1*IY+1 + IX+3*IY+3 + IX+5*IY+5)/128 as a sign-magnitude byte (inputs are the
; sign-magnitude high bytes of three words; the magnitude saturates at $7F).
; Evidence: tools/check_routines.py maths/rotation-helpers: $60.$60 -> $C8; -$60.$60 -> $48;
; three $40.$40 terms -> $E0.
; Callers: ApplySteeringVector and OrthogonaliseYVector.
ComputeNegatedDotProduct:
    LD B,(IX+$01)                              ; $FB1F: DD 46 01  high bytes of the first words
    LD A,(IY+$01)                              ; $FB22: FD 7E 01
    CALL L_FB10                                ; $FB25: CD 10 FB  term 1
    PUSH HL                                    ; $FB28: E5
    LD B,(IX+$03)                              ; $FB29: DD 46 03
    LD A,(IY+$03)                              ; $FB2C: FD 7E 03
    CALL L_FB10                                ; $FB2F: CD 10 FB  term 2
    PUSH HL                                    ; $FB32: E5
    LD B,(IX+$05)                              ; $FB33: DD 46 05
    LD A,(IY+$05)                              ; $FB36: FD 7E 05
    CALL L_FB10                                ; $FB39: CD 10 FB  term 3
    POP DE                                     ; $FB3C: D1  DE = term 2
    CALL AddSignMagnitude                      ; $FB3D: CD 24 E4  term 3 + term 2
    JR NC,L_FB44                               ; $FB40: 30 02
    LD A,$FF                                   ; $FB42: 3E FF  saturate
L_FB44:
    POP DE                                     ; $FB44: D1  DE = term 1
    LD L,A                                     ; $FB45: 6F
    CALL AddSignMagnitude                      ; $FB46: CD 24 E4  + term 1
    JR NC,L_FB4D                               ; $FB49: 30 02
    LD A,$FF                                   ; $FB4B: 3E FF  saturate
L_FB4D:
    RL H                                       ; $FB4D: CB 14  sign to carry
    RRA                                        ; $FB4F: 1F  A = sign | sum/2
    RET                                        ; $FB50: C9

; ============================================================================
; Keyboard and joystick input
; Called from the IM 2 handler every frame. Keys are latched as bits in eight
; state bytes (KeyFlagsScreens..JoystickNumberKeys) through KeyActionTable.
; ============================================================================

; VERIFIED: 40 character codes, indexed by key bit*8 + row, rows ordered $7FFE, $BFFE, $DFFE,
; $EFFE, $F7FE, $FBFE, $FDFE, $FEFE.  $00 = CAPS SHIFT, $01 = SYMBOL SHIFT, $0D = ENTER.
; RecordKeyPress stores the code of the pressed key in LastKeyCode.
; Evidence: tools/check_routines.py input/scan-keyboard pressing each key alone.
KeyCharacterTable:
    defm " "
    defb $0D
    defm "P01QA"
    defb $00                                                                              ; $FB51  bit 0: SPACE ENTER P 0 1 Q A CAPS
    defb $01
    defm "LO92WSZ"                                                                        ; $FB59  bit 1: SYM L O 9 2 W S Z
    defm "MKI83EDX"                                                                       ; $FB61  bit 2: M K I 8 3 E D X
    defm "NJU74RFC"                                                                       ; $FB69  bit 3: N J U 7 4 R F C
    defm "BHY65TGV"                                                                       ; $FB71  bit 4: B H Y 6 5 T G V

; VERIFIED: Interrupt-time input scan (called by InterruptHandler).  Clear JoystickNumberKeys, set
; LastKeyCode = $FF, read the eight keyboard half-rows (BC = $7FFE rotated before each IN,
; first port $FEFE) and call RecordKeyPress for each pressed key.  Then (L_FC16) merge the
; selected joystick into the direction bits of KeyFlagsFlight.
; Key bits are latched (ORed); consumers clear them (ClearInputFlags, ClearKeyFlags,
; L_7158, L_FF1D).
; Evidence: tools/check_routines.py input/scan-keyboard (all 40 keys, four input devices,
; CAPS+0 and ghost-key suppression).
ScanKeyboard:
    XOR A                                      ; $FB79: AF
    LD (JoystickNumberKeys),A                  ; $FB7A: 32 15 FC  JoystickNumberKeys = 0
    DEC A                                      ; $FB7D: 3D
    LD (LastKeyCode),A                         ; $FB7E: 32 13 FC  LastKeyCode = $FF (no key)
    LD BC,$7FFE                                ; $FB81: 01 FE 7F  port $7FFE; RLC B gives $FEFE first
    LD D,$08                                   ; $FB84: 16 08  eight half-rows
L_FB86:
    RLC B                                      ; $FB86: CB 00  next half-row port
    IN A,(C)                                   ; $FB88: ED 78  read the row (0 = pressed)
    AND $1F                                    ; $FB8A: E6 1F
    XOR $1F                                    ; $FB8C: EE 1F  pressed keys as 1 bits
    LD E,$05                                   ; $FB8E: 1E 05  five keys
L_FB90:
    RRA                                        ; $FB90: 1F  next key bit to carry
    CALL C,RecordKeyPress                      ; $FB91: DC C0 FC  pressed: record it
    DEC E                                      ; $FB94: 1D
    JR NZ,L_FB90                               ; $FB95: 20 F9

; VERIFIED: Jump over the input tables and state bytes at $FB9A..$FC15 to the scan continuation.
L_FB97:
    JP L_FC16                                  ; $FB97: C3 16 FC  skip the tables and state bytes

; VERIFIED: Laser type 1..4 -> equipment item 5 (EXTRA PULSE LASERS), 6 (EXTRA BEAM LASERS),
; 13 (MILITARY LASER), 14 (MINING LASER).  Read by the laser purchase code at $B6DE as
; LaserTypeItemTable-1 + old laser type to refund the replaced laser; $B65A performs the
; inverse map.  Item names: token $68 + item number.
LaserTypeItemTable:
    defb $05,$06,$0D,$0E                                                                  ; $FB9A ....  pulse, beam, military, mining

; VERIFIED: Attribute layout list for ColourAttributeStrips, commander status screen
; (ShowCommanderStatus, screen $0B).
; Each byte: bits 7..3 = number of cells set to colour $05 from the current row start
; (the first row starts at $5821), bits 2..0 = rows to advance; 0 ends the list.
StatusScreenAttributeLayout:
    defb $CB,$71,$89,$21,$21,$61,$32,$48                                                  ; $FB9E .q.!!a2H

; VERIFIED: Attribute layout list for ColourAttributeStrips, inventory screen (ShowInventory,
; token "INVENTORY").
; Format as StatusScreenAttributeLayout.
InventoryAttributeLayout:
    defb $7A,$21,$20                                                                      ; $FBA6 z! 

; VERIFIED: Two-letter pairs for message codes $D7..$FF (PrintMessagePairToken reads
; base + 2*(code-$D7)).  The 41 pairs run to $FBFA and overlap TokenPairTable from $FBC3.
; Pair 0 '@@' (code $D7) is not used by any of the 256 messages.
MessagePairTable:
    defm "@@"                                                                             ; $FBA9  code $D7 (unused)

; VERIFIED: Pair 1 of MessagePairTable and the first of the 32 pairs (64 bytes, running on into
; TokenPairTable) from which PrintRandomName prints 1..4 pairs at the even offsets
; NextDescriptionRandom AND $3E; a '?' second letter is not printed.  L_B91F addresses it
; as MessagePairTable+2.  Evidence: PrintRandomName, verified by simulation (r6_b000).
RandomNamePairTable:
    defm "ABOUSEIT"                                                                       ; $FBAB
    defm "ILETSTON"                                                                       ; $FBB3
    defm "LONUTHNO"                                                                       ; $FBBB

; VERIFIED: 32 two-letter pairs for token codes $80..$9F (PrintPairToken); a second letter '?' is
; not printed.  Also read by AppendNameLetterPair (pair index 1..31) and as message pairs $E4..$FF.
TokenPairTable:
    defm "ALLEXEGEZACEBISO"                                                               ; $FBC3
    defm "USESARMAINDIREA?"                                                               ; $FBD3
    defm "ERATENBERALAVETI"                                                               ; $FBE3
    defm "EDORQUANTEISRION"                                                               ; $FBF3

; VERIFIED: Attribute layout list for ColourAttributeStrips used by the data-on-system screen
; (DisplaySystemData, token "DATA ON").  Format as StatusScreenAttributeLayout.
SystemDataAttributeLayout:
    defb $B2,$42,$3A,$52,$52,$54,$92,$70                                                  ; $FC03 .B:RRT.p

; VERIFIED: Attribute layout list for ColourAttributeStrips used by the market prices screen
; (ShowMarketPrices, token "MARKET PRICES").  Format as StatusScreenAttributeLayout.
MarketPricesAttributeLayout:
    defb $DA,$F1,$F0                                                                      ; $FC0B ...

; VERIFIED: Latched key bits (state byte 0 of KeyActionTable): bit 0 ENTER, 1 L, 2 K, 3 P, 4 O, 5 I,
; 6 '0' (joystick fire, cleared again by the scan), 7 Y.
; Bits 5..0 (I, O, P, K, L, ENTER) select screens 7..12 in HandleScreenKeys, highest bit
; first: galactic chart, short-range chart, system data, market prices, commander status,
; inventory.  Bit 7 (Y) is the ToggleCloak key.
; ClearInputFlags clears KeyFlagsScreens..KeyFlagsCombat; ClearKeyFlags and ClearLatchedKeys clear five bytes.
KeyFlagsScreens:
    defb $00                                                                              ; $FC0E .

; VERIFIED: Latched key bits (state byte 1): bit 0 N / left, 1 M / right, 2 X / down, 3 S / up,
; 4 SPACE, 5 SYMBOL SHIFT.  Bits 0..3 are replaced by the selected joystick each scan and
; swapped by ControlOptions bits 4/5.  UpdateFlightControls consumes and clears the byte
; on screens 0..3; when docked, bit 5 opens the access menu (L_72A2).
KeyFlagsFlight:
    defb $00                                                                              ; $FC0F .

; VERIFIED: Latched key bits (state byte 2): bit 0 '1', 1 '2', 2 '3', 3 '4', 4 H, 5 G, 6 J,
; 7 CAPS SHIFT.  Keys 1..4 (HandleScreenKeys): cockpit views in flight; launch, buy, sell
; and equipment screens when docked.  H and G: CheckHyperspaceKeys (hyperspace, galactic
; with H); J: HandleTorusJumpKey; CAPS SHIFT starts the pause menu at HandleFreezeMode.
KeyFlagsViews:
    defb $00                                                                              ; $FC10 .

; VERIFIED: Latched key bits (state byte 3): bit 0 A or joystick fire, 1 T, 2 F, 3 U, 4 E, 5 W, 6 Q,
; 7 C.  Consumers: A laser (L_EBD8), T/F/U arm, fire and disarm a missile (L_A72E), E ECM
; (L_ED90), W energy bomb (UseEnergyBomb), Q escape pod (L_A788), C docking computer
; (CheckDockingComputerKey).  With the keyboard selected, bits 2 and 7 (and KeyFlagsViews bit 7) are cleared
; while any KeyFlagsFlight bit is set (L_FC8F).  INFERRED: suppression of matrix ghost keys.
KeyFlagsCombat:
    defb $00                                                                              ; $FC11 .

; VERIFIED: Latched key bits (state byte 4): bit 4 B, 5 D, 6 R; other bits unused.
; HandleChartCursorKeys reads bits 4..6 with the KeyFlagsFlight direction bits on screens 7..8.
KeyFlagsChart:
    defb $00                                                                              ; $FC12 .

; VERIFIED: Character code (KeyCharacterTable) of the last key found by the current scan; $FF = no
; key, $FE = CAPS SHIFT + '0'.  Waited on by WaitForKeyPress and the pause menu at L_8F78.
LastKeyCode:
    defb $FF                                                                              ; $FC13 .

; VERIFIED: Control options, initial $8C.  Bits 0..1 input device: 0 keyboard, 1 Kempston, 2 Cursor
; (5..8, 0), 3 Sinclair (6..9, 0); chosen by holding left on the title screen (L_71E5).
; Pause-menu keys toggle: bit 2 R (recentring), 3 D (damping), 4 B (reverse both),
; 5 Y (reverse vertical), 6 F, 7 sound (Q clears, S sets; tested before the ROM BEEPER).
; Bit 6 forces the alternative hyperspace arrival at $D68B (INFERRED: mis-jump).
ControlOptions:
    defb $8C                                                                              ; $FC14 .

; VERIFIED: Current (not latched) number keys from state byte 7:
; bit 0 '9', 1 '5', 2 '8', 3 '6', 4 '7'.  Cleared at each scan; converted to direction
; bits for the Cursor and Sinclair joysticks.
JoystickNumberKeys:
    defb $00                                                                              ; $FC15 .

; VERIFIED: Scan continuation after the eight rows.  D = KeyFlagsFlight AND $0F (keyboard).
; Kempston: IN port $1F; bit 4 fire -> KeyFlagsCombat bit 0; bits 0..3 -> D with both
; swap flags inverted.  Cursor: D = JoystickNumberKeys >> 1 (5 left, 8 right, 6 down, 7 up).
; Sinclair: bits reordered from 6 left, 7 right, 8 down, 9 up.  Cursor/Sinclair: '0'
; (KeyFlagsScreens bit 6) is fire.
L_FC16:
    DEC D                                      ; $FC16: 15  next half-row
    JP NZ,L_FB86                               ; $FC17: C2 86 FB
    LD A,(KeyFlagsFlight)                      ; $FC1A: 3A 0F FC  keyboard direction bits
    AND $0F                                    ; $FC1D: E6 0F
    LD D,A                                     ; $FC1F: 57  D = directions
    LD A,(ControlOptions)                      ; $FC20: 3A 14 FC
    LD E,A                                     ; $FC23: 5F  E = options
    AND $03                                    ; $FC24: E6 03  input device
    JR Z,L_FC69                                ; $FC26: 28 41  keyboard
    DEC A                                      ; $FC28: 3D
    JR NZ,L_FC43                               ; $FC29: 20 18  Cursor or Sinclair
    LD BC,$FF1F                                ; $FC2B: 01 1F FF  Kempston port $1F
    IN A,(C)                                   ; $FC2E: ED 78  1 bits = active
    BIT 4,A                                    ; $FC30: CB 67  Kempston fire
    JR Z,L_FC39                                ; $FC32: 28 05
    LD HL,KeyFlagsCombat                       ; $FC34: 21 11 FC  fire -> KeyFlagsCombat bit 0 (laser)
    SET 0,(HL)                                 ; $FC37: CB C6
L_FC39:
    AND $0F                                    ; $FC39: E6 0F  right, left, down, up bits
    LD D,A                                     ; $FC3B: 57
    LD A,E                                     ; $FC3C: 7B
    XOR $30                                    ; $FC3D: EE 30  invert both swap flags for Kempston bit order
    LD E,A                                     ; $FC3F: 5F
    JP L_FC69                                  ; $FC40: C3 69 FC
L_FC43:
    DEC A                                      ; $FC43: 3D
    LD A,(JoystickNumberKeys)                  ; $FC44: 3A 15 FC  number keys '9' '5' '8' '6' '7' (bits 0..4)
    RRA                                        ; $FC47: 1F  bits 0..3 = '5' '8' '6' '7'
    LD D,A                                     ; $FC48: 57
    JR Z,L_FC5D                                ; $FC49: 28 12  device 2: Cursor (5 6 7 8)
    LD D,$00                                   ; $FC4B: 16 00  device 3: Sinclair (6 7 8 9)
    RL D                                       ; $FC4D: CB 12  rebuild D: '6' left, '7' right, '8' down, '9' up
    RRA                                        ; $FC4F: 1F
    RRA                                        ; $FC50: 1F
    RL D                                       ; $FC51: CB 12
    SLA D                                      ; $FC53: CB 22
    RRA                                        ; $FC55: 1F
    RR D                                       ; $FC56: CB 1A
    RRA                                        ; $FC58: 1F
    RL D                                       ; $FC59: CB 12
    RL D                                       ; $FC5B: CB 12
L_FC5D:
    LD HL,KeyFlagsScreens                      ; $FC5D: 21 0E FC
    BIT 6,(HL)                                 ; $FC60: CB 76  '0' = fire
    JR Z,L_FC69                                ; $FC62: 28 05
    LD HL,KeyFlagsCombat                       ; $FC64: 21 11 FC  fire -> KeyFlagsCombat bit 0 (laser)
    SET 0,(HL)                                 ; $FC67: CB C6

; VERIFIED: Option swaps on D: ControlOptions bit 4 swaps bits 0<->1 and 2<->3, bit 5 swaps 2<->3.
L_FC69:
    BIT 4,E                                    ; $FC69: CB 63  reverse both?
    JR Z,L_FC7A                                ; $FC6B: 28 0D
    LD A,D                                     ; $FC6D: 7A
    AND $05                                    ; $FC6E: E6 05  left and down bits ...
    SLA A                                      ; $FC70: CB 27
    LD C,A                                     ; $FC72: 4F
    LD A,D                                     ; $FC73: 7A
    AND $0A                                    ; $FC74: E6 0A  ... exchanged with right and up
    SRL A                                      ; $FC76: CB 3F
    OR C                                       ; $FC78: B1
    LD D,A                                     ; $FC79: 57
L_FC7A:
    BIT 5,E                                    ; $FC7A: CB 6B  reverse vertical?
    JR Z,L_FC8F                                ; $FC7C: 28 11
    LD A,D                                     ; $FC7E: 7A
    AND $03                                    ; $FC7F: E6 03  keep left/right
    LD B,A                                     ; $FC81: 47
    LD A,D                                     ; $FC82: 7A
    AND $0C                                    ; $FC83: E6 0C  down/up ...
    LD C,A                                     ; $FC85: 4F
    SRL C                                      ; $FC86: CB 39
    SLA A                                      ; $FC88: CB 27
    OR C                                       ; $FC8A: B1
    AND $0C                                    ; $FC8B: E6 0C  ... exchanged
    OR B                                       ; $FC8D: B0
    LD D,A                                     ; $FC8E: 57

; VERIFIED: Keyboard only: while any KeyFlagsFlight bit is set, clear KeyFlagsViews bit 7 and
; KeyFlagsCombat bits 2 and 7.  Then store D in the low nibble of KeyFlagsFlight, clear
; KeyFlagsScreens bit 6 and report CAPS+0 as LastKeyCode $FE.
L_FC8F:
    LD HL,KeyFlagsFlight                       ; $FC8F: 21 0F FC
    LD A,(ControlOptions)                      ; $FC92: 3A 14 FC  input device
    AND $03                                    ; $FC95: E6 03
    JR NZ,L_FCA7                               ; $FC97: 20 0E  keyboard only
    LD A,(HL)                                  ; $FC99: 7E  any flight key latched?
    AND A                                      ; $FC9A: A7
    JR Z,L_FCA7                                ; $FC9B: 28 0A
    INC L                                      ; $FC9D: 2C  KeyFlagsViews
    RES 7,(HL)                                 ; $FC9E: CB BE  drop CAPS SHIFT (pause)
    INC L                                      ; $FCA0: 2C  KeyFlagsCombat
    RES 2,(HL)                                 ; $FCA1: CB 96  F (fire missile)
    RES 7,(HL)                                 ; $FCA3: CB BE  C (docking computer)
    DEC L                                      ; $FCA5: 2D  back to KeyFlagsFlight
    DEC L                                      ; $FCA6: 2D
L_FCA7:
    LD A,(HL)                                  ; $FCA7: 7E
    AND $F0                                    ; $FCA8: E6 F0  keep SPACE/SYMBOL SHIFT bits
    OR D                                       ; $FCAA: B2  new direction bits
    LD (HL),A                                  ; $FCAB: 77
    LD HL,KeyFlagsScreens                      ; $FCAC: 21 0E FC
    BIT 6,(HL)                                 ; $FCAF: CB 76  '0' pressed?
    RET Z                                      ; $FCB1: C8
    RES 6,(HL)                                 ; $FCB2: CB B6  consume '0'
    LD A,(KeyFlagsViews)                       ; $FCB4: 3A 10 FC  with CAPS SHIFT?
    AND $80                                    ; $FCB7: E6 80
    RET Z                                      ; $FCB9: C8
    LD A,$FE                                   ; $FCBA: 3E FE  CAPS SHIFT + 0
    LD (LastKeyCode),A                         ; $FCBC: 32 13 FC  LastKeyCode = $FE
    RET                                        ; $FCBF: C9

; VERIFIED: Called for one pressed key: E = 5..1 (bit counter), D = 8..1 (row counter).
; Index = (5-E)*8 + D-1; LastKeyCode = KeyCharacterTable[index]; then OR the mask from
; KeyActionTable[index] into state byte KeyFlagsScreens + offset.  BC and AF preserved.
RecordKeyPress:
    PUSH BC                                    ; $FCC0: C5
    PUSH AF                                    ; $FCC1: F5
    LD A,$05                                   ; $FCC2: 3E 05
    SUB E                                      ; $FCC4: 93  key bit 0..4
    ADD A,A                                    ; $FCC5: 87
    ADD A,A                                    ; $FCC6: 87
    ADD A,A                                    ; $FCC7: 87
    ADD A,D                                    ; $FCC8: 82
    DEC A                                      ; $FCC9: 3D  index = bit*8 + row
    LD B,A                                     ; $FCCA: 47
    SLA B                                      ; $FCCB: CB 20  B = 2*index
    LD HL,KeyCharacterTable                    ; $FCCD: 21 51 FB  character code
    ADD A,L                                    ; $FCD0: 85
    JR NC,L_FCD4                               ; $FCD1: 30 01
    INC H                                      ; $FCD3: 24
L_FCD4:
    LD L,A                                     ; $FCD4: 6F
    LD A,(HL)                                  ; $FCD5: 7E
    LD (LastKeyCode),A                         ; $FCD6: 32 13 FC  LastKeyCode = character
    LD HL,KeyActionTable                       ; $FCD9: 21 58 FF  action entry: offset, mask
    LD A,L                                     ; $FCDC: 7D
    ADD A,B                                    ; $FCDD: 80  entry 2*index (same page)
    LD L,A                                     ; $FCDE: 6F
    LD A,(HL)                                  ; $FCDF: 7E  A = state byte offset
    INC HL                                     ; $FCE0: 23
    LD B,(HL)                                  ; $FCE1: 46  B = mask
    LD HL,KeyFlagsScreens                      ; $FCE2: 21 0E FC
    ADD A,L                                    ; $FCE5: 85  state byte (same page)
    LD L,A                                     ; $FCE6: 6F
    LD A,(HL)                                  ; $FCE7: 7E
    OR B                                       ; $FCE8: B0  latch the key bit
    LD (HL),A                                  ; $FCE9: 77
    POP AF                                     ; $FCEA: F1
    POP BC                                     ; $FCEB: C1
    RET                                        ; $FCEC: C9

; Research note: proposed pirate patch storage before interrupt-vector region. Preserved, not used.
; INFERRED: 19 zero bytes before the vector table; no static or runtime reader or writer.
; The research note proposes them as patch storage; they are kept as zeros.
; stationslotfix=yes uses them for StationSlotFinish.
UnusedAfterReturnCandidate:
assert $-GameImage = StationSlotFinishStart-GameLoadAddress
IF STATION_SLOT_FIX
    StationSlotFinishCode
ELSE
    defs 19,0                                                                             ; $FCED..$FCFF
ENDIF
assert $-GameImage = StationSlotFinishLimit-GameLoadAddress

; VERIFIED: IM 2 vector table: 257 bytes of $FE at a page boundary, so that both bytes
; of the vector word read at I*256+bus value are $FE.
InterruptVectorTable:
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD00 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD10 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD20 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD30 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD40 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD50 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD60 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD70 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD80 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FD90 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDA0 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDB0 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDC0 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDD0 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDE0 ................
    defb $FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE,$FE                  ; $FDF0 ................
    defb $FE                                                                              ; $FE00 .

; ============================================================================
; Interrupt-driven flight controls and IM 2 handler
; Roll, pitch and speed accumulators are integrated from the latched direction
; and speed keys. InterruptEntry at the fixed address $FEFE splits this routine.
; ============================================================================

; VERIFIED: Called by InterruptHandler, on screens 0..3 only (CurrentScreenId < 4; otherwise the
; latched KeyFlagsFlight bits are left for the screen code).  B = KeyFlagsFlight,
; C = ControlOptions.
; RollControl: N (bit 0) from 0 -> $80FF, then +$FF per frame up to $8FF0; M (bit 1)
; likewise positive; both keys: unchanged.  Opposite key: 0 with recentring (C bit 2),
; else -$FF (floor 0).  No key: -$3C per frame with damping (C bit 3).
; PitchControl: X (bit 2) negative, S (bit 3) positive, step $66, damping $24.
; SpeedControl: SPACE +$A0 (max $1FE0), SYMBOL SHIFT -$A0 (floor 0).
; Finally clear KeyFlagsFlight.
; Evidence: tools/check_routines.py controls/update-flight-controls frame sequences.
UpdateFlightControls:
    LD A,(CurrentScreenId)                     ; $FE01: 3A 41 70
    CP $04                                     ; $FE04: FE 04  cockpit views only
    RET NC                                     ; $FE06: D0
    LD A,(KeyFlagsFlight)                      ; $FE07: 3A 0F FC
    LD B,A                                     ; $FE0A: 47  B = flight keys
    LD A,(ControlOptions)                      ; $FE0B: 3A 14 FC
    LD C,A                                     ; $FE0E: 4F  C = options
    LD HL,(RollControl)                        ; $FE0F: 2A 08 FF  roll accumulator
    BIT 0,B                                    ; $FE12: CB 40  N (left)?
    JR NZ,L_FE41                               ; $FE14: 20 2B
    BIT 1,B                                    ; $FE16: CB 48  M (right)?
    JR NZ,L_FE2E                               ; $FE18: 20 14
    BIT 3,C                                    ; $FE1A: CB 59  no key: damping option?
    JR Z,L_FE7A                                ; $FE1C: 28 5C  off: keep the roll
    LD DE,$003C                                ; $FE1E: 11 3C 00  roll damping step
    AND A                                      ; $FE21: A7
    SBC HL,DE                                  ; $FE22: ED 52
    BIT 6,H                                    ; $FE24: CB 74  magnitude below zero?
    JR Z,L_FE7A                                ; $FE26: 28 52
    LD HL,$0000                                ; $FE28: 21 00 00  stop at 0
    JP L_FE7A                                  ; $FE2B: C3 7A FE
L_FE2E:
    LD A,H                                     ; $FE2E: 7C  roll zero?
    AND $7F                                    ; $FE2F: E6 7F
    OR L                                       ; $FE31: B5
    JR NZ,L_FE3A                               ; $FE32: 20 06
    LD HL,$00FF                                ; $FE34: 21 FF 00  first M step
    JP L_FE7A                                  ; $FE37: C3 7A FE
L_FE3A:
    BIT 7,H                                    ; $FE3A: CB 7C  negative roll?
    JR Z,L_FE55                                ; $FE3C: 28 17  positive: grow
    JP L_FE63                                  ; $FE3E: C3 63 FE  negative: reduce (opposite key)
L_FE41:
    BIT 1,B                                    ; $FE41: CB 48  with M too?
    JR NZ,L_FE7A                               ; $FE43: 20 35  N and M: no change
    LD A,H                                     ; $FE45: 7C
    AND $7F                                    ; $FE46: E6 7F
    OR L                                       ; $FE48: B5
    JR NZ,L_FE51                               ; $FE49: 20 06
    LD HL,$80FF                                ; $FE4B: 21 FF 80  first N step: sign-magnitude -$FF
    JP L_FE7A                                  ; $FE4E: C3 7A FE
L_FE51:
    BIT 7,H                                    ; $FE51: CB 7C
    JR Z,L_FE63                                ; $FE53: 28 0E  positive roll: reduce (opposite key)
L_FE55:
    LD DE,$00FF                                ; $FE55: 11 FF 00  roll step
    ADD HL,DE                                  ; $FE58: 19
    BIT 4,H                                    ; $FE59: CB 64  magnitude would reach $1000: undo
    JR Z,L_FE7A                                ; $FE5B: 28 1D
    AND A                                      ; $FE5D: A7
    SBC HL,DE                                  ; $FE5E: ED 52
    JP L_FE7A                                  ; $FE60: C3 7A FE
L_FE63:
    BIT 2,C                                    ; $FE63: CB 51  recentring option?
    JR Z,L_FE6D                                ; $FE65: 28 06
    LD HL,$0000                                ; $FE67: 21 00 00  recentring: cancel at once
    JP L_FE7A                                  ; $FE6A: C3 7A FE
L_FE6D:
    LD DE,$00FF                                ; $FE6D: 11 FF 00  otherwise reduce by $FF
    AND A                                      ; $FE70: A7
    SBC HL,DE                                  ; $FE71: ED 52
    BIT 6,H                                    ; $FE73: CB 74  magnitude below zero?
    JR Z,L_FE7A                                ; $FE75: 28 03
    LD HL,$0000                                ; $FE77: 21 00 00  stop at 0

; VERIFIED: Store RollControl and update PitchControl from bits 2/3 (step $66, damping $24).
L_FE7A:
    LD (RollControl),HL                        ; $FE7A: 22 08 FF
    LD HL,(PitchControl)                       ; $FE7D: 2A 0A FF  pitch accumulator
    BIT 2,B                                    ; $FE80: CB 50  X (down)?
    JR NZ,L_FEAF                               ; $FE82: 20 2B
    BIT 3,B                                    ; $FE84: CB 58  S (up)?
    JR NZ,L_FE9C                               ; $FE86: 20 14
    BIT 3,C                                    ; $FE88: CB 59  no key: damping option?
    JR Z,L_FEE8                                ; $FE8A: 28 5C
    LD DE,$0024                                ; $FE8C: 11 24 00  pitch damping step
    AND A                                      ; $FE8F: A7
    SBC HL,DE                                  ; $FE90: ED 52
    BIT 6,H                                    ; $FE92: CB 74
    JR Z,L_FEE8                                ; $FE94: 28 52
    LD HL,$0000                                ; $FE96: 21 00 00  stop at 0
    JP L_FEE8                                  ; $FE99: C3 E8 FE
L_FE9C:
    LD A,H                                     ; $FE9C: 7C  pitch zero?
    AND $7F                                    ; $FE9D: E6 7F
    OR L                                       ; $FE9F: B5
    JR NZ,L_FEA8                               ; $FEA0: 20 06
    LD HL,$0066                                ; $FEA2: 21 66 00  first S step
    JP L_FEE8                                  ; $FEA5: C3 E8 FE
L_FEA8:
    BIT 7,H                                    ; $FEA8: CB 7C
    JR Z,L_FEC3                                ; $FEAA: 28 17
    JP L_FED1                                  ; $FEAC: C3 D1 FE
L_FEAF:
    BIT 3,B                                    ; $FEAF: CB 58  with S too?
    JR NZ,L_FEE8                               ; $FEB1: 20 35  X and S: no change
    LD A,H                                     ; $FEB3: 7C
    AND $7F                                    ; $FEB4: E6 7F
    OR L                                       ; $FEB6: B5
    JR NZ,L_FEBF                               ; $FEB7: 20 06
    LD HL,$8066                                ; $FEB9: 21 66 80  first X step: sign-magnitude -$66
    JP L_FEE8                                  ; $FEBC: C3 E8 FE
L_FEBF:
    BIT 7,H                                    ; $FEBF: CB 7C
    JR Z,L_FED1                                ; $FEC1: 28 0E
L_FEC3:
    LD DE,$0066                                ; $FEC3: 11 66 00  pitch step
    ADD HL,DE                                  ; $FEC6: 19
    BIT 4,H                                    ; $FEC7: CB 64  magnitude would reach $1000: undo
    JR Z,L_FEE8                                ; $FEC9: 28 1D
    AND A                                      ; $FECB: A7
    SBC HL,DE                                  ; $FECC: ED 52
    JP L_FEE8                                  ; $FECE: C3 E8 FE
L_FED1:
    BIT 2,C                                    ; $FED1: CB 51  recentring option?
    JR Z,L_FEDB                                ; $FED3: 28 06
    LD HL,$0000                                ; $FED5: 21 00 00  recentring: cancel at once
    JP L_FEE8                                  ; $FED8: C3 E8 FE
L_FEDB:
    LD DE,$0066                                ; $FEDB: 11 66 00  otherwise reduce by $66
    AND A                                      ; $FEDE: A7
    SBC HL,DE                                  ; $FEDF: ED 52
    BIT 6,H                                    ; $FEE1: CB 74
    JR Z,L_FEE8                                ; $FEE3: 28 03
    LD HL,$0000                                ; $FEE5: 21 00 00  stop at 0

; VERIFIED: Store PitchControl and update SpeedControl: SPACE (bit 4) +$A0 unless SYMBOL SHIFT too
; (undone when bit 13 would be set), SYMBOL SHIFT (bit 5) -$A0 with floor 0.
L_FEE8:
    LD (PitchControl),HL                       ; $FEE8: 22 0A FF
    LD HL,(SpeedControl)                       ; $FEEB: 2A 0C FF  speed accumulator
    LD DE,$00A0                                ; $FEEE: 11 A0 00  speed step
    BIT 4,B                                    ; $FEF1: CB 60  SPACE: faster
    JR NZ,L_FF00                               ; $FEF3: 20 0B
    BIT 5,B                                    ; $FEF5: CB 68  SYMBOL SHIFT: slower
    JR Z,L_FF1D                                ; $FEF7: 28 24
    AND A                                      ; $FEF9: A7
    SBC HL,DE                                  ; $FEFA: ED 52  reduce
    JR L_FF0E                                  ; $FEFC: 18 10

; VERIFIED: IM 2 entry point at the fixed address $FEFE selected by the vector table.
InterruptEntry:
    JR InterruptHandler                        ; $FEFE: 18 25

; VERIFIED: SPACE path of the speed update (UpdateFlightControls continues around InterruptEntry).
L_FF00:
    BIT 5,B                                    ; $FF00: CB 68
    JR NZ,L_FF1D                               ; $FF02: 20 19  both keys: no change
    ADD HL,DE                                  ; $FF04: 19  increase
    JP L_FF16                                  ; $FF05: C3 16 FF

; VERIFIED: Roll accumulator, 16-bit sign-magnitude (bit 15 sign), maintained by
; UpdateFlightControls from N/M (joystick left/right).  ReadFlightControls copies its
; high byte (RollControl+1) to PlayerRoll each frame (and 21 +/- that value to
; RollIndicator); ResetFlightInputs clears it.
; Roll meaning: the manual lists N/M as anticlockwise/clockwise roll.
RollControl:
    defb $00,$00                                                                          ; $FF08 ..

; VERIFIED: Pitch accumulator, 16-bit sign-magnitude, maintained from X/S (joystick down/up).
; ReadFlightControls copies its high byte to PlayerPitch.
PitchControl:
    defb $00,$00                                                                          ; $FF0A ..

; VERIFIED: Speed accumulator $0000..$1FE0 from SPACE / SYMBOL SHIFT.  ReadFlightControls
; copies the high byte to PlayerSpeed; ResetFlightInputs sets the high byte to $0C, and
; the escape-pod launch (L_A788) sets the word to $0010.
SpeedControl:
    defb $00,$00                                                                          ; $FF0C ..

; VERIFIED: SYMBOL SHIFT path: the SBC borrow means the speed went below zero -> 0.
L_FF0E:
    JR NC,L_FF1D                               ; $FF0E: 30 0D  no borrow: store
    LD HL,$0000                                ; $FF10: 21 00 00  below zero: 0
    JP L_FF1D                                  ; $FF13: C3 1D FF
L_FF16:
    BIT 5,H                                    ; $FF16: CB 6C  speed would reach $2000: undo
    JR Z,L_FF1D                                ; $FF18: 28 03
    AND A                                      ; $FF1A: A7
    SBC HL,DE                                  ; $FF1B: ED 52

; VERIFIED: Store SpeedControl and clear KeyFlagsFlight (the latched flight keys are consumed).
L_FF1D:
    LD (SpeedControl),HL                       ; $FF1D: 22 0C FF
    XOR A                                      ; $FF20: AF
    LD (KeyFlagsFlight),A                      ; $FF21: 32 0F FC  consume the flight keys
    RET                                        ; $FF24: C9

; VERIFIED: IM 2 service routine (InterruptEntry jumps here).  DI, save SP in InterruptSavedStack,
; switch to the private stack below InterruptStackTop ($FFBF, above the game image),
; push HL, DE, BC, AF, IX, IY, then ScanKeyboard, UpdateFlightControls and UpdateSoundEffect
; (sound effect step, gated by ControlOptions bit 7).  Restore, EI, RET.
; Alternate registers are not saved.  Runtime: stack use $FFAB..$FFBE only.
InterruptHandler:
    DI                                         ; $FF25: F3  no nested interrupts
    LD (InterruptSavedStack),SP                ; $FF26: ED 73 56 FF  save the interrupted SP
    LD SP,InterruptStackTop                    ; $FF2A: 31 BF FF  private interrupt stack above the image
    PUSH HL                                    ; $FF2D: E5
    PUSH DE                                    ; $FF2E: D5
    PUSH BC                                    ; $FF2F: C5
    PUSH AF                                    ; $FF30: F5
    PUSH IX                                    ; $FF31: DD E5
    PUSH IY                                    ; $FF33: FD E5
    CALL ScanKeyboard                          ; $FF35: CD 79 FB  keys and joystick
    CALL UpdateFlightControls                  ; $FF38: CD 01 FE  roll, pitch and speed
    CALL UpdateSoundEffect                     ; $FF3B: CD 82 90  sound effect step
    POP IY                                     ; $FF3E: FD E1
    POP IX                                     ; $FF40: DD E1
    POP AF                                     ; $FF42: F1
    POP BC                                     ; $FF43: C1
    POP DE                                     ; $FF44: D1
    POP HL                                     ; $FF45: E1
    LD SP,(InterruptSavedStack)                ; $FF46: ED 7B 56 FF  back to the interrupted stack
    EI                                         ; $FF4A: FB
    RET                                        ; $FF4B: C9

; VERIFIED: Select interrupt mode 2 with I = high byte of InterruptVectorTable.
; Every vector byte is $FE, so any value on the data bus selects $FEFE.
EnableInterruptMode2:
    LD A,InterruptVectorTable >> 8             ; $FF4C: 3E FD
    LD I,A                                     ; $FF4E: ED 47  I = vector table page
    IM 2                                       ; $FF50: ED 5E
    RET                                        ; $FF52: C9

; VERIFIED: Unused routine: IM 1, RET, the counterpart of EnableInterruptMode2 just before it.
; No caller: no word $FF53 in the image, no relative jump to it, and the seven 48K access
; traces neither execute nor read it.  The image contains no other IM 1, so the game
; never returns to the ROM interrupt mode.  Called, it selects interrupt mode 1 and
; returns with all registers and memory unchanged.  The comparison 48K memory images hold
; the same bytes $FF4C..$FF55 (EnableInterruptMode2 and this routine), again without a
; word $FF53; their start-up selects IM 2 with inline code instead of a CALL.
; Evidence: tools/check_routines.py dormant/unused-interrupt-routines; execution, read and
; write maps of tools/run_runtime_scenarios.py --accesses.
UnusedSelectInterruptMode1:
    IM 1                                       ; $FF53: ED 56
    RET                                        ; $FF55: C9

; VERIFIED: SP of the interrupted program, saved and restored by InterruptHandler.
InterruptSavedStack:
    defw $0000                                                                            ; $FF56

; VERIFIED: 40 two-byte entries in KeyCharacterTable order: state-byte offset from KeyFlagsScreens
; (0..7) and the bit mask ORed in by RecordKeyPress.  Z and V have mask 0.
; The table must not cross a page (L is incremented without carry).
; Evidence: tools/check_routines.py input/scan-keyboard (every key); the POKE notes swap the
; SYMBOL SHIFT and B entries.
KeyActionTable:
    defb $01,$10                                                                          ; $FF58 ..  SPACE        -> KeyFlagsFlight bit 4
    defb $00,$01                                                                          ; $FF5A ..  ENTER        -> KeyFlagsScreens bit 0
    defb $00,$08                                                                          ; $FF5C ..  P            -> KeyFlagsScreens bit 3
    defb $00,$40                                                                          ; $FF5E .@  '0'          -> KeyFlagsScreens bit 6 (fire)
    defb $02,$01                                                                          ; $FF60 ..  '1'          -> KeyFlagsViews bit 0
    defb $03,$40                                                                          ; $FF62 .@  Q            -> KeyFlagsCombat bit 6
    defb $03,$01                                                                          ; $FF64 ..  A            -> KeyFlagsCombat bit 0
    defb $02,$80                                                                          ; $FF66 ..  CAPS SHIFT   -> KeyFlagsViews bit 7

; POKE landmark: key-swap site (SYMBOL SHIFT state byte).
; VERIFIED: KeyActionTable entry 8, SYMBOL SHIFT: state offset $01 (KeyFlagsFlight).  The key-swap
; POKE writes $04 here (KeyFlagsChart).
KeySymbolShiftActionByte:
    defb $01                                                                              ; $FF68 .  SYMBOL SHIFT -> state offset 1 (KeyFlagsFlight)

; POKE landmark: key-swap site (SYMBOL SHIFT mask).
; VERIFIED: Mask of the SYMBOL SHIFT entry: $20 (bit 5).  The key-swap POKE writes $10 (B's bit 4).
; LastKeyCode still reports the original key characters.
KeySymbolShiftActionMask:
    defb $20                                                                              ; $FF69    mask: bit 5
    defb $00,$02                                                                          ; $FF6A ..  L            -> KeyFlagsScreens bit 1
    defb $00,$10                                                                          ; $FF6C ..  O            -> KeyFlagsScreens bit 4
    defb $07,$01                                                                          ; $FF6E ..  '9'          -> JoystickNumberKeys bit 0
    defb $02,$02                                                                          ; $FF70 ..  '2'          -> KeyFlagsViews bit 1
    defb $03,$20                                                                          ; $FF72 .   W            -> KeyFlagsCombat bit 5
    defb $01,$08                                                                          ; $FF74 ..  S            -> KeyFlagsFlight bit 3
    defb $00,$00                                                                          ; $FF76 ..  Z            -> no action bit
    defb $01,$02                                                                          ; $FF78 ..  M            -> KeyFlagsFlight bit 1
    defb $00,$04                                                                          ; $FF7A ..  K            -> KeyFlagsScreens bit 2
    defb $00,$20                                                                          ; $FF7C .   I            -> KeyFlagsScreens bit 5
    defb $07,$04                                                                          ; $FF7E ..  '8'          -> JoystickNumberKeys bit 2
    defb $02,$04                                                                          ; $FF80 ..  '3'          -> KeyFlagsViews bit 2
    defb $03,$10                                                                          ; $FF82 ..  E            -> KeyFlagsCombat bit 4
    defb $04,$20                                                                          ; $FF84 .   D            -> KeyFlagsChart bit 5
    defb $01,$04                                                                          ; $FF86 ..  X            -> KeyFlagsFlight bit 2
    defb $01,$01                                                                          ; $FF88 ..  N            -> KeyFlagsFlight bit 0
    defb $02,$40                                                                          ; $FF8A .@  J            -> KeyFlagsViews bit 6
    defb $03,$08                                                                          ; $FF8C ..  U            -> KeyFlagsCombat bit 3
    defb $07,$10                                                                          ; $FF8E ..  '7'          -> JoystickNumberKeys bit 4
    defb $02,$08                                                                          ; $FF90 ..  '4'          -> KeyFlagsViews bit 3
    defb $04,$40                                                                          ; $FF92 .@  R            -> KeyFlagsChart bit 6
    defb $03,$04                                                                          ; $FF94 ..  F            -> KeyFlagsCombat bit 2
    defb $03,$80                                                                          ; $FF96 ..  C            -> KeyFlagsCombat bit 7

; POKE landmark: key-swap site (B state byte).
; VERIFIED: KeyActionTable entry 32, B: state offset $04 (KeyFlagsChart).  The POKE writes $01.
KeyBActionByte:
    defb $04                                                                              ; $FF98 .  B            -> state offset 4 (KeyFlagsChart)

; POKE landmark: key-swap site (B mask).
; VERIFIED: Mask of the B entry: $10 (bit 4).  The key-swap POKE writes $20 (SYMBOL SHIFT's bit 5).
KeyBActionMask:
    defb $10                                                                              ; $FF99 .  mask: bit 4
    defb $02,$10                                                                          ; $FF9A ..  H            -> KeyFlagsViews bit 4
    defb $00,$80                                                                          ; $FF9C ..  Y            -> KeyFlagsScreens bit 7
    defb $07,$08                                                                          ; $FF9E ..  '6'          -> JoystickNumberKeys bit 3
    defb $07,$02                                                                          ; $FFA0 ..  '5'          -> JoystickNumberKeys bit 1
    defb $03,$02                                                                          ; $FFA2 ..  T            -> KeyFlagsCombat bit 1
    defb $02,$20                                                                          ; $FFA4 .   G            -> KeyFlagsViews bit 5
    defb $00,$00                                                                          ; $FFA6 ..  V            -> no action bit

; INFERRED: Last image byte, zero, after KeyActionTable; no reader or writer in code or traces.
L_FFA8:
    defs 1,0                                                                              ; $FFA8..$FFA8

