; Layout constraints required by the code (see tools/annotations).
assert L_C3D5+1-DormantPortLoader = $86         ; last patched CALL operand of the dormant loader
assert InterruptEntry-GameImage+GameLoadAddress = $FEFE ; IM 2 entry fixed by the $FE vector bytes
assert PlayerMissileEnergy-ObjectSlot7 = InstanceEnergy ; slot 7 energy byte
assert InitialRuntimeStateSize = InstanceSlotCount*InstanceSize ; the initial state region is exactly the slot array
assert ObjectSlot7-InitialRuntimeState = 7*InstanceSize ; eight contiguous slots
assert ObjectSlot1-InitialRuntimeState = InstanceSize ; slots are 39 bytes apart
assert ForwardShield-GaugeDisplayTable = 1      ; DrawGauges compares each value with the byte before it
assert FinishDockingTunnelLoop-(L_7A37+2) < 128 ; patched JR C displacement must stay in range
assert FinishHyperspaceTunnel-(L_7A37+2) < 128  ; patched JR C displacement must stay in range
assert FinishLaunchTunnelLoop-(L_7A37+2) < 128  ; patched JR C displacement must stay in range
assert CountTunnelFrame-(L_7A24+2) < 128        ; patched JR Z displacement must stay in range
assert LineClipRegionPairTable-LineClipRegionTable = 16 ; DrawLine indexes both region tables from LineClipRegionTable
assert ObjectSlot7OrientationBytes-ShipInstanceTemplate = $1F ; InitialiseShipFromBlueprint copies the template over +$00..+$1E
assert ((FontBitmap-GameImage+GameLoadAddress) & $0FFF) = 0 ; ViewBitmapBuffer = FontBitmap; SetLinePlotStart ORs y bits into its page
assert ((KeyActionTable-GameImage+GameLoadAddress) & $FF) + 80 <= 256 ; RecordKeyPress adds the entry offset to L without carry
assert ((KeyFlagsScreens-GameImage+GameLoadAddress) & $FF) + 8 <= 256 ; RecordKeyPress and L_FC8F address the state bytes by changing L only
assert InterruptStackTop - 20 >= GameImageEnd-GameImage+GameLoadAddress ; observed interrupt stack use ($FFAB..$FFBE) must stay above the game image
assert DrawFlaggedObjectDiscs-CirclePatchTargets = 2*32 ; CirclePatchCount ($20) pointers
assert ViewCirclePatchValues-ScreenCirclePatchValues = 32 ; one value per CirclePatchTargets entry
assert CirclePatchTargets-ViewCirclePatchValues = 32 ; one value per CirclePatchTargets entry
assert FontBitmap-GameImage+GameLoadAddress = $C000 ; ViewBitmapBuffer: SET 7,H maps screen $40xx..$4Fxx onto it
assert ScannerBackupBuffer+6*8*13 <= FontRuntime ; the 624-byte scanner backup must end before the runtime font copy
assert L_9A3A-DustPlotList = 16*3               ; DustPlotList holds 16 entries of 3 bytes
assert ((FontBitmap-GameImage+GameLoadAddress) & $0FFF) = 0 ; ViewBitmapBuffer (= FontBitmap): GetDustPixelAddress ORs row bits into its high byte
assert CargoHold-ActiveCommanderRecord = $17    ; commander record: cargo at +$17
assert CashHigh-ActiveCommanderRecord = $12     ; commander record: cash at +$12
assert CombatScoreFraction-ActiveCommanderRecord = $0C ; commander record: combat score at +$0C
assert ChartCursorX-ActiveCommanderRecord = $67 ; last tape byte is reused as the chart cursor X
assert CommanderFlags-ActiveCommanderRecord = $5C ; commander record: flags at +$5C
assert FuelLevel-ActiveCommanderRecord = $2E    ; commander record: fuel at +$2E
assert CurrentGalaxy-ActiveCommanderRecord = $11 ; commander record: galaxy at +$11
assert GalaxySeeds-ActiveCommanderRecord = $3C  ; commander record: galaxy seeds at +$3C
assert MarketStock-ActiveCommanderRecord = $4A  ; commander record: station stock at +$4A
assert CurrentSystemSeeds-ActiveCommanderRecord = $42 ; commander record: current system seeds at +$42
assert CurrentCommodity-MarketPrices = 17*2     ; ComputeMarket stores 17 price words
assert DrawShortRangeChart-ShortRangeChartRows = 24 ; DrawShortRangeChart clears 24 row flags
assert PitchRotationAngle-RollRotationAngle = 1 ; LD (RollRotationAngle),HL at $DD0B stores both angles
assert ((SquareLookupTables-GameImage+GameLoadAddress) & $FF) = 0 ; square tables are addressed by page (LD H,page; LD L,n)
assert ((InterruptVectorTable-GameImage+GameLoadAddress) & $FF) = 0 ; IM 2 vector table must start on a page boundary

